APP_NAME = "Rubenium"
VERSION = "1.0.0"            # file version of the .exe and setup
VERSION_NAME = "10.0"   # the version people see
BUILD = "2026.11.28.3"      # release tag (a date). It only ever goes up: this is what the updater compares


def build_number(build: str = "") -> int:
    """2026.11.17.1 -> 2026111701 (what the server compares to know if this version is too old)."""
    try:
        y, m, d, n = (int(x) for x in (build or BUILD).split("."))
        return y * 1000000 + m * 10000 + d * 100 + n
    except ValueError:
        return 0
log = logging.getLogger("rubenium")

# --------------------------------------------------------------------------- #
# Paths (one place for data)
# --------------------------------------------------------------------------- #
DOCS = win.documents_dir()
DATA_DIR = DOCS / "Rubenium"
CONFIG_PATH = DATA_DIR / "settings.json"          # one folder in Documents, kept across updates
OLD_CONFIG_PATH = DOCS / "RubeniumConfig.json"
BACKUP_DIR = DATA_DIR / "backups"
CROSSHAIR_DIR = DATA_DIR / "crosshairs"
LYRICS_DIR = DATA_DIR / "lyrics_cache"
LOG_PATH = DATA_DIR / "rubenium.log"
RECOVERY_PATH = DATA_DIR / "display_recovery.json"


def ensure_dirs() -> None:
    for d in (DATA_DIR, BACKUP_DIR, CROSSHAIR_DIR, LYRICS_DIR):
        try:
            d.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass


def setup_logging() -> None:
    ensure_dirs()
    level = logging.DEBUG if os.environ.get("RUBENIUM_DEBUG") else logging.INFO
    fmt = logging.Formatter("%(asctime)s %(levelname)s %(name)s: %(message)s")
    root = logging.getLogger()
    root.setLevel(level)
    try:
        fh = logging.handlers.RotatingFileHandler(LOG_PATH, maxBytes=512_000, backupCount=2, encoding="utf-8")
        fh.setFormatter(fmt)
        root.addHandler(fh)
    except OSError:
        pass
    if sys.stderr is not None:
        sh = logging.StreamHandler()
        sh.setFormatter(fmt)
        root.addHandler(sh)
    sys.excepthook = lambda t, v, tb: log.critical("Unhandled exception", exc_info=(t, v, tb))


# --------------------------------------------------------------------------- #
# Theme tokens
# --------------------------------------------------------------------------- #
ACCENT_DEFAULT = "#FFFFFF"      # white: the free base colour
BG_TOP = "#0B0F10"
BG_BOTTOM = "#101415"
SURFACE = "#1A1F20"
SURFACE_HI = "#282828"
TEXT = "#FFFFFF"
TEXT0 = TEXT                          # 6.3: the normal text colour (a coloured app font changes TEXT)
TEXT_DIM = "#B3B3B3"
TEXT_FAINT = "#7C8385"
PLACEHOLDER = "#575757"
TRACK = "#3A3A3A"
DANGER = "#E5484D"
WARN = "#F5A524"
FONT_DEFAULT = ["Segoe UI Variable", "Segoe UI", "Helvetica Neue", "Arial"]
FONT_FAMILIES = list(FONT_DEFAULT)


class Net:
    """Offline mode (3.0.0): while `blocked` is True, Rubenium makes no internet request at all."""
    blocked = False


class _UI:
    """Live theme state: every widget reads these at paint time."""
    scale = 1.0
    accent = QColor(ACCENT_DEFAULT)
    accent2 = None          # optional second colour (QColor), mixed into the outline and the header
    bg_top = QColor(BG_TOP)
    bg_bottom = QColor(BG_BOTTOM)
    ball = 1.0              # size of the ball, on top of the UI scale
    radius = 18             # card corner radius at 100 %
    motion = 1.0            # 8.0: interface movement time (0.3 with "Reduce motion")
    song = QColor("#FFFFFF")  # 9.1: the main buttons' colour: the playing song's cover, white when nothing plays


ui = _UI()


def S(v: float) -> int:
    """Scale a 100 % design dimension to the current UI scale."""
    return int(round(v * ui.scale))


def font(px: float, weight: QFont.Weight = QFont.Weight.Normal, spacing: float = 0.0) -> QFont:
    f = QFont()
    f.setFamilies(FONT_FAMILIES)
    f.setPixelSize(max(6, S(px)))
    f.setWeight(weight)
    if spacing:
        f.setLetterSpacing(QFont.SpacingType.AbsoluteSpacing, spacing * ui.scale)
    return f


def mix(a: QColor, b: QColor, t: float) -> QColor:
    t = max(0.0, min(1.0, t))
    return QColor(
        round(a.red() + (b.red() - a.red()) * t),
        round(a.green() + (b.green() - a.green()) * t),
        round(a.blue() + (b.blue() - a.blue()) * t),
        round(a.alpha() + (b.alpha() - a.alpha()) * t),
    )


def alpha(c: QColor | str, a: float) -> QColor:
    c = QColor(c)
    c.setAlphaF(max(0.0, min(1.0, a)))
    return c


class DS:
    """9.0 design system (Remastered): bigger, softer corners, glass surfaces lit from above, one brand palette
    (ruby to violet) for the chrome, gold for coins and help. Every shared control paints through these."""
    R_SM = 9            # inner pills, chips
    R_MD = 12           # buttons, inputs, segmented controls
    R_LG = 16           # cards, tiles, panels
    HAIR = 0.085        # hairline border (white, this opacity)
    TOP = 0.06          # extra light at the top edge of a raised surface
    SECTION = 10.5      # section titles (upper case, spaced)


BRAND = "#FF3D6E"       # 9.0: ruby
BRAND2 = "#8B5CFF"      # 9.0: violet
GOLD = "#F5C04A"        # coins, help, rewards
MINT = "#35E0A1"        # ready, won
KEY_BLUE = "#7FD4FF"    # keys


def brand_gradient(r: QRectF, a: float = 1.0) -> QLinearGradient:
    """9.0: the brand sweep, ruby to violet, along a rectangle."""
    g = QLinearGradient(r.topLeft(), r.bottomRight())
    g.setColorAt(0, alpha(BRAND, a))
    g.setColorAt(1, alpha(BRAND2, a))
    return g


def cta_colors() -> tuple:
    """9.1: the main buttons' two colours follow the song that plays (its cover's colour, white for a grey cover), and
    fade back to white when the music stops or pauses."""
    a = ui.song
    if a.hslSaturationF() < 0.12:
        lit = max(0.80, a.lightnessF())
        top = QColor.fromHslF(0.6, 0.06, min(1.0, lit + 0.06))
        return top, QColor.fromHslF(0.6, 0.08, lit - 0.08)
    return mix(a, QColor("#FFFFFF"), 0.10), mix(a, QColor("#000000"), 0.18)


def cta_fg() -> QColor:
    """Text and icons on the main buttons: dark on a light colour, white on a dark one."""
    c1, c2 = cta_colors()
    return QColor("#0B0D12") if mix(c1, c2, 0.5).lightnessF() > 0.62 else QColor("#FFFFFF")


def paint_surface(p: QPainter, r: QRectF, radius: float, base: float = 0.05, hover: float = 0.0,
                  edge: Optional[QColor] = None, tint: Optional[QColor] = None, tint_a: float = 0.0) -> None:
    """A raised glass surface: a soft top-to-bottom light, a hairline edge brighter at the top, a faint inner sheen.
    base/hover are white opacities; tint mixes a colour in (the accent, a state)."""
    g = QLinearGradient(r.topLeft(), r.bottomLeft())
    top = alpha("#FFFFFF", base + DS.TOP + 0.05 * hover)
    bottom = alpha("#FFFFFF", base * 0.45 + 0.03 * hover)
    if tint is not None and tint_a > 0:
        top = mix(top, alpha(tint, tint_a * 1.25), 0.6)
        bottom = mix(bottom, alpha(tint, tint_a * 0.8), 0.6)
    g.setColorAt(0, top)
    g.setColorAt(1, bottom)
    if edge is None:
        eg = QLinearGradient(r.topLeft(), r.bottomLeft())
        eg.setColorAt(0, alpha("#FFFFFF", DS.HAIR + 0.06 + 0.06 * hover))
        eg.setColorAt(1, alpha("#FFFFFF", DS.HAIR * 0.45 + 0.04 * hover))
        p.setPen(QPen(QBrush(eg), 1))
    else:
        p.setPen(QPen(edge, 1))
    p.setBrush(g)
    p.drawRoundedRect(r, radius, radius)
    if hover > 0.01 and r.height() > S(20):                # 9.0: a soft light follows the hover
        glow = QRadialGradient(QPointF(r.center().x(), r.top()), max(r.width(), r.height()) * 0.7)
        glow.setColorAt(0, alpha(ui.accent, 0.07 * hover))
        glow.setColorAt(1, alpha(ui.accent, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glow)
        p.drawRoundedRect(r, radius, radius)

def field_css(px: float = 13) -> str:
    """8.0: one look for every text field: recessed, a hairline edge, the accent edge while typing."""
    acc = ui.accent
    return (f"QLineEdit {{ background: rgba(0,0,0,0.30); border: 1px solid rgba(255,255,255,0.10);"
            f" border-radius: {S(DS.R_MD)}px; padding: 0 {S(10)}px; color: {TEXT}; font-size: {S(px)}px;"
            f" selection-background-color: rgba({acc.red()},{acc.green()},{acc.blue()},0.35); }}"
            f"QLineEdit:hover {{ border: 1px solid rgba(255,255,255,0.16); }}"
            f"QLineEdit:focus {{ border: 1px solid rgba({acc.red()},{acc.green()},{acc.blue()},0.75);"
            f" background: rgba(0,0,0,0.38); }}")


# Metrics at 100 % (the window multiplies through S()).
_PAGE_EXTRA = [0]           # set while the online menu builds its pages: they are made for its wider halves


def page_width() -> int:
    """The width a page (or a small screen inside the menu) is built for, in the menu building it right now."""
    return S(CARD_W - 2 * PAD + _PAGE_EXTRA[0])


class wide_pages:
    """with wide_pages(): pages made inside are made for the online menu's halves."""

    def __enter__(self):
        _PAGE_EXTRA[0] = ONLINE_EXTRA

    def __exit__(self, *_a):
        _PAGE_EXTRA[0] = 0

