from collections import deque

from PyQt6.QtCore import QObject, QPointF, QRectF, QTimer, Qt, pyqtSignal
from PyQt6.QtGui import QColor, QFont, QLinearGradient, QPainter, QPainterPath, QPen, QRadialGradient
from PyQt6.QtWidgets import QWidget


# ================================================================ the show / hide key
KEY_CHOICES = [("rshift", "Right Shift", 0xA1), ("rctrl", "Right Ctrl", 0xA3), ("insert", "Insert", 0x2D),
               ("home", "Home", 0x24), ("ralt", "Right Alt", 0xA5), ("off", "Off", 0)]
# 4.6: the game mode key (any of these, but never the show / hide key)
GM_KEY_CHOICES = [("rshift", "Right Shift", 0xA1), ("rctrl", "Right Ctrl", 0xA3), ("ralt", "Right Alt", 0xA5),
                  ("insert", "Insert", 0x2D), ("home", "Home", 0x24), ("end", "End", 0x23), ("pgup", "Page Up", 0x21),
                  ("pgdn", "Page Down", 0x22), ("pause", "Pause", 0x13), ("scroll", "Scroll Lock", 0x91),
                  ("f9", "F9", 0x78), ("f10", "F10", 0x79), ("f11", "F11", 0x7A), ("f12", "F12", 0x7B)]


class TapKey(QObject):
    """Tap one key (default Right Shift) to show or hide Rubenium. A tap is a short press with no other key: holding
    the key (to run in a game, say) does nothing. It reads the key state, it does not hook the keyboard."""
    tapped = pyqtSignal()
    held = pyqtSignal()                 # 4.5: held for 3 seconds: restart Rubenium
    GAME_KEYS = (0x57, 0x41, 0x53, 0x44, 0x20, 0x25, 0x26, 0x27, 0x28, 0xA0, 0x01, 0x02)  # WASD space arrows LShift mouse (not LCtrl: AltGr sends it)

    def __init__(self, parent=None, hold_s: float = 3.0, choices=None) -> None:
        super().__init__(parent)
        self.hold_s = hold_s
        self.choices = choices or KEY_CHOICES
        self.vk = 0
        self._down_at = 0.0
        self._was = False
        self._fired = False
        self._t = QTimer(self)
        self._t.setInterval(30)
        self._t.timeout.connect(self._poll)

    def set_key(self, name: str) -> None:
        self.vk = next((vk for k, _n, vk in self.choices if k == name), 0)
        self._was = False
        if self.vk and win.IS_WIN:
            self._t.start()
        else:
            self._t.stop()

    def _poll(self) -> None:
        down = win.key_down(self.vk)
        now = time.monotonic()
        if down and not self._was:
            self._down_at = now
            self._fired = False
        elif down and not self._fired and any(win.key_down(k) for k in self.GAME_KEYS):
            self._fired = True                          # held while playing (running, aiming...): never a restart
        elif down and not self._fired and now - self._down_at >= self.hold_s:
            self._fired = True
            self.held.emit()
        elif not down and self._was and now - self._down_at < 0.35:
            self.tapped.emit()
        self._was = down

    def stop(self) -> None:
        self._t.stop()


# ================================================================ badges on the music tab: size and place
BADGE_SIZES = [(70, "Small"), (100, "Normal"), (130, "Large"), (160, "Huge")]
BADGE_PLACES = [("above", "Above the title"), ("below", "Under the artist"), ("hidden", "Hidden")]
BADGE_LAYOUTS = [("row", "In a row"), ("apart", "Spread out"), ("stack", "Stacked"), ("pyramid", "Pyramid")]   # 9.1
BADGE_ALIGNS = [("left", "Left"), ("center", "Centre"), ("right", "Right")]


def badge_menu(ctx, on_change) -> None:
    from PyQt6.QtGui import QAction, QCursor
    from PyQt6.QtWidgets import QMenu
    m = QMenu()
    m.addSection(tr("Badge size"))
    for v, name in BADGE_SIZES:
        a = QAction(tr(name), m)
        a.setCheckable(True)
        a.setChecked(int(ctx.cfg["badge_size"]) == v)
        a.triggered.connect(lambda _c=False, v=v: (ctx.cfg.__setitem__("badge_size", v), on_change()))
        m.addAction(a)
    m.addSection(tr("Badge place"))
    for k, name in BADGE_PLACES:
        a = QAction(tr(name), m)
        a.setCheckable(True)
        a.setChecked(ctx.cfg["badge_pos"] == k)
        a.triggered.connect(lambda _c=False, k=k: (ctx.cfg.__setitem__("badge_pos", k), on_change()))
        m.addAction(a)
    n = len(ctx.econ.badges_worn()[:3])              # 9.1: layouts that fit how many badges you show
    layouts = {2: BADGE_LAYOUTS[:3], 3: BADGE_LAYOUTS}.get(n, ())
    cur = ctx.cfg["badge_layout"] if ctx.cfg["badge_layout"] in [k for k, _ in layouts] else "row"
    if layouts:
        m.addSection(tr("Badge layout"))
        for k, name in layouts:
            a = QAction(tr(name), m)
            a.setCheckable(True)
            a.setChecked(cur == k)
            a.triggered.connect(lambda _c=False, k=k: (ctx.cfg.__setitem__("badge_layout", k), on_change()))
            m.addAction(a)
    if cur != "apart":
        m.addSection(tr("Badge alignment"))
        for k, name in BADGE_ALIGNS:
            a = QAction(tr(name), m)
            a.setCheckable(True)
            a.setChecked(ctx.cfg["badge_align"] == k)
            a.triggered.connect(lambda _c=False, k=k: (ctx.cfg.__setitem__("badge_align", k), on_change()))
            m.addAction(a)
    if n > 1:
        m.addSection(tr("Badge spacing"))
        for k, name in enumerate(("Tight", "Normal", "Wide")):
            a = QAction(tr(name), m)
            a.setCheckable(True)
            a.setChecked(int(ctx.cfg["badge_gap"] or 0) == k)
            a.triggered.connect(lambda _c=False, k=k: (ctx.cfg.__setitem__("badge_gap", k), on_change()))
            m.addAction(a)
    m.exec(QCursor.pos())


# ================================================================ 5.3: a prize being shown can't be left half way
def claim_lock(ctx, seconds: float) -> None:
    """While a scratch card, a wheel or a prize is being revealed, nothing leaves the screen (with a time limit, so a
    lost answer can never lock the menu for good)."""
    ctx.claim_until = time.monotonic() + seconds if seconds > 0 else 0.0


def jackpot_holds(ctx) -> bool:
    """5.7.2: you joined a jackpot that is still running (or you are picking your prize): you stay on its screen."""
    d = getattr(ctx, "jackpot_data", None)
    if not isinstance(d, dict) or not d.get("mine") or d.get("state") not in ("open", "locked", "picking"):
        return False
    try:
        now = jp_now(ctx)
        if now - float(getattr(ctx, "jp_got_at", 0) or 0) > 20:     # no answer for a while: never trap anyone
            return False
        return now < float(d.get("pick_until") or 0) + 3
    except Exception:  # noqa: BLE001
        return False


def claim_blocked(ctx, minimize: bool = False) -> bool:
    """A prize being revealed, or a jackpot you're in, keeps you on its screen. 5.11: during a jackpot you may still
    minimize the menu (to use your PC), just not open another tab."""
    if getattr(ctx, "aerial_wide", False):             # Rubenium League: the match fills the menu
        try:
            ctx.toast(tr("Leave the match first"), "warn")
            ctx.window.toast_w.raise_()
            sfx.play("off")
        except Exception:  # noqa: BLE001
            pass
        return True
    if getattr(ctx, "kart_wide", False):               # 9.3.2: the race fills the menu until you leave it
        try:
            ctx.toast(tr("Leave the race first"), "warn")
            ctx.window.toast_w.raise_()
            sfx.play("off")
        except Exception:  # noqa: BLE001
            pass
        return True
    if jackpot_holds(ctx) and not minimize:
        try:
            ctx.toast(tr("You're in this jackpot: stay until it ends"), "warn")
            sfx.play("off")
        except Exception:  # noqa: BLE001
            pass
        return True
    if time.monotonic() < float(getattr(ctx, "claim_until", 0.0) or 0.0):
        try:
            ctx.toast(tr("Claim your prize first!"), "warn")
            sfx.play("off")
        except Exception:  # noqa: BLE001
            pass
        return True
    return False


# ================================================================ tutorial (5.0: first start and the 5.0 update)
# Its own window in the middle of the screen (it used to sit inside the menu and shrank or vanished with it). Every
# step has a small moving picture, two lines at most, and on some steps the settings to choose. No skipping: each
# step is confirmed, and everything can be changed later in Settings.
TUTORIAL = [      # 9.1: the guide follows the app as it is now (Play, mini games that pay by skill, tiers, Stats)
    ("welcome", "Welcome to Rubenium", "This quick guide shows the main parts and sets up the few things that matter. The menu opens when you finish."),
    ("ball", "The ball", "The R on your screen is Rubenium. Click it to open the menu, click the R again to fold it away. Pick the key that shows or hides it:"),
    ("music", "Music", "The first tab shows what is playing (Spotify, YouTube Music and more) with lyrics in time. The buttons take the colours of the song's cover."),
    ("alerts", "Notifications and sounds", "Small pop-ups tell you about trades, gifts, keys found and level ups. Choose what you want:"),
    ("coins", "Coins and keys", "Coins and keys come in just by having Rubenium open. Keys open cases in the Shop. Rewards has a free spin, a scratch card, a daily reward and quests."),
    ("online", "ONLINE mode", "The ONLINE button opens the big menu, with Play, Rewards, Stats, the Shop, trading and your friends."),
    ("play", "Play", "Mini games are free and pay by how well you do. The casino is behind its doors: there you bet coins."),
    ("tiers", "Tiers and Stats", "What you own (coins and items) sets your tier, from Poor to Casino Legend. A tier you reach is yours for good and pays more. Stats shows graphs of everything you play."),
    ("done", "You're all set!", "Everything you chose can be changed any time in Settings. Have fun!"),
]
TUTORIAL_CHOICE_KEYS = ("rshift", "rctrl", "ralt", "f9", "off")


class Tutorial(QWidget):
    """5.0: the guide, a window of its own (never inside the menu)."""

    def __init__(self, ctx, on_done=None) -> None:
        super().__init__(None)
        self.ctx, self.on_done = ctx, on_done
        self.step = 0
        self.step_at = time.monotonic()
        self.setWindowFlags(Qt.WindowType.FramelessWindowHint | Qt.WindowType.WindowStaysOnTopHint | Qt.WindowType.Tool)
        self.setAttribute(Qt.WidgetAttribute.WA_TranslucentBackground)
        self.setAttribute(Qt.WidgetAttribute.WA_DeleteOnClose)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        from PyQt6.QtGui import QGuiApplication
        screen = QGuiApplication.primaryScreen()
        geo = screen.availableGeometry() if screen is not None else None
        w, h = S(600), S(560)
        if geo is not None:
            w, h = min(w, int(geo.width() * 0.9)), min(h, int(geo.height() * 0.9))
            self.setGeometry(geo.center().x() - w // 2, geo.center().y() - h // 2, w, h)
        else:
            self.resize(w, h)
        self.body = QWidget(self)
        self._build()
        self._t = QTimer(self)
        self._t.setInterval(16)
        self._t.timeout.connect(self._tick)
        self._t.start()
        self.show()
        self.raise_()
        self.activateWindow()
        sfx.play("on")

    # -------------------------------------------------------------- layout of one step
    def _pic_rect(self) -> QRectF:
        return QRectF(S(24), S(54), self.width() - S(48), self.height() * 0.30)

    def _build(self) -> None:
        old = self.body
        self.body = QWidget(self)
        old.hide()
        old.deleteLater()
        top = int(self._pic_rect().bottom() + S(14))
        self.body.setGeometry(S(28), top, self.width() - S(56), self.height() - top - S(18))
        lay = vbox(self.body, 8)
        kind, title, text = TUTORIAL[self.step]
        lay.addWidget(Label(tr(title), 19, bold=True, wrap_w=self.body.width()))
        lay.addWidget(Label(tr(text), 12, TEXT_DIM, wrap_w=self.body.width()))
        cfg = self.ctx.cfg
        if kind == "welcome":
            seg = Segmented(["English", "Français"], 1 if lang() == "fr" else 0)

            def set_lang_(i: int) -> None:
                code = "fr" if i == 1 else "en"
                if code != lang():
                    self.ctx.set_language(code)
                    QTimer.singleShot(50, self._build)
            seg.changed.connect(set_lang_)
            lay.addWidget(Label(tr("Language"), 11, TEXT))
            lay.addWidget(seg)
        elif kind == "ball":
            keys = [k for k in TUTORIAL_CHOICE_KEYS if k == "off" or any(c[0] == k for c in KEY_CHOICES)]
            if cfg["hotkey"] not in keys and any(c[0] == cfg["hotkey"] for c in KEY_CHOICES):
                keys.insert(0, cfg["hotkey"])
            names = {c[0]: c[1] for c in KEY_CHOICES}
            seg = Segmented([tr("No key") if k == "off" else names.get(k, k).replace("Right ", "R ") for k in keys],
                            keys.index(cfg["hotkey"]) if cfg["hotkey"] in keys else 0)

            def set_key(i: int) -> None:
                cfg["hotkey"] = keys[i]
                try:
                    self.ctx.tapkey.set_key(keys[i])
                except Exception:  # noqa: BLE001
                    pass
            seg.changed.connect(set_key)
            lay.addWidget(seg)
        elif kind == "alerts":
            lay.addWidget(self._toggle(tr("Notifications"), "notify_all"))
            lay.addWidget(self._toggle(tr("Sounds"), "sounds",
                                       lambda v: (setattr(sfx, "enabled", bool(v)), cfg.__setitem__("notify_sound", bool(v)))))
        lay.addStretch(1)
        line = hbox(spacing=8)
        self.back = Button(tr("Back"), "ghost", 38)
        self.back.clicked.connect(self._back)
        self.back.setVisible(self.step > 0)
        last = self.step == len(TUTORIAL) - 1
        choose = kind in ("welcome", "ball", "alerts")
        self.next = Button(tr("Start playing") if last else (tr("Confirm") if choose else tr("Next")) +
                           f"  {self.step + 1}/{len(TUTORIAL)}", "primary", 38)
        self.next.clicked.connect(self._next)
        self.next.setEnabled(False)                     # read it first: Next wakes up after a moment
        line.addWidget(self.back, 1)
        line.addWidget(self.next, 2)
        lay.addLayout(line)
        self.body.show()
        self.step_at = time.monotonic()

    def _toggle(self, label: str, key: str, after=None) -> QWidget:
        row = QWidget()
        rl = hbox(row, 8)
        rl.addWidget(Label(label, 12, TEXT), 1)
        t = Toggle(bool(self.ctx.cfg[key]))

        def flip(v: bool) -> None:
            self.ctx.cfg[key] = bool(v)
            if after:
                after(v)
        t.toggled_by_user.connect(flip)
        rl.addWidget(t)
        return row

    # -------------------------------------------------------------- moving on
    def _tick(self) -> None:
        if not self.next.isEnabled() and time.monotonic() - self.step_at > 1.2:
            self.next.setEnabled(True)
        self.update(self._pic_rect().toRect().adjusted(-4, -40, 4, 4))

    def _next(self) -> None:
        sfx.play("pick")
        if self.step >= len(TUTORIAL) - 1:
            return self.finish()
        self.step += 1
        self._build()

    def _back(self) -> None:
        if self.step > 0:
            sfx.play("pick")
            self.step -= 1
            self._build()

    def finish(self) -> None:
        cfg = self.ctx.cfg
        cfg["tutorial_done"] = True
        try:
            cfg.save()
            self.ctx.apply_config()
        except Exception:  # noqa: BLE001
            pass
        self._t.stop()
        self.close()
        if self.on_done:
            self.on_done()

    def keyPressEvent(self, e) -> None:                  # Enter confirms, nothing closes it
        if e.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter) and self.next.isEnabled():
            return self._next()
        e.accept()

    def closeEvent(self, e) -> None:
        if not self.ctx.cfg["tutorial_done"] and not getattr(self.ctx, "_closing", False):
            e.ignore()
            return
        self._t.stop()
        super().closeEvent(e)

    # -------------------------------------------------------------- paint
    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(S(4), S(4), -S(4), -S(4))
        p.setPen(QPen(alpha(ui.accent, 0.55), S(1.6)))
        p.setBrush(QColor(10, 13, 15, 250))
        p.drawRoundedRect(r, S(20), S(20))
        dots = len(TUTORIAL)
        for k in range(dots):                            # where you are
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(ui.accent if k == self.step else alpha("#FFFFFF", 0.4 if k < self.step else 0.15))
            p.drawEllipse(QPointF(r.center().x() + (k - (dots - 1) / 2) * S(16), r.top() + S(24)), S(4), S(4))
        pic = self._pic_rect()
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(255, 255, 255, 8))
        p.drawRoundedRect(pic, S(14), S(14))
        p.save()
        p.setClipRect(pic)
        self._paint_pic(p, pic, time.monotonic() - self.step_at)
        p.restore()

    def _ball(self, p: QPainter, c: QPointF, rad: float, now: float) -> None:
        glow = QRadialGradient(c, rad * 1.9)
        glow.setColorAt(0, alpha(ui.accent, 0.35))
        glow.setColorAt(1, alpha(ui.accent, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glow)
        p.drawEllipse(c, rad * 1.9, rad * 1.9)
        p.setBrush(QColor("#0B0F10"))
        p.setPen(QPen(ui.accent, max(1.5, rad * 0.08)))
        p.drawEllipse(c, rad, rad)
        p.setPen(QColor("#FFFFFF"))
        p.setFont(font(max(8.0, rad / max(0.1, ui.scale) * 0.9), QFont.Weight.Black))
        p.drawText(QRectF(c.x() - rad, c.y() - rad, rad * 2, rad * 2), int(Qt.AlignmentFlag.AlignCenter), "R")
        p.setPen(QPen(alpha(ui.accent, 0.8), max(1.0, rad * 0.06)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawArc(QRectF(c.x() - rad * 1.3, c.y() - rad * 1.3, rad * 2.6, rad * 2.6), int(now * 160 * 16) % 5760, 90 * 16)

    @staticmethod
    def _doors(p: QPainter, box: QRectF, k: float, col) -> None:
        """The doors drawn on their own little picture, so nothing of them shows outside the box."""
        from PyQt6.QtGui import QPixmap
        dpr = p.device().devicePixelRatioF() if p.device() is not None else 1.0
        pm = QPixmap(max(1, int(box.width() * dpr)), max(1, int(box.height() * dpr)))
        pm.setDevicePixelRatio(dpr)
        pm.fill(Qt.GlobalColor.transparent)
        q = QPainter(pm)
        q.setRenderHint(QPainter.RenderHint.Antialiasing)
        paint_doors(q, QRectF(0, 0, box.width(), box.height()), k, QColor(col))
        q.end()
        clip = QPainterPath()
        clip.addRoundedRect(box, S(10), S(10))
        p.save()
        p.setClipPath(clip, Qt.ClipOperation.IntersectClip)
        p.drawPixmap(box.topLeft(), pm)
        p.restore()

    def _paint_pic(self, p: QPainter, r: QRectF, t: float) -> None:
        kind = TUTORIAL[self.step][0]
        c = r.center()
        now = time.monotonic()
        u = r.height()
        if kind in ("welcome", "done"):
            self._ball(p, c, u * 0.22 * (1 + 0.05 * math.sin(now * 3)), now)
            if kind == "done":
                p.setPen(QPen(QColor("#3DDC84"), S(5), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                k = min(1.0, t / 0.6)
                a, b, d = QPointF(c.x() + u * 0.28, c.y() + u * 0.05), QPointF(c.x() + u * 0.36, c.y() + u * 0.14), \
                    QPointF(c.x() + u * 0.52, c.y() - u * 0.12)
                p.drawLine(a, a + (b - a) * min(1.0, k * 2))
                if k > 0.5:
                    p.drawLine(b, b + (d - b) * ((k - 0.5) * 2))
            for i in range(14):                          # sparkles
                ang = i * math.tau / 14 + now * 0.4
                q = c + QPointF(math.cos(ang), math.sin(ang)) * u * (0.36 + 0.04 * math.sin(now * 2 + i))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha("#FFFFFF", 0.3 + 0.3 * math.sin(now * 3 + i)))
                p.drawEllipse(q, S(2), S(2))
        elif kind == "ball":                             # the ball opens the menu, then folds it away again
            cyc = t % 3.2
            open_k = min(1.0, max(0.0, (cyc - 0.6) / 0.4)) * (1 - min(1.0, max(0.0, (cyc - 2.4) / 0.4)))
            bx = c + QPointF(-r.width() * 0.28, 0)
            self._ball(p, bx, u * 0.14, now)
            if 0.4 < cyc < 0.7 or 2.2 < cyc < 2.5:       # the click
                p.setPen(QPen(alpha("#FFFFFF", 0.8), S(2)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(bx, u * 0.2, u * 0.2)
            card = QRectF(c.x() - r.width() * 0.08, r.top() + u * 0.12, r.width() * 0.4 * open_k, u * 0.76)
            if open_k > 0.02:
                p.setPen(QPen(alpha(ui.accent, 0.7), S(1.4)))
                p.setBrush(QColor(14, 18, 20))
                p.drawRoundedRect(card, S(10), S(10))
                p.setPen(Qt.PenStyle.NoPen)
                for i in range(4):
                    p.setBrush(alpha("#FFFFFF", 0.12 * open_k))
                    p.drawRoundedRect(QRectF(card.left() + S(10), card.top() + S(12) + i * u * 0.16,
                                             max(0.0, card.width() - S(20)), u * 0.1), S(4), S(4))
            name = next((n for k, n, _v in KEY_CHOICES if k == self.ctx.cfg["hotkey"]), "")
            if name:
                paint_keycap(p, QPointF(r.right() - S(110), r.bottom() - S(26)), name)
        elif kind == "music":                            # an equaliser and a note
            n = 14
            bw = r.width() * 0.5 / n
            for i in range(n):
                hgt = u * (0.15 + 0.55 * abs(math.sin(now * 2.6 + i * 0.7)))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor.fromHsvF((i / n * 0.3 + now * 0.05) % 1.0, 0.6, 1.0, 0.85))
                p.drawRoundedRect(QRectF(c.x() - r.width() * 0.25 + i * bw, c.y() + u * 0.35 - hgt, bw * 0.7, hgt), S(2), S(2))
        elif kind == "alerts":                           # a pop-up slides in and out
            cyc = t % 2.8
            k = min(1.0, cyc / 0.4) * (1 - min(1.0, max(0.0, (cyc - 2.2) / 0.4)))
            box = QRectF(c.x() - r.width() * 0.3, r.top() - u * 0.3 + (u * 0.42) * k, r.width() * 0.6, u * 0.3)
            p.setPen(QPen(alpha(ui.accent, 0.6), S(1.2)))
            p.setBrush(QColor(16, 20, 23))
            p.drawRoundedRect(box, S(10), S(10))
            paint_key(p, QPointF(box.left() + box.height() * 0.5, box.center().y()), box.height() * 0.5, QColor("#FFD27A"))
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(12, QFont.Weight.Bold))
            p.drawText(box.adjusted(box.height(), 0, -S(8), 0), int(Qt.AlignmentFlag.AlignVCenter), tr("KEY FOUND!"))
        elif kind == "coins":                            # coins rain into a pile
            for i in range(9):
                ph = (t * 0.8 + i * 0.13) % 1.0
                x = c.x() + (i - 4) * r.width() * 0.07
                paint_coin(p, QPointF(x, r.top() + ph * u * 0.9), u * 0.07)
            paint_key(p, QPointF(c.x() + r.width() * 0.33, c.y()), u * 0.35, QColor("#FFD27A"))
        elif kind == "play":                             # 9.1: three mini game icons hop, the casino doors breathe
            names = ("Connect 4", "Timing", "Memory")
            for i, name in enumerate(names):
                lift = max(0.0, math.sin(now * 3.2 - i * 0.9)) * u * 0.06
                paint_mini_badge(p, name, QPointF(c.x() - r.width() * 0.3 + i * u * 0.32, c.y()), u * 0.26, lift)
            door = QRectF(c.x() + r.width() * 0.12, r.top() + u * 0.14, u * 0.62, u * 0.72)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(20, 16, 10))
            p.drawRoundedRect(door, S(10), S(10))
            self._doors(p, door, 0.15 + 0.15 * (math.sin(now * 1.6) + 1) / 2, QColor("#F5C04A"))
        elif kind == "tiers":                            # 9.1: the tier bar charges, the next tier lights up
            n = len(WEALTH_TIERS)
            k = (t * 0.35) % 1.0
            bar = QRectF(r.left() + r.width() * 0.1, c.y() - u * 0.05, r.width() * 0.8, u * 0.1)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(255, 255, 255, 18))
            p.drawRoundedRect(bar, bar.height() / 2, bar.height() / 2)
            g = QLinearGradient(bar.topLeft(), bar.topRight())
            for i, (_n, _at, _m, col) in enumerate(WEALTH_TIERS):
                g.setColorAt(i / (n - 1), QColor(col))
            p.setBrush(g)
            p.drawRoundedRect(QRectF(bar.left(), bar.top(), max(bar.height(), bar.width() * k), bar.height()),
                              bar.height() / 2, bar.height() / 2)
            p.setFont(font(9.5, QFont.Weight.Bold))
            for i, (name, _at, _m, col) in enumerate(WEALTH_TIERS):
                x = bar.left() + bar.width() * i / (n - 1)
                lit = k >= i / (n - 1) - 1e-6
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(col) if lit else QColor(60, 66, 72))
                p.drawEllipse(QPointF(x, bar.center().y()), bar.height() * 0.9, bar.height() * 0.9)
                p.setPen(QColor(col) if lit else alpha(TEXT_DIM, 0.7))
                p.drawText(QRectF(x - S(60), bar.bottom() + S(10), S(120), S(18)), int(Qt.AlignmentFlag.AlignCenter),
                           tr(name))
            for i in range(7):                           # a little stats graph above
                hgt = u * (0.08 + 0.18 * (0.5 + 0.5 * math.sin(i * 1.3 + now * 1.5)))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha(STAT_SERIES[0], 0.85))
                p.drawRoundedRect(QRectF(c.x() - u * 0.42 + i * u * 0.12, bar.top() - S(12) - hgt, u * 0.08, hgt),
                                  S(2), S(2))
        elif kind == "games":                            # a case that shakes, then sparkles
            cyc = t % 2.4
            sh = math.sin(now * 40) * S(4) if cyc < 1.2 else 0.0
            size = u * 0.6
            try:
                paint_case(p, QRectF(c.x() - size / 2 + sh, c.y() - size / 2, size, size), "premium")
            except Exception:  # noqa: BLE001
                pass
            if cyc >= 1.2:
                for i in range(12):
                    ang = i * math.tau / 12
                    d = (cyc - 1.2) * u * 0.5
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(QColor.fromHsvF(i / 12, 0.6, 1.0, max(0.0, 1 - (cyc - 1.2))))
                    p.drawEllipse(c + QPointF(math.cos(ang), math.sin(ang)) * d, S(3), S(3))
        elif kind == "online":                           # the garage doors open on the online menu
            k = (math.sin(now * 1.4) + 1) / 2
            box = QRectF(c.x() - r.width() * 0.32, r.top() + u * 0.1, r.width() * 0.64, u * 0.8)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(20, 26, 30))
            p.drawRoundedRect(box, S(10), S(10))
            p.setPen(QColor("#3DDC84"))
            p.setFont(font(16, QFont.Weight.Black, 2))
            p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), tr("ONLINE"))
            self._doors(p, box, k, ui.accent)


