# --------------------------------------------------------------------------- #
# 6.9: animations. How the Rubenium banner leaves (and comes back): the simple default, or one of four Mythic ones,
# each in five finishes. Every one is drawn from the same two pictures: the banner and the ball.
# --------------------------------------------------------------------------- #
from PyQt6.QtGui import QPolygonF, QRadialGradient  # noqa: E402

# 9.5: re-ranked (the cooler, the rarer), six new ones; listed from the top tier down
ANIMS = (("blackhole", "Black Hole"), ("warp", "Warp"), ("shatter", "Shattered Shard"), ("eclipse", "Eclipse"),
         ("glitch", "Glitch"), ("origami", "Origami"), ("phoenix", "Phoenix"), ("rift", "Rift"),
         ("nova", "Supernova"), ("pixel", "Pixel Dust"), ("ripple", "Ripple"))
ANIM_RARITY = {"blackhole": "exotic", "warp": "exotic", "shatter": "exotic", "eclipse": "exotic",
               "glitch": "epic", "origami": "epic", "phoenix": "epic", "rift": "epic",
               "nova": "special", "pixel": "special", "ripple": "special"}
ANIM_IDS = tuple(a[0] for a in ANIMS)
ANIM_FINS = (("", "Original"), ("titanium", "Titanium"), ("gold", "Gold"), ("prismatic", "Prismatic"))   # 9.1


def anim_fins(design: str) -> tuple:
    """9.5: Titanium is for Mythic animations only; Epic and Legendary come in Gold and Prismatic."""
    return ANIM_FIN_IDS if ANIM_RARITY.get(design) == "exotic" else ("", "gold", "prismatic")
ANIM_FIN_IDS = tuple(f[0] for f in ANIM_FINS)
ANIM_SHORT = {"": "Base", "titanium": "Titanium", "gold": "Gold", "prismatic": "Prismatic"}
ANIM_LOOK = {"nova": ("#FF8A2B", "#FFD27A"), "shatter": ("#4FD8FF", "#B4F0FF"), "rift": ("#9B5CFF", "#E0C8FF"),
             "phoenix": ("#FF4A1C", "#FFB627"), "eclipse": ("#E0405A", "#FFE08A"),
             "blackhole": ("#7A5CFF", "#FFB36B"), "warp": ("#3D8BFF", "#BFE3FF"), "glitch": ("#FF2E88", "#2EF2FF"),
             "origami": ("#FF7A59", "#FFE6D6"), "pixel": ("#3DDC84", "#C9FFE0"), "ripple": ("#2EC4FF", "#C8F2FF")}


def anim_id(design: str, fin: str = "") -> str:
    return "anim:" + design + ("-" + fin if fin else "")


def _e3_safe(x: float) -> float:
    x = max(0.0, min(1.0, x))
    return x * x * (3 - 2 * x)


def anim_split(item: str):
    """"anim:nova-gold" -> ("nova", "gold"); None when it is not one of ours."""
    kind, base, _ = parts(item)
    if kind != "anim":
        return None
    design, _, fin = base.partition("-")
    if design not in ANIM_IDS or fin not in ANIM_FIN_IDS:
        return None
    return design, fin


def _e3(x: float) -> float:
    x = max(0.0, min(1.0, x))
    return x * x * (3 - 2 * x)


def _lerp(a: QPointF, b: QPointF, t: float) -> QPointF:
    return QPointF(a.x() + (b.x() - a.x()) * t, a.y() + (b.y() - a.y()) * t)


def anim_cols(design: str, fin: str, now: float, i: float = 0.0):
    """(main, light, core) colours of an animation in a finish."""
    if fin == "prismatic":
        h = (now * 0.3 + i * 0.11) % 1.0
        return QColor.fromHsvF(h, 0.78, 1.0), QColor.fromHsvF((h + 0.14) % 1.0, 0.45, 1.0), QColor("#FFFFFF")
    if fin == "gold":
        return QColor("#FFC83D"), QColor("#FFF0A8"), QColor("#FFFFFF")
    if fin == "titanium":                                      # 9.1: brushed steel with a cold sheen
        sheen = 0.5 + 0.5 * math.sin(now * 1.7 + i * 0.4)
        return QColor("#9AA7B6"), mix(QColor("#DCE6F2"), QColor("#FFFFFF"), sheen), QColor("#FFFFFF")
    if fin == "blacktitan":
        return QColor("#2A2142"), QColor("#B9A6FF"), QColor("#EDE6FF")
    if fin == "whitetitan":
        return QColor("#F2F6FF"), QColor("#9FC4FF"), QColor("#FFFFFF")
    a, b = ANIM_LOOK.get(design, ANIM_LOOK["nova"])
    return QColor(a), QColor(b), QColor("#FFFFFF")


def _a_glow(p: QPainter, c: QPointF, r: float, col: QColor, a: float, fin: str = "") -> None:
    if r < 1 or a <= 0.01:
        return
    p.setPen(Qt.PenStyle.NoPen)
    if fin == "blacktitan":                                    # a dark hole with a violet rim
        g = QRadialGradient(c, r)
        g.setColorAt(0, QColor(6, 4, 14, int(255 * min(1, a * 1.2))))
        g.setColorAt(0.6, QColor(6, 4, 14, int(200 * min(1, a))))
        g.setColorAt(0.85, alpha(col, 0.55 * a))
        g.setColorAt(1, alpha(col, 0.0))
    else:
        g = QRadialGradient(c, r)
        g.setColorAt(0, alpha(col, min(1.0, a)))
        g.setColorAt(0.45, alpha(col, 0.35 * a))
        g.setColorAt(1, alpha(col, 0.0))
    p.setBrush(g)
    p.drawEllipse(c, r, r)


def _a_dot(p: QPainter, pt: QPointF, r: float, a: QColor, b: QColor, fin: str, op: float, star: bool = False) -> None:
    if r < 0.3 or op <= 0.02:
        return
    if fin == "blacktitan":
        p.setPen(QPen(alpha(b, 0.9 * op), max(0.8, r * 0.4)))
    else:
        p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(alpha(a, op))
    p.drawEllipse(pt, r, r)
    if star and fin in ("gold", "prismatic", "whitetitan", "titanium"):          # a little glint
        p.setPen(QPen(alpha("#FFFFFF", 0.9 * op), max(0.8, r * 0.3)))
        p.drawLine(QPointF(pt.x() - r * 2.4, pt.y()), QPointF(pt.x() + r * 2.4, pt.y()))
        p.drawLine(QPointF(pt.x(), pt.y() - r * 2.4), QPointF(pt.x(), pt.y() + r * 2.4))
        p.setPen(Qt.PenStyle.NoPen)


def _a_ring(p: QPainter, c: QPointF, r: float, col: QColor, a: float, w: float) -> None:
    if r < 1 or a <= 0.01:
        return
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(alpha(col, 0.18 * a), w * 3))
    p.drawEllipse(c, r, r)
    p.setPen(QPen(alpha(col, min(1.0, a)), w))
    p.drawEllipse(c, r, r)
    p.setPen(Qt.PenStyle.NoPen)


# ---- 1. Supernova: the banner caves into a star that blows up, and the ball is born from the flash
def _anim_nova(p, k, now, m, hole, d, fin, banner, ball) -> None:
    c = m.center()
    span = min(m.width(), m.height()) * 0.78                   # 9.1: the blast stays inside the window
    te = 0.44
    e = _e3(k / te)
    a, b, core = anim_cols("nova", fin, now)
    if k < te + 0.02:
        s = 1.0 - 0.97 * e
        w, h = m.width() * s, m.height() * s
        banner(QRectF(c.x() - w / 2, c.y() - h / 2, w, h), 1.0 - 0.45 * e)
        rnd = random.Random(5)
        for i in range(28):                                    # light streaming into the core
            ang = rnd.uniform(0, math.tau)
            r0 = m.width() * rnd.uniform(0.25, 0.5)
            f = (e * 1.2 + rnd.random() * 0.3) % 1.0
            r1 = r0 * (1 - f)
            col = anim_cols("nova", fin, now, i)[1] if fin == "prismatic" else b
            p.setPen(QPen(alpha(col, 0.7 * (1 - f)), S(1.4)))
            p.drawLine(QPointF(c.x() + math.cos(ang) * r1, c.y() + math.sin(ang) * r1 * 0.55),
                       QPointF(c.x() + math.cos(ang) * (r1 + S(16) * (1 - f)), c.y() + math.sin(ang) * (r1 + S(16) * (1 - f)) * 0.55))
        p.setPen(Qt.PenStyle.NoPen)
        _a_glow(p, c, S(14) + m.height() * 0.8 * e, a, 0.55 * e + 0.1, fin)
        _a_glow(p, c, S(8) + m.height() * 0.35 * e, core, 0.9 * e, "")
    q = (k - te) / (1 - te)
    if q > 0:
        flash = max(0.0, 1.0 - q * 3.5)
        _a_glow(p, c, span * 0.5 * (0.3 + q), core, flash, "")
        _a_glow(p, c, span * 0.35 * (0.3 + q), a, 0.6 * max(0.0, 1 - q * 1.6), fin)
        for j, (sp, wd) in enumerate(((0.62, 6.0), (0.42, 3.5))):          # two shock rings
            qq = max(0.0, q - j * 0.08)
            if qq > 0:
                col = anim_cols("nova", fin, now, j * 3)[0] if fin == "prismatic" else (b if j else a if fin != "blacktitan" else b)
                p.setBrush(Qt.BrushStyle.NoBrush)
                _a_ring(p, c, span * sp * (qq ** 0.55), col, 1.0 - qq, S(wd) * (1 - qq))
        rnd = random.Random(9)
        for i in range(80):                                    # the debris
            ang = rnd.uniform(0, math.tau)
            sp = rnd.uniform(0.15, 0.62)
            r = span * sp * (q ** 0.6)
            pt = QPointF(c.x() + math.cos(ang) * r, c.y() + math.sin(ang) * r * 0.6 + q * q * S(14))
            aa, bb, _ = anim_cols("nova", fin, now, i)
            _a_dot(p, pt, S(rnd.uniform(1.2, 3.4)) * (1 - q * 0.6), aa if i % 3 else bb, bb, fin, max(0.0, 1.0 - q) ** 0.8, i % 7 == 0)
    t = _e3((k - 0.5) / 0.5)
    op = min(1.0, max(0.0, (k - 0.46) / 0.14))
    if op > 0:
        pos = _lerp(c, hole, t)
        grow = 0.35 + 0.65 * min(1.0, (k - 0.46) / 0.3) + 0.12 * math.sin(min(1.0, (k - 0.46) / 0.3) * math.pi)
        ball(pos, d * grow, op)


# ---- 2. Shatter: the banner breaks into glass that bursts out, then every piece is pulled into the ball
def _shard_polys(m: QRectF):
    cols, rows = 9, 3
    cw, ch = m.width() / cols, m.height() / rows
    rnd = random.Random(31)
    pts = [[QPointF(m.left() + i * cw + (rnd.uniform(-0.3, 0.3) * cw if 0 < i < cols else 0),
                    m.top() + j * ch + (rnd.uniform(-0.3, 0.3) * ch if 0 < j < rows else 0)) for i in range(cols + 1)]
           for j in range(rows + 1)]
    out = []
    for j in range(rows):
        for i in range(cols):
            tl, tr_, bl, br = pts[j][i], pts[j][i + 1], pts[j + 1][i], pts[j + 1][i + 1]
            out.append(QPolygonF([tl, tr_, bl]))
            out.append(QPolygonF([tr_, br, bl]))
    return out


# ---- 3. Rift: lightning cracks the banner open, both halves are squeezed into the slit, and the ball steps out
def _bolt(rnd, a: QPointF, b: QPointF, n: int, jag: float) -> QPainterPath:
    path = QPainterPath(a)
    for i in range(1, n):
        t = i / n
        path.lineTo(QPointF(a.x() + (b.x() - a.x()) * t + rnd.uniform(-jag, jag), a.y() + (b.y() - a.y()) * t + rnd.uniform(-jag, jag) * 0.4))
    path.lineTo(b)
    return path


def _anim_rift(p, k, now, m, hole, d, fin, banner, ball) -> None:
    cx = m.center().x()
    cy = m.center().y()
    a, b, core = anim_cols("rift", fin, now)
    top, bot = m.top() - S(4), m.bottom() + S(4)
    grow = _e3(k / 0.3)
    sq = _e3((k - 0.25) / 0.5)
    close = _e3((k - 0.72) / 0.28)
    # the two halves of the banner, squeezed towards the slit
    if sq < 0.995:
        for half in (0, 1):
            p.save()
            r = QRectF(m.left(), top - S(8), cx - m.left(), bot - top + S(16)) if half == 0 else \
                QRectF(cx, top - S(8), m.right() - cx, bot - top + S(16))
            p.setClipRect(r)
            p.translate(cx, 0)
            p.scale(max(0.005, 1 - sq), 1.0)
            p.translate(-cx, 0)
            banner(m, 1.0 - 0.3 * sq)
            p.restore()
    slit_h = (m.height() * 0.5 + S(4)) * (1 - close)
    if slit_h > 1:
        wdt = (S(3) + sq * S(15)) * (1 - close * 0.7)
        _a_glow(p, QPointF(cx, cy), max(slit_h, wdt * 4), a if fin != "blacktitan" else b, 0.45 * min(1, grow * 1.5), fin)
        # the slit itself: a tall pointed shape
        sl = QPainterPath()
        sl.moveTo(cx, cy - slit_h * grow)
        sl.quadTo(cx + wdt * 2.2, cy, cx, cy + slit_h * grow)
        sl.quadTo(cx - wdt * 2.2, cy, cx, cy - slit_h * grow)
        p.setPen(QPen(alpha(b, 0.9), S(1.4)))
        p.setBrush(QColor(4, 3, 10, 250) if fin != "whitetitan" else QColor(250, 252, 255, 250))
        p.drawPath(sl)
        p.setPen(Qt.PenStyle.NoPen)
    # lightning along and around the crack
    rnd = random.Random(int(now * 16))
    for i in range(6 if k < 0.9 else 2):
        if k < 0.04:
            break
        ang = rnd.uniform(-1.2, 1.2) + (0 if i % 2 else math.pi)
        ln = m.width() * rnd.uniform(0.08, 0.28) * (0.4 + sq) * min(1, grow * 2)
        beg = QPointF(cx, cy + rnd.uniform(-1, 1) * slit_h * 0.7)
        end = QPointF(cx + math.cos(ang) * ln, beg.y() + math.sin(ang) * ln * 0.7)
        path = _bolt(rnd, beg, end, 6, S(5))
        col = anim_cols("rift", fin, now, i)[1] if fin == "prismatic" else b
        for w_, al in ((S(5), 0.16), (S(2.2), 0.55), (S(1), 1.0)):
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(alpha(core if w_ < S(1.5) else col, al * (1 - close)), w_, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(path)
    p.setPen(Qt.PenStyle.NoPen)
    # the long vertical crack
    if k < 0.75:
        h = (m.height() * 0.5 + S(10)) * grow
        path = _bolt(random.Random(3), QPointF(cx, cy - h), QPointF(cx, cy + h), 14, S(3.5) * (1 - sq * 0.6))
        for w_, al in ((S(6), 0.14), (S(2.6), 0.5), (S(1.1), 1.0)):
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(alpha(core if w_ < S(2) else b, al), w_, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    rnd = random.Random(21)
    for i in range(40):                                        # sparks pulled into the slit
        f = (now * 0.9 + rnd.random()) % 1.0
        side = -1 if i % 2 else 1
        x = cx + side * m.width() * 0.45 * (1 - f) * rnd.uniform(0.3, 1.0)
        y = cy + rnd.uniform(-1, 1) * m.height() * 0.5
        aa, bb, _ = anim_cols("rift", fin, now, i)
        _a_dot(p, QPointF(x, y), S(rnd.uniform(1, 2.2)), bb, bb, fin, 0.85 * sq * (1 - close) * (1 - f * 0.4), i % 6 == 0)
    t = _e3((k - 0.66) / 0.34)
    op = min(1.0, max(0.0, (k - 0.64) / 0.12))
    if op > 0:
        pos = _lerp(QPointF(cx, cy), hole, t)
        _a_glow(p, pos, d * 1.7, b if fin != "blacktitan" else a, 0.45 * (1 - t * 0.8), fin)
        ball(pos, d * (0.5 + 0.5 * min(1.0, (k - 0.64) / 0.25)), op)
        _a_ring(p, QPointF(cx, cy), m.width() * 0.3 * close, b, (1 - close) * 0.8, S(2.2))


# ---- 4. Phoenix: fire climbs the banner and burns it into feathers; two flaming wings carry it to the ball
def _anim_phoenix(p, k, now, m, hole, d, fin, banner, ball) -> None:
    a, b, core = anim_cols("phoenix", fin, now)
    burn = _e3(k / 0.5)
    yb = m.bottom() - m.height() * burn
    if burn < 0.995:
        p.save()
        p.setClipRect(QRectF(m.left() - S(4), m.top() - S(40), m.width() + S(8), yb - m.top() + S(40)))
        banner(m.translated(0, -S(14) * burn), 1.0 - 0.35 * burn)
        p.restore()
    p.setPen(Qt.PenStyle.NoPen)
    if 0.0 < k < 0.58:                                          # the flames along the burning edge
        fade = 1.0 - max(0.0, (k - 0.46) / 0.12)
        n = 46
        for i in range(n):
            x = m.left() + m.width() * (i + 0.5) / n
            hh = S(14 + 30 * abs(math.sin(i * 1.7 + now * 9 + k * 6))) * fade
            wd = m.width() / n * 1.2
            aa, bb, cc = anim_cols("phoenix", fin, now, i * 0.6)
            tongue = QPainterPath()
            tongue.moveTo(x - wd / 2, yb + S(4))
            tongue.quadTo(x - wd * 0.2, yb - hh * 0.5, x + math.sin(now * 7 + i) * wd * 0.3, yb - hh)
            tongue.quadTo(x + wd * 0.2, yb - hh * 0.5, x + wd / 2, yb + S(4))
            g = QLinearGradient(x, yb + S(4), x, yb - hh)
            g.setColorAt(0, alpha(bb if fin != "blacktitan" else cc, 0.95))
            g.setColorAt(0.5, alpha(aa, 0.8))
            g.setColorAt(1, alpha(aa, 0.0))
            p.setBrush(g)
            p.drawPath(tongue)
    rnd = random.Random(44)
    for i in range(110):                                       # embers spiralling up into the ball's place
        tb = rnd.uniform(0.0, 0.55)
        life = rnd.uniform(0.3, 0.5)
        uu = (k - tb) / life
        if not 0 < uu < 1:
            continue
        sx = m.left() + m.width() * rnd.random()
        sy = m.bottom() - m.height() * _e3(tb / 0.5)
        pt = _lerp(QPointF(sx, sy), hole, uu ** 1.6)
        sw = math.sin(uu * math.pi * 2 + i) * S(26) * (1 - uu)
        pt = QPointF(pt.x() + sw, pt.y())
        aa, bb, _ = anim_cols("phoenix", fin, now, i)
        _a_dot(p, pt, S(rnd.uniform(1.2, 3.2)) * (1 - uu * 0.5), aa if i % 2 else bb, bb, fin, math.sin(uu * math.pi) * 0.95, i % 9 == 0)
    # two wings of feathers made of fire
    wing = _e3((k - 0.42) / 0.3) * (1.0 - _e3((k - 0.82) / 0.18))
    if wing > 0.01:
        flap = math.sin(now * 8.0) * 0.07
        reach = min(m.width() * 0.34, max(S(60), (m.bottom() - hole.y()) * 0.9))
        down = (hole.y() - m.top()) < reach * 0.85                 # 9.1: no room above the ball: the wings sweep down
        for side in (-1, 1):
            for j in range(9):
                f = j / 8
                ang = (math.radians(8 + 62 * f) if down else math.radians(-8 - 70 * f)) + flap * (0.4 + f)
                ln = reach * (0.55 + 0.45 * math.sin(f * math.pi * 0.8 + 0.35)) * wing
                dx, dy = math.cos(ang) * side, math.sin(ang)
                tip = QPointF(hole.x() + dx * ln, hole.y() + dy * ln * 0.8)
                mid = QPointF(hole.x() + dx * ln * 0.55, hole.y() + dy * ln * 0.55 * 0.8 - ln * 0.12)
                w0 = S(7) * (1 - f * 0.4) * wing
                feather = QPainterPath()
                feather.moveTo(hole.x(), hole.y() - w0 * 0.2)
                feather.quadTo(mid.x(), mid.y() - w0, tip.x(), tip.y())
                feather.quadTo(mid.x(), mid.y() + w0, hole.x(), hole.y() + w0 * 0.2)
                aa, bb, cc = anim_cols("phoenix", fin, now, j * side)
                g = QLinearGradient(hole, tip)
                g.setColorAt(0, alpha(cc if fin != "blacktitan" else bb, 0.95 * wing))
                g.setColorAt(0.45, alpha(bb, 0.85 * wing))
                g.setColorAt(1, alpha(aa, 0.0))
                p.setBrush(g)
                p.setPen(QPen(alpha(bb if fin == "blacktitan" else cc, 0.35 * wing), S(0.8)))
                p.drawPath(feather)
        p.setPen(Qt.PenStyle.NoPen)
        _a_glow(p, hole, d * 2.0 * wing, a if fin != "blacktitan" else b, 0.5 * wing, fin)
    op = min(1.0, max(0.0, (k - 0.58) / 0.22))
    if op > 0:
        e = _e3((k - 0.58) / 0.3)
        ball(hole, d * (0.55 + 0.45 * e + 0.1 * math.sin(e * math.pi)), op)


# ---- 5. Eclipse (9.1, Mythic): a dark moon slides over the banner; at totality the corona blazes, a diamond ring
# flashes on its rim, and the moon slips away into the ball
def _anim_eclipse(p, k, now, m, hole, d, fin, banner, ball) -> None:
    c = m.center()
    a, b, core = anim_cols("eclipse", fin, now)
    R = min(m.height() * 0.5, m.width() * 0.16)                 # the moon at totality (its corona stays on screen)
    cover = _e3(k / 0.42)
    start = QPointF(m.left() - R * 1.2, c.y() - m.height() * 0.1)
    moon = _lerp(start, c, cover)
    gone = _e3((k - 0.30) / 0.18)                                # the banner fades away under the moon
    if gone < 1.0:
        banner(m, (1.0 - 0.55 * cover) * (1.0 - gone))
    leave = _e3((k - 0.56) / 0.36)                               # the moon shrinks into the ball
    if leave > 0:
        moon = _lerp(c, hole, leave)
    rad = R * (1.0 - 0.86 * leave) * (0.55 + 0.45 * cover)
    moon_op = min(1.0, k / 0.06) * (1.0 - _e3((k - 0.86) / 0.12))
    total = max(0.0, min(1.0, (k - 0.34) / 0.12)) * (1.0 - leave)   # how bright the corona is
    if total > 0:
        _a_glow(p, moon, rad * 2.0, a, 0.55 * total, fin)
        rnd = random.Random(41)
        for i in range(48):                                      # the corona's streamers, slowly turning
            ang = i * math.tau / 48 + rnd.uniform(-0.05, 0.05) + now * 0.05
            ln = rad * (1.18 + rnd.uniform(0.15, 0.7) * (0.75 + 0.25 * math.sin(now * 1.3 + i)))
            col = anim_cols("eclipse", fin, now, i)[1] if fin == "prismatic" else (b if i % 2 else a)
            p.setPen(QPen(alpha(col, 0.5 * total * rnd.uniform(0.5, 1.0)), S(rnd.uniform(0.8, 2.0))))
            p.drawLine(QPointF(moon.x() + math.cos(ang) * rad * 1.02, moon.y() + math.sin(ang) * rad * 1.02),
                       QPointF(moon.x() + math.cos(ang) * ln, moon.y() + math.sin(ang) * ln))
        p.setPen(Qt.PenStyle.NoPen)
        _a_ring(p, moon, rad * 1.04, b, 0.9 * total, S(2.2))
    if leave > 0:                                                # sparks trailing the moon to the ball
        rnd = random.Random(8)
        for i in range(24):
            f = max(0.0, min(1.0, leave - rnd.uniform(0.0, 0.3)))
            if f <= 0:
                continue
            off = rnd.uniform(-1, 1) * S(18) * (1 - f)
            pt = _lerp(c, hole, f)
            aa, bb, _ = anim_cols("eclipse", fin, now, i)
            _a_dot(p, QPointF(pt.x() + off, pt.y() + off * 0.5), S(rnd.uniform(1.0, 2.4)), aa if i % 2 else bb, bb, fin,
                   (1 - f) * 0.9 * (1 - leave), i % 6 == 0)
    if moon_op > 0.01 and rad > 0.5:                             # the moon: dark, with a faint lit edge
        g = QRadialGradient(QPointF(moon.x() - rad * 0.3, moon.y() - rad * 0.3), rad * 1.3)
        g.setColorAt(0, QColor(28, 24, 36, int(255 * moon_op)))
        g.setColorAt(1, QColor(4, 3, 8, int(255 * moon_op)))
        p.setPen(QPen(alpha(b, 0.35 * moon_op), S(1)))
        p.setBrush(g)
        p.drawEllipse(moon, rad, rad)
        p.setPen(Qt.PenStyle.NoPen)
    ring = max(0.0, 1.0 - abs(k - 0.54) / 0.09)                  # the diamond ring, on the rim
    if ring > 0 and rad > 1:
        ang = -0.75
        bead = QPointF(moon.x() + math.cos(ang) * rad, moon.y() + math.sin(ang) * rad)
        _a_glow(p, bead, S(46) * ring, core, ring, "")
        _a_glow(p, bead, S(22) * ring, b, ring, fin)
        p.setPen(QPen(alpha(core, 0.9 * ring), S(1.6)))
        for t_ in range(4):                                      # a four-point star flare
            fa = t_ * math.pi / 2 + 0.3
            ln = S(70) * ring if t_ % 2 == 0 else S(34) * ring
            p.drawLine(QPointF(bead.x() - math.cos(fa) * ln, bead.y() - math.sin(fa) * ln),
                       QPointF(bead.x() + math.cos(fa) * ln, bead.y() + math.sin(fa) * ln))
        p.setPen(Qt.PenStyle.NoPen)
    op = min(1.0, max(0.0, (k - 0.72) / 0.2))
    if op > 0:
        e = _e3((k - 0.72) / 0.28)
        _a_ring(p, hole, d * (0.8 + 0.9 * e), b, 0.7 * (1 - e), S(2))
        ball(hole, d * (0.6 + 0.4 * e), op)


# ---- 9.5: helpers for the new animations
def _clip_poly(p: QPainter, poly) -> None:
    """Clip to a shape INSIDE the clip already set (the previews clip to their rounded card)."""
    path = QPainterPath()
    path.addPolygon(poly)
    path.closeSubpath()
    p.setClipPath(path, Qt.ClipOperation.IntersectClip)


def _shard_polys95(m: QRectF, n: int = 34):
    """Glass pieces that suit the window's shape: about n triangles, never long slivers."""
    ratio = m.width() / max(1.0, m.height())
    cols = max(3, int(round(math.sqrt(n / 2 * ratio))))
    rows = max(3, int(round(n / 2 / cols)))
    cw, ch = m.width() / cols, m.height() / rows
    rnd = random.Random(31)
    pts = [[QPointF(m.left() + i * cw + (rnd.uniform(-0.32, 0.32) * cw if 0 < i < cols else 0),
                    m.top() + j * ch + (rnd.uniform(-0.32, 0.32) * ch if 0 < j < rows else 0)) for i in range(cols + 1)]
           for j in range(rows + 1)]
    out = []
    for j in range(rows):
        for i in range(cols):
            tl, tr_, bl, br = pts[j][i], pts[j][i + 1], pts[j + 1][i], pts[j + 1][i + 1]
            if (i + j) % 2:
                out += [QPolygonF([tl, tr_, br]), QPolygonF([tl, br, bl])]
            else:
                out += [QPolygonF([tl, tr_, bl]), QPolygonF([tr_, br, bl])]
    return out


def _tint(p: QPainter, shape, col: QColor, a: float) -> None:
    """A coloured film over what was just drawn (the finish shows on the banner itself, not only around it)."""
    if a <= 0.01:
        return
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(alpha(col, a))
    if isinstance(shape, QRectF):
        p.drawRect(shape)
    else:
        p.drawPolygon(shape)


def _tint_fin(p: QPainter, shape, fin: str, col: QColor, a: float) -> None:
    """The finish as a film: Gold and Titanium first wash the colour out of the picture, so the metal reads true
    (gold straight over a blue banner went olive)."""
    if fin in ("gold", "titanium") and a > 0.01:
        _tint(p, shape, QColor("#C8C8C8" if fin == "titanium" else "#5A4A2A"), min(0.55, a * 1.3))
        a = min(0.75, a * 1.4)
    _tint(p, shape, col, a)


def _fin_tint(fin: str) -> float:
    return {"": 0.10, "titanium": 0.34, "gold": 0.36, "prismatic": 0.30}.get(fin, 0.2)


# ---- 2. Shatter (9.5, Mythic): the window cracks from one point, bursts into tinted glass that stays on screen,
# then every piece is swirled into the ball
def _anim_shatter(p, k, now, m, hole, d, fin, banner, ball) -> None:
    c = m.center()
    hit = QPointF(c.x() + m.width() * 0.08, c.y() - m.height() * 0.06)
    a, b, core = anim_cols("shatter", fin, now)
    crack = _e3(k / 0.1)
    u = _e3((k - 0.08) / 0.4)                                # the burst
    v = _e3((k - 0.46) / 0.4)                                # pulled into the ball
    reach = min(m.width(), m.height()) * 0.34
    if k < 0.12:                                             # 1. the window cracks
        banner(m, 1.0)
        _tint_fin(p, m, fin, a, _fin_tint(fin) * crack * 0.6)
        rnd = random.Random(4)
        p.setBrush(Qt.BrushStyle.NoBrush)
        for i in range(14):
            ang = i * math.tau / 14 + rnd.uniform(-0.2, 0.2)
            ln = reach * rnd.uniform(0.6, 1.4) * crack
            col = anim_cols("shatter", fin, now, i)[1]
            p.setPen(QPen(alpha(col, 0.9), S(1.6)))
            path = _bolt(rnd, hit, QPointF(hit.x() + math.cos(ang) * ln, hit.y() + math.sin(ang) * ln), 5, S(6))
            p.drawPath(path)
        _a_glow(p, hit, S(40) + reach * 0.5 * crack, core, 0.8 * crack, "")
        return
    polys = _shard_polys95(m)
    rnd = random.Random(77)
    for i, poly in enumerate(polys):
        cen = poly.boundingRect().center()
        dx, dy = cen.x() - hit.x(), cen.y() - hit.y()
        dist0 = math.hypot(dx, dy) + 1
        ang = math.atan2(dy, dx) + rnd.uniform(-0.35, 0.35)
        push = reach * rnd.uniform(0.25, 0.75) * (1.2 - min(1.0, dist0 / (reach * 2)) * 0.5)
        rot = rnd.uniform(-260, 260)
        blown = QPointF(cen.x() + math.cos(ang) * push * u, cen.y() + math.sin(ang) * push * u + u * u * S(10))
        # into the ball along a spiral
        sw = v ** 1.4
        spin = (1 - sw) * rnd.uniform(1.2, 2.4)
        rr = math.hypot(blown.x() - hole.x(), blown.y() - hole.y()) * (1 - sw)
        a0 = math.atan2(blown.y() - hole.y(), blown.x() - hole.x()) + (1 - (1 - sw) ** 0.5) * spin * 2.2
        cur = QPointF(hole.x() + math.cos(a0) * rr, hole.y() + math.sin(a0) * rr) if v > 0 else blown
        sc = (1.0 - 0.12 * u) * (1.0 - 0.95 * sw)
        op = max(0.0, 1.0 - max(0.0, v - 0.75) / 0.25)
        if op <= 0.01 or sc <= 0.02:
            continue
        p.save()
        p.translate(cur)
        p.rotate(rot * u + rot * 2 * v)
        p.scale(sc, sc)
        p.translate(-cen.x(), -cen.y())
        _clip_poly(p, poly)
        banner(m, op, True)
        aa, bb, _ = anim_cols("shatter", fin, now, i)
        _tint_fin(p, poly, fin, aa, (_fin_tint(fin) + 0.12 * u) * op)
        # a glint across the glass as it turns
        g = 0.5 + 0.5 * math.sin(now * 3 + i)
        _tint(p, poly, QColor("#FFFFFF"), 0.10 * g * u * op)
        p.restore()
        p.save()
        p.translate(cur)
        p.rotate(rot * u + rot * 2 * v)
        p.scale(sc, sc)
        p.translate(-cen.x(), -cen.y())
        p.setPen(QPen(alpha(bb, 0.85 * op), S(1.4) / max(0.25, sc)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPolygon(poly)
        p.restore()
    rnd = random.Random(12)
    for i in range(60):                                       # glass dust, then the trail into the ball
        ang = rnd.uniform(0, math.tau)
        r = reach * rnd.uniform(0.2, 1.2) * u
        base = QPointF(hit.x() + math.cos(ang) * r, hit.y() + math.sin(ang) * r)
        pt = _lerp(base, hole, v ** 1.2)
        aa, bb, _ = anim_cols("shatter", fin, now, i)
        _a_dot(p, pt, S(rnd.uniform(0.9, 2.4)), bb, bb, fin, (1 - v) * 0.9 * min(1.0, u * 3), i % 4 == 0)
    if v > 0:
        _a_glow(p, hole, d * (0.9 + 1.6 * v), a, 0.55 * v * (1 - max(0.0, v - 0.85) * 5), fin)
        _a_ring(p, hole, d * (0.6 + 1.8 * v), b, (1 - v) * 0.9, S(2.2))
    op = min(1.0, max(0.0, (k - 0.8) / 0.15))
    if op > 0:
        e = _e3((k - 0.8) / 0.2)
        _a_ring(p, hole, d * (0.7 + 1.2 * e), core, 0.8 * (1 - e), S(2.5))
        ball(hole, d * (0.55 + 0.45 * e + 0.08 * math.sin(e * math.pi)), op)


# ---- 6. Black Hole (9.5, Mythic): a singularity opens in the middle, the window is torn into strips that spiral
# into it, the hole collapses in a flash and the ball is fired up to its place
def _anim_blackhole(p, k, now, m, hole, d, fin, banner, ball) -> None:
    c = m.center()
    a, b, core = anim_cols("blackhole", fin, now)
    size = min(m.width(), m.height())
    grow = _e3(k / 0.22)
    pull = _e3((k - 0.12) / 0.5)
    collapse = _e3((k - 0.6) / 0.12)
    rh = size * 0.13 * grow * (1 - collapse)                 # the event horizon
    if collapse < 1:                                          # the accretion disk behind
        for j in range(3):
            p.save()
            p.translate(c)
            p.rotate(-18 + j * 6)
            p.scale(1.0, 0.32)
            col = anim_cols("blackhole", fin, now, j * 5)
            r = rh * (2.3 + j * 0.55) + S(2)
            g = QRadialGradient(QPointF(0, 0), r)
            g.setColorAt(0.0, alpha(col[2], 0.0))
            g.setColorAt(0.55, alpha(col[1], 0.0))
            g.setColorAt(0.72, alpha(col[1], 0.55 * grow))
            g.setColorAt(0.86, alpha(col[0], 0.35 * grow))
            g.setColorAt(1.0, alpha(col[0], 0.0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(g)
            p.drawEllipse(QPointF(0, 0), r, r)
            p.restore()
    if pull < 0.995:                                          # the window, torn into strips that spiral in
        n = 14
        sh = m.height() / n
        for i in range(n):
            strip = QRectF(m.left(), m.top() + i * sh, m.width(), sh + 1)
            dist = abs(strip.center().y() - c.y()) / (m.height() / 2)
            lag = 0.25 * dist
            t = _e3((pull - lag * 0.6) / (1 - lag * 0.6)) if pull > lag * 0.6 else 0.0
            if t >= 0.995:
                continue
            p.save()
            p.translate(c)
            p.rotate(t * (260 + 140 * (1 - dist)) * (1 if i % 2 else 0.85))
            sc = max(0.01, 1 - t)
            p.scale(sc * (1 + t * 0.6), sc * (1 - t * 0.5))
            p.translate(-c.x(), -c.y())
            p.setClipRect(strip, Qt.ClipOperation.IntersectClip)
            banner(m, 1.0 - 0.25 * t)
            _tint_fin(p, strip, fin, a, (_fin_tint(fin) + 0.3 * t) * (1 - t))
            p.restore()
    rnd = random.Random(21)
    for i in range(70):                                       # matter falling in
        ph = (rnd.random() + now * rnd.uniform(0.25, 0.5)) % 1.0
        ang = rnd.uniform(0, math.tau) + ph * 4.0
        r = size * 0.55 * (1 - ph) * grow * (1 - collapse) + rh
        pt = QPointF(c.x() + math.cos(ang) * r, c.y() + math.sin(ang) * r * 0.45)
        aa, bb, _ = anim_cols("blackhole", fin, now, i)
        _a_dot(p, pt, S(rnd.uniform(0.8, 2.0)), bb if i % 2 else aa, bb, fin, 0.8 * ph * grow * (1 - collapse), i % 9 == 0)
    if rh > 0.5:                                              # the horizon: black, with a bright lensing ring
        _a_ring(p, c, rh * 1.12, b, 0.9, S(2))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(2, 2, 6))
        p.drawEllipse(c, rh, rh)
    if k > 0.6:                                               # the flash, the shock ring, and the shot up
        f = (k - 0.6) / 0.4
        _a_glow(p, c, size * 0.5 * (0.2 + f), core, max(0.0, 1 - f * 3.2), "")
        _a_ring(p, c, size * 0.6 * _e3(f * 1.4), a, max(0.0, 1 - f * 1.6), S(4) * (1 - f))
        t = _e3((k - 0.66) / 0.3)
        if t > 0:
            pos = _lerp(c, hole, t)
            for j in range(6):                                # a streak behind it
                q = _lerp(c, pos, j / 6)
                _a_dot(p, q, d * 0.12 * (j + 1) / 6, b, b, fin, 0.5 * (1 - t * 0.6) * (j + 1) / 6)
            ball(pos, d * (0.45 + 0.55 * t), min(1.0, t * 3))


# ---- 7. Warp (9.5, Mythic): hyperspace: the stars stream past, the window is stretched into a beam of light that
# shoots up into the ball's place, which comes out of the jump with a flare
def _anim_warp(p, k, now, m, hole, d, fin, banner, ball) -> None:
    c = m.center()
    a, b, core = anim_cols("warp", fin, now)
    size = max(m.width(), m.height())
    speed = _e3(k / 0.45)
    stretch = _e3((k - 0.22) / 0.36)
    jump = _e3((k - 0.55) / 0.16)
    rnd = random.Random(8)
    for i in range(90):                                       # the star streaks
        ang = rnd.uniform(0, math.tau)
        ph = (rnd.random() + now * (0.15 + 1.4 * speed) * rnd.uniform(0.6, 1.2)) % 1.0
        r0 = size * 0.55 * ph ** 1.6
        ln = S(2) + size * 0.22 * speed * ph
        p1 = QPointF(c.x() + math.cos(ang) * r0, c.y() + math.sin(ang) * r0)
        p2 = QPointF(c.x() + math.cos(ang) * (r0 + ln), c.y() + math.sin(ang) * (r0 + ln))
        col = anim_cols("warp", fin, now, i)[1] if i % 3 else core
        p.setPen(QPen(alpha(col, (0.25 + 0.6 * speed) * min(1.0, ph * 3) * (1 - jump) ** 2), S(1.0 + speed)))
        p.drawLine(p1, p2)
    if stretch < 0.999:                                       # the window becomes a beam towards the hole
        shake = S(2.5) * speed * (1 - stretch) * math.sin(now * 70)
        w = m.width() * (1 - 0.94 * stretch)
        h = m.height() * (1 + 0.6 * stretch) * (1 - 0.85 * stretch ** 3)
        cx = c.x() + shake
        cy = c.y() + (hole.y() + h / 2 - c.y()) * stretch ** 1.5
        box = QRectF(cx - w / 2, cy - h / 2, w, h)
        p.save()
        p.translate(box.center())
        p.scale(box.width() / max(1.0, m.width()), box.height() / max(1.0, m.height()))
        p.translate(-c.x(), -c.y())
        banner(m, 1.0 - 0.2 * stretch)
        _tint_fin(p, m, fin, a, (_fin_tint(fin) + 0.4) * stretch)
        p.restore()
        g = QLinearGradient(QPointF(box.left(), 0), QPointF(box.right(), 0))
        g.setColorAt(0, alpha(b, 0.0))
        g.setColorAt(0.5, alpha(core, 0.85 * stretch))
        g.setColorAt(1, alpha(b, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawRect(box.adjusted(-w * 0.6, 0, w * 0.6, 0))
    if k > 0.55:
        f = (k - 0.55) / 0.45
        _a_glow(p, hole, d * (1.0 + 5 * jump) * (1 - f * 0.5), core, max(0.0, 1 - f * 2.2), "")
        _a_ring(p, hole, d * (0.8 + 4.5 * _e3(f * 1.2)), b, max(0.0, 1 - f * 1.4), S(3) * (1 - f))
        if f < 0.6:                                           # the flare
            fl = 1 - f / 0.6
            p.setPen(QPen(alpha(core, 0.8 * fl), S(1.5)))
            p.drawLine(QPointF(hole.x() - d * 4 * fl, hole.y()), QPointF(hole.x() + d * 4 * fl, hole.y()))
            p.setPen(QPen(alpha(b, 0.6 * fl), S(1.2)))
            p.drawLine(QPointF(hole.x(), hole.y() - d * 1.6 * fl), QPointF(hole.x(), hole.y() + d * 1.6 * fl))
        op = min(1.0, max(0.0, (k - 0.66) / 0.14))
        if op > 0:
            e = _e3((k - 0.66) / 0.34)
            ball(hole, d * (0.4 + 0.6 * e + 0.1 * math.sin(e * math.pi)), op)


# ---- 8. Glitch (9.5, Legendary): the window corrupts: slices jump, the colours split, then it falls apart into
# blocks that teleport up in steps and rebuild as the ball
def _anim_glitch(p, k, now, m, hole, d, fin, banner, ball) -> None:
    a, b, core = anim_cols("glitch", fin, now)
    step = int(now * 18)                                     # glitches move in jumps, not smoothly
    rnd = random.Random(step)
    bad = _e3(k / 0.4)
    gone = _e3((k - 0.34) / 0.3)
    if gone < 0.999:
        n = 12
        sh = m.height() / n
        for i in range(n):
            strip = QRectF(m.left() - m.width(), m.top() + i * sh, m.width() * 3, sh + 1)
            off = (rnd.uniform(-1, 1) * m.width() * 0.12 * bad) if rnd.random() < 0.15 + 0.5 * bad else 0.0
            keep = 1.0 if rnd.random() > gone else 0.0
            if not keep:
                continue
            p.save()
            p.setClipRect(strip, Qt.ClipOperation.IntersectClip)
            p.translate(off, 0)
            banner(m, 1.0 - 0.3 * bad)
            p.restore()
            if bad > 0.05 and off:                            # the split colour channels
                band = QRectF(m.left() + off, m.top() + i * sh, m.width(), sh)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha(a, 0.35 * bad))
                p.drawRect(band.translated(-S(6) * bad, 0))
                p.setBrush(alpha(b, 0.30 * bad))
                p.drawRect(band.translated(S(6) * bad, 0))
        p.setPen(Qt.PenStyle.NoPen)                            # scanlines
        p.setBrush(alpha("#000000", 0.18 * bad * (1 - gone)))
        y = m.top()
        while y < m.bottom():
            p.drawRect(QRectF(m.left(), y, m.width(), S(1)))
            y += S(4)
    # the blocks: thrown out, then up to the hole in six jumps
    if k > 0.3:
        u = _e3((k - 0.3) / 0.2)
        jumps = min(6, int(max(0.0, (k - 0.48) / 0.3) * 6.999))
        r2 = random.Random(5)
        for i in range(56):
            x0 = m.left() + r2.random() * m.width()
            y0 = m.top() + r2.random() * m.height()
            out = QPointF(x0 + r2.uniform(-1, 1) * S(30) * u, y0 + r2.uniform(-1, 1) * S(30) * u)
            t = jumps / 6
            pos = _lerp(out, QPointF(hole.x() + r2.uniform(-1, 1) * d * (1 - t), hole.y() + r2.uniform(-1, 1) * d * (1 - t)), t)
            sz = S(r2.uniform(4, 11)) * (1 - 0.6 * t)
            col = anim_cols("glitch", fin, now, i)[r2.randint(0, 1)]
            op = min(1.0, u * 2) * (1 - max(0.0, (k - 0.82) / 0.1))
            if op <= 0:
                continue
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha(col, 0.85 * op))
            p.drawRect(QRectF(pos.x() - sz / 2, pos.y() - sz / 2, sz, sz))
    if k > 0.78:                                              # the ball, flickering in with its colours split
        e = _e3((k - 0.78) / 0.22)
        flick = 1.0 if e > 0.7 else (1.0 if (step % 3) else 0.35)
        if e < 0.9:
            _a_glow(p, QPointF(hole.x() - S(4) * (1 - e), hole.y()), d * 0.8, a, 0.5 * (1 - e), "")
            _a_glow(p, QPointF(hole.x() + S(4) * (1 - e), hole.y()), d * 0.8, b, 0.5 * (1 - e), "")
        ball(hole, d * (0.7 + 0.3 * e), min(1.0, e * 2) * flick)


# ---- 9. Origami (9.5, Legendary): the window folds in half, and in half again, creases into a paper plane that
# loops up to the hole and opens into the ball
def _anim_origami(p, k, now, m, hole, d, fin, banner, ball) -> None:
    a, b, core = anim_cols("origami", fin, now)
    f1 = _e3(k / 0.2)                                        # bottom half folds up
    f2 = _e3((k - 0.2) / 0.18)                               # right half folds over
    shrink = _e3((k - 0.36) / 0.14)
    fly = _e3((k - 0.48) / 0.4)
    top = QRectF(m.left(), m.top(), m.width(), m.height() / 2)
    if k < 0.38:
        midy = m.center().y()
        if f2 <= 0:
            p.save()                                          # the top half, flat
            p.setClipRect(top, Qt.ClipOperation.IntersectClip)
            banner(m, 1.0)
            p.restore()
            fy = math.cos(f1 * math.pi)                       # the bottom half, turning over the crease
            p.save()
            p.translate(0, midy)
            p.scale(1.0, fy if abs(fy) > 0.01 else 0.01)
            p.translate(0, -midy)
            if fy >= 0:
                p.setClipRect(QRectF(m.left(), midy, m.width(), m.height() / 2), Qt.ClipOperation.IntersectClip)
                banner(m, 1.0)
                _tint(p, m, QColor("#000000"), 0.35 * f1)
            else:                                             # its back: paper in the animation's colour
                back = QRectF(m.left(), midy, m.width(), m.height() / 2)
                g = QLinearGradient(back.topLeft(), back.bottomRight())
                g.setColorAt(0, mix(a, QColor("#FFFFFF"), 0.35))
                g.setColorAt(1, a)
                p.setPen(QPen(alpha(b, 0.8), S(1)))
                p.setBrush(g)
                p.drawRect(back)
            p.restore()
        else:                                                 # second fold: the right half over the left
            g = QLinearGradient(top.topLeft(), top.bottomRight())
            g.setColorAt(0, mix(a, QColor("#FFFFFF"), 0.35))
            g.setColorAt(1, a)
            left = QRectF(top.left(), top.top(), top.width() / 2, top.height())
            p.setPen(QPen(alpha(b, 0.8), S(1)))
            p.setBrush(g)
            p.drawRect(left)
            fx = math.cos(f2 * math.pi)
            midx = top.center().x()
            right = QRectF(midx, top.top(), top.width() / 2, top.height())
            p.save()
            p.translate(midx, 0)
            p.scale(fx if abs(fx) > 0.01 else 0.01, 1.0)
            p.translate(-midx, 0)
            p.setBrush(mix(a, QColor("#000000"), 0.2 * (1 - fx)) if fx < 0 else g)
            p.drawRect(right)
            p.restore()
            p.setPen(QPen(alpha("#FFFFFF", 0.5), S(1), Qt.PenStyle.DashLine))
            p.drawLine(QPointF(top.left(), top.bottom()), QPointF(top.right() if fx > 0 else midx, top.bottom()))
    else:
        # a paper plane, flying a loop up to the hole
        start = QPointF(m.left() + m.width() * 0.25, m.top() + m.height() * 0.25)
        loop_c = QPointF(m.center().x(), m.top() + m.height() * 0.36)
        rad = min(m.width(), m.height()) * 0.2
        if fly <= 0:                                          # the folded square creases into the plane
            pos, ang = start, 0.0
            sq = QRectF(m.left(), m.top(), m.width() / 2, m.height() / 2)
            sz = S(26)
            plane = [QPointF(start.x() + sz, start.y()), QPointF(start.x() - sz * 0.8, start.y() - sz * 0.55),
                     QPointF(start.x() - sz * 0.45, start.y()), QPointF(start.x() - sz * 0.8, start.y() + sz * 0.55)]
            corners = [sq.topRight(), sq.topLeft(), sq.center(), sq.bottomLeft()]
            poly = QPolygonF([_lerp(c0, c1, shrink) for c0, c1 in zip(corners, plane)])
            g = QLinearGradient(sq.topLeft(), sq.bottomRight())
            g.setColorAt(0, mix(a, QColor("#FFFFFF"), 0.45))
            g.setColorAt(1, a)
            p.setPen(QPen(alpha(b, 0.9), S(1)))
            p.setBrush(g)
            p.drawPolygon(poly)
            return
        elif fly < 0.7:
            t = fly / 0.7
            th = math.pi + t * math.tau * 0.9
            pos = QPointF(loop_c.x() + math.cos(th) * rad * (1 - t * 0.3), loop_c.y() + math.sin(th) * rad * 0.7)
            pos = _lerp(start, pos, min(1.0, t * 4))
            ang = math.degrees(th) + 90
        else:
            t = (fly - 0.7) / 0.3
            prev = QPointF(loop_c.x() + math.cos(math.pi * 2.8) * rad * 0.7, loop_c.y() + math.sin(math.pi * 2.8) * rad * 0.7)
            pos = _lerp(prev, hole, _e3(t))
            ang = math.degrees(math.atan2(hole.y() - prev.y(), hole.x() - prev.x()))
        rnd = random.Random(3)
        for j in range(14):                                   # the dotted trail
            q = (fly - j * 0.03)
            if q <= 0:
                break
            _a_dot(p, QPointF(pos.x() - math.cos(math.radians(ang)) * j * S(7) + rnd.uniform(-1, 1),
                              pos.y() - math.sin(math.radians(ang)) * j * S(7)), S(1.4), b, b, fin, 0.6 * (1 - j / 14))
        sz = S(26) * (1 - 0.35 * fly) * (0.4 + 0.6 * shrink)
        plane = QPolygonF([QPointF(sz, 0), QPointF(-sz * 0.8, -sz * 0.55), QPointF(-sz * 0.45, 0), QPointF(-sz * 0.8, sz * 0.55)])
        op = 1.0 - max(0.0, (k - 0.86) / 0.08)
        if op > 0:
            p.save()
            p.translate(pos)
            p.rotate(ang)
            g = QLinearGradient(QPointF(-sz, -sz), QPointF(sz, sz))
            g.setColorAt(0, mix(a, QColor("#FFFFFF"), 0.45))
            g.setColorAt(1, a)
            p.setOpacity(op)
            p.setPen(QPen(alpha(b, 0.9), S(1)))
            p.setBrush(g)
            p.drawPolygon(plane)
            p.setPen(QPen(alpha("#000000", 0.25), S(1)))
            p.drawLine(QPointF(-sz * 0.45, 0), QPointF(sz, 0))
            p.setOpacity(1.0)
            p.restore()
    if k > 0.84:                                              # it opens into the ball
        e = _e3((k - 0.84) / 0.16)
        for i in range(8):
            ang = i * math.tau / 8
            _a_dot(p, QPointF(hole.x() + math.cos(ang) * d * (0.4 + 0.9 * e), hole.y() + math.sin(ang) * d * (0.4 + 0.9 * e)),
                   S(2), a, b, fin, 1 - e, i % 2 == 0)
        ball(hole, d * (0.5 + 0.5 * e + 0.1 * math.sin(e * math.pi)), min(1.0, e * 2.5))


# ---- 10. Pixel Dust (9.5, Epic): the window comes apart into pixels from the bottom up; they drift up and pack
# into the ball
def _anim_pixel(p, k, now, m, hole, d, fin, banner, ball) -> None:
    a, b, core = anim_cols("pixel", fin, now)
    eat = _e3(k / 0.55)                                       # how much of the window has turned into pixels
    line = m.bottom() - m.height() * eat
    if eat < 0.999:
        p.save()
        p.setClipRect(QRectF(m.left(), m.top(), m.width(), line - m.top()), Qt.ClipOperation.IntersectClip)
        banner(m, 1.0)
        p.restore()
        p.setPen(Qt.PenStyle.NoPen)                            # the edge being eaten glows
        g = QLinearGradient(QPointF(0, line - S(14)), QPointF(0, line))
        g.setColorAt(0, alpha(b, 0.0))
        g.setColorAt(1, alpha(b, 0.7))
        p.setBrush(g)
        p.drawRect(QRectF(m.left(), line - S(14), m.width(), S(14)))
    cell = max(S(6), min(m.width(), m.height()) / 26)
    rnd = random.Random(11)
    n = 150
    for i in range(n):
        x0 = m.left() + rnd.random() * m.width()
        y0 = m.bottom() - rnd.random() * m.height()
        born = (m.bottom() - y0) / max(1.0, m.height()) * 0.55   # it leaves when the line passes it
        t = (k - born) / max(0.05, 0.9 - born)
        if t <= 0:
            continue
        t = min(1.0, t)
        e = _e3(t)
        wob = math.sin(now * 3 + i) * S(10) * (1 - e)
        pos = QPointF(x0 + (hole.x() - x0) * e + wob, y0 + (hole.y() - y0) * (e ** 0.8))
        sz = cell * (1 - 0.7 * e)
        col = anim_cols("pixel", fin, now, i)[i % 2] if fin else (a if i % 3 else b)
        op = min(1.0, t * 5) * (1 - max(0.0, (k - 0.86) / 0.1))
        if op <= 0:
            continue
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha(col, 0.9 * op))
        p.drawRect(QRectF(pos.x() - sz / 2, pos.y() - sz / 2, sz, sz))
    if k > 0.55:
        e = _e3((k - 0.55) / 0.45)
        _a_glow(p, hole, d * (0.6 + 0.9 * e), a, 0.45 * e * (1 - max(0.0, e - 0.8) * 5), fin)
        op = min(1.0, max(0.0, (k - 0.78) / 0.14))
        if op > 0:
            ball(hole, d * (0.6 + 0.4 * _e3((k - 0.78) / 0.22)), op)


# ---- 11. Ripple (9.5, Epic): the window ripples like water, pulls together into one drop, the drop falls UP into
# the hole and the ball comes out of the splash
def _anim_ripple(p, k, now, m, hole, d, fin, banner, ball) -> None:
    a, b, core = anim_cols("ripple", fin, now)
    c = m.center()
    wave = _e3(k / 0.3)
    pinch = _e3((k - 0.18) / 0.32)
    rise = _e3((k - 0.48) / 0.26)
    if pinch < 0.999:
        n = 22
        sh = m.height() / n
        for i in range(n):
            strip = QRectF(m.left() - S(40), m.top() + i * sh, m.width() + S(80), sh + 1)
            off = math.sin(now * 9 + i * 0.7) * S(14) * wave * (1 - pinch)
            sx = 1 - pinch * (0.97 - 0.5 * math.sin(i / (n - 1) * math.pi) * (1 - pinch))
            p.save()
            p.setClipRect(strip, Qt.ClipOperation.IntersectClip)
            p.translate(c.x() + off, 0)
            p.scale(max(0.02, sx), 1.0)
            p.translate(-c.x(), 0)
            banner(m, 1.0 - 0.3 * pinch)
            _tint_fin(p, m, fin, a, _fin_tint(fin) * wave)
            p.restore()
        for j in range(3):                                    # rings on the surface
            q = (wave * 1.2 - j * 0.25)
            if q > 0:
                _a_ring(p, c, min(m.width(), m.height()) * 0.5 * q, b, 0.6 * (1 - min(1.0, q)), S(2))
    if pinch > 0.6 and rise < 1.0:                            # the drop
        drop_c = _lerp(c, hole, rise ** 1.6)
        r = d * (1.6 - 0.9 * rise) * min(1.0, (pinch - 0.6) / 0.3)
        tail = r * (1.2 + 2.5 * rise * (1 - rise) * 4)
        path = QPainterPath()
        path.moveTo(drop_c.x(), drop_c.y() + r + tail)          # the tail points away from where it goes
        path.cubicTo(QPointF(drop_c.x() + r * 1.1, drop_c.y() + r), QPointF(drop_c.x() + r, drop_c.y() - r),
                     QPointF(drop_c.x(), drop_c.y() - r))
        path.cubicTo(QPointF(drop_c.x() - r, drop_c.y() - r), QPointF(drop_c.x() - r * 1.1, drop_c.y() + r),
                     QPointF(drop_c.x(), drop_c.y() + r + tail))
        g = QRadialGradient(QPointF(drop_c.x() - r * 0.3, drop_c.y() - r * 0.3), r * 1.6)
        g.setColorAt(0, mix(core, b, 0.3))
        g.setColorAt(0.5, b)
        g.setColorAt(1, a)
        p.setPen(QPen(alpha(core, 0.6), S(1)))
        p.setBrush(g)
        p.drawPath(path)
    if k > 0.72:                                              # the splash
        e = _e3((k - 0.72) / 0.28)
        for j in range(2):
            _a_ring(p, hole, d * (0.6 + (2.6 - j) * e), b if j else a, 0.8 * (1 - e), S(2.4 - j))
        rnd = random.Random(2)
        for i in range(16):
            ang = rnd.uniform(-math.pi, 0)
            r = d * (0.6 + 1.8 * e)
            pt = QPointF(hole.x() + math.cos(ang) * r, hole.y() + math.sin(ang) * r * 0.7 + e * e * S(16))
            _a_dot(p, pt, S(rnd.uniform(1.0, 2.2)), b, b, fin, 1 - e, i % 4 == 0)
        ball(hole, d * (0.55 + 0.45 * e + 0.12 * math.sin(e * math.pi)), min(1.0, e * 3))


_ANIM_PAINT = {"nova": _anim_nova, "shatter": _anim_shatter, "rift": _anim_rift, "phoenix": _anim_phoenix,
               "eclipse": _anim_eclipse, "blackhole": _anim_blackhole, "warp": _anim_warp, "glitch": _anim_glitch,
               "origami": _anim_origami, "pixel": _anim_pixel, "ripple": _anim_ripple}


def paint_anim(p: QPainter, design: str, fin: str, k: float, now: float, m: QRectF, hole: QPointF, d: float, banner, ball) -> None:
    """k 0 = the banner is showing, 1 = only the ball is. banner(box, opacity, light) and ball(centre, size, opacity)
    draw the two pictures."""
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setPen(Qt.PenStyle.NoPen)
    try:
        _ANIM_PAINT[design](p, max(0.0, min(1.0, k)), now, m, hole, d, fin, banner, ball)
    finally:
        p.restore()


def paint_anim_thumb(p: QPainter, item: str, box: QRectF, now: float) -> None:
    """The small picture of an animation (shop, inventory, cases, market): a glowing ball in its colours."""
    sp = anim_split(item) or ("nova", "")
    design, fin = sp
    a, b, core = anim_cols(design, fin, now)
    c = box.center()
    r = box.width() * 0.5
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    pulse = 0.5 + 0.5 * math.sin(now * 2.4)
    _a_glow(p, c, r * (0.95 + 0.08 * pulse), a if fin != "blacktitan" else b, 0.55, fin)
    p.setPen(Qt.PenStyle.NoPen)
    g = QRadialGradient(QPointF(c.x() - r * 0.12, c.y() - r * 0.15), r * 0.55)
    g.setColorAt(0, core)
    g.setColorAt(0.5, b if fin != "blacktitan" else a)
    g.setColorAt(1, a)
    p.setBrush(g)
    p.drawEllipse(c, r * 0.36, r * 0.36)
    if fin == "blacktitan":
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(alpha(b, 0.9), max(1.0, r * 0.05)))
        p.drawEllipse(c, r * 0.36, r * 0.36)
    p.setPen(QPen(alpha(b, 0.7), max(1.0, r * 0.04)))
    p.setBrush(Qt.BrushStyle.NoBrush)
    if design == "nova":
        p.drawEllipse(c, r * (0.55 + 0.15 * pulse), r * (0.55 + 0.15 * pulse))
    elif design == "shatter":
        for i in range(6):
            ang = i * math.pi / 3 + 0.3
            p.drawLine(QPointF(c.x() + math.cos(ang) * r * 0.5, c.y() + math.sin(ang) * r * 0.5),
                       QPointF(c.x() + math.cos(ang + 0.3) * r * 0.82, c.y() + math.sin(ang + 0.3) * r * 0.82))
    elif design == "rift":
        p.drawLine(QPointF(c.x(), c.y() - r * 0.85), QPointF(c.x(), c.y() + r * 0.85))
    elif design == "blackhole":                                   # 9.5: a dark core in a tilted disk
        p.save()
        p.translate(c)
        p.rotate(-18)
        p.drawEllipse(QPointF(0, 0), r * 0.78, r * 0.26)
        p.restore()
        p.setBrush(QColor("#030306"))
        p.drawEllipse(c, r * 0.24, r * 0.24)
        p.setBrush(Qt.BrushStyle.NoBrush)
    elif design == "warp":
        for i in range(10):
            ang = i * math.tau / 10 + 0.2
            r0 = r * (0.45 + 0.1 * ((now * 1.5 + i * 0.3) % 1.0))
            p.drawLine(QPointF(c.x() + math.cos(ang) * r0, c.y() + math.sin(ang) * r0),
                       QPointF(c.x() + math.cos(ang) * r0 * 1.7, c.y() + math.sin(ang) * r0 * 1.7))
    elif design == "glitch":
        step = int(now * 8)
        rnd = random.Random(step)
        p.setPen(Qt.PenStyle.NoPen)
        for i in range(4):
            y = c.y() - r * 0.6 + i * r * 0.3
            p.setBrush(alpha(a if i % 2 else b, 0.7))
            p.drawRect(QRectF(c.x() - r * 0.7 + rnd.uniform(-1, 1) * r * 0.2, y, r * 1.4, r * 0.08))
    elif design == "origami":
        sz = r * 0.75
        p.drawPolygon(QPolygonF([QPointF(c.x() + sz, c.y()), QPointF(c.x() - sz * 0.8, c.y() - sz * 0.55),
                                 QPointF(c.x() - sz * 0.45, c.y()), QPointF(c.x() - sz * 0.8, c.y() + sz * 0.55)]))
    elif design == "pixel":
        p.setPen(Qt.PenStyle.NoPen)
        for i in range(8):
            ang = i * math.tau / 8 + now * 0.6
            q = QPointF(c.x() + math.cos(ang) * r * 0.62, c.y() + math.sin(ang) * r * 0.62)
            p.setBrush(alpha(b if i % 2 else a, 0.85))
            p.drawRect(QRectF(q.x() - r * 0.07, q.y() - r * 0.07, r * 0.14, r * 0.14))
    elif design == "ripple":
        for j in range(2):
            q = (now * 0.6 + j * 0.5) % 1.0
            p.setPen(QPen(alpha(b, 0.7 * (1 - q)), max(1.0, r * 0.04)))
            p.drawEllipse(c, r * (0.45 + 0.45 * q), r * (0.45 + 0.45 * q))
    elif design == "eclipse":
        p.setBrush(QColor("#08060C"))
        p.drawEllipse(QPointF(c.x() + r * 0.12, c.y() - r * 0.06), r * 0.34, r * 0.34)
        p.setBrush(Qt.BrushStyle.NoBrush)
        for i in range(12):
            ang = i * math.tau / 12 + now * 0.3
            p.drawLine(QPointF(c.x() + math.cos(ang) * r * 0.48, c.y() + math.sin(ang) * r * 0.48),
                       QPointF(c.x() + math.cos(ang) * r * (0.62 + 0.1 * pulse), c.y() + math.sin(ang) * r * (0.62 + 0.1 * pulse)))
    else:
        for side in (-1, 1):
            p.drawArc(QRectF(c.x() + (0 if side > 0 else -r * 0.9), c.y() - r * 0.5, r * 0.9, r * 0.9), 16 * (20 if side > 0 else 110), 16 * 50)
    p.restore()


_NAMES = {"ball": dict(BALLS), "line": dict(LINES), "font": {f[0]: f[1] for f in FONTS},
          "theme": {t[0]: t[1] for t in THEME_LOOKS}, "banner": dict(BANNERS), "frame": dict(FRAMES), "tag": dict(TAGS)}
ANIM_DESIGNS = [(d + ("-" + f if f else ""), (tn + " " + n if f else n)) for d, n in ANIMS for f, tn in ANIM_FINS]
_NAMES["anim"] = dict(ANIM_DESIGNS)
_themes: dict = {}


def parts(item: str) -> tuple:
    bits = (item or "").split(":") + ["", "", ""]
    return bits[0], bits[1], bits[2]


def colour_of(item: str) -> QColor:
    return QColor(SHOP_COLOURS.get(parts(item)[2], "#FFFFFF"))


def item_name(item: str) -> str:
    """"Orbit ball · Blue", "Ocean theme"... (badges are named in collection.py)."""
    kind, base, var = parts(item)
    if kind == "badge":
        pass
        return badge_label(item)
    if kind == "tag":
        return tr("{name} tag", name=_NAMES["tag"].get(base, base.upper()))
    name = f"{tr(_NAMES.get(kind, {}).get(base, base.capitalize()))} ({tr(KIND_NAMES.get(kind, kind)).lower()})"
    return name + (f" · {tr(COLOUR_NAMES.get(var, var))}" if var else "")


def shop_theme(ident: str):
    """The theme dict (same shape as extras.THEMES) of a shop theme, e.g. "theme:ocean"."""
    if not _themes:
        pass
        for tid, name, c1, c2, sky in THEME_LOOKS:
            th = _theme("theme:" + tid, name, 0, glow=1, sparkles=sky.get("sparkles", 0) // 2,
                        halo=1.0 + 0.1 * sky.get("glow", 2), edge=sky.get("edge", ""))
            th["tint"] = (c1, c2)
            th["scene"] = tid                              # 3.1: its own picture instead of the night sky
            _themes["theme:" + tid] = th
    return _themes.get(ident)


def font_families(item: str) -> list:
    base = parts(item)[1]
    return next((list(f[2]) for f in FONTS if f[0] == base), [])


# --------------------------------------------------------------------------- #
# Balls: the R in the item's colour, with a design around it
# --------------------------------------------------------------------------- #
def _r_text(p: QPainter, box: QRectF, d: float, col: QColor, dark: bool) -> None:
    f = font(20, QFont.Weight.ExtraBold)
    f.setPixelSize(max(8, int(d * 0.46)))
    p.setFont(f)
    centre = int(Qt.AlignmentFlag.AlignCenter)
    p.setPen(alpha("#FFFFFF" if dark else col, 0.45))
    p.drawText(box.translated(0, d * 0.022), centre, "R")
    p.setPen(col if not dark else QColor("#C9D2DA"))
    p.drawText(box, centre, "R")


def paint_shop_ball(p: QPainter, box: QRectF, d: float, item: str, now: float = 0.0) -> None:
    _k, design, var = parts(item)
    col = colour_of(item)
    dark = var == "black"
    line = QColor("#AEB8C2") if dark else col
    c = box.center()
    r = d / 2
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setBrush(Qt.BrushStyle.NoBrush)
    if design == "orbit":
        p.setPen(QPen(alpha(line, 0.45), max(1.0, d * 0.02)))
        p.save()
        p.translate(c)
        p.rotate(-24)
        p.drawEllipse(QPointF(0, 0), r * 0.74, r * 0.34)
        ang = now * 1.6
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(line)
        p.drawEllipse(QPointF(r * 0.74 * math.cos(ang), r * 0.34 * math.sin(ang)), d * 0.045, d * 0.045)
        p.restore()
    elif design == "pixel":
        p.setPen(Qt.PenStyle.NoPen)
        s = d * 0.075
        for k, (dx, dy) in enumerate(((-1, -1), (1, -1), (-1, 1), (1, 1), (-1.45, 0), (1.45, 0))):
            p.setBrush(alpha(line, 0.85 if k < 4 else 0.45))
            p.drawRect(QRectF(c.x() + dx * r * 0.5 - s / 2, c.y() + dy * r * 0.5 - s / 2, s, s))
    elif design == "halo":
        p.setPen(QPen(line, max(1.4, d * 0.04), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawArc(QRectF(c.x() - r * 0.5, c.y() - r * 0.82, r, r * 0.36), 0, 180 * 16)
        p.setPen(QPen(alpha(line, 0.35), max(1.0, d * 0.02)))
        p.drawArc(QRectF(c.x() - r * 0.5, c.y() - r * 0.82, r, r * 0.36), 180 * 16, 180 * 16)
    elif design == "bubble":
        for k, (dx, dy, rr) in enumerate(((-0.52, 0.44, 0.15), (0.56, -0.38, 0.19), (0.5, 0.5, 0.09), (-0.5, -0.5, 0.08))):
            bob = math.sin(now * 1.3 + k * 1.7) * d * 0.015
            p.setPen(QPen(alpha(line, 0.75), max(1.0, d * 0.018)))
            p.setBrush(alpha(line, 0.16))
            p.drawEllipse(QPointF(c.x() + dx * r, c.y() + dy * r + bob), rr * r, rr * r)
    elif design == "spiral":
        path = QPainterPath()
        for n in range(64):
            t = n / 63
            ang = t * 4.2 * math.pi + now * 0.5
            pt = QPointF(c.x() + r * 0.8 * t * math.cos(ang), c.y() + r * 0.8 * t * math.sin(ang))
            path.lineTo(pt) if n else path.moveTo(pt)
        p.setPen(QPen(alpha(line, 0.42), max(1.0, d * 0.022), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawPath(path)
    elif design == "bullseye":
        for k, rr in enumerate((0.78, 0.6)):
            p.setPen(QPen(alpha(line, 0.6 - 0.25 * k), max(1.0, d * (0.03 - 0.008 * k))))
            p.drawEllipse(c, r * rr, r * rr)
    elif design == "hex":
        path = QPainterPath()
        for n in range(7):
            ang = math.radians(60 * n + now * 6)
            pt = QPointF(c.x() + r * 0.78 * math.cos(ang), c.y() + r * 0.78 * math.sin(ang))
            path.lineTo(pt) if n else path.moveTo(pt)
        p.setPen(QPen(alpha(line, 0.7), max(1.2, d * 0.03), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                      Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
    elif design == "ripple":
        for k in range(3):
            t = (now * 0.35 + k / 3) % 1.0
            p.setPen(QPen(alpha(line, 0.7 * (1 - t)), max(1.0, d * 0.024)))
            p.drawEllipse(c, r * (0.3 + 0.55 * t), r * (0.3 + 0.55 * t))
    elif design == "shard":
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(6):
            ang = math.radians(60 * k + 15)
            tip = QPointF(c.x() + r * 0.86 * math.cos(ang), c.y() + r * 0.86 * math.sin(ang))
            a1, a2 = ang - 0.2, ang + 0.2
            tri = QPainterPath()
            tri.moveTo(tip)
            tri.lineTo(c.x() + r * 0.6 * math.cos(a1), c.y() + r * 0.6 * math.sin(a1))
            tri.lineTo(c.x() + r * 0.6 * math.cos(a2), c.y() + r * 0.6 * math.sin(a2))
            tri.closeSubpath()
            p.setBrush(alpha(line, 0.85 if k % 2 == 0 else 0.4))
            p.drawPath(tri)
    elif design == "petal":                              # 3.2 Common: four soft petals
        p.setPen(Qt.PenStyle.NoPen)
        for k in range(4):
            ang = math.radians(45 + 90 * k)
            p.setBrush(alpha(line, 0.42))
            p.save()
            p.translate(c.x() + r * 0.62 * math.cos(ang), c.y() + r * 0.62 * math.sin(ang))
            p.rotate(45 + 90 * k)
            p.drawEllipse(QPointF(0, 0), r * 0.2, r * 0.11)
            p.restore()
    elif design == "gear":                               # 3.2 Rare: a turning cog, teeth and a hub ring
        teeth, outer, inner = 10, r * 0.86, r * 0.72
        path = QPainterPath()
        spin = now * 18
        for k in range(teeth * 4 + 1):
            ang = math.radians(spin + k * 360 / (teeth * 4))
            rr = outer if (k % 4) in (1, 2) else inner
            pt = QPointF(c.x() + rr * math.cos(ang), c.y() + rr * math.sin(ang))
            path.lineTo(pt) if k else path.moveTo(pt)
        p.setPen(QPen(alpha(line, 0.75), max(1.0, d * 0.022), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap,
                      Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
        p.setPen(QPen(alpha(line, 0.3), max(1.0, d * 0.015)))
        p.drawEllipse(c, r * 0.6, r * 0.6)
    elif design == "planet":                             # 3.2 Epic: a tilted ring, a moon and two little stars
        p.save()
        p.translate(c)
        p.rotate(-18)
        p.setPen(QPen(alpha(line, 0.35), max(1.0, d * 0.05)))
        p.drawArc(QRectF(-r * 0.92, -r * 0.3, r * 1.84, r * 0.6), 0, -180 * 16)      # back half, faint
        p.setPen(QPen(alpha(line, 0.85), max(1.0, d * 0.032)))
        p.drawArc(QRectF(-r * 0.92, -r * 0.3, r * 1.84, r * 0.6), 0, 180 * 16)
        p.restore()
        ang = now * 0.9
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(mix(line, QColor("#FFFFFF"), 0.35))
        p.drawEllipse(QPointF(c.x() + r * 0.8 * math.cos(ang), c.y() + r * 0.8 * math.sin(ang) * 0.9), d * 0.05, d * 0.05)
        for k, (sx, sy) in enumerate(((-0.62, -0.6), (0.66, 0.55))):
            tw = 0.5 + 0.5 * math.sin(now * 3 + k * 2)
            p.setBrush(alpha("#FFFFFF", 0.4 + 0.5 * tw))
            p.drawEllipse(QPointF(c.x() + sx * r, c.y() + sy * r), d * 0.018, d * 0.018)
    elif design == "eclipse":                            # 4.5: a dark moon over a burning ring of light
        turn = now * 0.5
        for k, (w_, a) in enumerate(((0.16, 0.12), (0.09, 0.3), (0.04, 0.9))):
            g = QConicalGradient(c, math.degrees(turn) + k * 40)
            g.setColorAt(0.0, alpha(line, a))
            g.setColorAt(0.5, alpha(mix(line, QColor("#FFFFFF"), 0.6), a))
            g.setColorAt(1.0, alpha(line, a))
            p.setPen(QPen(g, d * w_))
            p.drawEllipse(c, r * 0.66, r * 0.66)
        p.setPen(Qt.PenStyle.NoPen)
        moon = QPointF(c.x() + r * 0.06 * math.cos(turn * 0.7), c.y() + r * 0.06 * math.sin(turn * 0.7))
        p.setBrush(QColor("#07080B"))
        p.drawEllipse(moon, r * 0.62, r * 0.62)
        p.setBrush(alpha("#FFFFFF", 0.85))
        bead = QPointF(c.x() + r * 0.66 * math.cos(turn * 2.2), c.y() + r * 0.66 * math.sin(turn * 2.2))
        p.drawEllipse(bead, d * 0.03, d * 0.03)
    elif design in ("nova", "snowglobe"):              # 3.2 Legendary: a burst of rays and orbiting sparks
        if design == "snowglobe":                         # limited: a glass globe with falling snow
            p.setPen(QPen(alpha("#DDF3FF", 0.65), max(1.0, d * 0.025)))
            p.setBrush(alpha("#9FE3FF", 0.10))
            p.drawEllipse(c, r * 0.84, r * 0.84)
            p.setPen(Qt.PenStyle.NoPen)
            for k in range(12):
                fx = math.sin(k * 7.3) * 0.6
                fy = ((now * 0.12 + k / 12) % 1.0) * 1.4 - 0.7
                if fx * fx + fy * fy < 0.55:
                    p.setBrush(alpha("#FFFFFF", 0.85))
                    p.drawEllipse(QPointF(c.x() + fx * r, c.y() + fy * r), d * 0.016, d * 0.016)
            p.setBrush(alpha("#C8283D", 0.85))
            p.drawRoundedRect(QRectF(c.x() - r * 0.5, c.y() + r * 0.72, r, r * 0.18), r * 0.06, r * 0.06)
        else:
            p.setPen(Qt.PenStyle.NoPen)
            for k in range(12):
                ang = math.radians(k * 30 + now * 20)
                long_ = 0.9 if k % 2 == 0 else 0.7
                ray = QPainterPath()
                ray.moveTo(c.x() + r * 0.56 * math.cos(ang - 0.08), c.y() + r * 0.56 * math.sin(ang - 0.08))
                ray.lineTo(c.x() + r * long_ * math.cos(ang), c.y() + r * long_ * math.sin(ang))
                ray.lineTo(c.x() + r * 0.56 * math.cos(ang + 0.08), c.y() + r * 0.56 * math.sin(ang + 0.08))
                ray.closeSubpath()
                p.setBrush(alpha(line, 0.75 if k % 2 == 0 else 0.4))
                p.drawPath(ray)
            for k in range(3):
                ang = now * (1.4 + k * 0.5) + k * 2.1
                p.setBrush(mix(line, QColor("#FFFFFF"), 0.6))
                p.drawEllipse(QPointF(c.x() + r * 0.92 * math.cos(ang), c.y() + r * 0.92 * math.sin(ang)), d * 0.025, d * 0.025)
            glow = QRadialGradient(c, r * 0.62)
            glow.setColorAt(0, alpha(line, 0.25))
            glow.setColorAt(1, alpha(line, 0.0))
            p.setBrush(glow)
            p.drawEllipse(c, r * 0.62, r * 0.62)
    if design == "split":                                # the R in two halves: colour above, white below
        for top in (True, False):
            p.save()
            p.setClipRect(QRectF(box.left(), box.top() if top else c.y(), box.width(), box.height() / 2))
            _r_text(p, box, d, col if top else QColor(TEXT), dark and top)
            p.restore()
        p.setPen(QPen(alpha(line, 0.5), max(1.0, d * 0.016)))
        p.drawLine(QPointF(c.x() - r * 0.7, c.y()), QPointF(c.x() + r * 0.7, c.y()))
    else:
        _r_text(p, box, d, col, dark)
    p.restore()


# --------------------------------------------------------------------------- #
# Lines: the song-progress ring of the ball
# --------------------------------------------------------------------------- #
def _arc_points(ring: QRectF, frac: float, step_deg: float, wobble=None) -> list:
    c, r = ring.center(), ring.width() / 2
    n = max(2, int(360 * frac / step_deg) + 1)
    out = []
    for i in range(n):
        deg = min(360 * frac, i * step_deg)
        ang = math.radians(90 - deg)
        rr = r + (wobble(i) if wobble else 0.0)
        out.append(QPointF(c.x() + rr * math.cos(ang), c.y() - rr * math.sin(ang)))
    return out


def paint_shop_ring(p: QPainter, ring: QRectF, item: str, frac: float, width: float, now: float = 0.0) -> None:
    _k, design, var = parts(item)
    col = QColor("#8C96A0") if var == "black" else colour_of(item)
    frac = max(0.0, min(1.0, frac))
    span = int(-360 * 16 * frac)
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.setPen(QPen(alpha("#FFFFFF", 0.10), width))
    p.drawEllipse(ring)
    if frac <= 0.0:
        return p.restore()
    round_pen = lambda c, w: QPen(c, w, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap)      # noqa: E731
    if design in ("dash", "chain", "steps"):
        pen = QPen(col, width * (1.5 if design == "steps" else 1.0), Qt.PenStyle.CustomDashLine, Qt.PenCapStyle.FlatCap)
        pen.setDashPattern({"dash": [3.0, 2.0], "chain": [4.0, 1.4, 1.0, 1.4], "steps": [1.6, 1.0]}[design])
        p.setPen(pen)
        p.drawArc(ring, 90 * 16, span)
    elif design == "beads":
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(col)
        for pt in _arc_points(ring, frac, 14):
            p.drawEllipse(pt, width * 0.8, width * 0.8)
    elif design == "zigzag":
        pts = _arc_points(ring, frac, 7, lambda i: width * (0.9 if i % 2 else -0.9))
        path = QPainterPath(pts[0])
        for pt in pts[1:]:
            path.lineTo(pt)
        p.setPen(QPen(col, width * 0.7, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
    elif design == "twin":
        for grow in (-width * 0.9, width * 0.9):
            p.setPen(round_pen(col, width * 0.5))
            p.drawArc(ring.adjusted(grow, grow, -grow, -grow), 90 * 16, span)
    elif design == "pulse":
        p.setPen(round_pen(alpha(col, 0.55), width * 0.6))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(Qt.PenStyle.NoPen)
        for i, pt in enumerate(_arc_points(ring, frac, 24)):
            beat = 0.6 + 0.4 * math.sin(now * 4 - i * 0.8)
            p.setBrush(col)
            p.drawEllipse(pt, width * beat, width * beat)
    elif design == "ribbon":
        p.setPen(QPen(alpha(col, 0.3), width * 2.2, Qt.PenStyle.SolidLine, Qt.PenCapStyle.FlatCap))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(round_pen(col, width * 0.6))
        p.drawArc(ring, 90 * 16, span)
    elif design == "laser":
        p.setPen(QPen(alpha(col, 0.28), width * 2.6, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(round_pen(col, width))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(round_pen(mix(col, QColor("#FFFFFF"), 0.8), width * 0.35))
        p.drawArc(ring, 90 * 16, span)
    elif design == "wave":                                   # 3.2 Common: a soft wave
        pts = _arc_points(ring, frac, 3, lambda i: width * 0.8 * math.sin(i * 0.9 + now * 3))
        path = QPainterPath(pts[0])
        for pt in pts[1:]:
            path.lineTo(pt)
        p.setPen(QPen(col, width * 0.65, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
    elif design == "stars":                                  # 3.2 Rare: a faint line dotted with little stars
        p.setPen(round_pen(alpha(col, 0.35), width * 0.45))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(Qt.PenStyle.NoPen)
        for i, pt in enumerate(_arc_points(ring, frac, 20)):
            tw = 0.7 + 0.3 * math.sin(now * 3 + i)
            star = QPainterPath()
            size = width * 1.3 * tw
            for k in range(10):
                ang = math.radians(-90 + 36 * k)
                rr = size if k % 2 == 0 else size * 0.42
                q = QPointF(pt.x() + rr * math.cos(ang), pt.y() + rr * math.sin(ang))
                star.lineTo(q) if k else star.moveTo(q)
            star.closeSubpath()
            p.setBrush(col)
            p.drawPath(star)
    elif design == "helix":                                  # 3.2 Epic: two strands twisting round each other
        for phase, a in ((0.0, 1.0), (math.pi, 0.55)):
            pts = _arc_points(ring, frac, 3, lambda i, ph=phase: width * 1.1 * math.sin(i * 0.35 + ph + now * 2))
            path = QPainterPath(pts[0])
            for pt in pts[1:]:
                path.lineTo(pt)
            p.setPen(QPen(alpha(col, a), width * 0.5, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(mix(col, QColor("#FFFFFF"), 0.5))
        for pt in _arc_points(ring, frac, 26):
            p.drawEllipse(pt, width * 0.35, width * 0.35)
    elif design == "lightning":                              # 3.2 Legendary: a crackling bolt with a glow
        rnd_k = int(now * 12)
        pts = _arc_points(ring, frac, 6, lambda i: width * 1.2 * math.sin(i * 2.7 + rnd_k * 1.3) * (0.4 + 0.6 * ((i * 37 + rnd_k) % 5) / 4))
        path = QPainterPath(pts[0])
        for pt in pts[1:]:
            path.lineTo(pt)
        p.setPen(QPen(alpha(col, 0.25), width * 2.6, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(path)
        p.setPen(QPen(col, width * 0.8, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
        p.drawPath(path)
        p.setPen(QPen(mix(col, QColor("#FFFFFF"), 0.85), width * 0.3))
        p.drawPath(path)
    elif design == "comet":                                  # 4.5: a fading tail behind a bright head
        pts = _arc_points(ring, frac, 3)
        n = len(pts)
        tail = max(2, min(n, 40))
        p.setPen(round_pen(alpha(col, 0.18), width * 0.7))
        p.drawArc(ring, 90 * 16, span)
        for i in range(n - tail, n - 1):
            k = (i - (n - tail)) / tail
            p.setPen(round_pen(alpha(mix(col, QColor("#FFFFFF"), k * 0.6), 0.15 + 0.85 * k), width * (0.6 + 0.9 * k)))
            p.drawLine(pts[i], pts[i + 1])
        head = pts[-1]
        p.setPen(Qt.PenStyle.NoPen)
        glow = QRadialGradient(head, width * 3.2)
        glow.setColorAt(0, alpha("#FFFFFF", 0.95))
        glow.setColorAt(0.35, alpha(col, 0.6))
        glow.setColorAt(1, alpha(col, 0.0))
        p.setBrush(glow)
        p.drawEllipse(head, width * 3.2, width * 3.2)
    elif design == "garland":                                # limited: a green garland with red and gold baubles
        p.setPen(round_pen(QColor("#1F7A4A"), width * 1.3))
        p.drawArc(ring, 90 * 16, span)
        p.setPen(Qt.PenStyle.NoPen)
        for i, pt in enumerate(_arc_points(ring, frac, 22)):
            glow_ = 0.75 + 0.25 * math.sin(now * 3 + i * 1.3)
            p.setBrush(QColor("#E8384F") if i % 2 == 0 else QColor("#E8C26A"))
            p.setOpacity(glow_)
            p.drawEllipse(pt, width * 0.75, width * 0.75)
        p.setOpacity(1.0)
    else:                                                    # spark: a line with a star at its head
        p.setPen(round_pen(col, width))
        p.drawArc(ring, 90 * 16, span)
        head = _arc_points(ring, frac, 360 * frac or 1)[-1]
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(mix(col, QColor("#FFFFFF"), 0.6))
        star = QPainterPath()
        size = width * (2.2 + 0.5 * math.sin(now * 5))
        for k in range(8):
            ang = math.radians(45 * k)
            rr = size if k % 2 == 0 else size * 0.3
            pt = QPointF(head.x() + rr * math.cos(ang), head.y() + rr * math.sin(ang))
            star.lineTo(pt) if k else star.moveTo(pt)
        star.closeSubpath()
        p.drawPath(star)
    p.restore()


# --------------------------------------------------------------------------- #
# A small picture of any item (shop, inventory, market, trades)
# --------------------------------------------------------------------------- #
def paint_cosmetic(p: QPainter, item: str, rect: QRectF, now: float = 0.0, effects: bool = True, dim: float = 1.0) -> None:
    kind, base, var = parts(item)
    if kind == "badge":
        pass
        return show_item(p, item, rect, now, effects, dim)
    if kind in ("banner", "frame", "tag"):
        return paint_look_icon(p, item, rect, now if effects else 0.0, dim)
    if kind == "anim":
        p.save()
        p.setOpacity(p.opacity() * dim)
        dd = min(rect.width(), rect.height())
        paint_anim_thumb(p, item, QRectF(rect.center().x() - dd / 2, rect.center().y() - dd / 2, dd, dd), now if effects else 0.6)
        p.restore()
        return
    d = min(rect.width(), rect.height())
    box = QRectF(rect.center().x() - d / 2, rect.center().y() - d / 2, d, d)
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    p.setOpacity(p.opacity() * dim)
    if kind == "ball":
        p.setPen(QPen(alpha("#FFFFFF", 0.12), 1))
        p.setBrush(QColor("#0B0E10"))
        p.drawEllipse(box)
        paint_shop_ball(p, box.translated(0, -d * 0.02), d, item, now if effects else 0.6)
    elif kind == "line":
        w = max(1.6, d * 0.07)
        paint_shop_ring(p, box.adjusted(w * 2.4, w * 2.4, -w * 2.4, -w * 2.4), item, 0.72, w, now if effects else 0.6)
    elif kind == "font":
        f = QFont()
        f.setFamilies(font_families(item) + ["Segoe UI", "Arial"])
        f.setPixelSize(max(8, int(d * 0.52)))
        f.setWeight(QFont.Weight.Bold)
        p.setFont(f)
        p.setPen(QColor("#AEB8C2") if var == "black" else colour_of(item))
        p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), "Aa")
    elif kind == "theme":
        look = next((t for t in THEME_LOOKS if t[0] == base), THEME_LOOKS[0])
        g = QLinearGradient(box.topLeft(), box.bottomRight())
        g.setColorAt(0.0, QColor(look[2]))
        g.setColorAt(1.0, QColor(look[3]))
        tile = box.adjusted(d * 0.08, d * 0.16, -d * 0.08, -d * 0.16)
        p.setPen(QPen(g, max(1.4, d * 0.06)))
        p.setBrush(QColor("#0B0E10"))
        p.drawRoundedRect(tile, d * 0.14, d * 0.14)
        p.setPen(Qt.PenStyle.NoPen)
        for k, (fx, fy, s) in enumerate(((0.3, 0.42, 0.05), (0.52, 0.6, 0.035), (0.7, 0.38, 0.045), (0.42, 0.68, 0.03))):
            p.setBrush(QColor(look[2 + k % 2]))
            tw = 0.7 + 0.3 * math.sin(now * 2 + k) if effects else 1.0
            p.drawEllipse(QPointF(box.left() + fx * d, box.top() + fy * d), s * d * tw, s * d * tw)
    p.restore()


