# Inventory
# --------------------------------------------------------------------------- #
class LedgerList(QWidget):
    """The last changes of your coins and keys."""

    def __init__(self, rows: list, width: int) -> None:
        super().__init__()
        self.rows = rows[:60]
        self.row_h = S(26)
        self.setFixedSize(width, max(S(26), int(self.row_h * len(self.rows))))
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        for i, row in enumerate(self.rows):
            r = QRectF(0, i * self.row_h, self.width(), self.row_h)
            if i % 2 == 0:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha("#FFFFFF", 0.03))
                p.drawRoundedRect(r.adjusted(0, 1, 0, -1), S(6), S(6))
            p.setPen(QColor(TEXT))
            p.setFont(font(11, QFont.Weight.DemiBold))
            p.drawText(r.adjusted(S(8), 0, -S(120), 0), int(Qt.AlignmentFlag.AlignVCenter),
                       tr(REASONS.get(row.get("reason", ""), row.get("reason", ""))))
            coins, keys = int(row.get("coins") or 0), int(row.get("keys") or 0)
            bits = []
            if coins:
                bits.append(("+" if coins > 0 else "−") + coins_text(abs(coins)))
            if keys:
                bits.append(("+" if keys > 0 else "−") + f"{abs(keys)} " + tr("key"))
            p.setPen(QColor("#5BE08A") if coins > 0 or (not coins and keys > 0) else QColor("#FF7A7A"))
            p.setFont(font(11, QFont.Weight.Bold))
            p.drawText(r.adjusted(0, 0, -S(8), 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                       "  ".join(bits))


class WalletRow(QWidget):
    """Your keys (they can be traded) and your cases waiting to be opened."""

    def __init__(self, page) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedHeight(S(40))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setToolTip(tr("Keys can be added to trades. Click to see your cases."))

    def mousePressEvent(self, e) -> None:
        e.accept()

    def mouseReleaseEvent(self, e) -> None:
        if self.rect().contains(e.position().toPoint()):
            sfx.play("pick")
            self.ctx.shop_tab, self.ctx.shop_case = 3, None
            self.ctx.reload_page()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        ec = self.ctx.econ
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        paint_surface(p, r, S(DS.R_MD), 0.04)          # 8.0: the shared surface
        half = r.width() / 2
        p.save()
        p.translate(r.left() + S(20), r.center().y())
        p.scale(S(14) / 20, S(14) / 20)
        draw_icon(p, "key", ui.accent)
        p.restore()
        p.setPen(QColor(TEXT))
        p.setFont(font(12, QFont.Weight.Bold))
        p.drawText(QRectF(r.left() + S(36), r.top(), half - S(40), r.height()), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("{n} keys", n=ec.keys))
        cases = sum(int(v or 0) for v in ec.stock.values())
        pass
        paint_case(p, QRectF(r.left() + half + S(8), r.top() + S(8), S(26), r.height() - S(16)), "standard")
        p.drawText(QRectF(r.left() + half + S(40), r.top(), half - S(44), r.height()), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("{n} cases to open", n=cases))


def build_inventory(page, lay) -> None:
    pass
    ctx, ec = page.ctx, page.ctx.econ
    if not ec.ready:
        return lay.addWidget(Label(tr("Connecting…") if ctx.online.logged_in() else tr("Log in to see your items"), 12, TEXT_DIM))
    raw = getattr(ctx, "inv_tab", 0)
    tab = 8 if raw == "levels" else int(raw or 0)
    ctx.inv_tab = tab
    picker = GamePicker([tr("All"), tr("Badges"), tr("Balls"), tr("Lines"), tr("Fonts"), tr("Themes"), tr("Profile"),
                         tr("Animations"), tr("Levels")], tab)

    def switch(i: int) -> None:
        ctx.inv_tab, ctx.inv_pick = i, ""
        ctx.reload_page()
    picker.changed.connect(switch)
    lay.addWidget(picker)
    lay.addWidget(WalletRow(page))                       # 3.2: keys and cases are yours too
    if tab == 8:                                         # 4.0: your level, badges and XP coupons
        pass
        return build_levels(page, lay)
    if tab == 7:                                         # 6.9: animations
        return build_animations(page, lay, False)
    if tab == 6:                                         # 6.9: the coin history moved here
        _inventory_items(page, lay, tab)
        return _coin_history(page, lay)
    return _inventory_items(page, lay, tab)


def _coin_history(page, lay) -> None:
    """6.9: the coin history lives at the end of the Profile tab."""
    ctx, ec = page.ctx, page.ctx.econ
    rows = getattr(ctx, "ledger_rows", None)
    if rows is None or time.monotonic() - getattr(ctx, "ledger_at", 0) > 8:
        ctx.ledger_at = time.monotonic()

        def got(ok: bool, data) -> None:
            if ok and isinstance(data, list) and data != getattr(ctx, "ledger_rows", None):
                ctx.ledger_rows = data
                if ctx.window.showing("themes") and getattr(ctx, "inv_tab", 0) == 6:
                    ctx.reload_page("themes")
        ec.online.ask("rb_ledger_list", {}, got)
    lay.addWidget(heading(tr("Coin history")))
    if rows:
        lay.addWidget(LedgerList(rows, page.W))
    else:
        lay.addWidget(Label(tr("Loading…") if rows is None else tr("Nothing here yet"), 12, TEXT_DIM))
    return


def _inventory_items(page, lay, tab: int) -> None:
    ctx, ec = page.ctx, page.ctx.econ
    want = ["", "badge", "ball", "line", "font", "theme", "look"][tab]
    groups: dict = {}
    for it in ec.items:
        k = it["item"].split(":")[0]
        if k == "coupon":                                 # XP coupons live in Levels
            continue
        if not want or k == want or (want == "look" and k in LOOKS and k != "anim"):
            groups.setdefault(it["item"], []).append(it)
    total = sum(value_of(ctx, k) * len(v) for k, v in groups.items())
    count = sum(len(v) for v in groups.values())
    lay.addWidget(Label(tr("{n} items · worth about {v} coins", n=count, v=coins_text(total)), 11, TEXT_DIM))
    if want == "look":                                   # 5.2: your titles first (grey until you are top 3)
        lay.addWidget(heading(tr("Titles")))
        lay.addWidget(TitleChips(ctx, page.W))
    lay.addWidget(sort_bar(ctx, lambda: ctx.reload_page()))        # 5.1: sort and filter
    order = sort_items(ctx, list(groups))
    extras = [i["id"] for k in order for i in [c for c in groups[k] if not c.get("locked")][1:]
              if ec.quick_value(k) > 0 and len(groups[k]) > 1]
    del extras                                           # 5.0: no more "quick sell the doubles"
    if not order:
        go = Button(tr("Open cases"), "primary", 32, icon="case")        # 8.0: a designed empty state with a way out

        def to_cases() -> None:
            ctx.shop_tab, ctx.shop_badge, ctx.shop_case, ctx.inv_pick = 2, None, None, ""
            ctx.reload_page()
        go.clicked.connect(to_cases)
        lay.addSpacing(S(4))
        lay.addWidget(notice("case", tr("Nothing here yet"),
                             tr("Open cases or visit the shop: everything you own shows up here."), page.W, go))
        return
    # 9.5: select several items and sell them together
    selecting = bool(getattr(ctx, "inv_select", False))
    sel = [k for k in (getattr(ctx, "inv_sel", None) or []) if k in groups]
    ctx.inv_sel = sel

    def sellable(k: str) -> list:
        return [c["id"] for c in groups[k] if not c.get("locked")] \
            if ec.info(k).get("tradeable") and ec.quick_value(k) > 0 and k != "tag:og" else []
    srow = hbox(spacing=8)
    if selecting:
        ids = [i for k in sel for i in sellable(k)]
        about = sum(ec.quick_value(k) * len(sellable(k)) for k in sel)
        key = tuple(sorted(ids))                        # the server's own quote (the local guess can be far off)
        q = getattr(ctx, "inv_quote", None)
        if isinstance(q, tuple) and q[0] == key:
            about = q[1]
        elif ids:
            def got_q(ok: bool, d, key_=key) -> None:
                if ok and isinstance(d, dict):
                    ctx.inv_quote = (key_, int(d.get("total") or 0))
                    if getattr(ctx, "inv_select", False):
                        ctx.reload_page()
            ec.quick_quote(ids, got_q)
        srow.addWidget(Label(tr("{n} selected · about {v} coins", n=len(ids), v=coins_text(about)) if sel else
                             tr("Click items to select them"), 11, TEXT if sel else TEXT_DIM, bold=bool(sel)), 1)
        allb = Button(tr("All"), "ghost", 30)
        allb.setToolTip(tr("Select everything you can sell on this tab"))
        allb.clicked.connect(lambda: (setattr(ctx, "inv_sel", [k for k in order if sellable(k)]), ctx.reload_page()))
        srow.addWidget(allb)
        sell_all = Button(tr("Sell all selected"), "primary", 30, icon="coin")
        sell_all.setEnabled(bool(ids))

        def go_sell() -> None:
            names = [item_name(k) for k in sel]
            what = names[0] if len(names) == 1 else tr("{n} items", n=len(ids))
            text = tr("Sell {n} items for about {v} coins? The pawn shop makes the final offer.", n=len(ids),
                      v=coins_text(about))
            ctx.window.confirm(text, lambda: (setattr(ctx, "inv_select", False), setattr(ctx, "inv_sel", []),
                                              quick_sell(ctx, ids, what)), yes=tr("Go to the pawn shop"))
        sell_all.clicked.connect(go_sell)
        srow.addWidget(sell_all)
        done_b = Button(tr("Done"), "ghost", 30)
        done_b.clicked.connect(lambda: (setattr(ctx, "inv_select", False), setattr(ctx, "inv_sel", []), ctx.reload_page()))
        srow.addWidget(done_b)
    else:
        srow.addStretch(1)
        selb = Button(tr("Select several"), "ghost", 30, icon="check")
        selb.clicked.connect(lambda: (setattr(ctx, "inv_select", True), setattr(ctx, "inv_pick", ""), ctx.reload_page()))
        srow.addWidget(selb)
    lay.addLayout(srow)
    pick = getattr(ctx, "inv_pick", "") or ""
    if pick not in groups or selecting:
        pick = ""
    if pick:
        _inventory_detail(page, lay, pick, groups[pick])
    wearing = set(worn(ctx))
    entries = []
    for k in order:
        free = [i for i in groups[k] if not i.get("locked")]
        on = k in wearing or ctx.shop_item_worn(k) or (k.split(":")[0] in LOOKS and look_worn(ctx, k))
        mark = "lock" if not free else ("worn" if on else "")
        if selecting:
            mark = "offered" if k in sel else ("lock" if not sellable(k) else "")
        entries.append({"item": k, "text": coins_text(value_of(ctx, k)) if value_of(ctx, k) else tr("Free"),
                        "tag": f"×{len(groups[k])}" if len(groups[k]) > 1 else "", "mark": mark,
                        "dim": 0.45 if selecting and not sellable(k) else 1.0})
    grid = ItemGrid(ctx, entries, page.W, 5, 72, order.index(pick) if pick else -1)

    def choose(i: int) -> None:
        sfx.play("pick")
        if selecting:
            k = order[i]
            if not sellable(k):
                return ctx.toast(tr("This one can't be sold"), "warn")
            ctx.inv_sel = [x for x in sel if x != k] if k in sel else sel + [k]
            return ctx.reload_page()
        ctx.inv_pick = "" if order[i] == pick else order[i]
        ctx.reload_page()
    grid.picked.connect(choose)
    lay.addWidget(grid)


# --------------------------------------------------------------------------- #
# 6.9: the Animations page (Shop and Inventory)
# --------------------------------------------------------------------------- #
class AnimPreview(QWidget):
    """A looping picture of one animation: the banner leaves, the ball waits, the banner comes back.
    9.2: it plays only while the mouse is over it (a faint PREVIEW until then), on a stage lit in its colours with
    drifting sparks and a light sweep."""

    def __init__(self, ctx, design: str, fin: str, width: int) -> None:
        super().__init__()
        self.ctx, self.design, self.fin = ctx, design, fin
        self.setFixedSize(width, S(136))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._t0 = time.monotonic()
        self._hover = Tween(self, on_change=self.update)
        self._on = False
        self._timer = QTimer(self)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self.update)
        rnd = random.Random(hash(design + fin) & 0xFFFF)
        self._sparks = [(rnd.random(), rnd.random(), rnd.uniform(0.6, 1.6), rnd.uniform(0, math.tau)) for _ in range(26)]

    def enterEvent(self, _e) -> None:
        self._on = True
        self._t0 = time.monotonic()
        self._hover.to(1.0, 220)
        self._timer.start()

    def leaveEvent(self, _e) -> None:
        self._on = False
        self._hover.to(0.0, 320)

    def hideEvent(self, _e) -> None:
        self._timer.stop()
        self._on = False

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        clip = QPainterPath()
        clip.addRoundedRect(r, S(12), S(12))
        now = time.monotonic()
        hv = self._hover.level
        if not self._on and hv < 0.01:
            self._timer.stop()
        try:
            ca, cb, _core = anim_cols(self.design, self.fin, now)
        except Exception:  # noqa: BLE001
            ca, cb = QColor(ui.accent), QColor("#FFFFFF")
        stage = QLinearGradient(r.topLeft(), r.bottomLeft())             # 9.2: a stage lit in the animation's colours
        stage.setColorAt(0, mix(QColor("#090B0E"), ca, 0.10 + 0.12 * hv))
        stage.setColorAt(1, QColor("#06070A"))
        p.setPen(QPen(alpha(ca, 0.18 + 0.45 * hv), 1))
        p.setBrush(stage)
        p.drawPath(clip)
        p.setClipPath(clip)
        p.setPen(Qt.PenStyle.NoPen)
        floor = QRadialGradient(QPointF(r.center().x(), r.bottom()), r.width() * 0.55)
        floor.setColorAt(0, alpha(ca, 0.22 + 0.2 * hv))
        floor.setColorAt(1, alpha(ca, 0.0))
        p.setBrush(floor)
        p.drawRect(r)
        for x, y, sp, ph in self._sparks:                                 # drifting sparks
            yy = (y - (now * 0.05 * sp if self._on else 0)) % 1.0
            a_ = (0.15 + 0.5 * hv) * (0.5 + 0.5 * math.sin(now * 2 * sp + ph))
            p.setBrush(alpha(cb if sp > 1.1 else ca, a_))
            rr = S(1.2) * sp
            p.drawEllipse(QPointF(r.left() + x * r.width(), r.top() + yy * r.height()), rr, rr)
        if hv > 0.01:                                                     # a light sweep while it plays
            sx = r.left() + ((now - self._t0) * 0.35 % 1.4 - 0.2) * r.width()
            sw = QLinearGradient(QPointF(sx - S(60), 0), QPointF(sx + S(60), 0))
            sw.setColorAt(0, alpha("#FFFFFF", 0.0))
            sw.setColorAt(0.5, alpha("#FFFFFF", 0.06 * hv))
            sw.setColorAt(1, alpha("#FFFFFF", 0.0))
            p.setBrush(sw)
            p.drawRect(r)
        t = (now - self._t0) % 4.8 if self._on else 0.0
        if t < 0.5:
            k = 0.0
        elif t < 1.9:
            k = (t - 0.5) / 1.4
        elif t < 2.8:
            k = 1.0
        elif t < 4.2:
            k = 1.0 - (t - 2.8) / 1.4
        else:
            k = 0.0
        m = QRectF(r.center().x() - r.width() * 0.3, r.center().y() - S(17) + S(10), r.width() * 0.6, S(34))
        hole = QPointF(r.center().x(), r.top() + S(24))
        d = S(26)
        acc = QColor(ui.accent)

        def banner(box: QRectF, op: float, light: bool = False) -> None:
            p.setOpacity(max(0.0, min(1.0, op)))
            g = QLinearGradient(box.topLeft(), box.bottomRight())
            g.setColorAt(0, mix(acc, QColor("#0B0E10"), 0.55))
            g.setColorAt(1, mix(acc, QColor("#0B0E10"), 0.8))
            p.setPen(QPen(alpha(acc, 0.8), 1))
            p.setBrush(g)
            p.drawRoundedRect(box, S(9), S(9))
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(max(7, 9 * box.height() / max(1.0, m.height())), QFont.Weight.Bold))
            p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), "Rubenium")
            p.setOpacity(1.0)

        def ball(pos: QPointF, size: float, op: float) -> None:
            p.setOpacity(max(0.0, min(1.0, op)))
            g = QRadialGradient(QPointF(pos.x() - size * 0.15, pos.y() - size * 0.2), size * 0.7)
            g.setColorAt(0, mix(acc, QColor("#FFFFFF"), 0.55))
            g.setColorAt(1, mix(acc, QColor("#000000"), 0.35))
            p.setPen(QPen(alpha("#FFFFFF", 0.35), 1))
            p.setBrush(g)
            p.drawEllipse(pos, size / 2, size / 2)
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(max(6, size * 0.34), QFont.Weight.ExtraBold))
            p.drawText(QRectF(pos.x() - size / 2, pos.y() - size / 2, size, size), int(Qt.AlignmentFlag.AlignCenter), "R")
            p.setOpacity(1.0)
        try:
            if hv > 0.01 or self._on:
                paint_anim(p, self.design, self.fin, k, now, m, hole, d, banner, ball)
            else:
                banner(m, 0.35)
        except Exception:  # noqa: BLE001
            log.exception("animation preview failed")
            self._timer.stop()
        if hv < 0.99:                                                     # PREVIEW until the mouse comes over it
            p.setOpacity(1.0 - hv)
            p.setPen(alpha("#FFFFFF", 0.22))
            p.setFont(font(26, QFont.Weight.Black, 8))
            p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), tr("PREVIEW"))
            p.setPen(alpha("#FFFFFF", 0.35))
            p.setFont(font(9.5, QFont.Weight.Bold))
            p.drawText(r.adjusted(0, 0, 0, -S(10)), int(Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignBottom),
                       tr("Hover to play"))
            p.setOpacity(1.0)


def anim_set(ctx, item: str) -> None:
    def done(ok: bool, d) -> None:
        if not ok:
            ctx.toast(tr(str(d)), "warn")
        else:
            ctx.econ.looks_changed.emit()
        ctx.reload_page()
    sfx.play("pick")
    ctx.econ.wear("anim", item, done)


ANIMS_LOCKED = False                      # 9.1: open again (5 animations, each with Titanium, Gold and Prismatic)


def build_animations(page, lay, shop: bool) -> None:
    ctx, ec = page.ctx, page.ctx.econ
    if ANIMS_LOCKED:
        lay.addWidget(Label(tr("Animations are locked for now. Watch this space."), 12, TEXT_DIM, wrap_w=page.W))
        return
    if not ec.ready or not ec.catalog:
        return lay.addWidget(Label(tr("Connecting…") if ctx.online.logged_in() else tr("Log in to see the shop"), 12, TEXT_DIM))
    cur = ec.worn("anim")
    cursp = anim_split(cur) if cur and ec.can_wear(cur) else None
    row = hbox(spacing=8)
    now_name = item_name(cur).split(" (")[0] if cursp else tr("Simple (free)")
    row.addWidget(Label(tr("Now: {name}", name=now_name), 12, bold=True), 1)
    off = Button(tr("Use the simple one"), "primary" if cursp else "ghost", 30)
    off.setEnabled(cursp is not None)
    off.setToolTip(tr("Turns the special animation off: the banner just floats up and drops back down"))
    off.clicked.connect(lambda: anim_set(ctx, ""))
    row.addWidget(off)
    lay.addLayout(row)
    state = getattr(ctx, "anim_fin", None)
    if not isinstance(state, dict):
        state = ctx.anim_fin = {}
    shown = 0
    # 9.5: Basic at the top (free, yours from the start, no versions), then Epic, Legendary and Mythic
    lay.addSpacing(S(6))
    lay.addWidget(Label(tr("BASIC"), 10, RARITY_COLOURS["standard"], weight=QFont.Weight.Bold))
    bhead = hbox(spacing=8)
    bhead.addWidget(Label(tr("Basic"), 14, bold=True), 1)
    bhead.addWidget(Label(tr("Free, always yours"), 11, TEXT_DIM, bold=True))
    lay.addLayout(bhead)
    lay.addWidget(Label(tr("The banner floats up into nothing and drops back down."), 10.5, TEXT_DIM, wrap_w=page.W))
    if cursp is not None:
        bb = Button(tr("Wear"), "primary", 32)
        bb.clicked.connect(lambda: anim_set(ctx, ""))
        lay.addWidget(bb)
    else:
        lay.addWidget(Label(tr("You're using this one."), 10.5, "#3DDC84", bold=True))
    tier_shown = None
    order = {"special": 0, "epic": 1, "exotic": 2}
    for design, name in sorted(ANIMS, key=lambda x: order.get(ANIM_RARITY.get(x[0]), 0)):
        fins = anim_fins(design)
        if shop:
            avail = [f for f in fins if anim_id(design, f) in ec.catalog and ec.info(anim_id(design, f)).get("price") is not None]
        else:
            avail = [f for f in ANIM_FIN_IDS if ec.owns(anim_id(design, f))]
        if not avail:
            continue
        if ANIM_RARITY.get(design) != tier_shown:
            tier_shown = ANIM_RARITY.get(design)
            lay.addSpacing(S(12))
            lay.addWidget(Label(tr(RARITY_NAMES.get(tier_shown, "")).upper(), 10,
                                RARITY_COLOURS.get(tier_shown, TEXT_DIM), weight=QFont.Weight.Bold))
        shown += 1
        fin = state.get(design, avail[0])
        if fin not in avail:
            fin = avail[0]
        item = anim_id(design, fin)
        lay.addSpacing(S(8))
        head = hbox(spacing=8)
        head.addWidget(Label(tr(name), 14, bold=True), 1)
        head.addWidget(Label(rarity_line(ctx, item), 11, RARITY_COLOURS.get(ec.rarity(item), TEXT_DIM), bold=True))
        lay.addLayout(head)
        lay.addWidget(AnimPreview(ctx, design, fin, page.W))
        if len(avail) > 1:
            chips = hbox(spacing=4)
            for f in avail:
                b = Button(tr(ANIM_SHORT[f]), "primary" if f == fin else "ghost", 26)
                b.setToolTip(tr(dict(ANIM_FINS)[f]))
                b.clicked.connect(lambda _c=False, d_=design, f_=f: (sfx.play("pick"), state.__setitem__(d_, f_), ctx.reload_page()))
                chips.addWidget(b, 1)
            lay.addLayout(chips)
        if ec.owns(item):
            on = ec.worn("anim") == item
            b = Button(tr("Take off") if on else tr("Wear"), "ghost" if on else "primary", 36)
            b.clicked.connect(lambda _c=False, it=item, on_=on: anim_set(ctx, "" if on_ else it))
            lay.addWidget(b)
        elif fin and not ec.owns(anim_id(design)):                # 9.1: versions unlock with the base one
            lay.addWidget(Label(tr("Own {name} first to unlock this version.", name=tr(name)), 10.5, TEXT_DIM,
                                wrap_w=page.W))
        elif ec.shop_price(item) is not None:
            price = ec.shop_price(item)
            b = Button(tr("Buy for {n} coins", n=coins_text(price)) + (f"  (-{ec.sale(item)}%)" if ec.sale(item) else ""), "primary", 36)

            def buy(it=item, pr=price, bt=b) -> None:
                if pr > ec.coins:
                    return ctx.toast(tr("Not enough coins: {n} more needed", n=coins_text(pr - ec.coins)), "warn")

                def done(ok: bool, data) -> None:
                    if not ok:
                        sfx.play("off")
                        return ctx.toast(tr(str(data)), "warn")
                    sfx.play("on")
                    ctx.toast(tr("Bought: {what}", what=item_name(it)))
                    ctx.reload_page()
                ctx.window.confirm(tr("Buy {name} for {n} coins?", name=item_name(it), n=coins_text(pr)),
                                   lambda: (bt.setEnabled(False), ec.buy(it, done)), yes=tr("Buy"))
            b.clicked.connect(buy)
            lay.addWidget(b)
            lay.addWidget(TaxNote(ctx, item, page.W))
        else:
            lay.addWidget(Label(tr("Not for sale."), 10.5, TEXT_DIM, wrap_w=page.W))
    if not shown:
        lay.addWidget(Label(tr("Nothing here yet. Buy one in the Shop or win one in the Crown Vault."), 12, TEXT_DIM, wrap_w=page.W))
    lay.addSpacing(S(6))
    lay.addWidget(Label(tr("If an animation ever glitches: click anywhere or press Esc to skip it, or press \"Use the simple one\"."),
                        10, TEXT_DIM, wrap_w=page.W))


def _inventory_detail(page, lay, item: str, copies: list) -> None:
    ctx, ec = page.ctx, page.ctx.econ
    kind = item.split(":")[0]
    free = [c for c in copies if not c.get("locked")]
    head = hbox(spacing=8)
    head.addWidget(Label(item_name(item), 13.5, bold=True), 1)
    head.addWidget(Label(rarity_line(ctx, item), 10.5, RARITY_COLOURS.get(ec.rarity(item), TEXT_DIM), bold=True))
    lay.addLayout(head)
    locked = len(copies) - len(free)
    note = tr("Worth {v} coins", v=coins_text(value_of(ctx, item))) if value_of(ctx, item) else \
        tr("A gift for the first users of Rubenium. It cannot be sold or traded.")
    if locked:
        where = copies[0].get("locked") or next((c["locked"] for c in copies if c.get("locked")), "")
        note += "  ·  " + (tr("{n} on the market", n=locked) if str(where).startswith("market") else tr("{n} in a trade", n=locked))
    lay.addWidget(Label(note, 10.5, TEXT_DIM, wrap_w=page.W))
    line = hbox(spacing=6)
    if kind == "badge":
        on = item in worn(ctx)
        b = Button(tr("Take off") if on else tr("Show"), "ghost" if on else "primary", 32)

        def show() -> None:
            done = lambda ok, d: (None if ok else ctx.toast(tr(str(d)), "warn"), ctx.reload_page())      # noqa: E731
            if on:
                return ec.wear(next(s for s in SLOTS if ec.worn(s) == item), "", done)
            slot = next((s for s in SLOTS if not ec.worn(s)), None)
            if slot is None:
                return ctx.toast(tr("Your showcase is full: take one off first"), "warn")
            sfx.play("pick")
            ec.wear(slot, item, done)
        b.clicked.connect(show)
    elif kind in LOOKS:
        on = look_worn(ctx, item)
        b = Button(tr("Take off") if on else tr("Wear"), "ghost" if on else "primary", 32)
        b.clicked.connect(lambda: wear_look(ctx, item, not on))
    else:
        on = ctx.shop_item_worn(item)
        b = Button(tr("Take off") if on else tr("Wear"), "ghost" if on else "primary", 32)

        def wear() -> None:
            sfx.play("pick")
            ctx.take_off_shop_item(kind) if on else ctx.wear_shop_item(item)
            ctx.reload_page()
        b.clicked.connect(wear)
    line.addWidget(b, 1)
    sellable = bool(free) and bool(ec.info(item).get("tradeable"))
    line2 = hbox(spacing=6)                               # 9.0: the market is gone: quick sell only
    quick = SellButton("pawn", tr("Quick sell"), tr("About {n} coins now", n=coins_text(ec.quick_value(item))))
    quick.setEnabled(sellable and ec.quick_value(item) > 0)
    quick.setToolTip(tr("Sell it right now for about {n} coins",
                        n=coins_text(ec.quick_value(item))))
    qty = [1]                                              # 6.2.7: how many copies go to the pawn shop

    def quick_go() -> None:
        n = max(1, min(qty[0], len(free)))
        ids = [c["id"] for c in free[-n:]]
        quick_sell(ctx, ids, item_name(item) if n == 1 else f"{n}× {item_name(item)}")
    quick.clicked.connect(quick_go)
    line2.addWidget(quick, 1)
    if free and item != "tag:og":                         # 5.1: the trash can, asked twice
        bin_ = IconButton("trash", 32, tip=tr("Delete for good"))
        bin_.clicked.connect(lambda: trash_item(ctx, free[-1]["id"], item))
        line.addWidget(bin_)
    import time as _t
    if getattr(ctx, "pawn_ban_until", 0) > _t.time():          # 4.6: the pawn shop's ban, readable at a glance
        pass

        def tick() -> None:
            try:
                left = int(ctx.pawn_ban_until - _t.time())
                if left <= 0:
                    quick.set_text(tr("Quick sell"))
                    return clock.stop()
                quick.set_text(tr("Closed {t}", t=pawn_clock(left)))
            except RuntimeError:
                clock.stop()
        clock = QTimer(quick)
        clock.setInterval(1000)
        clock.timeout.connect(tick)
        clock.start()
        tick()
    lay.addLayout(line)
    lay.addLayout(line2)
    if sellable and len(free) > 1:                         # 6.2.7: take several copies to the pawn shop at once
        row = hbox(spacing=6)
        sub = Label("", 10.5, TEXT_DIM)
        minus = Button("−", "ghost", 28)
        plus = Button("+", "ghost", 28)
        every = Button(tr("All"), "ghost", 28)
        for b_ in (minus, plus):
            b_.setFixedWidth(S(34))

        def shown() -> None:
            n = max(1, min(qty[0], len(free)))
            qty[0] = n
            sub.set_text(tr("Pawn shop: take {n} of {m}", n=n, m=len(free)))
            minus.setEnabled(n > 1)
            plus.setEnabled(n < len(free))
            every.setEnabled(n < len(free))
            if getattr(ctx, "pawn_ban_until", 0) <= time.time():
                quick.set_text(tr("Quick sell") if n == 1 else tr("Quick sell ×{n}", n=n))
                quick.sub = tr("About {n} coins now", n=coins_text(ec.quick_value(item) * n))
                quick.update()

        def step(d: int) -> None:
            sfx.play("pick")
            qty[0] += d
            shown()
        minus.clicked.connect(lambda: step(-1))
        plus.clicked.connect(lambda: step(1))
        every.clicked.connect(lambda: step(len(free) - qty[0]))
        row.addWidget(sub, 1)
        row.addWidget(minus)
        row.addWidget(plus)
        row.addWidget(every)
        lay.addLayout(row)
        shown()


class SellButton(QAbstractButton):
    """5.0: the two ways to sell, drawn as their own places: the market stall (striped awning, your price) and the
    pawn shop (gold sign, cash now)."""

    def __init__(self, kind: str, title: str, sub: str) -> None:
        super().__init__()
        self.kind, self.title, self.sub = kind, title, sub
        self.setFixedHeight(S(52))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.NoFocus)
        self._hover = Tween(self, on_change=self.update)

    def set_text(self, text: str) -> None:
        self.title = text
        self.update()

    def enterEvent(self, _e) -> None:
        self._hover.to(1.0, 140)

    def leaveEvent(self, _e) -> None:
        self._hover.to(0.0, 220)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        h = self._hover.level
        on = self.isEnabled()
        a, b = (("#1E6B5A", "#0E2E28") if self.kind == "market" else ("#6B4A12", "#2A1C06"))
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        g.setColorAt(0, mix(QColor(a), QColor("#FFFFFF"), 0.10 * h))
        g.setColorAt(1, QColor(b))
        p.setOpacity(1.0 if on else 0.4)
        p.setPen(QPen(alpha("#FFFFFF", 0.14 + 0.2 * h), 1.2))
        p.setBrush(g)
        p.drawRoundedRect(r, S(10), S(10))
        icon = QRectF(r.left() + S(8), r.top() + S(8), r.height() - S(16), r.height() - S(16))
        if self.kind == "market":                         # a little stall: striped awning over a counter
            aw = QRectF(icon.left(), icon.top(), icon.width(), icon.height() * 0.42)
            n = 4
            for i in range(n):
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor("#FFFFFF") if i % 2 == 0 else QColor("#3DDC84"))
                p.drawRect(QRectF(aw.left() + i * aw.width() / n, aw.top(), aw.width() / n + 0.5, aw.height()))
            p.setBrush(QColor("#C9F5DE"))
            p.drawRect(QRectF(icon.left() + icon.width() * 0.08, aw.bottom(), icon.width() * 0.84, icon.height() * 0.5))
            p.setBrush(QColor("#1E6B5A"))
            p.drawRect(QRectF(icon.left() + icon.width() * 0.3, aw.bottom() + icon.height() * 0.16,
                              icon.width() * 0.4, icon.height() * 0.34))
        else:                                             # the pawn shop's three gold balls and a coin
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#E8C26A"))
            rr = icon.width() * 0.17
            for dx, dy in ((0.22, 0.3), (0.78, 0.3), (0.5, 0.72)):
                p.drawEllipse(QPointF(icon.left() + icon.width() * dx, icon.top() + icon.height() * dy), rr, rr)
            p.setPen(QPen(QColor("#E8C26A"), S(1.4)))
            p.drawLine(QPointF(icon.left() + icon.width() * 0.22, icon.top() + icon.height() * 0.3),
                       QPointF(icon.left() + icon.width() * 0.5, icon.top()))
            p.drawLine(QPointF(icon.left() + icon.width() * 0.78, icon.top() + icon.height() * 0.3),
                       QPointF(icon.left() + icon.width() * 0.5, icon.top()))
        tx = icon.right() + S(8)
        p.setPen(QColor("#FFFFFF"))
        p.setFont(font(12, QFont.Weight.Bold))
        p.drawText(QRectF(tx, r.top() + S(7), r.right() - tx - S(6), S(20)), int(Qt.AlignmentFlag.AlignVCenter),
                   p.fontMetrics().elidedText(self.title, Qt.TextElideMode.ElideRight, int(r.right() - tx - S(6))))
        p.setPen(alpha("#FFFFFF", 0.65))
        p.setFont(font(9.5, QFont.Weight.DemiBold))
        p.drawText(QRectF(tx, r.top() + S(26), r.right() - tx - S(6), S(18)), int(Qt.AlignmentFlag.AlignVCenter),
                   p.fontMetrics().elidedText(self.sub, Qt.TextElideMode.ElideRight, int(r.right() - tx - S(6))))


def trash_item(ctx, instance: str, item: str) -> None:
    """5.1: delete one copy for good. Two questions, then the server checks a third time ('DELETE')."""
    name = item_name(item)

    def last() -> None:
        def done(ok: bool, data) -> None:
            if not ok:
                return ctx.toast(tr(str(data)), "warn")
            sfx.play("off")
            ec = ctx.econ
            ec.items = [i for i in ec.items if i["id"] != instance]
            ec._index()
            if isinstance(data, dict) and isinstance(data.get("equip"), dict):
                ec.equip = dict(data["equip"])
            ec.changed.emit()
            ctx.toast(tr("{name} was deleted", name=name))
            ctx.inv_pick = ""
            ctx.reload_page()
        ctx.econ.call("rb_trash", {"item_id": instance, "confirm": "DELETE"}, done)

    def second() -> None:
        QTimer.singleShot(250, lambda: ctx.window.confirm(
            tr("Really delete {name}? It cannot be undone, sold or given back.", name=name), last,
            yes=tr("Delete for good"), no=tr("Keep it")))
    ctx.window.confirm(tr("Throw {name} in the trash? It will be gone forever.", name=name), second,
                       yes=tr("Delete"), no=tr("Keep it"))


def quick_sell(ctx, ids: list, what: str) -> None:
    """4.3: quick sell is the pawn shop: it asks first, then you go in and take his offer or haggle."""
    ec = ctx.econ
    if not ec.quick_ready():
        return ctx.toast(tr("Coming very soon: the server is being updated"), "warn")
    first = next((i for i in ec.items if i["id"] == (ids[0] if ids else None)), None)
    pass
    open_pawn(ctx, list(ids), first["item"] if first else "", what)


def build_profile_style(page, lay) -> None:
    """Style > Your profile: banner, frame, tag and the 3 badges of your showcase, as everyone sees them."""
    pass
    ctx, ec = page.ctx, page.ctx.econ
    lay.addWidget(heading(tr("Your profile")))
    if not ec.ready:
        return lay.addWidget(Label(tr("Log in to change your profile"), 11, TEXT_DIM))
    lay.addWidget(LookPreview(ctx, "", page.W, tr("This is what other users see")))
    if not any(k.startswith("banner:") for k in ec.catalog):
        return lay.addWidget(Label(tr("Banners and frames: coming very soon"), 11, TEXT_DIM))
    head0 = hbox(spacing=8)                              # 5.2: titles (OG and leaderboard ranks), 3 at most
    head0.addWidget(Label(tr("Titles"), 12.5, bold=True), 1)
    head0.addWidget(Label(tr("Up to 3 · gold, silver and bronze while you are top 3"), 10, TEXT_DIM))
    lay.addLayout(head0)
    lay.addWidget(TitleChips(ctx, page.W))
    for kind, title, empty in (("banner", tr("Banner"), tr("No banner yet: buy one in the Shop or on the Market.")),
                               ("frame", tr("Frame"), tr("No frame yet: buy one in the Shop or on the Market."))):
        mine = sorted({i["item"] for i in ec.items if i["item"].startswith(kind + ":")},
                      key=lambda k: (-ec.worth(k), k))
        if kind == "tag" and not mine:
            continue
        head = hbox(spacing=8)
        head.addWidget(Label(title, 12.5, bold=True), 1)
        cur = ec.worn(kind)
        head.addWidget(Label(item_name(cur) if cur and cur in mine else tr("None"), 10.5, TEXT_DIM))
        lay.addLayout(head)
        if not mine:
            lay.addWidget(Label(empty, 10.5, TEXT_FAINT, wrap_w=page.W))
            continue
        entries = [{"item": k, "text": tr("Worn") if k == cur else tr("Wear")} for k in mine]
        grid = ItemGrid(ctx, entries, page.W, 3 if kind == "banner" else 5, 80 if kind == "banner" else 70,
                        mine.index(cur) if cur in mine else -1)
        grid.picked.connect(lambda i, m=mine, c=cur: wear_look(ctx, m[i], m[i] != c))
        lay.addWidget(grid)
        level = int((ec.wear_data.get(cur) or {}).get("level") or 0) if kind == "banner" and cur else 0
        if level:                                          # 3.1: keep the normal look or show its gold
            pass
            pick = ec.worn("banner_gold")
            pick = min(level, int(pick) if pick.isdigit() else 3)
            seg = Segmented([tr("Normal")] + [tr(GOLD_NAMES[n]) for n in range(1, level + 1)], pick)

            def choose(i: int) -> None:
                def done(ok: bool, _d) -> None:
                    if ok:
                        ec.equip["banner_gold"] = i
                        ec.looks_changed.emit()
                        ctx.reload_page()
                ec.call("rb_banner_gold", {"level": i}, done)
            seg.changed.connect(choose)
            lay.addWidget(seg)
    lay.addWidget(Label(tr("Click the one you wear to take it off."), 10, TEXT_FAINT))
    head = hbox(spacing=8)
    head.addWidget(Label(tr("Showcase"), 12.5, bold=True), 1)
    pick = Button(tr("Choose badges"), "ghost", 26)

    def to_collection() -> None:
        ctx.shop_tab = 2
        if ctx.window.showing("themes"):
            ctx.reload_page("themes")
        else:
            ctx.window._drop_page("themes")
            ctx.window.goto("themes")
    pick.clicked.connect(to_collection)
    head.addWidget(pick)
    lay.addLayout(head)
    lay.addWidget(Showcase3(ctx, ec.badges_worn(), page.W, True))
    if ec.badges_worn():                                 # 5.0: all of them back to the inventory at once
        clear = Button(tr("Clear badges"), "ghost", 28, icon="close")

        def clear_all() -> None:
            sfx.play("off")
            slots = ["badge1", "badge2", "badge3"]
            for slot in slots:
                ec.equip.pop(slot, None)                  # gone from the profile right away, the server follows

            def next_one(ok=True, d=None) -> None:         # one after the other: the last answer is the truth
                if ok and isinstance(d, dict):
                    ec.equip = {k: v for k, v in d.items() if k not in slots}
                if slots:
                    ec.call("rb_equip", {"slot": slots.pop(0), "what": ""}, next_one)
                else:
                    ec.looks_changed.emit()
            next_one()
            ec.looks_changed.emit()
            ec.changed.emit()
            ctx.reload_page()
        clear.clicked.connect(clear_all)
        lay.addWidget(clear)


def market_sell(ctx, item: str) -> None:
    """4.6: selling on the market is a place now: the market stall (market.py)."""
    pass
    open_market_stall(ctx, item)


