class ListingRow(QWidget):
    """One item on sale: picture, name, seller, price."""
    clicked = pyqtSignal()

    def __init__(self, ctx, row: dict, width: int, mine: bool = False) -> None:
        super().__init__()
        self.ctx, self.row, self.mine = ctx, row, mine
        self.setFixedSize(width, S(48))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._hover = False
        self._timer = QTimer(self)
        self._timer.setInterval(80)
        self._timer.timeout.connect(self.update)

    def showEvent(self, _e) -> None:
        self._timer.start()

    def hideEvent(self, _e) -> None:
        self._timer.stop()

    def enterEvent(self, _e) -> None:
        self._hover = True
        self.update()

    def leaveEvent(self, _e) -> None:
        self._hover = False
        self.update()

    def mousePressEvent(self, e) -> None:
        e.accept()
        if e.button() == Qt.MouseButton.LeftButton:
            self.clicked.emit()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        row, item = self.row, self.row.get("item", "")
        r = QRectF(self.rect()).adjusted(0.5, 2, -0.5, -2)
        col = QColor(RARITY_COLOURS.get(self.ctx.econ.rarity(item), "#9AA4AD"))
        p.setPen(QPen(alpha(col, 0.35 + (0.3 if self._hover else 0)), 1.1))
        p.setBrush(mix(QColor("#0D1214"), col, 0.07 + (0.05 if self._hover else 0)))
        p.drawRoundedRect(r, S(10), S(10))
        paint_cosmetic(p, item, QRectF(r.left() + S(8), r.top() + S(6), r.height() - S(12), r.height() - S(12)),
                       time.monotonic())
        x = r.left() + S(52)
        p.setPen(QColor(TEXT))
        p.setFont(font(12, QFont.Weight.Bold))
        name = p.fontMetrics().elidedText(item_name(item), Qt.TextElideMode.ElideRight, int(r.width() - S(150)))
        p.drawText(QRectF(x, r.top() + S(5), r.width() - S(150), S(18)), int(Qt.AlignmentFlag.AlignVCenter), name)
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(10, QFont.Weight.DemiBold))
        if self.mine:
            state = row.get("state")
            sub = tr("On sale") if state == "open" else tr("Sold to {name}", name=row.get("buyer") or "?")
        else:
            sub = (tr("Yours") if row.get("mine") else tr("by {name}", name=row.get("seller", "?"))) + \
                "  ·  " + tr("usual: {v}", v=coins_text(int(row.get("estimate") or 0)))
        p.drawText(QRectF(x, r.top() + S(23), r.width() - S(150), S(16)), int(Qt.AlignmentFlag.AlignVCenter), sub)
        paint_coin(p, QPointF(r.right() - S(86), r.center().y()), S(6))
        p.setPen(QColor(GOLD_TEXT))
        p.setFont(font(12.5, QFont.Weight.Bold))
        p.drawText(QRectF(r.right() - S(76), r.top(), S(68), r.height()), int(Qt.AlignmentFlag.AlignVCenter),
                   coins_text(int(row.get("price") or 0)))


def build_market(page, lay) -> None:
    ctx, ec = page.ctx, page.ctx.econ
    if not ec.ready:
        return lay.addWidget(Label(tr("Connecting…") if ctx.online.logged_in() else tr("Log in to see the market"), 12, TEXT_DIM))
    tab = int(getattr(ctx, "mk_tab", 0) or 0)
    offers = int(ec.live.get("offers") or 0)
    # 5.5: Buy · Swaps · Sell · My sales · Offers (selling starts here now, not in the inventory)
    # 5.12: no more Swaps tab (the pawn shop's Propose exchange replaces it). Tabs keep their old numbers.
    if tab == 1:
        tab = 0
    shown = [0, 2, 3, 4]
    seg = Segmented([tr("Buy"), tr("Sell"), tr("My sales"), tr("Offers") + (f" ({offers})" if offers else "")],
                    shown.index(tab))

    def switch(i: int) -> None:
        ctx.mk_tab, ctx.mk_at = shown[i], 0
        ctx.reload_page()
    seg.changed.connect(switch)
    lay.addWidget(seg)
    if tab == 4:
        return _offers(page, lay)
    if tab == 1:
        return build_swaps(page, lay)
    if tab == 2:
        return build_sell(page, lay)
    if tab:
        fn, args = "rb_market_mine", {}
    else:                                                    # 4.0: search by name, type, rarity and finish
        flt = market_filters(ctx)
        if not _market_search_bar(page, lay, flt):
            return
        ids = market_ids(ctx, flt["q"]) if flt["q"] else None
        if ids is not None and not ids:
            return lay.addWidget(Label(tr("No item is called “{q}”.", q=flt["q"]), 12, TEXT_DIM, wrap_w=page.W))
        fn, args = "rb_market_search", {"ids": ids, "kind": flt["kind"], "rarity": flt["rarity"],
                                        "cls": flt["cls"], "sort": flt["sort"], "page": 0}
    key = (fn, str(args))
    rows = getattr(ctx, "mk_rows", None) if getattr(ctx, "mk_key", None) == key else None
    if rows is None or time.monotonic() - getattr(ctx, "mk_at", 0) > 10:
        ctx.mk_at = time.monotonic()

        def got(ok: bool, data) -> None:
            if not ok or not isinstance(data, list):
                return
            changed = data != getattr(ctx, "mk_rows", None) or getattr(ctx, "mk_key", None) != key
            ctx.mk_rows, ctx.mk_key = data, key
            if changed and ctx.window.showing("themes") and getattr(ctx, "shop_tab", 0) == 4:
                ctx.reload_page("themes")
        ec.online.ask(fn, args, got)
    if rows is None:
        return lay.addWidget(Label(tr("Loading…"), 12, TEXT_DIM))
    if not rows:
        searching = not tab and market_filters(ctx) != MARKET_FILTERS
        lay.addSpacing(S(4))                              # 8.0: designed empty states
        lay.addWidget(notice("search" if searching else "market", tr("Nothing on sale"),
                             tr("Nothing on sale. Put an item on sale in Sell.") if tab else
                             tr("Nothing on sale matches this search.") if searching else
                             tr("Nothing on sale right now. Be the first: put an item on sale in Sell."), page.W))
    for row in rows[:40]:
        if is_secret(row.get("item", "")):
            row = dict(row)
        w = ListingRow(ctx, row, page.W, mine=bool(tab))
        if tab:
            ctx.mk_open_mine = sum(1 for r in rows if r.get("state", "open") == "open")
        w.clicked.connect(lambda r=row: _market_click(page, r, bool(tab)))
        lay.addWidget(w)
    if not tab:
        lay.addWidget(Label(tr("Fixed price set by the seller. 5% market fee."), 10.5, TEXT_DIM,
                            wrap_w=page.W))


def build_sell(page, lay) -> None:
    """5.5: pick one of your items here and put it on sale at the stall. 3 listings at most."""
    ctx = page.ctx
    n = int(getattr(ctx, "mk_open_mine", 0) or 0)
    lay.addWidget(Label(tr("Your listings: {n} / 3", n=n), 12, TEXT, bold=True))
    lay.addWidget(Label(tr("Pick one item, then set your price at the stall. 5% market fee when it sells."),
                        10.5, TEXT_DIM, wrap_w=page.W))
    picker = ItemPicker(page, 1)
    go = Button(tr("Put it on sale…"), "primary", 40, icon="chip")

    def update_go() -> None:
        go.setEnabled(bool(picker.picked))
    picker.changed.connect(update_go)
    update_go()

    def sell() -> None:
        if not picker.picked:
            return
        item = next((it for iid, it, _w in picker.rows if iid == picker.picked[0]), None)
        if item:
            open_market_stall(ctx, item)
    go.clicked.connect(sell)
    lay.addWidget(go)
    lay.addWidget(sort_bar(ctx, picker.resort))
    lay.addWidget(picker)


def build_swaps(page, lay) -> None:
    """5.5: SWAPS. Put an item up and say which items (1 to 3) you would take for it; anyone who has one of them can
    swap with one click. No coins, no fee. 3 open swaps at most."""
    ctx, ec = page.ctx, page.ctx.econ
    rows = getattr(ctx, "sw_rows", None)
    if rows is None or time.monotonic() - getattr(ctx, "sw_at", 0) > 10:
        ctx.sw_at = time.monotonic()

        def got(ok: bool, data) -> None:
            if not ok or not isinstance(data, list):
                return
            changed = data != getattr(ctx, "sw_rows", None)
            ctx.sw_rows = data
            if changed and ctx.window.showing("themes") and getattr(ctx, "mk_tab", 0) == 1:
                ctx.reload_page("themes")
        ec.online.ask("rb_item_swaps_list", {}, got)
    if getattr(ctx, "sw_new", False):
        return _swap_new(page, lay)
    mine = [r for r in rows or [] if r.get("mine")]
    new = Button(tr("New swap ({n}/3)", n=len(mine)), "primary", 38, icon="chip")
    new.setEnabled(len(mine) < 3)
    new.clicked.connect(lambda: (setattr(ctx, "sw_new", True), setattr(ctx, "sw_wants", []), ctx.reload_page()))
    lay.addWidget(new)
    if rows is None:
        return lay.addWidget(Label(tr("Loading…"), 12, TEXT_DIM))
    if not rows:
        lay.addWidget(Label(tr("No swap yet. Start one: pick what you give and what you want back."), 12, TEXT_DIM,
                            wrap_w=page.W))
    for r in rows[:40]:
        lay.addWidget(SwapRow(page, r))
    lay.addWidget(Label(tr("A swap gives your item for one of the items you asked for. No coins, no fee."),
                        10.5, TEXT_DIM, wrap_w=page.W))


class SwapRow(QWidget):
    """One swap: what is given, the arrow, the 1-3 items wanted, and Swap / Cancel."""

    def __init__(self, page, r: dict) -> None:
        super().__init__()
        self.page, self.ctx, self.r = page, page.ctx, r
        self.setFixedSize(page.W, S(78))
        lay = hbox(self, 8)
        lay.setContentsMargins(S(8), S(6), S(8), S(6))
        lay.addStretch(1)
        can = list(r.get("can") or [])
        if r.get("mine"):
            b = Button(tr("Cancel"), "ghost", 30)
            b.clicked.connect(self._cancel)
        else:
            b = Button(tr("Swap"), "primary", 30)
            b.setEnabled(bool(can))
            b.setToolTip(tr("You need one of the items it asks for") if not can else "")
            b.clicked.connect(self._take)
        b.setFixedWidth(S(84))
        lay.addWidget(b, 0, Qt.AlignmentFlag.AlignVCenter)

    def _cancel(self) -> None:
        ctx = self.ctx

        def done(ok: bool, d) -> None:
            sfx.play("off")
            ctx.sw_at = 0
            ctx.econ.refresh()
            ctx.reload_page()
        ctx.econ.call("rb_swap_cancel", {"sid": self.r["id"]}, done)

    def _take(self) -> None:
        ctx, r = self.ctx, self.r
        can = list(r.get("can") or [])
        if not can:
            return
        give = can[0]

        def go() -> None:
            def done(ok: bool, d) -> None:
                if not ok:
                    sfx.play("off")
                    return ctx.toast(tr(str(d)), "warn")
                sfx.tune("levelup")
                ctx.toast(tr("Swapped! {what} is yours", what=item_name(r.get("item", ""))))
                ctx.sw_at = 0
                ctx.econ.refresh()
                ctx.reload_page()
            ctx.econ.call("rb_swap_take", {"sid": r["id"], "item_id": give["id"]}, done, once=True)
        ctx.window.confirm(tr("Give your {a} for {b}?", a=item_name(give.get("item", "")), b=item_name(r.get("item", ""))),
                           go, yes=tr("Swap"))

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 2, -0.5, -2)
        mine = bool(self.r.get("mine"))
        paint_surface(p, r, S(DS.R_MD), 0.04, edge=alpha(ui.accent, 0.6) if mine else None)   # 8.0: shared surface
        now = time.monotonic()
        d = r.height() - S(22)
        show_item(p, self.r.get("item", ""), QRectF(r.left() + S(8), r.top() + S(4), d, d), now, effects=False)
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9, QFont.Weight.Bold))
        who = tr("You") if mine else str(self.r.get("from") or "?")
        p.drawText(QRectF(r.left() + S(4), r.bottom() - S(18), d + S(8), S(16)), int(Qt.AlignmentFlag.AlignCenter),
                   QFontMetrics(p.font()).elidedText(who, Qt.TextElideMode.ElideRight, int(d + S(8))))
        ax = r.left() + d + S(22)                          # the arrow
        p.setPen(QPen(QColor("#FFC94D"), S(2.4), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.drawLine(QPointF(ax, r.center().y() - S(4)), QPointF(ax + S(22), r.center().y() - S(4)))
        p.drawLine(QPointF(ax + S(22), r.center().y() - S(4)), QPointF(ax + S(15), r.center().y() - S(10)))
        p.drawLine(QPointF(ax, r.center().y() + S(4)), QPointF(ax + S(22), r.center().y() + S(4)))
        p.drawLine(QPointF(ax, r.center().y() + S(4)), QPointF(ax + S(7), r.center().y() + S(10)))
        x = ax + S(32)
        have = {c.get("item") for c in self.r.get("can") or []}
        for it in (self.r.get("wants") or [])[:3]:
            box = QRectF(x, r.top() + S(8), d - S(10), d - S(10))
            if it in have:
                p.setPen(QPen(QColor("#3DDC84"), S(2)))
                p.setBrush(alpha("#3DDC84", 0.12))
                p.drawRoundedRect(box.adjusted(-S(3), -S(3), S(3), S(3)), S(6), S(6))
            show_item(p, it, box, now, effects=False)
            x += d - S(2)
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9))
        p.drawText(QRectF(ax + S(32), r.bottom() - S(18), S(160), S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("any one of these"))


def _swap_new(page, lay) -> None:
    """Making a swap: 1. the item you give, 2. up to 3 items you want back (search by name), 3. Start."""
    ctx, ec = page.ctx, page.ctx.econ
    wants = list(getattr(ctx, "sw_wants", None) or [])
    top = hbox(spacing=8)
    back = IconButton("back", 30, tip=tr("Back"))
    back.clicked.connect(lambda: (setattr(ctx, "sw_new", False), ctx.reload_page()))
    top.addWidget(back)
    top.addWidget(Label(tr("NEW SWAP"), 14, "#FFC94D", bold=True), 1)
    lay.addLayout(top)
    lay.addWidget(Label(tr("2. What you want back: up to 3 (tap to remove)"), 11.5, TEXT, bold=True))
    if wants:
        grid = ItemGrid(ctx, [{"item": w, "text": item_name(w)} for w in wants], page.W, 5, 76)
        grid.picked.connect(lambda i: (wants.pop(i), setattr(ctx, "sw_wants", wants), ctx.reload_page()))
        lay.addWidget(grid)
    q = str(getattr(ctx, "sw_q", "") or "")

    def ask() -> None:
        def got(text: str, dlg) -> None:
            dlg.close()
            ctx.sw_q = text.strip()[:40]
            ctx.reload_page()
        AskDialog(ctx, tr("Which item do you want?"), tr("Name, type, rarity or finish"), tr("Search"), got, 40,
                  tr("For example: dragon, titanium, mythic banner."))
    bar = SearchBar(q, page.W)
    bar.clicked.connect(ask)
    bar.cleared.connect(lambda: (setattr(ctx, "sw_q", ""), ctx.reload_page()))
    lay.addWidget(bar)
    if q:
        found = [i for i in market_ids(ctx, q) if i not in wants][:15]
        if not found:
            lay.addWidget(Label(tr("No item is called “{q}”.", q=q), 11, TEXT_DIM, wrap_w=page.W))
        else:
            res = ItemGrid(ctx, [{"item": i, "text": item_name(i)} for i in found], page.W, 5, 76)

            def add(i: int) -> None:
                if len(wants) >= 3:
                    return ctx.toast(tr("3 at most: tap one above to remove it"), "warn")
                wants.append(found[i])
                ctx.sw_wants = wants
                sfx.play("pick")
                ctx.reload_page()
            res.picked.connect(add)
            lay.addWidget(res)
    lay.addWidget(Label(tr("1. What you give: pick one of your items"), 11.5, TEXT, bold=True))
    picker = ItemPicker(page, 1)
    start = Button(tr("Start the swap"), "primary", 40)

    def update() -> None:
        start.setEnabled(bool(picker.picked) and bool(wants))
    picker.changed.connect(update)
    update()

    def make() -> None:
        def done(ok: bool, d) -> None:
            if not ok:
                sfx.play("off")
                return ctx.toast(tr(str(d)), "warn")
            sfx.play("on")
            ctx.toast(tr("Swap open: anyone with one of those items can take it"))
            ctx.sw_new, ctx.sw_wants, ctx.sw_q, ctx.sw_at = False, [], "", 0
            ec.refresh()
            ctx.reload_page()
        ec.call("rb_swap_create", {"item_id": picker.ids()[0], "wants": wants}, done, once=True)
    start.clicked.connect(make)
    lay.addWidget(start)
    lay.addWidget(sort_bar(ctx, picker.resort))
    lay.addWidget(picker)


MARKET_FILTERS = {"q": "", "kind": "", "rarity": "", "cls": None, "sort": "new"}
MARKET_SORTS = [("new", "Newest"), ("cheap", "Cheapest"), ("dear", "Priciest"), ("deal", "Best deals")]
MARKET_KINDS = [("", "All"), ("badge", "Badges"), ("banner", "Banners"), ("frame", "Frames"), ("anim", "Animations"), ("ball", "Balls"),
                ("line", "Lines"), ("theme", "Themes"), ("font", "Fonts")]


def market_filters(ctx) -> dict:
    f = getattr(ctx, "mk_filters", None)
    if not isinstance(f, dict):
        f = ctx.mk_filters = dict(MARKET_FILTERS)
    return f


def market_ids(ctx, query: str) -> list:
    """Every item whose name, type, rarity or finish holds all the words typed (English or French)."""
    words = [w for w in query.lower().replace(",", " ").split() if w]
    pass
    out = []
    for iid, info in ctx.econ.catalog.items():
        if not info.get("tradeable") or info.get("kind") in ("prog", "tag", "coupon"):
            continue
        kind = info.get("kind", "")
        hay = [item_name(iid), iid, KIND_NAMES.get(kind, kind), RARITY_NAMES.get(info.get("rarity", ""), "")]
        if kind == "badge":
            hay.append(CLASS_NAMES[min(int(info.get("cls") or 0), len(CLASS_NAMES) - 1)])
        text = " ".join(hay + [tr(h) for h in hay]).lower()
        if all(w in text for w in words):
            out.append(iid)
    return out


def _market_search_bar(page, lay, flt: dict) -> bool:
    """The search bar and its filters. False if nothing more should be shown (never, for now)."""
    ctx = page.ctx

    def apply(**kw) -> None:
        flt.update(kw)
        ctx.mk_at = 0
        ctx.reload_page()

    def ask() -> None:
        def got(text: str, dlg) -> None:
            dlg.close()
            apply(q=text.strip()[:40])
        AskDialog(ctx, tr("Search the market"), tr("Name, type, rarity or finish"), tr("Search"), got, 40,
                  tr("For example: dragon, titanium, mythic banner."))
    bar = SearchBar(flt["q"], page.W)
    bar.clicked.connect(ask)
    bar.cleared.connect(lambda: apply(**MARKET_FILTERS))
    lay.addWidget(bar)
    kinds = Segmented([tr(n) for _k, n in MARKET_KINDS], [k for k, _n in MARKET_KINDS].index(flt["kind"])
                      if flt["kind"] in [k for k, _n in MARKET_KINDS] else 0)
    kinds.changed.connect(lambda i: apply(kind=MARKET_KINDS[i][0], cls=None if MARKET_KINDS[i][0] != "badge" else flt["cls"]))
    lay.addWidget(kinds)
    rar = ["", "standard", "rare", "special", "epic", "exotic"]
    rs = Segmented([tr("Any rarity")] + [tr(RARITY_NAMES[r]) for r in rar[1:]], rar.index(flt["rarity"]) if flt["rarity"] in rar else 0)
    rs.changed.connect(lambda i: apply(rarity=rar[i]))
    lay.addWidget(rs)
    if flt["kind"] == "badge":
        cls = [None, 0, 1, 2, 3, 4]
        cs = Segmented([tr("Any finish")] + [tr(CLASS_NAMES[c]) for c in cls[1:]],
                       cls.index(flt["cls"]) if flt["cls"] in cls else 0)
        cs.changed.connect(lambda i: apply(cls=cls[i]))
        lay.addWidget(cs)
    srt = [k for k, _n in MARKET_SORTS]
    ss = Segmented([tr(n) for _k, n in MARKET_SORTS], srt.index(flt["sort"]) if flt["sort"] in srt else 0)
    ss.changed.connect(lambda i: apply(sort=srt[i]))
    lay.addWidget(ss)
    return True


class SearchBar(QWidget):
    """A search field drawn like one: click to type (the keyboard stays with your game until then)."""
    clicked = pyqtSignal()
    cleared = pyqtSignal()

    def __init__(self, query: str, width: int) -> None:
        super().__init__()
        self.query = query
        self.setFixedSize(width, S(38))
        self.setCursor(Qt.CursorShape.IBeamCursor)
        self._hover = False

    def enterEvent(self, _e) -> None:
        self._hover = True
        self.update()

    def leaveEvent(self, _e) -> None:
        self._hover = False
        self.update()

    def _x_rect(self) -> QRectF:
        return QRectF(self.width() - S(34), 0, S(34), self.height())

    def mouseReleaseEvent(self, e) -> None:
        if e.button() != Qt.MouseButton.LeftButton:
            return
        if self.query and self._x_rect().contains(e.position()):
            sfx.play("pick")
            return self.cleared.emit()
        self.clicked.emit()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        p.setPen(QPen(alpha(ui.accent, 0.7) if self.query else alpha("#FFFFFF", 0.22 if self._hover else 0.12), S(1.2)))
        p.setBrush(alpha("#FFFFFF", 0.07 if self._hover else 0.05))
        p.drawRoundedRect(r, S(10), S(10))
        p.save()
        p.translate(r.left() + S(18), r.center().y())
        p.scale(S(15) / 20, S(15) / 20)
        draw_icon(p, "search", QColor(TEXT_DIM))
        p.restore()
        p.setFont(font(12, QFont.Weight.DemiBold if self.query else QFont.Weight.Normal))
        p.setPen(QColor(TEXT) if self.query else QColor(TEXT_DIM))
        p.drawText(r.adjusted(S(34), 0, -S(36), 0), int(Qt.AlignmentFlag.AlignVCenter),
                   self.query or tr("Search the market: name, type, rarity, finish…"))
        if self.query:
            c = self._x_rect().center()
            p.setPen(QPen(QColor(TEXT_DIM), S(1.6)))
            p.drawLine(QPointF(c.x() - S(4), c.y() - S(4)), QPointF(c.x() + S(4), c.y() + S(4)))
            p.drawLine(QPointF(c.x() + S(4), c.y() - S(4)), QPointF(c.x() - S(4), c.y() + S(4)))


def _market_click(page, row: dict, mine: bool) -> None:
    ctx, ec = page.ctx, page.ctx.econ
    price, item = int(row.get("price") or 0), row.get("item", "")

    def after(ok: bool, data) -> None:
        if not ok:
            sfx.play("off")
            ctx.toast(tr(str(data)), "warn")
        else:
            sfx.play("on")
        ctx.mk_at = 0
        ec.refresh()
        QTimer.singleShot(500, ctx.reload_page)
    if mine or row.get("mine"):
        if row.get("state", "open") != "open":
            return
        return ctx.window.confirm(tr("Take {name} off the market?", name=item_name(item)),
                                  lambda: ec.call("rb_market_cancel", {"listing": row["listing"]}, after), yes=tr("Take off"))
    if not ec.can_trade():
        return ctx.toast(tr("The market opens after 5 hours with Rubenium"), "warn")
    if price > ec.coins:
        return ctx.toast(tr("Not enough coins: {n} more needed", n=coins_text(price - ec.coins)), "warn")

    def bought(ok: bool, data) -> None:
        if ok and isinstance(data, dict):
            ec.gained(data.get("item"), data.get("id"), "market")
            ctx.toast(tr("Bought: {what}", what=item_name(item)))
        after(ok, data)
    text = tr("Buy {name} for {n} coins?", name=item_name(item), n=coins_text(price))
    est = int(row.get("estimate") or 0)
    if est and price > est * 2:
        text += " " + tr("This is much more than its usual price ({v}).", v=coins_text(est))
    def offer() -> None:
        low = -(-price // 2)

        def sent(n: int, dlg) -> None:
            if n < low or n >= price:
                return dlg.say(tr("Between {a} and {b} coins", a=coins_text(low), b=coins_text(price - 1)))
            if n > ec.coins:
                return dlg.say(tr("Not enough coins"))

            def done(ok: bool, d) -> None:
                if not ok:
                    return dlg.say(tr(str(d)))
                dlg.close()
                sfx.play("on")
                ctx.toast(tr("Offer sent. Your coins stay yours until the seller accepts."))
            ec.call("rb_market_offer", {"listing": row["listing"], "price": n}, done)
        ask_number(ctx, tr("Make an offer"), tr("Your price"), tr("Send offer"), sent,
                   tr("{name}: on sale for {n} coins. Offer at least {a}.", name=item_name(item), n=coins_text(price),
                      a=coins_text(low)))
    ctx.window.confirm(text, lambda: ec.call("rb_market_buy", {"listing": row["listing"]}, bought, once=True),
                       yes=tr("Buy"), no=tr("Make an offer"), on_no=offer)


def _offers(page, lay) -> None:
    """Offers made to you (accept or refuse), and offers you made."""
    ctx, ec = page.ctx, page.ctx.econ
    data = getattr(ctx, "offer_rows", None)
    if data is None or time.monotonic() - getattr(ctx, "offer_at", 0) > 8:
        ctx.offer_at = time.monotonic()

        def got(ok: bool, d) -> None:
            if ok and isinstance(d, dict) and d != getattr(ctx, "offer_rows", None):
                ctx.offer_rows = d
                if ctx.window.showing("themes") and getattr(ctx, "shop_tab", 0) == 4:
                    ctx.reload_page("themes")
        ec.online.ask("rb_market_offers", {}, got)
    if data is None:
        return lay.addWidget(Label(tr("Loading…"), 12, TEXT_DIM))

    def answer(o: dict, yes: bool) -> None:
        def done(ok: bool, d) -> None:
            if not ok:
                sfx.play("off")
                ctx.toast(tr(str(d)), "warn")
            else:
                sfx.play("on")
                ctx.toast(tr("Sold for {n} coins!", n=coins_text(o["price"])) if yes else tr("Offer refused"))
            ctx.offer_rows, ctx.mk_at = None, 0
            ec.refresh()
            QTimer.singleShot(400, ctx.reload_page)
        if yes:
            ctx.window.confirm(tr("Sell {name} to {who} for {n} coins?", name=item_name(o["item"]), who=o["from"],
                                  n=coins_text(o["price"])), lambda: ec.call("rb_market_answer", {"offer": o["offer"], "accept": True}, done),
                               yes=tr("Sell"))
        else:
            ec.call("rb_market_answer", {"offer": o["offer"], "accept": False}, done)
    lay.addWidget(heading(tr("Offers for your items")))
    if not data.get("to_me"):
        lay.addWidget(notice("coin", tr("No offers yet"), tr("When a player offers coins for one of your items, it shows up here."), page.W))
    for o in data.get("to_me") or []:
        w = ListingRow(ctx, {"item": o["item"], "price": o["price"], "seller": o["from"],
                             "estimate": o.get("asking")}, page.W)
        w.setToolTip(tr("{who} offers {n} coins (your price: {p})", who=o["from"], n=coins_text(o["price"]),
                        p=coins_text(o.get("asking") or 0)))
        lay.addWidget(w)
        line = hbox(spacing=6)
        no = Button(tr("Refuse"), "ghost", 28)
        yes = Button(tr("Accept {n}", n=coins_text(o["price"])), "primary", 28)
        no.clicked.connect(lambda _=False, x=o: answer(x, False))
        yes.clicked.connect(lambda _=False, x=o: answer(x, True))
        line.addWidget(no, 1)
        line.addWidget(yes, 2)
        lay.addLayout(line)
    lay.addWidget(heading(tr("Your offers")))
    if not data.get("mine"):
        lay.addWidget(notice("market", tr("No offers sent"), tr("Click an item in Buy, then Make an offer: the seller can accept or refuse it."), page.W))
    states = {"open": "Waiting", "taken": "Accepted", "refused": "Refused", "gone": "Closed"}
    for o in data.get("mine") or []:
        w = ListingRow(ctx, {"item": o["item"], "price": o["price"], "seller": tr(states.get(o["state"], "")),
                             "estimate": o.get("asking")}, page.W)
        if o["state"] == "open":
            w.clicked.connect(lambda x=o: ctx.window.confirm(tr("Take back this offer?"), lambda: ec.call(
                "rb_market_unoffer", {"offer": x["offer"]}, lambda _o, _d: (setattr(ctx, "offer_rows", None), ctx.reload_page())),
                yes=tr("Take back")))
        lay.addWidget(w)


# --------------------------------------------------------------------------- #
# Trading
# --------------------------------------------------------------------------- #
class TradeLink(QObject):
    """Keeps one trade in step with the server while it is open (asked every 1.5 s). If this stops (the app is
    closed, the internet is gone), the server ends the trade by itself after a minute."""
    changed = pyqtSignal()

    def __init__(self, ctx) -> None:
        super().__init__()
        self.ctx = ctx
        self.trade_id = ""
        self.data: dict = {}
        self.peek: dict = {}            # 4.0: the other player's tradeable items (look only)
        self.summary: dict = {}         # 4.0: what the server recorded once the trade is done
        self.view = 0                   # 4.0: 0 = your inventory, 1 = theirs
        self.shown_ready, self.shown_trade = (), ""
        self.got_at = 0.0
        self.busy = False
        self._sig = ""
        self._timer = QTimer(self)
        self._timer.setInterval(1500)
        self._timer.timeout.connect(self.poll)

    def open(self, trade_id: str) -> None:
        if trade_id and trade_id != self.trade_id:
            self.trade_id, self.data, self._sig = trade_id, {}, ""
            self.peek, self.summary, self.view = {}, {}, 0
        self._timer.start()
        self.poll()

    def close(self) -> None:
        self._timer.stop()
        self.trade_id, self.data, self._sig = "", {}, ""
        self.peek, self.summary, self.view = {}, {}, 0

    def close_if_left(self) -> None:
        w = self.ctx.window
        if self.finished() and not (w.showing("friends") and w.expanded):
            self.close()

    def finished(self) -> bool:
        """The trade is over (done or cancelled): only its summary is left to show."""
        return bool(self.trade_id) and self.data.get("state") in ("done", "cancelled")

    def poll(self) -> None:
        if not self.trade_id:
            return self._timer.stop()
        tid = self.trade_id

        def got(ok: bool, data) -> None:
            if tid != self.trade_id:
                return
            if not ok:
                if "rb_trade_gone" in str(data):
                    self.data = {"state": "cancelled", "why": "gone"}
                    self._timer.stop()
                    self.changed.emit()
                return
            was = self.data.get("state")
            self.data, self.got_at = data, time.monotonic()
            w = self.ctx.window
            if was == "asked" and data.get("state") == "open" and not (w.showing("friends") and w.expanded):
                self.ctx.notifier.push("trade", tr("TRADE"), tr("{name} accepted your trade", name=data.get(
                    "b" if data.get("me") == "a" else "a", "?")), "trade:" + tid)       # 4.6: you hear about it anywhere
            sig = str([data.get(k) for k in ("state", "version", "a_ready", "b_ready", "a_ok", "b_ok", "a_coins",
                                              "b_coins", "a_keys", "b_keys")]) + str(data.get("wait") is None)
            if data.get("state") in ("done", "cancelled"):
                self._timer.stop()
                self.ctx.econ.refresh()
            if sig != self._sig:
                self._sig = sig
                self.changed.emit()
        self.ctx.online.ask("rb_trade_get", {"trade": tid}, got, raw=True)

    def act(self, fn: str, args: dict, quiet: bool = False) -> None:
        if self.busy:
            return
        self.busy = True

        def back(ok: bool, data) -> None:
            self.busy = False
            if not ok and not quiet:
                sfx.play("off")
                self.ctx.toast(tr(str(data)), "warn")
            self.poll()
        self.ctx.econ.call(fn, dict(args, trade=self.trade_id), back)

    def wait_left(self) -> float:
        wait = self.data.get("wait")
        return 0.0 if wait is None else max(0.0, float(wait) - (time.monotonic() - self.got_at))


class Countdown(QWidget):
    """Both are ready: 5 seconds to look one last time, then Confirm lights up."""
    done = pyqtSignal()

    def __init__(self, link: TradeLink) -> None:
        super().__init__()
        self.link = link
        self.setFixedHeight(S(34))
        self._fired = False
        self._timer = QTimer(self)
        self._timer.setInterval(50)
        self._timer.timeout.connect(self._tick)

    def showEvent(self, _e) -> None:
        self._timer.start()

    def hideEvent(self, _e) -> None:
        self._timer.stop()

    def _tick(self) -> None:
        if self.link.wait_left() <= 0 and not self._fired:
            self._fired = True
            self.done.emit()
        self.update()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        left = self.link.wait_left()
        r = QRectF(self.rect()).adjusted(1, 3, -1, -3)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#FFFFFF", 0.06))
        p.drawRoundedRect(r, S(8), S(8))
        p.setBrush(alpha(GOLD_TEXT, 0.35))
        p.drawRoundedRect(QRectF(r.left(), r.top(), r.width() * (1 - min(1.0, left / 5.0)), r.height()), S(8), S(8))
        p.setPen(QColor(TEXT))
        p.setFont(font(11.5, QFont.Weight.Bold))
        p.drawText(r, int(Qt.AlignmentFlag.AlignCenter),
                   tr("Look one last time… {n}", n=int(math.ceil(left))) if left > 0 else tr("You can confirm now"))


# --------------------------------------------------------------------------- #
# 4.0: the trade screen: who is ready, both inventories (yours to add from, theirs to look at), and a summary
# --------------------------------------------------------------------------- #
READY_GREEN = "#5BE08A"
LOSS_RED = "#FF7A7A"


def paint_key(p: QPainter, c: QPointF, size: float, colour) -> None:
    """The key icon, `size` pixels tall, centred on c."""
    p.save()
    p.translate(c)
    p.scale(size / 20, size / 20)
    draw_icon(p, "key", QColor(colour))
    p.restore()


class ReadyPill(QWidget):
    """One player's state in the trade: NOT READY (dark), READY (green) or CONFIRMED (bright green). It flashes when
    the state has just changed, so a change on the other side is never missed."""

    def __init__(self, name: str, ready: bool, ok: bool, flash: bool) -> None:
        super().__init__()
        self.name, self.ready, self.ok = name, ready, ok
        self.setFixedHeight(S(32))
        self.setMinimumWidth(S(120))
        self._flash = Tween(self, 1.0 if flash else 0.0, self.update)
        if flash:
            QTimer.singleShot(30, lambda: self._flash.to(0.0, 900))

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(S(1), S(1), -S(1), -S(1))
        on = self.ready or self.ok
        green = QColor(READY_GREEN)
        f = self._flash.level
        if on:
            p.setPen(QPen(mix(green, QColor("#FFFFFF"), 0.4 * f), S(1.6)))
            p.setBrush(mix(QColor("#123A24"), green, 0.25 + (0.25 if self.ok else 0.0) + 0.3 * f))
        else:
            p.setPen(QPen(mix(QColor("#2A3238"), QColor("#FFFFFF"), 0.35 * f), S(1.2)))
            p.setBrush(QColor("#12171A"))
        p.drawRoundedRect(r, r.height() / 2, r.height() / 2)
        dot = QPointF(r.left() + S(14), r.center().y())
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#FFFFFF") if on else QColor("#46505A"))
        p.drawEllipse(dot, S(4), S(4))
        state = tr("CONFIRMED") if self.ok else tr("READY") if self.ready else tr("NOT READY")
        sf = font(10, QFont.Weight.ExtraBold)
        sw = QFontMetrics(sf).horizontalAdvance(state) + S(4)
        p.setFont(sf)
        p.setPen(QColor("#FFFFFF") if on else QColor(TEXT_FAINT))
        sr = QRectF(r.right() - sw - S(12), r.top(), sw, r.height())
        p.drawText(sr, int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight), state)
        nf = font(11, QFont.Weight.Bold)
        p.setFont(nf)
        p.setPen(QColor(TEXT) if on else QColor(TEXT_DIM))
        nr = QRectF(dot.x() + S(10), r.top(), sr.left() - dot.x() - S(16), r.height())
        p.drawText(nr, int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft),
                   QFontMetrics(nf).elidedText(self.name, Qt.TextElideMode.ElideRight, int(nr.width())))


class AmountRow(QWidget):
    """Coins and keys with their icons (never covered by a button), and the value on the right."""

    def __init__(self, coins: int, keys: int, worth: str = "", sign: str = "", colour: str = "",
                 skip_zero: bool = False) -> None:
        super().__init__()
        self.coins, self.keys, self.worth, self.sign, self.colour = coins, keys, worth, sign, colour
        self.skip_zero = skip_zero              # the trade summary: only what moved
        self.setFixedHeight(S(24))

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        h = self.height()
        f = font(11.5, QFont.Weight.Bold)
        p.setFont(f)
        fm = QFontMetrics(f)
        x = S(2)
        if self.coins or not self.skip_zero:
            paint_coin(p, QPointF(x + S(8), h / 2), S(7.5))
            x += S(20)
            text = self.sign + coins_text(self.coins)
            p.setPen(QColor(self.colour or GOLD_TEXT))
            p.drawText(QRectF(x, 0, fm.horizontalAdvance(text) + S(4), h), int(Qt.AlignmentFlag.AlignVCenter), text)
            x += fm.horizontalAdvance(text) + S(16)
        if self.keys or not self.skip_zero:
            paint_key(p, QPointF(x + S(8), h / 2), S(16), self.colour or ui.accent)
            x += S(20)
            text = self.sign + str(self.keys)
            p.setPen(QColor(self.colour) if self.colour else ui.accent)
            p.drawText(QRectF(x, 0, fm.horizontalAdvance(text) + S(4), h), int(Qt.AlignmentFlag.AlignVCenter), text)
            x += fm.horizontalAdvance(text) + S(10)
        if self.worth:
            wf = font(10.5)
            p.setFont(wf)
            p.setPen(QColor(TEXT_DIM))
            wr = QRectF(x, 0, self.width() - x - S(2), h)
            p.drawText(wr, int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                       QFontMetrics(wf).elidedText(self.worth, Qt.TextElideMode.ElideLeft, int(wr.width())))


class InvSwitch(QWidget):
    """YOUR INVENTORY | NAME'S INVENTORY: a two-way switch. The side shown is lit, the other is dark."""
    changed = pyqtSignal(int)

    def __init__(self, labels: list, index: int) -> None:
        super().__init__()
        self.labels, self.index = labels, index
        self.setFixedHeight(S(36))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._pos = Tween(self, float(index), self.update)
        self._hover = -1
        self.setMouseTracking(True)

    def mouseMoveEvent(self, e) -> None:
        i = 0 if e.position().x() < self.width() / 2 else 1
        if i != self._hover:
            self._hover = i
            self.update()

    def leaveEvent(self, _e) -> None:
        self._hover = -1
        self.update()

    def mousePressEvent(self, e) -> None:
        i = 0 if e.position().x() < self.width() / 2 else 1
        if i != self.index:
            sfx.play("pick")
            self.index = i
            self._pos.to(float(i), 280)
            self.changed.emit(i)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(S(1), S(1), -S(1), -S(1))
        p.setPen(QPen(QColor("#252C31"), S(1.2)))
        p.setBrush(QColor("#0B0F11"))
        p.drawRoundedRect(r, S(10), S(10))
        half = r.width() / 2
        knob = QRectF(r.left() + S(3) + self._pos.level * half, r.top() + S(3), half - S(6), r.height() - S(6))
        g = QLinearGradient(knob.topLeft(), knob.bottomLeft())
        g.setColorAt(0.0, mix(ui.accent, QColor("#FFFFFF"), 0.18))
        g.setColorAt(1.0, ui.accent)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawRoundedRect(knob, S(8), S(8))
        f = font(10.5, QFont.Weight.ExtraBold)
        p.setFont(f)
        fm = QFontMetrics(f)
        on_text = QColor("#0B0E10") if ui.accent.lightnessF() > 0.55 else QColor("#FFFFFF")
        for i, text in enumerate(self.labels):
            cell = QRectF(r.left() + i * half + S(6), r.top(), half - S(12), r.height())
            near = max(0.0, 1.0 - abs(self._pos.level - i))         # 1 = this side is lit
            dark = QColor("#4A535B") if i != self._hover else QColor("#7A848C")
            p.setPen(mix(dark, on_text, near))
            p.drawText(cell, int(Qt.AlignmentFlag.AlignCenter),
                       fm.elidedText(text, Qt.TextElideMode.ElideRight, int(cell.width())))


class SlideBox(QWidget):
    """Holds one page of content; a new one slides in from the side while the old one slides out."""

    def __init__(self, width: int) -> None:
        super().__init__()
        self.setFixedWidth(width)
        self.cur = self.old = None
        self._dir = 1
        self._t = Tween(self, 1.0, self._place)

    def put(self, w: QWidget, direction: int = 0) -> None:
        w.setParent(self)
        w.setFixedWidth(self.width())
        if w.layout() is not None:
            w.layout().activate()
            w.setFixedHeight(w.layout().sizeHint().height())
        self._t.stop()
        if self.old is not None:                     # a slide still running: finish it at once
            self.old.deleteLater()
            self.old = None
        self.old, self.cur = self.cur, w
        w.show()
        if self.old is None or not direction:
            if self.old is not None:
                self.old.deleteLater()
                self.old = None
            w.move(0, 0)
            self._height(w.height())
            return
        self._dir = direction
        self._height(max(w.height(), self.old.height()))
        self._t._value = 0.0
        self._place()
        self._t.to(1.0, 300)

    def _height(self, h: int) -> None:
        if h != self.height():
            self.setFixedHeight(h)
            refit_scroll(self)

    def _place(self) -> None:
        if self.cur is None:
            return
        v = self._t.level
        self.cur.move(int((1.0 - v) * self._dir * self.width()), 0)
        if self.old is not None:
            self.old.move(int(-v * self._dir * self.width()), 0)
            if v >= 1.0:
                self.old.deleteLater()
                self.old = None
                self._height(self.cur.height())


def _trade_pool(page, link, mine: list, offer) -> QWidget:
    """Your side of the switch: your tradeable items, click one to add it."""
    ctx, ec = page.ctx, page.ctx.econ
    box = QWidget()
    lay = vbox(box, 6)
    offered = {r["id"] for r in mine}
    pool = [i for i in ec.items if not i.get("locked") and i["id"] not in offered
            and ec.info(i["item"]).get("tradeable") and ec.info(i["item"]).get("kind") != "coupon"]
    pool = sort_items(ctx, pool, lambda i: i["item"])          # 5.1: sorted and filtered like the inventory
    lay.addWidget(sort_bar(ctx, lambda: ctx.reload_page()))
    if not pool:
        lay.addWidget(Label(tr("Nothing more to add."), 11.5, TEXT_DIM))
        return box
    grid = ItemGrid(ctx, [{"item": i["item"], "text": coins_text(value_of(ctx, i["item"])), "worth": value_of(ctx, i["item"])}
                          for i in pool], page.W, 6, 64, moving=False, tips=True)   # 4.6: every item, not only the first 60

    def add(i: int) -> None:
        if len(mine) >= 8:
            return ctx.toast(tr("8 items at most"), "warn")
        sfx.play("pick")
        offer([r["id"] for r in mine] + [pool[i]["id"]], None)
    grid.picked.connect(add)
    lay.addWidget(grid)
    return box


def _trade_peek(page, link, them: str) -> QWidget:
    """Their side of the switch: what they could trade. Only to look at, nothing here can be changed."""
    ctx = page.ctx
    box = QWidget()
    lay = vbox(box, 6)
    pk = link.peek if link.peek.get("trade") == link.trade_id else {}
    if "items" not in pk:
        lay.addWidget(Label(tr("Loading {name}'s items…", name=them), 11.5, TEXT_DIM))
        return box
    items = sort_items(ctx, list(pk["items"]), lambda i: i["item"])     # 5.1: sorted and filtered too
    lay.addWidget(sort_bar(ctx, lambda: ctx.reload_page()))
    if not items:
        lay.addWidget(Label(tr("{name} has nothing to trade.", name=them), 11.5, TEXT_DIM, wrap_w=page.W))
        return box
    lay.addWidget(Label(tr("Look only: ask {name} in the chat to add something.", name=them), 10.5, TEXT_DIM,
                        wrap_w=page.W))
    grid = ItemGrid(ctx, [{"item": i["item"], "text": coins_text(int(i.get("worth") or 0)), "worth": int(i.get("worth") or 0),
                           "mark": "offered" if i.get("offered") else ""} for i in items], page.W, 6, 64, moving=False,
                    tips=True)                       # 4.6: a click shows the item's card
    lay.addWidget(grid)
    return box


def _trade_summary(page, lay, link, them: str) -> None:
    """After the trade: what you got and what you gave, as the server recorded it."""
    ctx = page.ctx
    sm = link.summary if link.summary.get("id") == link.trade_id else None
    if sm is None:
        lay.addWidget(Label(tr("Trade done! Loading the summary…"), 13, READY_GREEN, bold=True, wrap_w=page.W))
        tid = link.trade_id

        def got(ok: bool, data) -> None:
            if tid != link.trade_id:
                return
            link.summary = data if ok and isinstance(data, dict) else {"id": tid, "failed": True}
            link.summary["id"] = tid
            ctx.reload_page("friends")
        ctx.online.ask("rb_trade_summary", {"trade": tid}, got, raw=True)
        return
    lay.addWidget(Label(tr("Trade complete ✓"), 17, READY_GREEN, bold=True))
    if sm.get("failed"):
        lay.addWidget(Label(tr("The items are in your Inventory."), 12, TEXT_DIM, wrap_w=page.W))
        return
    worth_got = sum(int(i.get("worth") or 0) for i in sm.get("got") or []) + int(sm.get("coins_got") or 0)
    worth_gave = sum(int(i.get("worth") or 0) for i in sm.get("gave") or []) + int(sm.get("coins_gave") or 0)

    def part(title: str, rows: list, coins: int, keys: int, sign: str, colour: str) -> None:
        head = hbox(spacing=6)
        head.addWidget(Label(title, 12.5, colour, bold=True), 1)
        lay.addLayout(head)
        if rows:
            lay.addWidget(ItemGrid(ctx, [{"item": r["item"], "text": sign + coins_text(int(r.get("worth") or 0)),
                                          "worth": int(r.get("worth") or 0)} for r in rows], page.W, 6, 64, moving=False,
                                   tips=True))
        elif not coins and not keys:
            lay.addWidget(Label(tr("Nothing"), 11, TEXT_FAINT))
        if coins or keys:
            lay.addWidget(AmountRow(coins, keys, sign=sign, colour=colour, skip_zero=True))
    part(tr("You received from {name}", name=sm.get("other") or them), sm.get("got") or [],
         int(sm.get("coins_got") or 0), int(sm.get("keys_got") or 0), "+", READY_GREEN)
    part(tr("You gave"), sm.get("gave") or [], int(sm.get("coins_gave") or 0), int(sm.get("keys_gave") or 0),
         "−", LOSS_RED)
    net = worth_got - worth_gave
    lay.addWidget(Label(tr("Value change: about {v}", v=("+" if net >= 0 else "−") + coins_text(abs(net))), 11.5,
                        READY_GREEN if net >= 0 else LOSS_RED, bold=True))
    lay.addWidget(Label(tr("Everything is already in your Inventory."), 10.5,
                        TEXT_DIM, wrap_w=page.W))


def build_trade(page, lay) -> None:
    """The trade screen (inside the Social tab)."""
    ctx, ec, link = page.ctx, page.ctx.econ, page.ctx.trade
    d = link.data
    if not d:
        lay.addWidget(Label(tr("Opening the trade…"), 12, TEXT_DIM))
        return
    me = d.get("me", "a")
    other = "b" if me == "a" else "a"
    them = d.get(other, "?")
    state = d.get("state")
    top = hbox(spacing=8)
    top.addWidget(Label(tr("Trade with {name}", name=them), 15, bold=True), 1)
    leave = Button(tr("Close") if state in ("done", "cancelled") else tr("Cancel trade"), "ghost", 28)

    def stop() -> None:
        if state in ("asked", "open"):
            ec.call("rb_trade_cancel", {"trade": link.trade_id}, lambda _o, _d: ec.refresh())
        link.close()
        ctx.reload_page()
    leave.clicked.connect(stop)
    top.addWidget(leave)
    lay.addLayout(top)
    if state in ("asked", "open"):
        lock_strip(ctx, lay, "trading", page.W)                     # 4.0: paused by the admins
    if state == "asked":
        lay.addWidget(Label(tr("Waiting for {name} to accept… (5 minutes at most)", name=them), 12, TEXT_DIM, wrap_w=page.W))
        return
    if state == "done":
        return _trade_summary(page, lay, link, them)
    if state == "cancelled":
        why = {"expired": "The trade ended: a user left or took too long.", "failed": "The trade could not be done: nothing was exchanged."
               }.get(d.get("why"), "The trade was cancelled. Nothing was exchanged.")
        lay.addWidget(Label(tr(why), 12.5, "#FF9A9A", wrap_w=page.W))
        return
    items = d.get("items") or []
    mine = [i for i in items if i.get("side") == me]
    theirs = [i for i in items if i.get("side") == other]
    my_coins, their_coins = int(d.get(me + "_coins") or 0), int(d.get(other + "_coins") or 0)
    my_keys, their_keys = int(d.get(me + "_keys") or 0), int(d.get(other + "_keys") or 0)      # 3.2: keys can be traded
    my_ready, their_ready = bool(d.get(me + "_ready")), bool(d.get(other + "_ready"))
    my_ok, their_ok = bool(d.get(me + "_ok")), bool(d.get(other + "_ok"))
    give = sum(int(i.get("estimate") or 0) for i in mine) + my_coins
    get = sum(int(i.get("estimate") or 0) for i in theirs) + their_coins
    version = int(d.get("version") or 0)

    def offer(ids: list, coins, keys: int = None) -> None:
        link.act("rb_trade_offer", {"items": ids, "coins": my_coins if coins is None else coins,
                                    "keys": my_keys if keys is None else keys})

    # who is ready: both players, side by side, flashing when it just changed
    now = (my_ready, my_ok, their_ready, their_ok)
    was = link.shown_ready if link.shown_trade == link.trade_id else now
    link.shown_ready, link.shown_trade = now, link.trade_id
    pills = hbox(spacing=8)
    pills.addWidget(ReadyPill(tr("You"), my_ready, my_ok, was[:2] != now[:2]), 1)
    pills.addWidget(ReadyPill(them, their_ready, their_ok, was[2:] != now[2:]), 1)
    lay.addLayout(pills)

    def side(title: str, rows: list, coins: int, total: int, removable: bool, keys: int) -> None:
        lay.addWidget(Label(title, 12, bold=True))
        entries = [{"item": r["item"], "text": coins_text(int(r.get("estimate") or 0)), "worth": int(r.get("estimate") or 0)}
                   for r in rows]
        entries += [{"empty": True}] * (8 - len(entries))
        grid = ItemGrid(ctx, entries, page.W, 8, 60, tips=not removable)
        if removable:
            grid.setToolTip(tr("Click an item to take it back"))
            grid.picked.connect(lambda i: offer([r["id"] for k, r in enumerate(mine) if k != i], None))
        lay.addWidget(grid)
        lay.addWidget(AmountRow(coins, keys, tr("Worth about {v}", v=coins_text(total))))
        if not removable:
            return
        pass
        if ec.coins > 0:
            cs = AmountSlider(tr("Coins"), 0, int(ec.coins), coins, coins_text, label_w=50)
            cs.released.connect(lambda v: offer([r["id"] for r in mine], int(v)) if int(v) != coins else None)
            lay.addWidget(cs)
        if ec.keys > 0:
            ks = AmountSlider(tr("Keys"), 0, min(99, int(ec.keys)), keys, str, label_w=50)
            ks.released.connect(lambda v: offer([r["id"] for r in mine], None, int(v)) if int(v) != keys else None)
            lay.addWidget(ks)
    side(tr("You give"), mine, my_coins, give, True, my_keys)
    side(tr("{name} gives", name=them), theirs, their_coins, get, False, their_keys)
    if give > max(get * 2, get + 500):
        lay.addWidget(Label(tr("Uneven trade: you give much more than you get."), 11.5, "#FFB020",
                            bold=True, wrap_w=page.W))
    if my_ready and their_ready:
        cd = Countdown(link)
        lay.addWidget(cd)
        line = hbox(spacing=6)
        back = Button(tr("Not ready"), "ghost", 36)
        back.clicked.connect(lambda: link.act("rb_trade_ready", {"ready": False, "seen_version": version}))
        go = Button(tr("Waiting for {name}…", name=them) if my_ok else tr("Confirm trade"), "primary", 36)
        go.setEnabled(link.wait_left() <= 0 and not my_ok)
        cd.done.connect(lambda: go.setEnabled(not my_ok))
        go.clicked.connect(lambda: (go.setEnabled(False), link.act("rb_trade_confirm", {"seen_version": version})))
        line.addWidget(back, 1)
        line.addWidget(go, 2)
        lay.addLayout(line)
        if their_ok and not my_ok:
            lay.addWidget(Label(tr("{name} confirmed. Your turn.", name=them), 11, READY_GREEN))
    else:
        ready = Button(tr("Not ready") if my_ready else tr("Ready"), "ghost" if my_ready else "primary", 36)
        ready.clicked.connect(lambda: link.act("rb_trade_ready", {"ready": not my_ready, "seen_version": version}))
        lay.addWidget(ready)
    lay.addWidget(Label(tr("Any change to the offer sets both players back to Not ready."), 10.5,
                        TEXT_DIM, wrap_w=page.W))

    # the two inventories
    switch = InvSwitch([tr("YOUR INVENTORY"), tr("{name}'S INVENTORY", name=them.upper())], 1 if link.view else 0)
    lay.addWidget(switch)
    box = SlideBox(page.W)
    lay.addWidget(box)

    def fill(direction: int = 0) -> None:
        try:
            box.put(_trade_peek(page, link, them) if link.view else _trade_pool(page, link, mine, offer), direction)
        except RuntimeError:                         # the page was rebuilt meanwhile
            pass

    def fetch() -> None:
        pk = link.peek
        if pk.get("trade") == link.trade_id and pk.get("version") == version and "items" in pk:
            return
        tid = link.trade_id

        def got(ok: bool, data) -> None:
            if tid != link.trade_id or not ok or not isinstance(data, dict):
                return
            link.peek = {"trade": tid, "version": version, "items": data.get("items") or []}
            if link.view:
                fill()
        ctx.online.ask("rb_trade_inventory", {"trade": tid}, got, raw=True)

    def flip(i: int) -> None:
        link.view = i
        fill(1 if i else -1)
        if i:
            fetch()
    switch.changed.connect(flip)
    fill()
    if link.view:
        fetch()


# ==================================================================================================
# SECTION: games2
# ==================================================================================================
import math
import random
import time

from PyQt6.QtCore import QPointF, QRectF, QTimer, Qt
from PyQt6.QtGui import QColor, QFont, QFontMetrics, QImage, QLinearGradient, QPainter, QPainterPath, QPen, QRadialGradient
from PyQt6.QtWidgets import QGridLayout, QWidget


TAP_MODES = [("normal", "Normal", "The classic: faster and faster."), ("rush", "Rush", "Much faster, many more notes."),
             ("holds", "Long notes", "Lots of notes to hold down."), ("chords", "Chords", "Two notes at once, very often.")]
MEM_THEMES = [("shapes", "Shapes"), ("numbers", "Numbers"), ("colours", "Colours")]
LANE_KEYS = [Qt.Key.Key_D, Qt.Key.Key_F, Qt.Key.Key_J, Qt.Key.Key_K]
LANE_NAMES = ["D", "F", "J", "K"]
LANE_COLOURS = ["#FF5C8A", "#4FC3FF", "#5BE08A", "#FFB547"]


def window_text(day: dict) -> str:
    """'Next 2 hours: 40 / 150 coins' for the mini game limits."""
    day = day or {}
    if int(day.get("cap") or 0) >= 1_000_000:           # 5.11: no daily limit any more
        return tr("Today: {n} coins won", n=coins_text(int(day.get("paid") or 0)))
    if day.get("daily"):                                 # 5.4: one simple limit a day per game
        return tr("Today: {n} / {cap} coins", n=coins_text(int(day.get("paid") or 0)),
                  cap=coins_text(int(day.get("cap") or 1500)))
    return tr("These 2 hours: {n} / {cap} coins", n=coins_text(int(day.get("paid") or 0)),
              cap=coins_text(int(day.get("cap") or 150)))


# ================================================================ Beat Tap 2
class BeatRush(QWidget):
    """Four lanes. Notes fall to the line: press D F J K (or click the lane) as they touch it. Long notes are held.
    Notes come faster and faster; hits in a row build a combo."""
    LEAD = 1.15                                   # seconds a note takes to fall

    def __init__(self, page, on_end=None) -> None:
        super().__init__()
        self.page, self.ctx, self.on_end = page, page.ctx, on_end
        self.setFixedSize(page.W, S(320))
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.state = "idle"                       # idle -> wait -> count -> play -> send -> done
        self.chart: list = []
        self.round = ""
        self.hits: dict = {}                      # note -> {"i", "t", "u"}
        self.judged: dict = {}                    # note -> "p" / "g" / "o" / "m"
        self.holding: dict = {}                   # lane -> note being held
        self.pressed = [0.0] * 4                  # when each lane was last pressed (for the glow)
        self.pops: list = []
        self.sparks: list = []
        self.combo = self.best = 0
        self.t0 = 0.0
        self.result: dict = {}
        self.duel = False
        self._frames = QTimer(self)
        self._frames.setTimerType(Qt.TimerType.PreciseTimer)
        self._frames.setInterval(16)
        self._frames.timeout.connect(self._tick)
        pass
        self.keys = KeyPoll(["D", "F", "J", "K", "Space"], self._key, lambda: self.state in ("count", "play"))
        self.keys.setParent(self)
        self.on_space = None                               # the page's Start button

    def _key(self, name: str, down: bool) -> None:
        if name == "Space":
            if down and self.state in ("idle", "done") and not self.duel:
                (self.on_space or self.start)()
            return
        lane = "DFJK".index(name)
        if down:
            self.pressed[lane] = time.monotonic()
            if self.state == "play":
                self._press(lane)
        else:
            self._release(lane)

    # -- rounds
    def start(self) -> None:
        if self.state in ("wait", "count", "play", "send"):
            return
        self.state = "wait"
        self.update()
        sent = time.monotonic()

        def got(ok: bool, data) -> None:
            if not ok or not isinstance(data, dict):
                self.state = "idle"
                self.update()
                return self.ctx.toast(tr(str(data)), "warn")
            self.begin(data, sent)
        mode = TAP_MODES[int(getattr(self.ctx, "tap_mode", 0) or 0)][0]
        self.ctx.econ.call("rb_tap_start", {"mode": mode}, got)

    def begin(self, data: dict, sent: float, duel: bool = False) -> None:
        now = time.monotonic()
        self.t0 = sent + (now - sent) / 2              # the server started its clock about half-way
        self.round, self.chart, self.duel = data["round"], list(data.get("chart") or []), duel
        self.hits, self.judged, self.holding, self.pops, self.sparks = {}, {}, {}, [], []
        self.combo = self.best = 0
        self.result = {}
        self.state = "play"
        if not self.keys.live:                         # 4.5: on Windows the keys are read directly (KeyPoll)
            self.ctx.window.allow_keys(True)
            self.setFocus(Qt.FocusReason.OtherFocusReason)
            self.grabKeyboard()
        self._frames.start()

    def abort(self) -> None:
        self._frames.stop()
        self.state = "idle"
        self.releaseKeyboard()

    def hideEvent(self, _e) -> None:
        self._frames.stop()
        self.releaseKeyboard()

    def _ms(self) -> float:
        return (time.monotonic() - self.t0) * 1000

    def _end_ms(self) -> float:
        if not self.chart:
            return 1.0
        return max(n["t"] + n["h"] for n in self.chart) + 900

    def _tick(self) -> None:
        if self.state == "play":
            ms = self._ms()
            for i, n in enumerate(self.chart):           # notes that went past without a press
                if i not in self.judged and ms > n["t"] + 260:
                    self.judged[i] = "m"
                    self.combo = 0
                    self._pop(n["l"], tr("MISS"), "#FF5C6C")
            for lane, i in list(self.holding.items()):   # holds that reached their end
                n = self.chart[i]
                if ms >= n["t"] + n["h"]:
                    self.hits[i]["u"] = int(ms)
                    del self.holding[lane]
                    self._burst(lane, LANE_COLOURS[lane], 10)
            if ms > self._end_ms():
                self._send()
        self.update()
        if self.state in ("idle", "done") and not self.pops and not self.sparks:
            self._frames.stop()

    def _send(self) -> None:
        self.state = "send"
        self.releaseKeyboard()
        for lane, i in list(self.holding.items()):
            self.hits[i]["u"] = int(self._ms())
        self.holding = {}
        hits = list(self.hits.values())

        def got(ok: bool, data) -> None:
            self.state = "done"
            if not ok:
                self.ctx.toast(tr(str(data)), "warn")
                data = {}
            self.result = data if isinstance(data, dict) else {}
            if int(self.result.get("paid") or 0):
                sfx.play("on")
            self._frames.start()
            if self.on_end:
                self.on_end(self.result)
        self.ctx.econ.call("rb_tap_finish", {"round": self.round, "hits": hits}, got)

    # -- input
    def _press(self, lane: int) -> None:
        if self.state != "play":
            return
        ms = self._ms()
        self.pressed[lane] = time.monotonic()
        best, gap = -1, 1e9
        for i, n in enumerate(self.chart):
            if n["l"] != lane or i in self.judged:
                continue
            d = abs(ms - n["t"])
            if d <= 260 and d < gap:
                best, gap = i, d
            if n["t"] > ms + 300:
                break
        if best < 0:
            return
        n = self.chart[best]
        self.hits[best] = {"i": best, "t": int(ms)}
        kind, text, col = (("p", "PERFECT", "#5BE08A") if gap <= 80 else
                           (("g", "GREAT", "#4FC3FF") if gap <= 160 else ("o", "GOOD", GOLD_TEXT)))
        self.judged[best] = kind
        self.combo += 1
        self.best = max(self.best, self.combo)
        if n["h"]:
            self.holding[lane] = best
        sfx.play("pick")
        self._pop(lane, tr(text), col)
        self._burst(lane, LANE_COLOURS[lane], 14 if kind == "p" else 8)

    def _release(self, lane: int) -> None:
        if lane in self.holding:
            i = self.holding.pop(lane)
            self.hits[i]["u"] = int(self._ms())

    def keyPressEvent(self, e) -> None:
        if e.isAutoRepeat() or self.keys.live:
            return
        if e.key() in LANE_KEYS:
            self._press(LANE_KEYS.index(e.key()))
        elif e.key() in (Qt.Key.Key_Space, Qt.Key.Key_Return) and self.state in ("idle", "done") and not self.duel:
            self.start()
        else:
            super().keyPressEvent(e)

    def keyReleaseEvent(self, e) -> None:
        if not e.isAutoRepeat() and not self.keys.live and e.key() in LANE_KEYS:
            self._release(LANE_KEYS.index(e.key()))

    def _lane_at(self, x: float) -> int:
        return max(0, min(3, int((x - self._board().left()) / (self._board().width() / 4))))

    def mousePressEvent(self, e) -> None:
        e.accept()
        self.setFocus()
        if e.button() == Qt.MouseButton.LeftButton:
            self._mouse_lane = self._lane_at(e.position().x())
            self._press(self._mouse_lane)

    def mouseReleaseEvent(self, e) -> None:
        lane = getattr(self, "_mouse_lane", None)
        if lane is not None:
            self._release(lane)
            self._mouse_lane = None

    # -- effects
    def _pop(self, lane: int, text: str, col: str) -> None:
        self.pops.append((lane, time.monotonic(), text, col))

    def _burst(self, lane: int, col: str, n: int) -> None:
        b = self._board()
        x = b.left() + b.width() / 4 * (lane + 0.5)
        y = self._line_y()
        now = time.monotonic()
        for _ in range(n):
            a = random.uniform(math.pi * 1.05, math.pi * 1.95)
            v = random.uniform(S(60), S(170))
            self.sparks.append((x, y, math.cos(a) * v, math.sin(a) * v, now, col))

    # -- drawing
    def _board(self) -> QRectF:
        return QRectF(self.rect()).adjusted(S(6), S(6), -S(6), -S(6))

    def _line_y(self) -> float:
        return self._board().bottom() - S(44)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        b = self._board()
        now = time.monotonic()
        ms = self._ms() if self.state in ("play", "send") else 0.0
        # background: dark, with a soft pulse on the beat once it gets going
        g = QLinearGradient(b.topLeft(), b.bottomLeft())
        g.setColorAt(0, QColor("#07090C"))
        g.setColorAt(1, QColor("#10141A"))
        p.setPen(QPen(alpha("#FFFFFF", 0.08), 1))
        p.setBrush(g)
        p.drawRoundedRect(b, S(12), S(12))
        lw = b.width() / 4
        line = self._line_y()
        speed = (line - b.top()) / (self.LEAD * 1000)
        for lane in range(4):
            x = b.left() + lw * lane
            col = QColor(LANE_COLOURS[lane])
            glow = max(0.0, 1 - (now - self.pressed[lane]) / 0.25)
            lg = QLinearGradient(QPointF(0, b.top()), QPointF(0, line))
            lg.setColorAt(0, alpha(col, 0.0))
            lg.setColorAt(1, alpha(col, 0.07 + 0.22 * glow))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(lg)
            p.drawRect(QRectF(x + 1, b.top() + S(4), lw - 2, line - b.top()))
            if lane:
                p.setPen(QPen(alpha("#FFFFFF", 0.05), 1))
                p.drawLine(QPointF(x, b.top() + S(8)), QPointF(x, b.bottom() - S(8)))
            # the key under each lane
            key = QRectF(x + lw / 2 - S(16), line + S(10), S(32), S(24))
            p.setPen(QPen(alpha(col, 0.35 + 0.65 * glow), S(1.4)))
            p.setBrush(alpha(col, 0.08 + 0.35 * glow))
            p.drawRoundedRect(key, S(6), S(6))
            p.setPen(QColor(TEXT) if glow > 0.2 else alpha(col, 0.9))
            p.setFont(font(11, QFont.Weight.ExtraBold))
            p.drawText(key, int(Qt.AlignmentFlag.AlignCenter), LANE_NAMES[lane])
        # the hit line
        p.setPen(QPen(alpha(ui.accent, 0.9), S(2.2)))
        p.drawLine(QPointF(b.left() + S(6), line), QPointF(b.right() - S(6), line))
        # notes
        if self.state in ("play", "send"):
            for i, n in enumerate(self.chart):
                dt = n["t"] - ms
                if dt > self.LEAD * 1000 + 50:
                    break
                lane, col = n["l"], QColor(LANE_COLOURS[n["l"]])
                held = self.holding.get(lane) == i
                if self.judged.get(i) not in (None, "m") and not held and not (n["h"] and i in self.hits and "u" not in self.hits[i]):
                    continue
                y = line - dt * speed
                x = b.left() + lw * lane
                if n["h"]:
                    top = line - (n["t"] + n["h"] - ms) * speed
                    bottom = line if held else y
                    if bottom > b.top():
                        tail = QRectF(x + lw * 0.34, max(b.top(), top), lw * 0.32, max(0.0, bottom - max(b.top(), top)))
                        p.setPen(Qt.PenStyle.NoPen)
                        p.setBrush(alpha(col, 0.75 if held else 0.4))
                        p.drawRoundedRect(tail, S(4), S(4))
                    if held:
                        continue
                if self.judged.get(i) == "m":
                    p.setOpacity(max(0.0, 1 + dt / 260))
                head = QRectF(x + S(6), y - S(8), lw - S(12), S(16))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha(col, 0.28))
                p.drawRoundedRect(head.adjusted(-S(3), -S(3), S(3), S(3)), S(9), S(9))
                hg = QLinearGradient(head.topLeft(), head.bottomLeft())
                hg.setColorAt(0, mix(col, QColor("#FFFFFF"), 0.45))
                hg.setColorAt(1, col)
                p.setBrush(hg)
                p.drawRoundedRect(head, S(7), S(7))
                p.setOpacity(1.0)
        # sparks and words
        keep = []
        for x, y, vx, vy, born, col in self.sparks:
            age = now - born
            if age < 0.5:
                keep.append((x, y, vx, vy, born, col))
                p.setOpacity(1 - age / 0.5)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor(col))
                p.drawEllipse(QPointF(x + vx * age, y + vy * age + S(220) * age * age), S(2.2), S(2.2))
        self.sparks = keep
        p.setOpacity(1.0)
        keep = []
        for lane, born, text, col in self.pops:
            age = now - born
            if age < 0.6:
                keep.append((lane, born, text, col))
                p.setOpacity(1 - age / 0.6)
                p.setPen(QColor(col))
                p.setFont(font(10, QFont.Weight.ExtraBold))
                x = b.left() + lw * lane
                p.drawText(QRectF(x - S(10), line - S(46) - S(18) * age, lw + S(20), S(16)), int(Qt.AlignmentFlag.AlignCenter), text)
        self.pops = keep
        p.setOpacity(1.0)
        if self.state in ("play", "send"):
            if self.combo >= 5:                                     # combo counter
                p.setPen(alpha("#FFFFFF", 0.85))
                p.setFont(font(24 + min(10, self.combo // 10 * 2), QFont.Weight.Black))
                p.drawText(QRectF(b.left(), b.top() + S(30), b.width(), S(40)), int(Qt.AlignmentFlag.AlignCenter), str(self.combo))
                p.setPen(alpha(ui.accent, 0.9))
                p.setFont(font(9, QFont.Weight.Bold))
                p.drawText(QRectF(b.left(), b.top() + S(68), b.width(), S(14)), int(Qt.AlignmentFlag.AlignCenter), tr("COMBO"))
            bar = QRectF(b.left() + S(10), b.top() + S(8), b.width() - S(20), S(4))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#FFFFFF", 0.08))
            p.drawRoundedRect(bar, S(2), S(2))
            p.setBrush(ui.accent)
            p.drawRoundedRect(QRectF(bar.left(), bar.top(), bar.width() * min(1.0, ms / self._end_ms()), bar.height()), S(2), S(2))
        if self.state in ("idle", "wait", "send", "done"):
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#000000", 0.55))
            p.drawRoundedRect(b, S(12), S(12))
            self._draw_card(p, b)

    def _draw_card(self, p: QPainter, b: QRectF) -> None:
        c = b.center()
        if self.state == "done" and self.result:
            res = self.result
            pct = int(res.get("pct") or 0)
            p.setPen(QColor(TEXT))
            p.setFont(font(26, QFont.Weight.Black))
            p.drawText(QRectF(b.left(), c.y() - S(96), b.width(), S(36)), int(Qt.AlignmentFlag.AlignCenter), f"{pct}%")
            grade = "S" if pct >= 95 else "A" if pct >= 85 else "B" if pct >= 70 else "C" if pct >= 50 else "D"
            p.setPen(QColor({"S": GOLD_TEXT, "A": "#5BE08A", "B": "#4FC3FF", "C": TEXT_DIM, "D": "#FF5C6C"}[grade]))
            p.setFont(font(13, QFont.Weight.ExtraBold))
            p.drawText(QRectF(b.left(), c.y() - S(60), b.width(), S(18)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Grade {g}", g=grade) + "  ·  " + tr("Best combo {n}", n=res.get("combo", 0)))
            p.setFont(font(10, QFont.Weight.DemiBold))
            parts = [("PERFECT", res.get("perfect", 0), "#5BE08A"), ("GREAT", res.get("great", 0), "#4FC3FF"),
                     ("GOOD", res.get("good", 0), GOLD_TEXT), ("MISS", res.get("miss", 0), "#FF5C6C")]
            w = b.width() / 4
            for k, (name, n, col) in enumerate(parts):
                r = QRectF(b.left() + w * k, c.y() - S(34), w, S(30))
                p.setPen(QColor(col))
                p.drawText(QRectF(r.left(), r.top(), r.width(), S(14)), int(Qt.AlignmentFlag.AlignCenter), tr(name))
                p.setPen(QColor(TEXT))
                p.drawText(QRectF(r.left(), r.top() + S(14), r.width(), S(16)), int(Qt.AlignmentFlag.AlignCenter), str(n))
            paid = int(res.get("paid") or 0)
            p.setPen(QColor(GOLD_TEXT if paid else TEXT_DIM))
            p.setFont(font(20, QFont.Weight.ExtraBold))
            text = tr("Duel score sent") if res.get("duel") else ("+" + coins_text(paid) if paid else tr("No coins this time"))
            p.drawText(QRectF(b.left(), c.y() + S(6), b.width(), S(30)), int(Qt.AlignmentFlag.AlignCenter), text)
            if res.get("day"):
                p.setPen(QColor(TEXT_DIM))
                p.setFont(font(10, QFont.Weight.DemiBold))
                p.drawText(QRectF(b.left(), c.y() + S(40), b.width(), S(16)), int(Qt.AlignmentFlag.AlignCenter), window_text(res["day"]))
            return
        p.setPen(QColor(TEXT))
        p.setFont(font(15, QFont.Weight.Bold))
        text = {"wait": tr("Get ready…"), "send": tr("Counting…")}.get(self.state, tr("Press Start"))
        p.drawText(QRectF(b.left(), c.y() - S(40), b.width(), S(24)), int(Qt.AlignmentFlag.AlignCenter), text)
        if self.state == "idle":
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            p.drawText(QRectF(b.left() + S(16), c.y() - S(10), b.width() - S(32), S(60)),
                       int(Qt.AlignmentFlag.AlignHCenter | Qt.TextFlag.TextWordWrap),
                       tr("Press D F J K (or click the lanes) when a note touches the line. Hold the long ones."))


# ================================================================ Memory
SYMBOLS = ["#FF5C8A", "#4FC3FF", "#5BE08A", "#FFB547", "#B36BFF", "#FF8A3D", "#2EE6D6", "#F4F04A",
           "#FF5CC8", "#8CFF2E", "#6A8CFF", "#E6EEF5"]


def paint_symbol(p: QPainter, kind: int, c: QPointF, r: float, theme: str = "shapes") -> None:
    """One of 12 pictures: shapes, numbers or colours (the Memory card style)."""
    col = QColor(SYMBOLS[kind % 12])
    if theme == "numbers":
        p.save()
        p.setPen(col)
        f = QFont(font(12, QFont.Weight.Black))
        f.setPixelSize(max(6, int(r * 1.5)))
        p.setFont(f)
        p.drawText(QRectF(c.x() - r * 1.5, c.y() - r * 1.5, r * 3, r * 3), int(Qt.AlignmentFlag.AlignCenter), str(kind + 1))
        p.restore()
        return
    if theme == "colours":
        p.save()
        p.setPen(QPen(QColor("#FFFFFF"), max(1.0, r * 0.08)))
        g = QRadialGradient(QPointF(c.x() - r * 0.3, c.y() - r * 0.3), r * 1.4)
        g.setColorAt(0, mix(col, QColor("#FFFFFF"), 0.35))
        g.setColorAt(1, col)
        p.setBrush(g)
        p.drawEllipse(c, r, r)
        p.restore()
        return
    p.save()
    p.translate(c)
    p.setPen(Qt.PenStyle.NoPen)
    glow = QRadialGradient(QPointF(0, 0), r * 1.6)
    glow.setColorAt(0, alpha(col, 0.35))
    glow.setColorAt(1, alpha(col, 0.0))
    p.setBrush(glow)
    p.drawEllipse(QPointF(0, 0), r * 1.6, r * 1.6)
    p.setBrush(col)
    path = QPainterPath()
    if kind == 0:
        path.addEllipse(QPointF(0, 0), r, r)
    elif kind == 1:
        path.addRoundedRect(QRectF(-r * 0.85, -r * 0.85, r * 1.7, r * 1.7), r * 0.25, r * 0.25)
    elif kind == 2:
        path.moveTo(0, -r); path.lineTo(r * 0.95, r * 0.8); path.lineTo(-r * 0.95, r * 0.8); path.closeSubpath()
    elif kind == 3:
        path.moveTo(0, -r); path.lineTo(r * 0.8, 0); path.lineTo(0, r); path.lineTo(-r * 0.8, 0); path.closeSubpath()
    elif kind == 4:
        for k in range(10):
            a = -math.pi / 2 + k * math.pi / 5
            rr = r if k % 2 == 0 else r * 0.45
            pt = QPointF(math.cos(a) * rr, math.sin(a) * rr)
            path.moveTo(pt) if k == 0 else path.lineTo(pt)
        path.closeSubpath()
    elif kind == 5:                                               # heart
        path.moveTo(0, r * 0.9)
        path.cubicTo(-r * 1.3, -r * 0.1, -r * 0.5, -r * 1.1, 0, -r * 0.35)
        path.cubicTo(r * 0.5, -r * 1.1, r * 1.3, -r * 0.1, 0, r * 0.9)
    elif kind == 6:                                               # ring
        path.addEllipse(QPointF(0, 0), r, r)
        inner = QPainterPath()
        inner.addEllipse(QPointF(0, 0), r * 0.5, r * 0.5)
        path = path.subtracted(inner)
    elif kind == 7:                                               # plus
        w = r * 0.38
        path.addRect(QRectF(-w, -r, 2 * w, 2 * r))
        path.addRect(QRectF(-r, -w, 2 * r, 2 * w))
        path = path.simplified()
    elif kind == 8:                                               # hexagon
        for k in range(6):
            a = k * math.pi / 3
            pt = QPointF(math.cos(a) * r, math.sin(a) * r)
            path.moveTo(pt) if k == 0 else path.lineTo(pt)
        path.closeSubpath()
    elif kind == 9:                                               # moon
        path.addEllipse(QPointF(0, 0), r, r)
        cut = QPainterPath()
        cut.addEllipse(QPointF(r * 0.45, -r * 0.3), r * 0.85, r * 0.85)
        path = path.subtracted(cut)
    elif kind == 10:                                              # bolt
        pts = [(0.25, -1), (-0.6, 0.15), (-0.05, 0.15), (-0.3, 1), (0.6, -0.2), (0.05, -0.2)]
        path.moveTo(pts[0][0] * r, pts[0][1] * r)
        for x, y in pts[1:]:
            path.lineTo(x * r, y * r)
        path.closeSubpath()
    else:                                                         # music note
        path.addEllipse(QPointF(-r * 0.3, r * 0.55), r * 0.42, r * 0.32)
        path.addRect(QRectF(r * 0.02, -r, r * 0.18, r * 1.55))
        path.addRect(QRectF(r * 0.02, -r, r * 0.65, r * 0.22))
        path = path.simplified()
    p.drawPath(path)
    p.restore()


class MemoryGame(QWidget):
    """Find the pairs. The server keeps the board and shows one card at a time, so nothing can be peeked."""

    def __init__(self, page, on_end=None) -> None:
        super().__init__()
        self.page, self.ctx, self.on_end = page, page.ctx, on_end
        self.setFixedSize(page.W, S(300))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.state = "idle"                       # idle -> busy -> play -> done
        self.round = ""
        self.n, self.cols = 16, 4
        self.faces: dict = {}                     # card -> symbol shown now
        self.found: set = set()
        self.flip_at: dict = {}                   # card -> when it turned (for the animation)
        self.wait = False
        self.flips = 0
        self.t0 = 0.0
        self.result: dict = {}
        self.duel = False
        self._t = QTimer(self)
        self._t.setInterval(16)
        self._t.timeout.connect(self._tick)

    def start(self) -> None:
        if self.state == "busy":
            return
        self.state = "busy"
        tier = int(getattr(self.ctx, "mem_tier", 0) or 0) + 1

        def got(ok: bool, data) -> None:
            if not ok or not isinstance(data, dict):
                self.state = "idle"
                self.update()
                return self.ctx.toast(tr(str(data)), "warn")
            self.begin(data)
        self.ctx.econ.call("rb_mem_start", {"tier": tier}, got)

    def begin(self, data: dict, duel: bool = False) -> None:
        self.round, self.n, self.cols, self.duel = data["round"], int(data["cards"]), int(data["cols"]), duel
        self.faces, self.found, self.flip_at, self.wait, self.flips, self.result = {}, set(), {}, False, 0, {}
        self.t0 = time.monotonic()
        self.state = "play"
        self._t.start()
        self.update()

    def _rows(self) -> int:
        return math.ceil(self.n / self.cols)

    def _cell(self, i: int) -> QRectF:
        rows = self._rows()
        gap = S(6)
        w = min((self.width() - gap * (self.cols + 1)) / self.cols, (self.height() - S(24) - gap * (rows + 1)) / rows)
        ox = (self.width() - (w * self.cols + gap * (self.cols - 1))) / 2
        r, c = divmod(i, self.cols)
        return QRectF(ox + c * (w + gap), S(22) + gap + r * (w + gap), w, w)

    def mousePressEvent(self, e) -> None:
        e.accept()
        if self.state != "play" or self.wait or e.button() != Qt.MouseButton.LeftButton:
            return
        for i in range(self.n):
            if self._cell(i).contains(e.position()):
                if i in self.found or i in self.faces:
                    return
                return self._flip(i)

    def _flip(self, i: int) -> None:
        self.wait = True

        def got(ok: bool, data) -> None:
            self.wait = False
            if not ok or not isinstance(data, dict):
                self.ctx.toast(tr(str(data)), "warn")
                return self.update()
            self.faces[i] = int(data["sym"])
            self.flip_at[i] = time.monotonic()
            sfx.play("pick")
            if data.get("first"):
                return self.update()
            self.flips = int(data.get("flips") or self.flips + 2)
            other = int(data.get("other", -1))
            if data.get("match"):
                self.found |= {i, other}
                sfx.play("on")
                if data.get("done"):
                    self.state = "done"
                    self.result = data
                    if self.on_end:
                        self.on_end(data)
                    QTimer.singleShot(250, self.update)
            else:
                self.wait = True                              # look at both for a moment, then turn them back

                def hide() -> None:
                    for k in (i, other):
                        self.faces.pop(k, None)
                        self.flip_at[k] = time.monotonic()
                    self.wait = False
                    self.update()
                QTimer.singleShot(700, hide)
            self.update()
        self.ctx.econ.call("rb_mem_flip", {"round": self.round, "card": i}, got)

    def _tick(self) -> None:
        self.update()
        if self.state != "play" and not any(time.monotonic() - t < 0.3 for t in self.flip_at.values()):
            self._t.stop()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        now = time.monotonic()
        if self.state in ("play", "done"):
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            secs = (now - self.t0) if self.state == "play" else float(self.result.get("secs") or 0)
            p.drawText(QRectF(S(4), 0, self.width() - S(8), S(18)), int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter),
                       tr("Pairs {a} / {b}", a=len(self.found) // 2, b=self.n // 2))
            p.drawText(QRectF(S(4), 0, self.width() - S(8), S(18)), int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                       tr("{n} flips", n=self.flips) + f"  ·  {int(secs)} s")
            for i in range(self.n):
                r = self._cell(i)
                k = min(1.0, (now - self.flip_at.get(i, 0)) / 0.25)
                face = i in self.faces or i in self.found
                squeeze = abs(math.cos(k * math.pi)) if k < 1 else 1.0
                showing = face if k >= 0.5 else not face
                rr = QRectF(r.center().x() - r.width() / 2 * squeeze, r.top(), r.width() * squeeze, r.height())
                if showing:
                    sym = self.faces.get(i)
                    col = QColor(SYMBOLS[sym % 12]) if sym is not None else QColor(TEXT_DIM)
                    p.setPen(QPen(alpha(col, 0.9 if i in self.found else 0.5), S(1.6)))
                    p.setBrush(QColor("#12161C"))
                    p.drawRoundedRect(rr, S(8), S(8))
                    if sym is not None and squeeze > 0.2:
                        p.save()
                        p.translate(rr.center())
                        p.scale(squeeze, 1)
                        paint_symbol(p, sym, QPointF(0, 0), r.width() * 0.26,
                                     MEM_THEMES[int(getattr(self.ctx, "mem_theme", 0) or 0)][0])
                        p.restore()
                else:
                    g = QLinearGradient(rr.topLeft(), rr.bottomRight())
                    g.setColorAt(0, mix(ui.accent, QColor("#1A1F26"), 0.55))
                    g.setColorAt(1, QColor("#1A1F26"))
                    p.setPen(QPen(alpha(ui.accent, 0.35), S(1.2)))
                    p.setBrush(g)
                    p.drawRoundedRect(rr, S(8), S(8))
                    if squeeze > 0.5:
                        p.setPen(alpha("#FFFFFF", 0.25))
                        p.setFont(font(14, QFont.Weight.Black))
                        p.drawText(rr, int(Qt.AlignmentFlag.AlignCenter), "R")
        if self.state == "done" and self.result:
            b = QRectF(self.rect()).adjusted(S(20), S(70), -S(20), -S(70))
            p.setPen(QPen(alpha(ui.accent, 0.6), S(1.4)))
            p.setBrush(alpha("#07090C", 0.92))
            p.drawRoundedRect(b, S(12), S(12))
            res = self.result
            p.setPen(QColor(TEXT))
            p.setFont(font(14, QFont.Weight.Bold))
            p.drawText(QRectF(b.left(), b.top() + S(12), b.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("All pairs in {n} flips", n=res.get("flips", 0)))
            paid = int(res.get("paid") or 0)
            p.setPen(QColor(GOLD_TEXT if paid else TEXT_DIM))
            p.setFont(font(20, QFont.Weight.ExtraBold))
            text = tr("Duel score sent") if res.get("duel") else ("+" + coins_text(paid) if paid else tr("No coins this time"))
            p.drawText(QRectF(b.left(), b.top() + S(40), b.width(), S(30)), int(Qt.AlignmentFlag.AlignCenter), text)
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10, QFont.Weight.DemiBold))
            line = tr("Perfect is {n} flips", n=res.get("perfect", self.n)) if not res.get("duel") else tr("{s} seconds", s=res.get("secs", 0))
            if res.get("day"):
                line += "  ·  " + window_text(res["day"])
            p.drawText(QRectF(b.left(), b.top() + S(74), b.width(), S(18)), int(Qt.AlignmentFlag.AlignCenter), line)
        elif self.state in ("idle", "busy"):
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(13, QFont.Weight.Bold))
            p.drawText(QRectF(self.rect()), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Loading…") if self.state == "busy" else tr("Press Start"))


# ================================================================ scratch card (every 12 hours)
class ScratchCard(QWidget):
    """A silver card. Scratch it with the mouse: it is hard at first, then easier and easier. Under it: a rarity
    colour and the prize (coins or keys). The server decides the prize when you start scratching."""
    COLS, ROWS = 30, 16

    def __init__(self, page) -> None:
        super().__init__()
        self.setProperty("cheat", True)                    # 5.1: Ruben's right click
        self.page, self.ctx = page, page.ctx
        self.setFixedSize(page.W, S(170))
        self.setCursor(Qt.CursorShape.CrossCursor)
        self.prize: dict = {}
        self.asked = False
        self.cleared = 0
        self.done = False
        self.grid = [[False] * self.COLS for _ in range(self.ROWS)]
        self.cover = None
        self.last = None
        self.done_at = 0.0
        self._t = QTimer(self)
        self._t.setInterval(16)
        self._t.timeout.connect(self.update)
        # 9.5.1: the card being asked for (or its prize) belongs to the app, not to this widget: if the page was laid
        # out again while the server answered, the new card carries on with the same prize instead of showing nothing
        self.ctx.scratch_card = self
        got = getattr(self.ctx, "scratch_got", None)
        if isinstance(got, dict) and got:
            self.prize, self.asked = dict(got), True
        elif time.monotonic() < float(getattr(self.ctx, "scratch_asking", 0) or 0):
            self.asked = True

    def _card(self) -> QRectF:
        return QRectF(self.rect()).adjusted(S(4), S(4), -S(4), -S(4))

    def _make_cover(self) -> None:
        r = self._card()
        img = QImage(int(r.width()), int(r.height()), QImage.Format.Format_ARGB32_Premultiplied)
        img.fill(Qt.GlobalColor.transparent)
        p = QPainter(img)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        g = QLinearGradient(0, 0, r.width(), r.height())
        for k, c in enumerate(["#9AA3AD", "#D9DEE3", "#8B949E", "#C9CFD6", "#9AA3AD"]):
            g.setColorAt(k / 4, QColor(c))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawRoundedRect(QRectF(0, 0, r.width(), r.height()), S(12), S(12))
        rnd = random.Random(7)
        p.setPen(QPen(alpha("#FFFFFF", 0.18), 1))
        for _ in range(140):
            x, y = rnd.uniform(0, r.width()), rnd.uniform(0, r.height())
            p.drawLine(QPointF(x, y), QPointF(x + rnd.uniform(-6, 6), y + rnd.uniform(-6, 6)))
        p.setPen(QColor("#5C6670"))
        p.setFont(font(15, QFont.Weight.Black))
        p.drawText(QRectF(0, 0, r.width(), r.height()), int(Qt.AlignmentFlag.AlignCenter), tr("SCRATCH ME"))
        p.end()
        self.cover = img

    def ready(self) -> bool:
        return int(getattr(self.ctx.econ, "scratch_in", 0) or 0) <= 0

    def _brush(self) -> float:
        frac = self.cleared / (self.COLS * self.ROWS)
        return S(6) + S(34) * frac ** 1.3                   # small at first, then bigger and bigger

    def mousePressEvent(self, e) -> None:
        e.accept()
        if self.done or not self.ready() and not self.prize:
            return
        if not self.asked:
            self.asked = True
            ctx = self.ctx
            ask_id = ctx.scratch_ask_id = int(getattr(ctx, "scratch_ask_id", 0) or 0) + 1
            ctx.scratch_asking = time.monotonic() + 20
            claim_lock(ctx, 8)

            def card():
                """9.5.1: the card on screen now (the page may have been laid out again since the ask)."""
                c = getattr(ctx, "scratch_card", None)
                try:
                    if c is not None:
                        c.isVisible()
                    return c
                except RuntimeError:
                    return None

            def got(ok: bool, data) -> None:
                if ask_id != getattr(ctx, "scratch_ask_id", 0):
                    return
                ctx.scratch_asking = 0
                claim_lock(ctx, 0)                               # 9.1: never stuck: leaving early still shows the prize
                c = card()
                if not ok or not isinstance(data, dict):
                    msg = str(data)
                    if c is not None and not c.prize:
                        c.asked = False
                    if any(w in msg for w in ("wait", "Wait", "soon", "countdown", "ready")):
                        # 9.5.1: the server says this card was already scratched: show when the next one comes,
                        # not a blank card that never fills in
                        ctx.econ.scratch_in = max(1, int(getattr(ctx.econ, "scratch_in", 0) or 0))
                        ctx.econ.refresh()
                        if c is not None and not c.prize:
                            c.reset()
                        return ctx.toast(tr("Not ready yet"), "warn")
                    if c is not None and not c.prize:
                        c.reset()
                    return ctx.toast(tr(msg), "warn")
                ctx.scratch_got = dict(data)
                ctx.econ.scratch_in = int(data.get("next") or 43200)
                if c is not None:
                    c.prize = dict(data)
                    c.asked = True
                    if c.cleared >= c.COLS * c.ROWS * 0.62:
                        c._finish()
                    c.update()

            def lost() -> None:                                  # 9.1: no answer: the card can be scratched again
                if ask_id != getattr(ctx, "scratch_ask_id", 0) or getattr(ctx, "scratch_got", None):
                    return
                ctx.scratch_asking = 0
                claim_lock(ctx, 0)
                c = card()
                if c is not None and not c.prize:
                    c.asked = False
                    c.reset()
                ctx.econ.refresh()                               # the server may have answered after all
            QTimer.singleShot(15000, lost)
            ctx.econ.call("rb_scratch", {}, got, hold=True)
        self.last = e.position()
        self._scratch(e.position())

    def mouseMoveEvent(self, e) -> None:
        if self.last is None or self.done:
            return
        a, b = self.last, e.position()
        steps = max(1, int(math.hypot(b.x() - a.x(), b.y() - a.y()) / S(3)))
        for k in range(1, steps + 1):
            self._scratch(QPointF(a.x() + (b.x() - a.x()) * k / steps, a.y() + (b.y() - a.y()) * k / steps))
        self.last = b

    def mouseReleaseEvent(self, _e) -> None:
        self.last = None

    def _scratch(self, pos: QPointF) -> None:
        if self.cover is None or not self.prize and self.cleared > self.COLS * self.ROWS * 0.25:
            return                                               # wait for the server before showing too much
        r = self._card()
        x, y = pos.x() - r.left(), pos.y() - r.top()
        rad = self._brush()
        p = QPainter(self.cover)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.setCompositionMode(QPainter.CompositionMode.CompositionMode_Clear)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(0, 0, 0, 255))
        p.drawEllipse(QPointF(x, y), rad, rad)
        p.end()
        cw, ch = r.width() / self.COLS, r.height() / self.ROWS
        for row in range(max(0, int((y - rad) / ch)), min(self.ROWS, int((y + rad) / ch) + 1)):
            for col in range(max(0, int((x - rad) / cw)), min(self.COLS, int((x + rad) / cw) + 1)):
                if not self.grid[row][col] and math.hypot((col + 0.5) * cw - x, (row + 0.5) * ch - y) <= rad:
                    self.grid[row][col] = True
                    self.cleared += 1
        if self.prize and self.cleared >= self.COLS * self.ROWS * 0.62:
            self._finish()
        self.update()

    def hideEvent(self, _e) -> None:
        if getattr(self.ctx, "scratch_card", None) is not self:  # 9.5.1: a newer card (the page laid out again) has it
            return
        if self.prize and not self.done:                         # 9.1: left before the end: the prize is shown anyway
            self._finish()

    def _finish(self) -> None:
        if self.done:
            return
        self.done = True
        self.ctx.scratch_got = None                              # 9.5.1: shown: the next card starts fresh
        self.done_at = time.monotonic()
        claim_lock(self.ctx, 1.2)
        self._t.start()
        QTimer.singleShot(1500, self._t.stop)
        self.ctx.econ.absorb(self.prize)
        self.ctx.econ.changed.emit()
        sfx.play("on")
        c, k = int(self.prize.get("coins_won") or 0), int(self.prize.get("keys_won") or 0)
        cp = self.prize.get("coupon")
        if cp:                                                   # 4.0: an XP coupon too (already in your items)
            pass
            self.ctx.econ.refresh()
            QTimer.singleShot(600, lambda: sfx.tune("coupon"))
        if self.prize.get("gold_wheel"):                         # 3.1: the Golden Wheel opens
            pass
            QTimer.singleShot(900, lambda: open_gold_wheel(self.ctx))
            return
        text = " · ".join(x for x in (("+" + coins_text(c)) if c else "", tr("+{n} key(s)", n=k) if k else "") if x) or "+0"
        if cp:
            text += "  ·  " + tr("+ {what}", what=tr(COUPONS.get(cp, ("XP coupon",))[0]))
        self.ctx.toast(text)
        QTimer.singleShot(2600, self._leave)                     # 9.2: back to the menu it was opened from

    def _leave(self) -> None:
        try:
            if self.isVisible() and getattr(self.ctx, "games_sub", None) == "scratch":
                leave_free_game(self.ctx)
        except RuntimeError:
            pass

    def reset(self) -> None:
        self.prize, self.asked, self.cleared, self.done, self.last = {}, False, 0, False, None
        self.grid = [[False] * self.COLS for _ in range(self.ROWS)]
        self.cover = None
        self.update()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = self._card()
        if not self.ready() and not self.prize:
            p.setPen(QPen(alpha("#FFFFFF", 0.1), 1))
            p.setBrush(QColor("#11151A"))
            p.drawRoundedRect(r, S(12), S(12))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(13, QFont.Weight.Bold))
            p.drawText(r, int(Qt.AlignmentFlag.AlignCenter),
                       tr("Next scratch card in {t}", t=clock_text(int(self.ctx.econ.scratch_in or 0))))
            return
        rar = self.prize.get("rarity", "standard")
        col = (QColor("#E8B23A") if rar == "golden" else QColor(RARITY_COLOURS.get(rar, "#9AA4AD"))) if self.prize else QColor("#2A3038")
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        g.setColorAt(0, mix(col, QColor("#000000"), 0.15))
        g.setColorAt(1, mix(col, QColor("#000000"), 0.6))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawRoundedRect(r, S(12), S(12))
        if self.prize:
            if self.done:                                        # a little shine once it is all off
                k = min(1.0, (time.monotonic() - self.done_at) / 1.2)
                x = r.left() + r.width() * (k * 1.6 - 0.3)
                sh = QLinearGradient(QPointF(x - S(40), 0), QPointF(x + S(40), 0))
                sh.setColorAt(0, alpha("#FFFFFF", 0))
                sh.setColorAt(0.5, alpha("#FFFFFF", 0.35 * (1 - k)))
                sh.setColorAt(1, alpha("#FFFFFF", 0))
                p.setBrush(sh)
                p.drawRoundedRect(r, S(12), S(12))
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(11, QFont.Weight.ExtraBold))
            p.drawText(QRectF(r.left(), r.top() + S(18), r.width(), S(18)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("GOLDEN") if rar == "golden" else tr(RARITY_NAMES.get(rar, "Common")).upper())
            c, k = int(self.prize.get("coins_won") or 0), int(self.prize.get("keys_won") or 0)
            p.setFont(font(26, QFont.Weight.Black))
            p.drawText(QRectF(r.left(), r.center().y() - S(20), r.width(), S(40)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Golden Wheel!") if rar == "golden" else
                       (coins_text(c) + " " + tr("coins") + ("  +  " + tr("{n} key(s)", n=k) if k else "")) if c else
                       tr("{n} key(s)", n=k))
            if self.prize.get("coupon"):                          # 4.0: and an XP coupon
                pass
                p.setFont(font(11, QFont.Weight.Bold))
                p.drawText(QRectF(r.left(), r.bottom() - S(34), r.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                           "+ " + tr(COUPONS.get(self.prize["coupon"], ("XP coupon",))[0]))
        if self.cover is None:
            self._make_cover()
        if not self.done:
            p.drawImage(r.topLeft(), self.cover)
        elif time.monotonic() - self.done_at < 0.4:
            p.setOpacity(1 - (time.monotonic() - self.done_at) / 0.4)
            p.drawImage(r.topLeft(), self.cover)
            p.setOpacity(1.0)


class ScratchOdds(QWidget):
    """4.0: the scratch card's real odds, as the server sends them (the same numbers it rolls with)."""
    COLOURS = {"golden": "#E8B23A"}

    def __init__(self, rows: list, width: int) -> None:
        super().__init__()
        self.rows = rows
        self.setFixedSize(width, S(25) * len(rows) + S(2))

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        for k, row in enumerate(reversed(self.rows)):
            tier = row.get("tier", "standard")
            col = QColor(self.COLOURS.get(tier) or RARITY_COLOURS.get(tier, "#9AA4AD"))
            r = QRectF(0, k * S(25), self.width(), S(23))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha(col, 0.09))
            p.drawRoundedRect(r, S(6), S(6))
            p.setBrush(col)
            p.drawEllipse(QPointF(r.left() + S(12), r.center().y()), S(4), S(4))
            p.setPen(col)
            p.setFont(font(11, QFont.Weight.Bold))
            name = tr("Golden") if tier == "golden" else tr(RARITY_NAMES.get(tier, tier))
            p.drawText(r.adjusted(S(24), 0, 0, 0), int(Qt.AlignmentFlag.AlignVCenter), name)
            nw = p.fontMetrics().horizontalAdvance(name) + S(34)
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10, QFont.Weight.DemiBold))
            p.drawText(QRectF(r.left() + nw, r.top(), r.width() - nw - S(56), r.height()), int(Qt.AlignmentFlag.AlignVCenter),
                       p.fontMetrics().elidedText(tr(str(row.get("prize", "")), **{k: coins_text(int(row[k])) for k in ("a", "b")
                                                                                if k in row}), Qt.TextElideMode.ElideRight,
                                                  int(r.width() - nw - S(56))))
            p.setPen(QColor(TEXT))
            p.setFont(font(11, QFont.Weight.Bold))
            p.drawText(r.adjusted(0, 0, -S(10), 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                       f"{row.get('pct', 0)}%")


def paint_freebie(widget, p, title: str, status: str, ready: bool, accent, icon) -> None:
    """4.3: the three freebies (daily reward, free spin, scratch card) as equal tiles in one row:
    the icon on top, the name under it, then ready or how long to wait."""
    r = QRectF(widget.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
    accent = QColor(accent)
    hover = 1.0 if widget.underMouse() else 0.0
    g = QLinearGradient(r.topLeft(), r.bottomLeft())
    g.setColorAt(0, mix(accent, QColor("#12161B"), 0.80 - 0.06 * hover) if ready else alpha("#FFFFFF", 0.05 + 0.02 * hover))
    g.setColorAt(1, QColor("#12161B") if ready else alpha("#FFFFFF", 0.025 + 0.02 * hover))
    p.setPen(QPen(alpha(accent, 0.55) if ready else alpha("#FFFFFF", 0.08 + 0.05 * hover), 1.2))
    p.setBrush(g)
    p.drawRoundedRect(r, S(11), S(11))
    icon(p, QPointF(r.center().x(), r.top() + S(21)))
    fm = QFontMetrics(font(11.5, QFont.Weight.Bold))
    p.setPen(QColor(TEXT))
    p.setFont(font(11.5, QFont.Weight.Bold))
    p.drawText(QRectF(r.left() + S(6), r.top() + S(35), r.width() - S(12), S(18)), int(Qt.AlignmentFlag.AlignCenter),
               fm.elidedText(title, Qt.TextElideMode.ElideRight, int(r.width() - S(12))))
    p.setPen(QColor(accent if ready else QColor(TEXT_DIM)))
    p.setFont(font(10.5, QFont.Weight.DemiBold))
    p.drawText(QRectF(r.left() + S(6), r.top() + S(52), r.width() - S(12), S(16)), int(Qt.AlignmentFlag.AlignCenter), status)


FREEBIE_H = 72


class ScratchRow(QWidget):
    """A tile in the games lobby: the scratch card is ready, or the time until the next one."""

    def __init__(self, page) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedHeight(S(FREEBIE_H))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._t = QTimer(self)
        self._t.setInterval(1000)
        self._t.timeout.connect(self._step)

    def _step(self) -> None:
        econ = self.ctx.econ
        if int(getattr(econ, "scratch_in", 0) or 0) > 0:
            econ.scratch_in -= 1
        self.update()

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def mouseReleaseEvent(self, e) -> None:
        if self.rect().contains(e.position().toPoint()):
            self.page.open_sub("scratch")

    def enterEvent(self, _e) -> None:
        self.update()

    def leaveEvent(self, _e) -> None:
        self.update()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        left = int(getattr(self.ctx.econ, "scratch_in", 0) or 0)
        ready = left <= 0 and not self.ctx.econ.server_old

        def icon(p, c):
            p.save()
            p.translate(c)
            p.scale(1.15, 1.15)
            draw_icon(p, "gift", QColor(TEXT) if ready else QColor(TEXT_DIM))
            p.restore()
        paint_freebie(self, p, tr("Scratch card"), tr("Ready!") if ready else (tr("Soon") if self.ctx.econ.server_old
                                                                               else clock_text(left)),
                      ready, "#D5DBE2", icon)


# ================================================================ duels
DUEL_GAMES = {"tap": "Beat Tap", "memory": "Memory", "park": "Parking"}


def duel_limit(ctx, name: str, page=None) -> int:
    """Highest duel bet with this friend: 80% of the lower of the two balances, in tens. Asked to the server
    once a minute per friend; until it answers (or on an older server) only your own balance counts."""
    cache = getattr(ctx, "duel_limits", None)
    if cache is None:
        cache = ctx.duel_limits = {}
    mine = int(int(ctx.econ.coins) * 0.8) // 10 * 10
    got = cache.get(name)
    if got is None or time.monotonic() - got[1] > 60:
        cache[name] = (got[0] if got else None, time.monotonic())

        def done(ok: bool, data) -> None:
            if ok and isinstance(data, (int, float)):
                old = cache.get(name, (None, 0))[0]
                cache[name] = (int(data), time.monotonic())
                if old != int(data) and ctx.window.showing("games") and getattr(ctx, "games_sub", None) == "duels":
                    ctx.reload_page("games")
        ctx.online.ask("rb_duel_limit", {"name": name}, done)
    top = cache.get(name, (None, 0))[0]
    return max(0, min(mine, top) if top is not None else mine)



class DuelRow(QWidget):
    """One duel: who, which game, the bet in big gold, and what can be done now (4.6: easier to read and to join)."""

    def __init__(self, page, d: dict) -> None:
        super().__init__()
        self.page, self.d = page, d
        lay = hbox(self, 8)
        lay.setContentsMargins(S(12), S(8), S(10), S(8))
        st = d.get("state")
        self.urgent = (st == "asked" and d.get("asked_me")) or (st == "on" and not d.get("played"))
        bet = int(d.get("bet") or 0)
        title = tr("{game} vs {name}", game=tr(DUEL_GAMES.get(d.get("game"), "")), name=d.get("other", "?"))
        col = vbox(spacing=1)
        col.addWidget(Label(title, 12, TEXT, bold=True))
        col.addWidget(Label(self._state_text(), 10, ui.accent.name() if self.urgent else TEXT_DIM, bold=bool(self.urgent)))
        lay.addLayout(col, 1)
        pot = vbox(spacing=0)
        pot.addWidget(Label(coins_text(bet) if bet else tr("No bet"), 13 if bet else 10.5, GOLD_TEXT if bet else TEXT_DIM,
                            bold=True, align=Qt.AlignmentFlag.AlignRight).fit(), 0, Qt.AlignmentFlag.AlignRight)
        if bet:
            pot.addWidget(Label(tr("each · pot {n}", n=coins_text(bet * 2)), 8.5, TEXT_DIM, align=Qt.AlignmentFlag.AlignRight).fit(), 0, Qt.AlignmentFlag.AlignRight)
        lay.addLayout(pot)
        if st == "asked" and d.get("asked_me"):
            yes = Button(tr("Accept & play"), "primary", 30, icon="play")
            yes.clicked.connect(lambda: page.duel_answer(d["id"], True, dict(d, state="on")))
            no = Button(tr("No"), "ghost", 30)
            no.clicked.connect(lambda: page.duel_answer(d["id"], False))
            lay.addWidget(yes)
            lay.addWidget(no)
        elif st == "asked":
            back = Button(tr("Take back"), "ghost", 30)
            back.clicked.connect(lambda: page.duel_answer(d["id"], False))
            lay.addWidget(back)
        elif st == "on" and not d.get("played"):
            go = Button(tr("Play"), "primary", 30, icon="play")
            go.clicked.connect(lambda: page.duel_play(d))
            lay.addWidget(go)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        paint_surface(p, r, S(DS.R_MD), 0.04, edge=alpha(ui.accent, 0.7) if self.urgent else None, tint=ui.accent if self.urgent else None, tint_a=0.10)   # 8.0: shared surface

    def _state_text(self) -> str:
        d = self.d
        st = d.get("state")
        if st == "asked":
            return tr("Waiting for an answer") if not d.get("asked_me") else tr("They challenge you!")
        if st == "on":
            if d.get("played"):
                return tr("Your score is in: waiting for them") if not d.get("other_played") else tr("Counting…")
            return tr("Your turn: play within 15 minutes")
        if st == "cancelled":
            return {"declined": tr("Declined"), "expired": tr("No answer"), "taken back": tr("Taken back")}.get(d.get("why"), tr("Cancelled"))
        if d.get("draw"):
            return tr("Draw: bets given back")
        return tr("You won!") if d.get("won") else tr("You lost")


def build_duels(page, lay) -> None:
    """The duel screen: challenge a friend, and the list of duels."""
    ctx = page.ctx
    top = hbox(spacing=8)
    back = IconButton("back", 32, tip=tr("Back"))
    back.clicked.connect(lambda: page.open_sub(None))
    top.addWidget(back)
    top.addWidget(Label(tr("Duels"), 16, bold=True), 1)
    pass
    top.addWidget(HelpButton(ctx, "duels"))
    lay.addLayout(top)
    lay.addWidget(CoinBar(ctx))
    duels = getattr(ctx, "duels_data", None)
    waiting = [d for d in (duels or []) if (d.get("state") == "asked" and d.get("asked_me"))
               or (d.get("state") == "on" and not d.get("played"))]
    if waiting:                                       # 4.6: duels waiting for me come first, before the challenge form
        lay.addWidget(Label(tr("WAITING FOR YOU"), 10, ui.accent.name(), weight=QFont.Weight.Bold))
        for d in waiting:
            lay.addWidget(DuelRow(page, d))
    friends = [f for f in (getattr(ctx, "duel_friends", None) or [])]
    lay.addWidget(Label(tr("CHALLENGE A FRIEND"), 10, TEXT_DIM, weight=QFont.Weight.Bold))
    if not friends:
        lay.addWidget(Label(tr("Add friends in the Social tab to duel them."), 11, TEXT_DIM, wrap_w=page.W))
    else:
        names = [f["name"] for f in friends][:6]
        pick = Segmented(names, min(int(getattr(ctx, "duel_pick", 0) or 0), len(names) - 1))
        lay.addWidget(pick)
        games = ["tap", "memory", "park"]
        g = Segmented([tr(DUEL_GAMES[k]) for k in games], int(getattr(ctx, "duel_game", 0) or 0))
        g.changed.connect(lambda i: setattr(ctx, "duel_game", i))
        lay.addWidget(g)
        lv = Segmented([tr("Easy"), tr("Medium"), tr("Hard")], int(getattr(ctx, "duel_tier", 1)))
        lv.changed.connect(lambda i: setattr(ctx, "duel_tier", i))
        lay.addWidget(lv)

        def who() -> str:
            return names[min(int(getattr(ctx, "duel_pick", 0) or 0), len(names) - 1)]
        top_bet = duel_limit(ctx, who(), page)
        mode = Segmented([tr("Bet"), tr("No bet")], 1 if getattr(ctx, "duel_nobet", False) or top_bet < 10 else 0)
        lay.addWidget(mode)
        amount = None
        if top_bet >= 10:
            start = max(10, min(top_bet, int(getattr(ctx, "duel_amount", 0) or 100)))
            amount = SliderRow(tr("Bet"), 10, top_bet, start, 10, start, lambda v: coins_text(int(v)), label_w=60)
            amount._val.setFixedWidth(S(78))
            amount.changed.connect(lambda v: setattr(ctx, "duel_amount", int(v)))
            amount.setVisible(mode.index() == 0)
            lay.addWidget(amount)
            lay.addWidget(Label(tr("Maximum {n} (80% of the lower balance).", n=coins_text(top_bet)),
                                10, TEXT_DIM, wrap_w=page.W))
        else:
            lay.addWidget(Label(tr("Not enough coins for a bet."), 10, TEXT_DIM, wrap_w=page.W))

        def on_mode(i: int) -> None:
            if top_bet < 10:
                return mode.set_index(1)
            ctx.duel_nobet = i == 1
            if amount is not None:
                amount.setVisible(i == 0)

        def on_pick(i: int) -> None:
            ctx.duel_pick = i
            ctx.reload_page()                       # the highest bet depends on the friend
        mode.changed.connect(on_mode)
        pick.changed.connect(on_pick)
        send = Button(tr("Send challenge"), "primary", 36, icon="shield")

        def ask() -> None:
            name = who()
            game = games[int(getattr(ctx, "duel_game", 0) or 0)]
            bet = 0 if amount is None or getattr(ctx, "duel_nobet", False) else int(amount.value())
            bet = 0 if bet < 10 else bet - bet % 10
            if bet > ctx.econ.coins:
                return ctx.toast(tr("Not enough coins"), "warn")

            def done(ok: bool, data) -> None:
                if not ok:
                    return ctx.toast(tr(str(data)), "warn")
                sfx.play("on")
                ctx.toast(tr("Challenge sent to {name}", name=name))
                page.load_duels()
            ctx.econ.call("rb_duel_ask", {"name": name, "game": game, "tier": int(getattr(ctx, "duel_tier", 1)) + 1, "bet": bet}, done)
        send.clicked.connect(ask)
        lay.addWidget(send)
        lay.addWidget(Label(tr("Same level for both players. Best score wins the pot (5% fee). A draw refunds both bets."),
                            10, TEXT_DIM, wrap_w=page.W))
    lay.addWidget(Label(tr("YOUR DUELS") if not waiting else tr("OTHER DUELS"), 10, TEXT_DIM, weight=QFont.Weight.Bold))
    if duels is None:
        lay.addWidget(Label(tr("Loading…"), 11, TEXT_DIM))
    elif not duels:
        lay.addWidget(Label(tr("No duels yet."), 11, TEXT_DIM))
    else:
        for d in [d for d in duels if d not in waiting][:10]:
            lay.addWidget(DuelRow(page, d))
    page.load_duels(quiet=True)



# ================================================================ the lobby: two big cards, and the mini game list
class BigCard(QWidget):
    """A big clickable card: an icon, a title and one line saying what it is."""

    def __init__(self, title: str, sub: str, icon: str, colours: tuple, on_click, height: int = 74) -> None:
        super().__init__()
        self.title, self.sub, self.icon, self.colours, self.on_click = title, sub, icon, colours, on_click
        self.setFixedHeight(S(height))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.hover = 0.0
        self.extra = ""                               # small text on the right (e.g. coins left)

    def enterEvent(self, _e) -> None:
        self.hover = 1.0
        self.update()

    def leaveEvent(self, _e) -> None:
        self.hover = 0.0
        self.update()

    def mouseReleaseEvent(self, e) -> None:
        if self.rect().contains(e.position().toPoint()):
            sfx.play("pick")
            self.on_click()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        a, b = QColor(self.colours[0]), QColor(self.colours[1])
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        g.setColorAt(0, mix(a, QColor("#0B0E10"), 0.55 - 0.1 * self.hover))
        g.setColorAt(1, mix(b, QColor("#0B0E10"), 0.8))
        p.setPen(QPen(alpha(a, 0.55 + 0.3 * self.hover), S(1.3)))
        p.setBrush(g)
        p.drawRoundedRect(r, S(14), S(14))
        glow = QRadialGradient(QPointF(r.left() + S(34), r.center().y()), S(40))
        glow.setColorAt(0, alpha(a, 0.45))
        glow.setColorAt(1, alpha(a, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glow)
        p.drawEllipse(QPointF(r.left() + S(34), r.center().y()), S(40), S(40))
        p.save()
        p.translate(r.left() + S(34), r.center().y())
        p.scale(1.5, 1.5)
        draw_icon(p, self.icon, QColor("#FFFFFF"))
        p.restore()
        p.setPen(QColor(TEXT))
        size = 15.0
        while size > 10 and QFontMetrics(font(size, QFont.Weight.ExtraBold)).horizontalAdvance(self.title) > r.width() - S(76):
            size -= 0.5                                   # long names (in French) get smaller, never cut
        p.setFont(font(size, QFont.Weight.ExtraBold))
        p.drawText(QRectF(r.left() + S(66), r.top() + S(10), r.width() - S(76), S(24)), int(Qt.AlignmentFlag.AlignVCenter), self.title)
        p.setPen(alpha("#FFFFFF", 0.75))
        p.setFont(font(10.5, QFont.Weight.DemiBold))
        p.drawText(QRectF(r.left() + S(66), r.top() + S(34), r.width() - S(80), r.height() - S(38)),
                   int(Qt.AlignmentFlag.AlignTop | Qt.TextFlag.TextWordWrap), self.sub)
        if self.extra:
            p.setPen(QColor(GOLD_TEXT))
            p.setFont(font(10, QFont.Weight.Bold))
            p.drawText(r.adjusted(0, S(8), -S(12), 0), int(Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignRight), self.extra)


MINI_GAME_COUNT = 7                                   # 6.3: + Mini Golf and Wave Rush


def build_minigames(page, lay) -> None:
    """Earn coins: the free mini games, each with what it pays."""
    page._back_bar(lay, tr("Earn coins"))
    cap = int(float(page.ctx.econ.cfg.get("game_window_cap", 300) or 300) * (1 + 0.004 * page.ctx.econ.level))
    del cap
    games = [
        ("Beat Tap", tr("Hit the notes on the beat. 4 modes: Normal, Rush, Long notes, Chords."), "note",
         ("#FF5C8A", "#7A1FFF"), "24-100", lambda: page._show_mini(True)),
        ("Parking", tr("Slide the cars and get the red one out. Easy, Medium or Hard."), "grid",
         ("#FF8A3D", "#C2271F"), "24-100", lambda: page._show_park(True)),
        ("Memory", tr("Find the pairs in as few flips as you can. 3 sizes, 3 card styles."), "gem",
         ("#4FC3FF", "#2E5BFF"), "24-110", lambda: page.open_sub("memory")),
        ("Block Blast", tr("Place the pieces, clear rows and columns. Classic, Relaxed or Hard. Leaderboard for each."),
         "blocks", ("#FFB547", "#E8503A"), "10-720", lambda: page.open_sub("blocks")),
        ("Minesweeper", tr("Open every safe cell, as fast as you can. Easy, Medium, Hard. Leaderboard for each."), "flag",
         ("#3DDC84", "#0F6B3A"), "70-840", lambda: page.open_sub("sweeper")),
    ]
    t = getattr(page.ctx.econ, "tier", None)
    m = float(t.get("mult") or 1) if isinstance(t, dict) else 1.0     # 9.0: what it pays at your tier
    for name, sub, icon, cols, pay, go in games:
        card = BigCard(tr(name), sub, icon, cols, go, 78)
        lo, hi = (int(x) for x in pay.split("-"))
        card.extra = tr("{n} coins", n=f"{scaled(lo, m)}-{scaled(hi, m)}")
        lay.addWidget(card)
    lay.addWidget(DuelTile(page, "golf"))                   # 6.3: Mini Golf and Wave Rush live here now
    lay.addWidget(DuelTile(page, "wave"))


