def get_hole(hid: int) -> dict:
    """Hole 1-60; 101-160 is the same hole mirrored left to right."""
    base = HOLES.get(hid % 100, HOLES[1])
    if hid < 100:
        return base

    def fx(r):
        return (1 - r[2], r[1], 1 - r[0], r[3])
    out = dict(base, tee=(1 - base["tee"][0], base["tee"][1]), cup=(1 - base["cup"][0], base["cup"][1]),
               rects=[fx(r) for r in base["rects"]], circles=[(1 - c[0], c[1], c[2]) for c in base["circles"]])
    for key in ("sand", "ice", "water"):
        out[key] = [fx(r) for r in base.get(key, [])]
    out["boost"] = [(1 - b[2], b[1], 1 - b[0], b[3], -b[4], b[5]) for b in base.get("boost", [])]
    return out


def _inside(zones, x: float, y: float) -> bool:
    return any(z[0] <= x <= z[2] and z[1] <= y <= z[3] for z in zones)


def simulate(hole: dict, x: float, y: float, ang: float, pw: float):
    """Roll one shot. Returns (frames at 60 fps, final x, final y, holed). Same maths on every PC."""
    v = math.sqrt(max(0.0, min(1.0, pw))) * VMAX        # 5.8: power = how far it rolls on flat grass
    vx, vy = math.cos(ang) * v, math.sin(ang) * v
    dt = 1 / 240
    x0, y0 = x, y
    frames = [(x, y)]
    sand, ice, water, boost = hole.get("sand", []), hole.get("ice", []), hole.get("water", []), hole.get("boost", [])
    cx, cy = hole["cup"]
    r = BALL_R
    for step in range(240 * 14):
        x += vx * dt
        y += vy * dt
        if x < r:
            x, vx = r, abs(vx) * BOUNCE
        elif x > 1 - r:
            x, vx = 1 - r, -abs(vx) * BOUNCE
        if y < r:
            y, vy = r, abs(vy) * BOUNCE
        elif y > FIELD_H - r:
            y, vy = FIELD_H - r, -abs(vy) * BOUNCE
        for (x1, y1, x2, y2) in hole["rects"]:
            qx, qy = max(x1, min(x2, x)), max(y1, min(y2, y))
            dx, dy = x - qx, y - qy
            d = math.hypot(dx, dy)
            if d < r:
                if d < 1e-9:                                   # inside the wall: out the nearest side
                    sides = ((x - x1, -1, 0), (x2 - x, 1, 0), (y - y1, 0, -1), (y2 - y, 0, 1))
                    _dist, nx, ny = min(sides)
                    x, y = (x1 - r if nx < 0 else x2 + r) if nx else x, (y1 - r if ny < 0 else y2 + r) if ny else y
                else:
                    nx, ny = dx / d, dy / d
                    x, y = qx + nx * r, qy + ny * r
                vn = vx * nx + vy * ny
                if vn < 0:
                    vx -= (1 + BOUNCE) * vn * nx
                    vy -= (1 + BOUNCE) * vn * ny
        for (bx, by, br) in hole["circles"]:
            dx, dy = x - bx, y - by
            d = math.hypot(dx, dy)
            if d < br + r and d > 1e-9:
                nx, ny = dx / d, dy / d
                x, y = bx + nx * (br + r), by + ny * (br + r)
                vn = vx * nx + vy * ny
                if vn < 0:
                    vx -= (1 + 0.95) * vn * nx                 # bumpers kick back harder
                    vy -= (1 + 0.95) * vn * ny
        if water and _inside(water, x, y):                     # splash: back to where it was hit from
            frames.append((x, y))
            frames.append((x0, y0))
            return frames, x0, y0, False
        for (x1, y1, x2, y2, px_, py_) in boost:
            if x1 <= x <= x2 and y1 <= y <= y2:
                vx += px_ * dt * 4
                vy += py_ * dt * 4
        speed = math.hypot(vx, vy)
        dc = math.hypot(x - cx, y - cy)
        if dc < CUP_R * 2.2 and speed < 0.7:                   # the cup pulls a slow ball in a little
            pull = 1.6 * dt
            vx += (cx - x) / max(dc, 1e-6) * pull
            vy += (cy - y) / max(dc, 1e-6) * pull
        if dc < CUP_R and speed < 1.05:
            frames.append((cx, cy))
            return frames, cx, cy, True
        dec = (GOLF_DEC + speed * 0.04) * dt                    # 5.8: grass slows it evenly (and air a little)
        if sand and _inside(sand, x, y):
            dec *= 4.0
        elif ice and _inside(ice, x, y):
            dec *= 0.25
        if speed <= dec or speed < 0.004:
            break
        k = (speed - dec) / speed
        vx, vy = vx * k, vy * k
        if step % 4 == 3:
            frames.append((x, y))
    frames.append((x, y))
    return frames, x, y, False


def golf_power(ball, mouse) -> float:
    """Shot power from how far the mouse is from the ball: 0 at the ball, full at GOLF_PULL away. 5.10: a curve, so
    small putts are easy to dose and long shots need a steady hand."""
    if not ball or not mouse:
        return 0.0
    return max(0.0, min(1.0, math.hypot(mouse[0] - ball[0], mouse[1] - ball[1]) / GOLF_PULL)) ** 1.35


def golf_ray(h, ball, ang: float, length: float) -> float:
    """How far a straight line from the ball goes before it meets a wall, a bumper, water or the edge."""
    if not h:
        return length
    dx, dy, step, d = math.cos(ang), math.sin(ang), 0.004, BALL_R * 1.6
    water = h.get("water", [])
    while d < length:
        x, y = ball[0] + dx * d, ball[1] + dy * d
        if not (BALL_R <= x <= 1 - BALL_R and BALL_R <= y <= FIELD_H - BALL_R):
            return d
        if any(x1 - BALL_R <= x <= x2 + BALL_R and y1 - BALL_R <= y <= y2 + BALL_R for x1, y1, x2, y2 in h.get("rects", [])):
            return d
        if any(math.hypot(x - bx, y - by) <= br + BALL_R for bx, by, br in h.get("circles", [])):
            return d
        if water and _inside(water, x, y):
            return d
        d += step
    return length


def paint_power_strip(p: QPainter, r: QRectF, pw, label: str = "") -> None:
    """5.15: the shot power, under the course: a wide bar, green to red, with the percentage."""
    p.save()
    bar = QRectF(r.left() + S(12), r.center().y() - S(7), r.width() - S(24) - S(56), S(14))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(alpha("#FFFFFF", 0.08))
    p.drawRoundedRect(bar, S(7), S(7))
    if pw is None:
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9.5, QFont.Weight.DemiBold))
        p.drawText(bar, int(Qt.AlignmentFlag.AlignCenter), label)
        p.restore()
        return
    g = QLinearGradient(bar.topLeft(), bar.topRight())
    g.setColorAt(0, QColor("#3DDC84"))
    g.setColorAt(0.6, QColor("#FFC94D"))
    g.setColorAt(1, QColor("#FF5C5C"))
    p.setBrush(g)
    p.drawRoundedRect(QRectF(bar.left(), bar.top(), max(bar.height(), bar.width() * pw), bar.height()), S(7), S(7))
    for k in (0.25, 0.5, 0.75):
        p.fillRect(QRectF(bar.left() + bar.width() * k, bar.top() + S(3), 1, bar.height() - S(6)), alpha("#000000", 0.35))
    p.setPen(QColor("#FFFFFF"))
    p.setFont(font(11, QFont.Weight.Black))
    p.drawText(QRectF(bar.right() + S(6), r.top(), S(56), r.height()), int(Qt.AlignmentFlag.AlignVCenter),
               f"{int(round(pw * 100))}%")
    p.restore()


def paint_golf_aim(p: QPainter, P, ball, ang: float, pw: float, col: QColor, f: QRectF, u: float, h=None,
                   meter: bool = False) -> None:
    """5.10: the aim shows the direction only (a short arrow that stops at the first wall or water) and a power meter.
    How far the ball rolls is up to you: no more target circle."""
    if ball is None:
        return
    full = 0.07 + 0.07 * pw                               # a short arrow: longer = harder, never the real distance
    reach = golf_ray(h, ball, ang, full)
    c = P(*ball)
    tip = P(ball[0] + math.cos(ang) * reach, ball[1] + math.sin(ang) * reach)
    start = P(ball[0] + math.cos(ang) * BALL_R * 1.8, ball[1] + math.sin(ang) * BALL_R * 1.8)
    p.save()
    p.setPen(QPen(alpha("#000000", 0.35), S(4.5), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
    p.drawLine(start, tip)
    p.setPen(QPen(col, S(3), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
    p.drawLine(start, tip)
    if reach >= full - 1e-6:                              # an arrow head when nothing is in the way
        a1, a2 = ang + math.radians(150), ang - math.radians(150)
        hl = S(7)
        head = QPainterPath(tip)
        head.lineTo(QPointF(tip.x() + math.cos(a1) * hl, tip.y() + math.sin(a1) * hl))
        head.lineTo(QPointF(tip.x() + math.cos(a2) * hl, tip.y() + math.sin(a2) * hl))
        head.closeSubpath()
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(col)
        p.drawPath(head)
    else:                                                 # blocked: a small bar where it hits
        p.setPen(QPen(QColor("#FFFFFF"), S(2.4), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        nx, ny = -math.sin(ang) * S(6), math.cos(ang) * S(6)
        p.drawLine(QPointF(tip.x() - nx, tip.y() - ny), QPointF(tip.x() + nx, tip.y() + ny))
    if not meter:                                         # 5.15: the power is shown under the course
        p.restore()
        return
    side = -1 if math.cos(ang) > 0 else 1                # on the other side from the arrow
    if c.x() + side * S(50) > f.right():
        side = -1
    elif c.x() + side * S(50) < f.left():
        side = 1
    mx = c.x() + side * (BALL_R * u + S(10)) - (S(6) if side < 0 else 0)
    bar = QRectF(mx, c.y() - S(22), S(6), S(44))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(alpha("#000000", 0.55))
    p.drawRoundedRect(bar.adjusted(-S(1.5), -S(1.5), S(1.5), S(1.5)), S(4), S(4))
    fill = QRectF(bar.left(), bar.bottom() - bar.height() * pw, bar.width(), bar.height() * pw)
    g = QLinearGradient(bar.bottomLeft(), bar.topLeft())
    g.setColorAt(0, QColor("#3DDC84"))
    g.setColorAt(0.6, QColor("#FFC94D"))
    g.setColorAt(1, QColor("#FF5C5C"))
    p.setBrush(g)
    p.drawRoundedRect(fill, S(3), S(3))
    p.setPen(QColor("#FFFFFF"))
    p.setFont(font(9, QFont.Weight.Black))
    tx = bar.right() + S(4) if side > 0 else bar.left() - S(36)
    p.drawText(QRectF(tx, bar.top() - S(2), S(32), S(14)),
               int((Qt.AlignmentFlag.AlignLeft if side > 0 else Qt.AlignmentFlag.AlignRight) | Qt.AlignmentFlag.AlignVCenter),
               f"{int(round(pw * 100))}%")
    p.restore()


def paint_golf_zone(p: QPainter, kind: str, r: QRectF, now: float, push=None) -> None:
    """5.3: sand, ice, water, boost pads, walls and bumpers, the same on the course and in the help. Water is clearer:
    bright, with a white edge and moving ripples."""
    p.save()
    p.setPen(Qt.PenStyle.NoPen)
    if kind == "sand":
        p.setBrush(QColor("#E3C88A"))
        p.drawRoundedRect(r, S(10), S(10))
        p.setBrush(alpha("#9C7A3C", 0.35))
        rnd = random.Random(int(r.left() * 7 + r.top() * 13))
        for _ in range(int(max(4, r.width() * r.height() / S(60)))):
            p.drawEllipse(QPointF(rnd.uniform(r.left() + S(4), r.right() - S(4)), rnd.uniform(r.top() + S(4), r.bottom() - S(4))),
                          S(1.1), S(1.1))
    elif kind == "ice":
        p.setBrush(alpha("#D8F6FF", 0.70))
        p.setPen(QPen(alpha("#FFFFFF", 0.85), S(1.2)))
        p.drawRoundedRect(r, S(6), S(6))
        p.setPen(QPen(alpha("#FFFFFF", 0.55), S(1.2)))
        p.setClipRect(r)
        step = S(14)
        x = r.left() - r.height()
        while x < r.right():
            p.drawLine(QPointF(x, r.bottom()), QPointF(x + r.height() * 0.6, r.top()))
            x += step
    elif kind == "water":
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        g.setColorAt(0, QColor("#5CC8FF"))
        g.setColorAt(1, QColor("#1F6FE0"))
        p.setBrush(g)
        p.setPen(QPen(alpha("#FFFFFF", 0.9), S(2)))
        p.drawRoundedRect(r, S(8), S(8))
        p.setClipRect(r.adjusted(S(2), S(2), -S(2), -S(2)))
        p.setPen(QPen(alpha("#FFFFFF", 0.55), S(1.4), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        rows = max(1, int(r.height() / S(12)))
        for k in range(rows):
            y = r.top() + (k + 0.5) * r.height() / rows
            path = QPainterPath(QPointF(r.left(), y))
            x = r.left()
            while x <= r.right():
                path.lineTo(QPointF(x, y + math.sin(x / S(7) + now * 2.5 + k) * S(2)))
                x += S(3)
            p.drawPath(path)
    elif kind == "boost":
        px_, py_ = push or (1.0, 0.0)
        p.setBrush(alpha("#FFB627", 0.40))
        p.setPen(QPen(alpha("#FFD36B", 0.9), S(1.2)))
        p.drawRoundedRect(r, S(6), S(6))
        ang_ = math.atan2(py_, px_)
        p.setPen(QPen(QColor("#FFD36B"), S(2.5), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        for k in range(3):
            t_ = ((now * 1.5 + k / 3) % 1.0) - 0.5
            m_ = min(r.width(), r.height()) * 0.8
            c_ = r.center() + QPointF(math.cos(ang_) * t_ * m_, math.sin(ang_) * t_ * m_)
            for sgn in (-1, 1):
                p.drawLine(c_, c_ - QPointF(math.cos(ang_ + sgn * 0.6) * S(7), math.sin(ang_ + sgn * 0.6) * S(7)))
    elif kind == "wall":
        p.setBrush(QColor("#6B4423"))
        p.drawRoundedRect(r, S(3), S(3))
        p.setBrush(alpha("#FFFFFF", 0.12))
        p.drawRect(QRectF(r.left(), r.top(), r.width(), min(r.height(), S(3))))
    elif kind == "bumper":
        rad = min(r.width(), r.height()) / 2
        glow = QRadialGradient(r.center(), rad)
        glow.setColorAt(0, QColor("#FF7AD9"))
        glow.setColorAt(1, QColor("#9B2C7E"))
        p.setBrush(glow)
        p.drawEllipse(r.center(), rad, rad)
    elif kind == "cup":
        p.setBrush(QColor("#0B120D"))
        p.drawEllipse(r.center(), min(r.width(), r.height()) * 0.3, min(r.width(), r.height()) * 0.3)
        p.setPen(QPen(QColor("#EDEDED"), S(1.5)))
        top = r.center() - QPointF(0, r.height() * 0.45)
        p.drawLine(r.center(), top)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#FF4B4B"))
        flag = QPainterPath(top)
        flag.lineTo(top + QPointF(S(12), S(4)))
        flag.lineTo(top + QPointF(0, S(8)))
        flag.closeSubpath()
        p.drawPath(flag)
    p.restore()


def paint_golf_field(p: QPainter, f: QRectF, h: dict, now: float) -> None:
    """The course of one hole inside the field rect f (clipped by the caller): grass, zones, walls, bumpers, cup, tee."""
    u = f.width()

    def P(x, y):
        return QPointF(f.left() + x * u, f.top() + y * u)
    grass = QLinearGradient(f.topLeft(), f.bottomRight())
    grass.setColorAt(0, QColor("#2E9E4F"))
    grass.setColorAt(1, QColor("#1E7A3B"))
    p.fillRect(f, grass)
    p.setPen(Qt.PenStyle.NoPen)
    for k in range(0, 12, 2):                            # mowed stripes
        p.fillRect(QRectF(f.left() + k * u / 12, f.top(), u / 12, f.height()), alpha("#FFFFFF", 0.035))
    for kind in ("sand", "ice", "water"):                # 5.3: one painter for the course and the help
        for (x1, y1, x2, y2) in h.get(kind, []):
            paint_golf_zone(p, kind, QRectF(P(x1, y1), P(x2, y2)), now)
    for (x1, y1, x2, y2, px_, py_) in h.get("boost", []):
        paint_golf_zone(p, "boost", QRectF(P(x1, y1), P(x2, y2)), now, (px_, py_))
    wood = QColor("#6B4423")
    for (x1, y1, x2, y2) in h["rects"]:
        r = QRectF(P(x1, y1), P(x2, y2))
        p.setBrush(wood)
        p.drawRoundedRect(r, S(3), S(3))
        p.setBrush(alpha("#FFFFFF", 0.12))
        p.drawRect(QRectF(r.left(), r.top(), r.width(), min(r.height(), S(3))))
    for (bx, by, br) in h["circles"]:
        glow = QRadialGradient(P(bx, by), br * u)
        glow.setColorAt(0, QColor("#FF7AD9"))
        glow.setColorAt(1, QColor("#9B2C7E"))
        p.setBrush(glow)
        p.drawEllipse(P(bx, by), br * u, br * u)
    cx, cy = h["cup"]
    p.setBrush(QColor("#0B120D"))
    p.drawEllipse(P(cx, cy), CUP_R * u, CUP_R * u)
    p.setPen(QPen(QColor("#EDEDED"), S(1.5)))
    top = P(cx, cy) - QPointF(0, S(30))
    p.drawLine(P(cx, cy), top)
    flag = QPainterPath(top)
    wave = math.sin(now * 3) * S(2)
    flag.lineTo(top + QPointF(S(16), S(5) + wave))
    flag.lineTo(top + QPointF(0, S(10)))
    flag.closeSubpath()
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor("#FF4B4B"))
    p.drawPath(flag)
    tx, ty = h["tee"]
    p.setBrush(alpha("#FFFFFF", 0.12))
    p.drawRoundedRect(QRectF(P(tx - 0.03, ty - 0.05), P(tx + 0.03, ty + 0.05)), S(4), S(4))


GOLF_BLOCKS = [("wall", "Wall", "The ball bounces off it."),
               ("bumper", "Bumper", "Kicks the ball back harder than a wall."),
               ("sand", "Sand", "Slows the ball down a lot."),
               ("ice", "Ice", "Almost no slowing down: the ball keeps rolling."),
               ("boost", "Boost pad", "Pushes the ball the way the arrows point."),
               ("water", "Water", "Splash! The ball goes back to where you hit it from (the shot still counts)."),
               ("cup", "Cup", "Get the ball in. A slow ball close to it gets pulled in.")]


class GolfLegend(QWidget):
    """5.3: in the golf help, every kind of block on a little patch of grass, with what it does."""

    def __init__(self, w: int) -> None:
        super().__init__()
        self.row_h = S(48)
        self.setFixedSize(w, self.row_h * len(GOLF_BLOCKS))
        self._t = QTimer(self)
        self._t.setInterval(33)
        self._t.timeout.connect(self.update)

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        now = time.monotonic()
        for i, (kind, name, what) in enumerate(GOLF_BLOCKS):
            top = i * self.row_h
            patch = QRectF(0, top + S(3), S(64), self.row_h - S(6))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#2E9E4F"))
            p.drawRoundedRect(patch, S(8), S(8))
            inner = patch.adjusted(S(8), S(6), -S(8), -S(6))
            if kind == "wall":
                inner = QRectF(patch.left() + S(10), patch.center().y() - S(4), patch.width() - S(20), S(8))
            elif kind in ("bumper", "cup"):
                d = patch.height() - S(10)
                inner = QRectF(patch.center().x() - d / 2, patch.center().y() - d / 2, d, d)
            paint_golf_zone(p, kind, inner, now, (1.0, 0.0))
            p.setPen(QColor(TEXT))
            p.setFont(font(11.5, QFont.Weight.Bold))
            p.drawText(QRectF(S(76), top + S(2), self.width() - S(76), S(18)), int(Qt.AlignmentFlag.AlignVCenter), tr(name))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(9.5))
            p.drawText(QRectF(S(76), top + S(19), self.width() - S(78), self.row_h - S(19)),
                       int(Qt.AlignmentFlag.AlignTop | Qt.TextFlag.TextWordWrap), tr(what))


def start_pos(hole: dict, side: str):
    tx, ty = hole["tee"]
    return (tx, ty - 0.022) if side == "a" else (tx, ty + 0.022)


class GolfView(QWidget):
    """The course, both balls, the scoreboard and the aim. Asks the server every 0.6 s while a match is on."""

    def __init__(self, page, gid: str, solo: bool = False) -> None:
        super().__init__()
        self.page, self.ctx, self.gid = page, page.ctx, gid
        self.solo = solo                     # 4.3: a round alone: no opponent, no clock, coins by strokes
        w = page.W
        self.head_h = S(46)
        self.foot_h = S(34)                  # 5.15: the power bar lives under the course
        self.setFixedSize(w, int(self.head_h + w * FIELD_H + self.foot_h))
        self.g: dict = {}
        self.balls = {"a": None, "b": None}
        self.anim = None                     # (side, frames, i, then)
        self.anim_hole = 0
        self.seen = -1                       # last shot number shown
        self.aim = None                      # (press point, current point) in field units
        self.sending = False
        self._asking = False
        self._banner, self._banner_at = "", 0.0
        self._poll = QTimer(self)
        self._poll.setInterval(3000 if solo else 450)   # 4.0: the other player's shot shows sooner
        self._poll.timeout.connect(self.ask)
        self._frame = QTimer(self)
        self._frame.setInterval(16)
        self._frame.timeout.connect(self._step)
        self.setCursor(Qt.CursorShape.CrossCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)   # 5.1: Space shoots
        self.setMouseTracking(True)                       # 5.1: the aim follows the mouse
        self._pw_t0 = time.monotonic()
        self._was_mine = False
        self.ask()

    # -- server
    def showEvent(self, _e) -> None:
        self._poll.start()
        self._frame.start()

    def hideEvent(self, _e) -> None:
        self._poll.stop()
        self._frame.stop()

    def ask(self) -> None:
        if self._asking or self.anim is not None:
            return
        self._asking = True

        def got(ok: bool, data) -> None:
            self._asking = False
            if ok and isinstance(data, dict):
                self.set_state(data)
            elif not ok and "gone" in str(data).lower():
                self.ctx.golf_id = None
                self.ctx.golf_solo_id = None
                self.ctx.reload_page()
        self.ctx.online.ask("rb_golf_solo_state" if self.solo else "rb_golf_state", {"gid": self.gid}, got)

    def n_holes(self) -> int:
        return max(1, len(self.g.get("holes") or [1, 2, 3, 4, 5]))

    def hole(self, n: int = 0) -> dict:
        """The layout of hole n of this match; the current hole by default."""
        hs = list(self.g.get("holes") or [1, 2, 3, 4, 5])
        n = max(1, min(len(hs), int(n or self.g.get("hole") or 1)))
        return get_hole(int(hs[n - 1]) if len(hs) >= n else 1)

    def set_state(self, g: dict) -> None:
        self.g = g
        seen_hole = getattr(self, "_hole_was", None)
        self._hole_was = g.get("hole")
        if seen_hole is not None and seen_hole != g.get("hole") and g.get("state") == "live":
            self._banner, self._banner_at = tr("Hole {n} of {t}", n=g.get("hole"), t=self.n_holes()), time.monotonic()
            sfx.play("on")
        shots = sorted(g.get("shots") or [], key=lambda s: int(s.get("n") or 0))
        if self.seen < 0:                                    # just opened: no replay of old shots
            self.seen = int(g.get("seq") or 0) - 1
        new = [s for s in shots if int(s.get("n") or 0) > self.seen]
        if new and self.anim is None:
            s = new[0]
            self.seen = int(s["n"])
            if s.get("by") != g.get("me") or not getattr(self, "_mine_sent", False):
                frames, _x, _y, _in = simulate(self.hole(int(s.get("hole") or 0)), float(s["x0"]), float(s["y0"]),
                                               float(s["ang"]), float(s["pow"]))
                frames[-1] = (float(s["x"]), float(s["y"]))
                self.anim_hole = int(s.get("hole") or 0)
                self.anim = [s.get("by"), frames, 0, self._settle]
                return
        if not new:
            self.seen = max(self.seen, int(g.get("seq") or 0) - 1)
        self._settle()
        if g.get("state") == "done" and getattr(self, "_was", "") == "live":     # 4.3: also when our own shot ends it
            self._finished()
        self._was = g.get("state")

    def _settle(self) -> None:
        """Balls where the server says they are."""
        g = self.g
        h = self.hole()
        for side in ("a", "b"):
            pos = g.get("p" + side)
            if g.get(side + "_in"):
                self.balls[side] = None
            elif pos:
                self.balls[side] = (float(pos[0]), float(pos[1]))
            else:
                self.balls[side] = start_pos(h, side)
        self._mine_sent = False
        self.update()

    def _finished(self) -> None:
        g = self.g
        me = g.get("me")
        won = int(g.get("paid") or 0) > 0 if self.solo else g.get("winner") == me
        sfx.play("on" if won else "off")
        self.ctx.golf_list = None
        if self.solo:
            self.ctx.econ.refresh()
            QTimer.singleShot(400, lambda: self.ctx.reload_page("games"))     # the Play again button shows
        self.update()

    # -- playing
    def my_turn(self) -> bool:
        g = self.g
        return (g.get("state") == "live" and g.get("turn") == g.get("me") and self.anim is None and not self.sending
                and not g.get(str(g.get("me")) + "_in"))

    def field(self) -> QRectF:
        return QRectF(0, self.head_h, self.width(), self.width() * FIELD_H)

    def to_field(self, pt) -> tuple:
        f = self.field()
        return ((pt.x() - f.left()) / f.width(), (pt.y() - f.top()) / f.width())

    # 5.1: aim with the mouse (the ball points at it), the power bar swings up and down on its own: click or press
    # Space at the right moment. Timing is the skill.
    POWER_PERIOD = 1.6

    def power(self) -> float:
        """5.8: the further the mouse is from your ball, the harder the shot (no more swinging bar)."""
        return golf_power(self.balls.get(self.g.get("me")), self.aim[0] if self.aim else None)

    def _old_power(self) -> float:
        t = (time.monotonic() - getattr(self, "_pw_t0", 0.0)) % self.POWER_PERIOD
        half = self.POWER_PERIOD / 2
        ping = t / half if t < half else 2 - t / half
        return 0.06 + 0.94 * ping

    def mousePressEvent(self, e) -> None:
        self.setFocus()
        if e.button() == Qt.MouseButton.LeftButton and self.my_turn():
            self.aim = (self.to_field(e.position()), None)
            self._fire()

    def mouseMoveEvent(self, e) -> None:
        if self.my_turn():
            self.aim = (self.to_field(e.position()), None)
            self.update()

    def keyPressEvent(self, e) -> None:
        if e.key() == Qt.Key.Key_Space and not e.isAutoRepeat() and self.my_turn():
            return self._fire()
        super().keyPressEvent(e)

    def _shot(self):
        me = self.g.get("me")
        ball = self.balls.get(me) or (0.5, 0.3)
        (qx, qy), _ = self.aim
        return math.atan2(qy - ball[1], qx - ball[0]), self.power()

    def mouseReleaseEvent(self, e) -> None:
        pass

    def _fire(self) -> None:
        if self.aim is None:
            return
        ang, pw = self._shot()
        self.aim = None
        me = self.g.get("me")
        ball = self.balls.get(me)
        if pw < 0.04 or not self.my_turn() or ball is None:
            return self.update()
        frames, x, y, holed = simulate(self.hole(), ball[0], ball[1], ang, pw)
        x, y = round(x, 4), round(y, 4)
        n = int(self.g.get("seq") or 0)
        self.sending, self._mine_sent = True, True
        self.seen = n
        sfx.play("putt")
        self.anim_hole = int(self.g.get("hole") or 1)
        self.anim = [me, frames, 0, self._settle]

        def done(ok: bool, data) -> None:
            self.sending = False
            if ok and isinstance(data, dict):
                self.g = data if self.anim is None else dict(data, _wait=True)
                if self.anim is None:
                    self.set_state(data)
            else:
                self.ctx.toast(tr(str(data)), "warn")
                self._mine_sent = False
                self.ask()
        if self.solo:                                 # 8.0: the server rolls the shot too (from, angle, power)
            return self.ctx.online.ask("rb_golf_solo_shot", {"gid": self.gid, "n": n, "x0": ball[0], "y0": ball[1], "ang": ang,
                                                             "pow": pw, "x": x, "y": y, "holed": holed}, done)
        self.ctx.online.ask("rb_golf_shot", {"gid": self.gid, "n": n, "x0": ball[0], "y0": ball[1], "ang": ang,
                                             "pow": pw, "x": x, "y": y, "holed": holed}, done)

    def _step(self) -> None:
        if self.anim is not None:
            side, frames, i, then = self.anim
            i += 2 if len(frames) > 400 else 1
            if i >= len(frames) - 1:
                last = frames[-1]
                self.anim = None
                self.balls[side] = last
                cup = self.hole(self.anim_hole)["cup"]
                if math.hypot(last[0] - cup[0], last[1] - cup[1]) < 1e-3:
                    sfx.play("on")
                g = self.g
                more = any(int(s.get("n") or 0) > self.seen for s in g.get("shots") or [])
                if g.pop("_wait", None) or more:          # 4.0: shots that came in meanwhile play in order
                    self.set_state(g)
                else:
                    then()
                    self.ask()
            else:
                self.anim[2] = i
                self.balls[side] = frames[i]
            return self.update()
        # 4.0: nothing moves: no full repaint 60 times a second (the course is costly to draw). The aim line,
        # the hole banner and the turn clock still repaint when they change.
        now = time.monotonic()
        clock = int(now * 4)
        if self.aim is not None or self.my_turn() or now - self._banner_at < 2.5 or clock != getattr(self, "_clock", -1):
            self._clock = clock
            self.update()

    # -- drawing
    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        g = self.g
        h = self.hole(self.anim_hole) if self.anim is not None else self.hole()
        now = time.monotonic()
        self._paint_head(p, g)
        f = self.field()
        u = f.width()

        def P(x, y):
            return QPointF(f.left() + x * u, f.top() + y * u)
        clip = QPainterPath()
        clip.addRoundedRect(f, S(10), S(10))
        p.save()
        p.setClipPath(clip)
        paint_golf_field(p, f, h, now)                   # 5.6: shared with the parties
        me = g.get("me", "a")
        mine_now = self.my_turn()
        if mine_now and not self._was_mine:
            self._pw_t0 = time.monotonic()                   # the swing starts from the bottom each turn
        self._was_mine = mine_now
        if g.get("state") == "live" and not self.solo:       # 5.1: a strip saying whose turn it is
            pulse = 0.5 + 0.5 * math.sin(now * 4)
            whose = g.get("turn")
            strip = QRectF(f.left(), f.top(), f.width(), S(22))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#3DDC84" if whose == me else "#000000", (0.55 + 0.25 * pulse) if whose == me else 0.45))
            p.drawRect(strip)
            p.setPen(QColor("#06110A") if whose == me else QColor("#FFFFFF"))
            p.setFont(font(10.5, QFont.Weight.Black, 1.5))
            p.drawText(strip, int(Qt.AlignmentFlag.AlignCenter),
                       tr("YOUR TURN") if whose == me else tr("{name}'s turn", name=str(g.get(whose) or "?")))
        if self.my_turn() and self.balls.get(me) and self.aim is not None:      # 5.8: power from the mouse
            pw = self.power()
            col = QColor.fromHsvF(max(0.0, 0.33 - 0.33 * pw), 0.85, 1.0)
            paint_golf_aim(p, P, self.balls[me], self._shot()[0], pw, col, f, u, h)
        if self.my_turn():
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(9, QFont.Weight.Black))
            p.drawText(QRectF(f.left(), f.bottom() - S(20), f.width() - S(10), S(16)),
                       int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                       tr("Move the mouse away from the ball for more power · click to shoot"))
        for side in ("a", "b"):
            pos = self.balls.get(side)
            if pos is None:
                continue
            c = P(*pos)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#000000", 0.3))
            p.drawEllipse(c + QPointF(S(1.5), S(2)), BALL_R * u, BALL_R * u)
            ring = ui.accent if side == me else QColor("#FFB627")
            if side == me:                                  # 5.1: your ball is easy to find
                pulse = 0.5 + 0.5 * math.sin(now * 4)
                p.setPen(QPen(alpha(ring, 0.35 + 0.35 * pulse), S(2)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(c, BALL_R * u * (2.0 + 0.4 * pulse), BALL_R * u * (2.0 + 0.4 * pulse))
            p.setBrush(QColor("#FFFFFF"))
            p.setPen(QPen(ring, S(2.5)))
            p.drawEllipse(c, BALL_R * u, BALL_R * u)
            p.setPen(ring)
            p.setFont(font(8.5, QFont.Weight.Black))
            label = tr("YOU") if side == me else str(g.get(side) or g.get(side + "_name") or "")
            if label:
                p.drawText(QRectF(c.x() - S(50), c.y() - BALL_R * u - S(18), S(100), S(14)), int(Qt.AlignmentFlag.AlignCenter),
                           label)
        if self._banner and now - self._banner_at < 2.0:
            a = min(1.0, 2.0 - (now - self._banner_at))
            p.setOpacity(a)
            p.fillRect(QRectF(f.left(), f.center().y() - S(22), f.width(), S(44)), alpha("#000000", 0.55))
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(16, QFont.Weight.Black))
            p.drawText(f, int(Qt.AlignmentFlag.AlignCenter), self._banner)
            p.setOpacity(1.0)
        if g.get("state") == "done" and self.solo:
            p.fillRect(f, alpha("#000000", 0.6))
            paid = int(g.get("paid") or 0)
            total = sum(int(x or 0) for x in (g.get("a_strokes") or []))
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(20, QFont.Weight.Black))
            p.drawText(QRectF(f.left(), f.center().y() - S(34), f.width(), S(30)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Round over: {n} strokes", n=total))
            p.setFont(font(13, QFont.Weight.Bold))
            p.setPen(QColor("#E8C26A") if paid else QColor(TEXT_DIM))
            p.drawText(QRectF(f.left(), f.center().y() + S(2), f.width(), S(24)), int(Qt.AlignmentFlag.AlignCenter),
                       ("+" + coins_text(paid) + " " + tr("coins")) if paid else tr("No coins this time"))
        elif g.get("state") == "done":
            p.fillRect(f, alpha("#000000", 0.6))
            won, draw = g.get("winner") == me, not g.get("winner")
            p.setPen(QColor("#3DDC84") if won else QColor("#FFFFFF"))
            p.setFont(font(20, QFont.Weight.Black))
            text = tr("Draw") if draw else (tr("You win!") if won else tr("{name} wins", name=g.get("b" if me == "a" else "a")))
            p.drawText(QRectF(f.left(), f.center().y() - S(30), f.width(), S(30)), int(Qt.AlignmentFlag.AlignCenter), text)
            bet = int(g.get("bet") or 0)
            if bet:
                p.setFont(font(12, QFont.Weight.Bold))
                p.setPen(QColor(TEXT))
                sub = (tr("Bets refunded") if draw else
                       ("+" + coins_text(int(bet * 2 * 0.95)) if won else "−" + coins_text(bet)))
                p.drawText(QRectF(f.left(), f.center().y() + S(4), f.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter), sub)
        p.restore()
        foot = QRectF(0, f.bottom() + S(4), self.width(), self.foot_h - S(4))      # 5.15: the power, under the course
        aiming = self.my_turn() and self.balls.get(g.get("me", "a")) and self.aim is not None
        paint_power_strip(p, foot, self.power() if aiming else None,
                          tr("Your turn: move the mouse away from your ball") if self.my_turn() else tr("Power"))

    def _paint_head(self, p: QPainter, g: dict) -> None:
        r = QRectF(0, 0, self.width(), self.head_h - S(6))
        paint_surface(p, r, S(DS.R_MD), 0.05)   # 8.0: shared surface
        if self.solo:
            return self._paint_solo_head(p, g, r)
        me = g.get("me", "a")
        hole = int(g.get("hole") or 1)
        w = r.width() / 3
        for i, side in enumerate(("a", "b")):
            box = QRectF(r.left() + (0 if i == 0 else 2 * w), r.top(), w, r.height())
            strokes = list(g.get(side + "_strokes") or [0])
            active = g.get("state") == "live" and g.get("turn") == side
            if active:                                    # 5.1: whose turn it is, at a glance
                pulse = 0.5 + 0.5 * math.sin(time.monotonic() * 4)
                hl = ui.accent if side == me else QColor("#FFB627")
                p.setPen(QPen(alpha(hl, 0.5 + 0.4 * pulse), S(2)))
                p.setBrush(alpha(hl, 0.12 + 0.08 * pulse))
                p.drawRoundedRect(box.adjusted(S(2), S(2), -S(2), -S(2)), S(8), S(8))
            p.setPen(ui.accent if side == me else QColor("#FFB627"))
            p.setFont(font(11, QFont.Weight.Bold))
            name = str(g.get(side) or "?")
            p.drawText(box.adjusted(S(8), S(3), -S(8), -r.height() / 2), int(Qt.AlignmentFlag.AlignVCenter |
                       (Qt.AlignmentFlag.AlignLeft if i == 0 else Qt.AlignmentFlag.AlignRight)), ("● " if active and i == 0 else "")
                       + name + (" ●" if active and i == 1 else ""))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10, QFont.Weight.DemiBold))
            p.drawText(box.adjusted(S(8), r.height() / 2, -S(8), -S(3)), int(Qt.AlignmentFlag.AlignVCenter |
                       (Qt.AlignmentFlag.AlignLeft if i == 0 else Qt.AlignmentFlag.AlignRight)),
                       (lambda n: tr("1 stroke") if n == 1 else tr("{n} strokes", n=n))(sum(int(x or 0) for x in strokes)))
        mid = QRectF(r.left() + w, r.top(), w, r.height())
        p.setPen(QColor(TEXT))
        p.setFont(font(11, QFont.Weight.Black))
        p.drawText(mid.adjusted(0, S(3), 0, -r.height() / 2), int(Qt.AlignmentFlag.AlignCenter),
                   tr("Hole {n} of {t}", n=hole, t=self.n_holes()) if g.get("state") == "live" else tr("Final score"))
        p.setFont(font(10, QFont.Weight.DemiBold))
        if g.get("state") == "live":
            left = max(0, int(float(g.get("left") or 0)))
            mine = g.get("turn") == me
            p.setPen(QColor("#3DDC84") if mine else QColor(TEXT_DIM))
            text = tr("Your turn · {s} s", s=left) if mine else tr("Waiting · {s} s", s=left)
            p.drawText(mid.adjusted(0, r.height() / 2, 0, -S(3)), int(Qt.AlignmentFlag.AlignCenter), text)


    SOLO_PAYS = (60, 35, 20, 10, 5, 0)

    def _paint_solo_head(self, p: QPainter, g: dict, r: QRectF) -> None:
        """4.3 solo: your strokes, the hole, and what holing the next shot pays."""
        w = r.width() / 3
        hole = int(g.get("hole") or 1)
        strokes = list(g.get("a_strokes") or [0])
        left, mid, right = (QRectF(r.left() + i * w, r.top(), w, r.height()) for i in range(3))
        top_half = lambda b: b.adjusted(S(8), S(3), -S(8), -r.height() / 2)
        low_half = lambda b: b.adjusted(S(8), r.height() / 2, -S(8), -S(3))
        p.setPen(ui.accent)
        p.setFont(font(11, QFont.Weight.Bold))
        p.drawText(top_half(left), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), str(g.get("a") or ""))
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(10, QFont.Weight.DemiBold))
        n = sum(int(x or 0) for x in strokes)
        p.drawText(low_half(left), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft),
                   tr("1 stroke") if n == 1 else tr("{n} strokes", n=n))
        p.setPen(QColor(TEXT))
        p.setFont(font(11, QFont.Weight.Black))
        p.drawText(top_half(mid), int(Qt.AlignmentFlag.AlignCenter),
                   tr("Hole {n} of {t}", n=hole, t=self.n_holes()) if g.get("state") == "live" else tr("Final score"))
        p.setPen(QColor("#3DDC84"))
        p.setFont(font(10, QFont.Weight.DemiBold))
        if g.get("state") == "live":
            p.drawText(low_half(mid), int(Qt.AlignmentFlag.AlignCenter), tr("Solo · no clock"))
            now_s = int(strokes[hole - 1] if len(strokes) >= hole else 0)
            pays = self.SOLO_PAYS[min(5, now_s)]
            p.setPen(QColor(TEXT_DIM))
            p.drawText(top_half(right), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight), tr("Hole it now"))
            p.setPen(QColor("#E8C26A") if pays else QColor(TEXT_DIM))
            p.setFont(font(11, QFont.Weight.Bold))
            p.drawText(low_half(right), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight), "+" + coins_text(pays))


class LobbyRow(QWidget):
    """One open lobby: who opened it, the bet, how long it stays, and Join (or Close for your own)."""

    def __init__(self, page, m: dict) -> None:
        super().__init__()
        self.m = m
        self.setFixedHeight(S(50))
        lay = hbox(self, 6)
        lay.setContentsMargins(S(10), 0, S(6), 0)
        bet = int(m.get("bet") or 0)
        name = Label(str(m.get("host", "?")), 12, TEXT, bold=True)
        name.setFixedWidth(name.text_width() + S(8))
        lay.addWidget(name)
        lay.addStretch(1)
        money = vbox(spacing=0)                          # 4.6: the bet, big and gold, and what the winner takes
        money.addWidget(Label(coins_text(bet) if bet else tr("No bet"), 13.5 if bet else 10.5, "#E8C26A" if bet else TEXT_DIM,
                              bold=True, align=Qt.AlignmentFlag.AlignRight).fit(), 0, Qt.AlignmentFlag.AlignRight)
        if bet:
            money.addWidget(Label(tr("win {n}", n=coins_text(int(bet * 2 * 0.95))), 8.5, TEXT_DIM,
                                  align=Qt.AlignmentFlag.AlignRight).fit(), 0, Qt.AlignmentFlag.AlignRight)
        lay.addLayout(money)
        if m.get("mine"):
            b = Button(tr("Close"), "ghost", 30)
            b.clicked.connect(lambda: golf_cancel(page, m["id"]))
        else:
            b = Button(tr("Join"), "primary", 32, icon="play")
            b.setFixedWidth(max(S(84), b.sizeHint().width()))
            b.clicked.connect(lambda: golf_join(page, m))
            self.setCursor(Qt.CursorShape.PointingHandCursor)   # 4.6: the whole row joins
        self.join_btn = b
        lay.addWidget(b)
        self._t0, self._left = time.monotonic(), int(m.get("left") or 0)
        self._tick = QTimer(self)
        self._tick.setInterval(1000)
        self._tick.timeout.connect(self.update)
        self._tick.start()

    def mouseReleaseEvent(self, e) -> None:
        if not self.m.get("mine") and e.button() == Qt.MouseButton.LeftButton and self.rect().contains(e.position().toPoint()):
            self.join_btn.clicked.emit()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        paint_surface(p, r, S(DS.R_MD), 0.05, edge=alpha(ui.accent, 0.5) if self.m.get("mine") else alpha("#E8C26A", 0.25))   # 8.0: shared surface
        left = max(0, self._left - int(time.monotonic() - self._t0))
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9.5, QFont.Weight.DemiBold))
        p.drawText(QRectF(r.left() + S(10), r.bottom() - S(15), r.width() * 0.5, S(13)), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("Closes in {t}", t=f"{left // 60}:{left % 60:02d}"))


# ---------------------------------------------------------------- 5.8: online golf, turn by turn (2 to 4 players)
PARTY_COLOURS = ["#4FC3FF", "#FFB627", "#FF5C8A", "#3DDC84"]


def party_tee(h: dict, seat: int):
    tx, ty = h["tee"]
    return (tx, max(0.02, min(0.6, ty + (seat - 1.5) * 0.022)))


