    # -- 2.4: sub-screens (Memory, duels, scratch card)
    def open_sub(self, name) -> None:
        if claim_blocked(self.ctx):
            return
        if name == "minigames":                       # 9.0.1: the old "Earn coins" list is gone: back to where you came from
            return leave_free_game(self.ctx)
        sfx.play("pick")
        for flag in ("quests_open", "mini_open", "park_open"):
            setattr(self.ctx, flag, False)
        self.ctx.games_sub = name
        self.ctx.reload_page()

    def _back_bar(self, lay, title: str, on_back=None, help_key=None) -> None:
        top = hbox(spacing=8)
        back = IconButton("back", 32, tip=tr("Back"))
        back.clicked.connect(on_back or (lambda: self.open_sub(None)))
        top.addWidget(back)
        top.addWidget(Label(title, 16, bold=True), 1)
        if help_key:                                     # 4.2: the golden "?" of the game
            pass
            top.addWidget(HelpButton(self.ctx, help_key))
        lay.addLayout(top)
        lay.addWidget(CoinBar(self.ctx))

