    def _scratch(self, lay) -> None:
        self._back_bar(lay, tr("Scratch card"), lambda: leave_free_game(self.ctx), "scratch")   # 9.2: back where it was opened
        card = ScratchCard(self)
        lay.addWidget(card)
        hours = int(float(self.ctx.econ.cfg.get("scratch_hours", 12) or 12))
        lay.addWidget(Label(tr("One card every {h} hours.", h=hours),
                            10.5, TEXT_DIM, wrap_w=self.W))
        odds = getattr(self.ctx, "scratch_odds", None)            # 4.0: the server's own odds, never a copy
        holder = QWidget()                                        # 9.1: filled in place, never by rebuilding the page
        hl = vbox(holder, 6)                                      # (a rebuild threw away a card being scratched)
        lay.addWidget(holder)

        def show(rows) -> None:
            try:
                if rows and not hl.count():
                    hl.addWidget(heading(tr("Chances")))
                    hl.addWidget(ScratchOdds(rows, self.W))
            except RuntimeError:
                pass
        if odds is None:
            def got(ok: bool, data) -> None:                      # 9.2: the page is laid out again with the chances
                if ok and isinstance(data, list):                 # under the card (added late they sat on top of it)
                    self.ctx.scratch_odds = data
                    try:
                        untouched = not card.asked and not card.prize
                    except RuntimeError:
                        return
                    if untouched and getattr(self.ctx, "games_sub", None) == "scratch" \
                            and self.ctx.window.showing("games"):
                        self.ctx.reload_page("games")
            self.ctx.online.ask("rb_scratch_odds", {}, got)
        else:
            show(odds)

    def load_duels(self, quiet: bool = False) -> None:
        ctx = self.ctx

        def got(ok: bool, data) -> None:
            if ok and isinstance(data, list) and data != getattr(ctx, "duels_data", None):
                ctx.duels_data = data
                ctx.econ.refresh()                      # a duel ended: the pot (or the bet back) is in the balance
                if ctx.window.showing("games") and getattr(ctx, "games_sub", None) == "duels":
                    ctx.reload_page("games")

        def friends(ok: bool, data) -> None:
            if ok and isinstance(data, list):
                rows = [{"name": f.get("username") or f.get("name"), "online": f.get("online")} for f in data
                        if f.get("state", "friend") == "friend" and (f.get("username") or f.get("name"))]
                rows.sort(key=lambda f: (not f.get("online"), str(f["name"]).lower()))
                if rows != getattr(ctx, "duel_friends", None):
                    ctx.duel_friends = rows
                    if ctx.window.showing("games") and getattr(ctx, "games_sub", None) == "duels":
                        ctx.reload_page("games")
        ctx.econ.call("rb_duels", {}, got)
        if not quiet or getattr(ctx, "duel_friends", None) is None:
            ctx.online.ask("rb_friends_list", {}, friends)

    def duel_answer(self, did: str, yes: bool, play: dict = None) -> None:
        def done(ok: bool, data) -> None:
            if not ok:
                return self.ctx.toast(tr(str(data)), "warn")
            sfx.play("on" if yes else "off")
            if yes and play:                            # 4.6: accept and play in one click
                return self.duel_play(play)
            self.load_duels()
        self.ctx.econ.call("rb_duel_answer", {"duel": did, "yes": yes}, done)

    def duel_play(self, d: dict) -> None:
        sent = time.monotonic()

        def done(ok: bool, data) -> None:
            if not ok or not isinstance(data, dict):
                return self.ctx.toast(tr(str(data)), "warn")
            self.ctx.duel_run = dict(data, id=d["id"], other=d.get("other"), sent=sent)
            self.open_sub("duel_run")
        self.ctx.econ.call("rb_duel_play", {"duel": d["id"]}, done)

    def _duel_run(self, lay) -> None:
        run = getattr(self.ctx, "duel_run", None) or {}
        game, data = run.get("game"), run.get("data") or {}
        self._back_bar(lay, tr("Duel vs {name}", name=run.get("other", "?")), lambda: self.open_sub("duels"), "duels")

        def ended(_res) -> None:
            self.ctx.duels_data = None
            self.load_duels(quiet=True)
        if game == "tap":
            w = BeatRush(self, ended)
            lay.addWidget(w)
            QTimer.singleShot(300, lambda: w.begin(data, run.get("sent", time.monotonic()), duel=True))
        elif game == "memory":
            w = MemoryGame(self, ended)
            lay.addWidget(w)
            w.begin(data, duel=True)
        elif game == "park":
            self.park = w = Parking(self)
            w.round, w.layout_, w.best = data.get("round", ""), data.get("layout", ""), int(data.get("best") or 0)
            w.duel = True
            lay.addWidget(w)
            again = Button(tr("Start over"), "ghost", 34)
            again.clicked.connect(w.restart)
            lay.addWidget(again)
            QTimer.singleShot(30, w.restart)


