    # -- the casino
    def _casino(self, lay) -> None:
        ctx = self.ctx
        top = hbox(spacing=6)
        back = IconButton("back", 40, tip=tr("Back"))
        back.clicked.connect(ctx.leave_casino)
        self.back = back
        top.addWidget(back)
        if getattr(ctx, "online_mode", False):           # 9.0: the top bar shows the coins: the game's name here
            self.game_title = Label("", 20, weight=QFont.Weight.ExtraBold)
            top.addWidget(self.game_title, 1)
        else:
            self.game_title = None
            top.addWidget(CoinBar(ctx, keys=True), 1)
        top.addWidget(HelpButton(ctx, lambda: CASINO_KEYS.get(self.NAMES[self.games.index(self.game)])
                                 if self.game in getattr(self, "games", []) else None, 36))
        lay.addLayout(top)
        lock_strip(ctx, lay, "casino", self.W)                   # 4.0: paused by the admins
        which = ctx.cfg["game"] if 0 <= ctx.cfg["game"] < len(self.NAMES) else 0     # 4.2: the free spin too
        if getattr(ctx, "casino_pick", None) is not None:           # a tile of the lobby was clicked
            which, ctx.casino_pick = ctx.casino_pick, None
        group = SKILL_GAMES if self.NAMES[min(which, self.PICKER - 1)] in SKILL_GAMES else GAMBLE_GAMES
        self.pick_map = [self.NAMES.index(n) for n in group]       # 9.1: the bar shows the casino or the mini games
        self.seg = GamePicker([tr(n) for n in group], self.pick_map.index(which) if which in self.pick_map else 0)
        self.seg.changed.connect(lambda i: self._choose(self.pick_map[i]))
        if which < self.PICKER and which not in self.pick_map:
            which = self.pick_map[0]
        lay.addWidget(self.seg)
        pass
        pass
        self.games = [Blackjack(self), Plinko(self), Bombs(self), Roulette(self), Dice(self), Timing(self), Rocket(self),
                      HiLo(self), Tower(self), Slots(self), CupGame(self), ConnectFour(self), ColourPick(self), SfxMatch(self),
                      Daily(self)]
        for g in self.games:
            g.setVisible(False)
            lay.addWidget(g)
        controls = QWidget()                         # same height for every game: the card never jumps
        controls.setFixedHeight(S(76))
        cl = vbox(controls, 8)
        self.opts = []
        for g in self.games:
            spec = g.options()
            seg = None
            if spec:
                seg = Segmented(spec[0], spec[1])
                seg.changed.connect(lambda i, game=g: (game.set_option(i), self.sync()))
                seg.hide()
                cl.addWidget(seg)
            self.opts.append(seg)
        self.bet_row = QWidget()                     # 4.5: one slider, from 10 to what your balance allows
        self.bet_row.setFixedHeight(S(34))
        self.bet_lay = hbox(self.bet_row, 6)
        self.bet_slider = None
        self._bet_top = -1
        self.bet_quick = []                          # 9.0: ½, 2× and Max beside the slider
        for label, fn in (("½", lambda b: b // 2), ("2×", lambda b: b * 2), (tr("Max"), lambda b: 10 ** 12)):
            q = Button(label, "ghost", 30)
            q.setFixedWidth(S(48))
            q.clicked.connect(lambda _=False, f=fn: self._bet_quick(f))
            self.bet_lay.addWidget(q)
            self.bet_quick.append(q)
        self._bet_slider()
        cl.addStretch(1)
        cl.addWidget(self.bet_row)
        lay.addWidget(controls)
        self.actions = QWidget()
        self.actions.setFixedHeight(S(38))
        self.act_lay = hbox(self.actions, 6)
        self.act_buttons: list = []
        lay.addWidget(self.actions)
        pass
        self.controls_bar = None                     # 9.0: keys still work (Space, 2, 3, ← →); the ? lists them
        self._keys = KeyPoll(["Space", "1", "2", "3", "4", "Left", "Right"], self._casino_key,
                             lambda: self.game is not None and self.game.busy)
        lay.addWidget(self._keys)
        self._choose(which)
        ctx.wallet.changed.connect(self.sync)

    # -- bet
    def max_bet(self) -> int:
        """4.5: the most you can bet: your balance, up to a limit that grows with it (the server's rb_bet_cap).
        6.3: half of your coins; a game with its own limit (Cup Game) keeps it."""
        bal = int(self.ctx.wallet.balance())
        top = min(bal, self.ctx.econ.bet_cap(bal))
        own = getattr(self.game, "BET_CFG", None)
        if own:
            try:
                top = min(top, int(float(self.ctx.econ.cfg.get(own[0], own[1]) or own[1])))
            except (TypeError, ValueError, AttributeError):
                top = min(top, own[1])
        return top

    def bet(self) -> int:
        """The bet, never more than you can."""
        if self.game is not None and self.game.busy and not isinstance(self.game, Plinko):
            return self.game.stake
        top = self.max_bet()
        if top < 10:
            return 0
        want = getattr(self.ctx, "casino_bet", None) or self.ctx.cfg["casino_bet"] or 50
        return max(10, min(top, int(want)))

    def _bet_slider(self) -> None:
        """(Re)build the slider when the most you can bet changes."""
        top = max(10, self.max_bet())
        if top == self._bet_top and self.bet_slider is not None:
            return
        self._bet_top = top
        if self.bet_slider is not None:
            self.bet_slider.hide()
            self.bet_slider.deleteLater()
        pass
        self.bet_slider = AmountSlider(tr("Bet"), 10, top, self.bet() or 10, coins_text, label_w=40)
        self.bet_slider.changed.connect(self._bet_set)
        self.bet_lay.insertWidget(0, self.bet_slider, 1)
        self._bet_warn()

    def _bet_set(self, v: int) -> None:
        self.ctx.casino_bet = int(v)
        self.ctx.cfg["casino_bet"] = int(v)          # 9.0: kept for next time
        self.ctx.cfg.save()
        self._bet_warn()

    def _bet_quick(self, f) -> None:
        """9.0: halve, double or max the bet in one click (the slider snaps to the nearest step)."""
        sl = self.bet_slider
        if sl is None or (self.game is not None and self.game.busy):
            return
        want = max(10, min(self.max_bet(), int(f(self.bet()))))
        vals = sl.values
        v = min(vals, key=lambda x: abs(x - want)) if vals else want
        sl.set_value(v)
        self._bet_set(v)
        sfx.play("pick")

    def _bet_warn(self) -> None:
        """6.3: a big bet shows in gold (over 10 000) and red (a quarter of your coins or more)."""
        if self.bet_slider is None:
            return
        v, bal = self.bet(), max(1, int(self.ctx.wallet.balance()))
        self.bet_slider.val.set_color(LOSE if v > BIG_BET and v * 4 >= bal else GOLD_TEXT if v > BIG_BET else TEXT)

    def _casino_key(self, name: str, down: bool) -> None:
        if not down or self.game is None or not self.game.isVisible() or isinstance(self.game, Daily):
            return
        if name in ("Left", "Right"):
            return None if getattr(self.game, "FREE", False) else self._step(-1 if name == "Left" else 1)
        i = 0 if name in ("Space", "1") else int(name) - 1
        if i < len(self.act_buttons) and self.act_buttons[i].isEnabled() and self.act_buttons[i].isVisible():
            self.act_buttons[i].click()

    def _step(self, d: int) -> None:
        """← / →: the next round value down or up."""
        sl = self.bet_slider
        if sl is None or (self.game is not None and self.game.busy):
            return
        vals = sl.values
        cur = self.bet()
        i = min(range(len(vals)), key=lambda k: abs(vals[k] - cur))
        i = max(0, min(len(vals) - 1, i + d))
        sl.set_value(vals[i])
        self._bet_set(vals[i])
        sfx.play("pick")

    # -- which game
    def _choose(self, i: int) -> None:
        if self.game is not None and self.game.busy:              # finish the round first
            cur = self.games.index(self.game)
            return self.seg.set_index(self.pick_map.index(cur) if cur in self.pick_map else 0)
        spin = i >= self.PICKER
        self.seg.setVisible(not spin and not getattr(self.ctx, "wide_games", False))   # 9.1: the side list when wide
        if not spin:
            self.ctx.cfg["game"] = i
            self.ctx.games_sub = "casino" if self.NAMES[i] in GAMBLE_GAMES else None
        for n, g in enumerate(self.games):
            g.setVisible(n == i)
            if self.opts[n] is not None:
                self.opts[n].setVisible(n == i)
        self.game = self.games[i]
        if getattr(self, "game_title", None) is not None:
            self.game_title.set_text(tr(self.NAMES[i]))
        self.bet_row.setVisible(self.NAMES[i] != "Free spin" and not getattr(self.game, "FREE", False))   # 9.1: mini games: no bet
        if getattr(self, "controls_bar", None) is not None:          # 6.0: no casino keys on the free spin / scratch card
            self.controls_bar.setVisible(not isinstance(self.game, Daily))
        self.sync()

    def sync(self) -> None:
        """Buttons and bet follow the state of the game."""
        if self.game is None:
            return
        busy = self.game.busy
        if not busy:
            self._bet_slider()
        if self.bet_slider is not None:
            self.bet_slider.setEnabled(not busy)
        for q in self.bet_quick:
            q.setEnabled(not busy)
        self.seg.setEnabled(not busy)
        self.back.setEnabled(not busy)
        for seg in self.opts:
            if seg is not None:
                seg.setEnabled(not busy)
        spec = self.game.buttons()
        if [s[0] for s in spec] != [b.text_key for b in self.act_buttons]:
            for b in self.act_buttons:
                b.hide()
                b.deleteLater()
            self.act_buttons = []
            for text, kind, call, _on, *how in spec:
                b = Button(text, kind, 38)
                b.text_key = text
                (b.pressed if how and how[0] == "press" else b.clicked).connect(call)
                b.keycap = ("" if isinstance(self.game, Daily) else                                  # 6.0
                            "Space" if not self.act_buttons else str(len(self.act_buttons) + 1))     # 4.5: keys
                self.act_lay.addWidget(b)
                self.act_buttons.append(b)
        for b, (_t, _k, _c, on, *_how) in zip(self.act_buttons, spec):
            b.setEnabled(bool(on))

    def busy(self) -> bool:
        return self.game is not None and self.game.busy

    def sync_labels(self) -> None:
        """While the rocket flies its button shows the growing prize: refresh the text only."""
        for b, (text, _k, _c, on, *_how) in zip(self.act_buttons, self.game.buttons()):
            if b._text != text:
                b._text = text
                b.text_key = text
                b.update()
            b.setEnabled(bool(on))

    def wrap_up(self) -> None:
        """You left the casino mid-round: a waiting hand stands, an open board cashes out (or gives the bet back
        if no card was turned). Rounds already running simply finish."""
        g = self.game
        if isinstance(g, Blackjack) and g.phase == "player":
            g.stand()
        elif isinstance(g, Bombs) and g.phase == "play":
            if g.found():
                g.cash()
            else:                                   # nothing turned yet: the board waits on the server and
                g.phase = "idle"                    # comes back the next time Bombs is started
                g.busy = False
                self.sync()
        elif isinstance(g, Rocket) and g.phase == "fly":
            g.cash()

    def on_show(self) -> None:
        self.sync()

    def on_hide(self) -> None:
        if getattr(self.ctx, "games_sub", None) == "duel_run" or getattr(self.ctx, "mini_open", False):
            QTimer.singleShot(0, self._keys_back)       # (not on a rebuild of the same screen)

    def _keys_back(self) -> None:
        """The keyboard goes back to the game you play once no keyboard game is on screen."""
        ctx = self.ctx
        still = ctx.window.showing("games") and (getattr(ctx, "games_sub", None) == "duel_run"
                                                 or getattr(ctx, "mini_open", False))
        if not still:
            ctx.window.allow_keys(False)


