# ================================================================ daily deals
class DealCard(QWidget):
    """One deal: the item, its old and new price and how much is saved."""

    def __init__(self, page, d: dict, width: int) -> None:
        super().__init__()
        self.page, self.ctx, self.d = page, page.ctx, d
        self.setFixedSize(width, S(150))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.owned = not d["item"].startswith("badge:") and self.ctx.econ.owns(d["item"])
        self.sold = bool(d.get("bought"))                  # 4.7: one of each deal a day
        self._t = QTimer(self)
        self._t.setInterval(50)
        self._t.timeout.connect(self.update)

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def mouseReleaseEvent(self, e) -> None:
        if not self.rect().contains(e.position().toPoint()):
            return
        sfx.play("pick")
        self.ctx.window.embed(DealSheet(self.ctx, self.d, self.owned, self.sold))   # 4.5: see it before you buy it


    def paintEvent(self, _e) -> None:
        pass
        pass
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        col = QColor(RARITY_COLOURS.get(self.ctx.econ.rarity(self.d["item"]), "#9AA4AD"))
        g = QLinearGradient(r.topLeft(), r.bottomLeft())
        g.setColorAt(0, mix(col, QColor("#0B0E10"), 0.75))
        g.setColorAt(1, QColor("#0B0E10"))
        p.setPen(QPen(alpha(col, 0.5), S(1.2)))
        p.setBrush(g)
        p.drawRoundedRect(r, S(12), S(12))
        paint_cosmetic(p, self.d["item"], QRectF(r.center().x() - S(26), r.top() + S(12), S(52), S(52)), time.monotonic())
        tag = QRectF(r.right() - S(46), r.top() + S(8), S(38), S(18))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#FF5C6C"))
        p.drawRoundedRect(tag, S(9), S(9))
        p.setPen(QColor("#FFFFFF"))
        p.setFont(font(9.5, QFont.Weight.ExtraBold))
        p.drawText(tag, int(Qt.AlignmentFlag.AlignCenter), f"-{self.d['pct']}%")
        name = QFontMetrics(font(10.5, QFont.Weight.Bold)).elidedText(item_name(self.d["item"]), Qt.TextElideMode.ElideRight,
                                                                       int(r.width() - S(12)))
        p.setPen(QColor(TEXT))
        p.setFont(font(10.5, QFont.Weight.Bold))
        p.drawText(QRectF(r.left() + S(6), r.top() + S(70), r.width() - S(12), S(18)), int(Qt.AlignmentFlag.AlignCenter), name)
        p.setPen(QColor(TEXT_FAINT))
        p.setFont(font(10))
        old = coins_text(int(self.d["price"]))
        rect = QRectF(r.left(), r.top() + S(92), r.width(), S(16))
        p.drawText(rect, int(Qt.AlignmentFlag.AlignCenter), old)
        w = QFontMetrics(font(10)).horizontalAdvance(old)
        p.setPen(QPen(alpha(TEXT_FAINT, 0.9), 1))
        p.drawLine(QPointF(rect.center().x() - w / 2 - 2, rect.center().y()), QPointF(rect.center().x() + w / 2 + 2, rect.center().y()))
        p.setPen(QColor(GOLD_TEXT if not (self.owned or self.sold) else TEXT_DIM))
        p.setFont(font(14, QFont.Weight.ExtraBold))
        p.drawText(QRectF(r.left(), r.top() + S(110), r.width(), S(26)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("Owned") if self.owned else tr("Sold out") if self.sold else coins_text(int(self.d["now"])))
        if not (self.owned or self.sold):
            p.setPen(QColor(TEXT_FAINT))
            p.setFont(font(8.5, QFont.Weight.Bold))
            p.drawText(QRectF(r.left() + S(8), r.top() + S(8), S(60), S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                       tr("1 left"))


class DealSheet(QWidget):
    """4.5: a deal, up close: the item shown big (a theme is tried on the menu), then Buy or Back."""

    def __init__(self, ctx, d: dict, owned: bool, sold: bool = False) -> None:
        super().__init__()
        pass
        pass
        pass
        self.ctx, self.d = ctx, d
        w = ctx.window.page_w()
        self.setFixedWidth(w)
        lay = vbox(self, 8)
        item = d["item"]
        top = hbox(spacing=8)
        back = IconButton("back", 30, tip=tr("Back"))
        back.clicked.connect(self._close)
        top.addWidget(back)
        top.addWidget(Label(item_name(item), 15, bold=True), 1)
        lay.addLayout(top)
        kind = item.split(":")[0]
        lay.addWidget(LookPreview(ctx, item, w) if kind in ("banner", "frame") else Preview(ctx, item))
        if kind == "theme":
            ctx.start_preview(item)
        price = Label(tr("{a} → {b} coins", a=coins_text(int(d.get("was") or d.get("price") or 0)), b=coins_text(int(d["now"]))),
                      13, GOLD_TEXT, bold=True)
        lay.addWidget(price)
        buy = Button(tr("You already have it") if owned else tr("Sold out until tomorrow") if sold
                     else tr("Buy for {n} coins", n=coins_text(int(d["now"]))), "ghost" if owned or sold else "primary", 38)
        buy.setEnabled(not owned and not sold)
        lay.addWidget(Label(tr("One at this price per day."), 10, TEXT_DIM))
        buy.clicked.connect(self._buy)
        lay.addWidget(buy)

    def on_closed(self) -> None:
        self.ctx.stop_preview()

    def _close(self) -> None:
        self.ctx.stop_preview()
        self.ctx.window.unembed(self)

    def _buy(self) -> None:
        ctx, ec, d = self.ctx, self.ctx.econ, self.d
        if d["now"] > ec.coins:
            return ctx.toast(tr("Not enough coins: {n} more needed", n=coins_text(d["now"] - ec.coins)), "warn")
        pass

        def bought(ok: bool, data) -> None:
            if not ok:
                return ctx.toast(tr(str(data)), "warn")
            sfx.play("on")
            ctx.toast(tr("Bought: {what}", what=item_name(d["item"])))
            d["bought"] = True                               # 4.7: sold out for you until tomorrow
            ctx.deals_data = None
            self._close()
        ec.buy(d["item"], bought)


def build_deals(page, lay) -> None:
    ctx = page.ctx
    if server_wait(ctx, lay, page.W):
        return
    data = getattr(ctx, "deals_data", None)
    if data is None or time.monotonic() - data[0] > 60:
        def got(ok: bool, ans) -> None:
            if ok and isinstance(ans, dict):
                ctx.deals_data = (time.monotonic(), ans)
                if ctx.window.showing("themes") and int(getattr(ctx, "shop_tab", 0) or 0) == 7:
                    ctx.reload_page("themes")
        ctx.online.ask("rb_deals", {}, got)
    if data is None:
        return lay.addWidget(Label(tr("Loading…"), 12, TEXT_DIM))
    ans = data[1]
    since = int(time.monotonic() - data[0])
    from PyQt6.QtWidgets import QGridLayout
    w = (page.W - S(6)) // 2
    deals = ans.get("deals") or []
    # 5.15: three shelves: 2 deals of the hour, 4 of the day, 2 of the week (each with its own clock)
    for slot, title in (("hour", tr("This hour")), ("day", tr("Today")), ("week", tr("This week"))):
        row = [d for d in deals if d.get("slot", "day") == slot]
        if not row:
            continue
        left = max(0, int(row[0].get("ends_in") or ans.get("ends_in") or 0) - since)
        head = hbox(spacing=8)                           # 8.0: the shelf titles were squeezed to nothing
        head.addWidget(Label(title, 13, TEXT, bold=True).fit())
        head.addStretch(1)
        head.addWidget(Label(tr("new ones in {t}", t=(f"{left // 86400}d {left % 86400 // 3600}h" if left >= 86400 else clock_text(left))), 10.5, GOLD_TEXT, bold=True).fit())
        lay.addSpacing(S(4))
        lay.addLayout(head)
        holder = QWidget()
        grid = QGridLayout(holder)
        grid.setContentsMargins(0, 0, 0, 0)
        grid.setSpacing(S(6))
        for k, d in enumerate(row):
            grid.addWidget(DealCard(page, d, w), k // 2, k % 2)
        lay.addWidget(holder)


class GameModeWindow(FloatWindow):
    """4.6: the controller button: game mode and how Rubenium opens, in one small window."""

    def __init__(self, ctx) -> None:
        super().__init__(ctx, 360)
        from PyQt6.QtWidgets import QGridLayout
        pass
        pass
        cfg = ctx.cfg
        self.lay = lay = vbox(self, 8, (16, 14, 16, 16))
        top = hbox(spacing=6)
        top.addWidget(Label(tr("Game mode"), 15, bold=True), 1)
        close = IconButton("close", 26, tip=tr("Close"))
        close.clicked.connect(self.close)
        top.addWidget(close)
        lay.addLayout(top)
        # 9.1: no "turn it on now" button: game mode is only turned on with its key, so nobody locks themselves out
        lay.addWidget(Label(tr("While it is on, Rubenium stays exactly as it is (open or closed) but ignores the mouse "
                               "completely: nothing in it can be clicked or even hovered, and the pointer never shows up "
                               "over it, so nothing gets in the way of your game. A padlock on the ball shows it."),
                            10.5, TEXT_DIM, wrap_w=S(328)))
        lay.addWidget(Label(tr("GAME MODE KEY"), 10, TEXT_DIM, weight=QFont.Weight.Bold))
        grid = QGridLayout()
        grid.setSpacing(S(5))
        keys = [("off", "No key", 0)] + [k for k in GM_KEY_CHOICES if k[0] != cfg["hotkey"]]
        for i, (k, name, _vk) in enumerate(keys):
            b = Button(tr(name), "primary" if cfg["gm_key"] == k else "ghost", 28)
            b.clicked.connect(lambda _c=False, k=k: self._key(k))
            grid.addWidget(b, i // 3, i % 3)
        lay.addLayout(grid)
        lay.addWidget(Label(tr("Press it to turn game mode on or off. It can't be the show / hide key."), 10.5, TEXT_DIM,
                            wrap_w=S(328)))
        lay.addWidget(Label(tr("Hold it for 5 seconds: game mode turns off and Rubenium restarts, in case anything is stuck."),
                            10, "#FFD54A", wrap_w=S(328)))
        lay.addWidget(Label(tr("OPENING"), 10, TEXT_DIM, weight=QFont.Weight.Bold))
        row = hbox(spacing=6)
        row.addWidget(Label(tr("Hold to open"), 11.5, TEXT), 1)
        t = Toggle(cfg["hold_open"])
        t.toggled_by_user.connect(lambda v: (cfg.__setitem__("hold_open", bool(v)), self._again()))
        row.addWidget(t)
        lay.addLayout(row)
        if cfg["hold_open"]:
            hold = SliderRow(tr("Hold time"), 200, 1000, cfg["hold_ms"], 100, 400, lambda v: f"{v / 1000:.1f} s",
                             marks=list(range(200, 1001, 100)))
            hold.changed.connect(lambda v: cfg.__setitem__("hold_ms", int(v)))
            lay.addWidget(hold)
        lay.addWidget(Label(tr("Show / hide key (a tap opens or closes Rubenium)"), 11.5, TEXT))
        hk_keys = [k for k, _n, _v in KEY_CHOICES]
        hk = Segmented([tr("No key") if k == "off" else n.replace("Right ", "R ") for k, n, _v in KEY_CHOICES],
                       hk_keys.index(cfg["hotkey"]) if cfg["hotkey"] in hk_keys else 0)

        def set_hk(i: int) -> None:
            cfg["hotkey"] = hk_keys[i]
            ctx.tapkey.set_key(hk_keys[i])
            if cfg["gm_key"] == hk_keys[i]:                # never the same key for both
                self._key("off")
                return
            self._again()
        hk.changed.connect(set_hk)
        lay.addWidget(hk)
        lay.addWidget(Label(tr("Holding this key down for 3 seconds restarts Rubenium, in case you are stuck or run into a problem."),
                            10, "#FFD54A", wrap_w=S(328)))
        self.centre()

    def _key(self, k: str) -> None:
        sfx.play("pick")
        self.ctx.cfg["gm_key"] = k
        self.ctx.gmkey.set_key(k)
        if k == "off" and getattr(self.ctx, "game_lock", False):
            self.ctx.toggle_game_lock(False)
        self._again()

    def _again(self) -> None:
        ctx = self.ctx
        QTimer.singleShot(0, lambda: (self.close(), setattr(ctx, "_gm_win", GameModeWindow(ctx))))


def open_game_mode(ctx) -> None:
    ctx._gm_win = GameModeWindow(ctx)


