# ==================================================================================================
import math
import random
import time
import uuid

from PyQt6.QtCore import QPointF, QRectF, QTimer, Qt
from PyQt6.QtGui import (QBrush, QColor, QConicalGradient, QFont, QLinearGradient, QPainter, QPainterPath, QPen,
                         QPixmap, QRadialGradient)
from PyQt6.QtWidgets import QWidget

STEEL_A, STEEL_B = "#2B3138", "#14171B"
HAZARD = "#F5C518"
SWITCH_GREEN = "#3DFF7A"
TITANIUM = "#F4F7FA"
DOOR_OPEN_S = (0.55, 1.05, 2.45)            # warning lights, bolts slide, doors fully open
REEL_ENDS = (8.4, 9.2, 10.0)               # each wheel stops, seconds after the explosion
OG_REWARDS = (("keys", "25", "KEYS"), ("coins", "5K", "COINS"), ("coupon", "750", "XP COUPON"))   # 5.3


def prism(h: float, s: float = 0.55, v: float = 1.0, a: float = 1.0) -> QColor:
    c = QColor.fromHsvF(h % 1.0, max(0.0, min(1.0, s)), max(0.0, min(1.0, v)))
    c.setAlphaF(max(0.0, min(1.0, a)))
    return c


def ease_io(k: float) -> float:
    k = max(0.0, min(1.0, k))
    return 4 * k ** 3 if k < 0.5 else 1 - (-2 * k + 2) ** 3 / 2


def paint_door_half(p: QPainter, r: QRectF, left: bool, accent: QColor, glow: float = 0.0, lights: float = 0.0) -> None:
    """9.1: one half of the Rubenium doors: black lacquer panels with fine gold inlay, a light strip along the seam in
    the song's colour that wakes up from the bottom, and half of the gold R medallion."""
    gold, gold_hi = QColor("#E8C26A"), QColor("#FFF1C2")
    lit = mix(accent, QColor("#FFFFFF"), 0.35) if accent.saturationF() > 0.15 else gold
    p.save()
    p.setClipRect(r)
    g = QLinearGradient(r.topLeft(), r.bottomRight() if left else r.bottomLeft())
    g.setColorAt(0, QColor("#15171C"))
    g.setColorAt(0.55, QColor("#0B0C10"))
    g.setColorAt(1, QColor("#050608"))
    p.fillRect(r, g)
    sheen = QLinearGradient(r.topLeft(), r.topRight())          # a soft lacquer sheen across the panel
    sheen.setColorAt(0.0 if left else 1.0, QColor(255, 255, 255, 0))
    sheen.setColorAt(0.65 if left else 0.35, QColor(255, 255, 255, 14))
    sheen.setColorAt(1.0 if left else 0.0, QColor(255, 255, 255, 0))
    p.fillRect(r, sheen)
    inset = S(26)                                               # two framed panels with thin gold inlay
    inner = r.adjusted(inset if left else S(34), inset, -S(34) if left else -inset, -inset)
    for k, part in enumerate((QRectF(inner.left(), inner.top(), inner.width(), inner.height() * 0.46),
                              QRectF(inner.left(), inner.top() + inner.height() * 0.54, inner.width(), inner.height() * 0.46))):
        p.setPen(QPen(alpha(gold, 0.30 + 0.25 * glow), S(1.2)))
        p.setBrush(QColor(255, 255, 255, 5 + 4 * k))
        p.drawRoundedRect(part, S(10), S(10))
        p.setPen(QPen(QColor(0, 0, 0, 120), S(1)))
        p.drawRoundedRect(part.adjusted(S(5), S(5), -S(5), -S(5)), S(7), S(7))
    seam_x = r.right() if left else r.left()                     # the light strip on the inner edge
    strip = QRectF(seam_x - S(5) if left else seam_x, r.top(), S(5), r.height())
    p.fillRect(strip, QColor("#020203"))
    wake = min(1.0, glow * 1.4)                                  # it lights up from the bottom
    if wake > 0:
        lg = QLinearGradient(strip.bottomLeft(), strip.topLeft())
        lg.setColorAt(0, alpha(lit, 0.95))
        lg.setColorAt(max(0.01, wake), alpha(lit, 0.75))
        lg.setColorAt(min(1.0, wake + 0.02), alpha(lit, 0.0))
        p.fillRect(strip, lg)
        halo = QLinearGradient(QPointF(seam_x, 0), QPointF(seam_x + (-S(60) if left else S(60)), 0))
        halo.setColorAt(0, alpha(lit, 0.22 * wake))
        halo.setColorAt(1, alpha(lit, 0.0))
        p.fillRect(QRectF(seam_x - S(60) if left else seam_x, r.top(), S(60), r.height()), halo)
    # half of the gold R medallion, cut by the seam
    d = min(r.height() * 0.30, r.width() * 1.1)
    whole = QRectF(0, 0, d, d)
    whole.moveCenter(QPointF(seam_x, r.center().y()))
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor("#08090C"))
    p.drawEllipse(whole)
    rim = QLinearGradient(whole.topLeft(), whole.bottomRight())
    rim.setColorAt(0, gold_hi)
    rim.setColorAt(0.5, gold)
    rim.setColorAt(1, QColor("#8A6420"))
    p.setPen(QPen(QBrush(rim), S(3.2)))
    p.setBrush(Qt.BrushStyle.NoBrush)
    p.drawEllipse(whole.adjusted(S(2), S(2), -S(2), -S(2)))
    p.setPen(QPen(alpha(gold, 0.35), S(1)))
    p.drawEllipse(whole.adjusted(S(10), S(10), -S(10), -S(10)))
    f = font(max(10.0, d / max(0.1, ui.scale) * 0.5), QFont.Weight.Black)
    path = QPainterPath()
    from PyQt6.QtGui import QFontMetricsF
    fm = QFontMetricsF(f)
    path.addText(QPointF(whole.center().x() - fm.horizontalAdvance("R") / 2,
                         whole.center().y() + (fm.ascent() - fm.descent()) / 2), f, "R")
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QBrush(rim))
    p.drawPath(path)
    if glow > 0:
        p.setPen(QPen(alpha(lit, 0.6 * glow), S(2)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawEllipse(whole.adjusted(-S(3), -S(3), S(3), S(3)))
    if lights > 0:                                               # a slow pulse on the medallion while it unlocks
        pulse = 0.5 + 0.5 * math.sin(lights * 9)
        halo = QRadialGradient(whole.center(), d * 0.9)
        halo.setColorAt(0, alpha(gold, 0.18 * pulse))
        halo.setColorAt(1, alpha(gold, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(halo)
        p.drawEllipse(whole.center(), d * 0.9, d * 0.9)
    p.restore()


def paint_doors(p: QPainter, r: QRectF, k_open: float, accent: QColor, seam: float = 0.0, lights: float = 0.0) -> None:
    """Both halves; k_open 0 (shut) to 1 (gone into the sides)."""
    half = r.width() / 2
    shift = half * ease_io(k_open) * 1.04
    paint_door_half(p, QRectF(r.left() - shift, r.top(), half, r.height()), True, accent, seam, lights)
    paint_door_half(p, QRectF(r.center().x() + shift, r.top(), half, r.height()), False, accent, seam, lights)
    if seam > 0 and k_open < 0.98:                        # light pushing through the gap
        gap = max(S(2), shift * 2)
        g = QLinearGradient(r.center().x() - gap, 0, r.center().x() + gap, 0)
        g.setColorAt(0, alpha(accent, 0.0))
        g.setColorAt(0.5, alpha(mix(accent, QColor("#FFFFFF"), 0.6), 0.9 * seam * (1 - k_open)))
        g.setColorAt(1, alpha(accent, 0.0))
        p.fillRect(QRectF(r.center().x() - gap * 3, r.top(), gap * 6, r.height()), g)


def door_pixmap(size, accent: QColor) -> QPixmap:
    """The shut doors as a picture: what the online menu shows while it drops (nothing inside can be seen)."""
    dpr = 2.0
    pm = QPixmap(max(1, int(size.width() * dpr)), max(1, int(size.height() * dpr)))
    pm.setDevicePixelRatio(dpr)
    pm.fill(QColor("#08090B"))
    p = QPainter(pm)
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    paint_doors(p, QRectF(0, 0, size.width(), size.height()), 0.0, accent)
    p.end()
    return pm


GAME_NAMES.update({"wave": "Wave Rush", "mini": "Beat Tap", "park": "Parking", "memory": "Memory", "blocks": "Block Blast",
                   "sweep": "Minesweeper", "sweeper": "Minesweeper", "golf_solo": "Mini Golf", "quest": "a quest",
                   "keno": "Keno", "limbo": "Limbo", "jackpot": "Jackpot", "c4": "Connect 4", "reversi": "Reversi",
                   "ships": "Battleships", "arena": "Arena duel"})   # 5.9: adds to the list, never replaces it


def show_key_found(ctx, game: str = "") -> None:
    """5.0: a key found in a mini game (or from a quest) comes down big in the middle of the menu, never silently."""
    from PyQt6.QtCore import QPoint
    from PyQt6.QtGui import QGuiApplication
    try:
        w = ctx.window
        centre = w.mapToGlobal(QPoint(w.width() // 2, int(w.height() * 0.38)))
        screen = QGuiApplication.screenAt(centre) or QGuiApplication.primaryScreen()
        fx = FxOverlay(ctx, screen)
    except Exception:  # noqa: BLE001
        return ctx.toast(tr("You found a key!"), "ok")
    at = fx.local(centre)
    rnd = random.Random()
    sparks = [(rnd.uniform(0, math.tau), rnd.uniform(0.4, 1.0) * S(170), rnd.uniform(1.6, 3.6)) for _ in range(40)]
    where = tr(GAME_NAMES.get(game, "")) if game else ""
    sfx.play("key")
    QTimer.singleShot(420, lambda: sfx.tune("unlock"))

    def paint(p: QPainter, k: float, now: float) -> None:
        drop = 1 - (1 - min(1.0, k / 0.22)) ** 3                         # falls in, settles, fades away
        fade = 1.0 if k < 0.78 else max(0.0, 1 - (k - 0.78) / 0.22)
        c = QPointF(at.x(), at.y() - S(90) * (1 - drop))
        p.setOpacity(fade)
        halo = QRadialGradient(c, S(120))
        halo.setColorAt(0, QColor(255, 210, 122, 150))
        halo.setColorAt(1, QColor(255, 210, 122, 0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(halo)
        p.drawEllipse(c, S(120), S(120))
        for ang, dist, size in sparks:
            d = dist * min(1.0, k / 0.5)
            col = QColor("#FFE6A8")
            col.setAlphaF(max(0.0, 1 - k) * fade)
            p.setBrush(col)
            p.drawEllipse(QPointF(c.x() + math.cos(ang) * d, c.y() + math.sin(ang) * d), S(size), S(size))
        p.save()
        p.translate(c)
        p.rotate(math.sin(now * 5) * 8 * (1 - drop * 0.6))
        paint_key(p, QPointF(0, 0), S(96) * (0.6 + 0.4 * drop), QColor("#FFD27A"))
        p.restore()
        p.setPen(QColor(0, 0, 0, 170))
        p.setFont(font(26, QFont.Weight.Black, 2))
        box = QRectF(c.x() - S(240), c.y() + S(62), S(480), S(36))
        p.drawText(box.translated(0, S(2)), int(Qt.AlignmentFlag.AlignCenter), tr("KEY FOUND!"))
        p.setPen(QColor("#FFD27A"))
        p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), tr("KEY FOUND!"))
        p.setPen(QColor("#FFFFFF"))
        p.setFont(font(13, QFont.Weight.Bold))
        p.drawText(box.translated(0, S(34)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("+1 key · found in {game}", game=where) if where else tr("+1 key"))
        p.setOpacity(1.0)
    fx.add(2.8, paint)


class DoorStage(QWidget):
    """5.0: covers the online menu once it has dropped. 'doors': the garage doors open on the menu. 'og': 5.15, the
    remastered OG Prismatic Case. The doors open on a void where the case floats inside three crystal seals.
    Click each seal to break it and free one reward. Then hold the case down until it charges and bursts open.
    Nothing is given until Claim, so a crash or a closed app plays it again."""

    SEALS = 3
    CHARGE_S = 1.7                              # holding the case this long opens it

    def __init__(self, win, mode: str) -> None:
        super().__init__(win)
        self.win, self.ctx, self.mode = win, win.ctx, mode
        self.setAttribute(Qt.WidgetAttribute.WA_OpaquePaintEvent, False)
        self.setMouseTracking(True)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.t0 = time.monotonic()
        self.state = "doors"                   # doors, void, hold, nova, claim, done, out
        self.st_at = self.t0
        self.rnd = random.Random()
        self.req = uuid.uuid4().hex             # one id for every try: the server gives the case once
        self.sparks: list = []                  # [x, y, vx, vy, life, hue, colour]
        self.dust = [(self.rnd.random(), self.rnd.random(), self.rnd.uniform(0.4, 1.0)) for _ in range(46)]
        self.stars = [(self.rnd.random(), self.rnd.random(), self.rnd.uniform(0.3, 1.0), self.rnd.random()) for _ in range(140)]
        self.broken: dict = {}                  # seal -> when it broke
        self.charge = 0.0
        self.holding = False
        self.hover = -1
        self.error = ""
        self.claimed = None
        self._sfx_marks: set = set()
        self._next_tick = 0.0
        self.rings: list = []                   # shock waves: [born, colour hue]
        gift = getattr(self.ctx, "og_chest", None) or {}
        self.rewards = [("keys", str(int(gift.get("keys") or 25)), "KEYS"),
                        ("coins", coins_text(int(gift.get("coins") or 5000)), "COINS"),
                        ("coupon", str(int(gift.get("xp") or 750)), "XP COUPON")]
        self.claim_btn = Button(tr("Claim rewards"), "primary", 46, parent=self)
        self.claim_btn.setFixedWidth(S(240))
        self.claim_btn.clicked.connect(self._claim)
        self.claim_btn.hide()
        self._t = QTimer(self)
        self._t.setInterval(16)
        self._t.timeout.connect(self._tick)
        self._t.start()
        sfx.play("on")

    # -------------------------------------------------------------- what may happen
    @property
    def blocking(self) -> bool:
        """Leaving online mode waits while the doors open and while the case has not been claimed (unless the
        server could not be reached: then the player may leave and try again later)."""
        if self.mode == "doors":
            return self.state == "doors"
        return self.state != "out" and not self.error

    def keyPressEvent(self, e) -> None:                     # nothing skips the scene
        if self.state == "claim" and e.key() in (Qt.Key.Key_Return, Qt.Key.Key_Enter, Qt.Key.Key_Space) \
                and self.claim_btn.isVisible() and self.claim_btn.isEnabled():
            self._claim()
        e.accept()

    def _go(self, state: str) -> None:
        self.state, self.st_at = state, time.monotonic()

    def _since(self) -> float:
        return time.monotonic() - self.st_at

    # -------------------------------------------------------------- places (for clicks and paint)
    def case_rect(self) -> QRectF:
        w = min(self.width() * 0.18, self.height() * 0.25)
        c = QPointF(self.width() / 2, self.height() * 0.37 + math.sin(time.monotonic() * 1.3) * S(5))
        return QRectF(c.x() - w / 2, c.y() - w / 2, w, w)

    def seal_at(self, k: int, now: float) -> QPointF:
        """The seals orbit the case on a tilted ring (they slow down as fewer are left)."""
        c = self.case_rect().center()
        rad = self.case_rect().width() * 1.05
        speed = 0.35 + 0.12 * len(self.broken)
        ang = now * speed + k * math.tau / self.SEALS
        return QPointF(c.x() + math.cos(ang) * rad, c.y() + math.sin(ang) * rad * 0.42)

    def seal_depth(self, k: int, now: float) -> float:
        """-1 behind the case, +1 in front."""
        speed = 0.35 + 0.12 * len(self.broken)
        return math.sin(now * speed + k * math.tau / self.SEALS)

    def card_rect(self, k: int) -> QRectF:
        w = min(self.width() * 0.16, self.height() * 0.22)
        h = w * 1.2
        gap = S(22)
        x = self.width() / 2 - (3 * w + 2 * gap) / 2 + k * (w + gap)
        return QRectF(x, self.height() * 0.6, w, h)

    def _seal_hit(self, pos: QPointF) -> int:
        now = time.monotonic()
        rr = self.case_rect().width() * 0.2
        best, k_ = -1, 1e9
        for k in range(self.SEALS):
            if k in self.broken:
                continue
            d = math.hypot(pos.x() - self.seal_at(k, now).x(), pos.y() - self.seal_at(k, now).y())
            if d < rr * 1.6 and d < k_:
                best, k_ = k, d
        return best

    def mouseMoveEvent(self, e) -> None:
        pos = e.position()
        self.hover = self._seal_hit(pos) if self.state == "void" else -1
        hot = self.hover >= 0 or (self.state == "hold" and self.case_rect().adjusted(-S(30), -S(30), S(30), S(30)).contains(pos))
        self.setCursor(Qt.CursorShape.PointingHandCursor if hot else Qt.CursorShape.ArrowCursor)

    def mousePressEvent(self, e) -> None:
        pos = e.position()
        e.accept()
        if e.button() != Qt.MouseButton.LeftButton:
            return
        if self.state == "void":
            k = self._seal_hit(pos)
            if k < 0:
                return
            self.broken[k] = time.monotonic()
            at = self.seal_at(k, time.monotonic())
            self._burst(at, 70, prismatic=True, power=1.3)
            self.rings.append([time.monotonic(), k / 3, at])
            shake(self.win, 4.0, 220)
            sfx.play(("key", "coin", "chip")[k % 3])
            if len(self.broken) >= self.SEALS:
                QTimer.singleShot(900, lambda: (self._go("hold"), sfx.play("on")) if self.state == "void" else None)
        elif self.state == "hold" and self.case_rect().adjusted(-S(30), -S(30), S(30), S(30)).contains(pos):
            self.holding = True

    def mouseReleaseEvent(self, e) -> None:
        self.holding = False
        e.accept()

    # -------------------------------------------------------------- the server
    def _claim(self) -> None:
        if self.state != "claim" or not self.claim_btn.isEnabled():
            return
        self.claim_btn.setEnabled(False)
        self.claim_btn.set_text(tr("Claiming…"))
        self.error = ""

        def back(ok: bool, data) -> None:
            try:
                if not self.isVisible() and self.state == "out":
                    return
            except RuntimeError:
                return
            if ok and isinstance(data, dict) and data.get("claimed"):
                self.claimed = data
                self.ctx.og_chest = {"due": False, "claimed": True}
                self.claim_btn.hide()
                self._go("done")
                sfx.tune("legend")
                for k in range(3):
                    self._burst(self.card_rect(k).center(), 46, prismatic=True, power=1.2)
                try:
                    self.ctx.econ.refresh()
                except Exception:  # noqa: BLE001
                    pass
            else:
                self.error = str(data or tr("Something went wrong: try again"))
                self.claim_btn.setEnabled(True)
                self.claim_btn.set_text(tr("Try again"))
        self.ctx.econ.call("rb_og_chest_claim", {"req": self.req}, back)

    # -------------------------------------------------------------- particles
    def _burst(self, at: QPointF, n: int, prismatic: bool = False, power: float = 1.0, colour: QColor = None) -> None:
        for _ in range(n):
            ang = self.rnd.uniform(0, math.tau)
            sp = self.rnd.uniform(1.5, 7.5) * power * ui.scale
            self.sparks.append([at.x(), at.y(), math.cos(ang) * sp, math.sin(ang) * sp - 1.5 * ui.scale,
                                self.rnd.uniform(0.6, 1.4), self.rnd.random() if prismatic else -1,
                                colour or QColor("#FFD27A")])

    def _tick(self) -> None:
        now = time.monotonic()
        t = self._since()
        keep = []
        for s in self.sparks:
            s[0] += s[2]
            s[1] += s[3]
            s[3] += (0.05 if self.mode == "og" and self.state != "doors" else 0.22) * ui.scale     # floaty in the void
            s[2] *= 0.985
            s[4] -= 0.014
            if s[4] > 0 and s[1] < self.height() + S(20):
                keep.append(s)
        self.sparks = keep[-900:]
        self.rings = [x for x in self.rings if now - x[0] < 1.4]
        if self.state == "doors":
            if t > DOOR_OPEN_S[0] and "bolt" not in self._sfx_marks:
                self._sfx_marks.add("bolt")
                sfx.play("cup")
                shake(self.win, 3.0, 240)
            if t > DOOR_OPEN_S[1] and "open" not in self._sfx_marks:
                self._sfx_marks.add("open")
                sfx.play("spin")
                for y in range(6):
                    self._burst(QPointF(self.width() / 2, self.height() * (0.1 + y * 0.16)), 8)
            if t >= DOOR_OPEN_S[2]:
                self._go("void" if self.mode == "og" else "out")
        elif self.state in ("void", "hold"):
            if self.rnd.random() < 0.3:                          # the case breathes light
                c = self.case_rect()
                ang = self.rnd.uniform(0, math.tau)
                self.sparks.append([c.center().x() + math.cos(ang) * c.width() * 0.4,
                                    c.center().y() + math.sin(ang) * c.width() * 0.4,
                                    math.cos(ang) * 0.6 * ui.scale, math.sin(ang) * 0.6 * ui.scale - 0.3 * ui.scale,
                                    self.rnd.uniform(0.5, 1.0), self.rnd.random(), None])
            if self.state == "hold":
                rate = 1 / self.CHARGE_S
                self.charge = min(1.0, self.charge + rate * 0.016) if self.holding else max(0.0, self.charge - 0.9 * 0.016)
                if self.holding and now >= self._next_tick:      # ticks that speed up as it charges
                    self._next_tick = now + 0.16 - 0.12 * self.charge
                    sfx.play("tick")
                    c = self.case_rect()
                    self._burst(c.center(), int(2 + 10 * self.charge), prismatic=True, power=0.4 + self.charge)
                if self.charge >= 1.0:
                    self.holding = False
                    self._go("nova")
                    sfx.tune("epic")
                    shake(self.win, 9.0, 600)
                    c = self.case_rect().center()
                    self._burst(c, 260, prismatic=True, power=2.6)
                    for i in range(4):
                        self.rings.append([now + i * 0.12, i / 4, c])
        elif self.state == "nova":
            if t > 2.4:
                self._go("claim")
                self.claim_btn.show()
                self.claim_btn.raise_()
                self.setFocus()
                for k in range(3):
                    QTimer.singleShot(120 * k, lambda k_=k: self._burst(self.card_rect(k_).center(), 30, prismatic=True))
        elif self.state == "done":
            if t > 2.6:
                self._go("out")
        elif self.state == "out":
            if t > 0.6:
                self._t.stop()
                self.hide()
                try:
                    if getattr(self.win, "stage", None) is self:
                        self.win.stage = None
                except RuntimeError:
                    pass
                self.deleteLater()
                return
        self.claim_btn.move(int(self.width() / 2 - self.claim_btn.width() / 2), int(self.height() * 0.88))
        self.update()

    # -------------------------------------------------------------- paint
    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect())
        now = time.monotonic()
        t = self._since()
        st = self.state
        if st == "out":
            p.setOpacity(max(0.0, 1 - t / 0.6))
            if self.mode == "og":
                self._paint_vault(p, r, now, 99.0)
            else:
                paint_doors(p, r, 1.0, ui.accent)
            return
        if self.mode == "og":
            self._paint_vault(p, r, now, t if st != "doors" else 0.0)
        if st == "doors":
            if self.mode != "og":
                p.fillRect(r, QColor(0, 0, 0, int(255 * max(0.0, 1 - max(0.0, t - DOOR_OPEN_S[1]) / 1.0))))
            k = max(0.0, (t - DOOR_OPEN_S[1]) / (DOOR_OPEN_S[2] - DOOR_OPEN_S[1]))
            seam = min(1.0, t / DOOR_OPEN_S[1])
            paint_doors(p, r, k, ui.accent, seam, t if t < DOOR_OPEN_S[1] else 0.0)
            if k > 0:                                          # dust rolls out as they part
                p.setPen(Qt.PenStyle.NoPen)
                for dx, dy, s_ in self.dust:
                    a = (1 - k) * 0.5 * s_
                    p.setBrush(QColor(255, 226, 160, int(255 * a)))     # 9.1: gold dust
                    p.drawEllipse(QPointF(r.center().x() + (dx - 0.5) * r.width() * k, r.top() + dy * r.height()),
                                  S(1.6) * s_, S(1.6) * s_)
        self._paint_sparks(p, now)
        if self.mode == "og" and st == "nova" and t < 0.5:          # the white of the burst
            p.fillRect(r, alpha("#FFFFFF", (1 - t / 0.5) * 0.95))

    def _paint_sparks(self, p: QPainter, now: float) -> None:
        p.setPen(Qt.PenStyle.NoPen)
        for x, y, _vx, _vy, life, hue, col in self.sparks:
            a = max(0.0, min(1.0, life))
            if hue >= 0:
                c = prism(hue + now * 0.3, 0.6, 1.0, a)
            else:
                c = QColor(col or "#FFD27A")
                c.setAlphaF(a)
            p.setBrush(c)
            rr = S(2.2) * (0.5 + a)
            p.drawEllipse(QPointF(x, y), rr, rr)

    # the void, the case, the seals, the cards
    def _paint_vault(self, p: QPainter, r: QRectF, now: float, t: float) -> None:
        st = self.state
        bg = QRadialGradient(r.center(), max(r.width(), r.height()) * 0.75)
        bg.setColorAt(0, QColor("#120E22"))
        bg.setColorAt(0.6, QColor("#07060D"))
        bg.setColorAt(1, QColor("#020203"))
        p.fillRect(r, bg)
        p.setPen(Qt.PenStyle.NoPen)
        for x, y, z, ph in self.stars:                         # drifting stars, closer ones faster
            sx = (x + now * 0.004 * z) % 1.0 * r.width()
            tw = 0.35 + 0.65 * abs(math.sin(now * (0.6 + z) + ph * 9))
            p.setBrush(QColor(255, 255, 255, int(170 * z * tw)))
            p.drawEllipse(QPointF(sx, y * r.height()), S(1.3) * z, S(1.3) * z)
        opened = st in ("nova", "claim", "done", "out")
        c = self.case_rect()
        cc = c.center()
        # slow prismatic rays: stronger once the case is open
        rays = 18
        for i in range(rays):
            ang = i * math.tau / rays + now * (0.1 if not opened else 0.22)
            path = QPainterPath(cc)
            wd = 0.04 if not opened else 0.07
            path.lineTo(cc + QPointF(math.cos(ang - wd), math.sin(ang - wd)) * r.width())
            path.lineTo(cc + QPointF(math.cos(ang + wd), math.sin(ang + wd)) * r.width())
            path.closeSubpath()
            p.setBrush(prism(i / rays + now * 0.05, 0.6, 1.0, (0.05 if not opened else 0.11) + 0.08 * self.charge))
            p.drawPath(path)
        title = tr("PRISMATIC CASE")
        self._prism_text(p, QRectF(0, r.height() * 0.05, r.width(), S(46)), title, 30, now)
        hint = {"void": tr("Break the 3 seals: click them as they fly around the case"),
                "hold": tr("Now hold the case down until it opens"),
                "claim": tr("Yours, OG. Thank you for being here from the start"),
                }.get(st, "")
        if hint:
            p.setPen(QColor(255, 255, 255, 200))
            p.setFont(font(13, QFont.Weight.DemiBold))
            p.drawText(QRectF(0, r.height() * 0.05 + S(46), r.width(), S(24)), int(Qt.AlignmentFlag.AlignCenter), hint)
        # seals behind the case first, then the case, then seals in front
        front = []
        for k in range(self.SEALS):
            if k in self.broken:
                continue
            (front if self.seal_depth(k, now) > 0 else []).append(k)
            if self.seal_depth(k, now) <= 0:
                self._paint_seal(p, k, now)
        self._paint_case(p, c, now, opened, t)
        for k in front:
            self._paint_seal(p, k, now)
        for born, hue, at in self.rings:                       # shock waves
            age = now - born
            if age < 0:
                continue
            k = age / 1.4
            rad = S(30) + k * max(r.width(), r.height()) * 0.7
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(prism(hue + now * 0.3, 0.55, 1.0, (1 - k) * 0.8), S(6) * (1 - k) + 1))
            p.drawEllipse(at, rad, rad * 0.9)
        if st == "hold":                                       # the charge ring around the case
            ring = c.adjusted(-S(26), -S(26), S(26), S(26))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(255, 255, 255, 40), S(6)))
            p.drawEllipse(ring)
            if self.charge > 0:
                g = QConicalGradient(ring.center(), 90)
                for i in range(7):
                    g.setColorAt(i / 6, prism(i / 6 + now * 0.4, 0.6, 1.0))
                p.setPen(QPen(QBrush(g), S(6), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
                p.drawArc(ring, 90 * 16, -int(360 * 16 * self.charge))
            p.setPen(QColor(255, 255, 255, int(160 + 90 * math.sin(now * 4))))
            p.setFont(font(12, QFont.Weight.Bold, 2))
            p.drawText(QRectF(0, ring.bottom() + S(8), r.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("HOLD") if not self.holding else f"{int(self.charge * 100)}%")
        # 6.0: the rewards stay hidden until the case bursts open. Then three cards rise out of it face down and flip
        # over one by one. Before that, only a count of the seals broken.
        if st == "void" and self.broken:
            p.setPen(QColor(255, 255, 255, 170))
            p.setFont(font(12, QFont.Weight.Bold, 1.5))
            p.drawText(QRectF(0, r.height() * 0.66, r.width(), S(24)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("{n} / 3 seals broken", n=len(self.broken)))
        if opened:
            since = t if st == "nova" else 9.0                  # seconds since the burst (claim / done: long done)
            for k in range(3):
                rise = max(0.0, min(1.0, (since - 0.35 - 0.12 * k) / 0.6))
                if rise <= 0:
                    continue
                cr = self.card_rect(k)
                ease = 1 - (1 - rise) ** 3
                centre = QPointF(cc.x() + (cr.center().x() - cc.x()) * ease, cc.y() + (cr.center().y() - cc.y()) * ease)
                if st == "done":                               # claimed: they fly up into your wallet
                    up = min(1.0, t / 1.2) ** 2
                    centre = centre + QPointF(0, -up * r.height() * 0.8)
                    p.setOpacity(max(0.0, 1 - up))
                sc = 0.35 + 0.65 * ease
                card = QRectF(centre.x() - cr.width() * sc / 2, centre.y() - cr.height() * sc / 2, cr.width() * sc, cr.height() * sc)
                flip = max(0.0, min(1.0, (since - 1.0 - 0.35 * k) / 0.45))        # 0 face down, 1 face up
                if 0 < flip < 1 and getattr(self, "_flipped", 0) <= k and flip > 0.5:
                    self._flipped = k + 1
                    sfx.play("card")
                p.save()
                p.translate(card.center())
                p.scale(max(0.04, abs(math.cos(flip * math.pi))), 1.0)          # the card turns over
                p.translate(-card.center())
                if flip < 0.5:
                    self._paint_card_back(p, card, k, now)
                else:
                    self._paint_card(p, card, k, now, True)
                p.restore()
                p.setOpacity(1.0)
        if st == "claim" and self.error:
            p.setPen(QColor(DANGER))
            p.setFont(font(13, QFont.Weight.DemiBold))
            p.drawText(QRectF(0, r.height() * 0.84, r.width(), S(24)), int(Qt.AlignmentFlag.AlignCenter), self.error)
        if st == "done":
            p.setOpacity(min(1.0, t / 0.5))
            self._prism_text(p, QRectF(0, r.height() * 0.84, r.width(), S(40)), tr("Rewards claimed!"), 24, now)
            p.setOpacity(1.0)

    def _paint_seal(self, p: QPainter, k: int, now: float) -> None:
        at = self.seal_at(k, now)
        depth = self.seal_depth(k, now)
        s = self.case_rect().width() * 0.13 * (1 + 0.25 * depth) * (1.18 if self.hover == k else 1.0)
        glow = QRadialGradient(at, s * 2.4)
        glow.setColorAt(0, prism(k / 3 + now * 0.2, 0.6, 1.0, 0.55))
        glow.setColorAt(1, prism(0, 0, 1, 0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glow)
        p.drawEllipse(at, s * 2.4, s * 2.4)
        gem = QPainterPath()                                     # a spinning crystal
        spin = now * 2.2 + k
        for i in range(6):
            ang = spin + i * math.tau / 6
            rr = s * (1.0 if i % 2 == 0 else 0.62)
            pt = at + QPointF(math.cos(ang) * rr, math.sin(ang) * rr * 1.25)
            gem.moveTo(pt) if i == 0 else gem.lineTo(pt)
        gem.closeSubpath()
        g = QLinearGradient(at - QPointF(s, s), at + QPointF(s, s))
        g.setColorAt(0, prism(k / 3 + now * 0.3, 0.35, 1.0))
        g.setColorAt(1, prism(k / 3 + 0.3 + now * 0.3, 0.75, 0.9))
        p.setBrush(g)
        p.setPen(QPen(QColor(255, 255, 255, 200), max(1.0, S(1.4))))
        p.drawPath(gem)

    def _paint_case(self, p: QPainter, c: QRectF, now: float, opened: bool, t: float) -> None:
        """A crystal case: a glowing core, faceted walls; the lid lifts and the walls part when it opens."""
        cc = c.center()
        w = c.width()
        aura = QRadialGradient(cc, w * (1.2 + 0.5 * self.charge + (0.6 if opened else 0)))
        aura.setColorAt(0, prism(now * 0.2, 0.45, 1.0, 0.6))
        aura.setColorAt(0.5, prism(now * 0.2 + 0.33, 0.6, 1.0, 0.2))
        aura.setColorAt(1, prism(0, 0, 1, 0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(aura)
        p.drawEllipse(cc, w * 1.6, w * 1.6)
        p.save()
        if self.state == "hold" and self.charge > 0:
            p.translate(math.sin(now * 47) * S(3) * self.charge, math.cos(now * 39) * S(2) * self.charge)
        part = min(1.0, t / 0.8) if opened and self.state == "nova" else (1.0 if opened else 0.0)
        part = 1 - (1 - part) ** 3
        seals_left = self.SEALS - len(self.broken)
        body = QRectF(cc.x() - w * 0.42, cc.y() - w * 0.18, w * 0.84, w * 0.6)
        lid = QRectF(cc.x() - w * 0.46, cc.y() - w * 0.38, w * 0.92, w * 0.24)
        lid.translate(0, -part * w * 0.3)
        dark = QColor("#14121E")
        for i, piece in enumerate((body, lid)):
            if opened and i == 0:                                # the walls part a little
                left = QRectF(piece.left() - part * w * 0.12, piece.top(), piece.width() / 2, piece.height())
                right = QRectF(piece.center().x() + part * w * 0.12, piece.top(), piece.width() / 2, piece.height())
                pieces = (left, right)
            else:
                pieces = (piece,)
            for pc in pieces:
                g = QConicalGradient(pc.center(), (now * 70 + i * 90) % 360)
                for j in range(7):
                    g.setColorAt(j / 6, mix(dark, prism(j / 6, 0.5, 1.0), 0.55 + 0.45 * (1 - seals_left / self.SEALS)))
                p.setBrush(g)
                p.setPen(QPen(QColor(255, 255, 255, 190), S(2)))
                p.drawRoundedRect(pc, S(8), S(8))
                p.setPen(QPen(QColor(255, 255, 255, 70), S(1.2)))     # facets
                p.drawLine(QPointF(pc.left() + pc.width() * 0.3, pc.top()), QPointF(pc.left() + pc.width() * 0.15, pc.bottom()))
                p.drawLine(QPointF(pc.left() + pc.width() * 0.7, pc.top()), QPointF(pc.left() + pc.width() * 0.85, pc.bottom()))
        core = QRadialGradient(QPointF(cc.x(), body.center().y()), w * 0.3)       # the light inside
        core.setColorAt(0, QColor(255, 255, 255, int(120 + 135 * max(self.charge, part))))
        core.setColorAt(1, prism(now * 0.3, 0.6, 1.0, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(core)
        p.drawEllipse(QPointF(cc.x(), body.center().y()), w * (0.22 + 0.4 * part), w * (0.22 + 0.4 * part))
        if not opened:                                            # one small lock per seal left
            for i in range(seals_left):
                x = cc.x() + (i - (seals_left - 1) / 2) * w * 0.16
                lk = QRectF(x - w * 0.05, body.top() - w * 0.02, w * 0.1, w * 0.12)
                p.setBrush(QColor(TITANIUM))
                p.drawRoundedRect(lk, S(3), S(3))
        p.restore()

    def _paint_card_back(self, p: QPainter, cr: QRectF, k: int, now: float) -> None:
        """6.0: a card face down: prismatic stripes and a question mark."""
        path = QPainterPath()
        path.addRoundedRect(cr, S(14), S(14))
        g = QLinearGradient(cr.topLeft(), cr.bottomRight())
        for i in range(5):
            g.setColorAt(i / 4, prism(i / 4 + now * 0.2 + k * 0.2, 0.55, 0.55))
        p.setBrush(g)
        p.setPen(QPen(QColor(255, 255, 255, 220), S(2.5)))
        p.drawPath(path)
        p.setPen(QColor(255, 255, 255, 235))
        p.setFont(font(28, QFont.Weight.Black))
        p.drawText(cr, int(Qt.AlignmentFlag.AlignCenter), "?")

    def _paint_card(self, p: QPainter, cr: QRectF, k: int, now: float, big: bool) -> None:
        kind, value, word = self.rewards[k]
        path = QPainterPath()
        path.addRoundedRect(cr, S(14), S(14))
        g = QLinearGradient(cr.topLeft(), cr.bottomRight())
        g.setColorAt(0, QColor(24, 20, 40, 240))
        g.setColorAt(1, QColor(10, 9, 18, 240))
        p.setBrush(g)
        p.setPen(QPen(prism(k / 3 + now * 0.25, 0.6, 1.0, 0.95), S(2.5)))
        p.drawPath(path)
        shine = (now * 0.5 + k * 0.33) % 1.6 - 0.3                 # a light sweep across the card
        p.save()
        p.setClipPath(path)
        sw = QLinearGradient(cr.left() + cr.width() * shine - cr.width() * 0.2, 0, cr.left() + cr.width() * shine + cr.width() * 0.2, 0)
        sw.setColorAt(0, QColor(255, 255, 255, 0))
        sw.setColorAt(0.5, QColor(255, 255, 255, 34))
        sw.setColorAt(1, QColor(255, 255, 255, 0))
        p.fillRect(cr, sw)
        p.restore()
        self._paint_tile(p, kind, QRectF(cr.left(), cr.top() + cr.height() * 0.06, cr.width(), cr.height() * 0.52), now, big=big)
        # 6.0: the amount in big plain white, the word under it: always readable, whatever the card size
        p.setPen(QColor("#FFFFFF"))
        p.setFont(font(17, QFont.Weight.Black))
        p.drawText(QRectF(cr.left(), cr.top() + cr.height() * 0.58, cr.width(), cr.height() * 0.17),
                   int(Qt.AlignmentFlag.AlignCenter), value)
        p.setPen(QColor(255, 255, 255, 200))
        p.setFont(font(10.5, QFont.Weight.Bold, 1.2))
        p.drawText(QRectF(cr.left(), cr.top() + cr.height() * 0.75, cr.width(), cr.height() * 0.1),
                   int(Qt.AlignmentFlag.AlignCenter), tr(word))
        self._prism_text(p, QRectF(cr.left(), cr.top() + cr.height() * 0.85, cr.width(), cr.height() * 0.12),
                         tr("EXOTIC"), 9.5, now)

    def _prism_text(self, p: QPainter, r: QRectF, text: str, size: float, now: float) -> None:
        f = font(size, QFont.Weight.Black, 2)
        g = QLinearGradient(r.left() + r.width() * 0.3, 0, r.right() - r.width() * 0.3, 0)
        for i in range(7):
            g.setColorAt(i / 6, prism(i / 6 + now * 0.25, 0.55, 1.0))
        p.setFont(f)
        p.setPen(QColor(0, 0, 0, 160))
        p.drawText(r.translated(0, S(2)), int(Qt.AlignmentFlag.AlignCenter), text)
        p.setPen(QPen(g, 1))
        p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), text)

    def _paint_tile(self, p: QPainter, kind: str, r: QRectF, now: float, big: bool = False) -> None:
        c = r.center()
        s = min(r.width(), r.height())
        if kind == "keys":
            paint_key(p, c, s * 0.55, QColor("#FFD27A"))
        elif kind == "coins":
            for i, (dx, dy) in enumerate(((-0.14, 0.08), (0.12, 0.1), (0.0, -0.08))):
                paint_coin(p, QPointF(c.x() + s * dx, c.y() + s * dy), s * 0.2)
        elif kind == "coupon":
            w = s * 0.86
            paint_coupon(p, QRectF(c.x() - w / 2, c.y() - w * 0.22, w, w * 0.44), "coupon:ogchest", now, label=False)
        else:
            gem = QPainterPath()
            gem.moveTo(c.x(), c.y() - s * 0.26)
            gem.lineTo(c.x() + s * 0.22, c.y())
            gem.lineTo(c.x(), c.y() + s * 0.26)
            gem.lineTo(c.x() - s * 0.22, c.y())
            gem.closeSubpath()
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(prism(now * 0.3 + r.top() * 0.002, 0.5, 1.0, 0.85))
            p.drawPath(gem)

# ==================================================================================================
# SECTION: jackpot (5.2)
# ==================================================================================================
import math
import random
import time

from PyQt6.QtCore import QPointF, QRectF, QTimer, Qt, pyqtSignal
from PyQt6.QtGui import QColor, QFont, QPainter, QPainterPath, QPen, QRadialGradient
from PyQt6.QtWidgets import QWidget

JP_COLOURS = ["#FF4D6D", "#3DDC84", "#4FC3FF", "#FFC94D", "#B36BFF", "#FF8A3D"]   # six that never look alike
JP_EVERY, JP_OPEN, JP_SPIN = 900, 120, 10.0


def jp_colour(i) -> QColor:
    return QColor(JP_COLOURS[int(i or 0) % len(JP_COLOURS)])


def jp_now(ctx=None) -> float:
    """5.3: the server's clock (a PC clock can be minutes off: the jackpot looked open when it was shut)."""
    return time.time() + float(getattr(ctx, "jp_offset", 0.0) or 0.0)


def jp_phase(ctx=None):
    """('open', seconds left) while a jackpot takes players, ('running', 0) while it spins, ('closed', seconds until the
    next one opens). 5.3: from the server's own answer when there is one, on the server's clock."""
    now = jp_now(ctx)
    d = getattr(ctx, "jackpot_data", None) if ctx is not None else None
    if isinstance(d, dict) and d.get("now") and now - float(getattr(ctx, "jp_got_at", 0) or 0) < 30:
        st = d.get("state")
        if st == "open" and d.get("waiting"):             # 6.2.3: empty, no countdown until a player joins
            return "waiting", 0.0
        if st == "open" and d.get("lock_at"):
            left = float(d["lock_at"]) - now
            if left > 0:
                return "open", left
            return "running", 0.0
        if st in ("locked", "picking"):
            return "running", 0.0
        nxt = float(d.get("next_at") or 0) - now
        return "closed", max(0.0, nxt)
    slot = math.floor(now / JP_EVERY) * JP_EVERY
    t = now - slot
    if t < JP_OPEN:
        return "open", JP_OPEN - t
    if t < JP_OPEN + 25:
        return "running", 0.0
    return "closed", slot + JP_EVERY - now


def jp_words(s: float) -> str:
    """6.0: a time in words for notices ('about 2 minutes'), not a frozen clock like 1:52."""
    s = max(0, int(math.ceil(s)))
    if s >= 90:
        return tr("{n} minutes", n=int(round(s / 60)))
    if s >= 45:
        return tr("1 minute")
    return tr("{n} seconds", n=max(5, int(round(s / 5)) * 5))


def jp_clock(s: float) -> str:
    s = max(0, int(math.ceil(s)))
    if s >= 3600:                                        # 8.0: 3:43:17, not 223:17
        return f"{s // 3600}:{s % 3600 // 60:02d}:{s % 60:02d}"
    return f"{s // 60}:{s % 60:02d}"


class JackpotCard(QWidget):
    """5.2: the top of the Games lobby. Gold and glowing while a jackpot is open; greyed with the time to the next."""

    def __init__(self, page) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedHeight(S(74))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._t = QTimer(self)
        self._t.setInterval(250)
        self._t.timeout.connect(self.update)

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def mouseReleaseEvent(self, e) -> None:
        if not self.rect().contains(e.position().toPoint()):
            return
        phase, left = jp_phase(self.ctx)
        if phase == "closed" and not getattr(self.ctx, "jackpot_in", False):
            sfx.play("off")
            return self.ctx.toast(tr("The next jackpot opens in about {t}", t=jp_words(left)), "warn")
        sfx.play("pick")
        self.page.open_sub("jackpot")

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        now = time.monotonic()
        phase, left = jp_phase(self.ctx)
        live = phase != "closed" or getattr(self.ctx, "jackpot_in", False)
        gold = QColor("#FFC94D")
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        if live:
            g.setColorAt(0, QColor("#3A2A06"))
            g.setColorAt(1, QColor("#120C02"))
        else:
            g.setColorAt(0, QColor("#1A1C1F"))
            g.setColorAt(1, QColor("#0E0F11"))
        pulse = 0.5 + 0.5 * math.sin(now * 3)
        p.setPen(QPen(alpha(gold, 0.55 + 0.35 * pulse) if live else alpha("#FFFFFF", 0.12), S(1.6)))
        p.setBrush(g)
        p.drawRoundedRect(r, S(14), S(14))
        c = QPointF(r.left() + S(38), r.center().y())
        if live:                                           # a little wheel of colours turning
            halo = QRadialGradient(c, S(44))
            halo.setColorAt(0, alpha(gold, 0.35 + 0.2 * pulse))
            halo.setColorAt(1, alpha(gold, 0.0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(halo)
            p.drawEllipse(c, S(44), S(44))
        rad = S(22)
        for i in range(6):
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(jp_colour(i) if live else alpha("#FFFFFF", 0.10 + 0.04 * (i % 2)))
            path = QPainterPath(c)
            path.arcTo(QRectF(c.x() - rad, c.y() - rad, rad * 2, rad * 2), (now * 40 if live else 0) + i * 60, 60)
            path.closeSubpath()
            p.drawPath(path)
        p.setBrush(QColor("#0B0E10"))
        p.drawEllipse(c, rad * 0.45, rad * 0.45)
        p.setPen(gold if live else QColor(TEXT_FAINT))
        p.setFont(font(18, QFont.Weight.Black, 3))
        p.drawText(QRectF(r.left() + S(74), r.top() + S(10), r.width() - S(84), S(28)), int(Qt.AlignmentFlag.AlignVCenter),
                   "JACKPOT")
        p.setFont(font(11, QFont.Weight.Bold))
        if phase == "waiting":
            p.setPen(QColor("#FFFFFF"))
            text = tr("OPEN · waiting for a player")
        elif phase == "open":
            p.setPen(QColor("#FFFFFF"))
            text = tr("OPEN · join in the next {t}", t=jp_clock(left))
        elif phase == "running":
            p.setPen(QColor("#FFFFFF"))
            text = tr("The wheel is spinning: watch it")
        else:
            p.setPen(QColor(TEXT_DIM))
            text = tr("Next jackpot in {t}", t=jp_clock(left))
        p.drawText(QRectF(r.left() + S(74), r.top() + S(38), r.width() - S(84), S(22)), int(Qt.AlignmentFlag.AlignVCenter), text)



class LiveSlot(QWidget):
    """9.2: Jackpot and Horse Racing take turns on the server's 20 minute clock, so only one shows at a time: the
    game that is on, or between games a locked card with the next one, its countdown, a flash as it nears and the
    padlock dropping when it opens."""

    def __init__(self, page) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedHeight(S(74))
        lay = vbox(self, 0)
        self.jp, self.hr, self.lk = JackpotCard(page), HorseCard(page), LockedEvent(self)
        for w in (self.jp, self.hr, self.lk):
            lay.addWidget(w)
        self._show = None
        self._t = QTimer(self)
        self._t.setInterval(400)
        self._t.timeout.connect(self._pick)
        self._pick()

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def next_event(self) -> tuple:
        """(kind name, seconds until it opens) of the next game, from the two servers' answers."""
        jph, jl = jp_phase(self.ctx)
        rph, rl = race_phase(self.ctx)
        opts = []
        if jph == "closed":
            opts.append(("Jackpot", jl))
        if rph == "closed":
            opts.append(("Horse Racing", rl))
        if not opts:
            return ("Jackpot", 0.0)
        return min(opts, key=lambda o: o[1])

    def _pick(self) -> None:
        ctx = self.ctx
        jph, _ = jp_phase(ctx)
        rph, _ = race_phase(ctx)
        if jph in ("open", "running", "waiting") or getattr(ctx, "jackpot_in", False):
            want = "jp"
        elif rph in ("open", "running", "done"):
            want = "hr"
        else:
            want = "lk"
        if want != self._show:
            if self._show == "lk" and want != "lk":
                sfx.play("on")                              # the padlock drops: the next game opens
            self._show = want
            self.jp.setVisible(want == "jp")
            self.hr.setVisible(want == "hr")
            self.lk.setVisible(want == "lk")


class LockedEvent(QWidget):
    """9.2: between two live games: which one is next, a padlock and the time left. It flashes in the last 15 s."""

    def __init__(self, slot) -> None:
        super().__init__()
        self.slot = slot
        self.setFixedHeight(S(74))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._t = QTimer(self)
        self._t.setInterval(50)
        self._t.timeout.connect(self.update)

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def mouseReleaseEvent(self, e) -> None:
        if self.rect().contains(e.position().toPoint()):
            name, left = self.slot.next_event()
            sfx.play("off")
            self.slot.ctx.toast(tr("{game} opens in about {t}", game=tr(name), t=jp_words(left)), "warn")

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        name, left = self.slot.next_event()
        now = time.monotonic()
        col = QColor("#FFC94D") if name == "Jackpot" else QColor("#35E0A1")
        near = left <= 15
        flash = (0.5 + 0.5 * math.sin(now * 9)) if near else 0.0
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        g.setColorAt(0, mix(QColor("#1A1C1F"), col, 0.10 + 0.18 * flash))
        g.setColorAt(1, QColor("#0E0F11"))
        p.setPen(QPen(alpha(col, 0.25 + 0.6 * flash) if near else alpha("#FFFFFF", 0.12), S(1.6)))
        p.setBrush(g)
        p.drawRoundedRect(r, S(14), S(14))
        c = QPointF(r.left() + S(38), r.center().y())
        lift = max(0.0, 1.0 - left / 3.0) * S(6)          # the shackle lifts in the last 3 s
        p.save()
        p.translate(c.x(), c.y() - lift * 0.3)
        p.scale(S(30) / 20, S(30) / 20)
        draw_icon(p, "lock", mix(QColor(TEXT_DIM), col, 0.35 + 0.65 * flash))
        p.restore()
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9.5, QFont.Weight.Bold, 1.5))
        p.drawText(QRectF(r.left() + S(74), r.top() + S(10), r.width() - S(84), S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("NEXT UP"))
        p.setPen(col if near else QColor(TEXT))
        p.setFont(font(17, QFont.Weight.Black, 2))
        p.drawText(QRectF(r.left() + S(74), r.top() + S(24), r.width() - S(84), S(26)), int(Qt.AlignmentFlag.AlignVCenter),
                   tr(name).upper())
        p.setFont(font(11, QFont.Weight.Bold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(r.left() + S(74), r.top() + S(48), r.width() - S(84), S(18)), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("Jackpot and Horse Racing take turns every 20 minutes"))
        p.setPen(col if near else QColor(TEXT))
        p.setFont(font(22, QFont.Weight.Black))
        p.drawText(r.adjusted(0, 0, -S(16), 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                   jp_clock(left))


class JackpotWheel(QWidget):
    """The wheel: each player's slice is their share, in their colour. In the middle the countdown, then the spin
    (10 s) that lands on the winner the server picked when the lobby locked."""

    def __init__(self, page, size: int) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedSize(size, size)
        self.d: dict = {}
        self.offset = 0.0                                  # server clock minus ours
        self._spin_from = None
        self._t = QTimer(self)
        self._t.setInterval(16)
        self._t.timeout.connect(self.update)
        self._confetti = []

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def set_data(self, d: dict) -> None:
        if d.get("now"):
            self.offset = float(getattr(self.ctx, "jp_offset", float(d["now"]) - time.time()))
        if d.get("i_won") and not self.d.get("i_won"):
            rnd = random.Random()
            self._confetti = [(rnd.uniform(0, 1), rnd.uniform(-0.6, 0), rnd.uniform(0.15, 0.45), rnd.uniform(0, math.tau),
                               rnd.choice(["#FFC94D", "#FFE08A", "#FFFFFF", "#E8B33A"])) for _ in range(140)]
            self._conf_t = time.monotonic()
        self.d = d
        self.update()

    def server_now(self) -> float:
        return time.time() + self.offset

    def _angle(self, now: float) -> float:
        """Degrees the wheel has turned. Lands with the winning point (roll) under the pointer at the top."""
        d = self.d
        roll = d.get("roll")
        if roll is None or not d.get("spin_at"):
            return 0.0
        t = now - float(d["spin_at"])
        if t <= 0:
            return 0.0
        final = 360 * 7 + float(roll) * 360           # 7 full turns, then the winner's point
        k = min(1.0, t / JP_SPIN)
        return final * (1 - (1 - k) ** 4)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        d = self.d
        now = self.server_now()
        w = self.width()
        c = QPointF(w / 2, w / 2)
        rad = w * 0.44
        entries = d.get("entries") or []
        total = sum(int(e.get("value") or 0) for e in entries) or 0
        ang = self._angle(now)
        # the slices (clockwise from the top), turned by the spin
        start = 90.0 + ang
        if total <= 0:
            p.setPen(QPen(alpha("#FFFFFF", 0.12), S(10)))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawEllipse(c, rad - S(6), rad - S(6))
        winner = d.get("winner")
        landed = d.get("result_at") and now >= float(d["result_at"])
        for e in entries:
            share = int(e.get("value") or 0) / total if total else 0
            span = share * 360
            path = QPainterPath(c)
            path.arcTo(QRectF(c.x() - rad, c.y() - rad, rad * 2, rad * 2), start, -span)
            path.closeSubpath()
            col = jp_colour(e.get("colour"))
            if landed and winner and e.get("id") != winner:
                col = mix(col, QColor("#0B0E10"), 0.65)
            p.setPen(QPen(QColor("#0B0E10"), S(2)))
            p.setBrush(col)
            p.drawPath(path)
            start -= span
        # the middle: countdown, bots joining, or the winner
        inner = rad * 0.62
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#0B0E10"))
        p.drawEllipse(c, inner, inner)
        state = d.get("state")
        box = QRectF(c.x() - inner, c.y() - inner, inner * 2, inner * 2)
        if state == "open" and d.get("waiting"):
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(13, QFont.Weight.Black))
            p.drawText(box.adjusted(S(6), -S(8), -S(6), -S(8)), int(Qt.AlignmentFlag.AlignCenter | Qt.TextFlag.TextWordWrap),
                       tr("Waiting for a player"))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(9, QFont.Weight.Bold))
            p.drawText(box.adjusted(S(8), S(26), -S(8), S(26)), int(Qt.AlignmentFlag.AlignCenter | Qt.TextFlag.TextWordWrap),
                       tr("The clock starts when someone joins"))
        elif state == "open" and d.get("lock_at"):
            left = float(d["lock_at"]) - now
            k = max(0.0, min(1.0, left / JP_OPEN))
            p.setPen(QPen(QColor("#FFC94D"), S(5), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawArc(QRectF(c.x() - inner + S(8), c.y() - inner + S(8), (inner - S(8)) * 2, (inner - S(8)) * 2),
                      90 * 16, int(k * 360 * 16))
            p.setPen(QColor("#FFFFFF"))
            p.setFont(font(30, QFont.Weight.Black))
            p.drawText(box.adjusted(0, -S(14), 0, -S(14)), int(Qt.AlignmentFlag.AlignCenter), str(max(0, int(math.ceil(left)))))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10, QFont.Weight.Bold))
            p.drawText(box.adjusted(0, S(30), 0, S(30)), int(Qt.AlignmentFlag.AlignCenter), coins_text(total))
        elif state in ("locked", "picking", "done"):
            if d.get("spin_at") and now < float(d["spin_at"]):
                p.setPen(QColor("#FFFFFF"))
                p.setFont(font(13, QFont.Weight.Black))
                p.drawText(box.adjusted(S(6), -S(10), -S(6), -S(10)), int(Qt.AlignmentFlag.AlignCenter | Qt.TextFlag.TextWordWrap),
                           tr("Locked! Filling the seats…"))
                p.setPen(QColor(TEXT_DIM))
                p.setFont(font(10, QFont.Weight.Bold))
                p.drawText(box.adjusted(0, S(26), 0, S(26)), int(Qt.AlignmentFlag.AlignCenter), coins_text(total))
            elif not landed:
                p.setPen(QColor("#FFC94D"))
                p.setFont(font(15, QFont.Weight.Black, 2))
                p.drawText(box, int(Qt.AlignmentFlag.AlignCenter), tr("SPINNING"))
            else:
                we = next((e for e in entries if e.get("id") == winner), None)
                if we is not None:
                    col = jp_colour(we.get("colour"))
                    p.setPen(col)
                    p.setFont(font(10, QFont.Weight.Black, 2))
                    p.drawText(box.adjusted(0, -S(26), 0, -S(26)), int(Qt.AlignmentFlag.AlignCenter), tr("WINNER"))
                    p.setPen(QColor("#FFFFFF"))
                    p.setFont(font(17, QFont.Weight.Black))
                    p.drawText(box.adjusted(S(4), 0, -S(4), 0), int(Qt.AlignmentFlag.AlignCenter), str(we.get("name")))
                    p.setPen(QColor("#FFC94D"))
                    p.setFont(font(11, QFont.Weight.Bold))
                    p.drawText(box.adjusted(0, S(28), 0, S(28)), int(Qt.AlignmentFlag.AlignCenter), coins_text(total))
        # the pointer at the top
        tip = QPainterPath(QPointF(c.x(), c.y() - rad + S(14)))
        tip.lineTo(QPointF(c.x() - S(11), c.y() - rad - S(10)))
        tip.lineTo(QPointF(c.x() + S(11), c.y() - rad - S(10)))
        tip.closeSubpath()
        p.setPen(QPen(QColor("#0B0E10"), S(2)))
        p.setBrush(QColor("#FFFFFF"))
        p.drawPath(tip)
        # golden confetti for the winner
        if self._confetti:
            age = time.monotonic() - self._conf_t
            if age > 5:
                self._confetti = []
            for x, y0, sp, ph, col in self._confetti:
                y = (y0 + age * sp) * w
                if y > w:
                    continue
                q = alpha(col, max(0.0, 1 - age / 5))
                p.save()
                p.translate(x * w + math.sin(age * 3 + ph) * S(8), y)
                p.rotate(age * 200 + ph * 50)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(q)
                p.drawRect(QRectF(-S(3), -S(1.5), S(6), S(3)))
                p.restore()


class JackpotRow(QWidget):
    """One player in the jackpot: colour, name (BOT for bots), their items, worth and chance."""

    def __init__(self, ctx, e: dict, total: int, w: int, winner=None, landed: bool = False) -> None:
        super().__init__()
        self.ctx, self.e, self.total, self.winner, self.landed = ctx, e, total, winner, landed
        self.setFixedSize(w, S(50))

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        e = self.e
        r = QRectF(self.rect()).adjusted(0.5, 2, -0.5, -2)
        col = jp_colour(e.get("colour"))
        won = self.landed and e.get("id") == self.winner
        p.setPen(QPen(col if (e.get("me") or won) else alpha(col, 0.35), S(2) if won else 1.2))
        p.setBrush(alpha(col, 0.16 if won else 0.07))
        p.drawRoundedRect(r, S(10), S(10))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(col)
        p.drawRoundedRect(QRectF(r.left() + S(6), r.top() + S(6), S(6), r.height() - S(12)), S(3), S(3))
        name = str(e.get("name") or "?")
        if e.get("bot"):
            paint_bot_logo(p, QPointF(r.left() + S(30), r.center().y()), S(12))
        p.setPen(QColor(TEXT))
        p.setFont(font(12, QFont.Weight.Bold))
        nx = r.left() + S(48 if e.get("bot") else 20)
        p.drawText(QRectF(nx, r.top() + S(4), S(150), S(20)), int(Qt.AlignmentFlag.AlignVCenter),
                   name + ("  ·  " + tr("BOT") if e.get("bot") else "") + ("  (" + tr("you") + ")" if e.get("me") else ""))
        x = nx
        for it in (e.get("items") or [])[:3]:
            show_item(p, it, QRectF(x, r.bottom() - S(22), S(18), S(18)), 0, effects=False)
            x += S(21)
        pct_ = int(e.get("value") or 0) / self.total if self.total else 0
        p.setPen(col)
        p.setFont(font(14, QFont.Weight.Black))
        p.drawText(r.adjusted(0, 0, -S(10), -S(16)), int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                   pct(pct_))
        p.setPen(QColor(GOLD_TEXT))
        p.setFont(font(10, QFont.Weight.Bold))
        p.drawText(r.adjusted(0, S(18), -S(10), 0), int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                   coins_text(int(e.get("value") or 0)))


class JackpotPick(QWidget):
    """The winner's prize: everybody else's items; click to choose exactly how many you may take."""
    changed = pyqtSignal()

    def __init__(self, ctx, pool: list, allowed: int, w: int) -> None:
        super().__init__()
        self.ctx, self.pool, self.allowed = ctx, pool, int(allowed)
        self.picked: list = []
        self.per = 5
        self.th = S(74)
        n = max(1, (len(pool) + self.per - 1) // self.per)
        self.setFixedSize(w, n * self.th + (n - 1) * S(5))
        self.setCursor(Qt.CursorShape.PointingHandCursor)

    def _tile(self, i: int) -> QRectF:
        gap = S(5)
        w = (self.width() - gap * (self.per - 1)) / self.per
        r, c = divmod(i, self.per)
        return QRectF(c * (w + gap), r * (self.th + gap), w, self.th)

    def mousePressEvent(self, e) -> None:
        e.accept()

    def mouseReleaseEvent(self, e) -> None:
        i = next((k for k in range(len(self.pool)) if self._tile(k).contains(e.position())), -1)
        if i < 0:
            return
        key = self.pool[i]["key"]
        if key in self.picked:
            self.picked.remove(key)
            sfx.play("off")
        elif len(self.picked) >= self.allowed:
            return self.ctx.toast(tr("You can take {n}: tap one you picked to swap it", n=self.allowed), "warn")
        else:
            self.picked.append(key)
            sfx.play("pick")
        self.changed.emit()
        self.update()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        now = time.monotonic()
        for i, x in enumerate(self.pool):
            r = self._tile(i).adjusted(0.5, 0.5, -0.5, -0.5)
            on = x["key"] in self.picked
            col = jp_colour(x.get("colour"))
            p.setPen(QPen(QColor("#FFC94D") if on else alpha(col, 0.4), S(2.2) if on else 1))
            p.setBrush(alpha("#FFC94D", 0.18) if on else alpha(col, 0.07))
            p.drawRoundedRect(r, S(9), S(9))
            dd = min(r.width(), r.height()) * 0.5
            show_item(p, x["item"], QRectF(r.center().x() - dd / 2, r.top() + S(6), dd, dd), now, effects=on)
            p.setPen(QColor(GOLD_TEXT))
            p.setFont(font(9, QFont.Weight.Bold))
            p.drawText(QRectF(r.left(), r.bottom() - S(19), r.width(), S(14)), int(Qt.AlignmentFlag.AlignCenter),
                       coins_text(int(x.get("worth") or 0)))
            if on:
                b = QRectF(r.right() - S(18), r.top() + S(3), S(15), S(15))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor("#FFC94D"))
                p.drawEllipse(b)
                p.setPen(QColor("#1A1200"))
                p.setFont(font(9, QFont.Weight.Black))
                p.drawText(b, int(Qt.AlignmentFlag.AlignCenter), "✓")


def _jp_shape(d: dict) -> tuple:
    """What, when changed, needs the page rebuilt (the wheel itself redraws by itself)."""
    if not isinstance(d, dict):
        return ()
    return (d.get("id"), d.get("state"), len(d.get("entries") or []), d.get("mine"), d.get("i_won"),
            bool(d.get("pool")), d.get("winner") is not None, bool(d.get("feature", True)))


def load_jackpot(ctx, then=None) -> None:
    if getattr(ctx, "_jp_asking", False):
        return
    ctx._jp_asking = True

    def got(ok: bool, data) -> None:
        ctx._jp_asking = False
        if not ok or not isinstance(data, dict):
            if "jackpot" in str(data).lower() or server_missing(data):
                ctx.jackpot_missing = True
            return
        old = getattr(ctx, "jackpot_data", None)
        ctx.jackpot_data = data
        if data.get("now"):                               # 5.3: one clock for everybody, the server's
            ctx.jp_offset = float(data["now"]) - time.time()
            ctx.jp_got_at = jp_now(ctx)
        ctx.jackpot_in = bool(data.get("mine")) and data.get("state") in ("open", "locked", "picking")
        if then:
            then(_jp_shape(old) != _jp_shape(data))
    ctx.online.ask("rb_jackpot_state", {}, got)


def glow_jackpot(ctx) -> None:
    """5.2: a gold glow sweeps the top of the screen when a jackpot opens."""
    from PyQt6.QtGui import QGuiApplication
    screen = QGuiApplication.primaryScreen()
    if screen is None:
        return
    fx = FxOverlay(ctx, screen)
    w = screen.geometry().width()

    def paint(p: QPainter, k: float, now: float) -> None:
        a = math.sin(k * math.pi)
        g = QLinearGradient(QPointF(0, 0), QPointF(0, S(120)))
        g.setColorAt(0, QColor(255, 201, 77, int(170 * a)))
        g.setColorAt(1, QColor(255, 201, 77, 0))
        p.fillRect(QRectF(0, 0, w, S(120)), g)
        x = w * k
        band = QLinearGradient(QPointF(x - S(220), 0), QPointF(x + S(220), 0))
        band.setColorAt(0, QColor(255, 255, 255, 0))
        band.setColorAt(0.5, QColor(255, 240, 200, int(160 * a)))
        band.setColorAt(1, QColor(255, 255, 255, 0))
        p.fillRect(QRectF(x - S(220), 0, S(440), S(8)), band)
    fx.add(2.4, paint)


# ==================================================================================================
# SECTION: horse racing (6.3)
# ==================================================================================================
HORSE_COLOURS = ["#FF4D4D", "#4FA3FF", "#3DDC84", "#FFD34D", "#C77BFF"]      # silks and saddle cloths, numbers 1 to 5
HORSE_COATS = ["#7A4521", "#26201C", "#D8D2C8", "#B5562A", "#E0B86A"]        # bay, black, grey, chestnut, palomino
HORSE_MANES = ["#2A160A", "#0C0A09", "#F4F1EC", "#6E2A10", "#FFF1CC"]
HORSE_NAMES = ["Red Rocket", "Blue Thunder", "Green Clover", "Golden Sun", "Purple Storm"]
RACE_ROLL, RACE_RUN, RACE_LEAD = 3.0, 240.0, 7.0     # the rolling start, the race clock, lock -> gun (s)
RACE_LEN = 4.0                                       # 7.0: the track is 4 times longer (the camera follows the leaders)
RACE_SPEED = 5.0                                     # 9.5: the horses run 2.5 times faster (same track): RACE_RUN / 5
RACE_FINISH = RACE_RUN / RACE_SPEED                  # when the winner crosses the line (s after the rolling start)
RACE_GAP = 0.022                                     # the line-up: one horse behind the other (track = 1.0 long)
RACE_VIEW = 0.30                                     # how much of the track the camera shows


def race_now(ctx) -> float:
    return time.time() + float(getattr(ctx, "race_offset", 0.0) or 0.0)


def race_phase(ctx):
    """('open', s left to bet), ('running', 0), ('done', 0) or ('closed', s until the next race)."""
    d = getattr(ctx, "race_data", None)
    now = race_now(ctx)
    if isinstance(d, dict) and d.get("now") and now - float(getattr(ctx, "race_got_at", 0) or 0) < 30:
        st = d.get("state")
        if st == "open":
            return "open", max(0.0, float(d.get("lock_at") or 0) - now)
        if st == "live":
            return "running", 0.0
        if st == "done":
            return "done", 0.0
        return "closed", max(0.0, float(d.get("next_at") or 0) - now)
    return "unknown", 0.0


def _race_shape(d) -> tuple:
    if not isinstance(d, dict):
        return ()
    return (d.get("id"), d.get("state"), len(d.get("bets") or []), d.get("mine"), bool(d.get("feature", True)))


def load_race(ctx, then=None) -> None:
    if getattr(ctx, "_race_asking", False):
        return
    ctx._race_asking = True

    def got(ok: bool, data) -> None:
        ctx._race_asking = False
        if not ok or not isinstance(data, dict):
            if "race" in str(data).lower() or server_missing(data):
                ctx.race_missing = True
            return
        old = getattr(ctx, "race_data", None)
        ctx.race_data = data
        if data.get("now"):
            ctx.race_offset = float(data["now"]) - time.time()
            ctx.race_got_at = race_now(ctx)
        if then:
            then(_race_shape(old) != _race_shape(data))
    ctx.online.ask("rb_race_state", {}, got)


def race_plan(seed: int, winner, places=None) -> dict:
    """The whole race from the server's seed and winner, the same on every PC: the line-up (front to back), the
    finishing order and times, and each horse's surges and fades. Each horse runs p(u) = u + a1 sin(pi u) +
    a2 sin(2 pi u) + a3 sin(3 pi u) (u = time / its finishing time): with |a1| pi + 2|a2| pi + 3|a3| pi < 1 it never
    runs backwards and crosses the line exactly at its finishing time, so the winner the server drew always wins."""
    rnd = random.Random(int(seed or 0) * 7919 + 17)
    column = rnd.sample(range(5), 5)
    plan = {"column": column, "fin": {}, "waves": {}, "order": []}
    if winner is None:
        return plan
    w = int(winner)
    order = [w] + rnd.sample([k for k in range(5) if k != w], 4)
    try:                                                   # 6.4: the server draws the whole finishing order
        if places and sorted(int(x) for x in places) == [0, 1, 2, 3, 4] and int(places[0]) == w:
            order = [int(x) for x in places]
    except (TypeError, ValueError):
        pass
    t = RACE_RUN
    for i, k in enumerate(order):
        if i:
            t += rnd.uniform(0.5, 2.2)                       # 6.8: the race is 3 times longer, so the gaps are bigger
        plan["fin"][k] = t / RACE_SPEED
    for k in range(5):                                       # 6.8: six waves each, so there are many more lead changes
        co = [rnd.uniform(-1, 1) * 0.11 / j for j in range(1, 7)]
        room = math.pi * sum((j + 1) * abs(a) for j, a in enumerate(co))
        scale = min(1.0, 0.82 / max(room, 1e-9))
        plan["waves"][k] = tuple(a * scale for a in co)
    plan["order"] = order
    return plan


def race_pos(plan: dict, k: int, t: float) -> tuple:
    """7.0: (where horse k is on the track, its speed), the track being RACE_LEN long. The race proper is scaled so the
    horses keep their pace on screen while the track is longer; the line-up before the gun is not stretched."""
    x, v = _race_pos_unit(plan, k, t)
    if t >= RACE_ROLL:
        x *= RACE_LEN
    return x, v * RACE_LEN


def _race_pos_unit(plan: dict, k: int, t: float) -> tuple:
    """(where horse k is on a track 1.0 long, its speed) t seconds after the gun. Before the race proper the line-up rolls
    up from the back: the last horse goes first, then the next one, and all of them reach the start line together."""
    ci = plan["column"].index(k)                           # 0 = the front of the line-up
    fin = plan["fin"].get(k, RACE_FINISH)
    co = plan["waves"].get(k, ())
    v0 = (1 + math.pi * sum((j + 1) * a for j, a in enumerate(co))) / fin       # its speed when the race proper begins
    x0 = -(ci + 1) * RACE_GAP
    if t <= 0 or not plan["fin"]:
        return x0, 0.0
    if t < RACE_ROLL:
        ts = (4 - ci) / 5 * RACE_ROLL                       # back to front
        if t <= ts:
            return x0, 0.0
        T = RACE_ROLL - ts
        s = (t - ts) / T
        m1 = v0 * T
        x = (2 * s ** 3 - 3 * s ** 2 + 1) * x0 + (s ** 3 - s ** 2) * m1
        v = ((6 * s ** 2 - 6 * s) * x0 + (3 * s ** 2 - 2 * s) * m1) / T
        return x, max(0.0, v)
    tau = t - RACE_ROLL
    if tau <= fin:
        u = tau / fin
        x = u + sum(a * math.sin((j + 1) * math.pi * u) for j, a in enumerate(co))
        v = (1 + math.pi * sum((j + 1) * a * math.cos((j + 1) * math.pi * u) for j, a in enumerate(co))) / fin
        return x, v
    vend = (1 + math.pi * sum((j + 1) * a * (-1) ** (j + 1) for j, a in enumerate(co))) / fin    # past the line: it slows down
    c = 0.9
    return 1.0 + vend * (1 - math.exp(-c * (tau - fin))) / c, vend * math.exp(-c * (tau - fin))


def paint_horse(p: QPainter, x: float, y: float, sz: float, lane: int, phase: float, moving: float, me: bool = False) -> None:
    """A racehorse seen from the side, running to the right: coat, mane and tail, four galloping legs, the saddle cloth
    in its colour with its big number, and the jockey in the same silks. (x, y) = the middle of the body."""
    coat = QColor(HORSE_COATS[lane])
    dark = coat.darker(135)
    mane = QColor(HORSE_MANES[lane])
    silk = QColor(HORSE_COLOURS[lane])
    p.save()
    bob = math.sin(phase * 2) * sz * 0.025 * moving
    y += bob
    # shadow
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(alpha("#000000", 0.22))
    p.drawEllipse(QPointF(x, y + sz * 0.62 - bob), sz * 0.55, sz * 0.07)
    # legs (far pair first, darker)
    def leg(hx, hy, off, near):
        a = math.sin(phase + off) * 0.75 * moving
        b = (math.sin(phase + off - 1.2) * 0.6 - 0.35) * moving
        l1, l2 = sz * 0.30, sz * 0.30
        kx, ky = hx + math.sin(a) * l1, hy + math.cos(a) * l1
        fx, fy = kx + math.sin(a + b) * l2, ky + math.cos(a + b) * l2
        col = coat if near else dark
        p.setPen(QPen(col, sz * 0.075, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        path = QPainterPath(QPointF(hx, hy))
        path.lineTo(kx, ky)
        path.lineTo(fx, fy)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#1A1410"))
        p.drawEllipse(QPointF(fx, fy), sz * 0.045, sz * 0.035)
    fx_, bx_ = x + sz * 0.30, x - sz * 0.30
    leg(fx_ - sz * 0.04, y + sz * 0.12, 0.0, False)
    leg(bx_ - sz * 0.04, y + sz * 0.12, math.pi * 0.85, False)
    # tail
    p.setPen(QPen(mane, sz * 0.07, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
    p.setBrush(Qt.BrushStyle.NoBrush)
    tail = QPainterPath(QPointF(x - sz * 0.48, y - sz * 0.08))
    sw = math.sin(phase * 1.0) * sz * 0.06 * moving
    tail.cubicTo(x - sz * 0.66, y - sz * 0.04 + sw, x - sz * 0.74, y + sz * 0.10 - sw, x - sz * 0.80, y + sz * 0.22 + sw)
    p.drawPath(tail)
    # body
    p.setPen(Qt.PenStyle.NoPen)
    g = QLinearGradient(QPointF(x, y - sz * 0.22), QPointF(x, y + sz * 0.22))
    g.setColorAt(0, coat.lighter(118))
    g.setColorAt(1, dark)
    p.setBrush(g)
    p.drawEllipse(QPointF(x, y), sz * 0.52, sz * 0.22)
    # neck and head
    neck = QPainterPath(QPointF(x + sz * 0.30, y - sz * 0.14))
    neck.lineTo(x + sz * 0.56, y - sz * 0.50)
    neck.lineTo(x + sz * 0.72, y - sz * 0.44)
    neck.lineTo(x + sz * 0.50, y + sz * 0.06)
    neck.closeSubpath()
    p.setBrush(coat)
    p.drawPath(neck)
    p.save()
    p.translate(x + sz * 0.70, y - sz * 0.42)
    p.rotate(28)
    p.drawRoundedRect(QRectF(-sz * 0.08, -sz * 0.09, sz * 0.32, sz * 0.17), sz * 0.08, sz * 0.08)
    p.setBrush(QColor("#111111"))
    p.drawEllipse(QPointF(sz * 0.03, -sz * 0.03), sz * 0.022, sz * 0.022)      # eye
    p.restore()
    ear = QPolygonF([QPointF(x + sz * 0.62, y - sz * 0.52), QPointF(x + sz * 0.60, y - sz * 0.64),
                     QPointF(x + sz * 0.67, y - sz * 0.54)])
    p.setBrush(dark)
    p.drawPolygon(ear)
    p.setPen(QPen(mane, sz * 0.06, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
    p.drawLine(QPointF(x + sz * 0.34, y - sz * 0.20), QPointF(x + sz * 0.58, y - sz * 0.52))
    # near legs
    leg(fx_ + sz * 0.04, y + sz * 0.12, math.pi * 0.35, True)
    leg(bx_ + sz * 0.04, y + sz * 0.12, math.pi * 1.2, True)
    # saddle cloth with the number
    p.setPen(QPen(alpha("#FFFFFF", 0.85), max(1.0, sz * 0.015)))
    p.setBrush(silk)
    cloth = QRectF(x - sz * 0.22, y - sz * 0.20, sz * 0.38, sz * 0.27)
    p.drawRoundedRect(cloth, sz * 0.04, sz * 0.04)
    p.setPen(QColor("#FFFFFF") if lane != 3 else QColor("#1A1A1A"))
    p.setFont(font(max(6.0, sz / S(1) * 0.17), QFont.Weight.Black))
    p.drawText(cloth, int(Qt.AlignmentFlag.AlignCenter), str(lane + 1))
    # jockey
    jx, jy = x + sz * 0.02, y - sz * 0.36
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(silk.darker(110))
    body = QPainterPath(QPointF(jx - sz * 0.10, jy + sz * 0.16))
    body.lineTo(jx + sz * 0.02, jy - sz * 0.06)
    body.lineTo(jx + sz * 0.16, jy - sz * 0.02)
    body.lineTo(jx + sz * 0.08, jy + sz * 0.18)
    body.closeSubpath()
    p.drawPath(body)
    p.setPen(QPen(silk, sz * 0.05, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
    p.drawLine(QPointF(jx + sz * 0.10, jy), QPointF(jx + sz * 0.30, jy + sz * 0.08))       # arm to the reins
    p.setPen(Qt.PenStyle.NoPen)
    p.setBrush(QColor("#F1C9A5"))
    p.drawEllipse(QPointF(jx + sz * 0.10, jy - sz * 0.12), sz * 0.065, sz * 0.065)
    p.setBrush(silk)
    p.drawChord(QRectF(jx + sz * 0.035, jy - sz * 0.20, sz * 0.13, sz * 0.13), 0, 180 * 16)    # helmet
    if me:                                                  # your horse: a small arrow over it
        p.setBrush(QColor("#FFFFFF"))
        tip = QPointF(jx + sz * 0.10, jy - sz * 0.30)
        p.drawPolygon(QPolygonF([tip, tip + QPointF(-sz * 0.07, -sz * 0.10), tip + QPointF(sz * 0.07, -sz * 0.10)]))
    p.restore()


RACE_SKIES = {"desert": ("#FFB46B", "#FFE6B8", "#E9B96E", "#C98F4A", "#D9A35B"),
              "forest": ("#6FB7FF", "#CDEBFF", "#3E7A3A", "#2C5A2A", "#7A5A36"),
              "snow": ("#9FB8D6", "#E9F2FB", "#DDE7F2", "#B9C9DB", "#F4F8FC")}


RACE_EXTRA = ("beach", "canyon", "night", "volcano", "moon")
RACE_SKIES.update({"beach": ("#58C4F5", "#E8F8FF", "#7FD3E8", "#2FA36B", "#F0D9A0"),
                   "canyon": ("#F29A62", "#FFD9A8", "#B5532F", "#8A3A20", "#C96F3F"),
                   "night": ("#050818", "#27306B", "#151B3D", "#7A86C8", "#3A3F55"),
                   "volcano": ("#2A0A0A", "#B53A14", "#1B0F10", "#FF6A1F", "#3A2A28"),
                   "moon": ("#000208", "#141B33", "#555B6B", "#8A90A0", "#9EA3B0")})
RACE_MAP_NAMES = {"desert": "Desert", "forest": "Forest", "snow": "Snow", "beach": "Beach", "canyon": "Canyon", "night": "Night City",
                  "volcano": "Volcano", "moon": "Moon"}
FR.update({"Beach": "Plage", "Canyon": "Canyon", "Night City": "Ville de nuit", "Volcano": "Volcan", "Moon": "Lune"})


def _paint_race_map_extra(p: QPainter, r: QRectF, mp: str, cam: float, now: float) -> None:
    """6.8: five more race maps: Beach, Canyon, Night City, Volcano and the Moon."""
    sky1, sky2, far, mid, track = RACE_SKIES[mp]
    W, H = r.width(), r.height()
    base = r.top() + H * 0.46
    g = QLinearGradient(r.topLeft(), QPointF(r.left(), base))
    g.setColorAt(0, QColor(sky1))
    g.setColorAt(1, QColor(sky2))
    p.fillRect(r, g)
    p.setPen(Qt.PenStyle.NoPen)
    rnd = random.Random({"beach": 11, "canyon": 12, "night": 13, "volcano": 14, "moon": 15}[mp])
    if mp in ("night", "moon", "volcano"):                      # stars (twinkling) or drifting embers
        for k in range(46 if mp != "volcano" else 0):
            x = r.left() + W * rnd.random()
            y = r.top() + H * 0.42 * rnd.random()
            p.setBrush(alpha("#FFFFFF", 0.25 + 0.6 * abs(math.sin(now * 1.1 + k * 1.7))))
            p.drawEllipse(QPointF(x, y), S(1.1), S(1.1))
    if mp == "beach" or mp == "canyon":                         # a big sun
        p.setBrush(alpha("#FFF4C9", 0.9))
        p.drawEllipse(QPointF(r.left() + W * 0.2, r.top() + H * 0.14), H * 0.075, H * 0.075)
        gl = QRadialGradient(QPointF(r.left() + W * 0.2, r.top() + H * 0.14), H * 0.3)
        gl.setColorAt(0, alpha("#FFF4C9", 0.35))
        gl.setColorAt(1, alpha("#FFF4C9", 0.0))
        p.setBrush(gl)
        p.drawEllipse(QPointF(r.left() + W * 0.2, r.top() + H * 0.14), H * 0.3, H * 0.3)
    elif mp == "night":                                         # a full moon
        mc = QPointF(r.left() + W * 0.8, r.top() + H * 0.14)
        gl = QRadialGradient(mc, H * 0.25)
        gl.setColorAt(0, alpha("#DDE6FF", 0.4))
        gl.setColorAt(1, alpha("#DDE6FF", 0.0))
        p.setBrush(gl)
        p.drawEllipse(mc, H * 0.25, H * 0.25)
        p.setBrush(QColor("#F3F6FF"))
        p.drawEllipse(mc, H * 0.065, H * 0.065)
    elif mp == "moon":                                          # the Earth hanging in the black sky
        ec = QPointF(r.left() + W * 0.22, r.top() + H * 0.17)
        p.setBrush(QColor("#2A6FD6"))
        p.drawEllipse(ec, H * 0.11, H * 0.11)
        p.setBrush(alpha("#4DBE6A", 0.85))
        p.drawEllipse(QPointF(ec.x() - H * 0.03, ec.y() - H * 0.02), H * 0.045, H * 0.06)
        p.drawEllipse(QPointF(ec.x() + H * 0.05, ec.y() + H * 0.05), H * 0.03, H * 0.025)
        p.setBrush(alpha("#FFFFFF", 0.45))
        p.drawEllipse(QPointF(ec.x() + H * 0.02, ec.y() - H * 0.07), H * 0.05, H * 0.015)
    elif mp == "volcano":
        for k in range(18):
            u = (now * 0.12 * (0.5 + rnd.random()) + rnd.random()) % 1.0
            p.setBrush(alpha("#FFB04D", 0.7 * (1 - u)))
            p.drawEllipse(QPointF(r.left() + W * ((rnd.random() + math.sin(now * 0.4 + k) * 0.02) % 1.0), base - u * H * 0.45), S(1.6), S(1.6))
    # the far layer (slow)
    off = cam * W * 0.4
    if mp == "beach":                                           # the sea, with its waves rolling in
        sea = QRectF(r.left(), base - H * 0.1, W, H * 0.1)
        g3 = QLinearGradient(sea.topLeft(), sea.bottomLeft())
        g3.setColorAt(0, QColor("#4AB8E8"))
        g3.setColorAt(1, QColor("#1E7FB8"))
        p.fillRect(sea, g3)
        p.setPen(QPen(alpha("#FFFFFF", 0.5), S(1.2)))
        for j in range(4):
            y = sea.top() + sea.height() * (j + 0.5) / 4
            path = QPainterPath()
            for x in range(0, int(W) + 8, 8):
                yy = y + math.sin(x / W * 14 + now * 1.4 + j * 1.7 - off * 0.01) * S(1.6)
                path.lineTo(r.left() + x, yy) if x else path.moveTo(r.left() + x, yy)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    path = QPainterPath(QPointF(r.left(), base))
    n = 41
    for i in range(n):
        x = r.left() + i * W / 20 - (off % (W))
        if mp == "canyon":                                      # flat-topped mesas
            hh = (0.08 + 0.2 * (((i // 3) * 37) % 5) / 5) * H
            path.lineTo(x, base - (hh if i % 3 else hh * 0.55))
        elif mp == "night":                                     # a skyline
            hh = (0.06 + 0.22 * (((i // 2) * 53) % 7) / 7) * H
            path.lineTo(x, base - hh)
            path.lineTo(x + W / 20, base - hh)
        elif mp == "volcano":
            hh = abs(((i * 0.23) % 1.0) - 0.5) * H * 0.9 + H * 0.03
            path.lineTo(x, base - hh)
        elif mp == "moon":
            hh = (math.sin(i * 0.8) * 0.5 + 0.5) * H * 0.07 + H * 0.02
            path.lineTo(x, base - hh)
        else:
            hh = (math.sin(i * 0.7 + 1) * 0.5 + 0.5) * H * 0.045 + H * 0.01
            path.lineTo(x, base - hh)
    path.lineTo(r.right(), base)
    path.closeSubpath()
    p.setBrush(QColor(far))
    p.drawPath(path)
    if mp == "night":                                           # lit windows
        p.setBrush(alpha("#FFD98A", 0.75))
        for i in range(0, 60):
            x = r.left() + ((i * 47) % 100) / 100 * W
            y = base - H * (0.03 + 0.2 * (((i * 31) % 17) / 17))
            if (int(now * 0.3 + i) % 5) != 0:
                p.drawRect(QRectF(x, y, S(2), S(2.6)))
    if mp == "volcano":                                         # a glowing crater and lava on the slopes
        p.setPen(QPen(alpha("#FF6A1F", 0.5 + 0.3 * math.sin(now * 2)), S(1.8)))
        p.drawPath(path)
        p.setPen(Qt.PenStyle.NoPen)
    # the middle layer (faster)
    step = W / 6
    off2 = (cam * W * 1.6) % step
    for i in range(-1, 8):
        x = r.left() + i * step - off2
        k = int((cam * W * 1.6) // step) + i
        s = 0.7 + 0.5 * ((k * 37) % 7) / 7
        y0 = base
        if mp == "beach":                                       # palm trees
            sway = math.sin(now * 1.2 + k) * S(2)
            p.setPen(QPen(QColor("#7A5230"), S(4) * s, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            p.drawLine(QPointF(x, y0), QPointF(x + S(4) * s + sway * 0.3, y0 - S(34) * s))
            p.setPen(QPen(QColor("#2FA36B"), S(3) * s, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            tip = QPointF(x + S(4) * s + sway * 0.3, y0 - S(34) * s)
            for a in (-150, -120, -90, -60, -30):
                ar = math.radians(a)
                p.drawLine(tip, QPointF(tip.x() + math.cos(ar) * S(18) * s + sway, tip.y() + math.sin(ar) * S(10) * s + S(6) * s))
            p.setPen(Qt.PenStyle.NoPen)
        elif mp == "canyon":                                    # boulders and dry bushes
            p.setBrush(QColor(mid))
            p.drawEllipse(QPointF(x, y0 - S(5) * s), S(16) * s, S(9) * s)
            p.setBrush(QColor(mid).darker(120))
            p.drawEllipse(QPointF(x + S(14) * s, y0 - S(3) * s), S(9) * s, S(6) * s)
            p.setPen(QPen(QColor("#7A5A2A"), S(1.2)))
            for a in (-70, -90, -110):
                ar = math.radians(a)
                p.drawLine(QPointF(x - S(18) * s, y0), QPointF(x - S(18) * s + math.cos(ar) * S(12) * s, y0 + math.sin(ar) * S(12) * s))
            p.setPen(Qt.PenStyle.NoPen)
        elif mp == "night":                                     # street lamps with glowing light
            p.setBrush(QColor("#1A1F33"))
            p.drawRect(QRectF(x - S(1.5), y0 - S(40) * s, S(3), S(40) * s))
            lg = QRadialGradient(QPointF(x, y0 - S(40) * s), S(34) * s)
            lg.setColorAt(0, alpha("#FFE7A8", 0.8))
            lg.setColorAt(1, alpha("#FFE7A8", 0.0))
            p.setBrush(lg)
            p.drawEllipse(QPointF(x, y0 - S(40) * s), S(34) * s, S(34) * s)
            p.setBrush(QColor("#FFF3C8"))
            p.drawEllipse(QPointF(x, y0 - S(40) * s), S(3.4) * s, S(3.4) * s)
        elif mp == "volcano":                                   # black rock spikes with glowing cracks
            p.setBrush(QColor("#140B0C"))
            p.drawPolygon(QPolygonF([QPointF(x, y0 - S(34) * s), QPointF(x - S(13) * s, y0), QPointF(x + S(13) * s, y0)]))
            p.setPen(QPen(alpha("#FF7A2E", 0.5 + 0.4 * math.sin(now * 3 + k)), S(1.4)))
            p.drawLine(QPointF(x, y0 - S(30) * s), QPointF(x - S(2) * s, y0 - S(12) * s))
            p.setPen(Qt.PenStyle.NoPen)
        else:                                                   # moon rocks
            p.setBrush(QColor(mid))
            p.drawEllipse(QPointF(x, y0 - S(4) * s), S(12) * s, S(6) * s)
            p.setBrush(QColor(mid).darker(125))
            p.drawEllipse(QPointF(x + S(10) * s, y0 - S(2) * s), S(6) * s, S(3.4) * s)
    # the track
    tr_ = QRectF(r.left(), base, W, H - (base - r.top()))
    g2 = QLinearGradient(tr_.topLeft(), tr_.bottomLeft())
    g2.setColorAt(0, QColor(track).lighter(108))
    g2.setColorAt(1, QColor(track).darker(112))
    p.fillRect(tr_, g2)
    if mp == "moon":                                            # craters on the ground
        p.setPen(QPen(alpha("#000000", 0.25), S(1)))
        p.setBrush(alpha("#000000", 0.12))
        for i in range(-1, 9):
            cx = r.left() + ((i * 0.31) % 1.0) * W * 1.2 - ((cam * W / RACE_VIEW * 0.5) % (W * 1.2)) + W * 0.1
            p.drawEllipse(QPointF(cx % (W * 1.2), base + H * (0.08 + 0.4 * ((i * 53) % 7) / 7)), S(14), S(4))
        p.setPen(Qt.PenStyle.NoPen)
    lane_h = (H * 0.50) / 5
    p.setPen(QPen(alpha("#FFFFFF", 0.22), S(1), Qt.PenStyle.DashLine))
    for i in range(1, 5):
        y = base + i * lane_h
        p.drawLine(QPointF(r.left(), y), QPointF(r.right(), y))
    rail = QColor({"beach": "#FFFFFF", "canyon": "#F4E7CF", "night": "#9FB3FF", "volcano": "#FF9A4D", "moon": "#DDE3EE"}[mp])
    p.setPen(QPen(rail, S(2.5)))
    p.drawLine(QPointF(r.left(), base - S(8)), QPointF(r.right(), base - S(8)))
    p.setPen(QPen(rail, S(2)))
    pst = W / 10
    off3 = (cam * W / RACE_VIEW) % pst
    for i in range(-1, 12):
        x = r.left() + i * pst - off3
        p.drawLine(QPointF(x, base - S(8)), QPointF(x, base))


class RaceView(QWidget):
    """The race track: the map (desert, forest or snow) with its own sky and scenery, the five horses lined up one
    behind the other, 3 2 1 and the gun, the rolling start, the race with its lead changes, and the finish."""

    def __init__(self, page, w: int) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedSize(w, int(S(250)))
        self.d: dict = {}
        self.plan = None
        self._plan_key = None
        self._said = set()
        self._t = QTimer(self)
        self._t.setInterval(16)
        self._t.timeout.connect(self._tick)
        rnd = random.Random(5)
        self.flakes = [(rnd.random(), rnd.random(), rnd.uniform(0.5, 1.4)) for _ in range(70)]

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def set_data(self, d: dict) -> None:
        self.d = d or {}
        key = (self.d.get("seed"), self.d.get("winner"), tuple(self.d.get("places") or ()))
        if key != self._plan_key:
            self._plan_key = key
            self.plan = race_plan(self.d.get("seed") or 0, self.d.get("winner"), self.d.get("places"))
        self.update()

    def t(self) -> float:
        """Seconds since the gun (negative before)."""
        if not self.d.get("start_at"):
            return -99.0
        return race_now(self.ctx) - float(self.d["start_at"])

    def _tick(self) -> None:
        t = self.t()
        st = self.d.get("state")
        if st in ("live", "done") and self.d.get("start_at"):
            rid = self.d.get("id")
            for n in (3, 2, 1):                              # 3, 2, 1 ...
                if -n <= t < -n + 0.5 and (rid, n) not in self._said:
                    self._said.add((rid, n))
                    sfx.play("beep")
            if 0 <= t < 0.6 and (rid, "gun") not in self._said:  # ... and the gun
                self._said.add((rid, "gun"))
                sfx.play("gun")
            if t >= RACE_ROLL + RACE_FINISH and (rid, "fin") not in self._said and t < RACE_ROLL + RACE_FINISH + 3:
                self._said.add((rid, "fin"))
                mine = self.d.get("mine")
                if mine is not None and mine == self.d.get("winner"):
                    sfx.tune("bigwin")
                else:
                    sfx.tune("win")
        self.update()

    # -- drawing
    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect())
        clip = QPainterPath()
        clip.addRoundedRect(r, S(14), S(14))
        p.setClipPath(clip)
        d = self.d
        mp = d.get("map") if d.get("map") in RACE_SKIES else "forest"
        t = self.t()
        plan = self.plan or race_plan(0, None)
        live = d.get("state") in ("live", "done") and plan["fin"]
        xs = {}
        for k in range(5):
            xs[k] = race_pos(plan, k, t if live else -1.0)
        lead = max(x for x, _v in xs.values())
        cam = max(-0.17, min(RACE_LEN + 0.12 - RACE_VIEW, lead - RACE_VIEW * 0.68))
        self._paint_map(p, r, mp, cam, time.monotonic())
        W = r.width()
        top = r.top() + r.height() * 0.46
        lane_h = (r.height() * 0.50) / 5

        def X(x):
            return r.left() + (x - cam) / RACE_VIEW * W
        # the start and finish lines
        for line, chk in ((0.0, False), (RACE_LEN, True)):
            lx = X(line)
            if -S(20) < lx < W + S(20):
                if chk:
                    sq = lane_h / 3
                    for j in range(int(r.height() * 0.5 / sq) + 1):
                        for i in range(2):
                            p.fillRect(QRectF(lx + i * sq, top + j * sq, sq, sq),
                                       QColor("#FFFFFF") if (i + j) % 2 == 0 else QColor("#111111"))
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(QColor("#E8C26A"))
                    p.drawRect(QRectF(lx - S(3), top - S(46), S(4), S(46)))
                    p.setFont(font(9, QFont.Weight.Black, 1))
                    p.setPen(QColor("#FFFFFF"))
                    p.drawText(QRectF(lx - S(40), top - S(62), S(80), S(14)), int(Qt.AlignmentFlag.AlignCenter), tr("FINISH"))
                else:
                    p.fillRect(QRectF(lx - S(1.5), top, S(3), r.height() * 0.5), alpha("#FFFFFF", 0.9))
        # distance posts
        for i in range(1, 10):
            px = X(i / 10)
            if -S(10) < px < W + S(10):
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha("#FFFFFF", 0.85))
                p.drawRect(QRectF(px - S(1.5), top - S(16), S(3), S(16)))
                p.setFont(font(7.5, QFont.Weight.Black))
                p.setPen(alpha("#000000", 0.6))
                p.drawText(QRectF(px - S(20), top - S(28), S(40), S(12)), int(Qt.AlignmentFlag.AlignCenter), f"{(10 - i) * 100}")
        # horses, back lane first (depth)
        sz = lane_h * 2.0
        mine = d.get("mine")
        for k in range(5):
            x, v = xs[k]
            hx = X(x) - sz * 0.25
            hy = top + (k + 0.5) * lane_h - sz * 0.22
            moving = min(1.0, v * 66) if live and t > 0 else 0.0
            phase = (x * 150 + k * 0.7) * 2 * math.pi / 6 if moving else 0.0
            if moving > 0.1:                                    # dust / snow spray
                p.setPen(Qt.PenStyle.NoPen)
                col = QColor("#FFFFFF") if mp == "snow" else QColor(RACE_SKIES[mp][4])
                for j in range(4):
                    k2 = (time.monotonic() * 3 + j * 0.25 + k * 0.13) % 1.0
                    p.setBrush(alpha(col, 0.35 * (1 - k2) * moving))
                    p.drawEllipse(QPointF(hx - sz * (0.45 + k2 * 0.6), hy + sz * 0.55 - k2 * sz * 0.15),
                                  sz * 0.08 * (0.5 + k2), sz * 0.05 * (0.5 + k2))
            paint_horse(p, hx, hy, sz, k, phase, moving, me=(mine == k))
        if mp == "snow":                                        # falling snow in front
            now = time.monotonic()
            p.setPen(Qt.PenStyle.NoPen)
            for fx, fy, spd in self.flakes:
                yy = (fy + now * 0.08 * spd) % 1.0
                xx = (fx - cam * 0.9 + math.sin(now + fy * 9) * 0.01) % 1.0
                p.setBrush(alpha("#FFFFFF", 0.75))
                p.drawEllipse(QPointF(r.left() + xx * W, r.top() + yy * r.height()), S(1.6) * spd, S(1.6) * spd)
        self._paint_overlay(p, r, t, live, plan)

    def _paint_map(self, p, r, mp, cam, now) -> None:
        if mp in RACE_EXTRA:                                     # 6.8: five more maps
            return _paint_race_map_extra(p, r, mp, cam, now)
        sky1, sky2, far, mid, track = RACE_SKIES[mp]
        W, H = r.width(), r.height()
        g = QLinearGradient(r.topLeft(), QPointF(r.left(), r.top() + H * 0.46))
        g.setColorAt(0, QColor(sky1))
        g.setColorAt(1, QColor(sky2))
        p.fillRect(r, g)
        if mp == "desert":                                       # a big sun
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#FFF4C9", 0.9))
            p.drawEllipse(QPointF(r.left() + W * 0.78, r.top() + H * 0.14), H * 0.08, H * 0.08)
        # far hills / dunes / mountains (slow)
        base = r.top() + H * 0.46
        off = cam * W * 0.4
        path = QPainterPath(QPointF(r.left(), base))
        for i in range(0, 41):
            x = r.left() + i * W / 20 - (off % (W / 20 * 20))
            h = (math.sin(i * 0.9 + 1) * 0.5 + 0.5) * H * (0.10 if mp == "desert" else 0.16) + H * 0.04
            if mp == "snow":
                h = abs(((i * 0.37) % 1.0) - 0.5) * H * 0.5 + H * 0.05
            path.lineTo(x, base - h)
        path.lineTo(r.right(), base)
        path.closeSubpath()
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(far))
        p.drawPath(path)
        if mp == "snow":                                         # snowy peaks
            p.setBrush(alpha("#FFFFFF", 0.6))
            p.drawPath(path.translated(0, -S(2)))
        # middle scenery (faster): cacti, trees or snowy pines
        step = W / 6
        off2 = (cam * W * 1.6) % step
        for i in range(-1, 8):
            x = r.left() + i * step - off2
            k = int((cam * W * 1.6) // step) + i
            s = 0.7 + 0.5 * ((k * 37) % 7) / 7
            y0 = base
            if mp == "desert":
                p.setBrush(QColor("#4E8A3E"))
                p.drawRoundedRect(QRectF(x - S(5) * s, y0 - S(38) * s, S(10) * s, S(38) * s), S(5) * s, S(5) * s)
                p.drawRoundedRect(QRectF(x - S(16) * s, y0 - S(28) * s, S(7) * s, S(16) * s), S(3) * s, S(3) * s)
                p.drawRoundedRect(QRectF(x + S(9) * s, y0 - S(32) * s, S(7) * s, S(18) * s), S(3) * s, S(3) * s)
            elif mp == "forest":
                p.setBrush(QColor("#5A3A22"))
                p.drawRect(QRectF(x - S(3) * s, y0 - S(18) * s, S(6) * s, S(18) * s))
                p.setBrush(QColor(mid))
                p.drawEllipse(QPointF(x, y0 - S(30) * s), S(18) * s, S(18) * s)
                p.setBrush(QColor("#3F7F3A"))
                p.drawEllipse(QPointF(x - S(8) * s, y0 - S(36) * s), S(11) * s, S(11) * s)
            else:
                p.setBrush(QColor("#2F5A46"))
                tri = QPolygonF([QPointF(x, y0 - S(46) * s), QPointF(x - S(16) * s, y0), QPointF(x + S(16) * s, y0)])
                p.drawPolygon(tri)
                p.setBrush(alpha("#FFFFFF", 0.85))
                cap = QPolygonF([QPointF(x, y0 - S(46) * s), QPointF(x - S(7) * s, y0 - S(26) * s), QPointF(x + S(7) * s, y0 - S(26) * s)])
                p.drawPolygon(cap)
        # the track
        tr_ = QRectF(r.left(), base, W, H - (base - r.top()))
        g2 = QLinearGradient(tr_.topLeft(), tr_.bottomLeft())
        g2.setColorAt(0, QColor(track).lighter(108))
        g2.setColorAt(1, QColor(track).darker(112))
        p.fillRect(tr_, g2)
        lane_h = (H * 0.50) / 5
        p.setPen(QPen(alpha("#FFFFFF", 0.22 if mp != "snow" else 0.0), S(1), Qt.PenStyle.DashLine))
        for i in range(1, 5):
            y = base + i * lane_h
            p.drawLine(QPointF(r.left(), y), QPointF(r.right(), y))
        # the rails (move with the track)
        rail = QColor("#FFFFFF") if mp != "desert" else QColor("#F4E7CF")
        p.setPen(QPen(rail, S(2.5)))
        p.drawLine(QPointF(r.left(), base - S(8)), QPointF(r.right(), base - S(8)))
        p.setPen(QPen(rail, S(2)))
        pst = W / 10
        off3 = (cam * W / RACE_VIEW) % pst
        for i in range(-1, 12):
            x = r.left() + i * pst - off3
            p.drawLine(QPointF(x, base - S(8)), QPointF(x, base))

    def _paint_overlay(self, p, r, t, live, plan) -> None:
        d = self.d
        st = d.get("state")
        now = race_now(self.ctx)

        def banner(text, sub="", col="#FFFFFF", big=30):
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#000000", 0.45))
            p.drawRoundedRect(QRectF(r.center().x() - S(150), r.top() + S(14), S(300), S(64) if sub else S(46)), S(12), S(12))
            p.setPen(QColor(col))
            p.setFont(font(big if len(text) < 6 else 15, QFont.Weight.Black, 1))
            p.drawText(QRectF(r.left(), r.top() + S(14), r.width(), S(46)), int(Qt.AlignmentFlag.AlignCenter), text)
            if sub:
                p.setPen(QColor("#FFFFFF"))
                p.setFont(font(9.5, QFont.Weight.Bold))
                p.drawText(QRectF(r.left(), r.top() + S(54), r.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter), sub)
        if st == "open":
            left = max(0.0, float(d.get("lock_at") or 0) - now)
            humans = sum(1 for b in d.get("bets") or [] if not b.get("bot"))
            banner(tr("BETS CLOSE IN {t}", t=jp_clock(left)),
                   tr("Pick a horse and bet. Bots take the empty horses at 0:00.") if humans else
                   tr("The clock restarts at 2:00 when the first player joins"), "#FFD34D", 15)
        elif st in ("live", "done") and t < 0:
            n = int(math.ceil(-t))
            if n <= 3:
                banner(str(n), "", "#FFD34D", 40)
            else:
                banner(tr("BOTS TAKE THE EMPTY HORSES"), tr("Get ready…"), "#FFFFFF", 15)
        elif live and t < 1.0:
            banner(tr("GO!"), "", "#3DDC84", 40)
        elif live and t >= RACE_ROLL + RACE_FINISH and plan["order"]:
            w = plan["order"][0]
            mine = d.get("mine")
            won = mine is not None and mine == w
            place = (plan["order"].index(mine) + 1) if mine is not None and mine in plan["order"] else 0
            sub = tr("Ridden for {who}", who=next((b.get("name") for b in d.get("bets") or [] if b.get("lane") == w), "?"))
            if won:
                text = tr("YOU WON {n}!", n=coins_text(race_my_pay(d, plan["order"])))
            elif place in (2, 3):                              # 6.4: second and third place are paid too
                text = tr("{p} PLACE: +{n}", p=tr("2ND") if place == 2 else tr("3RD"), n=coins_text(race_my_pay(d, plan["order"])))
                sub = tr("#{n} {name} WINS", n=w + 1, name=tr(HORSE_NAMES[w]).upper())
            else:
                text = tr("#{n} {name} WINS", n=w + 1, name=tr(HORSE_NAMES[w]).upper())
            banner(text, sub, "#3DDC84" if won else ("#FFD34D" if place in (2, 3) else HORSE_COLOURS[w]), 15)
        elif live and RACE_ROLL <= t < RACE_ROLL + RACE_FINISH:      # the running order, small, top left
            xs = sorted(range(5), key=lambda k: -race_pos(plan, k, t)[0])
            x0 = r.left() + S(10)
            for i, k in enumerate(xs):
                c = QPointF(x0 + i * S(22) + S(9), r.top() + S(16))
                p.setPen(QPen(QColor("#FFFFFF"), S(1.2)))
                p.setBrush(QColor(HORSE_COLOURS[k]))
                p.drawEllipse(c, S(9), S(9))
                p.setPen(QColor("#FFFFFF") if k != 3 else QColor("#1A1A1A"))
                p.setFont(font(8.5, QFont.Weight.Black))
                p.drawText(QRectF(c.x() - S(9), c.y() - S(9), S(18), S(18)), int(Qt.AlignmentFlag.AlignCenter), str(k + 1))


class RaceBoard(QWidget):
    """The big wooden board: the five horses, who rides for them, the money on each and its chance to win.
    While bets are open, a free horse can be clicked to pick it."""
    picked = pyqtSignal(int)

    def __init__(self, page, w: int) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.d: dict = {}
        self.sel = None
        self.extra = 0                                       # your bet, not placed yet: its chance is shown
        self.setFixedSize(w, int(S(54) + 5 * S(40) + S(16)))
        self.setMouseTracking(True)

    def set_data(self, d: dict) -> None:
        self.d = d or {}
        self.update()

    def _row(self, k: int) -> QRectF:
        return QRectF(S(14), S(54) + k * S(40), self.width() - S(28), S(36))

    def _free(self, k: int) -> bool:
        return self.d.get("state") == "open" and self.d.get("mine") is None and \
            not any(b.get("lane") == k for b in self.d.get("bets") or [])

    def mouseMoveEvent(self, e) -> None:
        hit = any(self._row(k).contains(e.position()) and self._free(k) for k in range(5))
        self.setCursor(Qt.CursorShape.PointingHandCursor if hit else Qt.CursorShape.ArrowCursor)

    def mouseReleaseEvent(self, e) -> None:
        for k in range(5):
            if self._row(k).contains(e.position()) and self._free(k):
                sfx.play("pick")
                self.sel = k
                self.picked.emit(k)
                self.update()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        # planks
        p.setPen(QPen(QColor("#3B2412"), S(2)))
        g = QLinearGradient(r.topLeft(), r.bottomLeft())
        g.setColorAt(0, QColor("#8A5A30"))
        g.setColorAt(1, QColor("#6A4122"))
        p.setBrush(g)
        p.drawRoundedRect(r, S(10), S(10))
        ph = r.height() / 7
        rnd = random.Random(3)
        for i in range(1, 7):
            y = r.top() + i * ph
            p.setPen(QPen(alpha("#2A170A", 0.55), S(1.4)))
            p.drawLine(QPointF(r.left() + S(4), y), QPointF(r.right() - S(4), y))
            p.setPen(QPen(alpha("#C08A55", 0.25), S(1)))
            for _j in range(3):                                # wood grain
                gy = y - ph * rnd.uniform(0.2, 0.8)
                gx = r.left() + rnd.uniform(0, r.width() * 0.7)
                p.drawLine(QPointF(gx, gy), QPointF(gx + rnd.uniform(S(30), S(120)), gy + rnd.uniform(-1, 1)))
        for cx in (r.left() + S(10), r.right() - S(10)):       # nails
            for cy in (r.top() + S(10), r.bottom() - S(10)):
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor("#C9C2B8"))
                p.drawEllipse(QPointF(cx, cy), S(3), S(3))
        d = self.d
        mp = tr(RACE_MAP_NAMES.get(d.get("map"), "")) if d.get("map") in RACE_MAP_NAMES else ""
        p.setPen(QColor("#FFE7B0"))
        p.setFont(font(15, QFont.Weight.Black, 2))
        p.drawText(QRectF(r.left(), r.top() + S(8), r.width(), S(26)), int(Qt.AlignmentFlag.AlignCenter), tr("RACE BOARD"))
        p.setFont(font(9, QFont.Weight.Bold))
        p.setPen(alpha("#FFE7B0", 0.8))
        total = int(d.get("total") or 0)
        bets = {int(b.get("lane")): b for b in d.get("bets") or []}
        extra = self.extra if self.sel is not None and self.sel not in bets else 0
        pot = total + extra
        p.drawText(QRectF(r.left(), r.top() + S(32), r.width(), S(16)), int(Qt.AlignmentFlag.AlignCenter),
                   (mp + " · " if mp else "") + tr("{n} on the horses", n=coins_text(pot)))
        winner = d.get("winner") if d.get("state") == "done" else None
        for k in range(5):
            row = self._row(k)
            b = bets.get(k)
            sel = self.sel == k and b is None
            p.setPen(QPen(QColor("#FFD34D"), S(2)) if sel or (b and b.get("me")) else Qt.PenStyle.NoPen)
            p.setBrush(alpha("#000000", 0.32 if (b or sel) else 0.18))
            p.drawRoundedRect(row, S(8), S(8))
            if winner == k:
                p.setPen(QPen(QColor("#3DDC84"), S(2.5)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawRoundedRect(row, S(8), S(8))
            c = QPointF(row.left() + S(20), row.center().y())
            p.setPen(QPen(QColor("#FFFFFF"), S(1.5)))
            p.setBrush(QColor(HORSE_COLOURS[k]))
            p.drawEllipse(c, S(13), S(13))
            p.setPen(QColor("#FFFFFF") if k != 3 else QColor("#1A1A1A"))
            p.setFont(font(12, QFont.Weight.Black))
            p.drawText(QRectF(c.x() - S(13), c.y() - S(13), S(26), S(26)), int(Qt.AlignmentFlag.AlignCenter), str(k + 1))
            p.setPen(QColor("#FFF6E0"))
            p.setFont(font(11, QFont.Weight.Black))
            nx = row.left() + S(40)
            p.drawText(QRectF(nx, row.top() + S(2), row.width() * 0.45, S(18)), int(Qt.AlignmentFlag.AlignVCenter),
                       tr(HORSE_NAMES[k]))
            p.setFont(font(9, QFont.Weight.Bold))
            if b:
                who = tr("You") if b.get("me") else str(b.get("name") or "?")
                p.setPen(QColor("#FFD34D") if b.get("me") else alpha("#FFF6E0", 0.8))
                text = who + ("  ·  BOT" if b.get("bot") else "")
            elif sel:
                p.setPen(QColor("#FFD34D"))
                text = tr("Your pick")
            else:
                p.setPen(alpha("#FFF6E0", 0.55))
                text = tr("Free: click to pick") if self._free(k) else tr("Free")
            p.drawText(QRectF(nx, row.top() + S(18), row.width() * 0.45, S(16)), int(Qt.AlignmentFlag.AlignVCenter), text)
            amt = int(b.get("amount") or 0) if b else (extra if sel else 0)
            if amt and pot:
                share = amt / pot
                p.setPen(QColor("#FFFFFF"))
                p.setFont(font(11, QFont.Weight.Black))
                p.drawText(QRectF(row.left(), row.top() + S(2), row.width() - S(10), S(18)),
                           int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter), pct(share))
                p.setFont(font(9, QFont.Weight.Bold))
                p.setPen(alpha("#FFF6E0", 0.8))
                p.drawText(QRectF(row.left(), row.top() + S(18), row.width() - S(10), S(16)),
                           int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter), coins_text(amt))
                bar = QRectF(row.left() + row.width() * 0.52, row.bottom() - S(6), row.width() * 0.30, S(3))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha("#000000", 0.35))
                p.drawRoundedRect(bar, S(1.5), S(1.5))
                p.setBrush(QColor(HORSE_COLOURS[k]))
                p.drawRoundedRect(QRectF(bar.left(), bar.top(), bar.width() * share, bar.height()), S(1.5), S(1.5))
            if b and b.get("paid"):
                p.setPen(QColor("#3DDC84"))
                p.setFont(font(9, QFont.Weight.Black))
                p.drawText(QRectF(row.left(), row.top() + S(18), row.width() * 0.80, S(16)),
                           int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter), "+" + coins_text(int(b["paid"])))


def race_my_pay(d: dict, order: list) -> int:
    """9.1: what the race pays me. The server pays when it closes the race, a moment after the finish line, so until
    then the same sum is worked out here (the bet back for 1st, 25% for 2nd, 5% for 3rd, plus 70/20/10% of the rest)."""
    if d.get("my_paid"):
        return int(d["my_paid"])
    mine = d.get("mine")
    places = list(d.get("places") or order or [])
    if mine is None or mine not in places[:3]:
        return 0
    amt = {int(b.get("lane", -1)): int(b.get("amount") or 0) for b in d.get("bets") or []}
    total = sum(amt.values())
    r1, r2, r3 = (amt.get(places[i], 0) if len(places) > i else 0 for i in range(3))
    pool = total - r1 - int(0.25 * r2) - int(0.05 * r3)
    k = places.index(mine)
    return int((1.0, 0.25, 0.05)[k] * amt.get(mine, 0)) + int((0.70, 0.20, 0.10)[k] * pool)


class HorseCard(QWidget):
    """6.3: the Horse Racing button in the Games lobby, under the Jackpot: green and running while bets are open."""

    def __init__(self, page) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedHeight(S(74))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._t = QTimer(self)
        self._t.setInterval(60)
        self._t.timeout.connect(self.update)
        if getattr(self.ctx, "race_data", None) is None:
            load_race(self.ctx)

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def mouseReleaseEvent(self, e) -> None:
        if not self.rect().contains(e.position().toPoint()):
            return
        phase, left = race_phase(self.ctx)
        if phase == "closed":                                  # 6.4: no peeking until the bets are open
            sfx.play("off")
            return self.ctx.toast(tr("The next race opens in about {t}", t=jp_words(left)), "warn")
        sfx.play("pick")
        self.page.open_sub("horses")

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        now = time.monotonic()
        phase, left = race_phase(self.ctx)
        live = phase in ("open", "running", "done")
        green = QColor("#5BE37D")
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        if live:
            g.setColorAt(0, QColor("#163A1E"))
            g.setColorAt(1, QColor("#0A160C"))
        else:
            g.setColorAt(0, QColor("#1A1C1F"))
            g.setColorAt(1, QColor("#0E0F11"))
        pulse = 0.5 + 0.5 * math.sin(now * 3)
        p.setPen(QPen(alpha(green, 0.55 + 0.35 * pulse) if live else alpha("#FFFFFF", 0.12), S(1.6)))
        p.setBrush(g)
        p.drawRoundedRect(r, S(14), S(14))
        clip = QPainterPath()
        clip.addRoundedRect(r, S(14), S(14))
        p.save()
        p.setClipPath(clip)
        p.setOpacity(1.0 if live else 0.45)
        paint_horse(p, r.left() + S(36), r.center().y() + S(2), S(40), int(now / 4) % 5 if live else 0,
                    now * 9 if live else 0.0, 1.0 if live else 0.0)
        p.restore()
        p.setPen(green if live else QColor(TEXT_FAINT))
        p.setFont(font(18, QFont.Weight.Black, 3))
        p.drawText(QRectF(r.left() + S(78), r.top() + S(10), r.width() - S(88), S(28)), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("HORSE RACING"))
        p.setFont(font(11, QFont.Weight.Bold))
        if phase == "open":
            p.setPen(QColor("#FFFFFF"))
            text = tr("OPEN · bets close in {t}", t=jp_clock(left))
        elif phase in ("running", "done"):
            p.setPen(QColor("#FFFFFF"))
            text = tr("They're racing: watch it")
        elif phase == "closed":
            p.setPen(QColor(TEXT_DIM))
            text = tr("Next race in {t}", t=jp_clock(left))
        else:
            p.setPen(QColor(TEXT_DIM))
            text = tr("5 horses, bet on one")
        p.drawText(QRectF(r.left() + S(78), r.top() + S(38), r.width() - S(88), S(22)), int(Qt.AlignmentFlag.AlignVCenter), text)


def load_race_history(ctx, then=None) -> None:
    """6.5: the finished races, newest first. Cached for a few seconds, asked again when a race has finished."""
    if getattr(ctx, "_rh_asking", False):
        return
    ctx._rh_asking = True

    def got(ok: bool, data) -> None:
        ctx._rh_asking = False
        if ok and isinstance(data, dict) and isinstance(data.get("races"), list):
            ctx.race_hist = data["races"]
            ctx.race_hist_at = time.time()
            ctx.race_hist_n = len(data["races"])
            if then:
                then()
    ctx.online.ask("rb_race_history", {"lim": 400}, got)


class RaceHistory(QWidget):
    """6.5: a trading-screen for Horse Racing, all of it read by hovering. From the top: the last winners (a disc each,
    in the winner's colour and number), the pot of every race as a price line with its moving average, a candle for
    every race (the wick runs from the smallest to the biggest bet, the body from the average bet to the winner's bet:
    green when a favourite won, red when an outsider did), the money each horse took and how often each one won.
    The cross-hair follows the mouse over everything and a card shows that race in full."""

    def __init__(self, ctx, w: int) -> None:
        super().__init__()
        self.ctx = ctx
        self.rs: list = []                                   # oldest first
        self.hover = None                                    # index into self.rs
        self.hover_x = 0.0
        self.hover_h = None                                  # a horse (its bar or its legend row)
        self.W = w
        self.setFixedWidth(w)
        self.setMouseTracking(True)
        self.set_data(getattr(ctx, "race_hist", None) or [])

    # ---- data ------------------------------------------------------------------------------------------------------
    def set_data(self, races: list) -> None:
        rs = []
        for r in reversed(races or []):
            try:
                amt = [0] * 5
                names = [""] * 5
                bots = [True] * 5
                mine = None
                paid = [0] * 5
                for b in r.get("bets") or []:
                    k = int(b.get("lane"))
                    amt[k] = int(b.get("amount") or 0)
                    names[k] = str(b.get("name") or "")
                    bots[k] = bool(b.get("bot"))
                    paid[k] = int(b.get("paid") or 0)
                    if b.get("me"):
                        mine = k
                pl = [int(x) for x in (r.get("places") or [])]
                w = int(r["winner"])
                if sorted(pl) != [0, 1, 2, 3, 4] or pl[0] != w:
                    pl = [w] + [k for k in range(5) if k != w]
                pot = int(r.get("total") or sum(amt))
                live = [a for a in amt if a > 0] or [0]
                avg = pot / max(1, len(live))
                rs.append({"t": float(r.get("t") or 0), "w": w, "pl": pl, "pot": pot, "amt": amt, "names": names,
                           "bots": bots, "paid": paid, "mine": mine, "avg": avg, "hi": max(live), "lo": min(live),
                           "wb": amt[w], "fav": max(range(5), key=lambda k: amt[k])})
            except (KeyError, TypeError, ValueError, IndexError):
                continue
        self.rs = rs
        if self.hover is not None and self.hover >= len(rs):
            self.hover = None
        self.setFixedHeight(self._layout())
        self.update()

    # ---- geometry --------------------------------------------------------------------------------------------------
    def _layout(self) -> int:
        w = self.W
        self.pad = S(12)
        self.axis = S(50)                                    # the price axis on the right
        top = S(34)
        self.disc = S(20)
        self.gap = S(5)
        per = max(1, int((w - 2 * self.pad + self.gap) // (self.disc + self.gap)))
        self.per = per
        n = len(self.rs)
        rows = max(1, min(8, -(-n // per))) if n else 1
        self.strip_n = min(n, rows * per)
        self.strip_r = QRectF(self.pad, top + S(16), w - 2 * self.pad, rows * (self.disc + self.gap))
        self.pod_n = min(n, 16)                              # 6.5: the podium of the last races, row by row
        self.pod_r = QRectF(self.pad, self.strip_r.bottom() + S(34), w - 2 * self.pad, self.pod_n * S(26))
        y = (self.pod_r.bottom() if n else self.strip_r.bottom()) + S(14)
        self.pot_r = QRectF(self.pad, y + S(14), w - 2 * self.pad - self.axis, S(150))
        y = self.pot_r.bottom() + S(22)
        self.can_r = QRectF(self.pad, y + S(14), w - 2 * self.pad - self.axis, S(120))
        y = self.can_r.bottom() + S(22)
        self.vol_r = QRectF(self.pad, y + S(14), w - 2 * self.pad - self.axis, S(56))
        y = self.vol_r.bottom() + S(22)
        self.leg_r = QRectF(self.pad, y + S(14), w - 2 * self.pad, 5 * S(26))
        return int(self.leg_r.bottom() + S(16))

    def _shown(self) -> list:
        return self.rs[-160:]

    def _xs(self, i: int, n: int, r: QRectF) -> float:
        return r.left() + (r.width() * (i + 0.5) / max(1, n))

    def _idx_at(self, x: float):
        sh = self._shown()
        if not sh:
            return None
        r = self.pot_r
        i = int((x - r.left()) / max(1.0, r.width()) * len(sh))
        off = len(self.rs) - len(sh)
        return off + max(0, min(len(sh) - 1, i))

    def _strip_idx(self, pos):
        if not self.strip_r.contains(pos):
            return None
        col = int((pos.x() - self.strip_r.left()) // (self.disc + self.gap))
        row = int((pos.y() - self.strip_r.top()) // (self.disc + self.gap))
        k = row * self.per + col
        if col >= self.per or k >= self.strip_n:
            return None
        return len(self.rs) - 1 - k

    def mouseMoveEvent(self, e) -> None:
        pos = e.position()
        old = (self.hover, self.hover_h)
        self.hover, self.hover_h = None, None
        si = self._strip_idx(pos)
        if si is None and self.pod_n and self.pod_r.contains(pos):      # a podium row
            si = len(self.rs) - 1 - int((pos.y() - self.pod_r.top()) // S(26))
        if si is not None:
            self.hover = si
            self.hover_x = -1.0
        else:
            for r in (self.pot_r, self.can_r, self.vol_r):
                if r.adjusted(0, -S(8), 0, S(8)).contains(pos):
                    self.hover = self._idx_at(pos.x())
                    self.hover_x = pos.x()
                    break
            else:
                for k in range(5):
                    if self._leg_row(k).contains(pos):
                        self.hover_h = k
        self.hover_pos = pos
        self.setCursor(Qt.CursorShape.CrossCursor if (self.hover is not None) else Qt.CursorShape.ArrowCursor)
        if old != (self.hover, self.hover_h) or self.hover is not None:
            self.update()

    def leaveEvent(self, _e) -> None:
        self.hover = self.hover_h = None
        self.update()

    def _leg_row(self, k: int) -> QRectF:
        return QRectF(self.leg_r.left(), self.leg_r.top() + k * S(26), self.leg_r.width(), S(24))

    # ---- helpers ---------------------------------------------------------------------------------------------------
    @staticmethod
    def _k(v: float) -> str:
        v = float(v)
        for lim, suf in ((1e9, "B"), (1e6, "M"), (1e3, "K")):
            if abs(v) >= lim:
                return f"{v / lim:.1f}".rstrip("0").rstrip(".") + suf
        return f"{v:.0f}"

    @staticmethod
    def _when(t: float) -> str:
        return time.strftime("%d/%m %H:%M", time.localtime(t))

    @staticmethod
    def _day(t: float) -> tuple:
        lt = time.localtime(t)
        return lt[0], lt[1], lt[2]

    def _scale(self, lo: float, hi: float):
        span = max(1.0, abs(hi) * 0.2)                    # 8.0: one race (or equal ones) still gets a readable axis
        if hi - lo < span:
            mid = (hi + lo) / 2
            lo, hi = mid - span / 2, mid + span / 2
        pad = (hi - lo) * 0.12
        return max(0.0, lo - pad), hi + pad

    def _y(self, v: float, lo: float, hi: float, r: QRectF) -> float:
        return r.bottom() - (v - lo) / max(1e-9, hi - lo) * r.height()

    def _grid(self, p: QPainter, r: QRectF, lo: float, hi: float, title: str) -> None:
        p.setPen(QPen(alpha("#FFFFFF", 0.10), 1))
        p.setBrush(alpha("#000000", 0.18))
        p.drawRoundedRect(r.adjusted(-S(4), -S(6), self.axis - S(2), S(6)), S(6), S(6))
        p.setFont(font(9.5))
        for k in range(5):
            f = k / 4
            y = r.bottom() - f * r.height()
            p.setPen(QPen(alpha("#FFFFFF", 0.07), 1, Qt.PenStyle.DashLine))
            p.drawLine(QPointF(r.left(), y), QPointF(r.right(), y))
            p.setPen(alpha(TEXT_DIM, 0.9))
            p.drawText(QRectF(r.right() + S(4), y - S(7), self.axis - S(8), S(14)),
                       int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter), self._k(lo + (hi - lo) * f))
        p.setFont(font(10.5, QFont.Weight.Bold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QPointF(r.left(), r.top() - S(12)), title)

    def _time_axis(self, p: QPainter, r: QRectF, sh: list) -> None:
        p.setFont(font(8.5))
        p.setPen(alpha(TEXT_FAINT, 1.0))
        n = len(sh)
        last_day = None
        steps = max(1, n // 5)
        for i in range(0, n, steps):
            d = self._day(sh[i]["t"])
            txt = time.strftime("%H:%M", time.localtime(sh[i]["t"]))
            if d != last_day:
                txt = time.strftime("%d/%m %H:%M", time.localtime(sh[i]["t"]))
                last_day = d
            x = self._xs(i, n, r)
            p.drawText(QRectF(x - S(34), r.bottom() + S(8), S(68), S(12)), int(Qt.AlignmentFlag.AlignHCenter), txt)

    # ---- painting --------------------------------------------------------------------------------------------------
    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w = self.width()
        p.setPen(QPen(alpha("#FFFFFF", 0.08), 1))
        p.setBrush(alpha("#0B0F10", 0.55))
        p.drawRoundedRect(QRectF(1, 1, w - 2, self.height() - 2), S(14), S(14))
        p.setPen(QColor(TEXT))
        p.setFont(font(14, QFont.Weight.Bold))
        p.drawText(QPointF(self.pad, S(24)), tr("RACE HISTORY"))
        if not self.rs:
            p.setFont(font(11))
            p.setPen(QColor(TEXT_DIM))
            p.drawText(QRectF(self.pad, S(40), w - 2 * self.pad, S(60)), int(Qt.AlignmentFlag.AlignLeft | Qt.TextFlag.TextWordWrap),
                       tr("The races will be listed here once the first one is over."))
            return
        rs, sh = self.rs, self._shown()
        off = len(rs) - len(sh)
        p.setFont(font(10))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(self.pad, S(8), w - 2 * self.pad, S(20)),
                   int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                   (tr("1 race · {c} bet in total", c=coins_text(sum(r["pot"] for r in rs))) if len(rs) == 1 else
                    tr("{n} races · {c} bet in total", n=len(rs), c=coins_text(sum(r["pot"] for r in rs)))))
        # --- the winners
        p.setFont(font(10.5, QFont.Weight.Bold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QPointF(self.pad, self.strip_r.top() - S(6)), tr("Winners, newest first"))
        for k in range(self.strip_n):
            i = len(rs) - 1 - k
            row, col = divmod(k, self.per)
            c = QPointF(self.strip_r.left() + col * (self.disc + self.gap) + self.disc / 2,
                        self.strip_r.top() + row * (self.disc + self.gap) + self.disc / 2)
            colr = QColor(HORSE_COLOURS[rs[i]["w"]])
            hot = (self.hover == i)
            g = QRadialGradient(QPointF(c.x() - self.disc * 0.15, c.y() - self.disc * 0.2), self.disc * 0.7)
            g.setColorAt(0, mix(colr, QColor("#FFFFFF"), 0.45))
            g.setColorAt(1, mix(colr, QColor("#000000"), 0.2))
            p.setBrush(g)
            p.setPen(QPen(QColor("#FFFFFF") if hot else QColor("#FFD34D"), S(2) if hot else S(1.6)))
            p.drawEllipse(c, self.disc / 2 - (0 if hot else 1), self.disc / 2 - (0 if hot else 1))
            if rs[i]["mine"] is not None and rs[i]["paid"][rs[i]["mine"]] > 0:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor("#FFD34D"))
                p.drawEllipse(QPointF(c.x() + self.disc * 0.38, c.y() - self.disc * 0.38), S(3), S(3))
            p.setPen(QColor("#10161A"))
            p.setFont(font(11, QFont.Weight.Black))
            p.drawText(QRectF(c.x() - self.disc / 2, c.y() - self.disc / 2, self.disc, self.disc), int(Qt.AlignmentFlag.AlignCenter),
                       str(rs[i]["w"] + 1))
        n = len(sh)
        # --- the podium: first, second and third of the last races, row by row
        if self.pod_n:
            medal = ("#FFD34D", "#D5DCE3", "#D68A4B")
            names = (tr("1st"), tr("2nd"), tr("3rd"))
            top = self.pod_r.top() - S(24)
            p.setFont(font(10.5, QFont.Weight.Bold))
            p.setPen(QColor(TEXT_DIM))
            p.drawText(QPointF(self.pad, top + S(8)), tr("Podium of the last races"))
            colx = [self.pod_r.left() + S(78) + k * S(86) for k in range(3)]
            p.setFont(font(9.5, QFont.Weight.Bold))
            for k in range(3):
                p.setPen(QColor(medal[k]))
                p.drawText(QPointF(colx[k] + S(2), top + S(21)), names[k])
            p.setPen(QColor(TEXT_FAINT))
            p.drawText(QRectF(self.pod_r.right() - S(70), top + S(10), S(70), S(14)), int(Qt.AlignmentFlag.AlignRight), tr("Pot"))
            for row in range(self.pod_n):
                i = len(rs) - 1 - row
                x = rs[i]
                rr = QRectF(self.pod_r.left(), self.pod_r.top() + row * S(26), self.pod_r.width(), S(24))
                if self.hover == i:
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(alpha("#FFFFFF", 0.09))
                    p.drawRoundedRect(rr, S(6), S(6))
                elif row % 2 == 0:
                    p.setPen(Qt.PenStyle.NoPen)
                    p.setBrush(alpha("#FFFFFF", 0.03))
                    p.drawRoundedRect(rr, S(6), S(6))
                p.setPen(QColor(TEXT_DIM))
                p.setFont(font(9.5))
                p.drawText(QRectF(rr.left() + S(4), rr.top(), S(72), rr.height()), int(Qt.AlignmentFlag.AlignVCenter), self._when(x["t"]))
                for k in range(3):
                    lane = x["pl"][k]
                    c = QPointF(colx[k] + S(10), rr.center().y())
                    d = S(10) if k == 0 else S(9)
                    p.setPen(QPen(QColor(medal[k]), S(2.4) if k == 0 else S(1.8)))
                    p.setBrush(QColor(HORSE_COLOURS[lane]))
                    p.drawEllipse(c, d, d)
                    p.setPen(QColor("#10161A"))
                    p.setFont(font(10.5 if k == 0 else 9.5, QFont.Weight.Black))
                    p.drawText(QRectF(c.x() - d, c.y() - d, 2 * d, 2 * d), int(Qt.AlignmentFlag.AlignCenter), str(lane + 1))
                    mine = x["mine"] == lane
                    if mine:
                        p.setPen(Qt.PenStyle.NoPen)
                        p.setBrush(QColor("#FFFFFF"))
                        p.drawEllipse(QPointF(c.x() + d * 0.85, c.y() - d * 0.85), S(2.6), S(2.6))
                    p.setPen(QColor(medal[k]))
                    p.setFont(font(9, QFont.Weight.Bold))
                    p.drawText(QRectF(c.x() + d + S(3), rr.top(), S(40), rr.height()), int(Qt.AlignmentFlag.AlignVCenter), self._k(x["amt"][lane]))
                p.setPen(QColor("#5BE37D"))
                p.setFont(font(9.5, QFont.Weight.Bold))
                p.drawText(QRectF(rr.right() - S(70), rr.top(), S(66), rr.height()),
                           int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter), self._k(x["pot"]))
        # --- 1. the pot as a price line
        pots = [r["pot"] for r in sh]
        lo, hi = self._scale(min(pots), max(pots))
        r = self.pot_r
        self._grid(p, r, lo, hi, tr("Pot of each race"))
        pts = [QPointF(self._xs(i, n, r), self._y(v, lo, hi, r)) for i, v in enumerate(pots)]
        area = QPainterPath(QPointF(pts[0].x(), r.bottom()))
        for q in pts:
            area.lineTo(q)
        area.lineTo(QPointF(pts[-1].x(), r.bottom()))
        area.closeSubpath()
        g = QLinearGradient(r.topLeft(), r.bottomLeft())
        g.setColorAt(0, alpha("#5BE37D", 0.38))
        g.setColorAt(1, alpha("#5BE37D", 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawPath(area)
        line = QPainterPath(pts[0])
        for q in pts[1:]:
            line.lineTo(q)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QColor("#5BE37D"), S(1.6), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(line)
        win = 5                                              # the moving average of the last 5 races
        if n >= 3:
            ma = QPainterPath()
            for i in range(n):
                seg = pots[max(0, i - win + 1): i + 1]
                q = QPointF(pts[i].x(), self._y(sum(seg) / len(seg), lo, hi, r))
                ma.moveTo(q) if i == 0 else ma.lineTo(q)
            p.setPen(QPen(QColor("#FFC94D"), S(1.3), Qt.PenStyle.DashLine))
            p.drawPath(ma)
        # the highest and lowest pot, marked on the line
        ihi, ilo = max(range(n), key=lambda k: pots[k]), min(range(n), key=lambda k: pots[k])
        p.setFont(font(9, QFont.Weight.Bold))
        for ix, txt, col in ((ihi, tr("HIGH {v}", v=self._k(pots[ihi])), "#5BE37D"), (ilo, tr("LOW {v}", v=self._k(pots[ilo])), "#FF6B6B")):
            if ix == ihi and ix == ilo:
                continue
            q = pts[ix]
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(col))
            p.drawEllipse(q, S(3), S(3))
            p.setPen(QColor(col))
            tw = p.fontMetrics().horizontalAdvance(txt)
            x = min(max(q.x() - tw / 2, r.left()), r.right() - tw)
            p.drawText(QPointF(x, q.y() + (-S(7) if ix == ihi else S(15))), txt)
        for i, q in enumerate(pts):                          # one dot per race, in the winner's colour
            p.setPen(QPen(alpha("#000000", 0.5), 1))
            p.setBrush(QColor(HORSE_COLOURS[sh[i]["w"]]))
            p.drawEllipse(q, S(2.6) if n < 80 else S(1.8), S(2.6) if n < 80 else S(1.8))
        lastv = pots[-1]
        yl = self._y(lastv, lo, hi, r)
        p.setPen(QPen(alpha("#5BE37D", 0.8), 1, Qt.PenStyle.DotLine))
        p.drawLine(QPointF(r.left(), yl), QPointF(r.right(), yl))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#5BE37D"))
        p.drawRoundedRect(QRectF(r.right() + S(2), yl - S(7), self.axis - S(6), S(14)), S(4), S(4))
        p.setPen(QColor("#06210F"))
        p.setFont(font(9, QFont.Weight.Bold))
        p.drawText(QRectF(r.right() + S(2), yl - S(7), self.axis - S(6), S(14)), int(Qt.AlignmentFlag.AlignCenter), self._k(lastv))
        self._time_axis(p, r, sh)
        # --- 2. a candle for every race
        r = self.can_r
        lo2, hi2 = self._scale(min(x["lo"] for x in sh), max(x["hi"] for x in sh))
        self._grid(p, r, lo2, hi2, tr("Bets: smallest to biggest · average to the winner's"))
        cw = max(1.5, min(S(12), r.width() / n * 0.62))
        for i, x in enumerate(sh):
            cx = self._xs(i, n, r)
            up = x["wb"] >= x["avg"]
            col = QColor("#3DDC84" if up else "#FF5C5C")
            p.setPen(QPen(col, 1))
            p.drawLine(QPointF(cx, self._y(x["hi"], lo2, hi2, r)), QPointF(cx, self._y(x["lo"], lo2, hi2, r)))
            y1, y2 = self._y(x["avg"], lo2, hi2, r), self._y(x["wb"], lo2, hi2, r)
            p.setBrush(col if not up else alpha(col, 0.85))
            p.drawRect(QRectF(cx - cw / 2, min(y1, y2), cw, max(1.5, abs(y1 - y2))))
        self._time_axis(p, r, sh)
        # --- 3. the money on each horse: stacked bars
        r = self.vol_r
        tops = [sum(x["amt"]) for x in sh]
        lo3, hi3 = 0.0, max(tops) * 1.1
        self._grid(p, r, lo3, hi3, tr("Money on each horse"))
        bw = max(1.5, r.width() / n * 0.74)
        for i, x in enumerate(sh):
            cx = self._xs(i, n, r)
            yb = r.bottom()
            for k in range(5):
                hgt = x["amt"][k] / max(1e-9, hi3) * r.height()
                col = QColor(HORSE_COLOURS[k])
                if k == x["w"]:
                    col = mix(col, QColor("#FFFFFF"), 0.25)
                else:
                    col.setAlphaF(0.55)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(col)
                p.drawRect(QRectF(cx - bw / 2, yb - hgt, bw, hgt))
                yb -= hgt
        # --- 4. the horses: wins, share, pot won
        wins = [0] * 5
        took = [0] * 5
        for x in rs:
            wins[x["w"]] += 1
            for k in range(5):
                took[k] += x["amt"][k]
        p.setFont(font(10.5, QFont.Weight.Bold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QPointF(self.pad, self.leg_r.top() - S(6)), tr("Wins by horse, all {n} races", n=len(rs)) if len(rs) != 1 else tr("Wins by horse, 1 race"))
        topw = max(max(wins), 1)
        for k in range(5):
            rr = self._leg_row(k)
            hot = self.hover_h == k
            if hot:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha("#FFFFFF", 0.07))
                p.drawRoundedRect(rr, S(6), S(6))
            c = QPointF(rr.left() + S(12), rr.center().y())
            p.setPen(QPen(alpha("#000000", 0.5), 1))
            p.setBrush(QColor(HORSE_COLOURS[k]))
            p.drawEllipse(c, S(9), S(9))
            p.setPen(QColor("#10161A"))
            p.setFont(font(10.5, QFont.Weight.Black))
            p.drawText(QRectF(c.x() - S(9), c.y() - S(9), S(18), S(18)), int(Qt.AlignmentFlag.AlignCenter), str(k + 1))
            p.setPen(QColor(TEXT))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            p.drawText(QRectF(rr.left() + S(28), rr.top(), S(100), rr.height()), int(Qt.AlignmentFlag.AlignVCenter), tr(HORSE_NAMES[k]))
            bx = rr.left() + S(128)
            bwid = rr.right() - bx - S(92)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#FFFFFF", 0.07))
            p.drawRoundedRect(QRectF(bx, rr.center().y() - S(4), bwid, S(8)), S(4), S(4))
            p.setBrush(QColor(HORSE_COLOURS[k]))
            p.drawRoundedRect(QRectF(bx, rr.center().y() - S(4), max(S(3), bwid * wins[k] / topw), S(8)), S(4), S(4))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10))
            p.drawText(QRectF(rr.right() - S(88), rr.top(), S(88), rr.height()),
                       int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                       f"{wins[k]} · {100 * wins[k] / max(1, len(rs)):.0f}%")
        # --- the cross-hair and the card
        if self.hover is not None and 0 <= self.hover < len(rs):
            i = self.hover - off
            x = rs[self.hover]
            if 0 <= i < n:
                cx = self._xs(i, n, self.pot_r)
                p.setPen(QPen(alpha("#FFFFFF", 0.55), 1, Qt.PenStyle.DashLine))
                for rr in (self.pot_r, self.can_r, self.vol_r):
                    p.drawLine(QPointF(cx, rr.top() - S(6)), QPointF(cx, rr.bottom() + S(6)))
                yv = self._y(x["pot"], lo, hi, self.pot_r)
                p.drawLine(QPointF(self.pot_r.left(), yv), QPointF(self.pot_r.right(), yv))
                p.setPen(QPen(QColor("#FFFFFF"), S(1.6)))
                p.setBrush(QColor(HORSE_COLOURS[x["w"]]))
                p.drawEllipse(QPointF(cx, yv), S(5), S(5))
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(QColor("#FFFFFF"))
                p.drawRoundedRect(QRectF(self.pot_r.right() + S(2), yv - S(7), self.axis - S(6), S(14)), S(4), S(4))
                p.setPen(QColor("#10161A"))
                p.setFont(font(9, QFont.Weight.Bold))
                p.drawText(QRectF(self.pot_r.right() + S(2), yv - S(7), self.axis - S(6), S(14)), int(Qt.AlignmentFlag.AlignCenter),
                           self._k(x["pot"]))
            self._card(p, x, rs)
        elif self.hover_h is not None:
            self._horse_card(p, self.hover_h, rs)
        p.end()

    def _lines(self, x: dict, rs: list) -> list:
        """[(text, colour, bold)] for one race."""
        day = self._day(x["t"])
        same = [y for y in rs if self._day(y["t"]) == day]
        pots = [y["pot"] for y in same]
        w = x["w"]
        mult = (x["paid"][w] / x["amt"][w]) if x["amt"][w] and x["paid"][w] else 0
        out = [(tr("#{n} {name} won", n=w + 1, name=tr(HORSE_NAMES[w])), HORSE_COLOURS[w], True),
               (self._when(x["t"]), TEXT_DIM, False),
               (tr("1st #{a} · 2nd #{b} · 3rd #{c}", a=x["pl"][0] + 1, b=x["pl"][1] + 1, c=x["pl"][2] + 1), TEXT, False),
               (tr("Pot {v}", v=coins_text(x["pot"])), "#5BE37D", True),
               (tr("Biggest bet {a} · smallest {b}", a=coins_text(x["hi"]), b=coins_text(x["lo"])), TEXT, False),
               (tr("Average bet {a} · winner's {b}", a=coins_text(int(x["avg"])), b=coins_text(x["wb"])),
                "#3DDC84" if x["wb"] >= x["avg"] else "#FF5C5C", False),
               (tr("Favourite: #{n} ({v}){s}", n=x["fav"] + 1, v=coins_text(x["amt"][x["fav"]]),
                   s=tr(" · it won") if x["fav"] == w else tr(" · UPSET")), "#FFC94D" if x["fav"] != w else TEXT_DIM, x["fav"] != w),
               (tr("That day: {n} races · pot high {a} · low {b}", n=len(same), a=self._k(max(pots)), b=self._k(min(pots))), TEXT_DIM, False)]
        places = (tr("1st"), tr("2nd"), tr("3rd"), tr("4th"), tr("5th"))
        for pi, k in enumerate(x["pl"]):
            nm = x["names"][k] or "?"
            out.append((f"{places[pi]}  #{k + 1} {nm}{' ★' if x['mine'] == k else ''}: {coins_text(x['amt'][k])}"
                        + (f" → {coins_text(x['paid'][k])}" if x["paid"][k] else ""),
                        ("#FFD34D", "#D5DCE3", "#D68A4B")[pi] if pi < 3 else TEXT_FAINT, x["mine"] == k or pi == 0))
        if mult:
            out.append((tr("Winner's pay: ×{m}", m=f"{mult:.2f}"), "#FFD34D", False))
        return out

    def _card_at(self, p: QPainter, lines: list, pos: QPointF) -> None:
        p.setFont(font(10.5))
        fm = p.fontMetrics()
        cw = min(self.width() - S(16), max(fm.horizontalAdvance(t) for t, _c, _b in lines) + S(22))
        ch = len(lines) * S(16) + S(14)
        x = pos.x() + S(16)
        if x + cw > self.width() - S(6):
            x = pos.x() - cw - S(16)
        x = max(S(6), min(self.width() - cw - S(6), x))
        y = max(S(6), min(self.height() - ch - S(6), pos.y() - ch / 2))
        p.setPen(QPen(alpha("#FFFFFF", 0.25), 1))
        p.setBrush(alpha("#0B1012", 0.96))
        p.drawRoundedRect(QRectF(x, y, cw, ch), S(8), S(8))
        for j, (t, c, b) in enumerate(lines):
            p.setFont(font(10.5, QFont.Weight.Bold if b else QFont.Weight.Normal))
            p.setPen(QColor(c))
            p.drawText(QRectF(x + S(10), y + S(7) + j * S(16), cw - S(14), S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                       p.fontMetrics().elidedText(t, Qt.TextElideMode.ElideRight, int(cw - S(16))))

    def _card(self, p: QPainter, x: dict, rs: list) -> None:
        self._card_at(p, self._lines(x, rs), getattr(self, "hover_pos", QPointF(self.width() / 2, self.height() / 2)))

    def _horse_card(self, p: QPainter, k: int, rs: list) -> None:
        wins = [x for x in rs if x["w"] == k]
        seconds = sum(1 for x in rs if x["pl"][1] == k)
        thirds = sum(1 for x in rs if x["pl"][2] == k)
        took = [x["amt"][k] for x in rs if x["amt"][k]]
        streak = best = 0
        for x in rs:
            streak = streak + 1 if x["w"] == k else 0
            best = max(best, streak)
        cur = 0
        for x in reversed(rs):
            if x["w"] != k:
                break
            cur += 1
        lines = [(f"#{k + 1} {tr(HORSE_NAMES[k])}", HORSE_COLOURS[k], True),
                 (tr("{a} wins · {b} second · {c} third", a=len(wins), b=seconds, c=thirds), TEXT, False),
                 (tr("Win rate {p}% (fair: 20%)", p=f"{100 * len(wins) / max(1, len(rs)):.1f}"), TEXT, False),
                 (tr("Best streak {n} · now {m}", n=best, m=cur), TEXT_DIM, False),
                 (tr("Average bet on it {v}", v=coins_text(int(sum(took) / max(1, len(took))))), TEXT_DIM, False),
                 (tr("Biggest bet on it {v}", v=coins_text(max(took) if took else 0)), TEXT_DIM, False),
                 (tr("Biggest pot it won {v}", v=coins_text(max((x["pot"] for x in wins), default=0))), "#5BE37D", False)]
        self._card_at(p, lines, getattr(self, "hover_pos", QPointF(self.width() / 2, self.height() / 2)))


def add_race_history(page, lay) -> None:
    """6.5: the history under the Horse Racing menu: asked now, and again every 15 seconds (cheap and cached)."""
    ctx = page.ctx
    view = RaceHistory(ctx, page.W)
    page._race_hist = view

    def fresh() -> None:
        try:
            view.set_data(ctx.race_hist)
        except RuntimeError:
            pass

    def tick() -> None:
        if time.time() - float(getattr(ctx, "race_hist_at", 0) or 0) > 14:
            load_race_history(ctx, fresh)
        elif getattr(ctx, "race_hist_n", None) != len(view.rs):
            fresh()
    lay.addWidget(view)
    lay.addWidget(_Poll(5000, tick))


_GAME_NAMES = {"plinko": "Plinko", "blackjack": "Blackjack", "slots": "Slots", "wave": "Wave Rush", "dice": "Dice", "tower": "Tower",
               "mines": "Mines", "sweeper": "Sweeper", "rocket": "Rocket", "timing": "Timing", "cups": "Cups", "c4": "Connect 4",
               "roulette": "Roulette", "hilo": "Hi-Lo", "daily": "Daily reward", "spin": "Free Spin", "colour": "Colour game",
               "sfx": "Sound game", "golf_party": "Mini Golf", "golf_solo": "Mini Golf", "scratch": "Scratch card",
               "horses": "Horse Racing", "park": "Parking", "blocks": "Blocks", "gold_wheel": "Gold Wheel", "memory": "Memory",
               "mini": "Beat Tap", "jackpot": "Jackpot", "flip": "Coinflip", "coinflip": "Coinflip", "reversi": "Reversi",
               "ships": "Battleships", "arena": "Arena duel"}
for _gen, _gfr in (("Plinko", "Plinko"), ("Blackjack", "Blackjack"), ("Slots", "Machine à sous"), ("Wave Rush", "Wave Rush"), ("Dice", "Dés"),
                 ("Tower", "Tour"), ("Mines", "Mines"), ("Sweeper", "Démineur"), ("Rocket", "Fusée"), ("Timing", "Timing"),
                 ("Cups", "Gobelets"), ("Connect 4", "Puissance 4"), ("Roulette", "Roulette"), ("Hi-Lo", "Plus ou moins"),
                 ("Daily reward", "Récompense du jour"), ("Free Spin", "Tour gratuit"), ("Colour game", "Jeu des couleurs"),
                 ("Sound game", "Jeu des sons"), ("Mini Golf", "Mini-golf"), ("Scratch card", "Carte à gratter"),
                 ("Horse Racing", "Course de chevaux"), ("Parking", "Parking"), ("Blocks", "Blocs"), ("Gold Wheel", "Roue en or"),
                 ("Memory", "Mémoire"), ("Beat Tap", "Beat Tap"), ("Jackpot", "Jackpot"), ("Coinflip", "Pile ou face"), ("Cases", "Caisses")):
    FR.setdefault(_gen, _gfr)


def game_label(g: str) -> str:
    if g.startswith("case:"):
        return "Cases"
    return _GAME_NAMES.get(g, g.replace("_", " ").capitalize())


def load_play_history(ctx, name: str, then=None) -> None:
    """6.6: all the finished rounds of a player, newest first (cached 30 s per player)."""
    key = (name or "").lower()
    if getattr(ctx, "_ph_asking", None) == key:
        return
    ctx._ph_asking = key

    def got(ok: bool, data) -> None:
        if getattr(ctx, "_ph_asking", None) == key:
            ctx._ph_asking = None
        if ok and isinstance(data, dict) and isinstance(data.get("rounds"), list):
            cache = getattr(ctx, "play_hist", None)
            if cache is None:
                cache = ctx.play_hist = {}
            cache[key] = (time.time(), data["rounds"])
            if then:
                then()
    ctx.online.ask("rb_play_history", {"name": name, "lim": 1500}, got)


class PlayHistory(RaceHistory):
    """6.6: a trading screen for a player: every round of every game. Hover anywhere: the net coins over time, the result
    of each round, the win rate, each day and each game. Green is a win, red a loss, grey an even round."""
    WIN, LOSS, EVEN = "#3DDC84", "#FF5C5C", "#8C969A"

    def __init__(self, ctx, w: int, rounds: list) -> None:
        self.ctx = ctx
        self.hover_day = None
        self.hover_g = None
        super().__init__(ctx, w)
        self.set_data(rounds)

    # ---- data ----------------------------------------------------------------------------------------------------------
    def set_data(self, rounds: list) -> None:
        rs = []
        for r in reversed(rounds or []):
            try:
                b, p = int(r.get("b") or 0), int(r.get("p") or 0)
                g = str(r.get("g") or "?")
                rs.append({"t": float(r.get("t") or 0), "g": g, "gl": game_label(g), "b": b, "p": p, "net": p - b,
                           "res": 1 if p > b else (-1 if p < b else 0)})
            except (TypeError, ValueError):
                continue
        self.rs = rs
        days: dict = {}
        for x in rs:
            d = days.setdefault(self._day(x["t"]), {"t": x["t"], "n": 0, "w": 0, "l": 0, "b": 0, "p": 0, "best": 0, "worst": 0, "g": {}})
            d["n"] += 1
            d["w"] += x["res"] > 0
            d["l"] += x["res"] < 0
            d["b"] += x["b"]
            d["p"] += x["p"]
            d["best"] = max(d["best"], x["net"])
            d["worst"] = min(d["worst"], x["net"])
            d["g"][x["gl"]] = d["g"].get(x["gl"], 0) + 1
        self.days = [days[k] for k in sorted(days)][-45:]
        games: dict = {}
        for x in rs:
            q = games.setdefault(x["gl"], {"name": x["gl"], "n": 0, "w": 0, "l": 0, "e": 0, "b": 0, "p": 0, "best": 0, "worst": 0,
                                           "streak": 0, "cur": 0})
            q["n"] += 1
            q["w"] += x["res"] > 0
            q["l"] += x["res"] < 0
            q["e"] += x["res"] == 0
            q["b"] += x["b"]
            q["p"] += x["p"]
            q["best"] = max(q["best"], x["net"])
            q["worst"] = min(q["worst"], x["net"])
            q["cur"] = q["cur"] + 1 if x["res"] > 0 else 0
            q["streak"] = max(q["streak"], q["cur"])
        self.games = sorted(games.values(), key=lambda q: -q["n"])[:16]
        self.hover = self.hover_day = self.hover_g = None
        self.setFixedHeight(self._layout())
        self.update()

    # ---- geometry ----------------------------------------------------------------------------------------------------
    def _layout(self) -> int:
        w = self.W
        self.pad, self.axis = S(12), S(50)
        self.disc, self.gap = S(12), S(4)
        self.per = max(1, int((w - 2 * self.pad + self.gap) // (self.disc + self.gap)))
        n = len(self.rs)
        rows = max(1, min(6, -(-n // self.per))) if n else 1
        self.strip_n = min(n, rows * self.per)
        self.sum_r = QRectF(self.pad, S(36), w - 2 * self.pad, S(58))
        self.strip_r = QRectF(self.pad, self.sum_r.bottom() + S(26), w - 2 * self.pad, rows * (self.disc + self.gap))
        cw = w - 2 * self.pad - self.axis
        y = self.strip_r.bottom() + S(8)
        rects = []
        for hgt in (130, 90, 90, 90):
            r = QRectF(self.pad, y + S(22), cw, S(hgt))
            rects.append(r)
            y = r.bottom() + S(24)
        self.pot_r, self.can_r, self.vol_r, self.day_r = rects
        self.leg_r = QRectF(self.pad, y + S(22), w - 2 * self.pad, max(1, len(self.games)) * S(26))
        return int(self.leg_r.bottom() + S(16))

    def _shown(self) -> list:
        return self.rs[-240:]

    def _leg_row(self, k: int) -> QRectF:
        return QRectF(self.leg_r.left(), self.leg_r.top() + k * S(26), self.leg_r.width(), S(24))

    def mouseMoveEvent(self, e) -> None:
        pos = e.position()
        self.hover = self.hover_day = self.hover_g = None
        si = self._strip_idx(pos)
        if si is not None:
            self.hover, self.hover_x = si, -1.0
        else:
            for r in (self.pot_r, self.can_r, self.vol_r):
                if r.adjusted(0, -S(8), 0, S(8)).contains(pos):
                    self.hover, self.hover_x = self._idx_at(pos.x()), pos.x()
                    break
            else:
                if self.day_r.adjusted(0, -S(8), 0, S(8)).contains(pos) and self.days:
                    i = int((pos.x() - self.day_r.left()) / max(1.0, self.day_r.width()) * len(self.days))
                    self.hover_day = max(0, min(len(self.days) - 1, i))
                else:
                    for k in range(len(self.games)):
                        if self._leg_row(k).contains(pos):
                            self.hover_g = k
        self.hover_pos = pos
        self.setCursor(Qt.CursorShape.CrossCursor if (self.hover is not None or self.hover_day is not None) else Qt.CursorShape.ArrowCursor)
        self.update()

    def leaveEvent(self, _e) -> None:
        self.hover = self.hover_day = self.hover_g = None
        self.update()

    def _idx_at(self, x: float):
        sh = self._shown()
        if not sh:
            return None
        i = int((x - self.pot_r.left()) / max(1.0, self.pot_r.width()) * len(sh))
        return len(self.rs) - len(sh) + max(0, min(len(sh) - 1, i))

    @staticmethod
    def _sg(v: int) -> str:
        return ("+" if v > 0 else "−" if v < 0 else "") + coins_text(abs(int(v)))

    def _col(self, res: int) -> str:
        return self.WIN if res > 0 else self.LOSS if res < 0 else self.EVEN

    # ---- painting ----------------------------------------------------------------------------------------------------
    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w = self.width()
        p.setPen(QPen(alpha("#FFFFFF", 0.08), 1))
        p.setBrush(alpha("#0B0F10", 0.55))
        p.drawRoundedRect(QRectF(1, 1, w - 2, self.height() - 2), S(14), S(14))
        p.setPen(QColor(TEXT))
        p.setFont(font(14, QFont.Weight.Bold))
        p.drawText(QPointF(self.pad, S(24)), tr("PLAY HISTORY"))
        rs = self.rs
        if not rs:
            p.setFont(font(11))
            p.setPen(QColor(TEXT_DIM))
            p.drawText(QRectF(self.pad, S(40), w - 2 * self.pad, S(60)), int(Qt.AlignmentFlag.AlignLeft | Qt.TextFlag.TextWordWrap),
                       tr("Every round of every game will be drawn here."))
            return
        wins, losses = sum(x["res"] > 0 for x in rs), sum(x["res"] < 0 for x in rs)
        bet, paid = sum(x["b"] for x in rs), sum(x["p"] for x in rs)
        net = paid - bet
        p.setFont(font(10))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(self.pad, S(8), w - 2 * self.pad, S(20)), int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                   tr("{n} rounds · {p}% won", n=len(rs), p=f"{100 * wins / max(1, len(rs)):.0f}"))
        # --- the numbers
        best = max(rs, key=lambda x: x["net"])
        worst = min(rs, key=lambda x: x["net"])
        cells = [(tr("Net result"), self._sg(net), self._col(1 if net > 0 else -1 if net < 0 else 0)),
                 (tr("Won / lost"), f"{wins} / {losses}", TEXT), (tr("Total bet"), coins_text(bet), TEXT),
                 (tr("Total paid"), coins_text(paid), TEXT), (tr("Best round"), self._sg(best["net"]), self.WIN),
                 (tr("Worst round"), self._sg(worst["net"]), self.LOSS)]
        cw3 = self.sum_r.width() / 3
        for i, (head, val, col) in enumerate(cells):
            bx = QRectF(self.sum_r.left() + (i % 3) * cw3, self.sum_r.top() + (i // 3) * S(29), cw3, S(29))
            p.setFont(font(9))
            p.setPen(QColor(TEXT_FAINT))
            p.drawText(QRectF(bx.left(), bx.top(), bx.width(), S(12)), int(Qt.AlignmentFlag.AlignLeft), head)
            p.setFont(font(12, QFont.Weight.Bold))
            p.setPen(QColor(col))
            p.drawText(QRectF(bx.left(), bx.top() + S(12), bx.width(), S(16)), int(Qt.AlignmentFlag.AlignLeft), val)
        # --- the strip
        p.setFont(font(10.5, QFont.Weight.Bold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QPointF(self.pad, self.strip_r.top() - S(8)), tr("Rounds, newest first"))
        for k in range(self.strip_n):
            i = len(rs) - 1 - k
            row, col = divmod(k, self.per)
            c = QPointF(self.strip_r.left() + col * (self.disc + self.gap) + self.disc / 2,
                        self.strip_r.top() + row * (self.disc + self.gap) + self.disc / 2)
            hot = self.hover == i
            p.setPen(QPen(QColor("#FFFFFF") if hot else alpha("#000000", 0.4), S(1.6) if hot else 1))
            p.setBrush(QColor(self._col(rs[i]["res"])))
            p.drawEllipse(c, self.disc / 2 - 0.5, self.disc / 2 - 0.5)
        sh = self._shown()
        n = len(sh)
        off = len(rs) - n
        cum, run = [], 0
        for x in sh:
            run += x["net"]
            cum.append(run)
        # --- A. net coins over time
        r = self.pot_r
        lo, hi = self._scale(min(0, min(cum)), max(0, max(cum)))
        self._grid(p, r, lo, hi, tr("Net coins over time (last {n} rounds)", n=n))
        yz = self._y(0, lo, hi, r)
        pts = [QPointF(self._xs(i, n, r), self._y(v, lo, hi, r)) for i, v in enumerate(cum)]
        path = QPainterPath(pts[0])
        for q in pts[1:]:
            path.lineTo(q)
        area = QPainterPath(QPointF(pts[0].x(), yz))
        for q in pts:
            area.lineTo(q)
        area.lineTo(QPointF(pts[-1].x(), yz))
        area.closeSubpath()
        for col, clip in ((self.WIN, QRectF(r.left(), r.top() - S(10), r.width(), yz - r.top() + S(10))),
                          (self.LOSS, QRectF(r.left(), yz, r.width(), r.bottom() - yz + S(10)))):
            p.save()
            p.setClipRect(clip)
            g = QLinearGradient(QPointF(0, yz), QPointF(0, r.top() if col == self.WIN else r.bottom()))
            g.setColorAt(0, alpha(col, 0.0))
            g.setColorAt(1, alpha(col, 0.40))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(g)
            p.drawPath(area)
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.setPen(QPen(QColor(col), S(1.6), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.drawPath(path)
            p.restore()
        p.setPen(QPen(alpha("#FFFFFF", 0.4), 1, Qt.PenStyle.DashLine))
        p.drawLine(QPointF(r.left(), yz), QPointF(r.right(), yz))
        lastc = self.WIN if cum[-1] >= 0 else self.LOSS
        yl = self._y(cum[-1], lo, hi, r)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(lastc))
        p.drawRoundedRect(QRectF(r.right() + S(2), yl - S(7), self.axis - S(6), S(14)), S(4), S(4))
        p.setPen(QColor("#06210F"))
        p.setFont(font(9, QFont.Weight.Bold))
        p.drawText(QRectF(r.right() + S(2), yl - S(7), self.axis - S(6), S(14)), int(Qt.AlignmentFlag.AlignCenter), self._k(cum[-1]))
        self._time_axis(p, r, sh)
        # --- B. the result of each round
        r = self.can_r
        m = max(1, max(abs(x["net"]) for x in sh))
        self._grid(p, r, -m * 1.1, m * 1.1, tr("Coins won or lost in each round"))
        yz = self._y(0, -m * 1.1, m * 1.1, r)
        bw = max(1.5, min(S(10), r.width() / n * 0.7))
        p.setPen(Qt.PenStyle.NoPen)
        for i, x in enumerate(sh):
            cx = self._xs(i, n, r)
            y2 = self._y(x["net"], -m * 1.1, m * 1.1, r)
            p.setBrush(QColor(self._col(x["res"])))
            p.drawRect(QRectF(cx - bw / 2, min(yz, y2), bw, max(1.2, abs(yz - y2))))
        p.setPen(QPen(alpha("#FFFFFF", 0.4), 1))
        p.drawLine(QPointF(r.left(), yz), QPointF(r.right(), yz))
        self._time_axis(p, r, sh)
        # --- C. the win rate over the last 20 rounds
        r = self.vol_r
        self._grid(p, r, 0, 100, tr("Win rate (last 20 rounds, %)"))
        wr = []
        for i in range(n):
            seg = rs[max(0, off + i - 19): off + i + 1]
            wr.append(100 * sum(x["res"] > 0 for x in seg) / len(seg))
        pts = [QPointF(self._xs(i, n, r), self._y(v, 0, 100, r)) for i, v in enumerate(wr)]
        p.setPen(QPen(alpha("#FFFFFF", 0.3), 1, Qt.PenStyle.DashLine))
        p.drawLine(QPointF(r.left(), self._y(50, 0, 100, r)), QPointF(r.right(), self._y(50, 0, 100, r)))
        line = QPainterPath(pts[0])
        for q in pts[1:]:
            line.lineTo(q)
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.setPen(QPen(QColor("#FFC94D"), S(1.6), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
        p.drawPath(line)
        # --- D. each day
        r = self.day_r
        dm = max(1, max(abs(d["p"] - d["b"]) for d in self.days))
        self._grid(p, r, -dm * 1.1, dm * 1.1, tr("Net coins each day"))
        yz = self._y(0, -dm * 1.1, dm * 1.1, r)
        nd = len(self.days)
        bw = max(2.0, min(S(16), r.width() / nd * 0.7))
        p.setPen(Qt.PenStyle.NoPen)
        for i, d in enumerate(self.days):
            cx = self._xs(i, nd, r)
            v = d["p"] - d["b"]
            y2 = self._y(v, -dm * 1.1, dm * 1.1, r)
            p.setBrush(QColor(self.WIN if v > 0 else self.LOSS if v < 0 else self.EVEN))
            p.drawRect(QRectF(cx - bw / 2, min(yz, y2), bw, max(1.2, abs(yz - y2))))
        p.setPen(QPen(alpha("#FFFFFF", 0.4), 1))
        p.drawLine(QPointF(r.left(), yz), QPointF(r.right(), yz))
        p.setFont(font(8.5))
        p.setPen(QColor(TEXT_FAINT))
        for i in range(0, nd, max(1, nd // 5)):
            p.drawText(QRectF(self._xs(i, nd, r) - S(24), r.bottom() + S(8), S(48), S(12)), int(Qt.AlignmentFlag.AlignHCenter),
                       time.strftime("%d/%m", time.localtime(self.days[i]["t"])))
        # --- the games
        p.setFont(font(10.5, QFont.Weight.Bold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QPointF(self.pad, self.leg_r.top() - S(8)), tr("Games: won, lost and even rounds"))
        topn = max(q["n"] for q in self.games)
        for k, q in enumerate(self.games):
            rr = self._leg_row(k)
            if self.hover_g == k:
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha("#FFFFFF", 0.07))
                p.drawRoundedRect(rr, S(6), S(6))
            p.setPen(QColor(TEXT))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            p.drawText(QRectF(rr.left() + S(6), rr.top(), S(104), rr.height()), int(Qt.AlignmentFlag.AlignVCenter),
                       p.fontMetrics().elidedText(tr(q["name"]), Qt.TextElideMode.ElideRight, S(100)))
            bx, bwid = rr.left() + S(112), rr.right() - rr.left() - S(112) - S(92)
            full = bwid * q["n"] / topn
            xx = bx
            p.setPen(Qt.PenStyle.NoPen)
            for cnt, col in ((q["w"], self.WIN), (q["e"], self.EVEN), (q["l"], self.LOSS)):
                wd = full * cnt / q["n"]
                p.setBrush(QColor(col))
                p.drawRect(QRectF(xx, rr.center().y() - S(4), wd, S(8)))
                xx += wd
            v = q["p"] - q["b"]
            p.setPen(QColor(self.WIN if v > 0 else self.LOSS if v < 0 else TEXT_DIM))
            p.setFont(font(10))
            p.drawText(QRectF(rr.right() - S(90), rr.top(), S(90), rr.height()), int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter),
                       f"{q['n']} · {self._k(abs(v))}" if v == 0 else f"{q['n']} · {'+' if v > 0 else '−'}{self._k(abs(v))}")
        # --- the cross-hair and the card
        if self.hover is not None and 0 <= self.hover < len(rs):
            i = self.hover - off
            x = rs[self.hover]
            if 0 <= i < n:
                cx = self._xs(i, n, self.pot_r)
                p.setPen(QPen(alpha("#FFFFFF", 0.55), 1, Qt.PenStyle.DashLine))
                for rr in (self.pot_r, self.can_r, self.vol_r):
                    p.drawLine(QPointF(cx, rr.top() - S(6)), QPointF(cx, rr.bottom() + S(6)))
                yv = self._y(cum[i], *self._scale(min(0, min(cum)), max(0, max(cum))), self.pot_r)
                p.setPen(QPen(QColor("#FFFFFF"), S(1.6)))
                p.setBrush(QColor(self._col(x["res"])))
                p.drawEllipse(QPointF(cx, yv), S(5), S(5))
            self._card_at(p, self._round_lines(x, cum[i] if 0 <= i < n else None, wr[i] if 0 <= i < n else None),
                          getattr(self, "hover_pos", QPointF(w / 2, self.height() / 2)))
        elif self.hover_day is not None:
            d = self.days[self.hover_day]
            cx = self._xs(self.hover_day, nd, self.day_r)
            p.setPen(QPen(alpha("#FFFFFF", 0.55), 1, Qt.PenStyle.DashLine))
            p.drawLine(QPointF(cx, self.day_r.top() - S(6)), QPointF(cx, self.day_r.bottom() + S(6)))
            top3 = sorted(d["g"].items(), key=lambda kv: -kv[1])[:3]
            v = d["p"] - d["b"]
            lines = [(time.strftime("%d/%m/%Y", time.localtime(d["t"])), TEXT, True),
                     (tr("Net {v}", v=self._sg(v)), self.WIN if v > 0 else self.LOSS if v < 0 else TEXT_DIM, True),
                     (tr("{n} rounds · {w} won · {l} lost", n=d["n"], w=d["w"], l=d["l"]), TEXT, False),
                     (tr("Bet {a} · paid {b}", a=coins_text(d["b"]), b=coins_text(d["p"])), TEXT_DIM, False),
                     (tr("Best round {a} · worst {b}", a=self._sg(d["best"]), b=self._sg(d["worst"])), TEXT_DIM, False),
                     (tr("Played: {g}", g=", ".join(f"{tr(k)} ×{c}" for k, c in top3)), TEXT_DIM, False)]
            self._card_at(p, lines, getattr(self, "hover_pos", QPointF(w / 2, self.height() / 2)))
        elif self.hover_g is not None:
            q = self.games[self.hover_g]
            v = q["p"] - q["b"]
            lines = [(tr(q["name"]), TEXT, True), (tr("Net {v}", v=self._sg(v)), self.WIN if v > 0 else self.LOSS if v < 0 else TEXT_DIM, True),
                     (tr("{n} rounds · {w} won · {l} lost · {e} even", n=q["n"], w=q["w"], l=q["l"], e=q["e"]), TEXT, False),
                     (tr("Win rate {p}%", p=f"{100 * q['w'] / q['n']:.1f}"), TEXT, False),
                     (tr("Total bet {a} · paid {b}", a=coins_text(q["b"]), b=coins_text(q["p"])), TEXT_DIM, False),
                     (tr("Average bet {v}", v=coins_text(q["b"] // q["n"])), TEXT_DIM, False),
                     (tr("Best round {a} · worst {b}", a=self._sg(q["best"]), b=self._sg(q["worst"])), TEXT_DIM, False),
                     (tr("Best winning streak {n}", n=q["streak"]), "#FFC94D", False)]
            self._card_at(p, lines, getattr(self, "hover_pos", QPointF(w / 2, self.height() / 2)))
        p.end()

    def _round_lines(self, x: dict, cum, wr) -> list:
        day = self._day(x["t"])
        same = [y for y in self.rs if self._day(y["t"]) == day]
        dn = sum(y["net"] for y in same)
        word = tr("WIN") if x["res"] > 0 else tr("LOSS") if x["res"] < 0 else tr("EVEN")
        out = [(f"{tr(x['gl'])} · {word}", self._col(x["res"]), True), (self._when(x["t"]), TEXT_DIM, False),
               (tr("Bet {a} → paid {b}", a=coins_text(x["b"]), b=coins_text(x["p"])), TEXT, False),
               (tr("Net {v}", v=self._sg(x["net"])), self._col(x["res"]), True)]
        if x["b"] > 0 and x["p"] > 0:
            out.append((tr("Multiplier ×{m}", m=f"{x['p'] / x['b']:.2f}"), "#FFD34D", False))
        if cum is not None:
            out.append((tr("Running net {v}", v=self._sg(int(cum))), TEXT_DIM, False))
            out.append((tr("Win rate then {p}%", p=f"{wr:.0f}"), TEXT_DIM, False))
        out.append((tr("That day: {n} rounds · net {v}", n=len(same), v=self._sg(dn)), TEXT_DIM, False))
        return out


def add_play_history(page, lay, name: str) -> None:
    """6.6: the graph at the top of a player's stats (yourself, or a friend)."""
    ctx = page.ctx
    key = (name or "").lower()
    cache = getattr(ctx, "play_hist", None) or {}
    view = PlayHistory(ctx, page.W, (cache.get(key) or (0, []))[1])
    state = {"n": len(view.rs)}

    def fresh() -> None:
        try:
            rounds = (getattr(ctx, "play_hist", None) or {}).get(key, (0, []))[1]
            view.set_data(rounds)
            state["n"] = len(view.rs)
        except RuntimeError:
            pass

    def tick() -> None:
        at = (getattr(ctx, "play_hist", None) or {}).get(key, (0, []))[0]
        if time.time() - at > 30:
            load_play_history(ctx, name, fresh)
    lay.addWidget(view)
    lay.addWidget(_Poll(10000, tick))


def build_horses(page, lay) -> None:
    """6.3: Horse Racing. Pick a free horse on the board, choose your bet, join. Bets close 2 minutes after the first
    player joins (or 2 minutes after it opens if nobody does: the bots race anyway). Then 3, 2, 1, the gun, the race."""
    ctx = page.ctx
    top = hbox(spacing=8)
    back = IconButton("back", 32, tip=tr("Back"))
    back.clicked.connect(lambda: page.open_sub(None))
    top.addWidget(back)
    top.addWidget(Label(tr("HORSE RACING"), 16, "#5BE37D", bold=True), 1)
    top.addWidget(HelpButton(ctx, "horses"))
    lay.addLayout(top)
    if getattr(ctx, "race_missing", False):
        return server_wait(ctx, lay, page.W)
    d = getattr(ctx, "race_data", None)

    def refresh(changed: bool) -> None:
        try:
            if ctx.window.showing("games") and getattr(ctx, "games_sub", "") == "horses":
                if changed:
                    ctx.reload_page("games")
                else:
                    for w in (getattr(page, "_race_view", None), getattr(page, "_race_board", None)):
                        if w is not None:
                            w.set_data(ctx.race_data)
        except RuntimeError:
            pass
    lay.addWidget(_Poll(1000, lambda: load_race(ctx, refresh)))
    if d is None:
        return lay.addWidget(Label(tr("Loading…"), 12, TEXT_DIM))
    if not d.get("feature", True):
        return lay.addWidget(LockStrip(tr("Horse Racing is paused for a moment. Nothing you own is lost."), page.W))
    lay.addWidget(CoinBar(ctx))
    state = d.get("state")
    if state == "closed":
        nxt = float(d.get("next_at") or 0) - float(d.get("now") or time.time())
        lay.addWidget(Label(tr("The next race opens in about {t}. Jackpot and Horse Racing take turns, 15 minutes apart.",
                               t=jp_clock(nxt)), 12, TEXT, wrap_w=page.W))
        return add_race_history(page, lay)               # 6.4: nothing to look at until it opens (6.5: but the history)
    view = RaceView(page, page.W)
    view.set_data(d)
    page._race_view = view
    lay.addWidget(view)
    board = RaceBoard(page, page.W)
    board.set_data(d)
    page._race_board = board
    if state == "open" and d.get("mine") is None:
        taken = {int(b.get("lane")) for b in d.get("bets") or []}
        if len(taken) >= 5:
            lay.addWidget(board)
            lay.addWidget(Label(tr("Every horse is taken. Watch the race!"), 11.5, TEXT_DIM, wrap_w=page.W))
        else:
            lo = int(d.get("min_bet") or 100)
            hi = int(d.get("max_bet") or 0)
            if hi < lo:
                lay.addWidget(board)
                lay.addWidget(Label(tr("You need at least {n} to bet.", n=coins_text(lo)), 11.5, TEXT_DIM, wrap_w=page.W))
            else:
                pick = getattr(ctx, "race_pick", None)
                if pick in taken:
                    pick = None
                board.sel = pick
                amount = AmountSlider(tr("Bet"), lo, hi, max(lo, min(hi, int(getattr(ctx, "race_bet", 1000) or 1000))),
                                      coins_text, label_w=40)
                info = Label("", 11.5, TEXT, bold=True, wrap_w=page.W)
                join = Button(tr("Bet on this horse"), "primary", 42)

                def update() -> None:
                    v = amount.value()
                    ctx.race_bet = v
                    board.extra = v
                    board.update()
                    cur = int((ctx.race_data or d).get("total") or 0)
                    late = race_now(ctx) >= float((ctx.race_data or d).get("lock_at") or 0) - 0.5
                    if board.sel is None:
                        info.set_text(tr("Click a free horse on the board"))
                        join.setEnabled(False)
                        return
                    others = cur
                    win = v + int(0.65 * others)               # 1st: the bet back + 70% of the winnings (about 65% of the others' money)
                    info.set_text(tr("Too late: the bets are closed") if late else
                                  tr("#{n}: {p} chance · 1st place pays about {w} · 2nd and 3rd get a smaller share",
                                     n=board.sel + 1, p=pct(v / max(1, cur + v)), w=coins_text(win)))
                    amount.val.set_color(LOSE if v > BIG_BET and v * 4 >= max(1, ctx.wallet.balance()) else
                                         GOLD_TEXT if v > BIG_BET else TEXT)
                    join.setEnabled(not late)

                def picked(k: int) -> None:
                    ctx.race_pick = k
                    update()
                board.picked.connect(picked)
                amount.changed.connect(lambda _v: update())

                def send() -> None:
                    join.setEnabled(False)

                    def done(ok: bool, data) -> None:
                        if not ok:
                            update()
                            return ctx.toast(tr(str(data)), "warn")
                        sfx.play("on")
                        ctx.econ.refresh()
                        ctx.race_data = data
                        ctx.reload_page("games")
                    ctx.econ.call("rb_race_join", {"lane": int(board.sel), "amount": int(amount.value())}, done, once=True)

                def go() -> None:
                    v = amount.value()
                    if board.sel is None:
                        return
                    if v > BIG_BET:                               # a big stake: asked first
                        pc = v * 100 / max(1, ctx.wallet.balance())
                        text = tr("Bet {n} coins on #{h} {name}? That is {p}% of your coins.", n=coins_text(v), h=board.sel + 1,
                                  name=tr(HORSE_NAMES[board.sel]), p=f"{pc:.0f}")
                        if pc >= 25:
                            text += "\n" + tr("Careful: you could lose a big part of your coins.")
                        return ctx.confirm(text, send, tr("Bet it"), tr("Cancel"))
                    send()
                join.clicked.connect(go)
                lay.addWidget(board)
                lay.addWidget(amount)
                row = hbox(spacing=8)
                row.addWidget(info, 1)
                lay.addLayout(row)
                lay.addWidget(join)
                lay.addWidget(_Poll(500, update))
                update()
    else:
        lay.addWidget(board)
        if state == "open":
            lay.addWidget(Label(tr("You're on #{n} {name}. Good luck!", n=int(d["mine"]) + 1, name=tr(HORSE_NAMES[int(d["mine"])])),
                                11.5, "#3DDC84", bold=True, wrap_w=page.W))
    lay.addWidget(Label(tr("Your chance to win is your share of all the money on the horses. 1st place gets their whole bet "
                           "back and 70% of the winnings, 2nd gets 25% of their bet back and 20%, 3rd gets 5% back and 10%. "
                           "Bets close 2 minutes after the first player joins; then bots take the empty horses and the "
                           "race starts, with or without players."), 10, TEXT_FAINT, wrap_w=page.W))
    add_race_history(page, lay)


def build_jackpot(page, lay) -> None:
    ctx = page.ctx
    top = hbox(spacing=8)
    back = IconButton("back", 32, tip=tr("Back"))
    back.clicked.connect(lambda: page.open_sub(None))
    top.addWidget(back)
    title = Label("JACKPOT", 16, "#FFC94D", bold=True)
    top.addWidget(title, 1)
    top.addWidget(HelpButton(ctx, "jackpot"))
    lay.addLayout(top)
    if getattr(ctx, "jackpot_missing", False):
        return server_wait(ctx, lay, page.W)
    d = getattr(ctx, "jackpot_data", None)

    def refresh(changed: bool) -> None:
        try:
            if ctx.window.showing("games") and getattr(ctx, "games_sub", "") == "jackpot":
                if changed:
                    ctx.reload_page("games")
                elif getattr(page, "_jp_wheel", None) is not None:
                    page._jp_wheel.set_data(ctx.jackpot_data)
        except RuntimeError:
            pass
    lay.addWidget(_Poll(1000, lambda: load_jackpot(ctx, refresh)))
    if d is None:
        return lay.addWidget(Label(tr("Loading…"), 12, TEXT_DIM))
    if not d.get("feature", True):
        return lay.addWidget(LockStrip(tr("Jackpot is paused for a moment. Nothing you own is lost."), page.W))
    lay.addWidget(CoinBar(ctx))
    state = d.get("state")
    if state == "closed":                                # between two jackpots: the next one, and the last result
        nxt = float(d.get("next_at") or 0) - float(d.get("now") or time.time())
        lay.addSpacing(S(6))                             # 8.0: a designed waiting card, not a lone line of text
        lay.addWidget(notice("hours", tr("The next jackpot opens in {t}", t=jp_clock(nxt)),
                             tr("Every 15 minutes, 2 minutes to join once a player is in. Put in up to 3 items: your "
                                "chance is your share of the pot."), page.W))
        return                                           # 6.4: nothing to look at until it opens
    wheel = JackpotWheel(page, min(page.W, S(330)))
    wheel.set_data(d)
    page._jp_wheel = wheel
    lay.addWidget(wheel, 0, Qt.AlignmentFlag.AlignHCenter)
    entries = d.get("entries") or []
    total = sum(int(e.get("value") or 0) for e in entries)
    landed = d.get("result_at") and wheel.server_now() >= float(d["result_at"])
    # the winner picks their prize
    if d.get("pool") and d.get("i_won"):
        allowed = int(d.get("picks_allowed") or 0)
        lay.addWidget(Label(tr("YOU WON THE JACKPOT!"), 20, "#FFC94D", bold=True))
        lay.addWidget(Label(tr("Your own items come back for free. Now pick up to {n} of the {m} items the others put in.",
                               n=allowed, m=len(d["pool"])), 11.5, TEXT, wrap_w=page.W))
        if d.get("cap"):
            lay.addWidget(Label(tr("Items from bots: up to {n} in all (twice what you put in).", n=coins_text(int(d["cap"]))),
                                10.5, TEXT_DIM, wrap_w=page.W))
        pick = JackpotPick(ctx, d["pool"], allowed, page.W)
        count = Label("", 13, "#FFC94D", bold=True)
        claim = Button(tr("Claim"), "primary", 42)

        cap = int(d.get("cap") or 0)
        worth_of = {x["key"]: int(x.get("worth") or 0) for x in d["pool"]}

        def bot_taken() -> int:
            return sum(worth_of.get(k, 0) for k in pick.picked if str(k).startswith("bot:"))

        def update_count() -> None:                      # 5.3: up to N, and bot items within the cap
            over = cap and bot_taken() > cap
            count.set_text(tr("Bot items too big: at most {n} from bots", n=coins_text(cap)) if over else
                           tr("{a} / {b} picked", a=len(pick.picked), b=allowed))
            claim.setEnabled(0 < len(pick.picked) <= allowed and not over)
        pick.changed.connect(update_count)
        update_count()

        def do_claim() -> None:
            claim.setEnabled(False)

            def done(ok: bool, data) -> None:
                if not ok:
                    claim.setEnabled(True)
                    return ctx.toast(tr(str(data)), "warn")
                sfx.tune("levelup")
                ctx.toast(tr("Jackpot claimed! The items are in your inventory."))
                ctx.econ.refresh()
                ctx.jackpot_data = None
                ctx.reload_page("games")
            ctx.econ.call("rb_jackpot_pick", {"jid": d["id"], "keys": list(pick.picked)}, done)
        claim.clicked.connect(do_claim)
        row = hbox(spacing=8)
        row.addWidget(count, 1)
        row.addWidget(claim, 1)
        lay.addLayout(row)                               # the button above the items: no scrolling to claim
        lay.addWidget(pick)
        left = float(d.get("pick_until") or 0) - wheel.server_now()
        lay.addWidget(Label(tr("If you don't pick within {t}, the best ones are picked for you.", t=jp_clock(left)),
                            10, TEXT_FAINT, wrap_w=page.W))
    # joining (while it is open and you are not in yet)
    if state == "open" and not d.get("mine") and wheel.server_now() < float(d.get("lock_at") or 0):
        n = len(entries)
        if n >= 5:
            lay.addWidget(Label(tr("This jackpot is full (5 players). Watch it spin!"), 11.5, TEXT_DIM, wrap_w=page.W))
        else:
            minj = int(d.get("min_join") or 500)
            maxj = int(d.get("max_join") or 0)
            picker = ItemPicker(page, 3)
            chance = Label("", 12, TEXT, bold=True)
            join = Button(tr("Join the jackpot"), "primary", 40)

            def update_chance() -> None:
                mine = picker.total()
                cur = int((ctx.jackpot_data or d).get("total") or total)
                if not picker.picked:
                    chance.set_text(tr("Pick 1 to 3 items (at least {n} in all)", n=coins_text(minj)))
                    join.setEnabled(False)
                    return
                share = mine / max(1, cur + mine)
                late = wheel.server_now() >= float((ctx.jackpot_data or d).get("lock_at") or 0) - 0.5
                big = maxj and mine > maxj
                ok = mine >= minj and not big and not late
                chance.set_text(tr("Too late: this jackpot is locked") if late else
                                tr("Too big: at most {n} in one jackpot", n=coins_text(maxj)) if big else
                                tr("Your chance: {p}", p=pct(share)) if mine >= minj else
                                tr("Too small: at least {n} to join", n=coins_text(minj)))
                join.setEnabled(ok)
            picker.changed.connect(update_chance)
            update_chance()
            lay.addWidget(_Poll(500, update_chance))         # 5.3: the button shuts with the timer, not after

            def do_join() -> None:
                join.setEnabled(False)

                def done(ok: bool, data) -> None:
                    if not ok:
                        update_chance()
                        return ctx.toast(tr(str(data)), "warn")
                    sfx.play("on")
                    ctx.econ.refresh()
                    ctx.jackpot_data = data
                    ctx.jackpot_in = True
                    ctx.reload_page("games")
                ctx.econ.call("rb_jackpot_join", {"items": picker.ids()}, done, once=True)
            join.clicked.connect(do_join)
            row = hbox(spacing=8)
            row.addWidget(chance, 1)
            row.addWidget(join, 1)
            lay.addLayout(row)
            lay.addWidget(sort_bar(ctx, picker.resort))
            lay.addWidget(picker)
    elif state == "open" and d.get("mine"):
        lay.addWidget(Label(tr("You're in! Watch the others join. Good luck."), 11.5, "#3DDC84", bold=True, wrap_w=page.W))
    elif state == "open":
        lay.addWidget(Label(tr("Watching. The jackpot locks when the timer runs out."), 11, TEXT_DIM, wrap_w=page.W))
    # everybody in it
    lay.addWidget(heading(tr("Players ({n}/5)", n=len(entries))))
    for e in entries:
        lay.addWidget(JackpotRow(ctx, e, total, page.W, d.get("winner"), bool(landed)))
    if not entries:
        lay.addWidget(Label(tr("Nobody yet: be the first (the first player has a 100% chance until others join)."),
                            11, TEXT_DIM, wrap_w=page.W))
    lay.addWidget(Label(tr("Your chance is your share of everything put in. The winner gets their own items back and "
                           "picks 75% of everyone else's; the rest leaves the game. After 2 minutes the lobby locks "
                           "and bots fill the empty seats."), 10, TEXT_FAINT, wrap_w=page.W))


