GAME_COLOURS = {"Blackjack": ("#2FD08A", "#0B5D3B"), "Plinko": ("#FF5CA8", "#6A1B9A"), "Bombs": ("#4FC3FF", "#1A3A8A"),
                "Roulette": ("#FF4D5E", "#7A0F1C"), "Dice": ("#FFFFFF", "#5A6470"), "Timing": ("#3DDC84", "#14532D"),
                "Rocket": ("#FF8A3D", "#7A2A0A"), "Hi-Lo": ("#B388FF", "#3A1A7A"), "Tower": ("#FFC94D", "#7A4A0A"),
                "Slots": ("#FF3D6E", "#5A0F3A"), "Cups": ("#E8C26A", "#5A3A0A"), "Connect 4": ("#FF5C5C", "#1A3A8A"),
                "Colour Pick": ("#FF6FD8", "#3813C2"), "SFX Match": ("#35E0A1", "#0B4A5A"), "Free spin": ("#F5C04A", "#8A5A00")}


def open_game(ctx, index: int, back: str = "") -> None:
    """9.0: straight into one casino game (or the free spin) from anywhere in the online menu."""
    for f in ("quests_open", "mini_open", "park_open"):
        setattr(ctx, f, False)
    ctx.games_sub = None
    ctx.back_to = back or None
    ctx.cfg["game"] = index
    ctx.casino = True
    w = ctx.window
    if getattr(w, "current", "") == "games":
        return ctx.reload_page("games")
    w.goto("games")


def leave_free_game(ctx) -> None:
    """9.0.1: the back button of a free game (Beat Tap, Memory, Mini Golf, Wave Rush...) returns to the page it was
    opened from (Play unless said otherwise, 9.1), never to the old "Earn coins" list."""
    for f in ("quests_open", "mini_open", "park_open"):
        setattr(ctx, f, False)
    ctx.games_sub = None
    ctx.casino = False
    dest = getattr(ctx, "back_to", None) or "games"
    ctx.back_to = None
    sfx.play("pick")
    w = ctx.window
    if getattr(w, "current", "") == dest:
        return ctx.reload_page(dest)
    w.goto(dest)


def open_games_part(ctx, sub: str = None, flag: str = "", back: str = "") -> None:
    """9.0: one part of the games (a mini game, the scratch card, the quests...) from Home or Rewards."""
    for f in ("quests_open", "mini_open", "park_open"):
        setattr(ctx, f, False)
    if flag:
        setattr(ctx, flag, True)
        if flag == "casino_door_auto":            # 9.5: only for the page this opens, never a later visit
            QTimer.singleShot(3000, lambda: setattr(ctx, "casino_door_auto", False))
    ctx.games_sub = sub
    ctx.back_to = back or None
    if ctx.casino:
        ctx.casino = False
    w = ctx.window
    if getattr(w, "current", "") == "games":
        return ctx.reload_page("games")
    w.goto("games")


def remember_game(ctx, index: int) -> None:
    try:
        rec = [int(i) for i in (ctx.cfg["recent_games"] or []) if int(i) != int(index)]
    except (TypeError, ValueError):
        rec = []
    ctx.cfg["recent_games"] = ([int(index)] + rec)[:6]


def scaled(n: int, m: float) -> int:
    """9.0: a reward times the wealth tier, rounded like the server (to 10, or to 5 under 100)."""
    if n <= 0:
        return n
    x, step = n * m, (5 if n * m < 100 else 10)
    return int(math.floor(x / step + 0.5)) * step


SKILL_PAY = {"timing": {"perfect": 240, "good": 100, "close": 30}, "cups": {0: 50, 1: 100, 2: 180, 3: 300},
             "c4": {"easy": 80, "medium": 180, "hard": 400, "pro": 1200}, "colour": {0: 80, 1: 120, 2: 180},
             "sfx": {0: 100, 1: 150, 2: 220}}        # the server's rb_skill_base × skill_pay_mult (9.2: 2), before the tier


def skill_pay(ctx, game: str, key, factor: float = 1.0) -> int:
    """9.1: what a skill round pays at full pay: the base (times an accuracy factor) times your tier, rounded the way
    the server rounds it."""
    try:
        m = float(tier_info(ctx).get("mult") or 1.0)
    except Exception:  # noqa: BLE001
        m = 1.0
    return scaled(int(round(SKILL_PAY.get(game, {}).get(key, 0) * factor)), m)


def tier_info(ctx) -> dict:
    """9.0: the wealth tier (from the server when it has 9.0, else worked out from the coins)."""
    t = getattr(ctx.econ, "tier", None)
    if isinstance(t, dict) and t.get("name"):
        return t
    bal = ctx.wallet.balance() if ctx.econ.ready else 0
    tiers = WEALTH_TIERS
    i = max(k for k, (_n, at, _x, _c) in enumerate(tiers) if bal >= at)
    nxt = tiers[i + 1][1] if i + 1 < len(tiers) else None
    return {"tier": i, "name": tiers[i][0], "mult": tiers[i][2], "wealth": bal, "next": nxt}


WEALTH_TIERS = [("Poor", 0, 1.0, "#9AA5B1"), ("Average", 50000, 1.3, "#5FD3A0"), ("Investor", 250000, 1.8, "#4FC3FF"),
                ("Businessman", 1000000, 2.6, "#F5C04A"), ("Casino Legend", 5000000, 4.0, "#FF5CA8")]     # 9.4
TIER_ICONS = ("coin", "chart", "gem", "briefcase", "crown")


class Tile(QWidget):
    """9.0: a big rounded tile: a coloured glow, an icon or a picture, a title and one short status. Lit when ready."""

    def __init__(self, title: str, status, icon, colours: tuple, on_click, height: int = 118, ready=None,
                 art=None, note: str = "") -> None:
        super().__init__()
        self.title, self.status, self.icon, self.colours, self.on_click = title, status, icon, colours, on_click
        self.note = note                                      # 9.1: one short line on top: how often it comes
        self.ready, self.art = ready, art                     # status / ready can be functions (live)
        self.setFixedHeight(S(height))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._hover = Tween(self, on_change=self.update)
        if callable(status) or callable(ready):
            self._t = QTimer(self)
            self._t.setInterval(1000)
            self._t.timeout.connect(self.update)
            self._t.start()

    def enterEvent(self, _e) -> None:
        self._hover.to(1.0, 140)

    def leaveEvent(self, _e) -> None:
        self._hover.to(0.0, 220)

    def mousePressEvent(self, e) -> None:
        e.accept()

    def mouseReleaseEvent(self, e) -> None:
        if e.button() == Qt.MouseButton.LeftButton and self.rect().contains(e.position().toPoint()):
            sfx.play("pick")
            self.on_click()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        h = self._hover.level
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1).translated(0, -S(2) * h)
        a, b = QColor(self.colours[0]), QColor(self.colours[1])
        ready = self.ready() if callable(self.ready) else self.ready
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        g.setColorAt(0, mix(a, QColor("#07090C"), 0.62 - 0.12 * h))
        g.setColorAt(1, mix(b, QColor("#07090C"), 0.82))
        p.setPen(QPen(alpha(a, 0.35 + 0.35 * h + (0.3 if ready else 0)), S(1.2)))
        p.setBrush(g)
        p.drawRoundedRect(r, S(18), S(18))
        p.save()
        clip = QPainterPath()
        clip.addRoundedRect(r, S(18), S(18))
        p.setClipPath(clip)
        glow = QRadialGradient(QPointF(r.right() - r.width() * 0.22, r.top() + r.height() * 0.38), r.height() * 0.9)
        glow.setColorAt(0, alpha(a, 0.42 + 0.15 * h))
        glow.setColorAt(1, alpha(a, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glow)
        p.drawRect(r)
        sheen = QLinearGradient(r.topLeft(), r.bottomLeft())
        sheen.setColorAt(0, alpha("#FFFFFF", 0.07))
        sheen.setColorAt(0.4, alpha("#FFFFFF", 0.0))
        p.setBrush(sheen)
        p.drawRect(r)
        art_c = QPointF(r.right() - r.width() * 0.22, r.top() + r.height() * 0.42)
        if self.art is not None:
            self.art(p, art_c, min(r.height() * 0.42, r.width() * 0.2))
        elif self.icon:
            p.save()
            p.translate(art_c)
            k = min(r.height() * 0.4, r.width() * 0.18) / 20
            p.scale(k, k)
            draw_icon(p, self.icon, alpha("#FFFFFF", 0.9))
            p.restore()
        p.restore()
        if self.note:
            p.setPen(alpha("#FFFFFF", 0.62))
            p.setFont(font(9.5, QFont.Weight.Bold))
            p.drawText(QRectF(r.left() + S(16), r.top() + S(12), r.width() * 0.6, S(18)), int(Qt.AlignmentFlag.AlignVCenter),
                       p.fontMetrics().elidedText(self.note, Qt.TextElideMode.ElideRight, int(r.width() * 0.6)))
        p.setPen(QColor(TEXT))
        p.setFont(font(15, QFont.Weight.ExtraBold))
        p.drawText(QRectF(r.left() + S(16), r.bottom() - S(52), r.width() * 0.75, S(24)), int(Qt.AlignmentFlag.AlignVCenter),
                   p.fontMetrics().elidedText(self.title, Qt.TextElideMode.ElideRight, int(r.width() * 0.75)))
        status = self.status() if callable(self.status) else self.status
        if status:
            p.setFont(font(11, QFont.Weight.Bold))
            sw = p.fontMetrics().horizontalAdvance(status) + S(18)
            chip = QRectF(r.left() + S(14), r.bottom() - S(28), sw, S(20))
            p.setPen(Qt.PenStyle.NoPen)
            if ready:
                pulse = 0.5 + 0.5 * math.sin(time.monotonic() * 3)
                p.setBrush(alpha(GOLD, 0.85 + 0.15 * pulse))
                p.drawRoundedRect(chip, S(10), S(10))
                p.setPen(QColor("#2A1C00"))
            else:
                p.setBrush(alpha("#000000", 0.38))
                p.drawRoundedRect(chip, S(10), S(10))
                p.setPen(QColor(TEXT_DIM))
            p.drawText(chip, int(Qt.AlignmentFlag.AlignCenter), status)


def tile_grid(tiles: list, cols: int = 2) -> QWidget:
    grid = QWidget()
    gl = QGridLayout(grid)
    gl.setContentsMargins(0, 0, 0, 0)
    gl.setSpacing(S(10))
    for k, t in enumerate(tiles):
        gl.addWidget(t, k // cols, k % cols)
    return grid


def game_art(name: str):
    """The little picture of a casino game (the lobby's), drawn at any size."""
    def draw(p: QPainter, c: QPointF, size: float) -> None:
        p.save()
        p.translate(c)
        k = size / S(26)
        p.scale(k, k)
        paint_game_art(p, name, QPointF(0, 0))
        p.restore()
    return draw


class TierBanner(QWidget):
    """9.1: your wealth tier on a five-step track. The bar charges toward the next tier; a tier once reached is kept
    (your wealth can go down inside it, never below it). Every free reward is multiplied by it."""

    def __init__(self, ctx) -> None:
        super().__init__()
        self.ctx = ctx
        self.setFixedHeight(S(92))
        lay = hbox(self, 6, (S(14), S(8), S(10), 0))
        lay.addStretch(1)
        lay.addWidget(HelpDot(tr("Your wealth = your coins + the shop value of your items. Average at 50 000, Investor at "
                                 "250 000, Businessman at 1 000 000, Casino Legend at 5 000 000. You go up one tier a day at "
                                 "most. Free rewards are multiplied by your tier, and a tier you reach is yours for good."),
                              tr("Wealth tier")), 0, Qt.AlignmentFlag.AlignTop)
        self._fill = Tween(self, 0.0, self.update, QEasingCurve.Type.OutCubic)
        self._want = None
        self.setCursor(Qt.CursorShape.PointingHandCursor)       # 9.2.1: a click shows what every tier gets
        self.setToolTip(tr("See what every tier gets"))
        self._t = QTimer(self)
        self._t.setInterval(40)
        self._t.timeout.connect(self._tick)
        self._t.start()

    def mouseReleaseEvent(self, e) -> None:
        if e.button() == Qt.MouseButton.LeftButton and self.rect().contains(e.position().toPoint()):
            open_tier_guide(self.ctx)

    def _frac(self, t: dict) -> float:
        i = int(t.get("tier", 0) or 0)
        nxt = t.get("next")
        if not nxt:
            return 1.0
        lo = float(t.get("at") if t.get("at") is not None else WEALTH_TIERS[min(i, len(WEALTH_TIERS) - 1)][1])
        return max(0.0, min(1.0, (float(t.get("wealth", 0) or 0) - lo) / max(1.0, float(nxt) - lo)))

    def _tick(self) -> None:
        if not self.isVisible():
            return
        t = tier_info(self.ctx)
        f = self._frac(t)
        if t.get("coins") is not None:                     # 9.1.1: what the wealth is made of
            tip = tr("Wealth {w} = {c} coins + {i} in items", w=coins_text(int(t.get("wealth") or 0)),
                     c=coins_text(int(t.get("coins") or 0)), i=coins_text(int(t.get("items") or 0)))
            if self.toolTip() != tip:
                self.setToolTip(tip)
        if self._want is None or abs(f - self._want) > 1e-4:
            self._want = f
            self._fill.to(f, int(900 * ui.motion))
        self.update()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        t = tier_info(self.ctx)
        i = max(0, min(len(WEALTH_TIERS) - 1, int(t.get("tier", 0) or 0)))
        col = QColor(WEALTH_TIERS[i][3])
        now = time.monotonic()
        paint_surface(p, r, S(16), 0.04, 0.0, tint=col, tint_a=0.14)
        # the emblem
        c = QPointF(r.left() + S(34), r.top() + S(30))
        glow = QRadialGradient(c, S(26))
        glow.setColorAt(0, alpha(col, 0.35))
        glow.setColorAt(1, alpha(col, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glow)
        p.drawEllipse(c, S(26), S(26))
        p.setBrush(alpha(col, 0.18))
        p.setPen(QPen(alpha(col, 0.8), S(1.4)))
        p.drawEllipse(c, S(17), S(17))
        p.save()
        p.translate(c)
        p.scale(S(18) / 20, S(18) / 20)
        draw_icon(p, TIER_ICONS[i], mix(col, QColor("#FFFFFF"), 0.35))
        p.restore()
        # name and multiplier
        p.setPen(QColor(TEXT))
        p.setFont(font(15, QFont.Weight.ExtraBold))
        name = tr(WEALTH_TIERS[i][0])
        p.drawText(QRectF(r.left() + S(60), r.top() + S(12), r.width(), S(22)), int(Qt.AlignmentFlag.AlignVCenter), name)
        nw = p.fontMetrics().horizontalAdvance(name)
        p.setFont(font(13, QFont.Weight.Black))
        p.setPen(col)
        p.drawText(QRectF(r.left() + S(68) + nw, r.top() + S(12), S(80), S(22)), int(Qt.AlignmentFlag.AlignVCenter),
                   "×" + f"{float(t.get('mult', 1) or 1):g}")
        nxt = t.get("next")
        p.setPen(QColor(TEXT_FAINT))
        p.setFont(font(10, QFont.Weight.DemiBold))
        label = tr("Top tier") if not nxt else tr("Wealth {w} / {n} for {name}", w=coins_text(int(t.get("wealth") or 0)),
                                                  name=tr(WEALTH_TIERS[i + 1][0]), n=coins_text(int(nxt)))
        if nxt and t.get("wait"):                                   # 9.4: one tier a day
            label = tr("{name} tomorrow", name=tr(WEALTH_TIERS[i + 1][0]))
        p.drawText(QRectF(r.left() + S(60), r.top() + S(12), r.width() - S(60) - S(44), S(22)),
                   int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight), label)
        # the track: five stops; the part to the next stop charges up
        n = len(WEALTH_TIERS)
        x0, x1 = r.left() + S(24), r.right() - S(24)
        y = r.bottom() - S(24)
        step = (x1 - x0) / (n - 1)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#FFFFFF", 0.08))
        p.drawRoundedRect(QRectF(x0, y - S(3), x1 - x0, S(6)), S(3), S(3))
        f = self._fill.level
        done = x0 + step * i + (step * f if i < n - 1 else 0)
        g = QLinearGradient(QPointF(x0, y), QPointF(max(done, x0 + 1), y))
        g.setColorAt(0, alpha(WEALTH_TIERS[0][3], 0.9))
        g.setColorAt(1, col)
        p.setBrush(g)
        p.drawRoundedRect(QRectF(x0, y - S(3), max(S(6), done - x0), S(6)), S(3), S(3))
        if i < n - 1 and f > 0.01:                                  # a light running along the charging part
            run = (now * 0.6) % 1.0
            sx = x0 + step * i + step * f * run
            sh = QRadialGradient(QPointF(sx, y), S(10))
            sh.setColorAt(0, alpha("#FFFFFF", 0.55))
            sh.setColorAt(1, alpha("#FFFFFF", 0.0))
            p.setBrush(sh)
            p.drawEllipse(QPointF(sx, y), S(10), S(4))
        for k in range(n):
            cx = x0 + step * k
            kc = QColor(WEALTH_TIERS[k][3])
            reached = k <= i
            p.setPen(QPen(QColor("#0B0D12"), S(2)))
            p.setBrush(kc if reached else alpha("#FFFFFF", 0.12))
            rad = S(6.5) if k == i else S(5)
            p.drawEllipse(QPointF(cx, y), rad, rad)
            p.setPen(QColor(TEXT) if k == i else (kc if reached else QColor(TEXT_FAINT)))
            p.setFont(font(8.5, QFont.Weight.Bold if k == i else QFont.Weight.DemiBold))
            al = Qt.AlignmentFlag.AlignLeft if k == 0 else Qt.AlignmentFlag.AlignRight if k == n - 1 else Qt.AlignmentFlag.AlignHCenter
            bx = QRectF(cx - (0 if k == 0 else S(90) if k == n - 1 else S(45)), y + S(7), S(90), S(14))
            p.drawText(bx, int(al | Qt.AlignmentFlag.AlignVCenter), tr(WEALTH_TIERS[k][0]))


