        self.setFixedHeight(S(32))
        self.hover = 0.0
        self.text = "🏆  " + tr("Leaderboards")
        f = font(11.5, QFont.Weight.ExtraBold)
        from PyQt6.QtGui import QFontMetrics
        self.setFixedWidth(QFontMetrics(f).horizontalAdvance(self.text) + S(28))
