# 9.0: the online menu is one focused page at a time, picked from a rail on the left. Each rail entry opens a page
# (and, for Shop / Collection, which part of it). Coins, keys and the level live in the top bar on every page.
NAV = [("hub", "home", "Home"), ("games", "dice", "Play"), ("rewards", "gift", "Rewards"), ("stats", "chart", "Stats"),
       ("leaders", "trophy", "Leaderboards"),
       ("shop", "gem", "Shop"),
       ("collection", "folder", "Collection"), ("trophies", "medal", "Trophies"), ("friends", "users", "Social"),
       ("settings", "cog", "Settings")]
NAV_PAGE = {"shop": "themes", "collection": "themes"}
SHOP_GET = (1, 7, 3)            # Shop, Deals, Cases (the player market is gone in 9.0)
SHOP_MINE = (5, 2, 8, 0, 6)     # Inventory, Collection, Style, Notifications, Sets
RAIL_W = 92


def nav_keys() -> list:
    keys = [k for k, _i, _t in NAV]
    if "giveaway" in LIVE_TABS:
        keys.insert(1, "giveaway")
    if "admin" in LIVE_TABS:
        keys.append("admin")
    return keys


def nav_of(ctx, page_key: str) -> str:
    """Which rail entry a page belongs to (the shop page is two entries: getting things and what is yours)."""
    if page_key == "themes":
        if int(getattr(ctx, "shop_tab", 1) or 0) == 2 and getattr(ctx, "coll_trophies", False):
            return "trophies"                                     # 9.2: Trophies have their own rail entry
        return "collection" if int(getattr(ctx, "shop_tab", 1) or 0) in SHOP_MINE else "shop"
    if page_key == "games":
        sub = getattr(ctx, "games_sub", None)
        if (ctx.casino and ctx.cfg["game"] == GamesPage.PICKER) or sub == "scratch" \
                or getattr(ctx, "quests_open", False):           # 9.1: the free games are in Play again
            return "rewards"
    return page_key


def rewards_ready(ctx) -> int:
    """9.0: how many free things can be collected now (the gold count on Rewards)."""
    try:
        ec, w = ctx.econ, ctx.wallet
        if not ec.ready or ec.server_old:
            return 0
        n = 1 if w.daily_wait() == 0 else 0
        n += 1 if int(getattr(ec, "scratch_in", 1) or 0) <= 0 and getattr(ec, "scratch_in", None) is not None else 0
        n += quests_ready(getattr(ctx, "quests_data", None))
        day = str(ec.streak_day or "")
        if day and day != datetime.date.today().isoformat():
            n += 1
        return n
    except Exception:  # noqa: BLE001
        return 0


NAV_TITLE = {"giveaway": ("gift", "Giveaway"), "admin": ("shield", "Admin")}


class NavRail(QWidget):
    """9.0: the online menu's sections, top to bottom: an icon and a short name. The one you are on wears the brand
    colours; a gold count says when something is waiting there."""
    picked = pyqtSignal(str)

    def __init__(self, win, parent=None) -> None:
        super().__init__(parent)
        self.win = win
        self.setMouseTracking(True)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.hover = None
        self._sel = Tween(self, 0.0, self.update, QEasingCurve.Type.OutCubic)
        self._sel_key = None
        self._t = QTimer(self)
        self._t.setInterval(1500)
        self._t.timeout.connect(self.update)
        self._t.start()

    def items(self) -> list:
        names = {k: (i, t) for k, i, t in NAV}
        names.update(NAV_TITLE)
        return [(k, *names[k]) for k in nav_keys()]

    def rects(self) -> list:
        items = self.items()
        gap = S(4)
        h = max(S(40), min(S(58), (self.height() - S(10)) / max(1, len(items)) - gap))     # 9.1: always fits
        out = []
        y = S(4)
        for k, icon, title in items:
            if k in ("settings",):                      # settings (and admin) sit at the bottom
                break
            out.append((QRectF(S(8), y, self.width() - S(16), h), k, icon, title))
            y += h + gap
        rest = [it for it in items if it[0] in ("settings", "admin")]
        y = self.height() - S(6) - len(rest) * (h + gap) + gap
        for k, icon, title in rest:
            out.append((QRectF(S(8), y, self.width() - S(16), h), k, icon, title))
            y += h + gap
        return out

    def mouseMoveEvent(self, e) -> None:
        h = next((k for r, k, _i, _t in self.rects() if r.contains(e.position())), None)
        if h != self.hover:
            self.hover = h
            self.update()

    def leaveEvent(self, _e) -> None:
        self.hover = None
        self.update()

    def mousePressEvent(self, e) -> None:
        e.accept()

    def mouseReleaseEvent(self, e) -> None:
        for r, k, _i, _t in self.rects():
            if r.contains(e.position()):
                self.picked.emit(k)
                return

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        cur = nav_of(self.win.ctx, self.win.current)
        c1, c2 = cta_colors()
        rects = self.rects()
        sel = next((r for r, k, _i, _t in rects if k == cur), None)
        if sel is not None:
            if self._sel_key != cur:
                old = getattr(self, "_sel_rect", None)
                self._sel_from = old if old is not None else sel
                self._sel_key = cur
                self._sel.jump(0.0)
                self._sel.to(1.0, int(260 * ui.motion))
            f = self._sel.level
            a0 = getattr(self, "_sel_from", sel)
            box = QRectF(lerp(a0.left(), sel.left(), f), lerp(a0.top(), sel.top(), f), sel.width(), sel.height())
            self._sel_rect = box
            glow = QRadialGradient(box.center(), box.width() * 0.75)
            glow.setColorAt(0, alpha(mix(c1, c2, 0.5), 0.30))
            glow.setColorAt(1, alpha(mix(c1, c2, 0.5), 0.0))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(glow)
            p.drawRoundedRect(box.adjusted(-S(6), -S(6), S(6), S(6)), S(18), S(18))
            g = QLinearGradient(box.topLeft(), box.bottomRight())
            g.setColorAt(0, alpha(c1, 0.95))
            g.setColorAt(1, alpha(c2, 0.95))
            p.setBrush(g)
            p.setPen(QPen(alpha("#FFFFFF", 0.28), 1))
            p.drawRoundedRect(box, S(14), S(14))
        ready = rewards_ready(self.win.ctx)
        for r, k, icon, title in rects:
            on = k == cur
            hov = k == self.hover and not on
            if hov:
                paint_surface(p, r, S(14), 0.03, 1.0)
            fg = (QColor("#0B0D12") if mix(c1, c2, 0.5).lightnessF() > 0.62 else QColor("#FFFFFF")) if on else \
                (QColor(TEXT) if hov else QColor(TEXT_DIM))
            if k == "admin" and not on:
                fg = QColor("#FF9A8F")
            if k == "giveaway" and not on:
                fg = QColor(GOLD)
            p.save()
            p.translate(r.center().x(), r.top() + S(22))
            p.scale(S(21) / 20, S(21) / 20)
            draw_icon(p, icon, fg)
            p.restore()
            p.setPen(fg)
            p.setFont(font(10, QFont.Weight.Bold if on else QFont.Weight.DemiBold))
            text = p.fontMetrics().elidedText(tr(title), Qt.TextElideMode.ElideRight, int(r.width() - S(4)))
            p.drawText(QRectF(r.left(), r.top() + S(36), r.width(), S(16)), int(Qt.AlignmentFlag.AlignCenter), text)
            n = ready if k == "rewards" else 0
            if n:
                b = QRectF(r.right() - S(22), r.top() + S(5), S(17), S(15))
                p.setPen(QPen(QColor("#0B0D12"), S(1.5)))
                p.setBrush(QColor(GOLD))
                p.drawRoundedRect(b, S(7.5), S(7.5))
                p.setPen(QColor("#2A1C00"))
                p.setFont(font(8.5, QFont.Weight.Black))
                p.drawText(b, int(Qt.AlignmentFlag.AlignCenter), str(min(n, 9)))


class WalletChip(QWidget):
    """9.0: the top bar's money: coins (rolling to the new value) and keys, always in sight. Click: Rewards."""
    clicked = pyqtSignal()

    def __init__(self, ctx, parent=None) -> None:
        super().__init__(parent)
        self.ctx = ctx
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedHeight(S(38))
        self._shown = float(ctx.wallet.balance())
        self.bump = 0.0
        self._tick = QTimer(self)
        self._tick.setInterval(33)
        self._tick.timeout.connect(self._step)
        self._sec = QTimer(self)
        self._sec.setInterval(1000)
        self._sec.timeout.connect(self.update)
        self._sec.start()
        ctx.wallet.changed.connect(self._wake)
        self._fit()

    def _wake(self) -> None:
        try:
            self._tick.start()
        except RuntimeError:                          # 9.4: this bar was closed (a language change rebuilds it)
            pass

    def _fit(self) -> None:
        f = font(14, QFont.Weight.ExtraBold)
        cw = QFontMetrics(f).horizontalAdvance(coins_text(max(round(self._shown), 99999999)))
        kw = QFontMetrics(f).horizontalAdvance("99")
        self.setFixedWidth(S(16) + S(22) + cw + S(18) + S(20) + kw + S(16))

    def _step(self) -> None:
        target = float(self.ctx.wallet.balance())
        gap = target - self._shown
        if abs(gap) < 1:
            self._shown = target
            self._tick.stop()
            self._fit()
        else:
            if gap > 0:
                self.bump = 1.0
            self._shown += gap * 0.18 + (1 if gap > 0 else -1)
        self.bump = max(0.0, self.bump - 0.05)
        self.update()

    def mousePressEvent(self, e) -> None:
        e.accept()

    def mouseReleaseEvent(self, e) -> None:
        if self.rect().contains(e.position().toPoint()):
            self.clicked.emit()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(0.5, 0.5, -0.5, -0.5)
        p.setPen(QPen(alpha(GOLD, 0.22 + 0.4 * self.bump), 1))
        p.setBrush(alpha("#000000", 0.35))
        p.drawRoundedRect(r, r.height() / 2, r.height() / 2)
        ec = self.ctx.econ
        x = r.left() + S(14)
        paint_coin(p, QPointF(x + S(9), r.center().y()), S(9.5))
        x += S(24)
        p.setFont(font(14, QFont.Weight.ExtraBold))
        p.setPen(mix(QColor(TEXT), QColor(GOLD), self.bump))
        text = coins_text(round(self._shown)) if ec.ready else "…"
        tw = p.fontMetrics().horizontalAdvance(text)
        p.drawText(QRectF(x, r.top(), tw + S(4), r.height()), int(Qt.AlignmentFlag.AlignVCenter), text)
        x += tw + S(10)
        p.setPen(QPen(alpha("#FFFFFF", 0.12), 1))
        p.drawLine(QPointF(x, r.top() + S(9)), QPointF(x, r.bottom() - S(9)))
        x += S(10)
        p.save()
        p.translate(x + S(7), r.center().y())
        p.scale(S(15) / 20, S(15) / 20)
        draw_icon(p, "key", QColor(KEY_BLUE))
        p.restore()
        x += S(19)
        p.setPen(QColor(TEXT))
        p.drawText(QRectF(x, r.top(), S(40), r.height()), int(Qt.AlignmentFlag.AlignVCenter), str(min(self.ctx.wallet.keys(), 99)))
        tip = tr("+{n} coins in {t}", n=int(float(ec.cfg.get('coin_amount', 10) or 10)) + ec.streak_bonus(),
                 t=clock_text(ec.next_coin_s())) if ec.ready else ""
        if self.toolTip() != tip:
            self.setToolTip(tip)


class LeaveButton(QWidget):
    """Leaving online mode: an arrow in a round button (9.0: no words, a tooltip)."""
    clicked = pyqtSignal()

    def __init__(self, parent=None) -> None:
        super().__init__(parent)
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFixedSize(S(38), S(38))
        self.hover = 0.0
        self.text = tr("Leave online")
        self.setToolTip(tr("Leave online"))

    def enterEvent(self, _e) -> None:
        self.hover = 1.0
        self.update()

    def leaveEvent(self, _e) -> None:
        self.hover = 0.0
        self.update()

    def mousePressEvent(self, e) -> None:
        e.accept()

    def mouseReleaseEvent(self, e) -> None:
        if self.rect().contains(e.position().toPoint()):
            sfx.play("pick")
            self.clicked.emit()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        paint_surface(p, r, r.height() / 2, 0.05, self.hover)
        p.save()
        p.translate(r.center())
        p.scale(S(15) / 20, S(15) / 20)
        draw_icon(p, "power", QColor(TEXT) if self.hover else QColor(TEXT_DIM))
        p.restore()


WIDE_SIDE = 250                     # 9.1: each side the online menu grows by while you play a game


class GameSide(QWidget):
    """9.1: beside a game, while the online menu is wide. "info": the game's picture, how it pays and how this session
    went. "play": the other games of the same group, one click away. Painted only (no layouts), so it costs nothing
    while it is hidden."""

    def __init__(self, win, kind: str, parent) -> None:
        super().__init__(parent)
        self.win, self.kind = win, kind
        self.level = 0.0
        self._rows: list = []
        self._hover = -1
        self.setMouseTracking(True)
        self.hide()

    def page(self):
        entry = getattr(self.win, "pages", {}).get("games")
        page = entry[1] if entry else None
        return page if page is not None and getattr(page, "game", None) is not None else None

    def set_level(self, v: float) -> None:
        self.level = v
        self.setVisible(v > 0.01)
        self.update()

    def mouseMoveEvent(self, e) -> None:
        i = next((k for k, (r, _i) in enumerate(self._rows) if r.contains(e.position())), -1)
        if i != self._hover:
            self._hover = i
            self.setCursor(Qt.CursorShape.PointingHandCursor if i >= 0 else Qt.CursorShape.ArrowCursor)
            self.update()

    def leaveEvent(self, _e) -> None:
        self._hover = -1
        self.update()

    def mousePressEvent(self, e) -> None:
        e.accept()

    def mouseReleaseEvent(self, e) -> None:
        page = self.page()
        if page is None or e.button() != Qt.MouseButton.LeftButton:
            return
        for r, idx in self._rows:
            if r.contains(e.position()):
                if page.game is not None and page.game.busy:
                    return page.ctx.toast(tr("Finish the round first"), "warn")
                if idx != page.games.index(page.game):
                    sfx.play("pick")
                    if idx in page.pick_map:
                        page.seg.set_index(page.pick_map.index(idx))
                    page._choose(idx)
                    self.parent().update()
                    for s in (self.parent().side_l, self.parent().side_r):
                        s.update()
                return

    def paintEvent(self, _e) -> None:
        page = self.page()
        if page is None:
            return
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        k = self.level
        p.setOpacity(k)
        p.translate((1 - k) * S(28) * (-1 if self.kind == "info" else 1), 0)
        r = QRectF(self.rect()).adjusted(S(2), S(2), -S(2), -S(2))
        paint_surface(p, r, S(DS.R_LG), 0.035)
        idx = page.games.index(page.game)
        name = page.NAMES[idx]
        if self.kind == "info":
            self._paint_info(p, r.adjusted(S(16), S(16), -S(16), -S(16)), page, name)
        else:
            self._paint_list(p, r.adjusted(S(12), S(14), -S(12), -S(12)), page, idx)

    def _paint_info(self, p: QPainter, r: QRectF, page, name: str) -> None:
        skill = name in SKILL_GAMES
        c = QPointF(r.center().x(), r.top() + S(46))
        cols = MINI_COLOURS.get(name) if skill else GAME_COLOURS.get(name, ("#8899AA", "#223344"))
        glow = QRadialGradient(c, S(70))
        glow.setColorAt(0, alpha(cols[0], 0.32))
        glow.setColorAt(1, alpha(cols[0], 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(glow)
        p.drawEllipse(c, S(70), S(70))
        if skill:
            paint_mini_badge(p, name, c, S(64))
        else:
            p.save()
            p.translate(c)
            p.scale(1.6, 1.6)
            paint_game_art(p, name, QPointF(0, 0))
            p.restore()
        y = c.y() + S(50)
        p.setPen(QColor(TEXT))
        p.setFont(font(17, QFont.Weight.ExtraBold))
        p.drawText(QRectF(r.left(), y, r.width(), S(26)), int(Qt.AlignmentFlag.AlignCenter), tr(name))
        y += S(26)
        p.setPen(QColor(GOLD_TEXT if not skill else MINT))
        p.setFont(font(9.5, QFont.Weight.Bold))
        p.drawText(QRectF(r.left(), y, r.width(), S(16)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("MINI GAME · FREE") if skill else tr("CASINO · COINS ONLY"))
        y += S(28)
        key = CASINO_KEYS.get(name)
        lines = list(HELP.get(key, ("", [], [], []))[3])[:4] if key in HELP else []
        if lines:
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(9, QFont.Weight.Black))
            p.drawText(QRectF(r.left(), y, r.width(), S(14)), int(Qt.AlignmentFlag.AlignVCenter), tr("HOW IT PAYS"))
            y += S(18)
            p.setFont(font(10, QFont.Weight.DemiBold))
            p.setPen(QColor(TEXT))
            fm = p.fontMetrics()
            for line in lines:
                text = tr(line)
                box = fm.boundingRect(0, 0, int(r.width() - S(12)), 2000, int(Qt.TextFlag.TextWordWrap), text)
                if y + box.height() > r.bottom() - S(110):
                    break
                p.setBrush(alpha(cols[0], 0.9))
                p.setPen(Qt.PenStyle.NoPen)
                p.drawEllipse(QPointF(r.left() + S(3), y + S(7)), S(2.4), S(2.4))
                p.setPen(QColor(TEXT))
                p.drawText(QRectF(r.left() + S(12), y, r.width() - S(12), box.height() + S(2)),
                           int(Qt.AlignmentFlag.AlignLeft | Qt.TextFlag.TextWordWrap), text)
                y += box.height() + S(8)
        log_ = [x for x in (getattr(page.ctx, "round_log", None) or []) if x[0] == name][-10:]
        net = sum(pay - bet for _n, bet, pay in log_)
        box = QRectF(r.left(), r.bottom() - S(92), r.width(), S(92))
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9, QFont.Weight.Black))
        p.drawText(QRectF(box.left(), box.top(), box.width(), S(14)), int(Qt.AlignmentFlag.AlignVCenter), tr("THIS SESSION"))
        p.setFont(font(20, QFont.Weight.ExtraBold))
        p.setPen(QColor(WIN if net > 0 else LOSE if net < 0 else TEXT))
        p.drawText(QRectF(box.left(), box.top() + S(16), box.width(), S(30)), int(Qt.AlignmentFlag.AlignVCenter),
                   ("+" if net > 0 else "−" if net < 0 else "") + coins_text(abs(net)))
        p.setFont(font(9.5, QFont.Weight.DemiBold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(box.left(), box.top() + S(46), box.width(), S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("{n} rounds", n=len(log_)) if log_ else tr("No round yet"))
        x = box.left()
        for _n, bet, pay in log_:                      # one dot per round: green won, red lost, grey even
            col = WIN if pay > bet else LOSE if pay < bet else TEXT_DIM
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor(col))
            p.drawRoundedRect(QRectF(x, box.top() + S(70), S(14), S(14)), S(4), S(4))
            x += S(18)
            if x + S(14) > box.right():
                break

    def _paint_list(self, p: QPainter, r: QRectF, page, idx: int) -> None:
        names = [page.NAMES[i] for i in page.pick_map]
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9, QFont.Weight.Black))
        p.drawText(QRectF(r.left() + S(4), r.top(), r.width(), S(14)), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("MINI GAMES") if names and names[0] in SKILL_GAMES else tr("CASINO GAMES"))
        top = r.top() + S(22)
        row_h = max(S(36), min(S(54), (r.bottom() - top) / max(1, len(names)) - S(4)))
        self._rows = []
        busy = page.game is not None and page.game.busy
        for k, (i, name) in enumerate(zip(page.pick_map, names)):
            row = QRectF(r.left(), top + k * (row_h + S(4)), r.width(), row_h)
            self._rows.append((row, i))
            on, hov = i == idx, k == self._hover and not busy
            cols = MINI_COLOURS.get(name) if name in SKILL_GAMES else GAME_COLOURS.get(name, ("#8899AA", "#223344"))
            p.setPen(QPen(alpha(cols[0], 0.7), S(1.4)) if on else Qt.PenStyle.NoPen)
            p.setBrush(alpha(cols[0], 0.20) if on else alpha("#FFFFFF", 0.06 if hov else 0.0))
            p.drawRoundedRect(row, S(12), S(12))
            c = QPointF(row.left() + S(10) + row_h * 0.36, row.center().y())
            if name in SKILL_GAMES:
                paint_mini_badge(p, name, c, row_h * 0.66)
            else:
                p.save()
                p.translate(c)
                p.scale(row_h / S(70), row_h / S(70))
                paint_game_art(p, name, QPointF(0, 0))
                p.restore()
            p.setOpacity(self.level * (0.5 if busy and not on else 1.0))
            p.setPen(QColor(TEXT if on or hov else TEXT_DIM))
            p.setFont(font(11.5, QFont.Weight.ExtraBold if on else QFont.Weight.Bold))
            p.drawText(QRectF(c.x() + row_h * 0.5, row.top(), row.right() - c.x() - row_h * 0.5 - S(6), row.height()),
                       int(Qt.AlignmentFlag.AlignVCenter), tr(name))
            p.setOpacity(self.level)


class OnlineBody(QWidget):
    """9.0: the online menu's frame: a top bar (wordmark, level, wallet, leave) and a rail of sections on the left;
    the page in use fills the rest."""

    def __init__(self, window) -> None:
        super().__init__(window)
        self.win = window
        self.tabbar = _NoTabs()
        self.to_ball = LeaveButton(self)
        self.stow = IconButton("rball", 30, tip=tr("Hide for now (click the R to bring it back)"), parent=self)
        self.xp = XPBar(window.ctx, self)
        self.xp.clicked.connect(window.open_levels)
        self.wallet = WalletChip(window.ctx, self)
        self.wallet.clicked.connect(lambda: window.goto("rewards"))
        self.rail = NavRail(window, self)
        self.rail.picked.connect(window.nav)
        self.switches = []                              # (8.0 had a switch over each half)
        self.host = QWidget(self)
        self.cover = LockCover(self.host)
        self.cover.hide()
        self.side_l = GameSide(window, "info", self)    # 9.1: beside a game while the menu is wide
        self.side_r = GameSide(window, "play", self)
        self.rail.raise_()                              # 9.0.1: the page host spans the full width; the rail sits on top
        self.to_ball.clicked.connect(window.ask_leave)
        self.stow.clicked.connect(window.collapse)
        self._press = None

    def set_tabs(self) -> None:
        self.win.relayout()

    def offset(self) -> int:
        return 0

    def header_rect(self) -> QRectF:
        return QRectF(0, 0, self.width(), S(HEAD_H))

    def dots_rect(self) -> QRect:
        return QRect(S(PAD), S(12), S(260), S(30))

    def release_drag(self) -> None: ...

    def side_w(self) -> int:
        """9.1: how much wider than usual the menu is on each side (while a game is played)."""
        return max(0, (self.width() - (S(RAIL_W) + col_width() + 2 * S(PAD))) // 2)

    def col_rect(self, i: int = 0) -> QRectF:
        """Where the page sits inside the body (in the middle of the room right of the rail)."""
        left = S(RAIL_W) + S(PAD) + self.side_w()
        return QRectF(left, S(HEAD_H), col_width(), self.height() - S(HEAD_H) - S(BOTTOM))

    def resizeEvent(self, _e) -> None:
        x = self.width() - S(PAD)
        for b in (self.to_ball, self.stow):
            x -= b.width()
            b.move(x, (S(HEAD_H) - b.height()) // 2)
            x -= S(8)
        self.wallet._fit()
        x -= self.wallet.width()
        self.wallet.move(x, (S(HEAD_H) - self.wallet.height()) // 2)
        right_end = x - S(14)
        left = S(PAD) + S(190)                     # clear of the wordmark, the online dot and the music dots
        xw = max(S(120), min(S(300), right_end - left))
        self.xp.setGeometry(int(right_end - xw), (S(HEAD_H) - self.xp.height()) // 2, int(xw), self.xp.height())
        self.rail.setGeometry(0, S(HEAD_H), S(RAIL_W), self.height() - S(HEAD_H) - S(BOTTOM))
        top = S(HEAD_H)
        self.host.setGeometry(0, top, self.width(), max(1, self.height() - top - S(BOTTOM)))
        sw, col = self.side_w(), self.col_rect()
        h = self.height() - top - S(BOTTOM) - S(10)
        self.side_l.setGeometry(int(S(RAIL_W) + S(PAD)), top + S(6), max(1, int(col.left() - S(RAIL_W) - S(PAD) - S(12))), h)
        self.side_r.setGeometry(int(col.right() + S(12)), top + S(6), max(1, int(self.width() - S(PAD) - col.right() - S(12))), h)
        for side in (self.side_l, self.side_r):
            side.set_level(min(1.0, sw / S(WIDE_SIDE)) if sw > S(120) else 0.0)
            side.raise_()
        self.rail.raise_()
        self.win.place_columns()
        if self.cover.isVisible():
            self.cover.setGeometry(self.host.rect())

    def mousePressEvent(self, e) -> None:
        e.accept()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        now = time.monotonic()
        playing = self.win.ctx.state.status is Status.PLAYING
        p.setFont(font(21, QFont.Weight.Black, 0.2))
        fm = p.fontMetrics()
        x, base = S(PAD) + S(4), QRectF(S(PAD) + S(4), 0, self.width(), S(HEAD_H))
        word = "Rubenium"
        full = fm.horizontalAdvance(word)
        split = x + full - fm.horizontalAdvance("ium")
        p.save()
        p.setClipRect(QRectF(0, 0, split, S(HEAD_H)))
        p.setPen(QColor(TEXT))
        p.drawText(base, int(Qt.AlignmentFlag.AlignVCenter), word)
        p.setClipRect(QRectF(split, 0, full, S(HEAD_H)))
        c1, c2 = cta_colors()
        g = QLinearGradient(QPointF(split, 0), QPointF(x + full, 0))
        g.setColorAt(0, c1)
        g.setColorAt(1, c2)
        p.setPen(QPen(QBrush(g), 1))
        p.drawText(base, int(Qt.AlignmentFlag.AlignVCenter), word)
        p.restore()
        x += full + S(10)
        pulse = 0.5 + 0.5 * math.sin(now * 3)
        off = self.win.ctx.online.offline
        col = alpha("#FFFFFF", 0.35) if off else QColor(MINT)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha(col, 0.22 + 0.2 * pulse))
        p.drawEllipse(QPointF(x + S(5), base.center().y()), S(6), S(6))
        p.setBrush(col)
        p.drawEllipse(QPointF(x + S(5), base.center().y()), S(3.4), S(3.4))
        x += S(16)
        for i in range(3 if playing else 0):          # 9.0: the bouncing dots only while a song plays
            lift = math.sin(now * 5.0 - i * 0.9) * S(2.6) if playing else 0.0
            p.setBrush(alpha(ui.accent, 1.0 if playing else 0.3))
            p.drawEllipse(QPointF(x + i * S(6), base.center().y() + S(4) - lift), S(1.7), S(1.7))
        p.setPen(QPen(alpha("#FFFFFF", 0.06), 1))          # hairlines under the bar and beside the rail
        p.drawLine(QPointF(S(PAD), S(HEAD_H) - 0.5), QPointF(self.width() - S(PAD), S(HEAD_H) - 0.5))
        p.drawLine(QPointF(S(RAIL_W) - 0.5, S(HEAD_H) + S(10)), QPointF(S(RAIL_W) - 0.5, self.height() - S(BOTTOM) - S(10)))


class _Focus(QObject):
    """Clicking anywhere in a column makes it the one toasts, confirmations and reloads belong to."""

    def __init__(self, win, key: str) -> None:
        super().__init__(win)
        self.win, self.key = win, key

    def eventFilter(self, obj, e) -> bool:
        if e.type() in (QEvent.Type.MouseButtonPress, QEvent.Type.Wheel) and self.win.current != self.key:
            self.win.focus(self.key, quiet=True)
        return False


def _make_class():
    """Built on first use (MainWindow lives in window.py, which imports this file's neighbours)."""
    pass

    class OnlineWindow(MainWindow):
        def __init__(self, ctx, main) -> None:
            self.main = main
            self.settings_open = False
            self._was_down = False
            self.phase = "hidden"                  # hidden / dropping / shown / stowed / leaving
            self.stage = None                      # 5.0: the garage doors / OG chest over the menu
            self._stage_mode = None
            self._filters: dict = {}
            super().__init__(ctx)
            self.ball.hide()
            self.body.hide()
            self.body.deleteLater()
            self.body = OnlineBody(self)
            self.body.hide()
            for w in (self.toast_w, self.confirm_w, self.busy_w):
                w.raise_()
            want = ctx.cfg["online_tab"]
            self.current = want if want in ("hub", "games", "rewards", "stats", "leaders", "themes", "friends", "settings") else "hub"
            self.drop = Tween(self, 0.0, self._on_drop, QEasingCurve.Type.OutBack)
            self.drop.finished.connect(self._drop_done)
            self.suck = Tween(self, 0.0, self.update, QEasingCurve.Type.InCubic)
            self.suck.finished.connect(self._suck_done)
            self._pm = None
            self._leave_then = None
            self.ball.save_position = lambda: None
            self._watch = QTimer(self)
            self._watch.setInterval(60)
            self._watch.timeout.connect(self._watch_outside)
            self.wide = Tween(self, 0.0, self._wide_step, QEasingCurve.Type.InOutCubic)    # 9.1: the wide game view
            self.wide.finished.connect(lambda: self._place() if self.phase == "shown" else None)
            self._wide_t = QTimer(self)
            self._wide_t.setInterval(200)
            self._wide_t.timeout.connect(self._wide_watch)
            self._wide_t.start()

        # -------------------------------------------------------------- what is shown
        def max_cols(self) -> int:
            return 1

        def panes(self) -> list:
            return [self.current]

        def tab_keys(self) -> list:
            return [getattr(self, "current", "hub")]

        def nav(self, key: str) -> None:
            """9.0: a rail entry was picked: its page, on its own (Shop and Collection are two parts of one page)."""
            if claim_blocked(self.ctx):
                return
            ctx = self.ctx
            if key in ("shop", "collection", "trophies"):
                ctx.coll_trophies = key == "trophies"
                if key == "trophies":
                    ctx.shop_tab, ctx.shop_badge, ctx.shop_case, ctx.shop_design, ctx.inv_pick = 2, None, None, None, ""
                tab = int(getattr(ctx, "shop_tab", 1) or 0)
                want = SHOP_GET if key == "shop" else SHOP_MINE
                if tab not in want:
                    ctx.shop_tab = want[0]
                    ctx.shop_badge = ctx.shop_case = ctx.shop_design = None
                    ctx.inv_pick = ""
                if self.current == "themes":
                    sfx.play("pick")
                    self.body.rail.update()
                    return self.reload_page("themes")
                key = "themes"
            ctx.back_to = None
            if key != "games" and self.current == "games" and nav_of(ctx, "games") == "rewards":
                ctx.games_sub = None                           # a reward was open in the games page: closed
                ctx.quests_open = ctx.mini_open = ctx.park_open = False
                ctx.casino = False
            if key == "games" and self.current == "games" and (ctx.casino or getattr(ctx, "games_sub", None)
                                                                or getattr(ctx, "quests_open", False)):
                ctx.games_sub = None                           # Play again: back to the lobby
                ctx.quests_open = ctx.mini_open = ctx.park_open = False
                if ctx.casino:
                    return ctx.leave_casino()
                return self.reload_page("games")
            self.set_pane(0, key)

        def set_pane(self, index: int, key: str) -> None:
            """Show `key` (the index is kept for the callers: there is one page at a time)."""
            if key == self.current and key in self.pages:
                return
            old = self.current
            self.current = key
            if key in ONLINE_KEYS or key in ("hub", "rewards", "stats", "leaders"):
                self.ctx.cfg["online_tab"] = key
            sfx.play("pick")
            if old in self.pages and old != key:
                self._drop_page(old)
            self.relayout()
            self.body.resizeEvent(None)
            self.body.rail.update()
            self.body.update()

        def open_leaders(self) -> None:
            """9.1: the leaderboards have their own place on the rail."""
            if self.current != "leaders":
                return self.nav("leaders")
            self.reload_page("leaders")

        def open_levels(self) -> None:
            """The level in the top bar: Collection > Inventory > Levels."""
            self.ctx.shop_tab = 5
            self.ctx.inv_tab = "levels"
            if self.current != "themes":
                return self.set_pane(0, "themes")
            self.body.rail.update()
            self.reload_page("themes")

        def showing(self, key: str) -> bool:
            return self.expanded and key in self.pages and key in self.tab_keys()

        def _area(self) -> QRect:
            c = self.main.ball.center if self.main is not None else QPoint(0, 0)
            return work_area(c)

        # -------------------------------------------------------------- geometry
        def _wide_extra(self, wa) -> int:
            """9.1: while a game is played the menu grows on both sides (as far as the screen allows)."""
            tw = getattr(self, "wide", None)
            if tw is None or tw.level <= 0:
                return 0
            base = S(RAIL_W) + col_width() + 2 * S(PAD) + 2 * S(GLOW)
            side = wa.width() if (getattr(self.ctx, "kart_wide", False) or getattr(self.ctx, "aerial_wide", False)) \
                else 2 * S(WIDE_SIDE)                                   # 9.3.2: a race (or a match) takes it all
            room = max(0, min(side, wa.width() - base - S(40)))
            return 0 if room < 2 * S(150) else int(room * tw.level) // 2 * 2

        def _wide_step(self) -> None:
            if self.phase != "shown":
                return
            self._place(sparks=False)
            self._layout_body()
            self.body.resizeEvent(None)
            self.update()

        def _wide_watch(self) -> None:
            """Wide while a game (not the free spin) is on screen; back to normal anywhere else."""
            ctx = self.ctx
            want = (self.phase == "shown" and self.current == "games" and bool(ctx.casino)
                    and ctx.cfg["game"] != GamesPage.PICKER) or bool(getattr(ctx, "kart_wide", False)) \
                or bool(getattr(ctx, "aerial_wide", False))
            if want != getattr(self, "_wide_on", False):
                self._wide_on = want
                room = self._area().width() - (S(RAIL_W) + col_width() + 2 * S(PAD) + 2 * S(GLOW)) - S(40)
                ctx.wide_games = want and room >= 2 * S(150)          # (a small screen keeps the normal view)
                entry = self.pages.get("games")
                page = entry[1] if entry else None
                seg = getattr(page, "seg", None)
                if seg is not None and getattr(page, "game", None) is not None:
                    try:
                        seg.setVisible(not ctx.wide_games and page.NAMES[page.games.index(page.game)] != "Free spin")
                    except (RuntimeError, ValueError):
                        pass
                self.wide.to(1.0 if want else 0.0, 520)

        def _place(self, ball=None, card_tl=None, sparks: bool = True) -> None:
            wa = self._area()
            cw, g = col_width(), S(GLOW)
            w = S(RAIL_W) + cw + 2 * S(PAD) + self._wide_extra(wa)
            h = int(min(wa.height() - S(18), S(HEAD_H + BOTTOM) + S(1000)))
            x = wa.center().x() - w // 2
            y = wa.top() + S(6)
            banner = QRect(x, y, w, h)
            self.setGeometry(banner.adjusted(-g, -g, g, g))
            self._max_l = QRectF(g, g, w, h)
            self._ball_l = QRectF(g + w / 2 - BD() / 2, g, BD(), BD())
            self.card_max_h = h
            self.card_pos = QPoint(x, y)
            if sparks or not getattr(self, "_sparks", None):
                self._sparks = extras.theme_sparkles(self.ctx.theme(), w, h, S(160))

        def _save_card(self) -> None: ...
        def save_position(self) -> None: ...
        def _restore_position(self) -> None: ...

        def reset_position(self) -> None:
            self.ctx.leave_online(after=self.main.reset_position)

        def _card_rect(self) -> QRectF:
            m = self._max_l
            lift = (1.0 - self.drop.level) * (m.bottom() + S(40))
            return m.translated(0, -lift)

        def _shape(self):
            return self._card_rect(), S(ui.radius)

        def _card_h(self, key: str) -> float:
            return float(self._max_l.height())

        def card_global(self) -> QRect:
            """The column in use: small windows (preview drawer, dialogs) open next to it, not the whole banner."""
            keys = self.tab_keys()
            if self.current in keys and self.body is not None:
                r = self.body.col_rect(0)
                tl = self.body.mapToGlobal(r.topLeft().toPoint())
                return QRect(tl, r.size().toSize())
            c = self._card_rect()
            return QRect(self.mapToGlobal(c.topLeft().toPoint()), c.size().toSize())

        def _layout_body(self) -> None:
            c = self._card_rect()
            self.body.setGeometry(int(round(c.left())), int(round(c.top())), int(c.width()), int(round(c.height())))
            st = getattr(self, "stage", None)
            if st is not None:
                try:
                    st.setGeometry(self.body.geometry())
                except RuntimeError:
                    self.stage = None
            ast = getattr(self.ctx, "aerial_stage", None)            # Rubenium League sits over the menu too
            if ast is not None:
                try:
                    ast.setGeometry(self.body.geometry())
                except RuntimeError:
                    self.ctx.aerial_stage = None
            lk = getattr(self.ctx, "kart_link", None)                # 9.3.2: the race sits over the menu
            kw = getattr(lk, "win", None) if lk is not None else None
            if kw is not None:
                try:
                    kw.setGeometry(self.body.geometry())
                except RuntimeError:
                    pass

        def place_columns(self) -> None:
            host = self.body.host
            entry = self.pages.get(self.current)
            if entry is not None:
                r = self.body.col_rect(0)
                entry[0].setGeometry(int(r.left()), 0, col_width(), host.height())

        # -------------------------------------------------------------- columns
        def page_w(self) -> int:
            return S(CARD_W - 2 * PAD + ONLINE_EXTRA)

        def _ensure_page(self, key: str):
            pass
            new = key not in self.pages
            with wide_pages():                          # 4.1: its pages are made for the wider halves
                entry = super()._ensure_page(key)
            if new:
                entry[0].no_stretch = True              # a column is taller than its page: the page keeps its size
                entry[0].resizeEvent(None)
                f = _Focus(self, key)
                self._filters[key] = f
                entry[0].installEventFilter(f)
                for child in entry[0].findChildren(QWidget):
                    child.installEventFilter(f)
            return entry

        def relayout(self) -> None:
            """(Re)build the columns: pages that are on show are made, the others dropped."""
            if self.phase in ("hidden",):
                return
            keys = self.tab_keys()
            for key in list(self.pages):
                if key not in keys and key != self.current:
                    self._drop_page(key)
            if self.current not in keys:
                self.current = keys[0]
            old = self.width()
            self._place()
            if self.width() != old:
                self._layout_body()
            for key in keys:
                new = key not in self.pages
                sa, page, _h = self._ensure_page(key)
                sa.show()
                if new and self.phase == "shown":
                    page.on_show()
            self.body.resizeEvent(None)
            self.body.update()
            self.update()

        def tabs_changed(self) -> None:
            self.relayout()

        def focus(self, key: str, quiet: bool = False) -> None:
            if key not in self.tab_keys():
                return
            if key != self.current:
                self.current = key
                if key in ONLINE_KEYS:
                    self.ctx.cfg["online_tab"] = key
                if not quiet:
                    sfx.play("pick")
                self.body.update()
                self.body.rail.update()

        def goto(self, key: str) -> None:
            if claim_blocked(self.ctx):
                return
            if key in ("hub", "games", "rewards", "stats", "leaders", "themes", "friends", "giveaway", "settings", "admin"):
                if key not in self.tab_keys():
                    self.set_pane(0, key)
                if not self.expanded:
                    self.current = key
                    return self.expand()
                return self.focus(key)
            # a part of the small menu (Home, Lyrics, Screen...): leave online mode, then open it there
            self.ctx.leave_online(after=lambda: self.main.goto(key))

        def toggle_settings(self) -> None:
            self.goto("settings")

        def reload_page(self, key: str = None) -> None:
            key = key or self.current
            if GamePerf.defer(self.ctx, self, key):          # 6.0: never rebuilt in the middle of a Wave Rush run
                return
            if not self.expanded or key not in self.tab_keys():
                if key in self.pages:
                    self._drop_page(key)
                return
            old = self.pages.get(key)
            offset = old[0].offset() if old else 0.0
            self._drop_page(key)
            sa, page, _h = self._ensure_page(key)
            self.place_columns()
            sa.show()
            sa._target = min(offset, max(0.0, sa.max_offset()))
            sa._pos.jump(sa._target)
            page.on_show()
            QTimer.singleShot(0, self.sync_lock)

        def page(self):
            entry = self.pages.get(self.current)
            return entry[1] if entry else None

        def _focus_rect(self) -> QRectF:
            """The focused column inside this window: toasts and questions show over it."""
            keys = self.tab_keys()
            c = self._card_rect()
            if self.current in keys:
                r = self.body.col_rect(0)
                return QRectF(c.left() + r.left(), c.top() + r.top(), r.width(), r.height())
            return c

        def toast(self, text: str, kind: str = "ok") -> None:
            if self.phase == "shown":
                self.toast_w.show_text(text, kind, self._focus_rect())

        def confirm(self, text: str, on_yes, yes: str = "", no: str = "", persistent: bool = False, on_no=None) -> None:
            if self.phase == "shown":
                self.toast_w.hide()
                self.confirm_w.ask(text, on_yes, self._focus_rect(), yes, no, persistent, on_no)

        def show_busy(self, text: str) -> None:
            if self.phase == "shown":
                self.toast_w.hide()
                self.confirm_w.hide()
                self.busy_w.start(text, self._focus_rect())

        def sync_lock(self) -> None:
            """Offline, locked or out of date: the whole banner is covered (every part of it is online)."""
            ctx = self.ctx
            cover = self.body.cover
            mode = ("offmode" if ctx.cfg["offline_mode"] and ctx.online.logged_in() else
                    "locked" if ctx.econ.live.get("locked") and not ctx.econ.admin else
                    "lockdown" if ctx.econ.lockdown_cover() else
                    "offline" if ctx.online.logged_in() and ctx.online.offline else "")
            on = bool(mode) and self.expanded and self.phase == "shown"
            if on and mode != cover.mode:
                cover.set_mode(mode, ctx.install_update if mode == "update" else
                               (ctx.online.probe if mode == "offline" else
                                (lambda: ctx.set_offline_mode(False)) if mode == "offmode" else None))
            if on:
                cover.setGeometry(self.body.host.rect())
                cover.resizeEvent(None)
                if not cover.isVisible():
                    cover.take(self.body.host)
                cover.show()
                cover.raise_()
            elif cover.isVisible():
                cover.hide()

        def rebuild(self) -> None:
            """Size or language changed: rebuild every column."""
            for key in list(self.pages):
                self._drop_page(key)
            self.fade.jump(1.0)
            self.chrome.jump(1.0)
            for w in (self.toast_w, self.confirm_w):
                w.deleteLater()
            self.body.deleteLater()
            pass
            _tiles.clear()
            self.body = OnlineBody(self)
            self.toast_w = Toast(self)
            self.confirm_w = Confirm(self)
            self.busy_w.raise_()
            if self.phase in ("shown", "dropping"):
                self._place()
                self._layout_body()
                self.body.show()
                self.relayout()
            self.update()

        def theme_changed(self) -> None:
            m = self._max_l
            self._sparks = extras.theme_sparkles(self.ctx.theme(), m.width(), m.height(), S(160))
            self._retime()
            self.update()
            for page in self.each_page():
                page.update()

        # the banner never moves with the mouse and its menu row never hides
        def begin_drag(self, grab) -> None: ...
        def end_drag(self) -> None: ...
        def _chrome_allowed(self) -> bool:
            return False

        def _on_morph(self) -> None:
            self.update()

        # -------------------------------------------------------------- in and out
        def open(self) -> None:
            """Drop down from the top of the screen."""
            self.phase = "dropping"
            self.expanded = True
            self.ctx.cfg["card_open"] = True
            self._place()
            self.morph.jump(1.0)
            self.chrome.jump(1.0)
            self._anim_in = self._anim_pick()
            self.drop.setEasingCurve(QEasingCurve.Type.Linear if self._anim_in else QEasingCurve.Type.OutBack)
            self.drop.jump(0.0)
            self._layout_body()
            self.body.show()
            self.relayout()
            for key in self.tab_keys():
                sa, page, _ = self._ensure_page(key)
                page.on_show()
            self._layout_body()
            self._pm = snapshot(self.body)
            self._stage_mode = self.ctx.door_mode() if hasattr(self.ctx, "door_mode") else None
            if self._stage_mode:                           # 5.0: the doors are shut while it drops, nothing shows
                self._pm = door_pixmap(self.body.size(), ui.accent)
            self.body.hide()
            self.show()
            if win.IS_WIN:
                win.set_topmost(int(self.winId()))
            self.drop.to(1.0, 1100 if self._anim_in else 620)
            self._retime()
            self.ctx.on_visibility()

        def _on_drop(self) -> None:
            if self.phase in ("dropping", "stowing"):
                self.update()

        def _drop_done(self) -> None:
            if self.phase == "dropping":
                self.phase = "shown"
                self._anim_in = None
                self._pm = None
                self._layout_body()
                self.body.show()
                self.body.resizeEvent(None)
                mode = getattr(self, "_stage_mode", None)
                self._stage_mode = None
                if mode and getattr(self, "stage", None) is None:     # 5.0: the doors open now, never before
                    try:
                        self.stage = DoorStage(self, mode)
                        self.stage.setGeometry(self.body.geometry())
                        self.stage.show()
                        self.stage.raise_()
                        for w in (self.toast_w, self.confirm_w, self.busy_w):
                            w.raise_()
                        self.stage.setFocus()
                        self.ctx.door_played(mode)
                    except Exception:  # noqa: BLE001
                        log.exception("online doors failed")
                        self.stage = None
                self._idle.stop()
                QTimer.singleShot(0, self.sync_lock)
                self._was_down = True
                self._watch.start()
                sfx.play("on")
                shake(self, 5.0, 300)
                fx = getattr(self.ctx, "_fx", None)
                if fx is not None:
                    try:
                        c = self.mapToGlobal(self._card_rect().center().toPoint())
                        bottom = QPoint(c.x(), self.mapToGlobal(self._card_rect().bottomLeft().toPoint()).y())
                        spark_burst(fx, fx.local(bottom), ui.accent, n=34, reach=180)
                    except RuntimeError:
                        pass
            elif self.phase == "stowing":
                self.phase = "stowed"
                self.hide()
                self._show_stowed_ball()

        def expand(self) -> None:
            if self.phase == "stowed":
                self.ball.hide()
                self.open()

        def collapse(self) -> None:
            """4.0: hide for now. The banner shoots up into a wide black hole at the top of the screen, which closes
            on the R; click the R to bring the banner back down. Also when you click outside it (on the desktop or a
            game)."""
            if self.phase != "shown":
                return
            if claim_blocked(self.ctx, minimize=True):
                return
            self._close_sheet()
            self.toast_w.hide()
            self.confirm_w.hide()
            self.drawer.close_now()
            self._watch.stop()
            self._pm = snapshot(self.body)
            self.body.hide()
            self.expanded = False
            self.ctx.cfg["card_open"] = False
            self.phase = "stowing"
            self._anim = self._anim_pick()
            self.suck.setEasingCurve(QEasingCurve.Type.Linear)
            self.suck.jump(0.0)
            self.suck.to(1.0, 1250 if self._anim else 700)
            for page in self.each_page():
                page.on_hide()
            sfx.play("off")
            self.ctx.on_visibility()

        def _show_stowed_ball(self) -> None:
            wa = self._area()
            d = BD()
            self.ball.set_center(QPoint(wa.center().x(), wa.top() + d // 2 + S(10)))
            self.ball.show()
            self.ball.appear.jump(0.6)
            self.ball.appear.to(1.0, 260)
            if win.IS_WIN:
                win.set_topmost(int(self.ball.winId()))

        def pick_file(self, title: str, pattern: str) -> str:
            """4.5: choosing a file (a profile picture, say) never sends the banner away or leaves it blank: it steps
            aside while the dialog is open, then comes back exactly as it was."""
            from PyQt6.QtWidgets import QFileDialog
            if win.fullscreen_state() == 2:
                self.toast(tr("Leave your game first"), "warn")
                return ""
            self.modal = True
            self._watch.stop()
            self.hide()
            try:
                path, _ = QFileDialog.getOpenFileName(None, title, "", pattern)
            finally:
                self.modal = False
                self._was_down = True
                self.heal(force=True)
                if self.phase == "shown":
                    self._watch.start()
            return path or ""

        def heal(self, force: bool = False) -> None:
            """4.5: never stuck half drawn: shown means the banner, its pages and its place on the screen are right."""
            if getattr(self, "modal", False):
                return
            if self.phase == "shown":
                if not self.isVisible():
                    self.show()
                    if win.IS_WIN:
                        win.set_topmost(int(self.winId()))
                wa = self._area()
                if force or not wa.contains(self.geometry().adjusted(S(GLOW), S(GLOW), -S(GLOW), -S(GLOW))) \
                        or abs(self.drop.level - 1.0) > 0.01:
                    self.drop.jump(1.0)
                    self._place()
                    self._pm = None
                if force or not self.body.isVisible() or self.body.geometry().height() < S(100):
                    self._pm = None
                    self._layout_body()
                    self.body.show()
                    self.relayout()
                self.update()
            elif self.phase == "stowed" and self.isVisible():
                self.hide()
                self._show_stowed_ball()

        def _mouse_guard(self) -> None:
            """4.5: while the banner is open, every click on it is for Rubenium, never for the game behind."""
            if self.phase in ("shown", "dropping") and not getattr(self.ctx, "game_lock", False):
                if self._through:
                    for w in (self, self.drawer):
                        hwnd = native_hwnd(w)
                        if hwnd:
                            win.set_click_through(hwnd, False)
                    self._through = False
                return
            super()._mouse_guard()

        def _watch_outside(self) -> None:
            """A click anywhere outside the banner (the desktop, a game) sends it up into the R. 4.7: not in game
            mode, where every click is for the game and the banner just stays as it is."""
            if self.phase != "shown" or getattr(self, "modal", False) or getattr(self.ctx, "game_lock", False) \
                    or self.ctx.cfg.get("online_stay_open", False) \
                    or getattr(self.ctx, "kart_wide", False) or getattr(self.ctx, "aerial_wide", False):
                self._was_down = False
                return
            down = win.key_down(0x01) if win.IS_WIN else False
            if down and not self._was_down:
                from PyQt6.QtGui import QCursor
                from PyQt6.QtWidgets import QApplication
                pos = QCursor.pos()
                inside = self.frameGeometry().contains(pos) or QApplication.topLevelAt(pos) is not None
                if not inside and getattr(self, "sheet", None) is None and not self.confirm_w.isVisible():
                    self.collapse()
            self._was_down = down

        def toggle(self) -> None:
            if self.phase == "shown":
                self.collapse()
            elif self.phase == "stowed":
                self.expand()

        def ask_leave(self) -> None:
            self.ctx.leave_online()

        def start_leaving(self, then) -> None:
            """4.0: leaving is calm: the banner lifts away and fades in one smooth move, then the R floats down."""
            self._leave_then = then
            self._close_sheet()
            self.toast_w.hide()
            self.confirm_w.hide()
            self.busy_w.hide()
            self.drawer.close_now()
            self._watch.stop()
            if self.phase == "stowed":
                self.ball.hide()
                self.phase = "leaving"
                return self._suck_done()
            for page in self.each_page():
                page.on_hide()
            self._pm = snapshot(self.body)
            self.body.hide()
            self.phase = "leaving"
            self.expanded = False
            self.suck.setEasingCurve(QEasingCurve.Type.InOutCubic)
            self.suck.jump(0.0)
            self.suck.to(1.0, 420)
            sfx.play("off")

        def _suck_done(self) -> None:
            if self.phase == "stowing":
                self.phase = "stowed"
                self.hide()
                self._pm = None
                return self._show_stowed_ball()
            if self.phase != "leaving":
                return
            self.phase = "hidden"
            self.hide()
            self.ball.hide()
            self._pm = None
            for key in list(self.pages):
                self._drop_page(key)
            then, self._leave_then = self._leave_then, None
            if then is not None:
                then()


        # -------------------------------------------------------------- painting
        def paintEvent(self, _e) -> None:
            pass
            p = QPainter(self)
            p.setRenderHint(QPainter.RenderHint.Antialiasing)
            p.setRenderHint(QPainter.RenderHint.SmoothPixmapTransform)
            now = time.monotonic()
            if self.phase == "leaving":
                return self._paint_leave(p)
            if self.phase == "stowing":
                return self._paint_stow(p, now)
            if self.phase == "dropping" and getattr(self, "_anim_in", None) is not None and self._pm is not None:
                try:
                    return self._paint_special(p, now, 1.0 - self.drop.level, self._anim_in)
                except Exception:  # noqa: BLE001
                    log.exception("animation failed: back to the simple drop")
                    self._anim_bad, self._anim_in = True, None
                    p.setOpacity(1.0)
                    p.setClipping(False)
            shape, radius = self._shape()
            level = self.ctx.glow_level()
            path = paint_shape(p, self.ctx, shape, radius, level, self.devicePixelRatioF())
            th = self.ctx.theme()
            if th["layers"] or self._sparks or ui.accent2 is not None:
                m = self._max_l
                p.save()
                p.setClipPath(path)
                pm = extras.theme_pattern(th, int(m.width()), int(m.height()), self._accent_to, self.devicePixelRatioF(),
                                          ui.scale, S(160))
                if pm is not None:
                    p.drawPixmap(shape.topLeft(), pm)
                if self._sparks:
                    extras.paint_sparkles(p, self._sparks, shape.left(), shape.top(), ui.accent, now, ui.scale)
                p.restore()
            if self._pm is not None:
                p.save()
                p.setClipPath(path)
                p.drawPixmap(shape.topLeft(), self._pm)
                p.restore()
            paint_edge(p, self.ctx, shape, radius, level)

        def _banner(self, p: QPainter, m: QRectF, opacity: float) -> None:
            pass
            p.setOpacity(max(0.0, opacity))
            path = paint_shape(p, self.ctx, m, S(ui.radius), self.ctx.glow_level() * opacity, self.devicePixelRatioF())
            if self._pm is not None:
                p.save()
                p.setClipPath(path)
                p.drawPixmap(m, self._pm, QRectF(self._pm.rect()))
                p.restore()
            p.setOpacity(1.0)

        def _paint_leave(self, p: QPainter) -> None:
            """Lifts, shrinks very slightly and fades: no spinning."""
            k = self.suck.level
            m = self._max_l
            s = 1.0 - 0.04 * k
            lift = S(70) * k * k
            w, h = m.width() * s, m.height() * s
            box = QRectF(m.center().x() - w / 2, m.top() - lift + (m.height() - h) * 0.15, w, h)
            self._banner(p, box, 1.0 - k)

        def _anim_pick(self):
            """6.9: the animation you wear, when it is yours and has not bugged out: (design, finish) or None."""
            try:
                ec = self.ctx.econ
                if getattr(self, "_anim_bad", False) or not ec.ready:
                    return None
                if ANIMS_LOCKED:
                    return None
                it = ec.worn("anim")
                sp = anim_split(it) if it else None
                if sp and ec.can_wear(it):
                    return sp
            except Exception:  # noqa: BLE001
                log.exception("animation lookup failed")
            return None

        def _paint_special(self, p: QPainter, now: float, k: float, anim) -> None:
            """6.9: one of the Mythic animations. k: 0 = the banner, 1 = only the ball."""
            m = self._max_l
            hole = QPointF(m.center().x(), m.top() + S(30))
            d = float(BD())
            dpr = self.devicePixelRatioF()

            def banner(box: QRectF, op: float, light: bool = False) -> None:
                if self._pm is None:
                    return
                op = max(0.0, min(1.0, op))
                if light:
                    p.setOpacity(op)
                    p.fillRect(box, QColor(12, 14, 18))
                    p.drawPixmap(box, self._pm, QRectF(self._pm.rect()))
                    p.setOpacity(1.0)
                else:
                    self._banner(p, box, op)

            def ball(pos: QPointF, size: float, op: float) -> None:
                size = max(2.0, size)
                shape = QRectF(pos.x() - size / 2, pos.y() - size / 2, size, size)
                p.setOpacity(max(0.0, min(1.0, op)))
                level = self.ctx.glow_level(0.6)
                paint_shape(p, self.ctx, shape, size / 2, level, dpr)
                paint_ball_face(p, self.ctx, shape, 1.0)
                paint_edge(p, self.ctx, shape, size / 2, level)
                p.setOpacity(1.0)
            paint_anim(p, anim[0], anim[1], k, now, m, hole, d, banner, ball)

        def _skip_anim(self) -> bool:
            """6.9: a click or Esc ends a special animation right now (in case one is slow or bugs out)."""
            if self.phase == "stowing" and getattr(self, "_anim", None) is not None:
                self.suck.stop()
                self.suck.jump(1.0)
                self._suck_done()
                return True
            if self.phase == "dropping" and getattr(self, "_anim_in", None) is not None:
                self.drop.stop()
                self.drop.jump(1.0)
                self._drop_done()
                return True
            return False

        def mousePressEvent(self, e) -> None:
            if self._skip_anim():
                return
            super().mousePressEvent(e)

        def keyPressEvent(self, e) -> None:
            if e.key() == Qt.Key.Key_Escape and self._skip_anim():
                return
            super().keyPressEvent(e)

        def _paint_stow(self, p: QPainter, now: float) -> None:
            """The simple default: the banner floats up into nothing and fades; the R appears where it went. (Coming
            back it just drops down.) A Mythic animation replaces this when one is worn."""
            k = self.suck.level
            m = self._max_l
            anim = getattr(self, "_anim", None)
            if anim is not None:
                try:
                    return self._paint_special(p, now, k, anim)
                except Exception:  # noqa: BLE001
                    log.exception("animation failed: back to the simple one")
                    self._anim_bad, self._anim = True, None
                    p.setOpacity(1.0)
                    p.setClipping(False)
            e = min(1.0, k / 0.72)
            e = e * e * (3 - 2 * e)
            s = 1.0 - 0.06 * e
            w, h = m.width() * s, m.height() * s
            box = QRectF(m.center().x() - w / 2, m.top() - S(110) * e * e + (m.height() - h) * 0.3, w, h)
            self._banner(p, box, (1.0 - e) ** 1.2)
            if k > 0.55:
                r_k = _e3_safe((k - 0.55) / 0.45)
                hole = QPointF(m.center().x(), m.top() + S(30))
                d = BD() * (0.75 + 0.25 * r_k)
                shape = QRectF(hole.x() - d / 2, hole.y() - d / 2, d, d)
                p.setOpacity(r_k)
                level = self.ctx.glow_level(0.6)
                paint_shape(p, self.ctx, shape, d / 2, level, self.devicePixelRatioF())
                paint_ball_face(p, self.ctx, shape, 1.0)
                paint_edge(p, self.ctx, shape, d / 2, level)
                p.setOpacity(1.0)

        def _tick(self) -> None:
            if self.phase in ("leaving", "stowing") or self.drop.busy:
                return self.update()
            super()._tick()

    return OnlineWindow


_CLASS = None


def online_window(ctx, main):
    global _CLASS
    if _CLASS is None:
        _CLASS = _make_class()
    return _CLASS(ctx, main)


# ================================================================ entering and leaving (driven by the app)
def fly_up(ctx, main, then) -> None:
    """The ball rises from where it is to the middle of the top of the screen and keeps going, off screen."""
    screen = QGuiApplication.screenAt(main.ball.center) or QGuiApplication.primaryScreen()
    fx = FxOverlay(ctx, screen)
    ctx._fx = fx
    start = fx.local(main.ball.center)
    geo = screen.geometry()
    top = QPointF(geo.width() / 2, -BD() * 1.2)
    mid = QPointF(geo.width() / 2, S(60))
    d = BD()
    trail: list = []
    main.ball.hide()
    sfx.play("on")

    def paint(p: QPainter, k: float, now: float) -> None:
        e = k * k * (3 - 2 * k)
        # a curve: up and to the middle, then straight up out of the screen
        q = 1 - e
        x = q * q * start.x() + 2 * q * e * mid.x() + e * e * top.x()
        y = q * q * start.y() + 2 * q * e * (start.y() * 0.35 + mid.y() * 0.65) + e * e * top.y()
        pos = QPointF(x, y)
        trail.append((pos, now))
        while trail and now - trail[0][1] > 0.28:
            trail.pop(0)
        p.setPen(Qt.PenStyle.NoPen)
        for tp, tt in trail:                          # a streak of light behind it
            age = (now - tt) / 0.28
            col = alpha(mix(ui.accent, QColor("#FFFFFF"), 0.3), 0.35 * (1 - age))
            p.setBrush(col)
            r = d * 0.5 * (1 - age * 0.7)
            p.drawEllipse(tp, r, r)
        s = 1.0 + 0.25 * math.sin(k * math.pi) - 0.35 * k * k
        fx.paint_ball(p, pos, d * s)
    fx.add(0.72, paint, done=lambda: _arrived(ctx, fx, QPointF(geo.width() / 2, 0), then))
    spark_burst(fx, start, ui.accent, n=18, reach=70, dur=0.5)


def _arrived(ctx, fx, at, then) -> None:
    ring_wave(fx, at + QPointF(0, S(4)), ui.accent, reach=260, dur=0.6)
    spark_burst(fx, at + QPointF(0, S(8)), ui.accent, n=30, reach=160, dur=0.7)

    def flash(p: QPainter, k: float, _now: float) -> None:
        g = QRadialGradient(at, S(420))
        g.setColorAt(0, alpha(ui.accent, 0.45 * (1 - k)))
        g.setColorAt(1, alpha(ui.accent, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawEllipse(at, S(420), S(240))
    fx.add(0.45, flash)
    then()


def float_down(ctx, main, then) -> None:
    """The R comes back down from the top of the screen, swaying a little, and lands where the ball lives."""
    main.ball.clamp()                                  # the ball comes back exactly where it left from
    screen = QGuiApplication.screenAt(main.ball.center) or QGuiApplication.primaryScreen()
    fx = getattr(ctx, "_fx", None)
    try:
        if fx is None or not fx.isVisible():
            raise RuntimeError
        fx.geometry()
    except RuntimeError:
        fx = FxOverlay(ctx, screen)
        ctx._fx = fx
    geo = screen.geometry()
    end = fx.local(main.ball.center)
    start = QPointF(geo.width() / 2, S(40))
    d = BD()

    def paint(p: QPainter, k: float, now: float) -> None:
        e = 1 - (1 - k) ** 3
        x = start.x() + (end.x() - start.x()) * e + math.sin(k * math.pi * 3) * S(18) * (1 - k)
        y = start.y() + (end.y() - start.y()) * e
        appear = min(1.0, k / 0.25)
        fx.paint_ball(p, QPointF(x, y), d * (0.55 + 0.45 * appear), appear)
        if int(now * 30) % 2 == 0:
            pass

    def landed() -> None:
        ring_wave(fx, end, ui.accent, reach=90, dur=0.45)
        spark_burst(fx, end, ui.accent, n=16, reach=60, dur=0.45)
        then()
    fx.add(0.85, paint, done=landed)


# ==================================================================================================
# SECTION: pawn
# ==================================================================================================
import math
import random
import time

from PyQt6.QtCore import QPointF, QRectF, Qt, QTimer
from PyQt6.QtGui import QColor, QFont, QLinearGradient, QPainter, QPainterPath, QPen, QPolygonF, QRadialGradient
from PyQt6.QtWidgets import QWidget


PAWN_GOLD = QColor("#E8C26A")


def pawn_chance(ratio: float, anger: float) -> float:
    """The same as the server's rb_pawn_chance."""
    if ratio <= 1:
        return 1.0
    return max(0.0, max(0.0, 1 - (ratio - 1) / 0.75) ** 1.15 * (1 - min(100.0, anger) / 300.0))     # 4.6: kinder


def pawn_rage(ratio: float) -> float:
    """How much a no adds to his anger (the server's rb_pawn_rage)."""
    return 15 + 50 * min(1.0, max(0.0, (ratio - 1) / 0.5))


def pawn_ease(t: float) -> float:
    t = max(0.0, min(1.0, t))
    return t * t * (3 - 2 * t)


def pawn_ease_out(t: float) -> float:
    t = max(0.0, min(1.0, t))
    return 1 - (1 - t) ** 3


def pawn_ease_in(t: float) -> float:
    t = max(0.0, min(1.0, t))
    return t * t * t


BIG_BET = 10000                      # 6.3: bets above this are confirmed and shown in gold / red


def pawn_clock(s: int) -> str:
    s = max(0, int(s))
    return f"{s // 60}:{s % 60:02d}"


# ---------------------------------------------------------------- the overlay
class PawnShop(QWidget):
    """Covers the whole menu while you are in the shop. Phases (seconds): fade 0.3 · close 0.45 · hold · open 0.6 ·
    shop · leave (close 0.4, open 0.5) · crack 1.5 · slam 0.25 + plaque 1.6 · banned (close 0.45, plaque 2.6, open 0.5)."""

    def __init__(self, ctx, ids: list, item: str, what: str) -> None:
        win = ctx.window
        super().__init__(win)
        self.ctx, self.win = ctx, win
        self.ids, self.item, self.what = list(ids), item, what
        # 9.5: several different items: one shows on the pad at a time, arrows by the pad go through them
        by_id = {i["id"]: i["item"] for i in ctx.econ.items}
        self.shown_items = list(dict.fromkeys(by_id[x] for x in self.ids if x in by_id)) or ([item] if item else [])
        self.shown_n = {k: sum(1 for x in self.ids if by_id.get(x) == k) for k in self.shown_items}
        self.view_i = 0
        self._arrows = (QRectF(), QRectF())
        self.base, self.anger, self.ban_left, self.max_ratio = 0, 0.0, 0, 1.5
        self.shown_anger = 0.0                      # the bar moves to the new level smoothly
        self.ask_mode = False
        self.ask = 0
        self.deal = 0                               # 4.7: the price he agreed to (not sold yet)
        self.market = 0                             # 4.7: what it goes for on the market, to compare
        self.busy = False
        self.line = tr("Let's see what you've got.")
        self.line_at = time.monotonic()
        self.phase, self.t0 = "fade", time.monotonic()
        self.loaded = False
        self.after = None                           # what happens when the doors have opened on the menu again
        self.shards: list = []
        self.snap = None
        self.sold_at = 0.0
        self.ban_end = 0.0
        self.props_left, self.props_end = 10, 0.0     # 6.2.7: exchanges you can still propose this hour
        self.setMouseTracking(True)
        self._build_controls()
        self._place()
        self.show()
        self.raise_()
        self.setFocus()
        self._timer = QTimer(self)
        self._timer.setTimerType(Qt.TimerType.PreciseTimer)
        self._timer.setInterval(16)
        self._timer.timeout.connect(self._frame)
        self._timer.start()
        ctx.econ.call("rb_pawn_enter", {"ids": self.ids}, self._entered)

    # -- geometry
    def _place(self) -> None:
        try:
            r = self.win._card_rect() if hasattr(self.win, "_card_rect") else QRectF(self.win.rect())
        except RuntimeError:
            return
        g = r.toRect()
        if self.geometry() != g:
            self.setGeometry(g)
            self._layout_controls()

    def _panel(self) -> QRectF:
        """The middle column everything in the shop lines up on."""
        w = min(float(self.width()) - S(40), S(560))
        return QRectF((self.width() - w) / 2, 0, w, self.height())

    def _counter_y(self) -> float:
        return self.height() * 0.50

    # -- controls (real buttons, shown only while you are in the shop)
    def _build_controls(self) -> None:
        self.box = QWidget(self)
        lay = vbox(self.box, 8)
        self.row_offer = QWidget()
        r1 = hbox(self.row_offer, 8)
        self.take = Button("", "primary", 40, icon="check")
        self.take.clicked.connect(lambda: self._sell(None))
        self.more = Button(tr("Ask for more"), "ghost", 40)
        self.more.clicked.connect(lambda: self._set_ask(True))
        r1.addWidget(self.take, 3)
        r1.addWidget(self.more, 2)
        self.swap_btn = Button(tr("Propose exchange"), "ghost", 40)     # 5.12: he offers one of his items for yours
        self.swap_btn.clicked.connect(lambda: self._trade("offer"))
        # 6.0: only for one tradeable item he can swap (worth 300 at least): no button that answers with an error
        info = self.ctx.econ.info(self.item) if len(self.ids) == 1 else None
        self.swap_btn.setVisible(len(self.ids) == 1 and bool(info and info.get("tradeable"))
                                 and self.ctx.econ.worth(self.item) >= 300)
        r1.addWidget(self.swap_btn, 2)
        lay.addWidget(self.row_offer)
        self.trade = None
        self.trade_confirm = False
        self.row_trade = QWidget()
        rt = hbox(self.row_trade, 8)
        self.trade_yes = Button(tr("Accept the exchange"), "primary", 40, icon="check")
        self.trade_yes.clicked.connect(lambda: self._trade("accept"))
        self.trade_more = Button(tr("Ask for more"), "ghost", 40)
        self.trade_more.clicked.connect(self._trade_more)
        self.trade_no = Button(tr("Refuse"), "ghost", 40)
        self.trade_no.clicked.connect(lambda: self._trade("refuse"))
        rt.addWidget(self.trade_yes, 3)
        rt.addWidget(self.trade_more, 3)
        rt.addWidget(self.trade_no, 2)
        lay.addWidget(self.row_trade)
        self.row_trade.hide()
        self.row_ask = QWidget()
        r2 = vbox(self.row_ask, 8)
        self.slider = Slider(0, 1, 0, 1)
        self.slider.changed.connect(self._slid)
        r2.addWidget(self.slider)
        btns = QWidget()
        r3 = hbox(btns, 8)
        self.offer = Button("", "primary", 40)
        self.offer.clicked.connect(lambda: self._sell(self.ask))
        self.back = Button(tr("Back"), "ghost", 40)
        self.back.clicked.connect(lambda: self._set_ask(False))
        r3.addWidget(self.offer, 3)
        r3.addWidget(self.back, 2)
        r2.addWidget(btns)
        lay.addWidget(self.row_ask)
        self.row_deal = QWidget()                   # 4.7: he said yes to your price: nothing is sold until you press Sell
        r4 = hbox(self.row_deal, 8)
        self.sell_deal = Button("", "primary", 40, icon="check")
        self.sell_deal.clicked.connect(lambda: self._sell(self.deal))
        self.no_deal = Button(tr("Not now"), "ghost", 40)
        self.no_deal.clicked.connect(self._drop_deal)
        r4.addWidget(self.sell_deal, 3)
        r4.addWidget(self.no_deal, 2)
        lay.addWidget(self.row_deal)
        self.row_deal.hide()
        self.leave_btn = Button(tr("Leave the shop"), "ghost", 32, icon="back", parent=self)
        self.leave_btn.clicked.connect(self.leave)
        self.box.hide()
        self.leave_btn.hide()
        self.row_ask.hide()

    def _layout_controls(self) -> None:
        pn = self._panel()
        top = self._counter_y() + S(150)
        h = S(40) + S(8) + S(26) + S(8) + S(40)
        self.box.setGeometry(int(pn.left()), int(top), int(pn.width()), int(h))
        self.leave_btn.adjustSize()
        self.leave_btn.setFixedWidth(max(S(150), self.leave_btn.sizeHint().width() + S(20)))
        self.leave_btn.move(int(S(16)), int(S(16)))

    def _controls(self, on: bool) -> None:
        self.box.setVisible(on)
        self.leave_btn.setVisible(on)
        if on:
            self._refresh_texts()

    def _refresh_texts(self) -> None:
        self.take.set_text(tr("Sell for {n}", n=coins_text(self.base)))
        trading = self.trade is not None
        self.row_trade.setVisible(trading)
        if trading:
            more = self.trade.get("more")
            self.trade_more.setEnabled(bool(more) and not self.busy)
            if not more:
                self.trade_more.set_text(tr("He won't go higher"))
            elif self.trade_confirm:
                self.trade_more.set_text(tr("Sure? {c}% yes", c=int(round(float(more.get("chance") or 0) * 100))))
                self.trade_more.set_kind("danger")
            else:
                self.trade_more.set_text(tr("Ask for more"))
                self.trade_more.set_kind("ghost")
            for b in (self.trade_yes, self.trade_no):
                b.setEnabled(not self.busy)
            self.row_offer.setVisible(False)
            self.row_ask.setVisible(False)
            self.row_deal.setVisible(False)
            self.leave_btn.setEnabled(not self.busy)
            return
        if self.props_left > 0:
            self.swap_btn.set_text(tr("Exchange · {n}/10 left", n=self.props_left))
        else:
            self.swap_btn.set_text(tr("No exchanges left"))
        self.swap_btn.setEnabled(not self.busy and self.props_left > 0)
        self.row_offer.setVisible(not self.ask_mode and not self.deal)
        self.row_ask.setVisible(self.ask_mode and not self.deal)
        self.row_deal.setVisible(bool(self.deal))
        self.sell_deal.set_text(tr("Sell for {n}", n=coins_text(self.deal)))
        at_his = self.ask <= self.base
        self.offer.set_text(tr("Sell for {n}", n=coins_text(self.ask)) if at_his else tr("Ask {n}", n=coins_text(self.ask)))
        for b in (self.take, self.more, self.offer, self.back, self.leave_btn, self.sell_deal, self.no_deal):
            b.setEnabled(not self.busy)

    def _drop_deal(self) -> None:
        if self.busy:
            return
        sfx.play("pick")
        self.deal = 0
        self.line, self.line_at = tr("Suit yourself."), time.monotonic()
        self._refresh_texts()
        self.update()

    def _set_ask(self, on: bool) -> None:
        if self.busy:
            return
        sfx.play("pick")
        self.ask_mode = on
        if on:
            lo, hi = self._ask_range()
            step = max(1, (hi - lo) // 100)
            self.slider.deleteLater()
            self.slider = Slider(lo, hi, lo, step)            # 4.7: starts on his price (100%), far left
            self.slider.changed.connect(self._slid)
            self.row_ask.layout().insertWidget(0, self.slider)
            self.ask = int(self.slider.value())
        self._refresh_texts()
        self.update()

    def _ask_range(self):
        lo = self.base
        hi = max(lo, int(math.floor(self.base * self.max_ratio)))
        return lo, hi

    def _slid(self, v: float) -> None:
        self.ask = int(v)
        self._refresh_texts()
        self.update()

    def _props(self, data) -> None:
        """6.2.7: how many exchange proposals are left this hour (the server counts), and when one comes back."""
        if not isinstance(data, dict) or data.get("props_left") is None:
            return
        self.props_left = int(data.get("props_left") or 0)   # the server says how many (10 an hour)
        reset = int(data.get("props_reset") or 0)
        self.props_end = time.time() + reset if self.props_left <= 0 and reset > 0 else 0.0
        try:
            self._refresh_texts()
        except RuntimeError:
            pass

    def _props_reload(self) -> None:
        self.ctx.econ.call("rb_pawn_props_left", {}, lambda ok, d: self._props(d) if ok else None)

    # -- the server
    def _entered(self, ok: bool, data) -> None:
        if not ok or not isinstance(data, dict):
            self.ctx.toast(tr(str(data)) if not ok else tr("Something went wrong: try again"), "warn")
            return self._go("leave_close")
        self.base = int(data.get("base") or 0)
        self.anger = self.shown_anger = float(data.get("anger") or 0)
        self.ban_left = int(data.get("ban_left") or 0)
        self.max_ratio = float(data.get("max_ratio") or 1.5)
        self._props(data)
        self.loaded = True
        if self.ban_left > 0:
            self.ban_end = time.monotonic() + self.ban_left
            self.ctx.pawn_ban_until = time.time() + self.ban_left
        elif int(data.get("n") or 0) == 0:
            self.ctx.toast(tr("This cannot be sold"), "warn")
            self.ban_left = -1                                    # nothing to sell: just open back on the menu
        self.line = tr("I'll give you {n} coins for {what}.", n=coins_text(self.base), what=self.what)
        self.line_at = time.monotonic()

    def _sell(self, ask) -> None:
        """Sell now: at his price (ask None or not above it), or at a price he already agreed to."""
        if ask is not None and ask > self.base and ask != self.deal:
            return self._ask(ask)
        if self.busy or self.phase != "shop":
            return
        self.busy = True
        self._refresh_texts()
        sfx.play("pick")

        def done(ok: bool, data) -> None:
            self.busy = False
            try:
                if not ok or not isinstance(data, dict):
                    self.ctx.toast(tr(str(data)), "warn")
                    return self._refresh_texts()
                res = data.get("result")
                self.anger = float(data.get("anger") or 0)
                if res == "yes":
                    sfx.play("on")
                    self.line, self.line_at = tr("Deal. Pleasure doing business."), time.monotonic()
                    self.sold_at = time.monotonic()
                    self.paid = int(data.get("paid") or 0)
                    ec = self.ctx.econ
                    gone = set(self.ids)
                    ec.items = [i for i in ec.items if i["id"] not in gone]
                    ec._index()
                    ec.refresh()
                    self.after = lambda: (self.ctx.toast(tr("Sold for {n} coins", n=coins_text(self.paid))),
                                          setattr(self.ctx, "inv_pick", ""), self.ctx.reload_page())
                    self._controls(False)
                    QTimer.singleShot(1500, lambda: self._go("leave_close"))
                elif res == "kicked":
                    self.anger = 100.0
                    self.line, self.line_at = tr("That's it. GET OUT!"), time.monotonic()
                    self.after = lambda: self.ctx.toast(tr("Thrown out of the pawn shop for 5 minutes"), "warn")
                    self._controls(False)
                    sfx.play("off")
                    QTimer.singleShot(500, self._crack)
                elif res == "banned":
                    self.ban_left = int(data.get("ban_left") or 0)
                    self.ban_end = time.monotonic() + self.ban_left
                    self.ctx.pawn_ban_until = time.time() + self.ban_left
                    self._controls(False)
                    self._go("ban_close")
                else:
                    sfx.play("off")
                    self.line = (tr("No way.") if self.anger < 45 else tr("You're pushing it.") if self.anger < 75
                                 else tr("One more and you're out."))
                    self.line_at = time.monotonic()
                    lo, hi = self._ask_range()
                    self.slider.set_value(max(lo, min(self.ask, hi)))
                    self._refresh_texts()
            except RuntimeError:
                pass
        self.ctx.econ.call("rb_pawn_sell", {"ids": self.ids, "ask": ask if ask and ask > self.base else None}, done, once=True)

    def _trade_more(self) -> None:
        """Asking for more needs a second click: the first shows the chance and the anger he would gain."""
        if self.busy or not self.trade or not self.trade.get("more"):
            return
        if not self.trade_confirm:
            self.trade_confirm = True
            sfx.play("pick")
            m = self.trade["more"]
            self.line = tr("Something worth {p}% of yours? {c}% chance I say yes. If I say no: +{r} anger.",
                           p=int(m.get("pct") or 0), c=int(round(float(m.get("chance") or 0) * 100)), r=int(round(float(m.get("rage") or 0))))
            self.line_at = time.monotonic()
            self._refresh_texts()
            return self.update()
        self.trade_confirm = False
        self._trade("more")

    def _trade(self, action: str) -> None:
        """5.12: swap your item for one of his (offer, more, accept, refuse)."""
        if self.busy or self.phase != "shop":
            return
        self.busy = True
        self.trade_confirm = False
        self._refresh_texts()
        sfx.play("pick")

        def done(ok: bool, data) -> None:
            self.busy = False
            try:
                if action == "offer" or not ok:
                    self._props_reload()
                if not ok or not isinstance(data, dict):
                    self.ctx.toast(tr(str(data)), "warn")
                    return self._refresh_texts()
                res = data.get("result")
                self.anger = float(data.get("anger") or self.anger)
                if res in ("offer", "no"):
                    first = self.trade is None
                    self.trade = data
                    if res == "no":
                        sfx.play("off")
                        self.line = (tr("No. Take it or leave it.") if self.anger < 45 else tr("You're pushing it.")
                                     if self.anger < 75 else tr("One more and you're out."))
                    else:
                        sfx.play("on")
                        self.line = (tr("I'll swap it for this {what}.", what=item_name(data.get("item", ""))) if first
                                     else tr("Fine. This {what} then.", what=item_name(data.get("item", ""))))
                    self.line_at = time.monotonic()
                elif res == "refused":
                    self.trade = None
                    self.line, self.line_at = tr("Suit yourself."), time.monotonic()
                elif res == "swapped":
                    sfx.play("on")
                    ec = self.ctx.econ
                    ec.items = [i for i in ec.items if i["id"] not in set(self.ids)]
                    ec._index()
                    ec.refresh()
                    got = data.get("item", "")
                    self.item, self.what, self.trade = got, item_name(got), None
                    self.line, self.line_at = tr("Deal. Enjoy your {what}.", what=item_name(got)), time.monotonic()
                    self.after = lambda: (self.ctx.toast(tr("You got {what}", what=item_name(got))),
                                          setattr(self.ctx, "inv_pick", ""), self.ctx.reload_page())
                    self._controls(False)
                    QTimer.singleShot(1800, lambda: self._go("leave_close"))
                elif res == "kicked":
                    self.anger, self.trade = 100.0, None
                    self.line, self.line_at = tr("That's it. GET OUT!"), time.monotonic()
                    self.after = lambda: self.ctx.toast(tr("Thrown out of the pawn shop for 5 minutes"), "warn")
                    self._controls(False)
                    sfx.play("off")
                    QTimer.singleShot(500, self._crack)
                    return
                elif res == "banned":
                    self.ban_left = int(data.get("ban_left") or 0)
                    self.ban_end = time.monotonic() + self.ban_left
                    self._controls(False)
                    return self._go("ban_close")
                self._refresh_texts()
                self.update()
            except RuntimeError:
                pass
        self.ctx.econ.call("rb_pawn_trade", {"ids": self.ids, "action": action}, done, once=True)

    def _ask(self, ask: int) -> None:
        """4.7: only asks. A yes keeps the price for you; the item stays yours until you press Sell."""
        if self.busy or self.phase != "shop":
            return
        self.busy = True
        self._refresh_texts()
        sfx.play("pick")

        def done(ok: bool, data) -> None:
            self.busy = False
            try:
                if not ok or not isinstance(data, dict):
                    self.ctx.toast(tr(str(data)), "warn")
                    return self._refresh_texts()
                res = data.get("result")
                self.anger = float(data.get("anger") or 0)
                if res == "yes":
                    sfx.play("on")
                    self.deal = int(data.get("price") or ask)
                    self.ask_mode = False
                    self.line, self.line_at = tr("Fine. {n} coins, if you want it.", n=coins_text(self.deal)), time.monotonic()
                    self._refresh_texts()
                elif res == "kicked":
                    self.anger = 100.0
                    self.line, self.line_at = tr("That's it. GET OUT!"), time.monotonic()
                    self.after = lambda: self.ctx.toast(tr("Thrown out of the pawn shop for 5 minutes"), "warn")
                    self._controls(False)
                    sfx.play("off")
                    QTimer.singleShot(500, self._crack)
                elif res == "banned":
                    self.ban_left = int(data.get("ban_left") or 0)
                    self.ban_end = time.monotonic() + self.ban_left
                    self.ctx.pawn_ban_until = time.time() + self.ban_left
                    self._controls(False)
                    self._go("ban_close")
                else:
                    sfx.play("off")
                    self.line = (tr("No way.") if self.anger < 45 else tr("You're pushing it.") if self.anger < 75
                                 else tr("One more and you're out."))
                    self.line_at = time.monotonic()
                    self._refresh_texts()
                self.update()
            except RuntimeError:
                pass
        self.ctx.econ.call("rb_pawn_ask", {"ids": self.ids, "ask": ask}, done, once=True)

    # -- phases
    def _go(self, phase: str) -> None:
        self.phase, self.t0 = phase, time.monotonic()
        if phase in ("close", "leave_close", "ban_close"):
            sfx.play("pick")
        if phase != "shop":
            self._controls(False)

    def leave(self) -> None:
        if self.phase == "shop" and not self.busy:
            self._go("leave_close")

    def keyPressEvent(self, e) -> None:
        if e.key() == Qt.Key.Key_Escape:
            return self.leave()
        super().keyPressEvent(e)

    def mousePressEvent(self, e) -> None:
        e.accept()                                     # nothing under the shop can be clicked
        if len(self.shown_items) > 1 and not self.sold_at:          # 9.5: the arrows by the pad
            for step, r in zip((-1, 1), self._arrows):
                if r.contains(e.position()):
                    self.view_i = (self.view_i + step) % len(self.shown_items)
                    sfx.play("pick")
                    self.update()

    def _crack(self) -> None:
        """The bar cracks, then the whole shop breaks into pieces that fall away."""
        self._go("crack")
        self.snap = None
        rnd = random.Random(int(time.time()))
        self.crack_seed = rnd.randrange(1 << 30)
        bar = self._bar_rect()
        self.crack_at = QPointF(bar.left() + bar.width() * rnd.uniform(0.55, 0.9), bar.center().y())

    def _make_shards(self) -> None:
        self.snap = self.grab()
        rnd = random.Random(self.crack_seed)
        c = self.crack_at
        n = 14
        angs = sorted(rnd.uniform(0, math.tau) for _ in range(n))
        far = math.hypot(self.width(), self.height()) * 1.2
        self.shards = []
        for i in range(n):
            a1, a2 = angs[i], angs[(i + 1) % n] + (math.tau if i == n - 1 else 0)
            mid = (a1 + a2) / 2
            poly = QPolygonF([c, c + QPointF(math.cos(a1) * far, math.sin(a1) * far),
                              c + QPointF(math.cos(mid) * far * 1.1, math.sin(mid) * far * 1.1),
                              c + QPointF(math.cos(a2) * far, math.sin(a2) * far)])
            self.shards.append((poly, math.cos(mid) * rnd.uniform(60, 220), rnd.uniform(-260, -40),
                                rnd.uniform(-90, 90), rnd.uniform(0, 0.15)))

    def _frame(self) -> None:
        self._place()
        now = time.monotonic()
        t = now - self.t0
        ph = self.phase
        if self.props_left <= 0 and self.props_end:
            if time.time() >= self.props_end:                   # an exchange came back: ask the server
                self.props_end = 0.0
                self._props_reload()
            elif int(time.time()) != getattr(self, "_props_sec", 0):
                self._props_sec = int(time.time())
                self._refresh_texts()
        if ph == "fade" and t >= 0.3:
            self._go("close")
        elif ph == "close" and t >= 0.45:
            self._go("hold")
            sfx.play("off")
        elif ph == "hold" and t >= 0.25 and self.loaded:
            if self.ban_left > 0:
                self._go("ban_close")
                self.t0 -= 0.45                              # the doors are shut already: straight to the plaque
            elif self.ban_left < 0:
                self._go("leave_open")
            else:
                self._go("open")
        elif ph == "open" and t >= 0.6:
            self._go("shop")
            self._controls(True)
        elif ph == "leave_close" and t >= 0.4:
            self._go("leave_open")
        elif ph == "ban_close" and t >= 0.45 + 2.6:
            self._go("leave_open")
        elif ph == "crack":
            if t >= 0.55 and self.snap is None:
                self._make_shards()
            if t >= 1.5:
                self._go("slam")
                self.ban_end = time.monotonic() + 300
                self.ctx.pawn_ban_until = time.time() + 300
        elif ph == "slam" and t >= 0.25 + 1.6:
            self._go("leave_open")
        elif ph == "leave_open" and t >= 0.5:
            return self._finish()
        self.shown_anger += (self.anger - self.shown_anger) * 0.12
        self.update()

    def _finish(self) -> None:
        self._timer.stop()
        after = self.after
        self.hide()
        self.deleteLater()
        if after:
            after()

    # -- drawing
    def _doors(self) -> float:
        """0: open (out of sight), 1: shut."""
        t = time.monotonic() - self.t0
        ph = self.phase
        if ph == "fade":
            return 0.0
        if ph in ("close", "leave_close", "ban_close"):
            return pawn_ease(t / (0.45 if ph != "leave_close" else 0.4))
        if ph in ("hold",):
            return 1.0
        if ph == "open":
            return 1 - pawn_ease(t / 0.6)
        if ph == "slam":
            return pawn_ease_in(t / 0.25)
        if ph == "leave_open":
            return 1 - pawn_ease(t / 0.5)
        return 0.0

    def _veil(self) -> float:
        """How dark the menu behind is."""
        t = time.monotonic() - self.t0
        if self.phase == "fade":
            return 0.9 * pawn_ease(t / 0.3)
        if self.phase == "leave_open":
            return 0.9 * (1 - pawn_ease(t / 0.5))
        return 0.9

    def _scene_on(self) -> bool:
        """The shop behind the doors: there while you are in it (and while it falls apart)."""
        return self.phase in ("open", "shop", "leave_close", "crack")

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect())
        clip = QPainterPath()
        clip.addRoundedRect(r, S(14), S(14))
        p.setClipPath(clip)
        now = time.monotonic()
        p.fillRect(r, alpha("#000000", self._veil()))
        if self.phase == "crack" and self.snap is not None:
            p.fillRect(r, QColor("#000000"))
            self._paint_shards(p, now)
        elif self._scene_on():
            self._paint_scene(p, r, now)
            if self.phase == "crack":
                self._paint_cracks(p, now)
        d = self._doors()
        if d > 0.001:
            self._paint_doors(p, r, d, now)

    # the shop
    def _paint_scene(self, p, r, now) -> None:
        wall = QLinearGradient(r.topLeft(), r.bottomLeft())
        wall.setColorAt(0, QColor("#2A1C14"))
        wall.setColorAt(1, QColor("#120C09"))
        p.fillRect(r, wall)
        lamp = QRadialGradient(QPointF(r.center().x(), r.top() + r.height() * 0.18), r.width() * 0.55)
        lamp.setColorAt(0, alpha("#FFC874", 0.22))
        lamp.setColorAt(1, alpha("#FFC874", 0.0))
        p.fillRect(r, lamp)
        pn = self._panel()
        cy = self._counter_y()
        self._paint_shelves(p, r, cy)
        self._paint_sign(p, pn)
        self._paint_keeper(p, pn, cy, now)
        self._paint_counter(p, r, cy, now)
        self._paint_bar(p, now)
        self._paint_texts(p, pn, cy, now)
        self._paint_bubble(p, pn, now)
        if self.loaded and self.phase == "shop":
            self._paint_props(p, r)

    def _paint_props(self, p, r) -> None:
        """6.2.7: the exchange allowance, big and always on screen: 5 pips for 5 proposals an hour."""
        left = self.props_left
        w, h = S(300), S(34)
        box = QRectF(r.right() - S(16) - w, r.top() + S(16), w, h)
        col = QColor(LOSE) if left <= 0 else QColor(GOLD_TEXT) if left <= 3 else QColor("#FFFFFF")
        p.save()
        p.setPen(QPen(alpha(col, 0.8), S(1.5)))
        p.setBrush(alpha("#000000", 0.55))
        p.drawRoundedRect(box, S(10), S(10))
        p.setFont(font(8.5, QFont.Weight.ExtraBold, 0.6))
        p.setPen(alpha(col, 0.95))
        back = ""
        if left <= 0 and self.props_end:
            back = " · " + pawn_clock(int(self.props_end - time.time()))
        p.drawText(QRectF(box.left() + S(10), box.top(), box.width() - S(140), h), int(Qt.AlignmentFlag.AlignVCenter),
                   tr("EXCHANGES THIS HOUR") + back)
        for i in range(10):
            c = QPointF(box.right() - S(12) - (9 - i) * S(13), box.center().y())
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(col if i < left else alpha("#FFFFFF", 0.18))
            p.drawEllipse(c, S(4.5), S(4.5))
        p.restore()

    def _paint_shelves(self, p, r, cy) -> None:
        rnd = random.Random(7)
        p.setPen(Qt.PenStyle.NoPen)
        for row in range(3):
            y = r.top() + r.height() * (0.20 + row * 0.10)
            p.setBrush(QColor("#3B2819"))
            p.drawRect(QRectF(r.left(), y, r.width(), S(6)))
            x = r.left() + S(10)
            while x < r.right() - S(30):
                w = S(rnd.choice([14, 18, 22, 26]))
                h = S(rnd.choice([18, 24, 30, 36]))
                if abs((x + w / 2) - r.center().x()) > self._panel().width() * 0.42:     # keep the middle clear
                    p.setBrush(alpha(rnd.choice(["#7A5A3A", "#5C6B73", "#8C7A4A", "#6E4A5A", "#4A6A5A"]), 0.55))
                    if rnd.random() < 0.4:
                        p.drawEllipse(QRectF(x, y - h, w, h))
                    else:
                        p.drawRoundedRect(QRectF(x, y - h, w, h), S(3), S(3))
                x += w + S(rnd.choice([6, 10, 16]))

    def _paint_sign(self, p, pn) -> None:
        sign = QRectF(pn.center().x() - S(150), S(58), S(300), S(46))
        g = QLinearGradient(sign.topLeft(), sign.bottomLeft())
        g.setColorAt(0, QColor("#5A3A22"))
        g.setColorAt(1, QColor("#3A2414"))
        p.setPen(QPen(QColor("#2A190D"), S(2)))
        p.setBrush(g)
        p.drawRoundedRect(sign, S(6), S(6))
        p.setPen(PAWN_GOLD)
        p.setFont(font(17, QFont.Weight.Black, 2.0))
        p.drawText(sign, int(Qt.AlignmentFlag.AlignCenter), tr("PAWN SHOP"))
        p.setPen(QPen(alpha("#000000", 0.5), S(1.5)))
        p.drawLine(QPointF(sign.left() + S(30), sign.top()), QPointF(sign.left() + S(30), sign.top() - S(20)))
        p.drawLine(QPointF(sign.right() - S(30), sign.top()), QPointF(sign.right() - S(30), sign.top() - S(20)))

    def _paint_keeper(self, p, pn, cy, now) -> None:
        a = min(1.0, self.shown_anger / 100)
        c = QPointF(pn.center().x() + pn.width() * 0.26, cy - S(62))
        shake = math.sin(now * 40) * S(2) * max(0.0, a - 0.75) * 4
        c += QPointF(shake, 0)
        p.setPen(Qt.PenStyle.NoPen)
        body = QPainterPath()                              # shoulders
        body.moveTo(c.x() - S(62), cy)
        body.cubicTo(c.x() - S(58), c.y() + S(30), c.x() - S(30), c.y() + S(26), c.x(), c.y() + S(26))
        body.cubicTo(c.x() + S(30), c.y() + S(26), c.x() + S(58), c.y() + S(30), c.x() + S(62), cy)
        body.closeSubpath()
        p.setBrush(QColor("#3C4A3A"))
        p.drawPath(body)
        skin = mix(QColor("#D9A57A"), QColor("#E0523C"), a * 0.85)
        p.setBrush(skin)
        p.drawEllipse(c, S(30), S(34))
        p.setBrush(QColor("#2A1C14"))                      # hair and a cap
        p.drawChord(QRectF(c.x() - S(31), c.y() - S(36), S(62), S(40)), 0, 180 * 16)
        eye_y = c.y() - S(2)
        for sx in (-1, 1):
            e = QPointF(c.x() + sx * S(11), eye_y)
            p.setBrush(QColor("#FFFFFF"))
            p.drawEllipse(e, S(5), S(4.2) * (1 - 0.35 * a))
            p.setBrush(QColor("#1A1210"))
            p.drawEllipse(e + QPointF(sx * -S(1), S(0.5)), S(2.2), S(2.2))
            p.setPen(QPen(QColor("#2A1C14"), S(2.6), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
            outer = QPointF(e.x() + sx * S(7), eye_y - S(10))       # the inner ends drop as he gets angry
            inner = QPointF(e.x() - sx * S(5), eye_y - S(9) + S(6) * a)
            p.drawLine(outer, inner)
            p.setPen(Qt.PenStyle.NoPen)
        mouth = QPainterPath()
        my = c.y() + S(16)
        bend = S(5) * (1 - 2 * a)                           # a smile, then a flat line, then a frown
        mouth.moveTo(c.x() - S(10), my)
        mouth.quadTo(QPointF(c.x(), my + bend), QPointF(c.x() + S(10), my))
        p.setPen(QPen(QColor("#5A2A1E"), S(2.4), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(mouth)
        self._head = QPointF(c)                             # 5.3: the bubble is painted last, on top

    def _paint_bubble(self, p, pn, now) -> None:
        """His speech bubble, to the left of his head, over everything else (5.3: nothing draws over it)."""
        c = getattr(self, "_head", None)
        if c is None:
            return
        a = min(1.0, self.shown_anger / 100)
        age = now - self.line_at
        if self.line:
            # 5.3: the bubble only uses the room left of his head (it used to slide over his face and the text)
            room = max(S(110), c.x() - S(46) - pn.left() - S(6))
            for size in (12, 11, 10, 9):
                p.setFont(font(size, QFont.Weight.Bold))
                fm = p.fontMetrics()
                br = fm.boundingRect(0, 0, int(room - S(30)), 400, int(Qt.TextFlag.TextWordWrap), self.line)
                if br.height() + S(22) <= S(96):
                    break
            bw, bh = br.width() + S(30), br.height() + S(22)      # 4.6: room for every line (no half-hidden words)
            b = QRectF(c.x() - S(46) - bw, max(c.y() - S(40), self._bar_rect().bottom() + S(8)), bw, bh)
            b.moveLeft(max(pn.left() + S(2), b.left()))
            k = pawn_ease_out(age / 0.25)
            p.save()
            p.translate(b.right(), b.bottom())
            p.scale(0.85 + 0.15 * k, 0.85 + 0.15 * k)
            p.translate(-b.right(), -b.bottom())
            p.setOpacity(k)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#F4EBDD"))
            p.drawRoundedRect(b, S(10), S(10))
            tail = QPolygonF([QPointF(b.right() - S(4), b.top() + S(12)), QPointF(b.right() + S(14), b.top() + S(20)),
                              QPointF(b.right() - S(4), b.top() + S(24))])
            p.drawPolygon(tail)
            p.setPen(QColor("#B3261E") if a > 0.7 else QColor("#2A1C14"))
            p.drawText(b.adjusted(S(13), S(8), -S(13), -S(8)), int(Qt.TextFlag.TextWordWrap | Qt.AlignmentFlag.AlignCenter),
                       self.line)
            p.restore()


    def _paint_counter(self, p, r, cy, now) -> None:
        top = QRectF(r.left(), cy, r.width(), S(14))
        g = QLinearGradient(top.topLeft(), top.bottomLeft())
        g.setColorAt(0, QColor("#8A5A34"))
        g.setColorAt(1, QColor("#5A3A20"))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawRect(top)
        front = QRectF(r.left(), cy + S(14), r.width(), r.height() - cy - S(14))
        g2 = QLinearGradient(front.topLeft(), front.bottomLeft())
        g2.setColorAt(0, QColor("#3E2716"))
        g2.setColorAt(1, QColor("#1E130B"))
        p.setBrush(g2)
        p.drawRect(front)
        p.setPen(QPen(alpha("#000000", 0.35), 1))
        for k in range(1, 8):
            x = r.left() + r.width() * k / 8
            p.drawLine(QPointF(x, front.top()), QPointF(x, front.bottom()))
        # the item on a velvet pad (it slides away once he buys it)
        pn = self._panel()
        pad = QRectF(pn.center().x() - pn.width() * 0.26 - S(56), cy - S(20), S(112), S(26))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#5A1E2A"))
        p.drawRoundedRect(pad, S(8), S(8))
        if self.item:
            pass
            many = len(self.shown_items) > 1 and self.trade is None
            on_pad = self.shown_items[self.view_i % len(self.shown_items)] if many else self.item
            k = pawn_ease_in((now - self.sold_at) / 0.8) if self.sold_at else 0.0
            box = QRectF(pad.center().x() - S(36), pad.top() - S(62), S(72), S(72))
            box.translate(pn.width() * 0.5 * k, -S(10) * math.sin(k * math.pi))
            p.setOpacity(1 - k)
            glow = QRadialGradient(box.center(), S(60))
            glow.setColorAt(0, alpha(PAWN_GOLD, 0.25))
            glow.setColorAt(1, alpha(PAWN_GOLD, 0.0))
            p.fillRect(box.adjusted(-S(30), -S(30), S(30), S(30)), glow)
            show_item(p, on_pad, box, now)
            if many and k < 0.01:                     # 9.5: ‹ 2/5 › to look through everything on the counter
                left = QRectF(pad.left() - S(30), box.center().y() - S(13), S(26), S(26))
                right = QRectF(pad.right() + S(4), box.center().y() - S(13), S(26), S(26))
                self._arrows = (left, right)
                for r_, sign in ((left, -1), (right, 1)):
                    p.setPen(QPen(alpha(PAWN_GOLD, 0.7), S(1.2)))
                    p.setBrush(QColor(20, 12, 8, 200))
                    p.drawEllipse(r_)
                    c_ = r_.center()
                    pen = QPen(QColor(PAWN_GOLD), S(2))
                    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
                    p.setPen(pen)
                    p.drawPolyline([QPointF(c_.x() - sign * S(2.5), c_.y() - S(5)), QPointF(c_.x() + sign * S(3), c_.y()),
                                    QPointF(c_.x() - sign * S(2.5), c_.y() + S(5))])
                n_ = self.shown_n.get(on_pad, 1)
                p.setPen(QColor("#E9D9B5"))
                p.setFont(font(9.5, QFont.Weight.Bold))
                p.drawText(QRectF(pad.left() - S(40), pad.bottom() + S(2), pad.width() + S(80), S(16)),
                           int(Qt.AlignmentFlag.AlignCenter),
                           f"{self.view_i % len(self.shown_items) + 1} / {len(self.shown_items)}"
                           + (f"  ·  ×{n_}" if n_ > 1 else ""))
            p.setOpacity(1.0)
            if self.trade:                                   # 5.12: his item on a plate, on his side of the counter
                plate = QRectF(pn.center().x() + pn.width() * 0.34 - S(56), cy - S(16), S(112), S(20))     # his side
                g3 = QLinearGradient(plate.topLeft(), plate.bottomLeft())
                g3.setColorAt(0, QColor("#E6EEF5"))
                g3.setColorAt(1, QColor("#8C98A3"))
                p.setPen(QPen(alpha("#000000", 0.4), 1))
                p.setBrush(g3)
                p.drawEllipse(plate)
                his = QRectF(plate.center().x() - S(28), plate.top() - S(50), S(56), S(56))
                glow2 = QRadialGradient(his.center(), S(60))
                glow2.setColorAt(0, alpha("#7FE8FF", 0.25))
                glow2.setColorAt(1, alpha("#7FE8FF", 0.0))
                p.fillRect(his.adjusted(-S(30), -S(30), S(30), S(30)), glow2)
                show_item(p, self.trade.get("item", ""), his, now)
                p.setPen(QColor(TEXT))
                p.setFont(font(10, QFont.Weight.Bold))
                p.drawText(QRectF(plate.left() - S(40), plate.bottom() + S(2), plate.width() + S(80), S(16)),
                           int(Qt.AlignmentFlag.AlignCenter), tr("His · worth {n} ({p}% of yours)", n=coins_text(int(self.trade.get("worth") or 0)),
                                                                 p=int(self.trade.get("pct") or 0)))
                p.setPen(QColor(TEXT_DIM))
                p.drawText(QRectF(pad.left() - S(40), pad.bottom() + S(2), pad.width() + S(80), S(16)),
                           int(Qt.AlignmentFlag.AlignCenter), tr("Yours · worth {n}", n=coins_text(int(self.trade.get("mine_worth") or 0))))
            if len(self.ids) > 1:
                p.setPen(QColor(TEXT))
                p.setFont(font(12, QFont.Weight.Black))
                p.drawText(QRectF(box.right() - S(6), box.bottom() - S(20), S(50), S(20)), int(Qt.AlignmentFlag.AlignVCenter),
                           f"×{len(self.ids)}")

    def _bar_rect(self) -> QRectF:
        pn = self._panel()
        return QRectF(pn.left() + S(80), S(126), pn.width() - S(160), S(16))

    def _paint_bar(self, p, now) -> None:
        bar = self._bar_rect()
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(9.5, QFont.Weight.Black, 1.2))
        p.drawText(QRectF(bar.left(), bar.top() - S(18), bar.width(), S(16)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("HIS PATIENCE RUNS OUT"))
        shake = 0.0
        if self.phase == "crack":
            shake = math.sin(now * 60) * S(3) * min(1.0, (now - self.t0) / 0.2)
        bar = bar.translated(shake, 0)
        path = QPainterPath()
        path.addRoundedRect(bar, bar.height() / 2, bar.height() / 2)
        p.setPen(QPen(alpha("#000000", 0.6), S(1.5)))
        p.setBrush(QColor("#1A120C"))
        p.drawPath(path)
        grad = QLinearGradient(bar.topLeft(), bar.topRight())
        grad.setColorAt(0, QColor("#3DDC84"))
        grad.setColorAt(0.5, QColor("#F2C94C"))
        grad.setColorAt(1, QColor("#FF3B3B"))
        p.save()
        p.setClipPath(path)
        a = max(0.0, min(100.0, self.shown_anger)) / 100
        p.setPen(Qt.PenStyle.NoPen)
        rage = None
        if self.ask_mode and self.phase == "shop" and self.base:           # the next no, if he says no at this price
            rage = pawn_rage(self.ask / self.base)
        elif self.trade_confirm and self.trade and self.trade.get("more"):  # 5.12: asking him for a better item
            rage = float(self.trade["more"].get("rage") or 0)
        if rage is not None:
            nxt = min(1.0, a + rage / 100)
            p.setOpacity(0.32 + 0.1 * math.sin(now * 5))
            p.setBrush(grad)
            p.drawRect(QRectF(bar.left(), bar.top(), bar.width() * nxt, bar.height()))
            p.setOpacity(1.0)
        p.setBrush(grad)
        p.drawRect(QRectF(bar.left(), bar.top(), bar.width() * a, bar.height()))
        p.restore()
        if self.phase == "crack":                                      # the crack, then it splits
            self._paint_bar_crack(p, bar, now)

    def _paint_bar_crack(self, p, bar, now) -> None:
        k = min(1.0, (now - self.t0) / 0.35)
        rnd = random.Random(self.crack_seed)
        c = QPointF(self.crack_at.x(), bar.center().y())
        p.setPen(QPen(QColor("#FFFFFF"), S(1.6)))
        for _ in range(5):
            ang = rnd.uniform(0, math.tau)
            pt = QPointF(c)
            path = QPainterPath(pt)
            for _s in range(4):
                ang += rnd.uniform(-0.6, 0.6)
                pt = pt + QPointF(math.cos(ang) * S(9) * k, math.sin(ang) * S(5) * k)
                path.lineTo(pt)
            p.drawPath(path)

    def _paint_cracks(self, p, now) -> None:
        """Before it breaks: cracks run out from the bar across everything."""
        t = now - self.t0
        k = max(0.0, min(1.0, (t - 0.25) / 0.3))
        if k <= 0:
            return
        rnd = random.Random(self.crack_seed + 1)
        c = self.crack_at
        far = math.hypot(self.width(), self.height())
        for _ in range(14):
            ang = rnd.uniform(0, math.tau)
            pt = QPointF(c)
            path = QPainterPath(pt)
            n = 9
            for s in range(n):
                if s / n > k:
                    break
                ang += rnd.uniform(-0.35, 0.35)
                step = far / n * rnd.uniform(0.6, 1.2)
                pt = pt + QPointF(math.cos(ang) * step, math.sin(ang) * step)
                path.lineTo(pt)
            p.setPen(QPen(alpha("#FFFFFF", 0.85), S(1.4)))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
            p.setPen(QPen(alpha("#000000", 0.5), S(3)))
            p.drawPath(path.translated(S(1), S(1)))

    def _paint_shards(self, p, now) -> None:
        t = max(0.0, now - self.t0 - 0.55)
        for poly, vx, vy, spin, delay in self.shards:
            tt = max(0.0, t - delay)
            dx, dy = vx * tt * S(1), (vy * tt + 0.5 * 1800 * tt * tt) * S(1) / 2
            p.save()
            c = poly.boundingRect().center()
            p.translate(c.x() + dx, c.y() + dy)
            p.rotate(spin * tt)
            p.translate(-c.x(), -c.y())
            path = QPainterPath()
            path.addPolygon(poly)
            path.closeSubpath()
            p.setClipPath(path)
            p.setOpacity(max(0.0, 1 - tt / 0.95))
            p.drawPixmap(0, 0, self.snap)
            p.restore()

    def _paint_texts(self, p, pn, cy, now) -> None:
        if self.phase not in ("shop", "open", "leave_close"):
            return
        y = cy + S(34)
        p.setPen(QColor(TEXT))
        p.setFont(font(15, QFont.Weight.Black))
        p.drawText(QRectF(pn.left(), y, pn.width(), S(26)), int(Qt.AlignmentFlag.AlignCenter), self.what)
        p.setFont(font(12, QFont.Weight.Bold))
        if self.sold_at:
            p.setPen(QColor("#3DDC84"))
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Sold for {n} coins", n=coins_text(getattr(self, "paid", 0))))
        elif self.trade:                                    # 5.12: the exchange, in plain words
            his = item_name(self.trade.get("item", ""))
            p.setPen(QColor("#7FE8FF"))
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Exchange: yours for his {what}", what=his))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            more = self.trade.get("more")
            line = (tr("Ask for more = ask for an item worth about {p}% of yours. {c}% chance he says yes. If he says no: +{r} anger "
                       "(the faint part of the bar) and no more asking.", p=int(more.get("pct") or 0),
                       c=int(round(float(more.get("chance") or 0) * 100)), r=int(round(float(more.get("rage") or 0))))
                    if more else tr("This is his last offer: accept or refuse."))
            p.drawText(QRectF(pn.left(), y + S(56), pn.width(), S(36)),
                       int(Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop | Qt.TextFlag.TextWordWrap), line)
            return
        elif self.deal:
            p.setPen(QColor("#3DDC84"))
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("He agreed to {n} coins: press Sell to sell it", n=coins_text(self.deal)))
        elif self.ask_mode and self.base:
            ch = pawn_chance(self.ask / self.base, self.anger)
            col = QColor("#3DDC84") if ch >= 0.6 else QColor("#F2C94C") if ch >= 0.3 else QColor("#FF6B5C")
            p.setPen(col)
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Chance he says yes: {p}%", p=int(round(ch * 100))))
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            p.drawText(QRectF(pn.left(), y + S(56), pn.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("If he says no, the faint part of the bar is how angry he gets"))
        else:
            p.setPen(PAWN_GOLD)
            p.drawText(QRectF(pn.left(), y + S(32), pn.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("His offer: {n} coins", n=coins_text(self.base)) if self.base else "…")
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            p.drawText(QRectF(pn.left(), y + S(56), pn.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Take it, or ask for more (up to +50%)"))
        if self.market and not self.sold_at:                   # 4.7: to compare with the market
            p.setPen(QColor(TEXT_DIM))
            p.setFont(font(10.5, QFont.Weight.Bold))
            p.drawText(QRectF(pn.left(), y + S(78), pn.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Market price: about {n} coins (selling there takes longer, 5% fee)", n=coins_text(self.market)))
        # how it works, under the buttons
        foot = QRectF(pn.left(), self.box.geometry().bottom() + S(14), pn.width(), S(60))
        p.setPen(alpha(TEXT_DIM, 0.85))
        p.setFont(font(10, QFont.Weight.DemiBold))
        p.drawText(foot, int(Qt.TextFlag.TextWordWrap | Qt.AlignmentFlag.AlignHCenter | Qt.AlignmentFlag.AlignTop),
                   tr("His price always sells. Asking for more only asks: if he says yes, you still choose to sell. "
                      "Every no makes him angrier (he calms down over time); if his patience runs out, he throws you out "
                      "for 5 minutes."))

    # the doors
    def _paint_doors(self, p, r, d, now) -> None:
        half = r.width() / 2
        off = (1 - d) * (half + S(20))
        for side in (0, 1):
            x = (r.left() - off) if side == 0 else (r.center().x() + off)
            door = QRectF(x, r.top(), half, r.height())
            g = QLinearGradient(door.topLeft(), door.topRight())
            g.setColorAt(0, QColor("#4A2E1A") if side == 0 else QColor("#3A2414"))
            g.setColorAt(1, QColor("#3A2414") if side == 0 else QColor("#4A2E1A"))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(g)
            p.drawRect(door)
            p.setPen(QPen(alpha("#000000", 0.35), S(1.2)))                 # planks
            for k in range(1, 6):
                xx = door.left() + door.width() * k / 6
                p.drawLine(QPointF(xx, door.top()), QPointF(xx, door.bottom()))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#2A2A2E"))                                    # iron bands with rivets
            for fy in (0.14, 0.86):
                band = QRectF(door.left(), door.top() + door.height() * fy - S(9), door.width(), S(18))
                p.drawRect(band)
                p.setBrush(QColor("#55555C"))
                for k in range(1, 8):
                    p.drawEllipse(QPointF(band.left() + band.width() * k / 8, band.center().y()), S(2.6), S(2.6))
                p.setBrush(QColor("#2A2A2E"))
            edge = door.right() if side == 0 else door.left()                # the handles meet in the middle
            hc = QPointF(edge + (-S(26) if side == 0 else S(26)), door.center().y())
            p.setBrush(QColor("#C9A24A"))
            p.drawEllipse(hc, S(9), S(9))
            p.setBrush(QColor("#7A5A20"))
            p.drawEllipse(hc, S(4), S(4))
            p.setPen(QPen(alpha("#000000", 0.6), S(3)))
            p.drawLine(QPointF(edge, door.top()), QPointF(edge, door.bottom()))
        if d > 0.98 and self.phase in ("ban_close", "slam") and self.ban_end:
            self._paint_plaque(p, r, now)

    def _paint_plaque(self, p, r, now) -> None:
        """4.6: a big plaque with a big countdown, easy to read from across the room."""
        left = max(0, int(math.ceil(self.ban_end - now)))
        pl = QRectF(r.center().x() - S(190), r.center().y() - S(190), S(380), S(170))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#000000", 0.45))
        p.drawRoundedRect(pl.translated(0, S(5)), S(10), S(10))
        p.setPen(QPen(QColor("#2A190D"), S(3)))
        p.setBrush(QColor("#EFE5CF"))
        p.drawRoundedRect(pl, S(10), S(10))
        p.setPen(QPen(alpha("#8A1C14", 0.5), S(1.5)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(pl.adjusted(S(7), S(7), -S(7), -S(7)), S(6), S(6))
        p.setPen(QColor("#8A1C14"))
        p.setFont(font(16, QFont.Weight.Black, 2.0))
        p.drawText(QRectF(pl.left(), pl.top() + S(16), pl.width(), S(26)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("CLOSED TO YOU"))
        pulse = 0.85 + 0.15 * math.sin(now * 3)
        p.setPen(QColor(int(178 * pulse), 30, 24))
        p.setFont(font(40, QFont.Weight.Black))
        p.drawText(QRectF(pl.left(), pl.top() + S(46), pl.width(), S(62)), int(Qt.AlignmentFlag.AlignCenter),
                   pawn_clock(left))
        p.setFont(font(11.5, QFont.Weight.Bold))
        p.setPen(QColor("#4A3A2A"))
        p.drawText(QRectF(pl.left(), pl.top() + S(112), pl.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("before you can come back in"))
        p.setFont(font(10, QFont.Weight.DemiBold))
        p.setPen(QColor("#6A5A4A"))
        p.drawText(QRectF(pl.left(), pl.top() + S(136), pl.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("You made him too angry"))


def open_pawn(ctx, ids: list, item: str, what: str) -> None:
    """Quick sell: ask first, then walk into the pawn shop."""
    if not ids:
        return
    old = getattr(ctx, "_pawn", None)
    try:
        if old is not None and old.isVisible():
            return
    except RuntimeError:
        pass

    ctx._pawn = PawnShop(ctx, ids, item, what)            # 5.0: no question first, straight into the shop


# ==================================================================================================
# SECTION: wave
# ==================================================================================================
import bisect
import math
import random
import time

from PyQt6.QtCore import QPointF, QRectF, Qt, QTimer
from PyQt6.QtGui import QColor, QFont, QLinearGradient, QPainter, QPainterPath, QPen, QPolygonF
from PyQt6.QtWidgets import QWidget


# ================================================================ the course (the server's rb_wave_sim, line for line)
WAVE_VX = 12              # units a tick, right and up/down
WAVE_R = 10               # hit radius
WAVE_H = 1000             # course height
WAVE_SW = 48              # half width of a spike
WAVE_TPS = 60             # ticks a second
WAVE_MAX = 60 * 900
GHOST_LAG = 84             # 6.4: the other player is shown 1.4 s behind, so we only ever draw what really happened
ROOM_LAG = 48              # 9.2: rooms send news every 0.3 s, so the others are shown only 0.8 s behind
WAVE_SEAT_COLS = ("#4FC3FF", "#FFB627", "#FF5CA8", "#7BE07B")     # 9.2: one colour per seat in a room
WAVE_SLIDE = 150          # 5.1 (033): the first 2.5 s you slide on the walls instead of crashing
WAVE_SPACE = 130          # 5.1 (033): two spikes in a row are never closer than this (they could close the gap)
WAVE_HUD = 46             # 5.1: the distance and the difficulty bar sit in their own strip above the course


class WaveRng:
    def __init__(self, seed: int) -> None:
        self.s = seed & 0x7FFFFFFF

    def next(self, n: int) -> int:
        self.s = (self.s * 1103515245 + 12345) & 0x7FFFFFFF
        return (self.s >> 8) % n


def wave_level(x: int) -> int:
    """5.13: 0 (start) to 1000. It jumps up at 250 m, 500 m, 750 m and 1 000 m (Medium, Hard, Insane, Extreme) and
    climbs a little inside each stage. The server (rb_wave_sim) does the same sums."""
    m = x // 100
    if m < 250:
        return m * 160 // 250
    if m < 500:
        return 300 + (m - 250) * 100 // 250
    if m < 750:
        return 500 + (m - 500) * 100 // 250
    if m < 1000:
        return 700 + (m - 750) * 100 // 250
    return min(1000, 880 + (m - 1000) * 120 // 500)


def wave_gap(d: int) -> int:
    f = d * (d + 1000) // 2000
    g = 420 - 300 * f // 1000
    return g - g % 2


class WaveCourse:
    """Segments [x0, length, c0, slope, gap, spikes]; spikes (x, side): 0 hangs from the top, 1 stands on the floor."""

    def __init__(self, seed: int) -> None:
        self.rng = WaveRng(seed)
        self.segs = [[0, 900, 500, 0, 420, []]]
        self.starts = [0]
        self.x_end, self.c_end = 900, 500

    def _add(self, length: int, slope: int, gap: int, spikes=None) -> None:
        self.segs.append([self.x_end, length, self.c_end, slope, gap, spikes or []])
        self.starts.append(self.x_end)
        self.x_end += length
        self.c_end += slope * length

    def _room(self, slope: int, gap: int) -> int:
        lo, hi = gap // 2 + 40, WAVE_H - gap // 2 - 40
        return hi - self.c_end if slope > 0 else self.c_end - lo

    def _pull(self, gap: int) -> None:
        lo, hi = gap // 2 + 40, WAVE_H - gap // 2 - 40
        if self.c_end < lo:
            self._add(lo - self.c_end, 1, gap)
        elif self.c_end > hi:
            self._add(self.c_end - hi, -1, gap)

    def grow(self) -> None:
        rnd = self.rng.next
        d = wave_level(self.x_end)
        gap = wave_gap(d)
        self._pull(gap)
        r = rnd(1000)
        p_zig = 200 + 400 * d // 1000
        p_flat = 450 - 200 * d // 1000
        if d >= 300 and r < 90:                                  # 5.13: a tunnel, a quarter narrower
            length = 300 + rnd(300)
            narrow = gap * 3 // 4
            self._add(length, 0, narrow - narrow % 2)
            return
        if r < p_flat:
            length = 300 + rnd(500)
            n = rnd(2 + 3 * d // 1000) if d >= 20 else 0
            n = min(n, max(0, length // WAVE_SPACE - 1))              # 5.1: never stacked in a tight space
            side = rnd(2)
            spikes = []                                               # 5.13: no more gates (above and below at once)
            for i in range(n):
                spikes.append((self.x_end + length * (i + 1) // (n + 1), side))
                side = 1 - side
            self._add(length, 0, gap, spikes)
        elif r < p_flat + p_zig:
            legs = 3 + rnd(4 + 4 * d // 1000)
            leg = max(100, 320 - 220 * d // 1000 + rnd(60))
            slope = 1 if self._room(1, gap) >= self._room(-1, gap) else -1
            for _ in range(legs):
                room = self._room(slope, gap)
                if room < 60:
                    slope = -slope
                    room = self._room(slope, gap)
                self._add(max(40, min(leg, room)), slope, gap)
                slope = -slope
        else:
            slope = 1 if rnd(2) else -1
            if self._room(slope, gap) < 120:
                slope = -slope
            length = max(60, min(150 + rnd(400), self._room(slope, gap)))
            spikes = []
            if d >= 500 and length >= 360:                            # 5.13: two on a long ramp, same side
                side = rnd(2)
                spikes = [(self.x_end + length // 3, side), (self.x_end + 2 * length // 3, side)]
            elif d >= 150 and length >= 200:                          # 4.5: ramps too
                spikes = [(self.x_end + length // 2, rnd(2))]
            self._add(length, slope, gap, spikes)

    def ensure(self, x: int) -> None:
        while self.x_end <= x + 4000:
            self.grow()

    def index(self, x: int) -> int:
        return max(0, bisect.bisect_right(self.starts, x) - 1)

    def bounds(self, i: int, x: int):
        x0, _ln, c0, slope, gap, spikes = self.segs[i]
        c = c0 + slope * (x - x0)
        half = gap // 2
        top, bot = c - half, c + half
        hh = gap * 38 // 100
        for xs, side in spikes:
            dx = abs(x - xs)
            if dx < WAVE_SW:
                k = hh * (WAVE_SW - dx) // WAVE_SW
                if side == 0:
                    top = max(top, c - half + k)
                else:
                    bot = min(bot, c + half - k)
        return top, bot


WAVE_FREE_X = 10000         # 5.3: the first 100 m (the walked start) pay nothing


def wave_pay(x: int) -> int:
    """Coins for a solo distance before the mini game limits (the server's rb_wave_pay_for)."""
    return (max(0, int(x) - WAVE_FREE_X) // 1000) * 5


def metres(x: int) -> int:
    return int(x) // 100


def level_colour(d: int) -> QColor:
    """The walls change colour as it gets harder: green, cyan, violet, then red."""
    stops = [(0, (0.40, 0.75)), (350, (0.52, 0.80)), (700, (0.76, 0.75)), (1000, (0.98, 0.85))]
    for (a, (ha, sa)), (b, (hb, sb)) in zip(stops, stops[1:]):
        if d <= b:
            t = (d - a) / max(1, b - a)
            return QColor.fromHsvF(ha + (hb - ha) * t, sa + (sb - sa) * t, 1.0)
    return QColor.fromHsvF(0.98, 0.85, 1.0)


WAVE_TIERS = [(0, "Easy"), (300, "Medium"), (500, "Hard"), (700, "Insane"), (880, "Extreme")]     # 250 / 500 / 750 / 1 000 m


def wave_tier_of(d: int) -> int:
    return max(i for i, (lo, _n) in enumerate(WAVE_TIERS) if d >= lo)


class WaveRunner:
    """4.5: another player's wave, rebuilt from the ticks where they pressed or let go (the server's maths). Past the
    last tick known it keeps going the same way, until newer ticks come in."""

    def __init__(self, course, name: str = "") -> None:
        self.course, self.name = course, name
        self.tg: list = []
        self.ys = [500]
        self.crash = None                    # the tick where this path hits a wall
        self.upto = 0
        self.done = False
        self.final = None                    # the last tick of a finished run
        self.shown_y = None
        self.fade_at = 0.0
        self.disp = None                     # 6.4: where this wave is shown (a smooth tick, always inside what is known)
        self.stamp = 0.0
        self.reached = False                 # a finished run: the crash is now shown
        self.reach_at = 0.0

    def set(self, toggles, upto: int, done: bool = False, final=None) -> None:
        tg = sorted({int(t) for t in (toggles or []) if int(t) > 0})
        if tg != self.tg:                    # 5.13: keep the path up to the first new toggle (it used to be rebuilt from
            k = 0                            # the start every time news came in: the stutter in long duels)
            while k < min(len(tg), len(self.tg)) and tg[k] == self.tg[k]:
                k += 1
            cut = min(tg[k] if k < len(tg) else 10 ** 9, self.tg[k] if k < len(self.tg) else 10 ** 9)
            self.tg = tg
            del self.ys[max(1, cut):]
            if self.crash is not None and self.crash >= cut:
                self.crash = None
        self.upto = max(self.upto, int(upto or 0))
        if done and not self.done:
            self.done, self.fade_at = True, time.monotonic()
        if final is not None:
            self.final = int(final)

    def y(self, t: int) -> int:
        t = max(0, int(t))
        while len(self.ys) <= t and self.crash is None:
            n = len(self.ys)
            held = bisect.bisect_right(self.tg, n) % 2 == 0
            y = self.ys[-1] + (-WAVE_VX if held else WAVE_VX)
            x = n * WAVE_VX
            self.course.ensure(x)
            top, bot = self.course.bounds(self.course.index(x), x)
            if n <= WAVE_SLIDE:                                     # 5.1: sliding on the start
                y = max(top + WAVE_R, min(bot - WAVE_R, y))
            self.ys.append(y)
            if n > WAVE_SLIDE and (y - WAVE_R < top or y + WAVE_R > bot):
                self.crash = n
        return self.ys[min(t, len(self.ys) - 1)]

    def held(self, t: int) -> bool:
        return bisect.bisect_right(self.tg, t) % 2 == 0


# ================================================================ the game view
class WaveView(QWidget):
    """The run. ready -> (press) -> run -> dead. on_end(ticks, toggles, x) is called once when a run ends."""

    def __init__(self, page, width: int, on_end=None, on_start=None) -> None:
        super().__init__()
        self.page, self.ctx = page, page.ctx
        self.setFixedSize(width, int(width * 0.66) + S(WAVE_HUD))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.on_end, self.on_start = on_end, on_start
        self.seed = None
        self.course = None
        self.state = "wait"                  # wait (no seed yet), ready, count, run, dead
        self.count_until = 0.0
        self.best = 0
        self.message = ""                    # under the result (coins, waiting for the other player…)
        self.message_col = TEXT_DIM
        self.other = None                    # duel: the other player's WaveRunner (seen see-through)
        self.auto_start = False              # duel: both start together when the countdown ends
        self.god = False                     # duel: the other one crashed and you are past them: nothing can hit you
        self.run_t0 = 0.0                    # when tick 0 was (for the other player's position)
        self.spectate = False                # duel: after you crash, you watch the other player until they crash too
        self._cam = None
        self._cam_t = 0.0
        self.watch = None                    # spectating: [runner a, runner b, t0]
        self.replay = None                   # dict: the last seconds before a crash, shown again
        self.can_retry = False               # solo: the next course is in, a press starts again
        self.result = None                   # duel: (title, line, colour) once it is over
        self.bot_on = bool(page.ctx.cfg["wave_bot"])       # 5.1: the practice bot
        self.bot = None
        self.runners = {}                    # 9.2: a room: the other players' waves, by name
        self.spec = None                     # 9.2: who you are watching after your crash
        self.my_col = None                   # 9.2: your seat's colour in a room
        self._legend = []                    # 9.2: (rect, name) of the names under the course
        self._reset()
        self._timer = QTimer(self)
        self._timer.setTimerType(Qt.TimerType.PreciseTimer)
        self._timer.setInterval(self._frame_ms())          # 6.0: one frame per screen refresh (no judder)
        self._timer.timeout.connect(self._frame)
        self._timer.start()
        self._idle_paint = 0.0
        self.keys = KeyPoll(["Space", "Up", "W"], self._key, lambda: self.state == "run", foreground_only=True)
        self.keys.setParent(self)

    # -- set up
    def _reset(self) -> None:
        self.t, self.x, self.y = 0, 0, 500
        self.held, self.held_in = True, False
        self.toggles: list = []
        self.trail: list = [(0, 500)]
        self.i = 0
        self.acc = 0.0
        self.last = time.monotonic()
        self.dead_at = 0.0
        self.parts: list = []
        self._cam = None

    def load(self, seed: int, count_until: float = 0.0) -> None:
        """A new course: ready to start (after a countdown in a duel)."""
        self.seed = int(seed)
        self.course = WaveCourse(self.seed)
        self.course.ensure(4000)
        self.bot = WaveBot(WaveCourse(self.seed))            # 5.1: its own copy of the same course
        self._reset()
        self.message = ""
        self.can_retry = False
        self.state = "count" if count_until > time.monotonic() else "ready"
        self.count_until = count_until
        self.update()

    def wait(self, text: str = "") -> None:
        self.state = "wait"
        self.message = text
        self.update()

    # -- input
    def _press(self, on: bool) -> None:
        self.held_in = on
        if on and self.state == "ready":
            self._go()

    def _go(self) -> None:
        self.state = "run"
        try:                                              # 5.3: Ruben's secret god mode: the wave flies itself
            ctx = self.page.ctx
            self.autopilot = bool(ctx.cfg["godmode"] and ctx.cfg["cheats"] and ctx.econ.admin
                                  and (ctx.online.username() or "").lower() == "ruben" and self.course is not None)
        except Exception:  # noqa: BLE001
            self.autopilot = False
        self.autobot = WaveBot(WaveCourse(self.seed)) if self.autopilot else None
        self.held, self.t = True, 0
        self.acc, self.last = 0.0, time.monotonic()
        self.run_t0 = self.last
        sfx.play("pick")
        GamePerf.enter(self.ctx)                          # 6.0: the hidden performance mode, for this run only
        if self.on_start:
            self.on_start()

    def finish_now(self) -> None:
        """Duel: the other player crashed and you are past them. Your run ends here, safely (no crash)."""
        if self.state != "run":
            return
        self.god = True
        self.state = "safe"
        self.dead_at = time.monotonic()
        sfx.play("on")
        QTimer.singleShot(0, lambda: GamePerf.leave(self.ctx))
        if self.on_end:
            self.on_end(self.t, list(self.toggles), self.x)

    def set_other(self, name: str, toggles, upto: int, done: bool, final=None) -> None:
        if self.course is None:
            return
        if self.other is None:
            self.other = WaveRunner(self.course, name)
        self.other.set(toggles, upto, done, final)

    def set_runner(self, name: str, seat: int, toggles, upto: int, done: bool, final=None) -> None:
        """9.2: a room: one of the other players, rebuilt from their presses (their seat gives their colour)."""
        if self.course is None:
            return
        run = self.runners.get(name)
        if run is None:
            run = WaveRunner(self.course, "")
            run.pname, run.col = name, QColor(WAVE_SEAT_COLS[int(seat) % 4])
            self.runners[name] = run
        run.set(toggles, upto, done, final)

    def _spec_runner(self):
        """9.2: the room player you are watching: the one you picked, or the one furthest along that is still going."""
        if not self.runners:
            return None
        now = time.monotonic()
        alive = [o for o in self.runners.values() if not o.reached]
        cur = self.runners.get(self.spec)
        if cur is None or (cur.reached and now - cur.reach_at > 1.6 and alive):
            pick = max(alive, key=lambda o: o.upto) if alive else (cur or next(iter(self.runners.values())))
            self.spec = pick.pname
            self._cam_t = now
        return self.runners.get(self.spec)

    def cycle_spec(self, step: int) -> None:
        names = [n for n, o in sorted(self.runners.items(), key=lambda kv: kv[1].col.name()) if not o.reached]
        if not names:
            return
        i = names.index(self.spec) if self.spec in names else -1
        self.spec = names[(i + step) % len(names)]
        sfx.play("pick")
        self.update()

    def start_replay(self, loser: WaveRunner, winner, title: str) -> None:
        """The last seconds before the crash, again: both waves, black bars, REPLAY."""
        end = loser.final if loser.final is not None else (loser.crash or loser.upto)
        loser.y(end + 40)
        if winner is not None:
            winner.y(end + 40)
        now = time.monotonic()
        wait = 0.0                                      # the other player first fades out where they crashed
        if self.other is not None and self.other.done and self.other.fade_at:
            wait = max(0.0, self.other.fade_at + 1.5 - now)
        rp = {"loser": loser, "winner": winner, "t0": max(0, end - 330), "t1": end, "at": now + wait + 0.5, "title": title}

        def go() -> None:
            try:
                self.replay = rp
                self.state = "replay"
                self.update()
            except RuntimeError:
                pass
        self._pending_replay = rp
        try:
            self.page.ctx.notifier.hold(wait + 0.5 + (rp["t1"] - rp["t0"]) / WAVE_TPS + 2.0)   # 4.6: no spoiler
        except AttributeError:
            pass
        QTimer.singleShot(int(wait * 1000), go)

    def mousePressEvent(self, e) -> None:
        e.accept()
        self.setFocus()
        win.take_focus(int(self.window().winId()), True)          # 9.4: a click brings Rubenium in front again
        for rect, name in self._legend:                    # 9.2: click a name to watch that player
            if rect.contains(e.position()) and self.state == "dead" and name in self.runners:
                self.spec = name
                sfx.play("pick")
                return self.update()
        if e.button() == Qt.MouseButton.LeftButton:
            self._press(True)

    def mouseReleaseEvent(self, e) -> None:
        if e.button() == Qt.MouseButton.LeftButton:
            self._press(False)

    def _key(self, _name: str, _down: bool) -> None:
        held = any(self.keys.down.values())
        if held != self.held_in or held:
            self._press(held)

    def keyPressEvent(self, e) -> None:
        if e.key() in (Qt.Key.Key_Space, Qt.Key.Key_Up, Qt.Key.Key_W):
            if not e.isAutoRepeat() and not self.keys.live:
                self._press(True)
            return e.accept()
        if e.key() in (Qt.Key.Key_Left, Qt.Key.Key_Right, Qt.Key.Key_A, Qt.Key.Key_D) and self.runners and self.state == "dead":
            self.cycle_spec(-1 if e.key() in (Qt.Key.Key_Left, Qt.Key.Key_A) else 1)
            return e.accept()
        super().keyPressEvent(e)

    def keyReleaseEvent(self, e) -> None:
        if e.key() in (Qt.Key.Key_Space, Qt.Key.Key_Up, Qt.Key.Key_W):
            if not e.isAutoRepeat() and not self.keys.live:
                self._press(False)
            return e.accept()
        super().keyReleaseEvent(e)

    def hideEvent(self, _e) -> None:
        if self.state == "run":                       # no pausing in the middle of a run: hiding it ends it
            self._crash()
        self._timer.stop()
        GamePerf.leave(self.ctx)
        try:
            win.take_focus(int(self.window().winId()), False)     # 9.4: the keyboard goes back to normal
        except RuntimeError:
            pass

    def showEvent(self, _e) -> None:
        self._timer.setInterval(self._frame_ms())
        self._timer.start()
        win.take_focus(int(self.window().winId()), True)          # 9.4: Wave Rush takes the keyboard while open

    def _frame_ms(self) -> int:
        """6.0: the timer follows the screen's refresh rate (60, 75, 120, 144 Hz…), so every frame shown is a new
        position the same distance apart: no more judder from 125 frames a second on a 60 Hz screen."""
        try:
            scr = self.screen() or QGuiApplication.primaryScreen()
            hz = float(scr.refreshRate()) if scr is not None else 60.0
        except Exception:  # noqa: BLE001
            hz = 60.0
        hz = max(50.0, min(240.0, hz or 60.0))
        return max(4, int(1000.0 / hz))

    def closeEvent(self, e) -> None:
        GamePerf.leave(self.ctx)
        super().closeEvent(e)

    # -- the run: fixed 60 ticks a second
    def _tick(self) -> bool:
        b = getattr(self, "autobot", None)
        if b is not None:                                 # 5.3: god mode: a perfect path, real inputs (the server agrees)
            if not (len(b.ys) > self.t and b.ys[self.t] == self.y):
                b.ys = [self.y] * (self.t + 1)            # plan again from exactly where the wave is
            self.held_in = b.y(self.t + 1) < self.y
        self.t += 1
        if self.held_in != self.held:
            self.toggles.append(self.t)
            self.held = self.held_in
        self.x += WAVE_VX
        self.y += -WAVE_VX if self.held else WAVE_VX
        self.course.ensure(self.x)
        segs = self.course.segs
        while self.x >= segs[self.i][0] + segs[self.i][1]:
            self.i += 1
        top, bot = self.course.bounds(self.i, self.x)
        if self.t <= WAVE_SLIDE:                                   # 5.1: the start slides, it never crashes
            self.y = max(top + WAVE_R, min(bot - WAVE_R, self.y))
        self.trail.append((self.x, self.y))
        if len(self.trail) > 400:
            del self.trail[:100]
        if self.god:
            return True
        if getattr(self.ctx, "wave_god", False) and self.t < WAVE_MAX:     # 6.0: god mode: slide, never crash
            self.y = max(top + WAVE_R, min(bot - WAVE_R, self.y))
            if self.trail:
                self.trail[-1] = (self.x, self.y)
            return True
        if (self.t > WAVE_SLIDE and (self.y - WAVE_R < top or self.y + WAVE_R > bot)) or self.t >= WAVE_MAX:
            self._crash()
            return False
        return True

    def _crash(self) -> None:
        self.state = "dead"
        self.dead_at = time.monotonic()
        sfx.play("lose")
        QTimer.singleShot(0, lambda: GamePerf.leave(self.ctx))
        rnd = random.Random(self.t)
        self.parts = [(rnd.uniform(0, math.tau), rnd.uniform(90, 420), rnd.uniform(3, 7)) for _ in range(26)]
        if self.on_end:
            self.on_end(self.t, list(self.toggles), self.x)

    def _frame(self) -> None:
        now = time.monotonic()
        if self.state == "count" and now >= self.count_until:
            self.state = "ready"
            sfx.play("on")
            if self.auto_start:                   # duel: everyone starts at the same moment
                self._go()
        if self.state == "replay" and self.replay and now > self.replay["at"] + (self.replay["t1"] - self.replay["t0"]) / WAVE_TPS + 1.6:
            done, self.replay = self.replay.get("then"), None
            self.state = "wait"
            if done:
                done()
        if self.state == "run":
            self.acc += min(0.5, now - self.last)          # 5.13: a hitch of up to half a second is caught up, not lost
            self.last = now
            step = 1.0 / WAVE_TPS
            while self.acc >= step and self.state == "run":
                self.acc -= step
                self._tick()
            GamePerf.alive()
            try:
                self.ctx.notifier.hold(0.5)                # 6.0: no pop-up in the middle of a run
            except Exception:  # noqa: BLE001
                pass
        elif self.state in ("wait", "ready") and self.watch is None and self.replay is None:
            if now - self._idle_paint < 0.05:              # 6.0: nothing moving: 20 frames a second is plenty
                return
            self._idle_paint = now
        self.update()

    # -- drawing
    def _scale(self) -> float:
        return (self.height() - S(WAVE_HUD)) / WAVE_H

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        now = time.monotonic()
        full = QRectF(self.rect())
        hud_h = S(WAVE_HUD)
        clip = QPainterPath()
        clip.addRoundedRect(full.adjusted(0.5, 0.5, -0.5, -0.5), S(12), S(12))
        p.setClipPath(clip)
        p.fillRect(QRectF(0, 0, full.width(), hud_h), QColor("#07090C"))          # 5.1: the HUD's own strip
        p.fillRect(QRectF(0, hud_h - 1, full.width(), 1), alpha("#FFFFFF", 0.08))
        p.translate(0, hud_h)
        r = QRectF(0, 0, full.width(), full.height() - hud_h)
        clip2 = QPainterPath()
        clip2.addRect(r)
        p.setClipPath(clip2)
        sc = self._scale()
        focus = self._focus(now)
        d = wave_level(focus)
        col = level_colour(d)
        bg = QLinearGradient(r.topLeft(), r.bottomLeft())
        bg.setColorAt(0, mix(QColor("#06080C"), col, 0.10))
        bg.setColorAt(1, QColor("#050608"))
        p.fillRect(r, bg)
        cam = focus - r.width() * 0.28 / sc                 # course x at the left edge
        if self.state == "dead":                            # a short shake when it crashes
            k = max(0.0, 1.0 - (now - self.dead_at) / 0.35)
            p.translate(math.sin(now * 90) * S(5) * k, math.cos(now * 70) * S(4) * k)
        p.setPen(QPen(alpha("#FFFFFF", 0.035), 1))          # a grid that scrolls slower than the course
        step = 200
        first = int((cam * 0.5) // step) * step
        gx = first if self.state != "run" else 10 ** 9      # 6.0: skipped while running (performance mode)
        while (gx - cam * 0.5) * sc < r.width():
            xx = (gx - cam * 0.5) * sc
            p.drawLine(QPointF(xx, 0), QPointF(xx, r.height()))
            gx += step
        if self.course is not None:
            self._paint_course(p, r, cam, sc, col)
            if self.replay is None and self.watch is None:   # 5.3: where the coins start (the first 100 m pay nothing)
                self._paint_pay_line(p, r, cam, sc, now)
            if self.replay is not None:
                rp = self.replay
                t = self._replay_t(now)
                if rp["winner"] is not None:
                    self._paint_runner(p, r, cam, sc, rp["winner"], t, QColor("#FFB627"), 0.45, now)
                self._paint_runner(p, r, cam, sc, rp["loser"], t, col, 1.0, now, boom=True)
            elif self.watch is not None:
                ta = self._watch_t(0, now)
                tb = self._watch_t(1, now)
                self._paint_runner(p, r, cam, sc, self.watch[0], ta, ui.accent, 0.95, now, boom=True)
                self._paint_runner(p, r, cam, sc, self.watch[1], tb, QColor("#FFB627"), 0.95, now, boom=True)
            else:
                self._paint_bot(p, r, cam, sc, now)
                self._paint_ghost(p, r, cam, sc, now)
                self._paint_room(p, r, cam, sc, now)
                self._paint_wave(p, r, cam, sc, self.my_col or col, now)
        if self.state == "run" and self.t <= WAVE_SLIDE and self.course is not None:     # 5.1: the start slide
            k = 1.0 - self.t / WAVE_SLIDE
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha("#3DDC84", 0.18 * k))
            p.drawRect(QRectF(0, r.height() - S(8), r.width(), S(8)))
            p.drawRect(QRectF(0, 0, r.width(), S(8)))
            p.setPen(alpha("#FFFFFF", 0.85 * k))
            p.setFont(font(12, QFont.Weight.Bold))
            p.drawText(QRectF(0, r.height() * 0.12, r.width(), S(22)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Hold to go up, let go to go down"))
        p.setClipping(False)
        p.resetTransform()
        p.setClipPath(clip)
        play = QRectF(0, hud_h, full.width(), full.height() - hud_h)
        if self.replay is not None:
            p.translate(0, hud_h)
            return self._paint_replay_hud(p, QRectF(0, 0, play.width(), play.height()), now)
        self._paint_hud(p, play, col, now)
        self._paint_legend(p, play, now)

    def _paint_pay_line(self, p, r, cam, sc, now) -> None:
        xx = (WAVE_FREE_X - cam) * sc
        if xx < -S(80) or xx > r.width() + S(80):
            return
        gold = QColor("#FFC94D")
        pulse = 0.6 + 0.4 * math.sin(now * 3)
        p.setPen(QPen(alpha(gold, 0.25), S(8)))
        p.drawLine(QPointF(xx, 0), QPointF(xx, r.height()))
        p.setPen(QPen(alpha(gold, 0.55 + 0.35 * pulse), S(2), Qt.PenStyle.DashLine))
        p.drawLine(QPointF(xx, 0), QPointF(xx, r.height()))
        paint_coin(p, QPointF(xx, r.height() * 0.5), S(11))         # 6.0: the line and the coin say it, no words

    def _paint_course(self, p, r, cam, sc, col) -> None:
        c = self.course
        x_from, x_to = int(cam) - 20, int(cam + r.width() / sc) + 20
        c.ensure(x_to)
        xs, tops, bots = [], [], []
        i = c.index(max(0, x_from))
        x = max(0, x_from - x_from % 6)
        while x <= x_to:
            while i + 1 < len(c.segs) and x >= c.segs[i + 1][0]:
                i += 1
            t, b = c.bounds(i, x)
            xs.append((x - cam) * sc)
            tops.append(t * sc)
            bots.append(b * sc)
            x += 6
        if not xs:
            return
        if x_from < 0:                                     # before the start: a closed wall behind the wave
            p.fillRect(QRectF(0, 0, (0 - cam) * sc, r.height()), mix(QColor("#0B0F14"), col, 0.18))
        fill = QLinearGradient(QPointF(0, 0), QPointF(0, r.height()))
        fill.setColorAt(0, mix(QColor("#0B0F14"), col, 0.22))
        fill.setColorAt(0.5, mix(QColor("#0B0F14"), col, 0.10))
        fill.setColorAt(1, mix(QColor("#0B0F14"), col, 0.22))
        top_poly = QPolygonF([QPointF(xs[0], -S(4))] + [QPointF(a, b) for a, b in zip(xs, tops)] + [QPointF(xs[-1], -S(4))])
        bot_poly = QPolygonF([QPointF(xs[0], r.height() + S(4))] + [QPointF(a, b) for a, b in zip(xs, bots)] +
                             [QPointF(xs[-1], r.height() + S(4))])
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(fill)
        p.drawPolygon(top_poly)
        p.drawPolygon(bot_poly)
        for w, a in ((S(6), 0.18), (S(2.2), 1.0)):         # the glowing edge
            p.setPen(QPen(alpha(col, a), w, Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.RoundJoin))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPolyline(QPolygonF([QPointF(a_, b_) for a_, b_ in zip(xs, tops)]))
            p.drawPolyline(QPolygonF([QPointF(a_, b_) for a_, b_ in zip(xs, bots)]))

    # -- the camera
    def _focus(self, now: float) -> float:
        if self.replay is not None:
            return self._replay_t(now) * WAVE_VX
        if self.watch is not None:
            return max(self._watch_t(0, now), self._watch_t(1, now)) * WAVE_VX
        if self._spectating():                             # 6.4: you crashed: the camera moves over to the other player
            o = self.other if self.other is not None else self._spec_runner()
            gx = (o.disp if o.disp is not None else self.x / WAVE_VX) * WAVE_VX
            if self._cam is None:
                self._cam, self._cam_t = float(self.x), now
            self._cam += (gx - self._cam) * min(1.0, max(0.0, now - self._cam_t) * 5.0)
            self._cam_t = now
            return self._cam
        return self.x + self._sub() * WAVE_VX              # 5.7: smooth between two physics steps

    def _sub(self) -> float:
        """5.7: how far into the next 1/60 s step we are (0-1), to draw between steps: smooth at any frame rate."""
        if self.state != "run":
            return 0.0
        return max(0.0, min(1.0, self.acc * WAVE_TPS))

    def _replay_t(self, now: float) -> int:
        rp = self.replay
        return int(min(rp["t1"] + 30, rp["t0"] + max(0.0, now - rp["at"]) * WAVE_TPS))

    def _watch_t(self, i: int, now: float) -> float:
        """Spectating: where each player is shown (a little behind, so the path shown is the real one)."""
        return self._ghost_tick(self.watch[i], now, self.watch[2])

    def _ghost_tick(self, o, now: float, t0: float, lag: int = GHOST_LAG) -> float:
        """6.4: a smooth tick for another wave. It never goes past what the server told us (no guessing, so no waves
        running into walls) and it speeds up or slows down a little to stay about GHOST_LAG ticks behind real time."""
        cap = float(o.final) if (o.done and o.final is not None) else float(o.upto)
        if o.crash is not None:
            cap = min(cap, float(o.crash))
        target = (now - t0) * WAVE_TPS - lag if t0 else 0.0
        dt = min(0.25, max(0.0, now - o.stamp)) if o.stamp else 0.0
        o.stamp = now
        if o.disp is None or target - o.disp > WAVE_TPS * 6 or o.disp - target > WAVE_TPS * 3:
            o.disp = max(0.0, min(target, cap))
        else:
            gap = target - o.disp
            o.disp += dt * WAVE_TPS * max(0.3, min(2.5, 1.0 + gap / 30.0))
        o.disp = max(0.0, min(o.disp, cap))
        if o.done and o.final is not None and o.disp >= cap - 0.01 and not o.reached:
            o.reached, o.reach_at, o.fade_at = True, now, now
        return o.disp

    def _spectating(self) -> bool:
        return (self.spectate and self.state == "dead" and (self.other is not None or bool(self.runners))
                and time.monotonic() - self.dead_at > 0.9)

    def _paint_room(self, p, r, cam, sc, now) -> None:
        """9.2: the other players of a room, live, each in their seat's colour. The one you watch is clear, the others
        see-through; a crashed wave bursts and fades."""
        if not self.runners or self.state not in ("run", "safe", "dead") or not self.run_t0:
            return
        spec = self._spec_runner() if self._spectating() else None
        order = [o for o in self.runners.values() if o is not spec] + ([spec] if spec is not None else [])
        for o in order:
            tf = self._ghost_tick(o, now, self.run_t0, ROOM_LAG)
            fade = 1.0
            if o.reached:
                fade = max(0.0, 1.0 - (now - o.reach_at) / 2.2)
                if fade <= 0:
                    continue
            base = 1.0 if o is spec else (0.42 if spec is not None else 0.55)
            self._paint_runner(p, r, cam, sc, o, tf, o.col, base * fade, now, boom=True)

    def _paint_legend(self, p, play: QRectF, now) -> None:
        """9.2: who is who, under the course: a colour and a name each (no names over the waves)."""
        self._legend = []
        if not self.runners:
            return
        rows = [(self.ctx.online.username() or tr("You"), self.my_col or QColor(WAVE_SEAT_COLS[0]), None)]
        rows += [(o.pname, o.col, o) for o in sorted(self.runners.values(), key=lambda o: WAVE_SEAT_COLS.index(o.col.name().upper())
                                                      if o.col.name().upper() in WAVE_SEAT_COLS else 9)]
        p.setFont(font(9.5, QFont.Weight.Bold))
        fm = p.fontMetrics()
        h = S(22)
        widths = [S(26) + fm.horizontalAdvance(n) + S(46) for n, _c, _o in rows]
        x = play.center().x() - (sum(widths) + S(6) * (len(rows) - 1)) / 2
        y = play.bottom() - h - S(8)
        spec = self.runners.get(self.spec) if self._spectating() else None
        for (name, col, o), w in zip(rows, widths):
            box = QRectF(x, y, w, h)
            me = o is None
            out = (self.state in ("dead", "safe")) if me else o.reached
            watched = o is not None and o is spec
            p.setPen(QPen(alpha(col, 0.9 if watched else 0.35), S(1.4 if watched else 1)))
            p.setBrush(alpha("#000000", 0.62))
            p.drawRoundedRect(box, h / 2, h / 2)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha(col, 0.35 if out else 1.0))
            p.drawEllipse(QPointF(box.left() + S(13), box.center().y()), S(5), S(5))
            p.setPen(alpha(TEXT, 0.5 if out else 1.0))
            p.drawText(QRectF(box.left() + S(24), box.top(), w - S(24), h), int(Qt.AlignmentFlag.AlignVCenter), name)
            if me:
                dist = metres(int(self.x))
            else:
                dist = metres(int((o.final if o.reached and o.final is not None else (o.disp or 0)) * WAVE_VX))
            p.setPen(QColor(TEXT_FAINT if out else TEXT_DIM))
            p.drawText(QRectF(box.left(), box.top(), w - S(10), h),
                       int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight), f"{dist} m")
            if o is not None:
                self._legend.append((box, name))
            x += w + S(6)

    def ghost_ready(self) -> bool:
        """Duel: have we shown the other player's end (so the result can come up)?"""
        o = self.other
        if o is None or not o.done or o.final is None or not (self.spectate and self.state == "dead"):
            return True
        return o.reached or time.monotonic() - (o.fade_at or 0.0) > 7.0

    def _paint_runner(self, p, r, cam, sc, run: WaveRunner, t: int, col, opacity: float, now: float, boom=False) -> None:
        """Another wave: its trail and its arrow at tick t (or where it crashed)."""
        tf = float(t)
        end = int(tf)
        frac = tf - end
        if run.done and run.final is not None and end >= run.final:
            end, frac = int(run.final), 0.0
        if run.crash is not None and run.crash <= end + 1 and run.crash <= run.upto + 1:
            if end >= run.crash:
                end, frac = min(end, run.crash), 0.0
        if frac > 0 and end + 1 > run.upto:
            frac = 0.0
        first = max(0, end - 160)
        pts = [QPointF((k * WAVE_VX - cam) * sc, run.y(k) * sc) for k in range(first, end + 1, 2)]
        if not pts:
            return
        if frac > 0:
            run.y(end + 1)
            pts.append(QPointF(((end + frac) * WAVE_VX - cam) * sc, (run.y(end) + (run.y(end + 1) - run.y(end)) * frac) * sc))
        p.setOpacity(opacity)
        if len(pts) >= 2:
            for w, a in ((S(6), 0.12), (S(2.6), 0.8)):
                p.setPen(QPen(alpha(mix(col, QColor("#FFFFFF"), 0.45), a), w, Qt.PenStyle.SolidLine,
                              Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
                p.drawPolyline(QPolygonF(pts))
        c = pts[-1] if frac > 0 else QPointF((end * WAVE_VX - cam) * sc, run.y(end) * sc)
        crashed = run.done and run.final is not None and t >= run.final
        if crashed and boom:
            k = min(1.0, (t - run.final) / 25.0) if t > run.final else (
                min(1.0, (now - run.reach_at) / 0.5) if run.reach_at else 0.0)
            p.setPen(Qt.PenStyle.NoPen)
            for j in range(12):
                ang = j * math.tau / 12
                q = c + QPointF(math.cos(ang) * S(26) * k, math.sin(ang) * S(26) * k)
                p.setBrush(alpha(col, max(0.0, 1.0 - k)))
                p.drawEllipse(q, S(3), S(3))
        else:
            p.save()
            p.translate(c)
            p.rotate(-45 if run.held(end) else 45)
            size = S(10)
            head = QPolygonF([QPointF(size, 0), QPointF(-size * 0.8, -size * 0.7), QPointF(-size * 0.35, 0),
                              QPointF(-size * 0.8, size * 0.7)])
            p.setPen(QPen(QColor("#FFFFFF"), S(1.2)))
            p.setBrush(mix(QColor("#FFFFFF"), col, 0.5))
            p.drawPolygon(head)
            p.restore()
        if run.name:
            p.setPen(alpha(col, 0.95))
            p.setFont(font(9, QFont.Weight.Bold))
            p.drawText(QRectF(c.x() - S(60), c.y() - S(28), S(120), S(14)), int(Qt.AlignmentFlag.AlignCenter), run.name)
        p.setOpacity(1.0)

    def _paint_bot(self, p, r, cam, sc, now) -> None:
        """5.1: the practice bot, see-through, 40 ticks ahead of you."""
        if not self.bot_on or self.bot is None or self.state not in ("run", "ready", "count"):
            return
        t = (self.t + 40) if self.state == "run" else 40
        try:
            pts = [QPointF((k * WAVE_VX - cam) * sc, self.bot.y(k) * sc) for k in range(max(0, t - 90), t + 1, 2)]
        except Exception:  # noqa: BLE001
            return
        cyan = QColor("#4FE3FF")
        p.setOpacity(0.32)
        if len(pts) >= 2:
            p.setPen(QPen(cyan, S(2), Qt.PenStyle.DashLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
            p.drawPolyline(QPolygonF(pts))
        c = pts[-1]
        up = len(pts) < 2 or pts[-1].y() < pts[-2].y()
        p.save()
        p.translate(c)
        p.rotate(-45 if up else 45)
        size = max(S(7), WAVE_R * sc * 2.2)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(cyan)
        p.drawPolygon(QPolygonF([QPointF(size, 0), QPointF(-size * 0.8, -size * 0.7), QPointF(-size * 0.35, 0),
                                 QPointF(-size * 0.8, size * 0.7)]))
        p.restore()
        p.setOpacity(0.55)
        p.setPen(cyan)
        p.setFont(font(8.5, QFont.Weight.Bold))
        p.drawText(QRectF(c.x() - S(40), c.y() - S(24), S(80), S(12)), int(Qt.AlignmentFlag.AlignCenter), "BOT")
        p.setOpacity(1.0)

    def _paint_ghost(self, p, r, cam, sc, now) -> None:
        """Duel: the other player, see-through (clear when you are watching them after your crash)."""
        o = self.other
        if o is None or self.state not in ("run", "safe", "dead") or not self.run_t0:
            return
        spec = self._spectating()
        tf = self._ghost_tick(o, now, self.run_t0)
        fade = 1.0
        if o.reached:                                 # they crashed: they fade out slowly where they crashed
            fade = max(0.0, 1.0 - (now - o.reach_at) / (3.0 if spec else 1.4))
            if fade <= 0:
                return
        t = int(tf)
        frac = tf - t
        o.y(t + 1)
        if o.crash is not None and t >= o.crash:
            t, frac = o.crash, 0.0
        y0 = o.y(t)
        hy = y0 + (o.y(t + 1) - y0) * frac if frac > 0 else y0
        first = max(0, t - 120)
        pts = [QPointF((k * WAVE_VX - cam) * sc, o.y(k) * sc) for k in range(first, t + 1, 3)]
        pts.append(QPointF(((t + frac) * WAVE_VX - cam) * sc, hy * sc))
        gold = QColor("#FFB627")
        base = 0.95 if spec else 0.38
        p.setOpacity(base * fade)
        if len(pts) >= 2:
            p.setPen(QPen(gold, S(3.0 if spec else 2.2), Qt.PenStyle.SolidLine, Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
            p.drawPolyline(QPolygonF(pts))
        c = pts[-1]
        if o.reached:
            k = min(1.0, (now - o.reach_at) / 0.5)
            p.setPen(Qt.PenStyle.NoPen)
            for j in range(12):
                ang = j * math.tau / 12
                p.setBrush(alpha(gold, max(0.0, 1.0 - k)))
                p.drawEllipse(c + QPointF(math.cos(ang) * S(26) * k, math.sin(ang) * S(26) * k), S(3), S(3))
        else:
            p.save()
            p.translate(c)
            p.rotate(-45 if o.held(t) else 45)
            size = S(12 if spec else 10)
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(gold)
            p.drawPolygon(QPolygonF([QPointF(size, 0), QPointF(-size * 0.8, -size * 0.7), QPointF(-size * 0.35, 0),
                                     QPointF(-size * 0.8, size * 0.7)]))
            p.restore()
        p.setOpacity((0.95 if spec else 0.6) * fade)
        p.setPen(gold)
        p.setFont(font(8.5, QFont.Weight.Bold))
        p.drawText(QRectF(c.x() - S(50), c.y() - S(24), S(100), S(12)), int(Qt.AlignmentFlag.AlignCenter), o.name)
        p.setOpacity(1.0)

    def _paint_wave(self, p, r, cam, sc, col, now) -> None:
        f = self._sub()
        hx = self.x + f * WAVE_VX                          # 5.7: the head drawn between steps (never ahead of a wall hit)
        hy = self.y + f * (-WAVE_VX if self.held_in else WAVE_VX) if self.state == "run" else self.y
        pts = [QPointF((tx - cam) * sc, ty * sc) for tx, ty in self.trail if (tx - cam) * sc > -S(10)]
        if self.state == "run":
            pts.append(QPointF((hx - cam) * sc, hy * sc))
        if len(pts) >= 2:                                  # the trail: the zigzag you drew
            for w, a in (((S(3), 0.85),) if self.state == "run" else ((S(7), 0.12), (S(3), 0.85))):
                p.setPen(QPen(alpha(mix(col, QColor("#FFFFFF"), 0.55), a), w, Qt.PenStyle.SolidLine,
                              Qt.PenCapStyle.RoundCap, Qt.PenJoinStyle.MiterJoin))
                p.drawPolyline(QPolygonF(pts))
        c = QPointF((hx - cam) * sc, hy * sc)
        if self.state in ("wait",) and self.result:
            return
        if self.state == "dead":
            age = now - self.dead_at
            for ang, sp, sz in self.parts:
                k = min(1.0, age / 0.6)
                q = c + QPointF(math.cos(ang) * sp * sc * 0.6 * k * 2.2, math.sin(ang) * sp * sc * 0.6 * k * 2.2)
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha(col if sz > 5 else QColor("#FFFFFF"), max(0.0, 1.0 - age / 0.9)))
                p.drawEllipse(q, S(sz) * (1 - 0.5 * k), S(sz) * (1 - 0.5 * k))
            return
        up = self.held if self.state == "run" else True
        p.save()
        p.translate(c)
        p.rotate(-45 if up else 45)
        size = max(S(7), WAVE_R * sc * 2.2)                      # 5.1: drawn the size of what can be hit
        head = QPolygonF([QPointF(size, 0), QPointF(-size * 0.8, -size * 0.7), QPointF(-size * 0.35, 0),
                          QPointF(-size * 0.8, size * 0.7)])
        p.setPen(QPen(alpha(col, 0.35), S(6)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPolygon(head)
        p.setPen(QPen(QColor("#FFFFFF"), S(1.4)))
        p.setBrush(mix(QColor("#FFFFFF"), col, 0.35))
        p.drawPolygon(head)
        p.restore()

    def _paint_hud(self, p, r, col, now) -> None:
        if self.state == "wait":
            p.fillRect(r, alpha("#000000", 0.55))
            return self._paint_wait(p, r)
        x = self._focus(now)
        p.setPen(QColor(TEXT))
        p.setFont(font(17, QFont.Weight.Black))
        p.drawText(QRectF(S(12), S(2), r.width() * 0.28, S(26)), int(Qt.AlignmentFlag.AlignVCenter), f"{metres(int(x))} m")
        if getattr(self.ctx, "wave_god", False):         # 6.0: Ruben's god mode is on
            p.setPen(QColor("#FF5C8A"))
            p.setFont(font(10, QFont.Weight.Black, 1.5))
            p.drawText(QRectF(r.width() * 0.3, S(4), S(60), S(22)), int(Qt.AlignmentFlag.AlignVCenter), "GOD")
        p.setFont(font(9.5, QFont.Weight.Bold))
        p.setPen(QColor(TEXT_DIM))
        if self.watch is None and self.replay is None and self.state in ("run", "ready", "count") and x < WAVE_FREE_X:
            p.setPen(QColor("#FFC94D"))                   # 5.3: the first 100 m pay nothing
            p.drawText(QRectF(S(12), S(26), r.width() * 0.28, S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                       tr("Coins from {n} m", n=metres(WAVE_FREE_X)))
        elif self.best and self.watch is None:
            p.drawText(QRectF(S(12), S(26), r.width() * 0.28, S(16)), int(Qt.AlignmentFlag.AlignVCenter),
                       tr("Best {n} m", n=metres(self.best)))
        self._paint_difficulty(p, r, self._focus(now), now)
        mid = QRectF(0, r.top() + r.height() * 0.30, r.width(), r.height() * 0.4)
        if self.state in ("ready", "count", "dead", "safe"):
            dim = 0.0 if (self.state in ("dead", "safe") and now - self.dead_at < 0.45) or self._spectating() else 0.55
            if dim:
                p.fillRect(r, alpha("#000000", dim))     # 5.1: r is the course only, the HUD strip stays readable
        if self.state == "count":
            n = max(1, math.ceil(self.count_until - now))
            self._big(p, mid, str(n), "#FFFFFF", 40)
        elif self.state == "ready":
            pulse = 0.75 + 0.25 * math.sin(now * 4)
            self._big(p, mid.adjusted(0, -S(14), 0, -S(14)), tr("Hold to start"), alpha("#FFFFFF", pulse), 20)
            pass
            labels = ["Hold", "Space", "Up", "W"]
            x = r.width() / 2 - S(62)
            for k in labels:
                x += paint_keycap(p, QPointF(x, mid.center().y() + S(24)), k) + S(6)
        elif self.state == "safe":
            self._big(p, mid.adjusted(0, -S(10), 0, -S(10)), tr("You outlasted them!"), "#3DDC84", 18)
            if self.message:
                self._big(p, mid.adjusted(0, S(20), 0, S(20)), self.message, self.message_col, 11.5)
        elif self.state == "dead" and self._spectating():
            o = self.other if self.other is not None else self._spec_runner()
            self._big(p, QRectF(r.left(), r.top() + S(40), r.width(), S(22)),
                      tr("You crashed at {n} m  ·  watching {name}", n=metres(self.x),
                         name=getattr(o, "pname", None) or o.name), "#FFFFFF", 11.5)
            if self.runners and sum(1 for x_ in self.runners.values() if not x_.reached) > 1:
                self._big(p, QRectF(r.left(), r.top() + S(62), r.width(), S(18)),
                          tr("◀ ▶ or click a name to watch someone else"), TEXT_DIM, 9.5)
        elif self.state == "dead" and now - self.dead_at >= 0.45:
            self._big(p, mid.adjusted(0, -S(22), 0, -S(22)), tr("Crashed at {n} m", n=metres(self.x)), "#FFFFFF", 20)
            if self.message:
                self._big(p, mid.adjusted(0, S(12), 0, S(12)), self.message, self.message_col, 12.5)
            if self.can_retry and now - self.dead_at > 0.9:
                pulse = 0.6 + 0.4 * math.sin(now * 4)
                self._big(p, mid.adjusted(0, S(44), 0, S(44)), tr("Press to go again"), alpha("#FFFFFF", pulse), 11)

    def _paint_difficulty(self, p, r, x: float, now: float) -> None:
        """4.5: no finish line, so no progress bar: a difficulty bar that keeps climbing, with the distance riding on it
        and the distance where the next level starts."""
        d = wave_level(int(x))
        bar = QRectF(r.width() * 0.30, S(13), r.width() * 0.66, S(7))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#FFFFFF", 0.08))
        p.drawRoundedRect(bar, bar.height() / 2, bar.height() / 2)
        g = QLinearGradient(bar.topLeft(), bar.topRight())
        for k in range(5):
            g.setColorAt(k / 4, level_colour(k * 250))
        fill = QRectF(bar.left(), bar.top(), max(bar.height(), bar.width() * d / 1000), bar.height())
        p.setBrush(g)
        p.drawRoundedRect(fill, bar.height() / 2, bar.height() / 2)
        if d < 1000:                                         # a soft shine running along the fill
            sx = fill.left() + (now * 0.6 % 1.0) * fill.width()
            sh = QLinearGradient(QPointF(sx - S(14), 0), QPointF(sx + S(14), 0))
            sh.setColorAt(0, alpha("#FFFFFF", 0.0))
            sh.setColorAt(0.5, alpha("#FFFFFF", 0.35))
            sh.setColorAt(1, alpha("#FFFFFF", 0.0))
            p.setBrush(sh)
            p.drawRoundedRect(fill, bar.height() / 2, bar.height() / 2)
        p.setFont(font(8, QFont.Weight.Bold))
        for (lo, name), metres_at in zip(WAVE_TIERS[1:], (250, 500, 750, 1000)):    # where each level starts
            tx = bar.left() + bar.width() * lo / 1000
            p.setPen(QPen(alpha("#FFFFFF", 0.55 if d >= lo else 0.25), 1))
            p.drawLine(QPointF(tx, bar.top() - S(2)), QPointF(tx, bar.bottom() + S(2)))
            p.setPen(alpha("#FFFFFF", 0.55 if d >= lo else 0.35))
            p.drawText(QRectF(tx - S(30), bar.bottom() + S(2), S(60), S(12)), int(Qt.AlignmentFlag.AlignCenter),
                       f"{metres_at} m")
        ti = wave_tier_of(d)
        col = level_colour(d)
        p.setPen(col)
        p.setFont(font(9.5, QFont.Weight.Black))
        p.drawText(QRectF(bar.left(), bar.top() - S(13), bar.width(), S(12)), int(Qt.AlignmentFlag.AlignLeft |
                   Qt.AlignmentFlag.AlignVCenter), tr(WAVE_TIERS[ti][1]).upper())
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(8.5, QFont.Weight.Bold))
        nxt = tr("Next level at {n} m", n=WAVE_TIERS[ti + 1][0] * 110 // 100) if ti + 1 < len(WAVE_TIERS) else \
            (tr("Hardest level") if d >= 1000 else tr("Hardest at {n} m", n=1100))
        p.drawText(QRectF(bar.left(), bar.top() - S(13), bar.width(), S(12)), int(Qt.AlignmentFlag.AlignRight |
                   Qt.AlignmentFlag.AlignVCenter), nxt)

    def _paint_replay_hud(self, p, r, now: float) -> None:
        rp = self.replay
        k = min(1.0, max(0.0, (now - rp["at"] + 0.5) / 0.45))
        bh = r.height() * 0.11 * k                           # black bars slide in
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor(0, 0, 0, 235))
        p.drawRect(QRectF(0, 0, r.width(), bh))
        p.drawRect(QRectF(0, r.height() - bh, r.width(), bh))
        if now < rp["at"]:                                   # the fade in
            p.fillRect(r, QColor(0, 0, 0, max(0, min(255, int(255 * (rp["at"] - now) / 0.5)))))
        dot = 0.5 + 0.5 * math.sin(now * 6)
        p.setBrush(alpha("#FF3B3B", 0.4 + 0.6 * dot))
        p.drawEllipse(QPointF(S(16), bh / 2), S(4.5), S(4.5))
        p.setPen(QColor("#FFFFFF"))
        p.setFont(font(12, QFont.Weight.Black, 2.0))
        p.drawText(QRectF(S(26), 0, S(120), bh), int(Qt.AlignmentFlag.AlignVCenter), tr("REPLAY"))
        p.setPen(QColor(TEXT_DIM))
        p.setFont(font(10, QFont.Weight.Bold))
        p.drawText(QRectF(0, 0, r.width() - S(12), bh), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                   rp["title"])
        span = max(1, rp["t1"] + 30 - rp["t0"])
        f = (self._replay_t(now) - rp["t0"]) / span
        line = QRectF(S(12), r.height() - bh / 2 - S(1.5), r.width() - S(24), S(3))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#FFFFFF", 0.15))
        p.drawRoundedRect(line, S(1.5), S(1.5))
        p.setBrush(QColor("#FF3B3B"))
        p.drawRoundedRect(QRectF(line.left(), line.top(), line.width() * min(1.0, f), line.height()), S(1.5), S(1.5))

    def _paint_wait(self, p, r) -> None:
        mid = QRectF(0, r.top() + r.height() * 0.30, r.width(), r.height() * 0.4)
        if self.result:
            title, line, colour = self.result
            self._big(p, mid.adjusted(0, -S(16), 0, -S(16)), title, colour, 24)
            self._big(p, mid.adjusted(0, S(20), 0, S(20)), line, TEXT, 12.5)
        else:
            self._big(p, mid, self.message or tr("Loading…"), TEXT_DIM, 13)

    def _big(self, p, rect, text, colour, size) -> None:
        p.setPen(QColor(colour) if not isinstance(colour, QColor) else colour)
        p.setFont(font(size, QFont.Weight.Black))
        p.drawText(rect, int(Qt.AlignmentFlag.AlignCenter), text)


