# The car each bot likes to drive (it takes another one when you drive the same).
AERIAL_BOT_CAR = {"pip": 0, "dusty": 2, "sprocket": 2, "ember": 1, "jinx": 1, "halo": 2, "vex": 0, "nova": 0,
                  "apex": 1, "ruben": 1}


def aerial_bot_car(key: str, mine: int) -> int:
    """The bot's car: its favourite, never the same car as yours."""
    k = AERIAL_BOT_CAR.get(key or "", 0)
    return k if k != mine else (k + 1) % len(AERIAL_CARS)


def aerial_bot_profile(key: str, lv_override: float = None) -> dict:
    """Every limit of one bot, worked out from its level. Calibration can move "lv"."""
    row = next(r for r in AERIAL_BOT_ROSTER if r[0] == key)
    k, name, rank, mmr, lv, about, tr = row
    if lv_override is not None:
        lv = lv_override
    L = max(0.0, min(1.2, lv))
    H = min(1.0, L)
    q = 1.0 - H
    X = max(0.0, (L - 1.0) / 0.2)          # past human: 0 .. 1 (Ruben)
    p = {
        "key": k, "name": name, "rank": rank, "mmr": mmr, "lv": lv, "about": about,
        "react": max(1, int(round(1 + 26 * q ** 1.4 - X))),     # steps it sees late
        "comp": 0.35 + 0.65 * H,                                # how well it makes up for that delay
        "replan": max(1, int(round(1 + 9 * q ** 1.2))),
        "horizon": 1.4 + 2.2 * H,                               # seconds of the ball it reads (walls included)
        "read": 0.20 * q ** 1.5 * (1 - X),                      # misreads the ball's speed by this share
        "aim": (0.20 * q ** 1.3 + 0.012) * (1 - 0.8 * X),       # radians
        "line": 0.02 + 0.30 * q,                                # how loose its line to the ball is
        "slack": 0.20 * q + 0.03,                               # seconds it allows itself to get there
        "noise": 0.45 * q + 0.05,                               # randomness in its choices
        "blunder": 0.10 * q ** 2,                               # a plain bad decision now and then
        "patience": 0.25 + 0.75 * H,                            # waits instead of over-committing
        "shadow_d": 900 - 400 * H,
        "boost_iq": 0.3 + 0.7 * H,                              # picks pads on its way, keeps boost for when it counts
        "feather": 0.4 + 0.6 * H,                               # boosts only as much as it needs
        "control": 0.45 + 0.55 * H + 0.1 * X,                   # how cleanly it keeps a dribble
        "flick_t": 0.55 - 0.30 * H,                             # how long it needs to turn a carry into a flick
        "urgency": 0.5 + 0.5 * H,                               # how fast it rotates back
        "read_opp": 0.2 + 0.8 * H,                              # reads your touches and rushes
        "drift_sense": 0.4 + 0.6 * H,
        "steer_res": 8 if H > 0.5 else 4,
        "machine": bool(tr.get("machine")),
        "kit": dict(AERIAL_BOT_KIT.get(k, AERIAL_BOT_KIT["pip"])),
    }
    p["plays"] = set(p["kit"]["plays"])
    p["guard"] = float(p["kit"].get("guard", 0.0))      # how disciplined its defence is (shadow depth, saves)
    return p


AERIAL_BOTS = {r[0]: aerial_bot_profile(r[0]) for r in AERIAL_BOT_ROSTER}


def aerial_apply_assist(m, team: int, key: str) -> None:
    """The hidden help (as the owner decided): from Master 2 up, more boost from the same pads and a little more top
    speed. It lives in the sim, so replays play back the same."""
    k = AERIAL_BOT_KIT.get(key or "")
    if k:
        m.sim.cars[team].assist = {"boost": float(k.get("boost", 1.0)), "speed": float(k.get("speed", 1.0)),
                                   "aim": float(k.get("aim", 0.0)), "shot": float(k.get("shot", 0.0))}


def _ae_turn_r(v: float, kind_turn: float = 1.0, drift: bool = False) -> float:
    """The tightest circle a car can drive at speed v."""
    t = AERIAL_TUNE
    v = abs(v)
    k = min(1.0, v / t["turn_slow_v"]) * (1.0 - t["turn_fast_cut"] * min(1.0, v / t["boost_max"]))
    w = t["turn"] * kind_turn * k * (t["drift_turn"] if drift else 1.0)
    return v / max(0.3, w)


def _ae_reachable(dn: float, ang: float, v: float, kind_turn: float = 1.0) -> bool:
    """Can a car at speed v reach a point dn ahead at angle ang without slowing down?"""
    s = abs(aerial_sin(ang)) if abs(ang) < _AE_PI / 2 else 1.0
    need = dn / max(1e-6, 2.0 * s) if s > 1e-6 else 1e9
    return need > _ae_turn_r(v, kind_turn) * 1.05


class _AeView:
    """A body as one bot sees it, turned so that its own goal is at -x (orange sees the pitch half turned)."""
    __slots__ = ("x", "y", "vx", "vy", "a", "fx", "fy", "w", "boost", "r", "hl", "drifting", "sp", "turn")

    def __init__(self) -> None:
        self.x = self.y = self.vx = self.vy = self.a = self.w = 0.0
        self.fx, self.fy, self.boost, self.r, self.hl, self.drifting, self.sp = 1.0, 0.0, 0.0, 30.0, 50.0, False, 0.0
        self.turn = 1.0


def _ae_norm(x: float, y: float) -> tuple:
    n = _ae_sqrt(x * x + y * y)
    if n < 1e-9:
        return 1.0, 0.0, 0.0
    return x / n, y / n, n


class AerialBot:
    """One bot. think() is called once a step with the match; it returns an AerialInput."""

    def __init__(self, team: int, key: str, seed: int = 1, prof: dict = None) -> None:
        self.team = team
        self.key = key
        self.p = prof or AERIAL_BOTS.get(key) or aerial_bot_profile("pip")
        self.rng = AerialRng(seed * 7919 + team * 104729 + 17)
        self.f = 1.0 if team == 0 else -1.0
        self.seen: list = []                     # what it saw, newest last (for the reaction delay)
        self.plan = None
        self.plan_t = 0
        self.tick = 0
        self.mode = "kick"
        self.path = None
        self.path_tick = -999
        self.aim_err = 0.0
        self.aim_t = 0
        self.mood = 0.0                          # leaning: attack (> 0) or hang back (< 0); changes now and then
        self.fake_t = 0
        self.flick_dir = 1
        self.carry_t = 0.0
        self.stat = {"plays": {}}
        self.last_boost = False
        self.stuck = 0
        self.unstick = 0
        self.noise_t = 0
        self.noise_v = {}

    # -- what it sees
    def _turn(self, x, y, vx, vy):
        f = self.f
        return x * f, y * f, vx * f, vy * f

    def _observe(self, m) -> None:
        sim = m.sim
        b = sim.ball
        o = sim.cars[1 - self.team]
        self.seen.append((b.x, b.y, b.vx, b.vy, o.x, o.y, o.vx, o.vy, o.a, o.boost, o.drifting, sim.tick))
        keep = self.p["react"] + 2
        if len(self.seen) > keep:
            del self.seen[0:len(self.seen) - keep]

    def _views(self, m):
        """Me (exact), the ball and the other car as I saw them a moment ago, moved on by what I guess happened
        since (how well depends on the bot)."""
        p = self.p
        sim = m.sim
        me_c = sim.cars[self.team]
        o_c = sim.cars[1 - self.team]
        s = self.seen[0] if len(self.seen) > p["react"] else self.seen[0]
        lag = (len(self.seen) - 1) * AERIAL_DT * p["comp"]
        me = _AeView()
        me.x, me.y, me.vx, me.vy = self._turn(me_c.x, me_c.y, me_c.vx, me_c.vy)
        me.a = aerial_wrap(me_c.a + (0.0 if self.team == 0 else _AE_PI))
        me.fx, me.fy = aerial_cos(me.a), aerial_sin(me.a)
        me.w, me.boost, me.r, me.hl, me.drifting = me_c.w, me_c.boost, me_c.r, me_c.hl, me_c.drifting
        me.turn = me_c.spec["turn"]
        me.sp = me_c.speed()
        bx, by, bvx, bvy = self._turn(s[0], s[1], s[2], s[3])
        bx += bvx * lag
        by += bvy * lag
        ox, oy, ovx, ovy = self._turn(s[4], s[5], s[6], s[7])
        op = _AeView()
        op.x, op.y, op.vx, op.vy = ox + ovx * lag, oy + ovy * lag, ovx, ovy
        op.a = aerial_wrap(s[8] + (0.0 if self.team == 0 else _AE_PI))
        op.fx, op.fy = aerial_cos(op.a), aerial_sin(op.a)
        op.boost, op.r, op.hl, op.drifting = s[9], o_c.r, o_c.hl, s[10]
        op.sp = _ae_sqrt(ovx * ovx + ovy * ovy)
        return me, (bx, by, bvx, bvy), op

    # -- how long things take
    def _reach(self, c, x: float, y: float, boost: float) -> float:
        """Rough seconds for car c to get its nose to (x, y): turn, then speed up (boost if it has some)."""
        dx, dy = x - c.x, y - c.y
        d = _ae_sqrt(dx * dx + dy * dy)
        if d < 1.0:
            return 0.0
        ang = abs(aerial_wrap(aerial_atan2(dy, dx) - c.a))
        d = max(0.0, d - c.hl - c.r * 0.5)
        v0 = c.vx * dx / max(d, 1.0) + c.vy * dy / max(d, 1.0) if d > 1.0 else 0.0
        v0 = max(0.0, v0) * max(0.0, 1.0 - ang / 1.6)
        turn = ang / 3.6 if ang > 0.25 else ang / 8.0
        vmax = 2250.0 if boost > 8.0 + d * 0.004 else 1350.0
        a = 2400.0 if boost > 5.0 else 1500.0
        t1 = max(0.0, (vmax - v0) / a)
        d1 = (v0 + vmax) * 0.5 * t1
        if d < d1:
            tt = (-v0 + _ae_sqrt(v0 * v0 + 2 * a * d)) / a
        else:
            tt = t1 + (d - d1) / vmax
        return turn + tt

    # -- the brain
    def think(self, m) -> AerialInput:
        self.tick += 1
        self._observe(m)
        if m.phase in (m.REPLAY, m.GOAL, m.OVER):
            return AerialInput(skip=m.phase == m.REPLAY)
        if m.phase == m.COUNT:
            self.mode = "kick"
            self.plan = None
            self.kick_choice = None
            return AerialInput(1 if m.phase_t > m.t["count_s"] - 0.05 else 0)
        if self.plan is None or self.tick - self.plan_t >= self.p["replan"]:
            self._plan(m)
            self.plan_t = self.tick
        self.want_aim = None
        inp = self._drive(m)
        if self.want_aim is not None:
            ux, uy = self.want_aim
            a = aerial_atan2(uy * self.f, ux * self.f)
            inp.aim = int(a / _AE_TAU * 64.0 + 64.5) % 64
            inp.shot = self.mode in ("shoot", "clear", "save", "kick", "shadow")
        # never stuck: pushing into a wall or a corner without moving, back out and turn
        c = m.sim.cars[self.team]
        if self.unstick > 0:
            self.unstick -= 1
            return AerialInput(-inp.thr if inp.thr else -1, -inp.steer if inp.steer else 8, False, False)
        if inp.thr != 0 and c.speed() < 140:
            self.stuck += 1
            if self.stuck > 45:
                self.stuck = 0
                self.unstick = 40
        else:
            self.stuck = 0
        return inp

    def _ball_path(self, m, ball) -> AerialBallPath:
        bx, by, bvx, bvy = ball
        p = self.p
        rd = p["read"]
        if rd > 0:
            k = 1.0 + self.rng.gauss(rd * 0.5)
            bvx *= k
            bvy *= k
        old = self.path
        if old is not None and old.pts:
            off = (self.tick - self.path_tick) // AerialBallPath.STEP
            if 0 <= off < len(old.pts) - 30:
                q = old.pts[off]
                if abs(q[0] - bx) < 25 and abs(q[1] - by) < 25 and abs(q[2] - bvx) < 60 and abs(q[3] - bvy) < 60:
                    return old, off
        path = AerialBallPath(m.sim, p["horizon"], bx, by, bvx, bvy)
        # (the pitch is the same turned half round, so the path can be worked out on my side directly)
        self.path, self.path_tick = path, self.tick
        return path, 0

    def _shot_dirs(self, bx: float, by: float, op) -> list:
        """Where to send the ball from (bx, by): the far post, the near post, the middle, and (if it knows them) off
        the side wall into the goal, or a pinch along the wall. Each with how good it looks."""
        t = AERIAL_TUNE
        hl, hw, gw, R = t["hl"], t["hw"], t["goal_hw"], t["ball_r"]
        p = self.p
        out = []
        inner = gw - R - 25.0
        # the other car's place in front of its goal: aim away from it
        guard = op.y if op.x > bx else 0.0
        for gy, label in ((inner, "post"), (-inner, "post"), (0.0, "mid"), (inner * 0.5, "mid"), (-inner * 0.5, "mid")):
            dx, dy = hl + R - bx, gy - by
            ux, uy, d = _ae_norm(dx, dy)
            open_ = min(1.0, abs(gy - guard) / (gw * 1.2)) if op.x > bx else 1.0
            block = 0.0
            # is the other car on the line?
            ox, oy = op.x - bx, op.y - by
            along = ox * ux + oy * uy
            if 0 < along < d:
                side = abs(-ox * uy + oy * ux)
                if side < op.r + R + 40:
                    block = 1.0 - side / (op.r + R + 40)
            sc = 1.0 + 0.6 * open_ - 1.2 * block - d / 9000.0
            out.append((sc, ux, uy, label))
        if "bank" in p["plays"]:
            for sy in (1.0, -1.0):
                gy = sy * (2 * hw - R * 2) - 0.0
                dx, dy = hl + R - bx, gy - by
                ux, uy, d = _ae_norm(dx, dy)
                if abs(uy) > 0.25 and bx > -400:
                    out.append((0.95 + 0.4 * (1.0 if op.x > bx and op.y * sy < 0 else 0.0) - d / 9000.0, ux, uy,
                                "bank"))
        if "pinch" in p["plays"] and abs(by) > hw - 380 and bx > -hl * 0.3:
            sy = 1.0 if by > 0 else -1.0
            ux, uy, _d = _ae_norm(1.0, sy * (0.9 if "corner" in p["plays"] else 1.4))
            out.append((1.05 + (0.25 if "corner" in p["plays"] and bx > hl * 0.35 else 0.0), ux, uy, "pinch"))
        return out

    def _reach_aligned(self, me, pt, home: bool) -> float:
        """Seconds to get my nose behind the ball point pt, lined up to send it up the pitch (or away from my goal)."""
        R = AERIAL_TUNE["ball_r"]
        bx, by, bvx, bvy = pt
        if home:
            ux, uy, _ = _ae_norm(1.0, 0.8 if by >= 0 else -0.8)
        else:
            ux, uy, _ = _ae_norm(AERIAL_TUNE["hl"] - bx, -by)
        hx, hy, _n = _ae_norm(1700.0 * ux - bvx, 1700.0 * uy - bvy)
        px, py = bx - hx * (R + me.r), by - hy * (R + me.r)
        nx_, ny_ = me.x + me.fx * me.hl, me.y + me.fy * me.hl
        ax, ay, dn = _ae_norm(px - nx_, py - ny_)
        cosang = ax * hx + ay * hy
        return self._reach(me, px, py, me.boost) + (1.0 - cosang) * 0.35

    def _best_dir(self, me, bx, by, bv, cands, mix: float):
        """The best way to send the ball: how good each direction is, less what it costs to line it up from where
        I am (and a touch of randomness so the top bots cannot be read)."""
        t = AERIAL_TUNE
        R = t["ball_r"]
        best, bs = None, -1e9
        nx_, ny_ = me.x + me.fx * me.hl, me.y + me.fy * me.hl
        lim_y = t["hw"] - me.r - 10
        lim_x = t["hl"] - me.r - 10
        for c in cands:
            q, ux, uy = c[0], c[1], c[2]
            hx, hy, _n = _ae_norm(1700.0 * ux - bv[0], 1700.0 * uy - bv[1])
            px, py = bx - hx * (R + me.r), by - hy * (R + me.r)
            if abs(py) > lim_y or (abs(px) > lim_x and abs(py) > t["goal_hw"] - me.r):
                q -= 0.6                                   # I cannot get behind it there
            ax, ay, dn = _ae_norm(px - nx_, py - ny_)
            cosang = ax * hx + ay * hy
            cost = (1.0 - cosang) * (0.55 if dn < 900 else 0.25)
            sc = q - cost + (self.rng.random() * mix if mix else 0.0)
            if sc > bs:
                best, bs = c, sc
        return best

    def _plan(self, m) -> None:
        p = self.p
        rng = self.rng
        me, ball, op = self._views(m)
        self.me, self.ball, self.op = me, ball, op
        path, off = self._ball_path(m, ball)
        t = AERIAL_TUNE
        hl, hw, R = t["hl"], t["hw"], t["ball_r"]
        bx, by, bvx, bvy = ball
        pts = path.pts[off:]
        if not pts:
            pts = [ball]
        h = AERIAL_DT * AerialBallPath.STEP
        # when can each car get to the ball?
        my_t, my_k = None, len(pts) - 1
        op_t = None
        slack = p["slack"]
        for k in range(0, len(pts), 2):
            x, y = pts[k][0], pts[k][1]
            tk = (k + 1) * h
            if my_t is None and self._reach_aligned(me, pts[k], x < -hl * 0.3) <= tk + slack:
                my_t, my_k = tk, k
            if op_t is None and self._reach(op, x, y, op.boost) <= tk:
                op_t = tk
            if my_t is not None and op_t is not None:
                break
        if my_t is None:
            my_t = len(pts) * h
        if op_t is None:
            op_t = len(pts) * h + 1.0
        ix, iy, ivx, ivy = pts[min(my_k, len(pts) - 1)]
        danger = path.goal_t is not None and path.goal_side == -1
        # options and their scores
        opts = []
        lead = op_t - my_t                       # > 0: I get there first
        my_half = ix < 0
        d_me = _ae_norm(bx - me.x, by - me.y)[2]
        ahead = (bx - me.x) * me.fx + (by - me.y) * me.fy
        rel_v = _ae_sqrt((bvx - me.vx) ** 2 + (bvy - me.vy) ** 2)
        # a ball on my nose: carry it, flick it, or shoot it
        close = d_me < me.hl + me.r + R + 70 and ahead > 0 and rel_v < 520 and abs(by) < hw - 260 and \
            abs(bx) < hl - 350
        if danger and path.goal_t < 2.6 + 1.6 * p["guard"]:
            opts.append((4.0 - path.goal_t + (1.0 if lead > -0.25 else 0.0), "save"))
        if close and "dribble" in p["plays"] and me.x < hl - 300:
            opts.append((1.4 + 0.6 * p["control"] - (0.5 if danger else 0.0), "carry"))
        if lead > -0.15 + 0.3 * p["guard"] * (1.0 if bx < hl * 0.3 else 0.0) or d_me < 400:
            shots = self._shot_dirs(ix, iy, op)
            best = max(shots, key=lambda s: s[0])
            att = 1.2 + best[0] * 0.6 - (0.5 if my_half and lead < 0.3 else 0.0) + 0.3 * self.mood
            opts.append((att, "shoot"))
        if my_half and (lead < 0.4 or danger) and "clear" in p["plays"]:
            opts.append((1.3 + (0.8 if ix < -hl * 0.45 else 0.0) - 0.3 * self.mood, "clear"))
        elif my_half and ix < -hl * 0.4:
            opts.append((1.1, "clear"))
        if lead < 0.0:
            sh = 1.4 + min(1.0, -lead) * p["patience"] - 0.3 * self.mood
            opts.append((sh, "shadow"))
            if "fake" in p["plays"] and -0.6 < lead < 0.0 and d_me < 900:
                opts.append((1.1 + 0.4 * p["read_opp"] * rng.random(), "fake"))
        # boost: on my way, or a full orb when there is time
        if "pads" in p["plays"] and me.boost < 45 and (lead > 0.9 or lead < -0.7):
            opts.append((0.9 + (45 - me.boost) / 45.0 * p["boost_iq"], "pads"))
        if "deny" in p["plays"] and me.boost > 60 and op.boost < 30 and lead < -0.8:
            opts.append((1.25, "deny"))
        if not opts:
            opts.append((1.0, "shoot"))
        # weigh them with a little randomness (more for the lower bots), and now and then a plain bad choice
        noise = p["noise"] * (1.6 if "mix" in p["plays"] else 1.0)
        # the randomness is drawn now and then, not every step, and the current plan gets a bonus: a bot commits
        if self.tick >= self.noise_t:
            self.noise_t = self.tick + int(AERIAL_HZ * (0.3 + 0.5 * rng.random()))
            self.noise_v = {}
        for _s, k in opts:
            if k not in self.noise_v:
                self.noise_v[k] = rng.gauss(noise * 0.5)
        scored = [(s + self.noise_v[k] + (0.35 if k == self.mode else 0.0), k) for s, k in opts]
        scored.sort(key=lambda z: -z[0])
        choice = scored[0][1]
        if rng.chance(p["blunder"]) and len(scored) > 1:
            choice = scored[1][1]
        if "mix" not in p["plays"] and self.mode == "shadow" and choice == "shadow":
            pass
        if self.mode == "kick" and m.sim.kick_wait:
            choice = "kick"
        if rng.chance(0.004):
            self.mood = rng.uniform(-1.0, 1.0)
        if choice != self.mode:
            self.stat["plays"][choice] = self.stat["plays"].get(choice, 0) + 1
            if choice == "fake":
                self.fake_t = int((0.35 + 0.5 * rng.random()) * AERIAL_HZ)
            if choice == "carry":
                self.carry_t = 0.0
                self.flick_dir = 1 if rng.random() < 0.5 else -1
        self.mode = choice
        self.plan = {"k": my_k, "pts": pts, "t": my_t, "op_t": op_t, "ix": ix, "iy": iy, "danger": danger,
                     "lead": lead, "path": path}
        if self.aim_t <= 0:
            self.aim_err = rng.gauss(p["aim"])
            self.aim_t = int(AERIAL_HZ * 0.5)

    # -- the hands
    def _steer_to(self, me, tx: float, ty: float, rev_ok: bool = False) -> tuple:
        dx, dy = tx - me.x, ty - me.y
        ang = aerial_wrap(aerial_atan2(dy, dx) - me.a)
        res = self.p["steer_res"]
        s = ang * 6.0 - me.w * 0.55                   # a little damping on the yaw
        s = max(-1.0, min(1.0, s))
        st = int(round(s * res)) * (8 // res)
        return st, ang

    def _go(self, me, tx: float, ty: float, want_v: float, ang_tol: float = 0.35, allow_drift: bool = True):
        """Drive at (tx, ty) at about want_v: steering, the powerslide for sharp turns, feathered boost."""
        p = self.p
        st, ang = self._steer_to(me, tx, ty)
        vl = me.vx * me.fx + me.vy * me.fy
        aa = abs(ang)
        thr = 1
        drift = False
        boost = False
        dist = _ae_norm(tx - me.x, ty - me.y)[2]
        if aa > 1.9 and dist < 700 and vl < 500:
            thr = -1                                     # a tight turn round from slow: back off and turn
            st = -st
        elif aa > 1.05 and vl > 650 and allow_drift and self.rng.random() < p["drift_sense"] + 0.2:
            drift = True                                 # a powerslide turn keeps the speed
        if vl > want_v + 220:
            thr = 0 if vl < want_v + 600 else -1
        if not drift and thr == 1 and aa < 1.9 and not _ae_reachable(dist, ang, vl, me.turn):
            thr = -1 if vl > 900 else (1 if vl < 350 else 0)
        if want_v > 1350 or (want_v > vl + 350 and aa < ang_tol):
            if aa < ang_tol and me.boost > 0:
                # feathered: just enough to hold the speed it wants
                need = min(1.0, max(0.0, (want_v - vl) / 900.0))
                boost = self.rng.random() < (0.35 + 0.65 * need) * (0.6 + 0.4 * p["feather"]) or need > 0.6
        if "chain" in p["plays"] and drift and aa < 1.4 and me.boost > 10:
            boost = True                                 # a drift-boost chain: slide round, boost out of it
        return AerialInput(thr, st, boost, drift)

    def _hit(self, me, bx, by, ux, uy, t_hit, urgent=False, bv=(0.0, 0.0), power=1700.0) -> AerialInput:
        """Get to the ball at (bx, by) (moving at bv then) in about t_hit seconds and send it along (ux, uy). The
        touch has to cancel the ball's own speed, so the car hits along (power * u - bv), not along u."""
        p = self.p
        t = AERIAL_TUNE
        R = t["ball_r"]
        e = self.aim_err
        ca, sa = aerial_cos(e), aerial_sin(e)
        ux, uy = ux * ca - uy * sa, ux * sa + uy * ca
        self.want_aim = (ux, uy)
        hx, hy, _n = _ae_norm(power * ux - bv[0], power * uy - bv[1])
        reach = R + me.r + me.hl * 0.85
        cx, cy = bx - hx * reach, by - hy * reach
        # a contact point in the wall cannot be reached: slide it along the wall
        lim_y = t["hw"] - me.r - 10
        if abs(cy) > lim_y:
            cy = lim_y if cy > 0 else -lim_y
        lim_x = t["hl"] - me.r - 10
        if abs(cx) > lim_x and abs(cy) > t["goal_hw"] - me.r:
            cx = lim_x if cx > 0 else -lim_x
        hx, hy, _n = _ae_norm(bx - cx, by - cy)
        # where I am against the hit line through the ball
        rx, ry = me.x - bx, me.y - by
        along = rx * hx + ry * hy                      # < 0: behind the ball
        lat = -rx * hy + ry * hx
        psi = aerial_wrap(me.a - aerial_atan2(hy, hx))
        vl = me.vx * me.fx + me.vy * me.fy
        d = _ae_norm(cx - me.x, cy - me.y)[2]
        turn_r = max(220.0, abs(vl) / 3.4)
        want = d / max(0.1, t_hit) * 1.05
        if urgent:
            want = max(want, 2200.0)
        # the touch sends the ball straight away from the nose: so put the nose on the point just behind the ball
        # on the hit line. Coming from anywhere behind the ball, the first contact is right there.
        px, py = bx - hx * (R + me.r - 4.0), by - hy * (R + me.r - 4.0)
        nx_, ny_ = me.x + me.fx * me.hl, me.y + me.fy * me.hl
        ax, ay, dn = _ae_norm(px - nx_, py - ny_)
        cosang = ax * hx + ay * hy
        if cosang > 0.55 - 0.25 * p["control"] and along < 0:
            want = max(want, power * (0.55 + 0.45 * min(1.0, 700.0 / max(1.0, dn))))
            want = max(450.0, min(2300.0, want))
            ang = aerial_wrap(aerial_atan2(py - me.y - me.fy * 0.0, px - me.x) - me.a)
            ang = aerial_wrap(aerial_atan2(ay, ax) - me.a) * 0.6 + ang * 0.4
            st = max(-1.0, min(1.0, ang * 5.0 - me.w * 0.4))
            res = p["steer_res"]
            st = int(round(st * res)) * (8 // res)
            thr = 1 if vl < want + 150 else 0
            ang_n = aerial_wrap(aerial_atan2(ay, ax) - me.a)
            if not _ae_reachable(dn, ang_n, vl, me.turn):
                thr = -1 if vl > 700 else (1 if vl < 350 else 0)    # too fast to make the turn: brake into it
            boost = False
            if me.boost > 0 and abs(ang) < 0.3 and want > vl + 250:
                need = min(1.0, (want - vl) / 900.0)
                boost = self.rng.random() < (0.35 + 0.65 * need) * (0.6 + 0.4 * p["feather"]) or need > 0.6
            return AerialInput(thr, st, boost, False)
        # off the line: swing round to a point behind the ball first
        back = reach + turn_r * (1.0 + 0.6 * min(1.0, abs(psi)))
        tx, ty = bx - hx * back, by - hy * back
        lim = t["hw"] - me.r - 30
        ty = max(-lim, min(lim, ty))
        tx = max(-t["hl"] + me.r + 30, min(t["hl"] - me.r - 30, tx))
        # never drive through the ball on the way round: pass it on my side
        wx, wy, dw = _ae_norm(tx - me.x, ty - me.y)
        u = (bx - me.x) * wx + (by - me.y) * wy
        clear = R + me.r + me.hl * 0.5 + 60
        sd = abs(-(bx - me.x) * wy + (by - me.y) * wx)
        if along > -reach * 0.6 or (0 < u < dw and sd < clear):
            if True:
                sg = 1.0 if lat >= 0 else -1.0
                tx, ty = bx - hy * sg * (clear + 40) - hx * R * 0.5, by + hx * sg * (clear + 40) - hy * R * 0.5
                ty = max(-lim, min(lim, ty))
                tx = max(-t["hl"] + me.r + 30, min(t["hl"] - me.r - 30, tx))
                dw = _ae_norm(tx - me.x, ty - me.y)[2]
        want = max(want, 1500.0 if dw > 500 else 900.0)
        want = max(500.0, min(2300.0, want))
        dbx, dby, dball = _ae_norm(bx - me.x, by - me.y)
        near = dball < 520
        if dball < 700 and dbx * hx + dby * hy < 0.35:
            # heading into the ball from the wrong side: turn away from it instead of knocking it the wrong way
            a_b = aerial_wrap(aerial_atan2(dby, dbx) - me.a)
            cone = (R + me.r + 50) / max(dball, R + me.r + 51)
            cone = 1.5707 if cone >= 1.0 else aerial_atan2(cone, _ae_sqrt(1.0 - cone * cone))
            if abs(a_b) < cone + 0.15 and vl > 150:
                st = -8 if a_b > 0 else 8
                return AerialInput(1 if vl < 700 else (0 if vl < 1200 else -1), st, False, False)
        return self._go(me, tx, ty, want, allow_drift=not near)

    def _drive(self, m) -> AerialInput:
        p, rng = self.p, self.rng
        me, ball, op = self._views(m)
        plan = self.plan
        t = AERIAL_TUNE
        hl, gw, R = t["hl"], t["goal_hw"], t["ball_r"]
        bx, by, bvx, bvy = ball
        self.aim_t -= 1
        k = max(0, plan["k"] - (self.tick - self.plan_t) // AerialBallPath.STEP)
        pts = plan["pts"]
        pt = pts[min(k, len(pts) - 1)] if pts else ball
        t_hit = max(0.05, (k + 1) * AERIAL_DT * AerialBallPath.STEP)
        mode = self.mode
        if mode == "kick":
            # straight at the ball, boosting; the better bots aim the touch a little to the side away from the
            # other car so the ball does not come straight back
            side = 0.0 if op.y == 0 else (-0.25 if op.y > 0 else 0.25)
            ux, uy, _ = _ae_norm(1.0, side * p["control"])
            return self._hit(me, bx, by, ux, uy, 0.6, urgent=True)
        if mode == "save" and p["guard"] > 0 and self.rng.random() < p["guard"]:
            sv = self._save_point(me, plan)
            if sv is not None:
                ix, iy, ivx, ivy, tt, line = sv
                cy = self._cross_y(plan)
                gt = plan["path"].goal_t if plan.get("path") is not None else None
                if cy is not None and gt is not None:
                    gt -= (self.tick - self.plan_t) * AERIAL_DT
                    kx = -hl + me.r + 170.0
                    # time to get onto the line there (and turn side on), against the time the ball needs
                    t_k = self._reach(me, kx, max(-gw + 60.0, min(gw - 60.0, cy)), me.boost) + 0.25
                    if line or ix < -hl + 520 or t_k < gt - 0.1 * (1.0 - p["guard"]):
                        return self._keeper(me, cy)
                d_b = _ae_norm(bx - me.x, by - me.y)[2]
                vb = _ae_sqrt(bvx * bvx + bvy * bvy)
                # the ball is about to reach me: meet it with the nose, any touch turns it away
                if d_b < 260 + vb * 0.18 and (bx - me.x) * me.fx + (by - me.y) * me.fy > 0:
                    st, _a = self._steer_to(me, bx + bvx * 0.05, by + bvy * 0.05)
                    return AerialInput(1, st, me.boost > 0 and abs(_a) < 0.4, False)
                if line:                                  # nothing reachable in time: get on the line and block it
                    return self._go(me, ix, iy, 2300.0, 0.6)
                # get my car onto its way a moment early, then turn into it
                dd = _ae_norm(ix - me.x, iy - me.y)[2]
                if dd < 160:
                    st, _a = self._steer_to(me, bx, by)
                    vl = me.vx * me.fx + me.vy * me.fy
                    return AerialInput(1 if vl < 600 else 0, st, False, False)
                return self._go(me, ix, iy, max(900.0, min(2300.0, dd / max(0.08, tt) * 1.15)), 0.5)
        if mode == "save":
            # the first point of the path I can reach before it goes in, and away to the side
            ix, iy = pt[0], pt[1]
            sy = 1.0 if iy > 0 else -1.0
            ux, uy, _ = _ae_norm(0.55, sy * 1.0)
            if me.x > ix:                                 # I'm beyond the ball: get back to goal first
                gx, gy = -hl + 160, max(-gw + 40, min(gw - 40, iy * 0.6))
                return self._go(me, gx, gy, 2300.0, 0.5)
            return self._hit(me, ix, iy, ux, uy, t_hit, urgent=True, bv=(pt[2], pt[3]), power=2000.0)
        if mode == "clear":
            ix, iy = pt[0], pt[1]
            cands = []
            for dy_, q in ((0.85, 1.0), (-0.85, 1.0), (0.3, 0.9), (-0.3, 0.9), (1.8, 0.75), (-1.8, 0.75)):
                ux, uy, _ = _ae_norm(1.0, dy_)
                if iy * dy_ < 0 and abs(iy) > 300:
                    q -= 0.15                              # across the front of my own goal: less good
                cands.append((q, ux, uy, "clear"))
            s = self._best_dir(me, ix, iy, (pt[2], pt[3]), cands, 0.0)
            return self._hit(me, ix, iy, s[1], s[2], t_hit, urgent=plan["lead"] < 0.3, bv=(pt[2], pt[3]),
                             power=2000.0)
        if mode == "carry":
            return self._carry(m, me, ball, op)
        if mode == "shoot":
            ix, iy = pt[0], pt[1]
            if not hasattr(self, "shot_pick") or self.tick - getattr(self, "shot_t", -999) > 30:
                shots = self._shot_dirs(ix, iy, op)
                # moving it on is better than a shot that cannot be lined up
                for dy_ in (0.0, 0.7, -0.7, 1.6, -1.6):
                    ux, uy, _ = _ae_norm(1.0, dy_)
                    shots.append((0.75 - abs(dy_) * 0.08 + (0.0 if ix < 0 else -0.2), ux, uy, "advance"))
                mix = 0.25 if "mix" in p["plays"] else 0.1
                self.shot_pick = self._best_dir(me, ix, iy, (pt[2], pt[3]), shots, mix)
                self.shot_t = self.tick
            s = self.shot_pick
            urgent = plan["lead"] < 0.35 and ("lunge" in p["plays"] or plan["lead"] < 0.1)
            return self._hit(me, ix, iy, s[1], s[2], t_hit, urgent, bv=(pt[2], pt[3]),
                             power=1500.0 + 900.0 * p["control"])
        if mode == "shadow":
            # between the ball and my goal, facing the ball; go in when the ball comes loose or close
            gx, gy = -hl - 100, 0.0
            g = p["guard"]
            # the better defenders shadow where the ball is going, and stay goal side: deep enough that a shot has
            # to beat them, close enough to step up when the ball comes loose
            ax_, ay_ = bx + bvx * 0.3 * g, by + bvy * 0.3 * g
            ux, uy, dgb = _ae_norm(ax_ - gx, ay_ - gy)
            sd_old = min(p["shadow_d"], dgb * 0.55)
            sd_new = dgb - max(380.0, min(1100.0 - 450.0 * g, dgb * 0.4))
            sd = sd_old * (1.0 - g) + max(sd_old, sd_new) * g
            sx, sy = ax_ - ux * sd, ay_ - uy * sd
            sx = max(-hl + 180, sx)
            dgoal = _ae_norm(bx + hl, by)[2]
            o_behind = op.x > bx - 120 and _ae_norm(op.x - bx, op.y - by)[2] < 1100
            if g > 0 and o_behind and dgoal < 1300 + 4000 * g and me.x < bx - 200:
                # it can shoot from there: keep the line between the ball and my goal (step up only when it is loose)
                lead_ = plan["lead"]
                if not (lead_ > 0.25 and _ae_norm(bx - me.x, by - me.y)[2] < 900):
                    gy_ = by * (420.0 / max(420.0, dgoal))
                    return self._keeper(me, gy_, 170.0 + 260.0 * min(1.0, dgoal / 3500.0))
            loose = _ae_sqrt((bvx - op.vx) ** 2 + (bvy - op.vy) ** 2) > 420 or \
                _ae_norm(bx - op.x, by - op.y)[2] > op.hl + op.r + R + 160
            d_b = _ae_norm(bx - me.x, by - me.y)[2]
            if (loose and rng.random() < p["read_opp"]) or d_b < 300 + 200 * (1 - p["patience"]):
                ix, iy = pt[0], pt[1]
                sy2 = 1.0 if iy >= 0 else -1.0
                ux2, uy2, _ = _ae_norm(1.0, sy2 * 0.7)
                return self._hit(me, ix, iy, ux2, uy2, t_hit, urgent=True, bv=(pt[2], pt[3]), power=1800.0)
            d_s = _ae_norm(sx - me.x, sy - me.y)[2]
            if d_s < 220:
                st, _ang = self._steer_to(me, bx, by)
                vl = me.vx * me.fx + me.vy * me.fy
                return AerialInput(0 if vl > 250 else 1, st, False, False)
            return self._go(me, sx, sy, 900 + 1300 * p["urgency"] * min(1.0, d_s / 1500), 0.4)
        if mode == "fake":
            # come at the ball as if to challenge, stop short, then punish the touch
            self.fake_t -= 1
            if self.fake_t <= 0:
                self.mode = "shadow"
            d_b = _ae_norm(bx - me.x, by - me.y)[2]
            if d_b < 420:
                st, _ang = self._steer_to(me, bx, by)
                return AerialInput(-1, st, False, False)
            return self._go(me, bx, by, 1500.0)
        if mode in ("pads", "deny"):
            pad = self._pick_pad(m, me, op, mode == "deny")
            if pad is None:
                self.mode = "shadow"
                return AerialInput(1, 0)
            return self._go(me, pad[0], pad[1], 2000.0, 0.45)
        return self._go(me, bx, by, 1400.0)

    def _keeper(self, me, ty: float, depth: float = 170.0) -> AerialInput:
        """Goal-line keeping: stand in the mouth of my goal side on to the pitch (the long side of the car blocks the
        most), and slide along the line by driving forward and back to stay in front of where the ball will cross."""
        t = AERIAL_TUNE
        hl, gw = t["hl"], t["goal_hw"]
        x0 = -hl + me.r + depth
        ty = max(-gw + 60.0, min(gw - 60.0, ty))
        # a save goes out to the side and up the pitch, away from the middle of my goal
        sgn = 1.0 if ty >= 0 else -1.0
        ux_, uy_, _ = _ae_norm(0.6, sgn)
        self.want_aim = (ux_, uy_)
        dx, dy = x0 - me.x, ty - me.y
        vl = me.vx * me.fx + me.vy * me.fy
        if abs(dx) > 170 or abs(dy) > 520:
            # get there; arrive side on (aim a little past the spot along the line)
            return self._go(me, x0, ty, max(900.0, min(2300.0, _ae_norm(dx, dy)[2] * 2.2)), 0.5)
        want = _AE_PI * 0.5 if aerial_sin(me.a) >= 0 else -_AE_PI * 0.5
        err = aerial_wrap(want - me.a)
        # keep on the line: steer a little toward it while sliding
        corr = max(-0.5, min(0.5, dx / 300.0)) * (1.0 if want > 0 else -1.0)
        st = max(-1.0, min(1.0, (err - corr) * 5.0 - me.w * 0.4))
        along = dy * me.fy                                  # > 0: the spot is ahead of my nose
        if abs(err) > 0.9:
            thr = 1 if vl < 250 else 0
        elif abs(dy) < 25 and abs(vl) < 120:
            thr = 0
        else:
            need = max(-1.0, min(1.0, dy * (1.0 if me.fy >= 0 else -1.0) / 140.0)) * 900.0
            thr = 1 if vl < need - 60 else (-1 if vl > need + 60 else 0)
        boost = abs(along) > 260 and me.boost > 0 and along * vl >= 0 and abs(err) < 0.3
        return AerialInput(thr, int(round(st * 8)), boost and thr == 1, False)

    def _cross_y(self, plan):
        """Where the ball's way crosses my goal line, if it does."""
        hl = AERIAL_TUNE["hl"]
        for x, y, _vx, _vy in plan["pts"]:
            if x < -hl + 100:
                return y
        return None

    def _save_point(self, me, plan):
        """A save: the first point on the ball's way into my goal that my nose gets to in time (any touch will do);
        if there is none, the point where it crosses in front of the goal, to block it there."""
        t = AERIAL_TUNE
        hl = t["hl"]
        pts = plan["pts"]
        if not pts:
            return None
        h = AERIAL_DT * AerialBallPath.STEP
        k_off = (self.tick - self.plan_t) // AerialBallPath.STEP
        for k in range(k_off, len(pts), 2):
            x, y, vx, vy = pts[k]
            tk = (k - k_off + 1) * h
            if x < -hl - 20:
                break
            if self._reach(me, x, y, me.boost) <= tk:
                return x, y, vx, vy, tk, False
        for k in range(k_off, len(pts)):
            x, y, vx, vy = pts[k]
            if x < -hl + me.r + 120:
                return -hl + me.r + 60, y, vx, vy, 0.1, True
        return None

    def _pick_pad(self, m, me, op, deny: bool):
        sim = m.sim
        best, bs = None, 1e18
        f = self.f
        bx, by = self.ball[0], self.ball[1]
        for k, (x, y, big) in enumerate(sim.arena.pads):
            if sim.pad_t[k] > 0.5:
                continue
            x, y = x * f, y * f
            if deny and not big:
                continue
            dme = _ae_norm(x - me.x, y - me.y)[2]
            if deny:
                if x < 0:
                    continue
                sc = dme
            else:
                back = _ae_norm(x - bx, y - by)[2]
                home = 0.0 if x < bx else 600.0          # pads on my side of the ball are safer
                sc = dme + back * 0.4 + home - (900.0 if big and me.boost < 25 else 0.0)
            if sc < bs:
                best, bs = (x, y), sc
        return best

    def _carry(self, m, me, ball, op) -> AerialInput:
        """A dribble: keep the ball on the nose, steer it toward goal, and when the other car comes, snap a drift
        flick past it (or shoot when the goal is open)."""
        p, rng = self.p, self.rng
        t = AERIAL_TUNE
        hl, hw, R = t["hl"], t["hw"], t["ball_r"]
        bx, by, bvx, bvy = ball
        self.carry_t += AERIAL_DT
        dx, dy = bx - me.x, by - me.y
        ux, uy, d = _ae_norm(dx, dy)
        ahead = dx * me.fx + dy * me.fy
        if d > me.hl + me.r + R + 140 or ahead < 0 or abs(by) > hw - 230:
            self.mode = "shoot"
            return self._go(me, bx, by, 1500.0)
        gx, gy = hl, 0.0
        gux, guy, gd = _ae_norm(gx - bx, gy - by)
        od = _ae_norm(op.x - bx, op.y - by)[2]
        op_front = (op.x - me.x) * me.fx + (op.y - me.y) * me.fy > 0
        # flick when the other car closes in, or at the goal when close enough
        rush = od < 520 + 250 * p["read_opp"] and op_front
        if (rush or (gd < 1300 and self.carry_t > p["flick_t"])) and self.carry_t > p["flick_t"] * 0.6:
            if rush:
                # flick to the side away from the rushing car
                os_ = -(op.x - me.x) * me.fy + (op.y - me.y) * me.fx
                self.flick_dir = -1 if os_ > 0 else 1
            else:
                ang = aerial_wrap(aerial_atan2(guy, gux) - me.a)
                self.flick_dir = 1 if ang > 0 else -1
            self.mode = "shoot" if rng.random() > p["control"] * 0.3 else "carry"
            self.carry_t = -0.25
            return AerialInput(1, 8 * self.flick_dir, me.boost > 5, True)
        if self.carry_t < 0:                                # mid flick: keep the snap going
            return AerialInput(1, 8 * self.flick_dir, me.boost > 5, True)
        # push it on toward goal: the nose on the far side of the ball from the goal, a little faster than the ball
        vb = _ae_sqrt(bvx * bvx + bvy * bvy)
        return self._hit(me, bx, by, gux, guy, 0.25, False, bv=(bvx, bvy), power=vb + 260.0 + 200.0 * p["control"])


def aerial_bot_match(key_a: str, key_b: str, seed: int = 1, kinds=None, match_s: float = None,
                     prof_a: dict = None, prof_b: dict = None, max_ticks: int = None) -> dict:
    """One headless bot against bot match (blue = key_a). Returns the result."""
    if kinds is None:
        ka = AERIAL_BOT_CAR.get(key_a, 0)
        kinds = (ka, aerial_bot_car(key_b, ka))
    m = AerialMatch(kinds, seed=seed, match_s=match_s, replays=False, vs_bot=True)
    a = AerialBot(0, key_a, seed, prof_a)
    b = AerialBot(1, key_b, seed + 1, prof_b)
    aerial_apply_assist(m, 0, key_a)
    aerial_apply_assist(m, 1, key_b)
    lim = max_ticks or int((m.length + 300) * AERIAL_HZ)
    n = 0
    while m.phase != m.OVER and n < lim:
        m.step([a.think(m), b.think(m)])
        n += 1
    r = m.result()
    r["bots"] = [a.stat, b.stat]
    r["timeout"] = m.phase != m.OVER
    return r


# SECTION: aerial (ladder)
# Ranks, MMR, rank-up series and the demotion shield, the player's Rubenium League profile (rank, history, settings)
# and the replay files. No Qt. The ladder rules here are the ones the server will run once ranked goes online; until
# then ranked against bots is kept on this PC (no coins depend on it).
import json as _ae_json
import os as _ae_os
import time as _ae_time
import zlib as _ae_zlib

AERIAL_NAME = "Rubenium League"
# Four families, ten ranks: Rookie 1-3, Challenger 1-3, Master 1-3, Rubenite. Family: name, colour, emblem shape.
AERIAL_FAMILIES = [("Rookie", "#7BE0A0", 0), ("Challenger", "#4FC3FF", 1), ("Master", "#F5C04A", 3),
                   ("Rubenite", "#FF2E63", 4)]
AERIAL_RANKS = [(0, 1), (0, 2), (0, 3), (1, 1), (1, 2), (1, 3), (2, 1), (2, 2), (2, 3), (3, 0)]   # (family, tier)
AERIAL_STEP = 5         # 5 more wins than losses against your rank's bot: up a rank; 5 more losses: down a rank
AERIAL_ROMAN = ("I", "II", "III")
AERIAL_REPLAY_V = 2     # 2: the flat top-down game. Replays from the side-view game (1) cannot be played again


def aerial_rank_name(i: int) -> str:
    fam, tier = AERIAL_RANKS[i]
    return AERIAL_FAMILIES[fam][0] + (" %d" % tier if tier else "")


def aerial_rank(mmr: float) -> dict:
    """A rating (0-1000: 100 a rank, 10 a win) to its rank: family, tier, colour, and the -5..+5 progress in it."""
    mmr = max(0.0, min(1000.0, float(mmr)))
    i = min(9, int(mmr // 100))
    v = int(round((mmr - i * 100 - 50) / 10.0))
    v = max(-5, min(5, v))
    fam, tier = AERIAL_RANKS[i]
    name, col, _shape = AERIAL_FAMILIES[fam]
    return {"rank": fam, "name": name, "tier": tier, "index": i, "colour": col, "v": v, "frac": (v + 5) / 10.0,
            "mmr": int(round(mmr)), "label": aerial_rank_name(i), "div": 0}


def aerial_rating(i: int, v: int) -> int:
    return i * 100 + 50 + 10 * v


class AerialLadder:
    """One player's place: the rank (0-9) and the progress in it (-5..+5). A win is +1, a loss -1; at +5 you go up a
    rank, at -5 down one, starting the new rank at 0. Your ranked opponent is always your rank's bot."""

    def __init__(self, d: dict = None) -> None:
        d = d or {}
        self.r = int(d.get("r", 0)) if "r" in d else 0
        self.v = int(d.get("v", 0)) if "r" in d else 0
        self.r = max(0, min(9, self.r))
        self.v = max(-5, min(5, self.v))
        self.peak = int(d.get("peak_r", self.r))
        self.reached = list(d.get("reached_r", [0]))

    @property
    def mmr(self) -> float:
        return float(aerial_rating(self.r, self.v))

    @property
    def series(self):
        return None

    def to_dict(self) -> dict:
        return {"r": self.r, "v": self.v, "peak_r": self.peak, "reached_r": self.reached}

    def opponents(self) -> list:
        return [AERIAL_BOT_ROSTER[self.r][0]]

    def result(self, _opp=None, won: bool = False) -> dict:
        before = (self.r, self.v)
        out = {"before": self.mmr, "rank_before": aerial_rank_name(self.r), "promoted": False, "demoted": False,
               "first": False, "series": None}
        self.v += 1 if won else -1
        if self.v >= AERIAL_STEP:
            if self.r < 9:
                self.r += 1
                self.v = 0
                out["promoted"] = True
                if self.r not in self.reached:
                    self.reached.append(self.r)
                    out["first"] = True
            else:
                self.v = AERIAL_STEP
        elif self.v <= -AERIAL_STEP:
            if self.r > 0:
                self.r -= 1
                self.v = 0
                out["demoted"] = True
            else:
                self.v = -AERIAL_STEP + 1          # nothing below Rookie 1
        self.peak = max(self.peak, self.r)
        out["after"] = self.mmr
        out["delta"] = int(round(self.mmr - out["before"]))
        out["rank_after"] = aerial_rank_name(self.r)
        out["v"] = self.v
        out["moved"] = (self.r, self.v) != before
        return out


class AerialStore:
    """The player's Rubenium League file (Documents/Rubenium/aerial/profile.json) and the last 10 replays."""
    KEEP = 10

    def __init__(self, folder) -> None:
        self.dir = str(folder)
        self.rep_dir = _ae_os.path.join(self.dir, "replays")
        self.data = {"ladder": {}, "history": [], "car": 0, "aim": "mouse", "keys": {}, "drills": {}, "seen_help": False}
        try:
            with open(_ae_os.path.join(self.dir, "profile.json"), encoding="utf-8") as f:
                d = _ae_json.load(f)
            if isinstance(d, dict):
                self.data.update(d)
        except (OSError, ValueError):
            pass
        self.ladder = AerialLadder(self.data.get("ladder"))

    def save(self) -> None:
        self.data["ladder"] = self.ladder.to_dict()
        try:
            _ae_os.makedirs(self.dir, exist_ok=True)
            tmp = _ae_os.path.join(self.dir, "profile.json.tmp")
            with open(tmp, "w", encoding="utf-8") as f:
                _ae_json.dump(self.data, f, separators=(",", ":"))
            _ae_os.replace(tmp, _ae_os.path.join(self.dir, "profile.json"))
        except OSError:
            pass

    def add_match(self, row: dict, replay: dict) -> None:
        """Remember a finished match (history keeps 200) and its replay (only the last 10 are kept)."""
        name = ""
        if replay is not None:
            name = "%d_%s.rlreplay" % (int(_ae_time.time()), row.get("mode", "match"))
            try:
                _ae_os.makedirs(self.rep_dir, exist_ok=True)
                with open(_ae_os.path.join(self.rep_dir, name), "wb") as f:
                    f.write(aerial_pack_replay(replay))
            except OSError:
                name = ""
        row["replay"] = name
        hist = self.data.setdefault("history", [])
        hist.insert(0, row)
        del hist[200:]
        keep = [h.get("replay") for h in hist if h.get("replay")][:self.KEEP]
        try:
            for f in _ae_os.listdir(self.rep_dir):
                if f.endswith(".rlreplay") and f not in keep:
                    _ae_os.remove(_ae_os.path.join(self.rep_dir, f))
        except OSError:
            pass
        for h in hist:
            if h.get("replay") and h["replay"] not in keep:
                h["replay"] = ""
        self.save()

    def settle_open(self) -> dict:
        """A ranked match that was never finished (the app closed or crashed during it) counts as a loss."""
        o = self.data.pop("open_ranked", None)
        if not o:
            return None
        row = AERIAL_BOTS.get(o.get("bot") or "")
        out = self.ladder.result(row["mmr"] if row else self.ladder.mmr, False)
        hist = self.data.setdefault("history", [])
        hist.insert(0, {"t": int(o.get("t", 0)), "mode": "ranked", "bot": o.get("bot"), "score": [0, 0], "won": False,
                        "forfeit": True, "mmr": int(self.ladder.mmr), "delta": out.get("delta", 0), "replay": ""})
        del hist[200:]
        self.save()
        return out

    def replay_path(self, name: str) -> str:
        return _ae_os.path.join(self.rep_dir, name)


def aerial_pack_replay(rep: dict) -> bytes:
    """A replay is the seed, the cars and every input: the match is played again exactly. Inputs are run-length
    packed, so a whole match is a few kilobytes."""
    out = dict(rep)
    for k in ("in0", "in1"):
        runs, last, n = [], None, 0
        for v in rep.get(k, []):
            if v == last:
                n += 1
            else:
                if last is not None:
                    runs.append([last, n])
                last, n = v, 1
        if last is not None:
            runs.append([last, n])
        out[k] = runs
    return b"RLR1" + _ae_zlib.compress(_ae_json.dumps(out, separators=(",", ":")).encode(), 9)


def aerial_unpack_replay(data: bytes) -> dict:
    if not data.startswith(b"RLR1"):
        raise ValueError("not a Rubenium League replay")
    rep = _ae_json.loads(_ae_zlib.decompress(data[4:]).decode())
    for k in ("in0", "in1"):
        flat = []
        for v, n in rep.get(k, []):
            flat.extend([int(v)] * int(n))
        rep[k] = flat
    return rep


# SECTION: aerial (drawing)
# How Rubenium League looks from above: the pitch in blue and orange, the boost orbs and pads (with their respawn
# rings), the ball, the three cars, boost flames, skid marks, the goal explosion. Drawing reads the sim and never
# changes it. Everything is QPainter (no pictures to load); the pitch is cached in a pixmap.
from PyQt6.QtCore import QPointF as _AeP, QRectF as _AeR, Qt as _AeQt
from PyQt6.QtGui import (QColor as _AeC, QLinearGradient as _AeLG, QPainter as _AePainter, QPainterPath as _AePath,
                         QPen as _AePen, QPixmap as _AePixmap, QRadialGradient as _AeRG, QBrush as _AeBrush)

AERIAL_TEAM = [{"main": "#2E8BFF", "light": "#8CC4FF", "dark": "#0E3E8C", "glow": "#4FA8FF", "name": "Blue"},
               {"main": "#FF8A1F", "light": "#FFC27A", "dark": "#8C3E05", "glow": "#FFA347", "name": "Orange"}]


def _ae_c(hx: str, a: float = 1.0) -> _AeC:
    c = _AeC(hx)
    c.setAlphaF(max(0.0, min(1.0, a)))
    return c


class AerialCam:
    """Game units to pixels: the whole pitch (goals included) fits the view, x to the right, y down."""

    def __init__(self, arena, w: float, h: float, top: float = 0.0) -> None:
        self.set(arena, w, h, top)

    def set(self, arena, w: float, h: float, top: float = 0.0) -> None:
        self.w, self.h = w, h
        span_x = 2 * (arena.hl + arena.gd) + 120
        span_y = 2 * arena.hw + 120
        self.k = min(w / span_x, (h - top) / span_y)
        self.ox = w / 2
        self.oyc = top + (h - top) / 2
        self.zoom, self.cx, self.cy = 1.0, 0.0, 0.0
        self.home = (0.0, 0.0)

    def s(self, v: float) -> float:
        return v * self.k * self.zoom


def aerial_cam_point(cam, x: float, y: float) -> _AeP:
    k = cam.k * cam.zoom
    return _AeP(cam.ox + (x - cam.cx) * k, cam.oyc + (y - cam.cy) * k)


class AerialPainter:
    """Draws one frame of a match. The pitch is drawn once into a pixmap per size."""

    def __init__(self) -> None:
        self._bg = None
        self._bg_key = None
        self.trail = []                 # recent ball positions (x, y, speed)
        self.skids = []                 # powerslide marks: [x, y, angle, life]

    def _arena_path(self, cam, arena) -> _AePath:
        path = _AePath()
        pts = arena.outline
        path.moveTo(aerial_cam_point(cam, *pts[0]))
        for q in pts[1:]:
            path.lineTo(aerial_cam_point(cam, *q))
        path.closeSubpath()
        return path

    def background(self, cam, arena, size) -> _AePixmap:
        key = (int(size.width()), int(size.height()), round(cam.k, 5))
        if self._bg is not None and self._bg_key == key:
            return self._bg
        pm = _AePixmap(int(size.width()), int(size.height()))
        pm.fill(_AeC("#05070D"))
        p = _AePainter(pm)
        p.setRenderHint(_AePainter.RenderHint.Antialiasing)
        P = lambda x, y: aerial_cam_point(cam, x, y)          # noqa: E731
        hl, hw, gw, gd = arena.hl, arena.hw, arena.gw, arena.gd
        path = self._arena_path(cam, arena)
        # the turf: dark green-blue with mowing stripes, each half tinted in its team's colour
        p.fillPath(path, _AeBrush(_AeC("#0E1A22")))
        p.save()
        p.setClipPath(path)
        n = 14
        for i in range(n):
            x0 = -hl - gd + (2 * (hl + gd)) * i / n
            x1 = -hl - gd + (2 * (hl + gd)) * (i + 1) / n
            if i % 2 == 0:
                p.fillRect(_AeR(P(x0, -hw), P(x1, hw)), _ae_c("#FFFFFF", 0.025))
        for team, s in ((0, -1.0), (1, 1.0)):
            col = AERIAL_TEAM[team]
            g = _AeLG(P(s * (hl + gd), 0), P(0, 0))
            g.setColorAt(0, _ae_c(col["main"], 0.26))
            g.setColorAt(1, _ae_c(col["main"], 0.03))
            r = _AeR(P(min(0.0, s * (hl + gd)), -hw), P(max(0.0, s * (hl + gd)), hw))
            p.fillRect(r, _AeBrush(g))
        line = _AePen(_ae_c("#E8F0FF", 0.42), max(1.5, cam.s(10)))
        p.setPen(line)
        p.setBrush(_AeC(0, 0, 0, 0))
        p.drawLine(P(0, -hw), P(0, hw))
        cr = cam.s(430)
        p.drawEllipse(P(0, 0), cr, cr)
        p.setBrush(_ae_c("#E8F0FF", 0.5))
        p.drawEllipse(P(0, 0), cam.s(16), cam.s(16))
        p.setBrush(_AeC(0, 0, 0, 0))
        for team, s in ((0, -1.0), (1, 1.0)):
            col = AERIAL_TEAM[team]
            p.setPen(_AePen(_ae_c(col["light"], 0.5), max(1.5, cam.s(10))))
            bx = s * (hl - 620)
            p.drawRect(_AeR(P(min(bx, s * hl), -(gw + 260)), P(max(bx, s * hl), gw + 260)))
            p.drawArc(_AeR(P(bx - 300, -300), P(bx + 300, 300)), (90 if s > 0 else -90) * 16, 180 * 16)
        p.restore()
        # the goals: a net in the team's colour and a bright frame
        for team, s in ((0, -1.0), (1, 1.0)):
            col = AERIAL_TEAM[team]
            rr = _AeR(P(min(s * hl, s * (hl + gd)), -gw), P(max(s * hl, s * (hl + gd)), gw))
            g3 = _AeLG(P(s * hl, 0), P(s * (hl + gd), 0))
            g3.setColorAt(0, _ae_c(col["main"], 0.35))
            g3.setColorAt(1, _ae_c(col["dark"], 0.9))
            p.fillRect(rr, _AeBrush(g3))
            p.setPen(_AePen(_ae_c(col["light"], 0.22), 1))
            step = max(4.0, cam.s(55))
            x = rr.left()
            while x < rr.right():
                p.drawLine(_AeP(x, rr.top()), _AeP(x, rr.bottom()))
                x += step
            y = rr.top()
            while y < rr.bottom():
                p.drawLine(_AeP(rr.left(), y), _AeP(rr.right(), y))
                y += step
            p.setPen(_AePen(_AeC(col["light"]), max(2.0, cam.s(18))))
            p.drawLine(P(s * hl, -gw), P(s * hl, gw))
            p.setBrush(_AeC("#FFFFFF"))
            p.setPen(_AeQt.PenStyle.NoPen)
            for gy in (-gw, gw):
                p.drawEllipse(P(s * hl, gy), cam.s(22), cam.s(22))
        # the walls
        p.setPen(_AePen(_ae_c("#9FB4FF", 0.75), max(2.0, cam.s(16))))
        p.setBrush(_AeC(0, 0, 0, 0))
        p.drawPath(path)
        p.setPen(_AePen(_ae_c("#9FB4FF", 0.18), max(4.0, cam.s(60))))
        p.drawPath(path)
        p.end()
        self._bg, self._bg_key = pm, key
        return pm

    # -- boost pads: a glowing orb or disc when there; a dim ring that fills up while it comes back
    def pads(self, p: _AePainter, cam, sim, t: float) -> None:
        tune = sim.t
        for k, (x, y, big) in enumerate(sim.arena.pads):
            q = aerial_cam_point(cam, x, y)
            wait = sim.pad_t[k]
            full = tune["big_respawn"] if big else tune["small_respawn"]
            r = cam.s(78 if big else 40)
            if wait <= 0:
                pulse = 0.85 + 0.15 * _ae_math.sin(t * 4.0 + k)
                g = _AeRG(q, r * 1.9)
                g.setColorAt(0, _ae_c("#FFE37A", 0.55 * pulse))
                g.setColorAt(1, _ae_c("#FFB020", 0.0))
                p.setPen(_AeQt.PenStyle.NoPen)
                p.setBrush(g)
                p.drawEllipse(q, r * 1.9, r * 1.9)
                g2 = _AeRG(_AeP(q.x() - r * 0.3, q.y() - r * 0.3), r * 1.2)
                g2.setColorAt(0, _AeC("#FFFBE0"))
                g2.setColorAt(1, _AeC("#FFB020"))
                p.setBrush(g2)
                p.drawEllipse(q, r * (0.62 if big else 0.55), r * (0.62 if big else 0.55))
            else:
                p.setPen(_AePen(_ae_c("#FFB020", 0.22), max(1.0, cam.s(8))))
                p.setBrush(_ae_c("#000000", 0.25))
                p.drawEllipse(q, r * 0.6, r * 0.6)
                p.setPen(_AePen(_ae_c("#FFD24A", 0.75), max(1.0, cam.s(9)), cap=_AeQt.PenCapStyle.RoundCap))
                p.setBrush(_AeC(0, 0, 0, 0))
                done = max(0.0, min(1.0, 1.0 - wait / full))
                rr = r * 0.6
                p.drawArc(_AeR(q.x() - rr, q.y() - rr, 2 * rr, 2 * rr), 90 * 16, -int(360 * 16 * done))

    # -- bodies
    def ball(self, p: _AePainter, cam, b, R: float, glow: float = 0.0) -> None:
        c = aerial_cam_point(cam, b.x, b.y)
        r = cam.s(R)
        sp = _ae_sqrt(b.vx * b.vx + b.vy * b.vy)
        n = len(self.trail)
        for i, (tx, ty, ts) in enumerate(self.trail):
            a = (i + 1) / max(1, n) * max(0.0, min(1.0, (ts - 1400.0) / 2200.0)) * 0.4
            if a > 0.01:
                q = aerial_cam_point(cam, tx, ty)
                p.setPen(_AeQt.PenStyle.NoPen)
                p.setBrush(_ae_c("#FFFFFF", a))
                rr = r * (0.3 + 0.6 * (i + 1) / n)
                p.drawEllipse(q, rr, rr)
        p.setPen(_AeQt.PenStyle.NoPen)
        p.setBrush(_ae_c("#000000", 0.35))
        p.drawEllipse(_AeP(c.x() + r * 0.18, c.y() + r * 0.22), r, r)
        if sp > 2600 or glow > 0:
            gl = _AeRG(c, r * 2.2)
            gl.setColorAt(0, _ae_c("#FFFFFF", 0.25 + 0.3 * glow))
            gl.setColorAt(1, _ae_c("#FFFFFF", 0.0))
            p.setBrush(gl)
            p.drawEllipse(c, r * 2.2, r * 2.2)
        rg = _AeRG(_AeP(c.x() - r * 0.35, c.y() - r * 0.4), r * 1.3)
        rg.setColorAt(0, _AeC("#FFFFFF"))
        rg.setColorAt(0.6, _AeC("#D9DEE8"))
        rg.setColorAt(1, _AeC("#8D96A8"))
        p.setPen(_AePen(_AeC("#2A2F3A"), max(1.0, r * 0.06)))
        p.setBrush(rg)
        p.drawEllipse(c, r, r)
        p.save()
        p.translate(c)
        p.rotate(b.a * 57.29578)
        p.setPen(_AePen(_ae_c("#3A4152", 0.7), max(1.0, r * 0.08)))
        p.setBrush(_AeC(0, 0, 0, 0))
        for _k in range(3):
            p.rotate(120)
            p.drawLine(_AeP(r * 0.22, 0), _AeP(r * 0.92, 0))
        p.setBrush(_ae_c("#3A4152", 0.85))
        p.drawEllipse(_AeP(0, 0), r * 0.22, r * 0.22)
        p.restore()

    def skid(self, cars) -> None:
        for c in cars:
            if c.drifting and c.speed() > 300:
                for side in (-1.0, 1.0):
                    x = c.x - c.fx * c.hl * 0.9 - c.fy * c.r * 0.8 * side
                    y = c.y - c.fy * c.hl * 0.9 + c.fx * c.r * 0.8 * side
                    self.skids.append([x, y, 1.0])
        del self.skids[:-500]

    def fade_skids(self, dt: float) -> None:
        for s in self.skids:
            s[2] -= dt * 0.6
        self.skids = [s for s in self.skids if s[2] > 0]

    def draw_skids(self, p: _AePainter, cam) -> None:
        p.setPen(_AeQt.PenStyle.NoPen)
        r = max(1.0, cam.s(9))
        for x, y, a in self.skids:
            p.setBrush(_ae_c("#000000", 0.35 * a))
            p.drawEllipse(aerial_cam_point(cam, x, y), r, r)

    def car(self, p: _AePainter, cam, c, kind: int, team: int, boosting: bool, t: float,
            ghost: bool = False, ring: bool = False) -> None:
        """A car from above: body, cabin and windscreen, four wheels, the boost flame out of the back."""
        col = AERIAL_TEAM[team]
        k = cam.k * cam.zoom
        ctr = aerial_cam_point(cam, c.x, c.y)
        ang = _ae_math.degrees(_ae_math.atan2(c.fy, c.fx))
        L = (c.hl + c.r) * k                              # half length in pixels
        H = c.r * k * (1.05 if kind != 1 else 1.15)       # half width
        p.save()
        p.translate(ctr)
        p.rotate(ang)
        if ghost:
            p.setOpacity(0.35)
        p.setPen(_AeQt.PenStyle.NoPen)
        p.setBrush(_ae_c("#000000", 0.35))
        p.drawRoundedRect(_AeR(-L + k * 6, -H + k * 8, 2 * L, 2 * H), H * 0.6, H * 0.6)
        if boosting:
            ln = L * (1.0 + 0.3 * _ae_math.sin(t * 40))
            fg = _AeLG(_AeP(-L, 0), _AeP(-L - ln, 0))
            fg.setColorAt(0, _ae_c("#FFFFFF", 0.95))
            fg.setColorAt(0.25, _ae_c(col["glow"], 0.9))
            fg.setColorAt(1, _ae_c(col["glow"], 0.0))
            fl = _AePath()
            fl.moveTo(-L * 0.9, -H * 0.55)
            fl.quadTo(-L - ln * 0.6, -H * 0.35, -L - ln, 0)
            fl.quadTo(-L - ln * 0.6, H * 0.35, -L * 0.9, H * 0.55)
            fl.closeSubpath()
            p.fillPath(fl, _AeBrush(fg))
        if ring:
            p.setPen(_AePen(_ae_c("#FFFFFF", 0.55), max(1.0, k * 5)))
            p.setBrush(_AeC(0, 0, 0, 0))
            p.drawEllipse(_AeP(0, 0), L * 1.35, L * 1.35)
        # wheels
        p.setPen(_AeQt.PenStyle.NoPen)
        p.setBrush(_AeC("#0B0D12"))
        ww, wl = H * 0.32, L * 0.3
        for wx in (-L * 0.58, L * 0.52):
            for sy in (-1.0, 1.0):
                p.drawRoundedRect(_AeR(wx - wl / 2, sy * H * 0.98 - ww / 2, wl, ww), ww * 0.3, ww * 0.3)
        body = _AePath()
        if kind == 1:          # Blade: long, slim, a pointed nose
            body.moveTo(L, 0)
            body.lineTo(L * 0.55, -H * 0.8)
            body.lineTo(-L * 0.85, -H * 0.9)
            body.quadTo(-L, -H * 0.9, -L, -H * 0.5)
            body.lineTo(-L, H * 0.5)
            body.quadTo(-L, H * 0.9, -L * 0.85, H * 0.9)
            body.lineTo(L * 0.55, H * 0.8)
        elif kind == 2:        # Titan: short, wide, square
            body.addRoundedRect(_AeR(-L, -H, 2 * L, 2 * H), H * 0.28, H * 0.28)
        else:                  # Comet: rounded all-rounder
            body.addRoundedRect(_AeR(-L, -H * 0.92, 2 * L, 1.84 * H), H * 0.7, H * 0.7)
        body.closeSubpath()
        bg = _AeLG(_AeP(0, -H), _AeP(0, H))
        bg.setColorAt(0, _AeC(col["light"]))
        bg.setColorAt(0.5, _AeC(col["main"]))
        bg.setColorAt(1, _AeC(col["dark"]))
        p.setPen(_AePen(_ae_c("#0A0D14", 0.9), max(1.0, k * 3)))
        p.setBrush(bg)
        p.drawPath(body)
        # cabin and windscreen
        cab = _AeR(-L * 0.45, -H * 0.58, L * 0.95, H * 1.16)
        p.setPen(_AeQt.PenStyle.NoPen)
        p.setBrush(_ae_c(col["dark"], 0.9))
        p.drawRoundedRect(cab, H * 0.35, H * 0.35)
        ws = _AePath()
        ws.moveTo(L * 0.5, -H * 0.55)
        ws.lineTo(L * 0.5, H * 0.55)
        ws.lineTo(L * 0.2, H * 0.48)
        ws.lineTo(L * 0.2, -H * 0.48)
        ws.closeSubpath()
        p.setBrush(_ae_c("#BFE3FF", 0.85))
        p.drawPath(ws)
        p.setBrush(_ae_c("#FFFFFF", 0.3))
        p.drawRect(_AeR(-L * 0.95, -H * 0.12, L * 0.45, H * 0.24))
        p.setBrush(_AeC("#FFF6C8"))
        for sy in (-1.0, 1.0):
            p.drawEllipse(_AeP(L * 0.9, sy * H * 0.55), H * 0.14, H * 0.14)
        p.setBrush(_AeC("#FF3355"))
        for sy in (-1.0, 1.0):
            p.drawRect(_AeR(-L * 1.0, sy * H * 0.6 - H * 0.12, L * 0.06, H * 0.24))
        p.restore()

    def boost_meter(self, p: _AePainter, cx: float, cy: float, rad: float, v: float, team: int,
                    boosting: bool = False) -> None:
        """The boost meter: a thick ring that empties as you boost, the number in the middle."""
        col = AERIAL_TEAM[team]
        p.setPen(_AeQt.PenStyle.NoPen)
        p.setBrush(_ae_c("#000000", 0.55))
        p.drawEllipse(_AeP(cx, cy), rad * 1.32, rad * 1.32)
        p.setPen(_AePen(_ae_c("#FFFFFF", 0.12), rad * 0.26))
        p.setBrush(_AeC(0, 0, 0, 0))
        p.drawEllipse(_AeP(cx, cy), rad, rad)
        f = max(0.0, min(1.0, v / 100.0))
        hue = "#FFD24A" if f > 0.3 else "#FF6B4A"
        p.setPen(_AePen(_AeC(col["glow"] if f > 0.3 else hue), rad * 0.26, cap=_AeQt.PenCapStyle.RoundCap))
        p.drawArc(_AeR(cx - rad, cy - rad, 2 * rad, 2 * rad), 225 * 16, -int(270 * 16 * f))
        if boosting:
            g = _AeRG(_AeP(cx, cy), rad * 1.4)
            g.setColorAt(0, _ae_c(col["glow"], 0.0))
            g.setColorAt(0.8, _ae_c(col["glow"], 0.25))
            g.setColorAt(1, _ae_c(col["glow"], 0.0))
            p.setPen(_AeQt.PenStyle.NoPen)
            p.setBrush(g)
            p.drawEllipse(_AeP(cx, cy), rad * 1.4, rad * 1.4)

    def boost_bar(self, p: _AePainter, cx: float, cy: float, rad: float, v: float, team: int) -> None:
        self.boost_meter(p, cx, cy, rad, v, team)


# SECTION: aerial (game view)
import collections  # noqa: E402
import datetime  # noqa: E402
import math  # noqa: E402
import random  # noqa: E402
from PyQt6.QtCore import QEasingCurve, QEvent, QSizeF, QUrl  # noqa: E402,F811
from PyQt6.QtGui import QDesktopServices  # noqa: E402,F811
from PyQt6.QtWidgets import QGridLayout, QWidget  # noqa: E402,F811
# Rubenium League on screen: the match runs inside the online menu (like Karting): the menu widens, the match fades
# in over it, and leaving brings the menu back. Physics at a fixed 120 steps a second, drawing at the screen's rate.


def aerial_store(ctx=None) -> AerialStore:
    st = getattr(ctx, "aerial_store", None) if ctx is not None else None
    if st is None:
        st = AerialStore(DATA_DIR / "aerial")
        if ctx is not None:
            ctx.aerial_store = st
    return st


def aerial_enabled(ctx=None) -> bool:
    """Rubenium League shows unless an admin hid it for everyone (Admin > Locks, "league", or the admin button in the
    League lobby). Admins always see it, so they can test it while it is hidden."""
    econ = getattr(ctx, "econ", None) if ctx is not None else None
    try:
        return not (econ is not None and econ.is_locked("league"))
    except Exception:  # noqa: BLE001
        return True


def aerial_hidden_for_players(ctx) -> bool:
    """For the admins' note in the lobby: the game is hidden for everyone else."""
    econ = getattr(ctx, "econ", None)
    return "league" in ((getattr(econ, "locks", None) or {}).get("locked") or [])


def aerial_draw_emblem(p: QPainter, r: QRectF, rank: int, tier: int = 1, div: int = 1, t: float = 0.0,
                       glow: bool = True) -> None:
    """The five rank emblems: one family whose shape grows with rank. Rookie a bolt on a hex plate, Challenger twin
    chevrons, Elite a cut crystal with short wings, Champion a crowned flame with wings, Rubenite a faceted ruby with
    the Rubenium R and a slow shine. Tier: pips under it; division: bars on the plate."""
    col = QColor(AERIAL_FAMILIES[rank][1])
    fam = rank
    rank = AERIAL_FAMILIES[fam][2]                     # the shape: 0 hex, 1 chevrons, 3 crown, 4 ruby
    dark = col.darker(260)
    light = col.lighter(150)
    p.save()
    p.setRenderHint(QPainter.RenderHint.Antialiasing)
    c = r.center()
    s = min(r.width(), r.height()) / 2.0
    p.translate(c)
    p.scale(s / 50.0, s / 50.0)                      # draw in a 100 x 100 box
    if glow:
        g = QRadialGradient(QPointF(0, 0), 52)
        g.setColorAt(0, alpha(col, 0.35 + 0.1 * fam))
        g.setColorAt(1, alpha(col, 0.0))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(g)
        p.drawEllipse(QPointF(0, 0), 52, 52)
    # wings (Elite and up), longer with rank
    if rank >= 2:
        wl = 16 + 8 * (rank - 2)
        for sx in (-1, 1):
            w = QPainterPath()
            w.moveTo(sx * 18, -6)
            w.cubicTo(sx * (18 + wl), -22, sx * (24 + wl), -4, sx * (20 + wl * 0.9), 10)
            w.cubicTo(sx * (14 + wl * 0.6), 6, sx * 22, 12, sx * 16, 16)
            w.closeSubpath()
            wg = QLinearGradient(QPointF(sx * 18, 0), QPointF(sx * (22 + wl), 0))
            wg.setColorAt(0, light)
            wg.setColorAt(1, alpha(col, 0.55))
            p.setPen(QPen(dark, 1.6))
            p.setBrush(wg)
            p.drawPath(w)
    # the plate
    plate = QPainterPath()
    if rank == 0:
        for i in range(6):
            a = math.pi / 3 * i + math.pi / 6
            pt = QPointF(30 * math.cos(a), 30 * math.sin(a))
            plate.moveTo(pt) if i == 0 else plate.lineTo(pt)
    elif rank == 1:
        plate.moveTo(0, -34)
        plate.lineTo(28, -16)
        plate.lineTo(28, 14)
        plate.lineTo(0, 34)
        plate.lineTo(-28, 14)
        plate.lineTo(-28, -16)
    elif rank == 2:
        plate.moveTo(0, -38)
        plate.lineTo(24, -12)
        plate.lineTo(16, 30)
        plate.lineTo(0, 38)
        plate.lineTo(-16, 30)
        plate.lineTo(-24, -12)
    elif rank == 3:
        plate.moveTo(0, -40)
        plate.cubicTo(18, -26, 30, -8, 22, 16)
        plate.cubicTo(16, 30, 6, 36, 0, 38)
        plate.cubicTo(-6, 36, -16, 30, -22, 16)
        plate.cubicTo(-30, -8, -18, -26, 0, -40)
    else:
        plate.moveTo(0, -42)
        plate.lineTo(26, -20)
        plate.lineTo(30, 6)
        plate.lineTo(14, 32)
        plate.lineTo(0, 42)
        plate.lineTo(-14, 32)
        plate.lineTo(-30, 6)
        plate.lineTo(-26, -20)
    plate.closeSubpath()
    pg = QLinearGradient(QPointF(0, -40), QPointF(0, 40))
    pg.setColorAt(0, light)
    pg.setColorAt(0.5, col)
    pg.setColorAt(1, dark)
    p.setPen(QPen(QColor("#0B0E16"), 2.4))
    p.setBrush(pg)
    p.drawPath(plate)
    # facets (Elite and up)
    if rank >= 2:
        p.setPen(QPen(alpha("#FFFFFF", 0.35), 1.2))
        p.drawLine(QPointF(0, -36), QPointF(0, 36))
        p.drawLine(QPointF(-22, -12), QPointF(0, 6))
        p.drawLine(QPointF(22, -12), QPointF(0, 6))
    # the crown (Champion) / the shine (Rubenite)
    if rank == 3:
        cr = QPainterPath()
        cr.moveTo(-16, -38)
        cr.lineTo(-10, -50)
        cr.lineTo(-4, -42)
        cr.lineTo(0, -54)
        cr.lineTo(4, -42)
        cr.lineTo(10, -50)
        cr.lineTo(16, -38)
        cr.closeSubpath()
        p.setPen(QPen(dark, 1.4))
        p.setBrush(QColor("#FFE08A"))
        p.drawPath(cr)
    if rank == 4:
        p.save()
        p.setClipPath(plate)
        x = -60 + ((t * 30) % 160)
        sh = QLinearGradient(QPointF(x - 14, -40), QPointF(x + 14, 40))
        sh.setColorAt(0, alpha("#FFFFFF", 0.0))
        sh.setColorAt(0.5, alpha("#FFFFFF", 0.45))
        sh.setColorAt(1, alpha("#FFFFFF", 0.0))
        p.fillRect(QRectF(-50, -50, 100, 100), QBrush(sh))
        p.restore()
    # the symbol
    p.setPen(QPen(QColor("#0B0E16"), 1.4))
    p.setBrush(QColor("#FFFFFF"))
    if rank == 0:
        b = QPainterPath()
        b.moveTo(4, -20)
        b.lineTo(-10, 4)
        b.lineTo(0, 4)
        b.lineTo(-4, 20)
        b.lineTo(10, -4)
        b.lineTo(0, -4)
        b.closeSubpath()
        p.drawPath(b)
    elif rank == 1:
        for dy in (-8, 6):
            ch = QPainterPath()
            ch.moveTo(-14, dy + 6)
            ch.lineTo(0, dy - 6)
            ch.lineTo(14, dy + 6)
            ch.lineTo(14, dy + 12)
            ch.lineTo(0, dy)
            ch.lineTo(-14, dy + 12)
            ch.closeSubpath()
            p.drawPath(ch)
    elif rank == 2:
        cy = QPainterPath()
        cy.moveTo(0, -18)
        cy.lineTo(10, -4)
        cy.lineTo(0, 18)
        cy.lineTo(-10, -4)
        cy.closeSubpath()
        p.drawPath(cy)
    elif rank == 3:
        fl = QPainterPath()
        fl.moveTo(0, -20)
        fl.cubicTo(12, -6, 12, 8, 0, 18)
        fl.cubicTo(-12, 8, -10, -4, -2, -8)
        fl.cubicTo(-4, 0, 2, 2, 0, -20)
        p.drawPath(fl)
    else:
        p.setFont(font(26, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(QRectF(-20, -22, 40, 40), int(Qt.AlignmentFlag.AlignCenter), "R")
    # division bars (not used by the 10-rank ladder) and tier pips (none on Rubenite)
    for i in range(3 if div else 0):
        on = i < div
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#FFFFFF") if on else alpha("#000000", 0.35))
        p.drawRoundedRect(QRectF(-13 + i * 9.5, 24, 7, 4), 1.5, 1.5)
    for i in range(3 if tier else 0):
        on = i < tier
        p.setPen(QPen(dark, 1.0))
        p.setBrush(light if on else alpha("#000000", 0.4))
        p.drawEllipse(QPointF(-12 + i * 12, 47), 4, 4)
    p.restore()


class AerialEmblem(QWidget):
    """A rank emblem as a widget (it shines while on screen when it is Rubenite)."""

    def __init__(self, mmr: float, size: int = 64, rank_info: dict = None) -> None:
        super().__init__()
        self.info = rank_info or aerial_rank(mmr)
        self.setFixedSize(S(size), S(size))
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)
        self._t = None
        if self.info["rank"] == 4:
            self._t = QTimer(self)
            self._t.setInterval(50)
            self._t.timeout.connect(self.update)

    def showEvent(self, _e) -> None:
        if self._t is not None:
            self._t.start()

    def hideEvent(self, _e) -> None:
        if self._t is not None:
            self._t.stop()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        i = self.info
        aerial_draw_emblem(p, QRectF(self.rect()), i["rank"], i["tier"], i["div"], time.monotonic())


def aerial_azerty() -> bool:
    """A French keyboard (from the system's input language, else the app's language)."""
    try:
        from PyQt6.QtCore import QLocale
        from PyQt6.QtGui import QGuiApplication
        im = QGuiApplication.inputMethod()
        if im is not None and im.locale().language() == QLocale.Language.French:
            return True
    except Exception:  # noqa: BLE001
        pass
    return lang() == "fr"


def aerial_keys() -> dict:
    """The driving keys shown in the lobby: WASD and ZQSD both work at the same time; the first set shown is the
    one of this keyboard."""
    return {"up": "Z", "left": "Q", "down": "S", "right": "D", "alt": "W A S D"} if aerial_azerty() else \
        {"up": "W", "left": "A", "down": "S", "right": "D", "alt": "Z Q S D"}


class AerialView(QWidget):
    """The match: input, the fixed physics clock, the drawing, goal replays and the menus over it.
    mode: "free" (Free Play, one car), "practice" (any bot, no MMR), "private" (a match you set up, no MMR),
    "ranked" (your rank's bot), "replay" (a saved match played again), "watch" (admins: bot against bot)."""
    finished = pyqtSignal(dict)
    leave = pyqtSignal()
    again = pyqtSignal()

    def __init__(self, ctx, cfg: dict) -> None:
        super().__init__()
        self.ctx, self.cfg = ctx, dict(cfg)
        self.setFocusPolicy(Qt.FocusPolicy.StrongFocus)
        self.setMouseTracking(True)
        self.setContextMenuPolicy(Qt.ContextMenuPolicy.PreventContextMenu)   # right click is the powerslide
        self.setMinimumSize(S(560), S(320))
        self.store = aerial_store(ctx)
        self.mode = cfg.get("mode", "practice")
        rep = cfg.get("replay_data")
        if rep is not None:
            self.seed, kinds, self.bot_key = int(rep["seed"]), tuple(rep["kinds"]), rep.get("bot")
            self.match_s = float(rep.get("match_s", AERIAL_TUNE["match_s"]))
            self.rep_in = (rep["in0"], rep["in1"])
            self.bot0_key = rep.get("bot0")
        else:
            self.seed = int(cfg.get("seed") or (int(time.time() * 1000) & 0x7FFFFFFF))
            mine = int(self.store.data.get("car", 0)) % len(AERIAL_CARS)
            self.bot0_key = cfg.get("bot0") if self.mode == "watch" else None
            if self.bot0_key:
                mine = AERIAL_BOT_CAR.get(self.bot0_key, 0)
            bot_car = cfg.get("bot_car")
            if bot_car is None or int(bot_car) == mine:
                bot_car = aerial_bot_car(cfg.get("bot"), mine)
            kinds = (mine, int(bot_car))
            self.bot_key = cfg.get("bot")
            self.match_s = float(cfg.get("match_s", AERIAL_TUNE["match_s"]))
            self.rep_in = None
        self.m = AerialMatch(kinds, seed=self.seed, match_s=self.match_s, replays=True, vs_bot=True)
        self.free = self.mode == "free"
        if self.free:
            self.m.sim.active = [True, False]
            self.m.sim.cars[1].x = self.m.sim.cars[1].y = 99999.0
            self.m.phase = self.m.LIVE
            self.m.sim.frozen = False
        self.bot = None
        self.bot0 = None                       # (admins) bot against bot: a bot drives blue too
        if self.bot0_key in AERIAL_BOTS:
            if self.rep_in is None:
                self.bot0 = AerialBot(0, self.bot0_key, self.seed + 99)
            aerial_apply_assist(self.m, 0, self.bot0_key)
        if self.bot_key and not self.free and self.rep_in is None:
            self.bot = AerialBot(1, self.bot_key, self.seed)
        if self.bot_key and not self.free:
            aerial_apply_assist(self.m, 1, self.bot_key)   # replays too, so they play back the same
        self.keys: set = set()
        self.mouse = None
        self.lmb = self.rmb = False
        self.log0, self.log1 = [], []
        self.ring = collections.deque(maxlen=AERIAL_HZ * 9)      # (tick, snapshot) for goal replays
        self.painter = AerialPainter()
        self.cam = None
        self.fx: list = []                     # particles [x, y, vx, vy, life, max, colour, size]
        self.waves: list = []                  # goal shock waves [x, y, age, colour]
        self.pops: list = []                   # [text, colour, until, team]
        self.banner = None                     # (text, colour, until)
        self.shake = 0.0
        self.paused = False
        self.menu_open = False
        self.over = False
        self.result = None
        self.inf_boost = True                  # Free Play: infinite boost (B turns it off)
        self.slow = False
        self.hitbox = False
        self.mech_label = None
        self.free_wait = 0
        self.tab_down = False
        self.hide_ball = False
        self.step_acc = 0.0
        self._last = time.monotonic()
        self._fps = 60.0
        self.last_count = 9
        self.t0 = time.monotonic()
        self.fx_scale = 0.0 if getattr(ui, "motion", 1.0) <= 0.01 else 1.0
        self.timer = QTimer(self)
        self.timer.setTimerType(Qt.TimerType.PreciseTimer)
        self.timer.setInterval(7)
        self.timer.timeout.connect(self._tick)
        self.timer.start()
        if self.free:
            self._free_reset()
        if self.mode == "ranked":
            self.store.data["open_ranked"] = {"bot": self.bot_key, "t": int(time.time())}
            self.store.save()

    # ---------------------------------------------------------------------------------------- input
    def keyPressEvent(self, e) -> None:
        if e.isAutoRepeat():
            return
        k = e.key()
        if k == Qt.Key.Key_Escape:
            return self.toggle_menu()
        if k == Qt.Key.Key_Tab:
            self.tab_down = True
            return
        self.keys.add(k)
        if self.free and not self.menu_open:
            if k == Qt.Key.Key_R:
                self._free_reset()
            elif k == Qt.Key.Key_T:
                self._free_drop()
            elif k == Qt.Key.Key_B:
                self.inf_boost = not self.inf_boost
            elif k == Qt.Key.Key_G:
                self.slow = not self.slow
            elif k == Qt.Key.Key_H:
                self.hitbox = not self.hitbox

    def keyReleaseEvent(self, e) -> None:
        if not e.isAutoRepeat():
            self.keys.discard(e.key())
            if e.key() == Qt.Key.Key_Tab:
                self.tab_down = False

    def contextMenuEvent(self, e) -> None:
        e.accept()                             # never a right-click menu during play

    def _playing(self) -> bool:
        return not self.menu_open and not self.over and self.mode not in ("replay", "watch")

    def mouseMoveEvent(self, e) -> None:
        self.mouse = e.position()

    def mousePressEvent(self, e) -> None:
        self.setFocus()
        if self.menu_open or self.over:
            return
        if e.button() == Qt.MouseButton.LeftButton:
            self.lmb = True
        elif e.button() == Qt.MouseButton.RightButton:
            self.rmb = True
        e.accept()

    def mouseReleaseEvent(self, e) -> None:
        if e.button() == Qt.MouseButton.LeftButton:
            self.lmb = False
        elif e.button() == Qt.MouseButton.RightButton:
            self.rmb = False
        e.accept()

    def mouseDoubleClickEvent(self, e) -> None:
        self.mousePressEvent(e)

    def focusOutEvent(self, _e) -> None:
        self.keys.clear()                      # never a stuck key after alt-tab
        self.lmb = self.rmb = False
        self.tab_down = False

    def focusNextPrevChild(self, _n) -> bool:
        return False

    def _down(self, *keys) -> bool:
        return any(k in self.keys for k in keys)

    def _input(self) -> AerialInput:
        """WASD and ZQSD at the same time (and the arrows): forward, back/brake, steer. Shift or the left mouse
        button boosts; Ctrl or the right mouse button powerslides. Space skips a goal replay."""
        K = Qt.Key
        if self.menu_open or self.over:
            return AerialInput()
        up = self._down(K.Key_W, K.Key_Z, K.Key_Up)
        down = self._down(K.Key_S, K.Key_Down)
        left = self._down(K.Key_A, K.Key_Q, K.Key_Left)
        right = self._down(K.Key_D, K.Key_Right)
        boost = self._down(K.Key_Shift) or self.lmb
        drift = self._down(K.Key_Control) or self.rmb
        skip = self._down(K.Key_Space, K.Key_Return, K.Key_Enter) and self.m.phase == self.m.REPLAY
        thr = (1 if up else 0) - (1 if down else 0)
        steer = (8 if right else 0) - (8 if left else 0)
        return AerialInput(thr, steer, boost, drift, skip)

    def _intro(self, p: QPainter, w: float, h: float, t: float) -> None:
        def ease(x: float) -> float:
            x = max(0.0, min(1.0, x))
            return 1.0 - (1.0 - x) ** 3
        k_in = ease(t / 0.55)
        k_out = 1.0 - ease((t - 2.25) / 0.5)
        a = max(0.0, min(k_in, k_out))
        if a <= 0.0:
            return
        p.save()
        p.fillRect(QRectF(0, 0, w, h), alpha("#05070C", 0.45 * a))
        pw, ph = min(S(360), w * 0.4), S(84)
        cy = h * 0.30
        sides = []
        if self.bot0_key in AERIAL_BOTS:
            sides.append((self._me_name(), aerial_rank(AERIAL_BOTS[self.bot0_key]["mmr"]), AERIAL_TEAM[0]["glow"]))
        else:
            sides.append((self._me_name(), aerial_rank(self.store.ladder.mmr), AERIAL_TEAM[0]["glow"]))
        sides.append((AERIAL_BOTS[self.bot_key]["name"], aerial_rank(AERIAL_BOTS[self.bot_key]["mmr"]),
                      AERIAL_TEAM[1]["glow"]))
        for i, (name, info, col) in enumerate(sides):
            off = (1.0 - k_in) * (w * 0.6) * (-1 if i == 0 else 1)
            x = (w / 2 - S(40) - pw if i == 0 else w / 2 + S(40)) + off
            r = QRectF(x, cy - ph / 2, pw, ph)
            g = QLinearGradient(r.topLeft(), r.topRight())
            g.setColorAt(0 if i == 0 else 1, alpha(col, 0.55 * a))
            g.setColorAt(1 if i == 0 else 0, alpha("#0B0F18", 0.85 * a))
            p.setPen(QPen(alpha(col, 0.9 * a), S(1.5)))
            p.setBrush(QBrush(g))
            p.drawRoundedRect(r, S(14), S(14))
            em = QRectF(r.left() + S(10) if i == 0 else r.right() - S(74), r.top() + S(10), S(64), S(64))
            p.setOpacity(a)
            aerial_draw_emblem(p, em, info["rank"], info["tier"], 0, time.monotonic(), glow=True)
            p.setOpacity(1.0)
            tx = QRectF(r.left() + S(84), r.top() + S(12), pw - S(98), S(34)) if i == 0 else \
                QRectF(r.left() + S(14), r.top() + S(12), pw - S(98), S(34))
            al = Qt.AlignmentFlag.AlignLeft if i == 0 else Qt.AlignmentFlag.AlignRight
            p.setFont(font(19, QFont.Weight.Black))
            p.setPen(alpha("#FFFFFF", a))
            p.drawText(tx, int(al | Qt.AlignmentFlag.AlignVCenter), name)
            p.setFont(font(11, QFont.Weight.Bold, 1.5))
            p.setPen(alpha(info["colour"], a))
            p.drawText(tx.translated(0, S(30)), int(al | Qt.AlignmentFlag.AlignVCenter),
                       aerial_rank_label(info["index"]).upper())
        p.setFont(font(34 * (0.7 + 0.3 * k_in), QFont.Weight.Black))
        p.setPen(alpha("#FFFFFF", a))
        p.drawText(QRectF(0, cy - S(40), w, S(80)), int(Qt.AlignmentFlag.AlignCenter), tr("VS"))
        p.restore()

    def _me_name(self) -> str:
        return AERIAL_BOTS[self.bot0_key]["name"] if self.bot0_key in AERIAL_BOTS else tr("You")

    # ---------------------------------------------------------------------------------------- Free Play
    def _free_reset(self) -> None:
        """R: the car back to its spot with a full tank, the ball to the centre spot."""
        sim = self.m.sim
        c = sim.cars[0]
        c.reset(-900.0, 0.0, 0.0, 100.0)
        b = sim.ball
        b.x, b.y, b.vx, b.vy = 0.0, 0.0, 0.0, 0.0
        sim.ball_held = False
        sim.kick_wait = False
        sim.kick_cap_t = 0.0
        self.mech_label = None

    def _free_drop(self) -> None:
        """T: the ball a little in front of the car, rolling with it (quick dribble and flick practice)."""
        sim = self.m.sim
        c, b = sim.cars[0], sim.ball
        d = c.hl + c.r + AERIAL_TUNE["ball_r"] + 30
        x, y = c.x + c.fx * d, c.y + c.fy * d
        lim_x, lim_y = sim.arena.hl - 120, sim.arena.hw - 120
        b.x, b.y = max(-lim_x, min(lim_x, x)), max(-lim_y, min(lim_y, y))
        b.vx, b.vy = c.vx, c.vy
        sim.ball_held = False

    # ---------------------------------------------------------------------------------------- menus
    def toggle_menu(self) -> None:
        if self.over:
            return
        self.menu_open = not self.menu_open
        self.paused = self.menu_open and self.mode in ("free", "practice", "private", "replay")
        self.keys.clear()
        self.lmb = self.rmb = False
        self.update()

    def menu_rects(self) -> list:
        w, h = self.width(), self.height()
        bw, bh = S(260), S(46)
        items = [("resume", tr("Resume"))]
        if self.mode in ("free", "practice", "private"):
            items.append(("restart", tr("Restart")))
        items.append(("leave", tr("Forfeit and leave") if self.mode == "ranked" and not self.over else tr("Leave")))
        top = h / 2 - (len(items) * (bh + S(10))) / 2 + S(30)
        return [(k, label, QRectF(w / 2 - bw / 2, top + i * (bh + S(10)), bw, bh)) for i, (k, label) in enumerate(items)]

    def event(self, e) -> bool:
        if e.type() == QEvent.Type.MouseButtonRelease and self.menu_open:
            for k, _l, r in self.menu_rects():
                if r.contains(e.position()):
                    self._menu_pick(k)
                    return True
        return super().event(e)

    def _menu_pick(self, k: str) -> None:
        sfx.play("pick")
        if k == "resume":
            self.toggle_menu()
        elif k == "restart":
            self.menu_open = self.paused = False
            if self.free:
                self._free_reset()
            else:
                self.again.emit()
        elif k == "leave":
            self.menu_open = False
            if self.mode == "ranked" and not self.over and self.m.phase != self.m.OVER:
                self._forfeit()
            self.leave.emit()

    # ---------------------------------------------------------------------------------------- the clock
    def _tick(self) -> None:
        try:
            now = time.monotonic()
            dt = min(0.05, now - self._last)
            self._last = now
            self._fps = self._fps * 0.95 + (1.0 / max(1e-3, dt)) * 0.05
            if not self.paused and not self.over:
                self.step_acc += dt * (0.35 if (self.slow and self.free) else 1.0)
                n = 0
                while self.step_acc >= AERIAL_DT and n < 12:
                    self.step_acc -= AERIAL_DT
                    self._step()
                    n += 1
                    if self.over:
                        break
                if n >= 12:
                    self.step_acc = 0.0
            self._effects(dt)
            playing = self._playing() and self.isVisible() and self.hasFocus()
            if playing and self.cursor().shape() != Qt.CursorShape.BlankCursor:
                self.setCursor(Qt.CursorShape.BlankCursor)
            elif not playing and self.cursor().shape() == Qt.CursorShape.BlankCursor:
                self.unsetCursor()
            self.update()
        except RuntimeError:
            self.timer.stop()
        except Exception:  # noqa: BLE001
            self.timer.stop()                      # never an error every frame: stop, log once, leave
            log.exception("Rubenium League: the match stopped")
            self.store.data.pop("open_ranked", None)   # our fault, not the player's: no loss
            self.store.save()
            try:
                self.ctx.toast(tr("Rubenium League hit a problem and stopped"), "error")
            except Exception:  # noqa: BLE001
                pass
            self.leave.emit()

    def _step(self) -> None:
        m = self.m
        if self.rep_in is not None:
            i = len(self.log0)
            if i >= len(self.rep_in[0]):
                if m.phase != m.OVER:
                    self._end()
                return
            a = AerialInput.unpack(self.rep_in[0][i])
            b = AerialInput.unpack(self.rep_in[1][i]) if i < len(self.rep_in[1]) else AerialInput()
            self.log0.append(a.pack())
            self.log1.append(b.pack())
        else:
            a = self.bot0.think(m) if self.bot0 is not None else self._input()
            b = self.bot.think(m) if self.bot is not None else AerialInput()
            self.log0.append(a.pack())
            self.log1.append(b.pack())
        if self.free:
            m.sim.step([a, b])
            if self.inf_boost:
                m.sim.cars[0].boost = 100.0
            g = m.sim.ball_in_goal()
            if g >= 0 and not self.hide_ball:
                bb = m.sim.ball
                self._burst(bb.x, bb.y, 1 - g)
                self.banner = (tr("GOAL!"), "#FFFFFF", time.monotonic() + 1.2)
                sfx.play("gun")
                self.free_wait = int(0.9 * AERIAL_HZ)
                bb.vx = bb.vy = 0.0
                m.sim.ball_held = True
                self.hide_ball = True
            if self.free_wait > 0:
                self.free_wait -= 1
                if self.free_wait == 0:
                    self.hide_ball = False
                    b2 = m.sim.ball
                    b2.x, b2.y, b2.vx, b2.vy = 0.0, 0.0, 0.0, 0.0
                    m.sim.ball_held = False
            self.painter.skid(m.sim.cars[:1])
            self._react(m.sim.ev)
            return
        m.step([a, b])
        if m.phase != m.REPLAY:
            self.ring.append((m.sim.tick, m.snapshot()))
            self.painter.skid([c for c, on in zip(m.sim.cars, m.sim.active) if on])
        self._react(m.ev)
        if m.phase == m.OVER and not self.over:
            self._end()

    def _react(self, events) -> None:
        """Sounds, particles, banners and point pop-ups for what just happened."""
        m, now = self.m, time.monotonic()
        for e in events:
            k = e[0]
            if k == "touch":
                sp, kind = e[2], e[3]
                sfx.play("putt" if sp > 1800 else "drop")
                self._sparks(m.sim.ball.x, m.sim.ball.y, min(1.0, sp / 4000.0))
                if sp > 3000:
                    self.shake = max(self.shake, 4.0)
                if kind in ("pinch", "flick"):
                    self.mech_label = (tr("Pinch!") if kind == "pinch" else tr("Drift flick!"), now + 1.2,
                                       AERIAL_TEAM[e[1]]["light"])
            elif k == "pad":
                if e[1] == 0:
                    sfx.play("pick" if e[2] else "drop")
            elif k == "goal":
                team = e[1]
                self._burst(e[4], e[5], team)
                self.shake = 12.0
                own = e[3] < 0
                self.banner = (tr("OWN GOAL") if own else tr("GOAL!"), AERIAL_TEAM[team]["light"], now + 2.0)
                sfx.play("gun")
            elif k == "go":
                sfx.play("gun")
                self.banner = (tr("GO!"), "#35E0A1", now + 0.8)
            elif k == "overtime":
                self.banner = (tr("OVERTIME"), "#F5C04A", now + 2.0)
                sfx.play("beep")
            elif k == "points":
                team, label, pts = e[1], e[2], e[3]
                self.pops.append([tr(label) + ("  +%d" % pts if pts else ""), AERIAL_TEAM[team]["light"], now + 2.2, team])
                self.pops = self.pops[-6:]
                if label in ("Epic Save", "Save", "Hat Trick", "Savior", "Pinch Goal", "Flick Goal"):
                    self.banner = (tr(label).upper() + "!", "#FFFFFF", now + 1.6)
                if team == 0:
                    sfx.play("coin")
        if m.phase == m.COUNT:
            c = m.countdown()
            if c != self.last_count:
                self.last_count = c
                sfx.play("beep")
        else:
            self.last_count = 9

    def _end(self) -> None:
        self.over = True
        m = self.m
        res = m.result() if not self.free else {}
        res["mode"] = self.mode
        res["bot"] = self.bot_key
        self.result = res
        self.unsetCursor()
        self.finished.emit(res)

    def _forfeit(self) -> None:
        """Leaving ranked counts as a loss."""
        if self.over:
            return
        self.over = True
        res = self.m.result()
        res["winner"] = 1
        res["forfeit"] = True
        res["mode"] = self.mode
        res["bot"] = self.bot_key
        self.result = res
        self.finished.emit(res)

    def replay_dict(self) -> dict:
        return {"v": AERIAL_REPLAY_V, "build": BUILD, "seed": self.seed,
                "kinds": [self.m.sim.cars[0].kind, self.m.sim.cars[1].kind], "bot": self.bot_key,
                "bot0": self.bot0_key, "match_s": self.match_s, "in0": self.log0, "in1": self.log1}

    # ---------------------------------------------------------------------------------------- effects
    def _sparks(self, x: float, y: float, k: float) -> None:
        if not self.fx_scale:
            return
        rng = random.Random(int(x * 7 + y * 13))
        for _ in range(int(6 + 14 * k)):
            a = rng.uniform(0, 6.283)
            v = rng.uniform(150, 650) * (0.5 + k)
            self.fx.append([x, y, math.cos(a) * v, math.sin(a) * v, 0.35, 0.35, "#FFFFFF", rng.uniform(5, 11)])

    def _burst(self, x: float, y: float, team: int) -> None:
        """The goal explosion: a shock wave in the scorer's colour and a burst of sparks."""
        self.waves.append([x, y, 0.0, AERIAL_TEAM[team]["glow"]])
        if not self.fx_scale:
            return
        rng = random.Random(int(x) ^ 77)
        col = AERIAL_TEAM[team]
        for _ in range(140):
            a = rng.uniform(0, 6.283)
            v = rng.uniform(300, 2400)
            self.fx.append([x, y, math.cos(a) * v, math.sin(a) * v, 1.3, 1.3, rng.choice([col["main"], col["light"],
                                                                                         "#FFFFFF", "#FFD24A"]),
                            rng.uniform(10, 28)])

    def _effects(self, dt: float) -> None:
        keep = []
        for f in self.fx:
            f[4] -= dt
            if f[4] > 0:
                f[0] += f[2] * dt
                f[1] += f[3] * dt
                f[2] *= 1 - 2.2 * dt
                f[3] *= 1 - 2.2 * dt
                keep.append(f)
        self.fx = keep[-500:]
        for wv in self.waves:
            wv[2] += dt
        self.waves = [wv for wv in self.waves if wv[2] < 1.0]
        self.shake = max(0.0, self.shake - dt * 25)
        self.painter.fade_skids(dt)
        b = self.m.sim.ball
        tr_ = self.painter.trail
        tr_.append((b.x, b.y, math.hypot(b.vx, b.vy)))
        del tr_[:-10]
        now = time.monotonic()
        self.pops = [p for p in self.pops if p[2] > now]

    # ---------------------------------------------------------------------------------------- drawing
    def _replay_frame(self):
        """During a goal replay: the snapshot to show. The last second is in slow motion."""
        m = self.m
        if m.phase != m.REPLAY or m.last_goal is None or not self.ring:
            return None
        g_tick = m.last_goal[0]
        span = int(AERIAL_TUNE["replay_s"] * AERIAL_HZ)
        u = min(1.0, m.phase_t / AERIAL_TUNE["replay_s"])
        f = u / 0.7 * 0.85 if u < 0.7 else 0.85 + (u - 0.7) / 0.3 * 0.15     # slow motion at the end
        want = g_tick - span + int(f * span) + 10
        best = None
        for tk, snap in self.ring:
            if tk >= want:
                best = snap
                break
            best = snap
        return best

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w, h = self.width(), self.height()
        m = self.m
        top = S(64)
        if self.cam is None:
            self.cam = AerialCam(m.sim.arena, w, h, top)
        elif self.cam.w != w or self.cam.h != h:
            self.cam.set(m.sim.arena, w, h, top)
        cam = self.cam
        live_snap = None
        rf = self._replay_frame()
        if rf is not None:
            live_snap = m.snapshot()
            m.restore(rf)
        try:
            sx = sy = 0.0
            if self.shake > 0 and self.fx_scale:
                sx = math.sin(time.monotonic() * 91) * self.shake
                sy = math.cos(time.monotonic() * 77) * self.shake
            p.translate(sx, sy)
            p.drawPixmap(0, 0, self.painter.background(cam, m.sim.arena, QSizeF(w, h)))
            sim = m.sim
            now = time.monotonic() - self.t0
            self.painter.pads(p, cam, sim, now)
            self.painter.draw_skids(p, cam)
            if rf is not None:                       # a replay: a red frame round the pitch
                p.setPen(QPen(alpha("#FF2E63", 0.55), S(3)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawPath(self.painter._arena_path(cam, m.sim.arena))
            if not (m.phase == m.GOAL and sim.ball_held) and not self.hide_ball:
                self.painter.ball(p, cam, sim.ball, AERIAL_TUNE["ball_r"])
            for i, c in enumerate(sim.cars):
                if not sim.active[i]:
                    continue
                self.painter.car(p, cam, c, c.kind, c.team, c.boosting, now, ring=(i == 0 and m.phase == m.COUNT))
                if self.hitbox:
                    self._hitbox(p, cam, c)
            for wv in self.waves:                    # goal shock waves
                q = aerial_cam_point(cam, wv[0], wv[1])
                rr = cam.s(200 + 2400 * wv[2])
                p.setPen(QPen(alpha(wv[3], 0.85 * (1.0 - wv[2])), S(6) * (1.0 - wv[2]) + 1))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawEllipse(q, rr, rr)
                p.setPen(QPen(alpha("#FFFFFF", 0.6 * (1.0 - wv[2])), S(2)))
                p.drawEllipse(q, rr * 0.7, rr * 0.7)
            for f in self.fx:
                q = aerial_cam_point(cam, f[0], f[1])
                a = max(0.0, f[4] / f[5])
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha(f[6], a))
                r = cam.s(f[7]) * (0.4 + 0.6 * a)
                p.drawEllipse(q, r, r)
            me = sim.cars[0]
            p.translate(-sx, -sy)
            self._hud(p, w, h, top, me, rf is not None)
        finally:
            if live_snap is not None:
                m.restore(live_snap)

    def _scoreboard(self, p, w, h) -> None:
        """Tab: both players' points and stats."""
        m = self.m
        cols = [("score", tr("Score")), ("goals", tr("Goals")), ("saves", tr("Saves")), ("epic", tr("Epic saves")),
                ("shots", tr("Shots")), ("touches", tr("Touches")), ("pinches", tr("Pinches")), ("flicks", tr("Flicks"))]
        bw, rh = min(w - S(60), S(800)), S(40)
        r = QRectF(w / 2 - bw / 2, h / 2 - S(80), bw, S(44) + 2 * rh + S(16))
        p.setPen(QPen(alpha("#FFFFFF", 0.12), 1))
        p.setBrush(QColor(10, 12, 18, 235))
        p.drawRoundedRect(r, S(16), S(16))
        name_w = S(190)
        cw = (bw - name_w - S(20)) / len(cols)
        p.setFont(font(9.5, QFont.Weight.Black, 1))
        p.setPen(QColor(TEXT_DIM))
        for i, (_k, label) in enumerate(cols):
            p.drawText(QRectF(r.left() + name_w + i * cw, r.top() + S(12), cw, S(20)), int(Qt.AlignmentFlag.AlignCenter),
                       label.upper())
        for team in (0, 1):
            y = r.top() + S(44) + team * rh
            row = QRectF(r.left() + S(8), y, bw - S(16), rh - S(4))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(alpha(AERIAL_TEAM[team]["main"], 0.28))
            p.drawRoundedRect(row, S(10), S(10))
            name = self._me_name() if team == 0 else ((AERIAL_BOTS[self.bot_key]["name"] + " · " + tr("BOT"))
                                                      if self.bot_key else "")
            p.setFont(font(12, QFont.Weight.Black))
            p.setPen(QColor("#FFFFFF"))
            p.drawText(QRectF(r.left() + S(22), y, name_w, rh - S(4)), int(Qt.AlignmentFlag.AlignVCenter), name)
            st = m.sim.cars[team].stats
            for i, (k, _l) in enumerate(cols):
                p.drawText(QRectF(r.left() + name_w + i * cw, y, cw, rh - S(4)), int(Qt.AlignmentFlag.AlignCenter),
                           str(int(st.get(k, 0))))

    def _hitbox(self, p, cam, c) -> None:
        p.setPen(QPen(alpha("#00FF88", 0.9), 1.5))
        p.setBrush(Qt.BrushStyle.NoBrush)
        k = cam.k * cam.zoom
        p.save()
        p.translate(aerial_cam_point(cam, c.x, c.y))
        p.rotate(math.degrees(math.atan2(c.fy, c.fx)))
        p.drawRoundedRect(QRectF(-(c.hl + c.r) * k, -c.r * k, 2 * (c.hl + c.r) * k, 2 * c.r * k), c.r * k, c.r * k)
        p.restore()

    def _hud(self, p, w, h, top, me, replay: bool) -> None:
        m = self.m
        now = time.monotonic()
        if not self.free:
            bw = S(330)
            r = QRectF(w / 2 - bw / 2, S(8), bw, S(46))
            paint_surface(p, r, S(14), 0.07)
            for team in (0, 1):
                tr_ = QRectF(r.left() + (bw - S(72)) * team, r.top(), S(72), r.height())
                p.setPen(Qt.PenStyle.NoPen)
                p.setBrush(alpha(AERIAL_TEAM[team]["main"], 0.85))
                p.drawRoundedRect(tr_.adjusted(S(4), S(4), -S(4), -S(4)), S(10), S(10))
                p.setPen(QColor("#FFFFFF"))
                p.setFont(font(22, QFont.Weight.Black))
                p.drawText(tr_, int(Qt.AlignmentFlag.AlignCenter), str(m.score[team]))
            if m.overtime:
                txt = "+%d:%02d" % (int(m.ot_t) // 60, int(m.ot_t) % 60)
            else:
                cs = int(math.ceil(m.clock))
                txt = "%d:%02d" % (cs // 60, cs % 60)
            p.setFont(font(20, QFont.Weight.Black))
            p.setPen(QColor("#F5C04A") if m.overtime else QColor("#FFFFFF"))
            p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), txt)
            p.setFont(font(10, QFont.Weight.Bold))
            p.setPen(QColor(TEXT_DIM))
            name0 = self._me_name()
            name1 = AERIAL_BOTS[self.bot_key]["name"] + " · " + tr("BOT") if self.bot_key else ""
            p.drawText(QRectF(r.left() - S(170), r.top(), S(160), r.height()),
                       int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight), name0)
            p.drawText(QRectF(r.right() + S(10), r.top(), S(220), r.height()),
                       int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft), name1)
        # the boost meter: big, bottom right, the number in the middle
        rad = S(40)
        cx, cy = w - S(70), h - S(70)
        self.painter.boost_meter(p, cx, cy, rad, me.boost, 0, me.boosting)
        p.setPen(QColor("#FFFFFF"))
        p.setFont(font(22, QFont.Weight.Black))
        p.drawText(QRectF(cx - rad, cy - rad - S(4), 2 * rad, 2 * rad), int(Qt.AlignmentFlag.AlignCenter),
                   "∞" if (self.free and self.inf_boost) else str(int(me.boost)))
        p.setFont(font(8.5, QFont.Weight.Black, 2))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(cx - rad, cy + S(10), 2 * rad, S(16)), int(Qt.AlignmentFlag.AlignCenter), tr("BOOST"))
        if me.drifting:
            p.setFont(font(10, QFont.Weight.Black, 1.5))
            p.setPen(QColor("#FFD24A"))
            p.drawText(QRectF(cx - S(80), cy - rad - S(40), S(160), S(20)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("POWERSLIDE"))
        if m.phase == m.COUNT and self.bot_key and not getattr(self, "intro_done", False) and self.rep_in is None:
            self._intro(p, w, h, m.phase_t)
        elif m.phase == m.LIVE:
            self.intro_done = True
        if m.phase == m.COUNT:
            c = m.countdown()
            k = 1.0 - ((m.phase_t % 1.0))
            p.setFont(font(110 * (0.8 + 0.3 * k), QFont.Weight.Black))
            p.setPen(alpha("#FFFFFF", 0.4 + 0.6 * k))
            p.drawText(QRectF(0, 0, w, h), int(Qt.AlignmentFlag.AlignCenter), str(c))
        if replay:
            p.setFont(font(13, QFont.Weight.Black, 3))
            r = QRectF(S(16), top, S(150), S(30))
            p.setPen(Qt.PenStyle.NoPen)
            p.setBrush(QColor("#FF2E63"))
            p.drawRoundedRect(r, S(8), S(8))
            p.setPen(QColor("#FFFFFF"))
            p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), tr("REPLAY"))
            lg = m.last_goal
            if lg is not None:
                p.setFont(font(12, QFont.Weight.Bold))
                who = self._me_name() if lg[3] == 0 else (AERIAL_BOTS[self.bot_key]["name"] if lg[3] == 1 and self.bot_key else tr("Own goal"))
                p.drawText(QRectF(S(16), top + S(36), S(400), S(22)), int(Qt.AlignmentFlag.AlignLeft),
                           "%s · %d km/h" % (who, int(lg[2] * 0.036)))
            p.setFont(font(11, QFont.Weight.DemiBold))
            p.setPen(QColor(TEXT_DIM))
            p.drawText(QRectF(0, h - S(34), w, S(24)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Space to skip the replay"))
        if self.banner and self.banner[2] > now and not replay:
            text, col, until = self.banner
            k = min(1.0, (until - now) / 0.3)
            p.setFont(font(54, QFont.Weight.Black, 2))
            p.setPen(alpha(col, k))
            p.drawText(QRectF(0, h * 0.28, w, S(80)), int(Qt.AlignmentFlag.AlignCenter), text)
        y0 = {0: top + S(10), 1: top + S(10)}
        for text, col, until, team in self.pops:
            a = min(1.0, (until - now) / 0.4)
            p.setFont(font(13, QFont.Weight.Black))
            p.setPen(alpha(col, a))
            r = QRectF(S(16) if team == 0 else w - S(316), y0[team] + (S(70) if replay and team == 0 else 0), S(300), S(22))
            p.drawText(r, int(Qt.AlignmentFlag.AlignLeft if team == 0 else Qt.AlignmentFlag.AlignRight), text)
            y0[team] += S(24)
        if self.mech_label and self.mech_label[1] > now:
            p.setFont(font(16, QFont.Weight.Black))
            p.setPen(QColor(self.mech_label[2] if len(self.mech_label) > 2 else "#35E0A1"))
            p.drawText(QRectF(0, h - S(110), w, S(30)), int(Qt.AlignmentFlag.AlignCenter), self.mech_label[0])
        if self.free:
            p.setFont(font(10.5, QFont.Weight.DemiBold))
            p.setPen(QColor(TEXT_DIM))
            tips = tr("R reset · T ball in front · B infinite boost: {b} · G slow motion: {s} · H hitbox",
                      b=tr("on") if self.inf_boost else tr("off"), s=tr("on") if self.slow else tr("off"))
            p.drawText(QRectF(S(16), S(12), w - S(32), S(22)), int(Qt.AlignmentFlag.AlignLeft), tips)
        if self.tab_down and not self.free:
            self._scoreboard(p, w, h)
        if self.menu_open:
            p.fillRect(QRectF(0, 0, w, h), alpha("#000000", 0.55))
            p.setFont(font(26, QFont.Weight.Black))
            p.setPen(QColor("#FFFFFF"))
            p.drawText(QRectF(0, h / 2 - S(150), w, S(40)), int(Qt.AlignmentFlag.AlignCenter),
                       tr("Paused") if self.paused else tr("The match goes on"))
            for k, label, r in self.menu_rects():
                hov = self.mouse is not None and r.contains(self.mouse)
                paint_surface(p, r, S(12), 0.08, 1.0 if hov else 0.0,
                              tint=QColor("#FF6B78") if k == "leave" else None, tint_a=0.3 if k == "leave" else 0.0)
                p.setFont(font(13, QFont.Weight.Bold))
                p.setPen(QColor("#FFFFFF"))
                p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), label)


class AerialResults(QWidget):
    """After the final whistle: the score, both players' points and stats, the MVP, and (ranked) the MMR change."""

    def __init__(self, res: dict, ladder_out: dict, bot_key: str, width: int) -> None:
        super().__init__()
        self.res, self.lo, self.bot_key = res, ladder_out, bot_key
        self.setFixedSize(min(width, S(640)), S(418 if ladder_out else 358))
        self.t0 = time.monotonic()
        self._t = QTimer(self)                       # the emblem is forged on a promotion (rays, a flash, a pop)
        self._t.setInterval(30)
        self._t.timeout.connect(self._anim)
        if ladder_out and (ladder_out.get("promoted") or ladder_out.get("series")):
            self._t.start()

    def _anim(self) -> None:
        if time.monotonic() - self.t0 > 4.0:
            self._t.stop()
        self.update()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r, w = self.res, self.width()
        won = r.get("winner") == 0
        p.setFont(font(30, QFont.Weight.Black))
        p.setPen(QColor("#3BE38A") if won else QColor("#FF6B78"))
        title = tr("Victory") if won else (tr("Forfeit") if r.get("forfeit") else tr("Defeat"))
        if r.get("overtime"):
            title += "  ·  " + tr("overtime")
        p.drawText(QRectF(0, 0, w, S(42)), int(Qt.AlignmentFlag.AlignVCenter), title)
        sc = r.get("score", [0, 0])
        p.setFont(font(30, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(QRectF(0, 0, w, S(42)), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                   "%d - %d" % (sc[0], sc[1]))
        st = r.get("stats", [{}, {}])
        rows = [("score", tr("Score")), ("goals", tr("Goals")), ("shots", tr("Shots")), ("saves", tr("Saves")),
                ("epic", tr("Epic saves")), ("clears", tr("Clears")), ("touches", tr("Touches")),
                ("pinches", tr("Pinches")), ("flicks", tr("Flicks"))]
        y = S(56)
        col_w = (w - S(160)) / 2
        p.setFont(font(11, QFont.Weight.Black, 1))
        mvp = 0 if st[0].get("score", 0) >= st[1].get("score", 0) else 1
        for team in (0, 1):
            p.setPen(QColor(AERIAL_TEAM[team]["light"]))
            name = self._me_name() if team == 0 else (AERIAL_BOTS[self.bot_key]["name"] if self.bot_key else "")
            if team == mvp and r.get("winner") == team:
                name += "  ★ MVP"
            p.drawText(QRectF(S(160) + team * col_w, y, col_w, S(20)), int(Qt.AlignmentFlag.AlignCenter), name)
        y += S(26)
        for key, label in rows:
            p.setPen(QPen(alpha("#FFFFFF", 0.06), 1))
            p.drawLine(QPointF(0, y + S(26)), QPointF(w, y + S(26)))
            p.setFont(font(12, QFont.Weight.DemiBold))
            p.setPen(QColor(TEXT_DIM))
            p.drawText(QRectF(0, y, S(150), S(26)), int(Qt.AlignmentFlag.AlignVCenter), label)
            p.setFont(font(13, QFont.Weight.Black))
            p.setPen(QColor("#FFFFFF"))
            for team in (0, 1):
                p.drawText(QRectF(S(160) + team * col_w, y, col_w, S(26)), int(Qt.AlignmentFlag.AlignCenter),
                           str(int(st[team].get(key, 0))))
            y += S(27)
        lo = self.lo
        if lo:
            y += S(8)
            d = lo.get("delta", 0)
            info = aerial_rank(lo["after"])
            age = time.monotonic() - self.t0
            if lo.get("promoted") and age < 4.0 and getattr(ui, "motion", 1.0) > 0.01:
                c = QPointF(S(28), y + S(28))
                k = min(1.0, age / 0.6)
                for i in range(12):                  # rays
                    a = i * math.pi / 6 + age * 0.8
                    p.setPen(QPen(alpha(info["colour"], 0.5 * (1 - age / 4.0)), S(3)))
                    p.drawLine(c, QPointF(c.x() + math.cos(a) * S(60) * k, c.y() + math.sin(a) * S(60) * k))
                sz = S(56) * (0.4 + 0.6 * k + 0.08 * math.sin(min(age, 1.2) * 9) * (1 - min(1.0, age)))
                aerial_draw_emblem(p, QRectF(c.x() - sz / 2, c.y() - sz / 2, sz, sz), info["rank"], info["tier"],
                                   info["div"], time.monotonic())
            else:
                aerial_draw_emblem(p, QRectF(0, y, S(56), S(56)), info["rank"], info["tier"], info["div"],
                                   time.monotonic())
            p.setFont(font(14, QFont.Weight.Black))
            p.setPen(QColor(info["colour"]))
            p.drawText(QRectF(S(66), y + S(2), w, S(22)), int(Qt.AlignmentFlag.AlignLeft),
                       aerial_rank_label(info["index"]) + "   ·   %d MMR (%+d)" % (info["mmr"], d))
            p.setFont(font(12, QFont.Weight.Bold))
            if lo.get("promoted"):
                p.setPen(QColor("#3BE38A"))
                txt = tr("Promoted to {r}!", r=aerial_rank_label(info["index"]))
            elif lo.get("demoted"):
                p.setPen(QColor("#FF6B78"))
                txt = tr("Down to {r}", r=aerial_rank_label(info["index"]))
            else:
                p.setPen(QColor(TEXT_DIM))
                txt = aerial_progress_text(info)
            p.drawText(QRectF(S(66), y + S(26), w, S(20)), int(Qt.AlignmentFlag.AlignLeft), txt)
            aerial_draw_progress(p, QRectF(S(66), y + S(50), min(S(300), w - S(70)), S(10)), info["v"], info["colour"])


def aerial_rank_label(i: int) -> str:
    fam, tier = AERIAL_RANKS[i]
    return tr(AERIAL_FAMILIES[fam][0]) + (" %d" % tier if tier else "")


def aerial_progress_text(info: dict) -> str:
    i, v = info["index"], info["v"]
    if i == 9:
        return tr("The top. {n} more losses than wins and you drop.", n=AERIAL_STEP + v)
    up = tr("{n} wins to {r}", n=AERIAL_STEP - v, r=aerial_rank_label(i + 1))
    if i == 0:
        return up
    return up + "  ·  " + tr("{n} losses to drop", n=AERIAL_STEP + v)


def aerial_draw_progress(p: QPainter, r: QRectF, v: int, colour: str) -> None:
    """The rank bar: five cells down (red) and five up (the rank's colour) from the middle; filled up to where you
    are."""
    n = 2 * AERIAL_STEP
    gap = S(3)
    cw = (r.width() - gap * (n - 1)) / n
    for k in range(n):
        x = r.left() + k * (cw + gap)
        pos = k - AERIAL_STEP                      # -5 .. 4: the cell for step pos..pos+1
        on = (v > 0 and 0 <= pos < v) or (v < 0 and v <= pos < 0)
        c = QColor(colour) if pos >= 0 else QColor("#FF6B78")
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(c if on else alpha(c, 0.16))
        p.drawRoundedRect(QRectF(x, r.top(), cw, r.height()), r.height() / 2, r.height() / 2)
    p.setPen(QPen(alpha("#FFFFFF", 0.7), S(2)))
    mx = r.left() + AERIAL_STEP * (cw + gap) - gap / 2
    p.drawLine(QPointF(mx, r.top() - S(3)), QPointF(mx, r.bottom() + S(3)))


class AerialStage(QWidget):
    """Rubenium League in the online menu (as Karting does): the menu widens, the match fades in over it, and when you
    leave it fades out. The menu takes the keyboard while the match is on."""

    def __init__(self, ctx, cfg: dict) -> None:
        self.host = ctx.window
        super().__init__(self.host)
        self.ctx, self.cfg = ctx, dict(cfg)
        self.hide()
        self.lay = vbox(self, 0)
        bar = QWidget()
        bar.setFixedHeight(S(44))
        bl = hbox(bar, 8, (S(14), 0, S(10), 0))
        titles = {"free": tr("Free Play"), "practice": tr("Practice"), "private": tr("Private match"),
                  "ranked": tr("Ranked"), "replay": tr("Replay"), "watch": tr("Bot against bot")}
        self.title = Label(AERIAL_NAME + "  ·  " + titles.get(cfg.get("mode"), ""), 13, TEXT, bold=True)
        bl.addWidget(self.title, 1)
        self.sound = Button(tr("Sound on") if sfx.enabled else tr("Sound off"), "ghost", 30)
        self.sound.clicked.connect(self._sound)
        bl.addWidget(self.sound)
        self.leave_b = Button(tr("Leave"), "ghost", 30)
        self.leave_b.clicked.connect(self.ask_leave)
        bl.addWidget(self.leave_b)
        self.lay.addWidget(bar)
        self.body = QWidget()
        self.body_lay = vbox(self.body, 0)
        self.lay.addWidget(self.body, 1)
        self.view = AerialView(ctx, cfg)
        self.view.finished.connect(self._finished)
        self.view.leave.connect(self.close_stage)
        self.view.again.connect(self._again)
        self.body_lay.addWidget(self.view, 1)
        self.over = None
        self.closing = False
        self.fade = Tween(self, 0.0, self._fade_step, QEasingCurve.Type.OutCubic)
        self.fade.finished.connect(self._fade_done)
        self._fx = None

    @staticmethod
    def start(ctx, cfg: dict) -> None:
        old = getattr(ctx, "aerial_stage", None)
        if old is not None:
            return
        if not hasattr(getattr(ctx, "window", None), "_wide_watch"):
            return ctx.toast(tr("Rubenium League plays in the online menu"), "warn")
        if not aerial_enabled(ctx):
            return ctx.toast(tr("Rubenium League is switched off for now"), "warn")
        if cfg.get("mode") in ("practice", "private", "watch") and not aerial_can_play(ctx, cfg.get("bot")):
            return ctx.toast(tr("Beat the bots in order: you can play up to one rank above yours"), "warn")
        if cfg.get("mode") == "watch" and not aerial_is_admin(ctx):
            return
        try:
            st = AerialStage(ctx, cfg)
        except Exception:  # noqa: BLE001
            log.exception("Rubenium League could not start")
            return ctx.toast(tr("Rubenium League could not start"), "error")
        ctx.aerial_stage = st
        st.open()

    def open(self) -> None:
        h, ctx = self.host, self.ctx
        ctx.aerial_wide = True
        try:
            if getattr(h, "phase", "shown") == "stowed":
                h.expand()
            h.allow_keys(True)
            if hasattr(h, "_wide_watch"):
                h._wide_watch()
        except (RuntimeError, AttributeError):
            pass
        self.place()
        QTimer.singleShot(int(560 * max(0.2, getattr(ui, "motion", 1.0))), self._fade_in)

    def _fade_in(self) -> None:
        if self.closing:
            return
        self.place()
        self._set_fx(0.0)
        self.show()
        self.raise_()
        self.fade.to(1.0, 380)
        self.focus()

    def focus(self) -> None:
        try:
            self.host.raise_()
            self.host.activateWindow()
        except RuntimeError:
            pass
        self.view.setFocus()

    def place(self) -> None:
        try:
            self.setGeometry(self.host.body.geometry())
        except (RuntimeError, AttributeError):
            pass

    def _fade_step(self) -> None:
        if self._fx is not None:
            try:
                self._fx.setOpacity(max(0.0, min(1.0, self.fade.level)))
            except RuntimeError:
                self._fx = None

    def _set_fx(self, v: float) -> None:
        from PyQt6.QtWidgets import QGraphicsOpacityEffect
        self._fx = QGraphicsOpacityEffect(self)
        self._fx.setOpacity(v)
        self.setGraphicsEffect(self._fx)

    def _fade_done(self) -> None:
        if not self.closing:
            self._fx = None
            self.setGraphicsEffect(None)
            self.focus()
            return
        ctx, h = self.ctx, self.host
        ctx.aerial_wide = False
        ctx.aerial_stage = None
        try:
            h.allow_keys(False)
            if hasattr(h, "_wide_watch"):
                h._wide_watch()
            if h.showing("games") and getattr(ctx, "games_sub", None) == "aerial":
                ctx.reload_page("games")
        except (RuntimeError, AttributeError):
            pass
        self.hide()
        self.deleteLater()

    def close_stage(self) -> None:
        if self.closing:
            return
        self.closing = True
        self.view.timer.stop()
        if self.isVisible():
            self._set_fx(self.fade.level)
            self.fade.to(0.0, 300)
        else:
            self._fade_done()

    def ask_leave(self) -> None:
        v = self.view
        if v.mode == "ranked" and not v.over:
            def go() -> None:
                v._forfeit()
                self.close_stage()
            try:
                self.host.confirm(tr("Leave this ranked match? It counts as a loss."), go, yes=tr("Leave"))
                self.host.confirm_w.raise_()
            except Exception:  # noqa: BLE001
                go()
            return
        self.close_stage()

    def _sound(self) -> None:
        sfx.enabled = not sfx.enabled
        try:
            self.ctx.cfg["sounds"] = sfx.enabled
        except Exception:  # noqa: BLE001
            pass
        self.sound.set_text(tr("Sound on") if sfx.enabled else tr("Sound off"))
        self.focus()

    def _finished(self, res: dict) -> None:
        """Save the match (history, replay, ranked MMR) and show the results over the pitch."""
        v = self.view
        store = aerial_store(self.ctx)
        store.data.pop("open_ranked", None)
        lo = None
        if v.mode in ("ranked", "practice", "private") and res.get("stats"):
            won = res.get("winner") == 0
            if v.mode == "ranked":
                opp = AERIAL_BOTS[v.bot_key]["mmr"] if v.bot_key else 0
                lo = store.ladder.result(opp, won)
            st = res["stats"][0]
            row = {"t": int(time.time()), "mode": v.mode, "bot": v.bot_key, "car": v.m.sim.cars[0].kind,
                   "score": res.get("score"), "won": won, "ot": bool(res.get("overtime")), "forfeit": bool(res.get("forfeit")),
                   "pts": st.get("score", 0), "goals": st.get("goals", 0), "saves": st.get("saves", 0),
                   "epic": st.get("epic", 0), "touches": st.get("touches", 0), "shots": st.get("shots", 0),
                   "pinches": st.get("pinches", 0), "flicks": st.get("flicks", 0), "mmr": int(store.ladder.mmr),
                   "delta": (lo or {}).get("delta", 0), "secs": int(v.m.sim.tick / AERIAL_HZ)}
            store.add_match(row, v.replay_dict() if not res.get("forfeit") else None)
            if lo and lo.get("promoted"):
                sfx.play("coin")
        if res.get("forfeit"):
            return
        if v.mode == "replay":
            return QTimer.singleShot(400, self.close_stage)
        card = QWidget()
        cl = vbox(card, 12, (S(24), S(20), S(24), S(20)))
        cl.addWidget(AerialResults(res, lo, v.bot_key, self.width() - S(80)))
        btns = hbox(spacing=8)
        back = Button(tr("Back to the lobby"), "ghost", 42)
        back.clicked.connect(self.close_stage)
        again = Button(tr("Play again"), "primary", 42, icon="play")
        again.clicked.connect(self._again)
        btns.addWidget(back, 1)
        btns.addWidget(again, 1)
        cl.addLayout(btns)
        self.over = AerialOverlayCard(self.body, card)
        self.over.setGeometry(self.body.rect())
        self.over.show()

    def _again(self) -> None:
        ctx, cfg = self.ctx, dict(self.cfg)
        cfg.pop("seed", None)
        if cfg.get("mode") == "ranked":
            if aerial_ranked_closed(ctx):
                self.close_stage()
                return ctx.toast(tr("Ranked is closed for now while we fix something. Practice and Free Play stay "
                                    "open."), "warn")
            st = aerial_store(ctx)
            cfg["bot"] = aerial_pick_ranked(st)
        self.close_stage()
        QTimer.singleShot(420, lambda: AerialStage.start(ctx, cfg))

    def resizeEvent(self, e) -> None:
        super().resizeEvent(e)
        if self.over is not None:
            self.over.setGeometry(self.body.rect())

    def keyPressEvent(self, e) -> None:
        if e.key() == Qt.Key.Key_Escape and self.over is not None:
            return self.close_stage()
        super().keyPressEvent(e)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        path = QPainterPath()
        path.addRoundedRect(QRectF(self.rect()), S(ui.radius), S(ui.radius))
        p.setClipPath(path)
        p.fillRect(self.rect(), QColor(8, 10, 16))
        p.setPen(QPen(alpha("#FF2E63", 0.4), 1))
        p.drawLine(QPointF(0, S(44) - 0.5), QPointF(self.width(), S(44) - 0.5))


class AerialOverlayCard(QWidget):
    """A card in the middle of a dimmed match (the match keeps drawing behind it)."""

    def __init__(self, parent, card: QWidget) -> None:
        super().__init__(parent)
        lay = vbox(self, 0)
        lay.addStretch(1)
        row = hbox(spacing=0)
        row.addStretch(1)
        row.addWidget(card)
        row.addStretch(1)
        lay.addLayout(row)
        lay.addStretch(1)
        self.card = card

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        p.fillRect(self.rect(), QColor(0, 0, 0, 140))
        r = QRectF(self.card.geometry()).adjusted(-2, -2, 2, 2)
        p.setPen(QPen(alpha("#FFFFFF", 0.12), 1))
        p.setBrush(QColor(14, 16, 22, 248))
        p.drawRoundedRect(r, S(20), S(20))


def aerial_is_admin(ctx) -> bool:
    econ = getattr(ctx, "econ", None)
    return bool(econ is not None and getattr(econ, "admin", False))


def aerial_bot_index(key: str) -> int:
    for i, r in enumerate(AERIAL_BOT_ROSTER):
        if r[0] == key:
            return i
    return 0


def aerial_can_play(ctx, key) -> bool:
    """Practice: any bot up to one rank above yours (admins: every bot)."""
    if key not in AERIAL_BOTS:
        return False
    if aerial_is_admin(ctx):
        return True
    return aerial_bot_index(key) <= aerial_store(ctx).ladder.r + 1


def aerial_pick_ranked(store: AerialStore) -> str:
    """Ranked is always against the bot of my rank."""
    opts = store.ladder.opponents()
    return opts[random.randrange(len(opts))]


# SECTION: aerial (lobby and tracker)
# The Rubenium League pages in Play: the banner that opens it, the lobby (rank, cars, ranked, practice, Free Play),
# the tracker (stats, MMR over time, match history, the last 10 replays) and the ladder.


class AerialBanner(QWidget):
    """The big Rubenium League tile at the top of Play: a pitch at night, a car flying at the ball, your rank."""

    def __init__(self, ctx, on_click) -> None:
        super().__init__()
        self.ctx, self.on_click = ctx, on_click
        self.setFixedHeight(S(132))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._hover = Tween(self, on_change=self.update)
        self._t = QTimer(self)
        self._t.setInterval(40)
        self._t.timeout.connect(self.update)
        self._car = AerialCar(0, 0)

    def showEvent(self, _e) -> None:
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def enterEvent(self, _e) -> None:
        self._hover.to(1.0, 160)

    def leaveEvent(self, _e) -> None:
        self._hover.to(0.0, 240)

    def mouseReleaseEvent(self, e) -> None:
        if e.button() == Qt.MouseButton.LeftButton and self.rect().contains(e.position().toPoint()):
            sfx.play("pick")
            self.on_click()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        hv = self._hover.level
        t = time.monotonic()
        path = QPainterPath()
        path.addRoundedRect(r, S(18), S(18))
        p.save()
        p.setClipPath(path)
        g = QLinearGradient(r.topLeft(), r.bottomRight())
        g.setColorAt(0, QColor("#0C1430"))
        g.setColorAt(0.55, QColor("#1A1240"))
        g.setColorAt(1, QColor("#3A0F28"))
        p.fillRect(r, QBrush(g))
        for i in range(7):                                   # light beams
            x = r.left() + r.width() * (i / 6.0) + math.sin(t * 0.4 + i) * S(20)
            bg = QLinearGradient(QPointF(x, r.top()), QPointF(x, r.bottom()))
            bg.setColorAt(0, alpha("#FFFFFF", 0.06 + 0.04 * hv))
            bg.setColorAt(1, alpha("#FFFFFF", 0.0))
            beam = QPainterPath()
            beam.moveTo(x - S(8), r.top())
            beam.lineTo(x + S(8), r.top())
            beam.lineTo(x + S(60), r.bottom())
            beam.lineTo(x - S(60), r.bottom())
            p.fillPath(beam, QBrush(bg))
        p.fillRect(QRectF(r.left(), r.bottom() - S(18), r.width(), S(18)), alpha("#000000", 0.35))
        # a little pitch from above: a car carrying the ball toward goal, the boost flame on
        pr = QRectF(r.right() - S(250), r.top() + S(16), S(230), r.height() - S(32))
        p.setPen(QPen(alpha("#9FB4FF", 0.35), S(1.5)))
        p.setBrush(alpha("#0E1A22", 0.65))
        p.drawRoundedRect(pr, S(14), S(14))
        p.setPen(QPen(alpha("#FFFFFF", 0.18), S(1.2)))
        p.drawLine(QPointF(pr.center().x(), pr.top()), QPointF(pr.center().x(), pr.bottom()))
        p.drawEllipse(pr.center(), S(18), S(18))
        for side, col in ((-1, "#2E8BFF"), (1, "#FF8A1F")):
            gx = pr.left() if side < 0 else pr.right()
            p.setPen(QPen(QColor(col), S(3)))
            p.drawLine(QPointF(gx, pr.center().y() - S(16)), QPointF(gx, pr.center().y() + S(16)))
        u = (t * 0.18) % 1.0
        cx = pr.left() + S(30) + (pr.width() - S(70)) * u
        cy = pr.center().y() + math.sin(t * 2.0) * S(18) * (1 - u)
        ang = math.atan2(math.cos(t * 2.0) * S(36) * (1 - u) * 0.18, (pr.width() - S(70)) * 0.18)
        cam = _AeBannerCam(S(1) * 0.16, cx, cy)
        c = self._car
        c.x, c.y, c.fx, c.fy = 0.0, 0.0, math.cos(ang), math.sin(ang)
        AerialPainter().car(p, cam, c, int(t / 3) % 3, 0, True, t)
        bx = cx + math.cos(ang) * S(26)
        by = cy + math.sin(ang) * S(26)
        bgr = QRadialGradient(QPointF(bx - S(2), by - S(2)), S(9))
        bgr.setColorAt(0, QColor("#FFFFFF"))
        bgr.setColorAt(1, QColor("#8D96A8"))
        p.setPen(QPen(QColor("#20242E"), 1))
        p.setBrush(bgr)
        p.drawEllipse(QPointF(bx, by), S(8), S(8))
        p.restore()
        p.setPen(QPen(alpha("#FF2E63", 0.35 + 0.4 * hv), 1.5))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawRoundedRect(r, S(18), S(18))
        p.setFont(font(24, QFont.Weight.Black, 1.5))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(QRectF(r.left() + S(20), r.top() + S(18), r.width(), S(34)), int(Qt.AlignmentFlag.AlignLeft),
                   AERIAL_NAME.upper())
        p.setFont(font(11.5, QFont.Weight.DemiBold))
        p.setPen(alpha("#FFFFFF", 0.75))
        p.drawText(QRectF(r.left() + S(20), r.top() + S(54), r.width() - S(200), S(20)), int(Qt.AlignmentFlag.AlignLeft),
                   tr("1 v 1 top-down car soccer · 10 ranks · 10 bots to beat"))
        info = aerial_rank(aerial_store(self.ctx).ladder.mmr)
        aerial_draw_emblem(p, QRectF(r.left() + S(18), r.bottom() - S(52), S(40), S(40)), info["rank"], info["tier"],
                           0, t, glow=False)
        p.setFont(font(12, QFont.Weight.Black))
        p.setPen(QColor(info["colour"]))
        p.drawText(QRectF(r.left() + S(64), r.bottom() - S(46), S(260), S(20)), int(Qt.AlignmentFlag.AlignLeft),
                   aerial_rank_label(info["index"]) + "   ·   %d MMR" % info["mmr"])
        p.setFont(font(12, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(QRectF(r.right() - S(140), r.bottom() - S(44), S(120), S(24)),
                   int(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter), tr("PLAY") + "  ›")


class _AeBannerCam:
    """A tiny camera for drawing one car on a tile."""

    def __init__(self, k: float, ox: float, oy: float) -> None:
        self.k, self.zoom, self.ox, self.oyc, self.cx, self.cy = k, 1.0, ox, oy, 0.0, 0.0

    def s(self, v: float) -> float:
        return v * self.k


class AerialCarCard(QWidget):
    """One of the three cars: drawn from above with its hitbox, its name and what it is good at."""

    def __init__(self, kind: int, picked: bool, on_pick, width: int) -> None:
        super().__init__()
        self.kind, self.picked, self.on_pick = kind, picked, on_pick
        self.setFixedSize(width, S(118))
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self._hover = Tween(self, on_change=self.update)
        self._car = AerialCar(0, kind)

    def enterEvent(self, _e) -> None:
        self._hover.to(1.0, 140)

    def leaveEvent(self, _e) -> None:
        self._hover.to(0.0, 220)

    def mouseReleaseEvent(self, e) -> None:
        if e.button() == Qt.MouseButton.LeftButton:
            self.on_pick(self.kind)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        paint_surface(p, r, S(14), 0.05, self._hover.level, edge=QColor("#4FA8FF") if self.picked else None,
                      tint=QColor("#2E8BFF") if self.picked else None, tint_a=0.18 if self.picked else 0.0)
        cam = _AeBannerCam(S(1) * 0.42, r.center().x(), r.top() + S(40))
        c = self._car
        c.x = c.y = 0.0
        c.fx, c.fy = 1.0, 0.0
        AerialPainter().car(p, cam, c, self.kind, 0, False, 0.0)
        k = cam.k
        p.setPen(QPen(alpha("#35E0A1", 0.55), 1, Qt.PenStyle.DashLine))
        p.setBrush(Qt.BrushStyle.NoBrush)
        L, H = (c.hl + c.r) * k, c.r * k
        p.drawRoundedRect(QRectF(r.center().x() - L, r.top() + S(40) - H, 2 * L, 2 * H), H, H)
        car = AERIAL_CARS[self.kind]
        p.setFont(font(13, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(QRectF(r.left(), r.top() + S(70), r.width(), S(20)), int(Qt.AlignmentFlag.AlignCenter), car["name"])
        p.setFont(font(9.5, QFont.Weight.DemiBold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(r.left() + S(6), r.top() + S(90), r.width() - S(12), S(22)),
                   int(Qt.AlignmentFlag.AlignCenter | Qt.TextFlag.TextWordWrap), tr(car["line"]))


class AerialBotTile(QWidget):
    """A bot in Practice: its rank colour and emblem, its name, MMR and what kind of player it is."""

    def __init__(self, key: str, on_click, width: int, state: str = "open") -> None:
        super().__init__()
        self.key, self.on_click = key, on_click
        self.state = state                     # "open", "next" (your next challenge: it glows), "locked"
        self.b = AERIAL_BOTS[key]
        self.setFixedSize(width, S(58))
        self.setCursor(Qt.CursorShape.PointingHandCursor if state != "locked" else Qt.CursorShape.ForbiddenCursor)
        self._hover = Tween(self, on_change=self.update)
        self._t0 = time.monotonic()
        if state == "next":
            self._timer = QTimer(self)
            self._timer.setInterval(33)
            self._timer.timeout.connect(self.update)
            self._timer.start()

    def enterEvent(self, _e) -> None:
        self._hover.to(1.0, 140)

    def leaveEvent(self, _e) -> None:
        self._hover.to(0.0, 220)

    def mouseReleaseEvent(self, e) -> None:
        if e.button() == Qt.MouseButton.LeftButton:
            sfx.play("off" if self.state == "locked" else "pick")
            self.on_click(self.key)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        b = self.b
        info = aerial_rank(b["mmr"])
        col = QColor(info["colour"])
        if self.state == "next":
            # the next challenge: a slow breathing glow in the rank's colour and a light running round the edge
            t = time.monotonic() - self._t0
            k = 0.5 + 0.5 * math.sin(t * 2.6)
            for i in range(3):
                p.setPen(QPen(alpha(col, (0.10 + 0.22 * k) / (i + 1)), S(2 + 3 * i)))
                p.setBrush(Qt.BrushStyle.NoBrush)
                p.drawRoundedRect(r.adjusted(S(1), S(1), -S(1), -S(1)), S(12), S(12))
        if self.state == "locked":
            p.setOpacity(0.38)
        paint_surface(p, r, S(12), 0.04, self._hover.level, tint=col, tint_a=0.18 if self.state == "next" else 0.10)
        if self.state == "next":
            t = time.monotonic() - self._t0
            path = QPainterPath()
            path.addRoundedRect(r.adjusted(S(1), S(1), -S(1), -S(1)), S(12), S(12))
            pos = path.pointAtPercent((t * 0.22) % 1.0)
            g = QRadialGradient(pos, S(26))
            g.setColorAt(0, alpha("#FFFFFF", 0.55))
            g.setColorAt(0.4, alpha(col, 0.35))
            g.setColorAt(1, alpha(col, 0.0))
            p.save()
            p.setClipPath(path)
            p.setPen(QPen(QBrush(g), S(2.5)))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawPath(path)
            p.restore()
            p.setPen(QPen(alpha(col, 0.9), S(1.4)))
            p.drawPath(path)
        aerial_draw_emblem(p, QRectF(r.left() + S(6), r.top() + S(7), S(44), S(44)), info["rank"], info["tier"],
                           0, time.monotonic(), glow=False)
        p.setFont(font(12.5, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(QRectF(r.left() + S(58), r.top() + S(8), r.width(), S(20)), int(Qt.AlignmentFlag.AlignLeft), b["name"])
        p.setFont(font(10, QFont.Weight.Bold))
        p.setPen(QColor(info["colour"]))
        p.drawText(QRectF(r.left() + S(58), r.top() + S(8), r.width() - S(66), S(20)),
                   int(Qt.AlignmentFlag.AlignRight), aerial_rank_label(info["index"]))
        p.setFont(font(9.5))
        p.setPen(QColor(TEXT_DIM))
        sub = tr(b["about"])
        if self.state == "locked":
            sub = tr("Locked: reach {r} first", r=aerial_rank_label(max(0, aerial_bot_index(self.key) - 1)))
        elif self.state == "next":
            p.setPen(QColor(col).lighter(130))
            sub = tr("Your next challenge")
        p.drawText(QRectF(r.left() + S(58), r.top() + S(30), r.width() - S(64), S(20)), int(Qt.AlignmentFlag.AlignLeft),
                   QFontMetrics(p.font()).elidedText(sub, Qt.TextElideMode.ElideRight, int(r.width() - S(64))))
        if self.state == "locked":
            p.setOpacity(1.0)
            lk = QRectF(r.right() - S(26), r.bottom() - S(24), S(16), S(16))
            p.setPen(QPen(alpha("#FFFFFF", 0.7), S(1.6)))
            p.setBrush(Qt.BrushStyle.NoBrush)
            p.drawRoundedRect(lk.adjusted(S(2), S(6), -S(2), 0), S(2), S(2))
            p.drawArc(lk.adjusted(S(4.5), 0, -S(4.5), -S(7)), 0, 180 * 16)


class AerialRankCard(QWidget):
    """My rank, as in Rocket League: the emblem, the rank in big letters, the MMR in its own box on the side, and the
    bar of 5 wins up and 5 losses down."""

    def __init__(self, ladder: AerialLadder, width: int) -> None:
        super().__init__()
        self.L = ladder
        self.info = aerial_rank(ladder.mmr)
        self.setFixedSize(width, S(118))
        self._t = QTimer(self)
        self._t.setInterval(60)
        self._t.timeout.connect(self.update)

    def showEvent(self, _e) -> None:
        if self.info["rank"] == 3:
            self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        i = self.info
        col = QColor(i["colour"])
        paint_surface(p, r, S(16), 0.05, tint=col, tint_a=0.16)
        aerial_draw_emblem(p, QRectF(r.left() + S(10), r.top() + S(10), S(96), S(96)), i["rank"], i["tier"], 0,
                           time.monotonic())
        x = r.left() + S(118)
        box = QRectF(r.right() - S(104), r.top() + S(14), S(90), S(48))
        p.setPen(QPen(alpha(col, 0.6), 1.2))
        p.setBrush(alpha("#000000", 0.35))
        p.drawRoundedRect(box, S(12), S(12))
        p.setFont(font(19, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(box.adjusted(0, S(2), 0, -S(14)), int(Qt.AlignmentFlag.AlignCenter), str(i["mmr"]))
        p.setFont(font(8.5, QFont.Weight.Black, 2))
        p.setPen(col)
        p.drawText(box.adjusted(0, S(28), 0, 0), int(Qt.AlignmentFlag.AlignCenter), "MMR")
        p.setFont(font(22, QFont.Weight.Black, 1.5))
        p.setPen(col)
        p.drawText(QRectF(x, r.top() + S(12), box.left() - x - S(8), S(32)), int(Qt.AlignmentFlag.AlignLeft),
                   aerial_rank_label(i["index"]).upper())
        p.setFont(font(10.5, QFont.Weight.DemiBold))
        p.setPen(QColor("#FFFFFF"))
        bot = AERIAL_BOTS[AERIAL_BOT_ROSTER[i["index"]][0]]["name"]
        p.drawText(QRectF(x, r.top() + S(46), box.left() - x, S(18)), int(Qt.AlignmentFlag.AlignLeft),
                   tr("Your ranked opponent: {b}", b=bot))
        aerial_draw_progress(p, QRectF(x, r.top() + S(72), r.right() - x - S(16), S(12)), i["v"], i["colour"])
        p.setFont(font(10, QFont.Weight.DemiBold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(x, r.top() + S(90), r.right() - x - S(16), S(18)), int(Qt.AlignmentFlag.AlignLeft),
                   aerial_progress_text(i))


class AerialMMRChart(QWidget):
    """MMR over the last ranked matches."""

    def __init__(self, points: list, width: int) -> None:
        super().__init__()
        self.pts = points
        self.setFixedSize(width, S(130))
        self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        paint_surface(p, r, S(14), 0.04)
        pts = self.pts
        if len(pts) < 2:
            p.setFont(font(11, QFont.Weight.DemiBold))
            p.setPen(QColor(TEXT_DIM))
            p.drawText(r, int(Qt.AlignmentFlag.AlignCenter), tr("Play ranked to see your MMR over time"))
            return
        lo, hi = min(pts), max(pts)
        if hi - lo < 40:
            lo, hi = lo - 20, hi + 20
        a = r.adjusted(S(40), S(14), -S(12), -S(16))
        for v in (lo, hi):
            y = a.bottom() - (v - lo) / (hi - lo) * a.height()
            p.setPen(QPen(alpha("#FFFFFF", 0.08), 1))
            p.drawLine(QPointF(a.left(), y), QPointF(a.right(), y))
            p.setFont(font(9))
            p.setPen(QColor(TEXT_DIM))
            p.drawText(QRectF(r.left() + S(4), y - S(8), S(34), S(16)), int(Qt.AlignmentFlag.AlignRight), str(int(v)))
        path = QPainterPath()
        for k, v in enumerate(pts):
            q = QPointF(a.left() + a.width() * k / (len(pts) - 1), a.bottom() - (v - lo) / (hi - lo) * a.height())
            path.moveTo(q) if k == 0 else path.lineTo(q)
        col = QColor(aerial_rank(pts[-1])["colour"])
        p.setPen(QPen(col, S(2.2)))
        p.setBrush(Qt.BrushStyle.NoBrush)
        p.drawPath(path)


class AerialHistoryRow(QWidget):
    """One match in the tracker: win or loss, score, who, when, points, MMR change; watch and save its replay."""

    def __init__(self, ctx, row: dict, width: int) -> None:
        super().__init__()
        self.ctx, self.row = ctx, row
        self.setFixedSize(width, S(50))
        lay = hbox(self, 6, (S(width - 190), S(10), S(8), S(10)))
        lay.addStretch(1)
        if row.get("replay"):
            w = Button(tr("Watch"), "ghost", 30)
            w.setFixedWidth(S(80))
            w.clicked.connect(self._watch)
            lay.addWidget(w)
            sv = Button(tr("Save"), "ghost", 30)
            sv.setFixedWidth(S(70))
            sv.clicked.connect(self._save)
            lay.addWidget(sv)

    def _watch(self) -> None:
        st = aerial_store(self.ctx)
        try:
            with open(st.replay_path(self.row["replay"]), "rb") as f:
                rep = aerial_unpack_replay(f.read())
        except (OSError, ValueError):
            return self.ctx.toast(tr("That replay is gone"), "warn")
        if int(rep.get("v", 1) or 1) < AERIAL_REPLAY_V:
            return self.ctx.toast(tr("This replay is from the old side-view Rubenium League and cannot be played"), "warn")
        if str(rep.get("build")) != str(BUILD):
            self.ctx.toast(tr("This replay was made by another version: it may play differently"), "warn")
        AerialStage.start(self.ctx, {"mode": "replay", "replay_data": rep, "bot": rep.get("bot")})

    def _save(self) -> None:
        import shutil
        from PyQt6.QtWidgets import QFileDialog
        st = aerial_store(self.ctx)
        src = st.replay_path(self.row["replay"])
        dest, _f = QFileDialog.getSaveFileName(self, tr("Save replay"), str(DOCS / self.row["replay"]),
                                               "Rubenium League replay (*.rlreplay)")
        if dest:
            try:
                shutil.copyfile(src, dest)
                self.ctx.toast(tr("Replay saved"), "ok")
            except OSError:
                self.ctx.toast(tr("Could not save the replay"), "error")

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        row = self.row
        won = row.get("won")
        paint_surface(p, r, S(12), 0.035)
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(QColor("#3BE38A") if won else QColor("#FF6B78"))
        p.drawRoundedRect(QRectF(r.left() + S(8), r.top() + S(10), S(6), r.height() - S(20)), S(3), S(3))
        sc = row.get("score") or [0, 0]
        p.setFont(font(14, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(QRectF(r.left() + S(22), r.top(), S(64), r.height()), int(Qt.AlignmentFlag.AlignVCenter),
                   "%d-%d" % (sc[0], sc[1]))
        bot = AERIAL_BOTS.get(row.get("bot") or "", {}).get("name", "?")
        mode = {"ranked": tr("Ranked"), "private": tr("Private match")}.get(row.get("mode"), tr("Practice"))
        p.setFont(font(11.5, QFont.Weight.Bold))
        p.drawText(QRectF(r.left() + S(84), r.top() + S(6), S(260), S(20)), int(Qt.AlignmentFlag.AlignLeft),
                   tr("vs {b}", b=bot) + "  ·  " + mode + ("  ·  OT" if row.get("ot") else ""))
        p.setFont(font(9.5))
        p.setPen(QColor(TEXT_DIM))
        when = datetime.datetime.fromtimestamp(row.get("t", 0)).strftime("%d %b %H:%M")
        d = row.get("delta", 0)
        extra = ("  ·  %+d MMR" % d) if row.get("mode") == "ranked" else ""
        p.drawText(QRectF(r.left() + S(84), r.top() + S(26), S(330), S(18)), int(Qt.AlignmentFlag.AlignLeft),
                   "%s  ·  %d %s  ·  %d %s  ·  %d %s%s" % (when, row.get("pts", 0), tr("pts"), row.get("goals", 0),
                                                           tr("goals"), row.get("saves", 0), tr("saves"), extra))


def aerial_ranked_closed(ctx) -> bool:
    """An admin closed ranked (Admin > Locks, "league_ranked"), or Rubenium is in lockdown. Practice stays open."""
    econ = getattr(ctx, "econ", None)
    try:
        return bool(econ is not None and econ.is_locked("league_ranked"))
    except Exception:  # noqa: BLE001
        return False


def aerial_play_ranked(ctx) -> None:
    if aerial_ranked_closed(ctx):
        return ctx.toast(tr("Ranked is closed for now while we fix something. Practice and Free Play stay open."),
                         "warn")
    AerialStage.start(ctx, {"mode": "ranked", "bot": aerial_pick_ranked(aerial_store(ctx))})


def aerial_admin_ranked(ctx, lock: bool) -> None:
    def go() -> None:
        def back(ok: bool, data) -> None:
            if not ok:
                return ctx.toast(tr("Failed: {e}", e=str(data)), "warn")
            ctx.toast(tr("Ranked closed for everyone") if lock else tr("Ranked open again"))
            try:
                ctx.econ.poll_live()
            except Exception:  # noqa: BLE001
                pass
            QTimer.singleShot(600, lambda: ctx.reload_page("games"))
        ctx.econ.call("rb_admin_feature", {"name": "league_ranked", "lock": lock,
                                           "note": "Rubenium League ranked" if lock else ""}, back)
    ctx.window.confirm(tr("Close Rubenium League ranked for everyone?") if lock else
                       tr("Open Rubenium League ranked again for everyone?"), go,
                       yes=tr("Close ranked") if lock else tr("Open ranked"))


def aerial_admin_hide(ctx, lock: bool) -> None:
    """Admins: hide the whole game for everyone (the "league" lock; Admin > Locks does the same)."""
    def go() -> None:
        def back(ok: bool, data) -> None:
            if not ok:
                return ctx.toast(tr("Failed: {e}", e=str(data)), "warn")
            ctx.toast(tr("Rubenium League hidden for everyone") if lock else tr("Rubenium League shows again"))
            try:
                ctx.econ.poll_live()
            except Exception:  # noqa: BLE001
                pass
            QTimer.singleShot(600, lambda: ctx.reload_page("games"))
        ctx.econ.call("rb_admin_feature", {"name": "league", "lock": lock,
                                           "note": "Rubenium League hidden" if lock else ""}, back)
    ctx.window.confirm(tr("Hide Rubenium League for everyone? Admins still see it.") if lock else
                       tr("Show Rubenium League to everyone again?"), go,
                       yes=tr("Hide it") if lock else tr("Show it"))


def build_aerial(page, lay) -> None:
    """Rubenium League in Play: three tabs (Play, Tracker, Ladder)."""
    ctx = page.ctx
    st = aerial_store(ctx)
    W = page.W
    if getattr(ctx, "aerial_stage", None) is None and st.data.get("open_ranked"):
        lo = st.settle_open()
        if lo:
            ctx.toast(tr("Your last ranked match was not finished: it counts as a loss ({d} MMR)", d=lo["delta"]), "warn")
    top = hbox(spacing=8)
    back = IconButton("back", 32, tip=tr("Back"))
    back.clicked.connect(lambda: page.open_sub(None))
    top.addWidget(back)
    top.addWidget(Label(AERIAL_NAME, 16, bold=True), 1)
    top.addWidget(HelpButton(ctx, "aerial"))
    lay.addLayout(top)
    tab = int(getattr(ctx, "aerial_tab", 0) or 0)
    seg = Segmented([tr("Play"), tr("Tracker"), tr("Ladder")], tab)
    seg.changed.connect(lambda i: (setattr(ctx, "aerial_tab", i), ctx.reload_page("games")))
    lay.addWidget(seg)
    if aerial_is_admin(ctx) and aerial_hidden_for_players(ctx):
        lay.addWidget(LockStrip(tr("Hidden for players: only admins see Rubenium League. Admin tools below turn it "
                                   "back on."), W))
    if tab == 1:
        return _aerial_tracker(page, lay, st, W)
    if tab == 2:
        return _aerial_ladder(page, lay, st, W)
    lay.addWidget(AerialRankCard(st.ladder, W))
    closed = aerial_ranked_closed(ctx)
    go = Button(tr("Ranked is closed for now") if closed else tr("Play ranked"), "primary", 50, icon="play")
    if closed:
        go.fade = 0.55
    go.clicked.connect(lambda: aerial_play_ranked(ctx))
    lay.addWidget(go)
    lay.addWidget(Label(tr("Ranked 1 v 1 is against the bot of your rank."), 10, TEXT_FAINT, wrap_w=W))
    _aerial_private(page, lay, st, W)
    lay.addWidget(heading(tr("Your car")))
    row = hbox(spacing=8)
    cw = (W - S(16)) // 3

    def pick(k: int) -> None:
        st.data["car"] = k
        st.save()
        sfx.play("pick")
        ctx.reload_page("games")
    for k in range(3):
        row.addWidget(AerialCarCard(k, int(st.data.get("car", 0)) == k, pick, cw))
    lay.addLayout(row)
    lay.addWidget(heading(tr("Practice and training")))
    fp = Button(tr("Free Play"), "ghost", 40, icon="play")
    fp.clicked.connect(lambda: AerialStage.start(ctx, {"mode": "free"}))
    lay.addWidget(fp)
    admin = aerial_is_admin(ctx)
    lay.addWidget(Label(tr("Practise against any bot up to one rank above yours: no MMR. The glowing one is your next "
                           "challenge."), 10, TEXT_FAINT, wrap_w=W))
    grid = QGridLayout()
    grid.setSpacing(S(8))
    tw = (W - S(8)) // 2

    def practice(key: str) -> None:
        if not aerial_can_play(ctx, key):
            return ctx.toast(tr("Beat the bots in order: you can play up to one rank above yours"), "warn")
        AerialStage.start(ctx, {"mode": "practice", "bot": key})
    mine = st.ladder.r
    for i, r in enumerate(AERIAL_BOT_ROSTER):
        state = "next" if i == mine + 1 else ("locked" if i > mine + 1 and not admin else "open")
        grid.addWidget(AerialBotTile(r[0], practice, tw, state), i // 2, i % 2)
    lay.addLayout(grid)
    if admin:
        _aerial_admin(page, lay, st, W)
    keys = aerial_keys()
    lay.addWidget(ControlsBar([([keys["up"] + "/" + keys["down"]], tr("Drive / brake and reverse")),
                               ([keys["left"] + "/" + keys["right"]], tr("Steer")),
                               (["Shift", "LMB"], tr("Boost")),
                               (["Ctrl", "RMB"], tr("Powerslide")),
                               (["Space"], tr("Skip a goal replay")),
                               (["Tab"], tr("Scoreboard")), ([tr("Esc")], tr("Menu"))], W))
    lay.addWidget(Label(tr("{a} and {b} both work at the same time, and the arrow keys too. Free Play: infinite boost, "
                           "R puts the ball back, T drops it in front of you.", a="WASD", b="ZQSD"),
                        10, TEXT_FAINT, wrap_w=W))


def _aerial_private(page, lay, st, W) -> None:
    """A private match: you pick the opponent (any bot you can play), its car and the length. No MMR."""
    ctx = page.ctx
    opened = bool(getattr(ctx, "aerial_private_open", False))
    pm = Button(tr("Private match") + ("  ▴" if opened else "  ▾"), "ghost", 40)

    def toggle() -> None:
        ctx.aerial_private_open = not opened
        ctx.reload_page("games")
    pm.clicked.connect(toggle)
    lay.addWidget(pm)
    if not opened:
        return
    keys = [r[0] for r in AERIAL_BOT_ROSTER if aerial_can_play(ctx, r[0])]
    bot = getattr(ctx, "aerial_private_bot", None)
    if bot not in keys:
        bot = AERIAL_BOT_ROSTER[min(st.ladder.r, len(AERIAL_BOT_ROSTER) - 1)][0]
        if bot not in keys:
            bot = keys[0]
    mine = int(st.data.get("car", 0)) % len(AERIAL_CARS)
    car = getattr(ctx, "aerial_private_car", None)
    if car is None or car == mine:
        car = aerial_bot_car(bot, mine)
    lengths = (150.0, 300.0)
    ln = getattr(ctx, "aerial_private_len", 150.0)
    row = hbox(spacing=8)
    bw = (W - S(16)) // 3

    def cyc_bot() -> None:
        ctx.aerial_private_bot = keys[(keys.index(bot) + 1) % len(keys)]
        ctx.aerial_private_car = None
        ctx.reload_page("games")

    def cyc_car() -> None:
        others = [k for k in range(len(AERIAL_CARS)) if k != mine]
        ctx.aerial_private_car = others[(others.index(car) + 1) % len(others)] if car in others else others[0]
        ctx.reload_page("games")

    def cyc_len() -> None:
        ctx.aerial_private_len = lengths[(lengths.index(ln) + 1) % len(lengths)] if ln in lengths else lengths[0]
        ctx.reload_page("games")
    b1 = Button(tr("Opponent: {b}", b=AERIAL_BOTS[bot]["name"]), "ghost", 38)
    b1.setFixedWidth(bw)
    b1.clicked.connect(cyc_bot)
    b2 = Button(tr("Its car: {c}", c=AERIAL_CARS[car]["name"]), "ghost", 38)
    b2.setFixedWidth(bw)
    b2.clicked.connect(cyc_car)
    b3 = Button(tr("Length: {t}", t="%d:%02d" % (int(ln) // 60, int(ln) % 60)), "ghost", 38)
    b3.setFixedWidth(bw)
    b3.clicked.connect(cyc_len)
    for b in (b1, b2, b3):
        row.addWidget(b)
    lay.addLayout(row)
    go = Button(tr("Start the private match"), "primary", 40, icon="play")
    go.clicked.connect(lambda: AerialStage.start(ctx, {"mode": "private", "bot": bot, "bot_car": car, "match_s": ln}))
    lay.addWidget(go)
    lay.addWidget(Label(tr("Your rules, no MMR. Any bot up to one rank above yours."), 10, TEXT_FAINT, wrap_w=W))


def _aerial_admin(page, lay, st, W) -> None:
    """Admins only: every bot unlocked, bot against bot, short test matches, move your own rank, close ranked."""
    ctx = page.ctx
    keys = [r[0] for r in AERIAL_BOT_ROSTER]
    lay.addWidget(heading(tr("Admin tools")))
    lay.addWidget(Label(tr("Only admins see this. Every bot is unlocked for you."), 10, TEXT_FAINT, wrap_w=W))
    a = getattr(ctx, "aerial_admin_a", "apex")
    b = getattr(ctx, "aerial_admin_b", "ruben")
    row = hbox(spacing=8)
    bw = (W - S(16)) // 3

    def cycle(attr: str, cur: str) -> None:
        setattr(ctx, attr, keys[(keys.index(cur) + 1) % len(keys)] if cur in keys else keys[0])
        ctx.reload_page("games")
    ba = Button(tr("Blue: {b}", b=AERIAL_BOTS[a]["name"]), "ghost", 38)
    ba.setFixedWidth(bw)
    ba.clicked.connect(lambda: cycle("aerial_admin_a", a))
    bb = Button(tr("Orange: {b}", b=AERIAL_BOTS[b]["name"]), "ghost", 38)
    bb.setFixedWidth(bw)
    bb.clicked.connect(lambda: cycle("aerial_admin_b", b))
    go = Button(tr("Watch"), "primary", 38, icon="play")
    go.setFixedWidth(bw)
    go.clicked.connect(lambda: AerialStage.start(ctx, {"mode": "watch", "bot0": a, "bot": b}))
    for w in (ba, bb, go):
        row.addWidget(w)
    lay.addLayout(row)
    row2 = hbox(spacing=8)
    t30 = Button(tr("30 s test vs {b}", b=AERIAL_BOTS[b]["name"]), "ghost", 38)
    t30.clicked.connect(lambda: AerialStage.start(ctx, {"mode": "practice", "bot": b, "match_s": 30.0}))
    row2.addWidget(t30)

    def move(d: int) -> None:
        L = st.ladder
        L.r = max(0, min(9, L.r + d))
        L.v = 0
        L.peak = max(L.peak, L.r)
        st.save()
        ctx.toast(tr("Your rank is now {r}", r=aerial_rank_label(L.r)))
        ctx.reload_page("games")
    dn = Button(tr("Rank -1"), "ghost", 38)
    dn.clicked.connect(lambda: move(-1))
    up = Button(tr("Rank +1"), "ghost", 38)
    up.clicked.connect(lambda: move(1))
    row2.addWidget(dn)
    row2.addWidget(up)
    lay.addLayout(row2)
    econ = ctx.econ
    locked = "league_ranked" in ((getattr(econ, "locks", None) or {}).get("locked") or [])
    row3 = hbox(spacing=8)
    ab = Button(tr("Open ranked again for everyone") if locked else tr("Close ranked for everyone"), "ghost", 38)
    ab.clicked.connect(lambda _c=False, lk=not locked: aerial_admin_ranked(ctx, lk))
    row3.addWidget(ab)
    hid = aerial_hidden_for_players(ctx)
    hb = Button(tr("Show Rubenium League again") if hid else tr("Hide Rubenium League for everyone"), "ghost", 38)
    hb.clicked.connect(lambda _c=False, lk=not hid: aerial_admin_hide(ctx, lk))
    row3.addWidget(hb)
    lay.addLayout(row3)


def _aerial_tracker(page, lay, st, W) -> None:
    hist = st.data.get("history", [])
    ranked = [h for h in hist if h.get("mode") == "ranked"]
    n = len(hist)
    wins = sum(1 for h in hist if h.get("won"))
    tot = lambda k: sum(int(h.get(k, 0) or 0) for h in hist)          # noqa: E731
    peak = st.ladder.peak
    grid = QGridLayout()
    grid.setSpacing(S(8))
    items = [(tr("Matches"), str(n)), (tr("Wins"), "%d (%d%%)" % (wins, round(100 * wins / n) if n else 0)),
             (tr("Goals"), str(tot("goals"))), (tr("Saves"), str(tot("saves"))), (tr("Epic saves"), str(tot("epic"))),
             (tr("Pinches"), str(tot("pinches"))), (tr("Flicks"), str(tot("flicks"))),
             (tr("Peak"), aerial_rank_label(peak))]
    cw = (W - S(24)) // 4
    for i, (k, v) in enumerate(items):
        grid.addWidget(_AeStat(k, v, cw), i // 4, i % 4)
    lay.addLayout(grid)
    lay.addWidget(heading(tr("MMR")))
    lay.addWidget(AerialMMRChart([h.get("mmr", 0) for h in reversed(ranked[:60])], W))
    lay.addWidget(help_row(tr("Match history"), tr("Your last 200 matches. The last 10 keep their replay: watch it here or "
                                                   "save the file to keep or share it.")))
    if not hist:
        lay.addWidget(Label(tr("No matches yet."), 11, TEXT_DIM))
    for h in hist[:40]:
        lay.addWidget(AerialHistoryRow(page.ctx, h, W))
    op = Button(tr("Open the replays folder"), "ghost", 34)

    def openf() -> None:
        os.makedirs(st.rep_dir, exist_ok=True)
        QDesktopServices.openUrl(QUrl.fromLocalFile(st.rep_dir))
    op.clicked.connect(openf)
    lay.addWidget(op)


class _AeStat(QWidget):
    def __init__(self, k: str, v: str, w: int) -> None:
        super().__init__()
        self.k, self.v = k, v
        self.setFixedSize(w, S(58))

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        r = QRectF(self.rect()).adjusted(1, 1, -1, -1)
        paint_surface(p, r, S(12), 0.04)
        p.setFont(font(15, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(QRectF(r.left(), r.top() + S(6), r.width(), S(24)), int(Qt.AlignmentFlag.AlignCenter), self.v)
        p.setFont(font(9.5, QFont.Weight.DemiBold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(r.left(), r.top() + S(32), r.width(), S(18)), int(Qt.AlignmentFlag.AlignCenter), self.k)


def _aerial_ladder(page, lay, st, W) -> None:
    lay.addWidget(Label(tr("The climb, from Rookie 1 at the bottom to Rubenite at the top. Each rank has its own bot: "
                           "beat it 5 more times than it beats you to go up, lose 5 more than you win and you drop."),
                        10.5, TEXT_DIM, wrap_w=W))
    lay.addWidget(AerialClimb(st.ladder, W))


class AerialClimb(QWidget):
    """The whole ladder as one tower: 10 ranks, Rookie 1 at the bottom and Rubenite at the top, each family a band in
    its colour with its emblem, each rank's bot beside it, and me on the bar. When it opens, the bar fills from the
    bottom up to me and a light runs up it."""
    STEP = 92

    def __init__(self, ladder: AerialLadder, width: int) -> None:
        super().__init__()
        self.L = ladder
        self.me = aerial_rank(ladder.mmr)
        self.top_pad, self.bot_pad = S(60), S(16)
        self.setFixedSize(width, self.top_pad + self.bot_pad + S(self.STEP) * 10)
        self.t0 = None
        self._t = QTimer(self)
        self._t.setInterval(16)
        self._t.timeout.connect(self._tick)

    def showEvent(self, _e) -> None:
        self.t0 = time.monotonic()
        self._t.start()

    def hideEvent(self, _e) -> None:
        self._t.stop()

    def _tick(self) -> None:
        if getattr(ui, "motion", 1.0) <= 0.01 and self.t0 is not None and time.monotonic() - self.t0 > 0.1:
            self._t.stop()
        self.update()

    def y_of(self, steps: float) -> float:
        return self.height() - self.bot_pad - steps * S(self.STEP)

    def paintEvent(self, _e) -> None:
        p = QPainter(self)
        p.setRenderHint(QPainter.RenderHint.Antialiasing)
        w = self.width()
        now = time.monotonic()
        age = now - (self.t0 or now)
        motion = getattr(ui, "motion", 1.0) > 0.01
        track_x, track_w = S(150), S(16)
        bands = [(0, 0, 3), (1, 3, 6), (2, 6, 9), (3, 9, 10)]       # family, first rank, last rank + 1
        for fam, s0, s1 in bands:
            name, col, _sh = AERIAL_FAMILIES[fam]
            y0, y1 = self.y_of(s1), self.y_of(s0)
            band = QRectF(S(4), y0 + S(2), w - S(8), y1 - y0 - S(4))
            c = QColor(col)
            g = QLinearGradient(band.topLeft(), band.topRight())
            g.setColorAt(0, alpha(c, 0.18))
            g.setColorAt(0.5, alpha(c, 0.06))
            g.setColorAt(1, alpha(c, 0.02))
            p.setPen(QPen(alpha(c, 0.4 if fam == self.me["rank"] else 0.15), 1))
            p.setBrush(QBrush(g))
            p.drawRoundedRect(band, S(16), S(16))
            em = S(70 if fam < 3 else 64)
            cy = (y0 + y1) / 2
            aerial_draw_emblem(p, QRectF(S(16), cy - em / 2 - S(10), em, em), fam, 3 if fam < 3 else 0, 0, now)
            p.setFont(font(12.5, QFont.Weight.Black, 1.5))
            p.setPen(c)
            p.drawText(QRectF(S(4), cy + em / 2 - S(6), S(140), S(18)), int(Qt.AlignmentFlag.AlignCenter),
                       tr(name).upper())
        for i in range(10):                                          # each rank: a line, its name, its bot
            fam, tier = AERIAL_RANKS[i]
            col = QColor(AERIAL_FAMILIES[fam][1])
            yb, ym = self.y_of(i), self.y_of(i + 0.5)
            p.setPen(QPen(alpha("#FFFFFF", 0.16), 1))
            p.drawLine(QPointF(track_x - S(8), yb), QPointF(w - S(14), yb))
            p.setFont(font(11, QFont.Weight.Black))
            p.setPen(QColor("#FFFFFF") if i == self.me["index"] else alpha("#FFFFFF", 0.75))
            p.drawText(QRectF(track_x + track_w + S(14), ym - S(11), S(150), S(22)),
                       int(Qt.AlignmentFlag.AlignLeft | Qt.AlignmentFlag.AlignVCenter), aerial_rank_label(i))
            key, bname = AERIAL_BOT_ROSTER[i][0], AERIAL_BOT_ROSTER[i][1]
            chip = QRectF(w - S(206), ym - S(14), S(190), S(28))
            p.setPen(QPen(alpha(col, 0.7), 1))
            p.setBrush(alpha(col, 0.14))
            p.drawRoundedRect(chip, S(14), S(14))
            p.setFont(font(10, QFont.Weight.Black))
            p.setPen(QColor("#FFFFFF"))
            p.drawText(chip.adjusted(S(12), 0, -S(10), 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft),
                       bname)
            p.setFont(font(8.5, QFont.Weight.DemiBold))
            p.setPen(QColor(TEXT_DIM))
            tag = tr(AERIAL_BOT_TAGS.get(key, ""))
            p.drawText(chip.adjusted(S(12), 0, -S(12), 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                       tag)
        tr_r = QRectF(track_x, self.y_of(10), track_w, self.y_of(0) - self.y_of(10))
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha("#000000", 0.45))
        p.drawRoundedRect(tr_r, track_w / 2, track_w / 2)
        target = self.me["index"] + self.me["frac"]
        k = min(1.0, age / 1.6) if motion else 1.0
        k = 1 - (1 - k) ** 3
        ytop = self.y_of(target * k)
        fr = QRectF(track_x + S(2), ytop, track_w - S(4), self.y_of(0) - ytop)
        g = QLinearGradient(QPointF(0, self.y_of(0)), QPointF(0, self.y_of(10)))
        for fam, s0, _s1 in bands:
            g.setColorAt(min(1.0, s0 / 10.0 + 0.001), QColor(AERIAL_FAMILIES[fam][1]))
        g.setColorAt(1.0, QColor(AERIAL_FAMILIES[3][1]))
        rad = (track_w - S(4)) / 2
        if fr.height() > 0:
            p.setBrush(QBrush(g))
            p.drawRoundedRect(fr, rad, rad)
            if motion:
                ly = self.y_of(0) - ((age * S(300)) % max(1.0, fr.height() + S(80))) + S(40)
                lg = QLinearGradient(QPointF(0, ly - S(40)), QPointF(0, ly + S(40)))
                lg.setColorAt(0, alpha("#FFFFFF", 0.0))
                lg.setColorAt(0.5, alpha("#FFFFFF", 0.55))
                lg.setColorAt(1, alpha("#FFFFFF", 0.0))
                p.save()
                clip = QPainterPath()
                clip.addRoundedRect(fr, rad, rad)
                p.setClipPath(clip)
                p.fillRect(QRectF(fr.left(), ly - S(40), fr.width(), S(80)), QBrush(lg))
                p.restore()
        i = self.me
        mc = QColor(i["colour"])
        pulse = 0.5 + 0.5 * math.sin(age * 3.0) if motion else 1.0
        p.setPen(Qt.PenStyle.NoPen)
        p.setBrush(alpha(mc, 0.25 + 0.2 * pulse))
        p.drawEllipse(QPointF(track_x + track_w / 2, ytop), S(15), S(15))
        p.setBrush(QColor("#FFFFFF"))
        p.drawEllipse(QPointF(track_x + track_w / 2, ytop), S(6), S(6))
        pill = QRectF(track_x + track_w + S(120), ytop - S(15), S(150), S(30))
        p.setPen(QPen(mc, 1.5))
        p.setBrush(QColor(14, 16, 22, 235))
        p.drawRoundedRect(pill, S(15), S(15))
        p.setFont(font(10.5, QFont.Weight.Black))
        p.setPen(QColor("#FFFFFF"))
        p.drawText(pill.adjusted(S(12), 0, -S(12), 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft),
                   tr("YOU"))
        p.setPen(mc)
        p.drawText(pill.adjusted(S(12), 0, -S(12), 0), int(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignRight),
                   "%d MMR" % i["mmr"])
        p.setFont(font(11, QFont.Weight.Black, 3))
        p.setPen(QColor("#FF2E63"))
        p.drawText(QRectF(0, S(8), w, S(20)), int(Qt.AlignmentFlag.AlignCenter), tr("THE SUMMIT"))
        p.setFont(font(9, QFont.Weight.DemiBold))
        p.setPen(QColor(TEXT_DIM))
        p.drawText(QRectF(0, S(28), w, S(18)), int(Qt.AlignmentFlag.AlignCenter),
                   tr("Rubenite. Only Ruben waits here."))


